function RoleCard({ icon, name, desc, badge, onClick, last }) {
  const [hover, setHover] = useState(false);
  return (
    <div
      onClick={onClick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        background: hover ? "rgba(255,255,255,.055)" : "rgba(4,5,10,1)",
        padding:"12px 13px",
        display:"flex",
        alignItems:"center",
        gap:"11px",
        cursor:"pointer",
        transition:"all .15s",
        borderBottom: last ? "none" : "1px solid rgba(255,255,255,.04)",
      }}>
      <div style={{ width:52, height:52, borderRadius:14, background:"rgba(8,12,30,.98)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
        {icon}
      </div>
      <div style={{ flex:1 }}>
        <div style={{ fontSize:15, fontWeight:500, color:"rgba(255,255,255,.9)" }}>{name}</div>
        <div style={{ fontSize:11, color:"rgba(255,255,255,.3)", marginTop:1 }}>{desc}</div>
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:6 }}>
        {badge != null && badge !== 0 && (
          <div style={{
            width:28, height:28, borderRadius:"50%",
            display:"flex", alignItems:"center", justifyContent:"center",
            fontSize:11, fontWeight:600,
            background:"rgba(60,110,255,.18)", color:"#6A9FFF",
            boxShadow:"0 0 8px rgba(60,110,255,.3),inset 0 0 6px rgba(60,110,255,.15)",
          }}>{badge}</div>
        )}
        <span style={{ color:"rgba(255,255,255,.18)", fontSize:14 }}>›</span>
      </div>
    </div>
  );
}

function GroupSection({ label, children }) {
  return (
    <div style={{ marginBottom:22 }}>
      <div style={{ display:"flex", alignItems:"center", gap:8, padding:"0 2px 8px" }}>
        {GroupIcons[label]}
        <span style={{ fontSize:12, fontWeight:800, color:"#4A7FFF", letterSpacing:"2px", textTransform:"uppercase" }}>{label}</span>
        <div style={{ flex:1, height:1, background:"linear-gradient(90deg,rgba(60,110,255,.3),transparent)", marginLeft:4 }}/>
      </div>
      <div style={{ background:"rgba(6,9,20,1)", border:"1px solid rgba(60,110,255,.18)", borderRadius:16, overflow:"hidden", boxShadow:"0 0 24px rgba(60,110,255,.07),0 2px 12px rgba(0,0,0,.4)" }}>
        {children}
      </div>
    </div>
  );
}

// Desktop home tiles (bento) — the featured HeroTile spends the one moment of
// colour; HomeTile is the standard workspace tile; MiniTile the dense secondary
// row. Mobile keeps the hero image + RoleCard list.
function HeroTile({ icon, name, desc, badge, onClick }) {
  return (
    <button className="hm-tile hm-hero" onClick={onClick}>
      <span className="hm-ic">{icon}</span>
      {badge > 0 && <span className="hm-bd">{badge} today</span>}
      <span>
        <span className="hm-nm">{name}</span>
        <span className="hm-ds">{desc}</span>
        <span className="hm-cta">Open workspace →</span>
      </span>
    </button>
  );
}
function HomeTile({ icon, name, desc, badge, onClick }) {
  return (
    <button className="hm-tile" onClick={onClick}>
      <span className="hm-ic">{icon}</span>
      {badge > 0 && <span className="hm-bd">{badge}</span>}
      <span className="hm-nm">{name}</span>
      <span className="hm-ds">{desc}</span>
      <span className="hm-ar">→</span>
    </button>
  );
}
function MiniTile({ icon, name, desc, onClick }) {
  return (
    <button className="hm-mini" onClick={onClick}>
      <span className="hm-mic">{icon}</span>
      <span style={{ minWidth: 0 }}>
        <span className="hm-mnm">{name}</span>
        <span className="hm-mds">{desc}</span>
      </span>
    </button>
  );
}

function RoleSelector({ onSelect, orders, returnsLog, hasPermission, canAccessStock, isSuperAdmin }) {
  const isDesktop = !useIsNarrow(1024);
  const { user: homeUser, permRecord: homePerm, signOut: homeSignOut } = usePermissions();
  const today = getSADateString();
  const incoming = orders ? orders.filter(o => o.status === STATUS.INCOMING).length : 0;
  // Source badge = today's restock requests + on-hold (Tomorrow), excluding OOS.
  // Today's request = orders marked READY/COLLECTED today (sold/sent items),
  // minus any of those orders that have been returned today (physically back
  // in the warehouse, no restock needed). On hold = COMING_TOMORROW.
  const returnedToday = returnedOrderIdsOnSADate(returnsLog, today);
  const sourceTodayCount = orders ? orders.filter(o =>
    o.status !== STATUS.OUT_OF_STOCK &&
    (o.status === STATUS.READY || o.status === STATUS.COLLECTED) &&
    orderSaleDate(o) === today &&
    !returnedToday.has(o.id)
  ).length : 0;
  const onHold = orders ? orders.filter(o =>
    o.status === STATUS.COMING_TOMORROW && o.status !== STATUS.OUT_OF_STOCK
  ).length : 0;
  const sourceBadge = sourceTodayCount + onHold;
  // assistant badge = today's placed orders
  const assistantBadge = orders ? orders.filter(o =>
    o.createdAt && o.createdAt.slice(0,10) === today
  ).length : 0;

  // Display Checks card — behind the master flag + the module's own access gate
  // (super-admin, or a store-scoped display_checks grant). Dark by default. The
  // badge slot is intentionally omitted (wired to nothing yet — a later PR feeds
  // it the store's outstanding count).
  const dcVisible = displayChecksVisibleForViewer(
    { email: homeUser?.email, permissions: homePerm?.permissions, destShop: homePerm?.destShop },
    isSuperAdmin ? null : (homePerm?.destShop || null)
  );

  // Shared, permission-gated role data — rendered as a desktop tile grid or the
  // mobile RoleCard list.
  const groups = [
    { label: "Operations", cards: [
      hasPermission(ROLE_TO_PERMISSION[ROLES.ASSISTANT]) && { key:"assistant", icon:RoleIcons.assistant, name:"Store Assistant", desc:"Place customer orders", badge:assistantBadge, onClick:()=>onSelect(ROLES.ASSISTANT) },
      hasPermission(ROLE_TO_PERMISSION[ROLES.WAREHOUSE]) && { key:"warehouse", icon:RoleIcons.warehouse, name:"Warehouse", desc:"Manage order queue", badge:incoming, onClick:()=>onSelect(ROLES.WAREHOUSE) },
      hasPermission(ROLE_TO_PERMISSION[ROLES.SOURCE])    && { key:"source", icon:RoleIcons.source, name:"Source", desc:"Restock requests", badge:sourceBadge, onClick:()=>onSelect(ROLES.SOURCE) },
      // ── RETURNS TILE REMOVED (2026-07-29, owner) ─────────────────────────
      // Nothing goes back to a hub any more, so there is nothing to log:
      // sneakers were never transferred off their hub, and clothing that reaches
      // the shop stays there as shop stock. A tile called "Log returned items"
      // that can only tell you there is nothing to do is a daily dead end.
      //
      // The MODULE IS NOT DELETED — ReturnsView, submitReturn, the date-scoped
      // disp_ reversal, logReturn and the returns_log feed are all intact, and
      // the route below still resolves. Only the way in from the home screen is
      // gone. Restoring it is this one line.
      { key:"barcodes", icon:RoleIcons.stock, name:"Barcodes", desc:"Print product barcodes", onClick:()=>onSelect(ROLES.BARCODES) },
      { key:"label_print", icon:RoleIcons.stock, name:"Print Labels", desc:"Product labels · name, price, barcode", onClick:()=>onSelect(ROLES.LABEL_PRINT) },
      dcVisible && { key:"display_checks", icon:RoleIcons.display_checks, name:"Display Checks", desc:"Clothing display checks", onClick:()=>onSelect(ROLES.DISPLAY_CHECKS) },
    ].filter(Boolean) },
    { label: "Insights & Display", cards: [
      hasPermission(ROLE_TO_PERMISSION[ROLES.INSIGHTS]) && { key:"insights", icon:RoleIcons.insights, name:"Internal Insights", desc:"Business analytics", onClick:()=>onSelect(ROLES.INSIGHTS) },
      hasPermission(ROLE_TO_PERMISSION[ROLES.DISPLAY])  && { key:"display", icon:RoleIcons.display, name:"TV Display", desc:"Customer queue screen", onClick:()=>onSelect(ROLES.DISPLAY) },
      hasPermission(ROLE_TO_PERMISSION[ROLES.CUSTOMER]) && { key:"customer", icon:RoleIcons.customer, name:"Track Order", desc:"Live order status & timeline", onClick:()=>onSelect(ROLES.CUSTOMER) },
    ].filter(Boolean) },
    { label: "Administration", cards: [
      hasPermission(ROLE_TO_PERMISSION[ROLES.CUSTOMERS_DB])     && { key:"customers", icon:RoleIcons.customers_db, name:"Customers", desc:"Customer database", onClick:()=>onSelect(ROLES.CUSTOMERS_DB) },
      hasPermission(ROLE_TO_PERMISSION[ROLES.ADMIN])            && { key:"admin", icon:RoleIcons.admin, name:"Admin", desc:"Manage products", onClick:()=>onSelect(ROLES.ADMIN) },
      canAccessStock                                           && { key:"stock", icon:RoleIcons.stock, name:"Stock", desc:"Inventory & transfers", onClick:()=>onSelect(ROLES.STOCK) },
      // Inventory Health — the AI refill engine's control centre, promoted to its
      // own primary card (owner decision 2026-07-12). Same access as Stock.
      canAccessStock                                           && { key:"health", icon:RoleIcons.insights, name:"Inventory Health", desc:"Refill engine & exceptions", onClick:()=>onSelect(ROLES.HEALTH) },
      true                                                     && { key:"display_register", icon:RoleIcons.display, name:"Display Register", desc:"What's on the floor, and in what size", onClick:()=>onSelect(ROLES.DISPLAY_REGISTER) },
      hasPermission(ROLE_TO_PERMISSION[ROLES.BROADCAST_GROUPS]) && { key:"broadcast", icon:RoleIcons.broadcast_groups, name:"Group Broadcast", desc:"Send to WhatsApp groups", onClick:()=>onSelect(ROLES.BROADCAST_GROUPS) },
      hasPermission(ROLE_TO_PERMISSION[ROLES.USER_MANAGEMENT]) && { key:"user_mgmt", icon:RoleIcons.user_management, name:"User Management", desc:"Manage staff accounts", onClick:()=>(window.location.hash = "#admin/users") },
      isSuperAdmin && { key:"ai_studio", icon:RoleIcons.ai_studio, name:"AI Studio", desc:"Photos · Names · Reorder · Voice", onClick:()=>onSelect(ROLES.AI_STUDIO) },
    ].filter(Boolean) },
  ];
  const anyCards = groups.some(g => g.cards.length > 0);

  // ── DESKTOP HOME (≥1024px) — a live retail-ops dashboard: greeting, today's
  //    numbers, and a BENTO of workspaces (featured primary + weighted rest).
  //    Mobile keeps the hero image + RoleCard list. ──
  if (isDesktop) {
    const hr = new Date().getHours();
    const greet = hr < 12 ? "Good morning" : hr < 18 ? "Good afternoon" : "Good evening";
    const name = homePerm?.displayName || homePerm?.username || homeUser?.email?.split("@")[0] || "there";
    const dateStr = new Date().toLocaleDateString("en-ZA", { weekday: "long", day: "numeric", month: "long" });
    const ops = groups[0].cards;                                   // Operations
    const featured = ops.find(c => c.key === "assistant") || ops[0] || null;
    const opsRest = ops.filter(c => c !== featured);
    const others = groups.slice(1).filter(g => g.cards.length > 0); // Insights, Admin
    const stats = [
      { k: "Orders today", v: assistantBadge, role: ROLES.WAREHOUSE },
      { k: "In queue", v: incoming, role: ROLES.WAREHOUSE },
      { k: "To restock", v: sourceBadge, warn: sourceBadge > 0, role: ROLES.SOURCE },
      // "Returns" stat removed with the tile — it linked into the same module and
      // would have been the one remaining door to a screen with nothing to do.
    ];
    return (
      <div style={{ minHeight:"100vh", background:"#000", color:"#f3f6ff", fontFamily:FONT, position:"relative" }}>
        <div style={{ position:"absolute", inset:0, pointerEvents:"none", background:"radial-gradient(1200px 560px at 84% -12%, rgba(60,110,255,.12), transparent 58%), radial-gradient(900px 520px at 4% 0%, rgba(127,90,240,.09), transparent 52%)" }} />
        <style>{`
          @keyframes hmRise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
          .hm-r{opacity:0;animation:hmRise .55s cubic-bezier(.2,.7,.2,1) forwards}
          .hm-stat{position:relative;width:100%;text-align:left;font-family:inherit;color:#f3f6ff;background:rgba(255,255,255,.022);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:14px 15px}
          .hm-stat.clk{cursor:pointer;transition:transform .18s cubic-bezier(.2,.7,.2,1),border-color .18s,box-shadow .18s}
          .hm-stat.clk:hover,.hm-stat.clk:focus-visible{transform:translateY(-3px);border-color:rgba(74,127,255,.5);box-shadow:0 14px 30px -20px rgba(60,110,255,.55);outline:none}
          .hm-sgo{position:absolute;top:13px;right:14px;color:#4A7FFF;font-size:13px;opacity:0;transform:translateX(-3px);transition:.18s}
          .hm-stat.clk:hover .hm-sgo,.hm-stat.clk:focus-visible .hm-sgo{opacity:1;transform:none}
          .hm-tile{position:relative;display:flex;flex-direction:column;justify-content:flex-end;gap:5px;width:100%;text-align:left;cursor:pointer;font-family:inherit;color:#f3f6ff;
            background:linear-gradient(180deg,rgba(255,255,255,.02),transparent 60%),rgba(255,255,255,.022);border:1px solid rgba(255,255,255,.08);border-radius:18px;padding:16px;overflow:hidden;
            transition:transform .22s cubic-bezier(.2,.7,.2,1),border-color .22s,box-shadow .22s}
          .hm-tile:hover,.hm-tile:focus-visible{transform:translateY(-5px);border-color:rgba(74,127,255,.5);box-shadow:0 20px 46px -22px rgba(60,110,255,.6);outline:none}
          .hm-ic{position:absolute;top:15px;left:15px;width:40px;height:40px;border-radius:12px;display:grid;place-items:center;color:#9DBCFF;background:rgba(74,127,255,.12);border:1px solid rgba(74,127,255,.28)}
          .hm-ic svg{width:20px;height:20px}
          .hm-nm{font-size:15px;font-weight:750;letter-spacing:-.01em;color:#fff}
          .hm-ds{display:block;font-size:11.5px;color:rgba(233,238,255,.5)}
          .hm-bd{position:absolute;top:16px;right:15px;font-size:12px;font-weight:800;color:#9DBCFF;background:rgba(74,127,255,.2);border-radius:999px;padding:2px 10px;font-variant-numeric:tabular-nums}
          .hm-ar{position:absolute;bottom:15px;right:16px;color:#4A7FFF;font-size:15px;opacity:0;transform:translateX(-4px);transition:.2s}
          .hm-tile:hover .hm-ar,.hm-tile:focus-visible .hm-ar{opacity:1;transform:none}
          .hm-hero{grid-column:span 2;grid-row:span 2;justify-content:space-between;padding:22px;
            background:radial-gradient(120% 120% at 100% 0,rgba(127,90,240,.22),transparent 55%),linear-gradient(160deg,rgba(74,127,255,.14),rgba(10,12,22,.4));border-color:rgba(122,110,255,.4)}
          .hm-hero .hm-ic{position:static;width:52px;height:52px;border-radius:15px;background:linear-gradient(135deg,#6e7bff,#7f5af0);color:#fff;border:0;box-shadow:0 10px 26px -8px rgba(127,90,240,.7)}
          .hm-hero .hm-ic svg{width:26px;height:26px}
          .hm-hero .hm-nm{font-size:23px;font-weight:800;letter-spacing:-.02em}
          .hm-hero .hm-ds{font-size:13px;margin-top:2px}
          .hm-hero .hm-bd{top:22px;right:20px;background:rgba(255,255,255,.14);color:#fff}
          .hm-cta{display:inline-flex;align-items:center;margin-top:13px;font-size:12.5px;font-weight:800;color:#fff;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);border-radius:10px;padding:8px 13px}
          .hm-mini{position:relative;display:flex;align-items:center;gap:12px;width:100%;text-align:left;cursor:pointer;font-family:inherit;color:#f3f6ff;
            background:rgba(255,255,255,.022);border:1px solid rgba(255,255,255,.08);border-radius:15px;padding:13px 14px;transition:transform .2s,border-color .2s,box-shadow .2s}
          .hm-mini:hover,.hm-mini:focus-visible{transform:translateY(-3px);border-color:rgba(74,127,255,.45);box-shadow:0 14px 32px -20px rgba(60,110,255,.55);outline:none}
          .hm-mic{width:38px;height:38px;flex:0 0 auto;border-radius:11px;display:grid;place-items:center;color:#9DBCFF;background:rgba(74,127,255,.1);border:1px solid rgba(74,127,255,.24)}
          .hm-mic svg{width:18px;height:18px}
          .hm-mnm{display:block;font-size:13.5px;font-weight:700;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
          .hm-mds{display:block;font-size:11px;color:rgba(233,238,255,.5);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
          @media(prefers-reduced-motion:reduce){.hm-r{animation:none;opacity:1}.hm-tile,.hm-mini,.hm-ar,.hm-stat{transition:none}}
        `}</style>
        <div style={{ position:"relative", maxWidth:1100, margin:"0 auto", padding:"28px 30px 72px" }}>
          {/* Top bar */}
          <div className="hm-r" style={{ display:"flex", alignItems:"center", gap:14, marginBottom:38, animationDelay:".02s" }}>
            <span style={{ fontSize:20, fontWeight:800, fontStyle:"italic", letterSpacing:-.6 }}>marathon</span>
            <span style={{ fontSize:10, fontWeight:700, letterSpacing:5, color:"#4A7FFF" }}>CLUB</span>
            <div style={{ flex:1 }} />
            <span style={{ fontSize:12.5, color:"rgba(233,238,255,.5)" }}>{dateStr}</span>
            <div style={{ display:"flex", alignItems:"center", gap:9, padding:"6px 8px 6px 6px", border:"1px solid rgba(255,255,255,.08)", borderRadius:999, background:"rgba(255,255,255,.022)" }}>
              <span style={{ width:26, height:26, borderRadius:"50%", background:"rgba(74,127,255,.2)", border:"1px solid rgba(74,127,255,.5)", color:"#9DBCFF", fontSize:11, fontWeight:800, display:"grid", placeItems:"center" }}>{(name[0] || "?").toUpperCase()}</span>
              <span style={{ fontSize:12, fontWeight:700 }}>{name}</span>
              <button onClick={homeSignOut} title="Sign out" aria-label="Sign out" style={{ border:0, background:"transparent", color:"rgba(233,238,255,.4)", cursor:"pointer", display:"grid", placeItems:"center", padding:2 }}>
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/></svg>
              </button>
            </div>
          </div>

          {/* Greeting */}
          <div className="hm-r" style={{ animationDelay:".08s" }}>
            <div style={{ fontSize:"clamp(26px,3.4vw,38px)", fontWeight:800, letterSpacing:"-.02em", lineHeight:1.05, textWrap:"balance" }}>
              {greet}, <span style={{ background:"linear-gradient(90deg,#6e7bff,#8a6dff,#7f5af0)", WebkitBackgroundClip:"text", backgroundClip:"text", WebkitTextFillColor:"transparent" }}>{name}</span>.
            </div>
            <div style={{ fontSize:13.5, color:"rgba(233,238,255,.5)", marginTop:9 }}>Here's what's moving at Marathon today.</div>
          </div>

          {/* Today's numbers — each jumps to its queue when you have access. */}
          <div className="hm-r" style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:12, margin:"22px 0 34px", animationDelay:".14s" }}>
            {stats.map(s => {
              const can = hasPermission(ROLE_TO_PERMISSION[s.role]);
              const El = can ? "button" : "div";
              return (
                <El key={s.k} className={"hm-stat" + (can ? " clk" : "")} onClick={can ? () => onSelect(s.role) : undefined}>
                  {can && <span className="hm-sgo">→</span>}
                  <div style={{ fontSize:10.5, letterSpacing:".14em", textTransform:"uppercase", color:"rgba(233,238,255,.3)", fontWeight:700 }}>{s.k}</div>
                  <div style={{ fontSize:28, fontWeight:800, letterSpacing:"-.02em", fontVariantNumeric:"tabular-nums", marginTop:6, color: s.warn ? "#F5A623" : "#fff" }}>{s.v}</div>
                </El>
              );
            })}
          </div>

          {!anyCards ? (
            <div style={{ textAlign:"center", color:"#555", padding:"4rem 1rem", fontSize:14 }}>
              No tools assigned to your account yet. Ask an admin to update your permissions.
            </div>
          ) : (
            <>
              <div className="hm-r" style={{ fontSize:11, letterSpacing:".22em", textTransform:"uppercase", color:"rgba(233,238,255,.3)", fontWeight:700, margin:"0 2px 14px", animationDelay:".2s" }}>Workspaces</div>
              <div className="hm-r" style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gridAutoRows:118, gridAutoFlow:"dense", gap:13, marginBottom:34, animationDelay:".24s" }}>
                {featured && <HeroTile icon={featured.icon} name={featured.name} desc={featured.desc} badge={featured.badge} onClick={featured.onClick} />}
                {opsRest.map(c => <HomeTile key={c.key} icon={c.icon} name={c.name} desc={c.desc} badge={c.badge} onClick={c.onClick} />)}
              </div>

              {others.map((g, gi) => (
                <div key={g.label} className="hm-r" style={{ animationDelay: `${.3 + gi * .06}s` }}>
                  <div style={{ fontSize:11, letterSpacing:".22em", textTransform:"uppercase", color:"rgba(233,238,255,.3)", fontWeight:700, margin:"0 2px 14px" }}>{g.label}</div>
                  <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(224px, 1fr))", gap:12, marginBottom:30 }}>
                    {g.cards.map(c => <MiniTile key={c.key} icon={c.icon} name={c.name} desc={c.desc} onClick={c.onClick} />)}
                  </div>
                </div>
              ))}
            </>
          )}
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight:"100vh", background:"#000", fontFamily:FONT, maxWidth:430, margin:"0 auto", overflowX:"hidden" }}>
      {/* MARATHON HERO */}
      <div style={{ position:"relative", height:260, overflow:"hidden" }}>
        <img src="/hero/marathon.jpg" alt="Marathon" style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%", objectFit:"contain", objectPosition:"center", zIndex:0 }}/>
        <div style={{ position:"absolute", bottom:0, left:0, right:0, height:100, background:"linear-gradient(transparent,#000)", zIndex:1 }}/>
        <div style={{ position:"absolute", top:0, left:0, right:0, display:"flex", alignItems:"center", justifyContent:"space-between", padding:"50px 16px 0", zIndex:5 }}>
          <button style={{ width:34, height:34, borderRadius:"50%", background:"rgba(0,0,0,.5)", backdropFilter:"blur(10px)", border:"none", display:"flex", alignItems:"center", justifyContent:"center", cursor:"pointer" }}>
            <svg width="14" height="14" viewBox="0 0 24 24" stroke="rgba(255,255,255,.65)" fill="none" strokeWidth="2" strokeLinecap="round"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
          </button>
          <div style={{ display:"flex", gap:7 }}>
            <button style={{ width:34, height:34, borderRadius:"50%", background:"rgba(0,0,0,.5)", backdropFilter:"blur(10px)", border:"none", display:"flex", alignItems:"center", justifyContent:"center", cursor:"pointer" }}>
              <svg width="14" height="14" viewBox="0 0 24 24" stroke="rgba(255,255,255,.65)" fill="none" strokeWidth="2" strokeLinecap="round"><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/><circle cx="5" cy="12" r="1"/></svg>
            </button>
            <button style={{ width:34, height:34, borderRadius:"50%", background:"rgba(0,0,0,.5)", backdropFilter:"blur(10px)", border:"none", display:"flex", alignItems:"center", justifyContent:"center", cursor:"pointer" }}>
              <svg width="14" height="14" viewBox="0 0 24 24" stroke="rgba(255,255,255,.65)" fill="none" strokeWidth="2" strokeLinecap="round"><path d="M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9M13.73 21a2 2 0 01-3.46 0"/></svg>
            </button>
          </div>
        </div>
      </div>

      {/* ROLE GROUPS — each tile gated by hasPermission (shared `groups` data).
          Empty groups are hidden so staff with limited permissions don't see
          empty headings. Inventory Health lives in the Administration group above. */}
      <div style={{ padding:"10px 14px 36px", background:"#000" }}>
        {anyCards ? groups.filter(g => g.cards.length > 0).map(g => (
          <GroupSection key={g.label} label={g.label}>
            {g.cards.map((c, i) => (
              <RoleCard key={c.key} icon={c.icon} name={c.name} desc={c.desc} badge={c.badge} onClick={c.onClick} last={i === g.cards.length - 1} />
            ))}
          </GroupSection>
        )) : (
          <div style={{ textAlign:"center", color:"#555", padding:"3rem 1rem", fontSize:14 }}>
            No tools assigned to your account yet. Ask an admin to update your permissions.
          </div>
        )}
      </div>
    </div>
  );
}

// ─── ADMIN VIEW ───────────────────────────────────────────────────────────────
// Sneaker size options (clothing uses CLOTHING_SIZES). Hoisted to module
// scope so both AdminView's Add Product form and AdminProductDetail's size
// editor share the same source of truth.
const SNEAKER_SIZES = ["3","4","5","5.5","6","7","8","9","10","11"];

// `#product/{id}` is the detail-page route. Returns null when the hash is
// anything else (empty, #admin, etc.).
function parseProductHash() {
  const m = (window.location.hash || "").match(/^#product\/(.+)$/);
  return m ? m[1] : null;
}

// ─── AI NAME CLEANUP — REVIEW & APPROVE ───────────────────────────────────────
// Live view of /aiAssistant/nameProposals (written by the cleanProductNames Cloud
// Function — a vision + typed-name merge). The catalogue name changes ONLY when an
// admin approves a row here; nothing auto-applies. Approve writes the (optionally
// edited) suggested name to /products/{id}.name and marks the proposal approved;
// Reject marks it rejected; both decisions stop the row reappearing on a re-run.
function useNameProposals() {
  const [proposals, setProposals] = useState({});
  useEffect(() => {
    const unsub = onValue(ref(database, "aiAssistant/nameProposals"), snap => setProposals(snap.val() || {}));
    return () => unsub();
  }, []);
  return proposals;
}

// ─── AI PHOTO CLEANUP — REVIEW & APPROVE ──────────────────────────────────────
// Side-by-side original vs AI white-background re-shoot (written by the
// generateProductPhotos function to /aiAssistant/photoProposals). Approve swaps the
// product's photoUrl to the white-bg version but KEEPS the original (stored in
// photoUrlOriginal; the original file at products/{id}/photo.jpg is never touched).
// Reject discards. Nothing auto-applies.
function usePhotoProposals() {
  const [proposals, setProposals] = useState({});
  useEffect(() => {
    const unsub = onValue(ref(database, "aiAssistant/photoProposals"), snap => setProposals(snap.val() || {}));
    return () => unsub();
  }, []);
  return proposals;
}

// " · gemini $0.0390, openai $0.0461" from the function's per-engine cost split.
function costByEngineStr(cbe) {
  if (!cbe || typeof cbe !== "object") return "";
  const parts = Object.entries(cbe).filter(([, v]) => Number(v) > 0).map(([k, v]) => `${k} $${Number(v).toFixed(4)}`);
  return parts.length ? ` · ${parts.join(", ")}` : "";
}

// Aggregate generateProductPhotos per-product failure reasons into a short "why"
// suffix so a failed run isn't silent (e.g. " — why: AI credits depleted… ×11;
// No sneaker Style Kit references… ×1"). Empty when the run had no failures or an
// older function build returned no `failures` array.
function photoFailureSuffix(failures) {
  if (!Array.isArray(failures) || !failures.length) return "";
  const byReason = new Map();
  for (const f of failures) {
    const r = (f && f.reason) || "failed";
    byReason.set(r, (byReason.get(r) || 0) + 1);
  }
  const parts = [...byReason.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([r, n]) => `${r} ×${n}`);
  return ` — why: ${parts.join("; ")}`;
}

// One-tap fix shortcuts for a regenerate: a short label the user taps → a clear,
// expanded instruction the image engine understands, appended to the run note. Tap
// several to combine; free text can be added too. Keeps "make gemini understand
// what to fix" to one tap instead of writing a prompt each time.
const FIX_PRESETS = [
  ["Wrong shape",   "the shape and silhouette look wrong — correct it to the authentic product's true shape and proportions"],
  ["Wrong side",    "the wrong side is showing — show the OUTER branded display side, do not flip to the plain inner side"],
  ["Colour off",    "the colours are off or washed out — restore the product's true, accurate, full-strength colours exactly"],
  ["Blacks weak",   "the dark areas look weak and greyish — make black, charcoal and navy richer and deeper so they stand out"],
  ["Blurry",        "it looks blurry or soft — make it tack-sharp with crisp clean edges and fine detail throughout"],
  ["Design detail", "minor design details are wrong — fix the logos, patterns, stitching and text to match the authentic product exactly"],
  ["Framing",       "framing is off — centre the product straight and level with an even margin, fully visible and not cut off"],
  ["Remove bg",     "remove every trace of the original background and props — show only the single product on flat pure white"],
];

// ─── "RECENT" PICKER CATEGORY ─────────────────────────────────────────────────
// Newest photo uploads across ALL categories. Upload time = photoUpdatedAt
// (stamped on every admin photo upload/replace since 2026-07); fallback is the
// creation time encoded in the product id ("p" + serverNowMs() — every product id
// in the DB conforms), so legacy products sort correctly too. AI-studio
// approvals deliberately do NOT stamp photoUpdatedAt: an approved re-shoot
// isn't a new upload.
const RECENT_DAYS = 14; // ~20 uploads/day currently → a fortnight is plenty of lookback…
const RECENT_CAP  = 100; // …but render only the newest 100 (thumbnails are lazy-loaded, so a bigger grid than PICK_RENDER_CAP stays cheap)
const uploadTs = (p) => {
  if (typeof p?.photoUpdatedAt === "number" && p.photoUpdatedAt > 0) return p.photoUpdatedAt;
  const n = Number(String(p?.id || "").slice(1));
  return Number.isFinite(n) && n > 0 ? n : 0;
};
// SA-time (UTC+2, no DST) day bucket → header label "Today" / "Yesterday" / "3 Jul".
const saDay = (ms) => new Date(ms + 2 * 60 * 60 * 1000).toISOString().slice(0, 10);
const RECENT_MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const recentDayLabel = (day) => {
  if (day === saDay(serverNowMs())) return "Today";
  if (day === saDay(serverNowMs() - 864e5)) return "Yesterday";
  return `${Number(day.slice(8, 10))} ${RECENT_MONTHS[Number(day.slice(5, 7)) - 1]}`;
};

// Keyframes for the Recent-grid shimmer. A module-level element keeps its
// identity across re-renders, so React never remounts the <style> tag.
const RECENT_SHIMMER_STYLE = (
  <style>{`@keyframes recentShimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }`}</style>
);

// One card in the Recent grid: square photo, name strip, green selection ring
// (same selected-green as the list rows). Shimmer placeholder + fade-in so the
// grid doesn't pop as thumbnails arrive.
function RecentPickCard({ p, selected, onToggle }) {
  const [loaded, setLoaded] = useState(false);
  return (
    <div onClick={onToggle} title={p.name}
         style={{ position:"relative", borderRadius:12, overflow:"hidden", cursor:"pointer",
                  background:"rgba(255,255,255,.04)",
                  border:"1px solid " + (selected ? "rgba(74,202,122,.65)" : "rgba(255,255,255,.08)"),
                  boxShadow: selected ? "0 0 0 1px rgba(74,202,122,.65), 0 4px 18px rgba(74,202,122,.14)" : "none",
                  transition:"border-color .15s ease, box-shadow .15s ease" }}>
      <img src={p.photoUrl} alt="" loading="lazy" decoding="async" onLoad={() => setLoaded(true)}
           style={{ width:"100%", aspectRatio:"1", objectFit:"cover", display:"block",
                    opacity: loaded ? 1 : 0, transition:"opacity .25s ease" }}/>
      {!loaded && (
        <div style={{ position:"absolute", inset:0,
                      background:"linear-gradient(110deg, rgba(255,255,255,.03) 30%, rgba(255,255,255,.09) 50%, rgba(255,255,255,.03) 70%)",
                      backgroundSize:"200% 100%", animation:"recentShimmer 1.4s linear infinite" }}/>
      )}
      <div style={{ position:"absolute", left:0, right:0, bottom:0, padding:"14px 7px 5px",
                    background:"linear-gradient(transparent, rgba(0,0,0,.72))",
                    fontSize:10, fontWeight:600, color:"rgba(255,255,255,.88)",
                    overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{p.name}</div>
      {selected && (
        <span style={{ position:"absolute", top:5, right:5, width:20, height:20, borderRadius:"50%",
                       background:"#4ACA7A", color:"#04150B", fontSize:12, fontWeight:900,
                       display:"flex", alignItems:"center", justifyContent:"center" }}>✓</span>
      )}
    </div>
  );
}

function AdminReviewPhotosTab({ products = [] }) {
  const proposals = usePhotoProposals();
  const [busyId, setBusyId]   = useState(null);
  const [regenIds, setRegenIds] = useState(() => new Set()); // ids currently re-generating (per-row lock)
  const [dlIds, setDlIds]     = useState(() => new Set()); // ids currently downloading (per-row lock, UI)
  const dlBusyRef = useRef(new Set()); // synchronous double-click guard (state lags a fast second tap)
  // The product whose Regenerate popup is open (null = closed). The popup carries
  // its own AI + fix + comment choices and resets every time it opens, so nothing
  // stays selected after a send.
  const [regenFor, setRegenFor] = useState(null);
  const [bulkBusy, setBulkBusy] = useState(false);
  const [runN, setRunN]       = useState(12);
  const [quality, setQuality] = useState("medium");
  // Engine: "auto" = route by category (Footwear→Gemini, else OpenAI); or force one
  // to compare. Only sent when not "auto"; the function auto-routes otherwise.
  const [engine, setEngine] = useState("auto");
  const engineArg = engine !== "auto" ? { engine } : {};
  // Style: "white" = classic white-bg re-shoot (default, unchanged behavior).
  // "house" = Marathon house-style scene — Style Kit references + Nano Banana
  // Pro (engine choice doesn't apply; the function forces NB Pro).
  const [style, setStyle] = useState("white");
  const house = style === "house";
  const styleArg = house ? { style: "house" } : {};
  const [runBusy, setRunBusy] = useState(false);
  const [runMsg, setRunMsg]   = useState(null);
  const [lightbox, setLightbox] = useState(null);
  // Product picker: choose specific products to generate (multi-select).
  const [picking, setPicking]   = useState(false);
  const [pickSearch, setPickSearch] = useState("");
  // One filter value: "recent" = newest uploads (the default view) · "" = all ·
  // "cat:Footwear" = a whole top-level · "sub:Caps & Hats" = one subcategory.
  // Non-recent values come from a single grouped dropdown so subcategories are
  // directly pickable.
  const [pickFilter, setPickFilter] = useState("recent");
  const [selectedIds, setSelectedIds] = useState(() => new Set());
  // Re-run a product that already has a proposal (e.g. to redo earlier batches
  // through the improved engine). Off by default so the normal flow still hides
  // done products.
  const [includeDone, setIncludeDone] = useState(false);

  // Products already generated (pending/approved) are excluded so you don't re-pick
  // them; rejected ones stay available to retry.
  const handledIds = useMemo(() => new Set(
    Object.entries(proposals || {}).filter(([, v]) => v && v.status !== "rejected").map(([id]) => id)
  ), [proposals]);
  const pickList = useMemo(() => {
    let avail = (products || []).filter(p => p && p.id && p.name && p.photoUrl && (includeDone || !handledIds.has(p.id)));
    if (pickFilter.startsWith("cat:")) { const c = pickFilter.slice(4); avail = avail.filter(p => p.category === c); }
    else if (pickFilter.startsWith("sub:")) { const s = pickFilter.slice(4); avail = avail.filter(p => p.subcategory === s); }
    const q = pickSearch.trim();
    if (q) avail = avail.filter(p => productMatchesQuery(p, q));
    if (pickFilter === "recent") {
      // Newest uploads across all categories: last RECENT_DAYS days, newest
      // first, capped at RECENT_CAP for the grid.
      const cutoff = serverNowMs() - RECENT_DAYS * 864e5;
      return avail.filter(p => uploadTs(p) >= cutoff)
        .sort((a, b) => uploadTs(b) - uploadTs(a))
        .slice(0, RECENT_CAP);
    }
    return avail.sort((a, b) => a.name.localeCompare(b.name));
  }, [products, pickSearch, pickFilter, handledIds, includeDone]);
  // Day-grouped view of the Recent list: [{ day:"2026-07-06", items:[…] }, …].
  // pickList is already newest-first, so groups come out in display order.
  const recentGroups = useMemo(() => {
    if (pickFilter !== "recent") return [];
    const groups = [];
    for (const p of pickList) {
      const day = saDay(uploadTs(p));
      if (!groups.length || groups[groups.length - 1].day !== day) groups.push({ day, items: [] });
      groups[groups.length - 1].items.push(p);
    }
    return groups;
  }, [pickFilter, pickList]);
  // Per-category / per-subcategory count of products that are STILL pickable
  // (have a source photo + not already generated). Shown next to each dropdown
  // option so you can see at a glance which categories have work left — without
  // this, picking a fully-done category just shows "0 products" with no clue why.
  const availBuckets = useMemo(() => {
    const cat = {}, sub = {};
    for (const p of (products || [])) {
      if (!p || !p.id || !p.name || !p.photoUrl) continue;
      if (!includeDone && handledIds.has(p.id)) continue;
      if (p.category)    cat[p.category]    = (cat[p.category]    || 0) + 1;
      if (p.subcategory) sub[p.subcategory] = (sub[p.subcategory] || 0) + 1;
    }
    return { cat, sub };
  }, [products, handledIds, includeDone]);
  const toggleSel = (id) => setSelectedIds(s => { const n = new Set(s); n.has(id) ? n.delete(id) : n.add(id); return n; });
  // Add the products currently shown (after the category/search filters) to the
  // selection — e.g. "select all Jerseys" in one tap. Capped at the 200/batch
  // limit the generate flow enforces server-side, so the UI never promises more
  // than one run can process.
  const PICK_CAP = 200;
  const PICK_RENDER_CAP = 60; // only render this many rows (a category can be 1000+ → don't DOM/fetch 1000 full-res source photos). Narrow with a subcategory; counts in the dropdown show where the work is.
  const selectAllShown = () => setSelectedIds(s => {
    const n = new Set(s);
    for (const p of pickList) { if (n.size >= PICK_CAP) break; n.add(p.id); }
    return n;
  });
  const generateSelected = async () => {
    const ids = [...selectedIds];
    if (!ids.length) return;
    setRunBusy(true); setRunMsg(`Generating ${ids.length} selected${house ? " in house style" : ""} at ${quality}… (slow — image generation)`);
    try {
      const res = await httpsCallable(functions, "generateProductPhotos")({ productIds: ids, reprocess: true, quality, ...engineArg, ...styleArg });
      const d = res?.data || {};
      setRunMsg(`Done — ${d.processed} generated, ${d.failed} failed (≈ $${Number(d.estCostUSD || 0).toFixed(4)} est)${costByEngineStr(d.costByEngine)}${photoFailureSuffix(d.failures)}.`);
      setSelectedIds(new Set()); setPicking(false);
    } catch (e) {
      const m = String(e?.message || e);
      setRunMsg(`Couldn't run: ${m}${m.toLowerCase().includes("internal") || m.toLowerCase().includes("not-found") ? " — is generateProductPhotos deployed?" : ""}`);
    } finally { setRunBusy(false); }
  };

  const pending = useMemo(() => Object.entries(proposals || {})
    .filter(([, v]) => v && v.status !== "approved" && v.status !== "rejected")
    .map(([id, v]) => ({ id, ...v })), [proposals]);
  const decidedCount = useMemo(() => Object.values(proposals || {}).filter(v => v && (v.status === "approved" || v.status === "rejected")).length, [proposals]);

  const approve = async (row) => {
    setBusyId(row.id);
    try {
      await update(ref(database, `products/${row.id}`), { photoUrl: row.proposedUrl, photoUrlOriginal: row.originalUrl });
      await update(ref(database, `aiAssistant/photoProposals/${row.id}`), { status: "approved", decidedAt: serverNowMs() });
      return true;
    } catch (e) { setRunMsg(`Approve failed for “${row.name || row.id}”: ${e?.message || e}`); return false; }
    finally { setBusyId(null); }
  };
  // Save the CURRENT proposed photo onto the product as an extra angle, so a later
  // Regenerate (which re-shoots in place) doesn't throw away a good angle Gemini
  // already produced — at NO extra generation cost. Each generation has a unique,
  // permanent storage URL, so we just append that URL to products/{id}/gallery.
  const galleryOf = (id) => { const p = products.find(x => x.id === id); return Array.isArray(p?.gallery) ? p.gallery.filter(Boolean) : []; };
  const keepExtra = async (row) => {
    const url = row.proposedUrl;
    if (!url) return false;
    const gallery = galleryOf(row.id);
    if (gallery.includes(url)) { setRunMsg(`That photo is already kept for “${row.name || row.id}”.`); return true; }
    try {
      await update(ref(database, `products/${row.id}`), { gallery: [...gallery, url] });
      setRunMsg(`Kept as an extra angle for “${row.name || row.id}” — ${gallery.length + 1} extra${gallery.length ? "s" : ""} saved.`);
      return true;
    } catch (e) { setRunMsg(`Couldn't keep photo: ${e?.message || e}`); return false; }
  };
  const removeExtra = async (row, url) => {
    const gallery = galleryOf(row.id).filter(u => u !== url);
    try { await update(ref(database, `products/${row.id}`), { gallery }); setRunMsg(`Removed an extra angle from “${row.name || row.id}”.`); }
    catch (e) { setRunMsg(`Couldn't remove: ${e?.message || e}`); }
  };
  // Download the AI-generated (proposed) photo to the device. Storage URLs are
  // cross-origin, so a bare <a download> would just navigate — fetch → blob →
  // object-URL keeps the save-as behaviour (Firebase Storage sends CORS on GET).
  // On Safari/iOS the file-share sheet is used instead: a web page can't write
  // into the Photos library directly, but sharing the image FILE puts "Save
  // Image" one tap away — straight into Photos, never via the Downloads folder.
  // Falls back to opening the photo in a new tab if the fetch is blocked.
  const downloadPhoto = async (row) => {
    const url = row.proposedUrl;
    // Ref guard is synchronous — a double-click's second tap lands before React
    // re-renders the disabled state, so a state-only check would race.
    if (!url || dlBusyRef.current.has(row.id)) return;
    dlBusyRef.current.add(row.id);
    setDlIds(s => new Set(s).add(row.id));
    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const ext = (blob.type.split("/")[1] || "jpg").replace("jpeg", "jpg");
      const base = String(row.name || row.id).toLowerCase().replace(/[^\w]+/g, "-").replace(/^-+|-+$/g, "") || row.id;
      const file = new File([blob], `${base}-ai.${ext}`, { type: blob.type || "image/jpeg" });
      // Share sheet where supported (Safari/iOS/iPadOS): "Save Image" → Photos.
      if (typeof navigator !== "undefined" && navigator.canShare && navigator.canShare({ files: [file] })) {
        try {
          await navigator.share({ files: [file], title: row.name || "Product photo" });
          setRunMsg(`Shared “${row.name || row.id}” — tap "Save Image" to add it to Photos.`);
          return;
        } catch (e) {
          // User closed the sheet — not an error, and don't ALSO download.
          if (e?.name === "AbortError") return;
          // Share failed for real (e.g. gesture expired) → fall through to download.
        }
      }
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = file.name;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
      setRunMsg(`Downloaded “${row.name || row.id}” photo.`);
    } catch {
      window.open(url, "_blank", "noopener");
      setRunMsg("Direct download blocked — opened the photo in a new tab (right-click / long-press to save).");
    } finally {
      dlBusyRef.current.delete(row.id);
      setDlIds(s => { const n = new Set(s); n.delete(row.id); return n; });
    }
  };
  const reject = async (row) => {
    setBusyId(row.id);
    try { await update(ref(database, `aiAssistant/photoProposals/${row.id}`), { status: "rejected", decidedAt: serverNowMs() }); }
    catch (e) { setRunMsg(`Reject failed for “${row.name || row.id}”: ${e?.message || e}`); }
    finally { setBusyId(null); }
  };
  const approveAll = async () => {
    if (!pending.length) return;
    if (!window.confirm(`Approve ALL ${pending.length} photos? This swaps those products to the white-bg version (originals are kept).`)) return;
    setBulkBusy(true);
    let okN = 0, failN = 0;
    try { for (const r of pending) { (await approve(r)) ? okN++ : failN++; } }
    finally { setBulkBusy(false); setRunMsg(`Approved ${okN}${failN ? `, ${failN} failed (see above)` : ""}.`); }
  };
  const runAI = async () => {
    setRunBusy(true); setRunMsg(`Generating ${runN} clothing photos${house ? " in house style" : ""}… (slow — image generation)`);
    try {
      const res = await httpsCallable(functions, "generateProductPhotos")({ limit: Number(runN) || 12, category: "clothing", quality, ...engineArg, ...styleArg });
      const d = res?.data || {};
      setRunMsg(`Done — ${d.processed} generated, ${d.failed} failed (≈ $${Number(d.estCostUSD || 0).toFixed(4)} est)${costByEngineStr(d.costByEngine)}${photoFailureSuffix(d.failures)}.`);
    } catch (e) {
      const m = String(e?.message || e);
      setRunMsg(`Couldn't run: ${m}${m.toLowerCase().includes("internal") || m.toLowerCase().includes("not-found") ? " — is generateProductPhotos deployed?" : ""}`);
    } finally { setRunBusy(false); }
  };
  // Re-shoot THIS one product. opts from the Regenerate popup: { note, engine }.
  // The popup's choices win; "auto"/empty fall back to the studio-level engine.
  const regenerate = async (row, opts = {}) => {
    setRegenIds(s => new Set(s).add(row.id));
    const note = String(opts.note || "").trim();
    const thisNote = note ? { note } : {};
    const engine = opts.engine;
    const thisEngine = (engine === "gemini" || engine === "openai") ? { engine } : engineArg;
    setRunMsg(`Regenerating “${row.name || row.id}”${house ? " in house style" : ""} at ${quality}${!house && engine && engine !== "auto" ? ` via ${engine}` : ""}${note ? ` — “${note}”` : ""}…`);
    try {
      const res = await httpsCallable(functions, "generateProductPhotos")({ productIds: [row.id], reprocess: true, quality, ...thisEngine, ...thisNote, ...styleArg });
      const d = res?.data || {};
      setRunMsg(d.processed ? `Regenerated “${row.name || row.id}” (${quality}, ≈ $${Number(d.estCostUSD || 0).toFixed(4)})${costByEngineStr(d.costByEngine)}.` : `Regenerate failed for “${row.name || row.id}”${photoFailureSuffix(d.failures)}.`);
    } catch (e) { setRunMsg(`Regenerate failed for “${row.name || row.id}”: ${e?.message || e}`); }
    finally { setRegenIds(s => { const n = new Set(s); n.delete(row.id); return n; }); }
  };

  const imgBox = { width:"100%", aspectRatio:"1", objectFit:"contain", background:"rgba(255,255,255,.05)", borderRadius:12, border:"1px solid rgba(255,255,255,.08)", cursor:"zoom-in", display:"block" };

  return (
    <div style={{ padding:"0 14px 30px" }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, padding:"6px 0 12px" }}>
        <span style={{ fontSize:18, fontWeight:700, color:"#fff", letterSpacing:-.2 }}>AI Photo Studio</span>
        <span style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.12)", color:"rgba(255,255,255,.6)", fontSize:11.5, fontWeight:600, padding:"3px 10px", borderRadius:999 }}>{pending.length} to review</span>
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", marginBottom:10 }}>
        <span style={{ fontSize:12, color:"rgba(255,255,255,.6)" }}>Generate</span>
        <input type="number" min={1} max={200} value={runN} onChange={e => setRunN(e.target.value)}
               style={{ width:60, background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", borderRadius:8, color:"#fff", padding:"7px 9px", fontSize:13 }}/>
        <select value={quality} onChange={e => setQuality(e.target.value)} title="OpenAI image quality (cost rises with quality; Gemini ignores it)"
                style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", borderRadius:8, color:"#fff", padding:"7px 9px", fontSize:13 }}>
          <option value="low">low (~$0.01)</option>
          <option value="medium">medium (~$0.04)</option>
          <option value="high">high (~$0.17)</option>
        </select>
        <select value={engine} onChange={e => setEngine(e.target.value)} disabled={house}
                title={house ? "House style always runs on Nano Banana Pro" : "Engine: Auto routes Footwear→Gemini, else OpenAI. Force one to compare."}
                style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", borderRadius:8, color:"#fff", padding:"7px 9px", fontSize:13, opacity: house ? .45 : 1 }}>
          <option value="auto">Auto (by category)</option>
          <option value="gemini">Gemini (~$0.067)</option>
          <option value="openai">OpenAI</option>
        </select>
        {/* Style: classic white background vs the Marathon house-style scene
            (Style Kit references + Nano Banana Pro — manage refs in Style Kit). */}
        <div style={{ display:"flex", borderRadius:9, overflow:"hidden", border:"1px solid rgba(255,255,255,.15)" }}>
          {[["white", "⬜ White bg", "Classic white-background re-shoot"], ["house", "⌗ House style", "Marathon scene from the Style Kit references — Nano Banana Pro, ~$0.14/image"]].map(([val, label, hint]) => {
            const on = style === val;
            return (
              <button key={val} onClick={() => setStyle(val)} title={hint}
                      style={{ background: on ? (val === "house" ? "rgba(167,139,250,.28)" : "rgba(74,127,255,.28)") : "rgba(255,255,255,.04)",
                               color: on ? (val === "house" ? "#C4B5FD" : "#9DBCFF") : "rgba(255,255,255,.5)",
                               border:"none", padding:"8px 12px", fontSize:12, fontWeight:700, cursor:"pointer" }}>
                {label}
              </button>
            );
          })}
        </div>
        <button onClick={selectedIds.size ? generateSelected : runAI} disabled={runBusy}
                title={selectedIds.size ? "Generate the products you picked" : "Auto-generate the next clothing items missing a photo"}
                style={{ background:"#4A7FFF", color:"#fff", border:"none", borderRadius:9, padding:"8px 14px", fontSize:12.5, fontWeight:700, cursor: runBusy ? "wait" : "pointer", opacity: runBusy ? .6 : 1 }}>
          {runBusy ? "Generating…" : selectedIds.size ? `Generate ${selectedIds.size} picked (${quality})` : "Generate next clothing"}
        </button>
        <button onClick={() => setPicking(v => !v)}
                style={{ background: picking ? "#4A7FFF" : "rgba(74,127,255,.14)", color: picking ? "#fff" : "#7AA7FF", border:"1px solid rgba(74,127,255,.4)", borderRadius:9, padding:"8px 14px", fontSize:12.5, fontWeight:700, cursor:"pointer" }}>
          {picking ? "Close picker" : "Choose products…"}
        </button>
        {pending.length > 0 && (
          <button onClick={approveAll} disabled={bulkBusy}
                  style={{ background:"rgba(0,150,70,.22)", color:"#4ACA7A", border:"1px solid rgba(0,180,80,.45)", borderRadius:9, padding:"8px 14px", fontSize:12.5, fontWeight:800, cursor: bulkBusy ? "wait" : "pointer", opacity: bulkBusy ? .6 : 1 }}>
            {bulkBusy ? "Approving…" : `Approve all (${pending.length})`}
          </button>
        )}
      </div>
      {runMsg && <div style={{ fontSize:11.5, color:"rgba(255,255,255,.6)", marginBottom:10 }}>{runMsg}</div>}
      {decidedCount > 0 && <div style={{ fontSize:11, color:"rgba(255,255,255,.35)", marginBottom:10 }}>{decidedCount} already decided (hidden).</div>}

      {/* PRODUCT PICKER — search, tap to select as many as you want, then generate exactly those. */}
      {picking && (
        <div style={{ background:"rgba(8,11,20,.95)", border:"1px solid rgba(74,127,255,.3)", borderRadius:12, padding:12, marginBottom:14 }}>
          {RECENT_SHIMMER_STYLE}
          {/* View chips — "Recent" (newest uploads across all categories, the
              default) vs "Browse categories" (the grouped dropdown below). */}
          <div style={{ display:"flex", gap:8, marginBottom:8 }}>
            {[["recent", "✦ Recent"], ["", "Browse categories"]].map(([val, label]) => {
              const active = (pickFilter === "recent") === (val === "recent");
              return (
                <button key={val || "browse"} onClick={() => setPickFilter(val)}
                        style={{ background: active ? "rgba(74,127,255,.22)" : "rgba(255,255,255,.05)",
                                 color: active ? "#9DBCFF" : "rgba(255,255,255,.55)",
                                 border:"1px solid " + (active ? "rgba(74,127,255,.55)" : "rgba(255,255,255,.12)"),
                                 borderRadius:999, padding:"7px 14px", fontSize:12, fontWeight:700, cursor:"pointer",
                                 transition:"background .15s ease, color .15s ease, border-color .15s ease" }}>
                  {label}
                </button>
              );
            })}
          </div>
          <input value={pickSearch} onChange={e => setPickSearch(e.target.value)} placeholder="Search products by name or barcode…"
                 style={{ width:"100%", boxSizing:"border-box", background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", borderRadius:8, color:"#fff", padding:"9px 11px", fontSize:13.5, marginBottom:8 }}/>
          {/* Category filter — ONE grouped dropdown: every top-level AND every subcategory
              (Caps & Hats, T-Shirts, Sneakers…) directly pickable, grouped by top level. */}
          {pickFilter !== "recent" && (
          <select value={pickFilter} onChange={e => setPickFilter(e.target.value)} aria-label="Filter by category"
                  style={{ width:"100%", boxSizing:"border-box", background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", borderRadius:8, color:"#fff", padding:"8px 9px", fontSize:12.5, marginBottom:8 }}>
            <option value="">All categories</option>
            {Object.entries(CATEGORY_TREE).map(([top, subs]) => (
              <optgroup key={top} label={top}>
                <option value={`cat:${top}`}>All {top} ({availBuckets.cat[top] || 0})</option>
                {subs.map(s => <option key={s} value={`sub:${s}`}>{s} ({availBuckets.sub[s] || 0})</option>)}
              </optgroup>
            ))}
          </select>
          )}
          {/* Re-run already-done products (e.g. redo earlier batches through the improved
              engine). Counts + list switch to include them when on. */}
          <label style={{ display:"flex", alignItems:"center", gap:8, marginBottom:8, cursor:"pointer", fontSize:12, color:"rgba(255,255,255,.75)" }}>
            <input type="checkbox" checked={includeDone} onChange={e => { setIncludeDone(e.target.checked); setSelectedIds(new Set()); }} style={{ width:15, height:15, accentColor:"#4A7FFF", cursor:"pointer" }}/>
            Include already-done products <span style={{ color:"rgba(255,255,255,.4)" }}>(re-generate)</span>
          </label>
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:8 }}>
            <span style={{ fontSize:11, color:"rgba(255,255,255,.4)" }}>
              {pickFilter === "recent"
                ? <>{pickList.length} upload{pickList.length===1?"":"s"} · last {RECENT_DAYS} days{pickList.length >= RECENT_CAP ? ` (newest ${RECENT_CAP})` : ""}{selectedIds.size ? ` · ${selectedIds.size} selected` : ""}</>
                : <>{pickList.length} product{pickList.length===1?"":"s"} {includeDone ? "available (incl. done)" : "not yet done"}{!includeDone && handledIds.size ? ` · ${handledIds.size} hidden` : ""}{selectedIds.size ? ` · ${selectedIds.size} selected` : ""}</>}
            </span>
            {pickList.length > 0 && (
              <button onClick={selectAllShown}
                      style={{ background:"rgba(74,127,255,.16)", color:"#7AA7FF", border:"1px solid rgba(74,127,255,.4)", borderRadius:7, padding:"4px 10px", fontSize:11.5, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap" }}>
                + Select all {Math.min(pickList.length, PICK_CAP)}
              </button>
            )}
          </div>
          {/* RECENT — day-grouped grid of newest uploads, tap to select. */}
          {pickFilter === "recent" && (
            <div style={{ maxHeight:420, overflowY:"auto" }}>
              {recentGroups.map(g => (
                <div key={g.day}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, margin:"10px 2px 7px" }}>
                    <span style={{ fontSize:11, fontWeight:800, letterSpacing:.4, textTransform:"uppercase", color:"rgba(157,188,255,.85)" }}>{recentDayLabel(g.day)}</span>
                    <span style={{ flex:1, height:1, background:"linear-gradient(90deg, rgba(74,127,255,.28), transparent)" }}/>
                    <span style={{ fontSize:10.5, color:"rgba(255,255,255,.35)" }}>{g.items.length}</span>
                  </div>
                  <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(92px, 1fr))", gap:8 }}>
                    {g.items.map(p => <RecentPickCard key={p.id} p={p} selected={selectedIds.has(p.id)} onToggle={() => toggleSel(p.id)}/>)}
                  </div>
                </div>
              ))}
              {pickList.length === 0 && (
                <div style={{ textAlign:"center", padding:"28px 10px 22px" }}>
                  <div style={{ fontSize:22, marginBottom:6, opacity:.5 }}>✦</div>
                  <div style={{ fontSize:13, fontWeight:700, color:"rgba(255,255,255,.75)" }}>No recent uploads</div>
                  <div style={{ fontSize:11.5, color:"rgba(255,255,255,.4)", marginTop:4 }}>
                    {pickSearch.trim() ? `Nothing in the last ${RECENT_DAYS} days matches that search.` : `Nothing uploaded in the last ${RECENT_DAYS} days${!includeDone ? " that isn't already done — tick “Include already-done” to see everything" : ""}.`}
                  </div>
                </div>
              )}
            </div>
          )}
          {pickFilter !== "recent" && (
          <div style={{ maxHeight:380, overflowY:"auto", display:"flex", flexDirection:"column", gap:6 }}>
            {pickList.slice(0, PICK_RENDER_CAP).map(p => {
              const on = selectedIds.has(p.id);
              return (
                <div key={p.id} onClick={() => toggleSel(p.id)}
                     style={{ display:"flex", alignItems:"center", gap:10, padding:"6px 8px", borderRadius:9, cursor:"pointer",
                              background: on ? "rgba(74,202,122,.16)" : "rgba(255,255,255,.03)", border:"1px solid "+(on ? "rgba(74,202,122,.5)" : "rgba(255,255,255,.07)") }}>
                  <img src={p.photoUrl} alt="" loading="lazy" decoding="async"
                       style={{ width:38, height:38, borderRadius:7, objectFit:"cover", background:"rgba(255,255,255,.08)", flexShrink:0 }}/>
                  <span style={{ flex:1, minWidth:0, fontSize:12.5, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{p.name}</span>
                  <span style={{ fontSize:15, color: on ? "#4ACA7A" : "rgba(255,255,255,.25)" }}>{on ? "✓" : "+"}</span>
                </div>
              );
            })}
            {pickList.length === 0 && <div style={{ color:"#555", fontSize:12, padding:"12px 4px" }}>{(pickSearch.trim() || pickFilter) ? "No products match these filters (those products may have no source photo, or are already done)." : "All products already generated 🎉"}</div>}
          </div>
          )}
          {pickList.length > PICK_RENDER_CAP && pickFilter !== "recent" && (
            <div style={{ fontSize:10.5, color:"rgba(255,255,255,.4)", marginTop:6 }}>
              Showing first {PICK_RENDER_CAP} of {pickList.length} — narrow with a subcategory or search. “Select all” still grabs up to {PICK_CAP}.
            </div>
          )}
          <div style={{ fontSize:10.5, color:"rgba(255,255,255,.3)", marginTop:4 }}>Tip: each batch caps at 200; for a big run, select in groups.</div>
          <div style={{ display:"flex", gap:8, marginTop:10 }}>
            <button onClick={generateSelected} disabled={!selectedIds.size || runBusy}
                    style={{ flex:1, background:"#4A7FFF", color:"#fff", border:"none", borderRadius:9, padding:"10px 0", fontSize:12.5, fontWeight:800, cursor: (!selectedIds.size||runBusy) ? "not-allowed" : "pointer", opacity: (!selectedIds.size||runBusy) ? .5 : 1 }}>
              {runBusy ? "Generating…" : `Generate ${selectedIds.size || ""} selected (${quality})`}
            </button>
            {selectedIds.size > 0 && (
              <button onClick={() => setSelectedIds(new Set())}
                      style={{ background:"rgba(255,255,255,.06)", color:"rgba(255,255,255,.7)", border:"1px solid rgba(255,255,255,.15)", borderRadius:9, padding:"10px 14px", fontSize:12.5, fontWeight:700, cursor:"pointer" }}>Clear</button>
            )}
          </div>
        </div>
      )}

      {pending.length === 0 && !picking && (
        <div style={{ textAlign:"center", color:"#555", padding:"2.5rem 1rem", fontSize:"0.9rem" }}>
          No photo proposals to review. Use “Generate next clothing” or “Choose products…” to re-shoot on a white background.
        </div>
      )}

      <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
        {pending.map(row => {
          const busy = busyId === row.id;
          const regen = regenIds.has(row.id);
          const extras = galleryOf(row.id);
          return (
            <div key={row.id} style={{ background:"rgba(255,255,255,.025)", border:"1px solid rgba(255,255,255,.08)", borderRadius:16, padding:14 }}>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:12 }}>
                <span style={{ fontSize:14, fontWeight:600, color:"#fff", letterSpacing:-.1, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", flex:1, minWidth:0 }}>{row.name || "(no name)"}</span>
                {row.style === "house" && (
                  <span title={`House style · ${row.template || "?"} template · ${row.refsUsed ?? 0} reference${row.refsUsed === 1 ? "" : "s"}`}
                        style={{ background:"rgba(167,139,250,.18)", border:"1px solid rgba(167,139,250,.45)", color:"#C4B5FD", fontSize:10, fontWeight:800, padding:"2px 8px", borderRadius:999, flexShrink:0 }}>
                    ⌗ HOUSE
                  </span>
                )}
                {row.engine && (
                  <span style={{ display:"inline-flex", alignItems:"center", gap:5, fontSize:11, fontWeight:600, color:"rgba(255,255,255,.45)", flexShrink:0 }}>
                    <span style={{ width:6, height:6, borderRadius:"50%", background: row.engine === "gemini" ? "#F59E0B" : row.engine === "nbpro" ? "#A78BFA" : "#7AA7FF" }}/>
                    {row.engine === "gemini" ? "Gemini" : row.engine === "nbpro" ? "NB Pro" : "OpenAI"}{Number(row.costUSD) > 0 ? ` · $${Number(row.costUSD).toFixed(3)}` : ""}
                  </span>
                )}
              </div>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:12 }}>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:9, fontWeight:700, color:"rgba(255,255,255,.3)", marginBottom:5, letterSpacing:1 }}>BEFORE</div>
                  <img src={row.originalUrl} alt="" onClick={() => setLightbox(row.originalUrl)} style={imgBox}/>
                </div>
                <span style={{ color:"rgba(255,255,255,.2)", fontSize:16, marginTop:18, flexShrink:0 }}>→</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:9, fontWeight:700, color:"rgba(123,167,255,.7)", marginBottom:5, letterSpacing:1 }}>AFTER</div>
                  <img src={row.proposedUrl} alt="" onClick={() => setLightbox(row.proposedUrl)} style={imgBox}/>
                </div>
              </div>
              {/* Extras + keep on one quiet line: kept angles on the left, a ghost
                  "Keep angle" chip on the right. Tap a thumb to zoom; × to remove. */}
              <div style={{ display:"flex", alignItems:"center", gap:7, flexWrap:"wrap", marginBottom:12 }}>
                {extras.length > 0 && <span style={{ fontSize:9, fontWeight:700, color:"rgba(255,255,255,.35)", letterSpacing:1 }}>EXTRAS</span>}
                {extras.map((u) => (
                  <div key={u} style={{ position:"relative" }}>
                    <img src={u} alt="" onClick={() => setLightbox(u)} style={{ width:34, height:34, borderRadius:8, objectFit:"cover", background:"#fff", border:"1px solid rgba(255,255,255,.12)", cursor:"zoom-in", display:"block" }}/>
                    <button onClick={() => removeExtra(row, u)} aria-label="Remove extra angle"
                            style={{ position:"absolute", top:-5, right:-5, width:15, height:15, borderRadius:"50%", background:"rgba(10,12,20,.9)", color:"rgba(255,255,255,.7)", border:"1px solid rgba(255,255,255,.2)", fontSize:10, lineHeight:1, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", padding:0 }}>×</button>
                  </div>
                ))}
                <button onClick={() => keepExtra(row)} disabled={busy || regen} title="Save this photo as an extra angle (no extra cost)"
                        style={{ marginLeft:"auto", display:"inline-flex", alignItems:"center", gap:5, background:"transparent", border:"1px solid rgba(255,255,255,.14)", color:"rgba(255,255,255,.65)", borderRadius:999, padding:"5px 11px", fontSize:11, fontWeight:600, cursor:(busy||regen)?"wait":"pointer" }}>
                  <span style={{ fontSize:12 }}>＋</span> Keep angle
                </button>
                <button onClick={() => downloadPhoto(row)} disabled={dlIds.has(row.id)} title="Download the AI-generated photo to this device"
                        style={{ display:"inline-flex", alignItems:"center", gap:5, background:"transparent", border:"1px solid rgba(255,255,255,.14)", color:"rgba(255,255,255,.65)", borderRadius:999, padding:"5px 11px", fontSize:11, fontWeight:600, cursor: dlIds.has(row.id) ? "wait" : "pointer", opacity: dlIds.has(row.id) ? .55 : 1 }}>
                  <span style={{ fontSize:12 }}>⬇</span> {dlIds.has(row.id) ? "Saving…" : "Download"}
                </button>
              </div>
              <div style={{ display:"flex", flexWrap:"wrap", gap:8 }}>
                <button onClick={() => approve(row)} disabled={busy || regen}
                        style={{ flex:"1.4 1 100px", background:"rgba(74,202,122,.16)", border:"1px solid rgba(74,202,122,.35)", color:"#5FD894", borderRadius:11, padding:"11px 0", fontSize:13, fontWeight:700, cursor: (busy||regen) ? "wait" : "pointer", opacity: (busy||regen) ? .55 : 1 }}>
                  {busy ? "…" : "Approve"}
                </button>
                <button onClick={() => setRegenFor(row)} disabled={busy || regen}
                        title="Open regenerate options"
                        style={{ flex:1, display:"inline-flex", alignItems:"center", justifyContent:"center", gap:6, background:"rgba(255,255,255,.045)", border:"1px solid rgba(255,255,255,.1)", color:"rgba(255,255,255,.8)", borderRadius:11, padding:"11px 0", fontSize:13, fontWeight:600, cursor: (busy||regen) ? "wait" : "pointer", opacity: (busy||regen) ? .55 : 1 }}>
                  <span style={{ fontSize:13 }}>↻</span>{regen ? "…" : "Regenerate"}
                </button>
                <button onClick={() => reject(row)} disabled={busy || regen} title="Reject"
                        style={{ flexShrink:0, background:"transparent", border:"1px solid rgba(255,255,255,.1)", color:"rgba(255,120,120,.75)", borderRadius:11, padding:"11px 16px", fontSize:13, fontWeight:600, cursor: (busy||regen) ? "wait" : "pointer", opacity: (busy||regen) ? .55 : 1 }}>
                  Reject
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {lightbox && (
        <div onClick={() => setLightbox(null)} style={{ position:"fixed", inset:0, background:"rgba(0,0,0,.9)", zIndex:9999, display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
          <img src={lightbox} alt="" style={{ maxWidth:"100%", maxHeight:"100%", objectFit:"contain", borderRadius:10 }}/>
        </div>
      )}
      {regenFor && (
        <RegenerateModal
          row={regenFor}
          quality={quality}
          house={house}
          product={products.find(p => p.id === regenFor.id)}
          extraCount={galleryOf(regenFor.id).length}
          onClose={() => setRegenFor(null)}
          onSubmit={async (opts) => { const r = regenFor; setRegenFor(null); if (opts.keepFirst) await keepExtra(r); regenerate(r, opts); }}
        />
      )}
    </div>
  );
}

// Regenerate popup — opens from a card's Regenerate button. Holds its OWN choices
// (AI + fixes + comment) in local state, so they reset every time it opens and
// nothing stays selected after a send. onSubmit closes it and fires the re-shoot.
// In house mode the engine picker is hidden (the function forces Nano Banana Pro)
// and sneakers get a box-photo slot: the product's real box shot is attached to
// every house generation so the AI reproduces the actual box, not a guess.
function RegenerateModal({ row, quality, house = false, product = null, extraCount = 0, onClose, onSubmit }) {
  const [engine, setEngine] = useState("gemini"); // default to Gemini for regenerates
  const [note, setNote] = useState("");
  const [keepFirst, setKeepFirst] = useState(true); // keep the current photo before re-shooting (no extra cost)
  // Box-photo slot state (house + sneaker only). boxUrl mirrors the product's
  // photoBoxUrl and updates optimistically after an upload. Mirror the backend's
  // clothing test EXACTLY (category === "Clothing" || productType === "clothing")
  // so we never show a box slot for something the function treats as clothing —
  // otherwise the uploaded box would be silently ignored in house generation.
  const isSneaker = !((product?.category || row.category) === "Clothing" || (product?.productType || row.productType) === "clothing");
  const [boxUrl, setBoxUrl] = useState(product?.photoBoxUrl || null);
  const [boxBusy, setBoxBusy] = useState(false);
  const [boxErr, setBoxErr] = useState(null);
  const boxFileRef = useRef(null);
  const handleBoxFile = async (e) => {
    const file = e.target.files[0];
    e.target.value = "";
    if (!file || !product?.id) return;
    setBoxBusy(true); setBoxErr(null);
    try { setBoxUrl(await uploadBoxPhoto(product.id, file)); }
    catch (err) { setBoxErr(String(err?.message || err)); }
    finally { setBoxBusy(false); }
  };
  const toggle = (instr) => setNote(n => {
    const t = n.trim();
    if (t.includes(instr)) return t.replace(instr, "").replace(/;\s*;/g, ";").replace(/^;\s*|;\s*$/g, "").trim();
    return (t ? t + "; " + instr : instr).slice(0, 240);
  });
  const lbl = { fontSize:11, fontWeight:700, color:"rgba(255,255,255,.5)", marginBottom:7, letterSpacing:.4 };
  const ENGINES = [["auto","Auto","smart pick"], ["gemini","Gemini","best for shoes"], ["openai","OpenAI","best for clothing"]];
  return (
    <div onClick={onClose} style={{ position:"fixed", inset:0, background:"rgba(4,6,12,.72)", backdropFilter:"blur(6px)", WebkitBackdropFilter:"blur(6px)", zIndex:10000, display:"flex", alignItems:"center", justifyContent:"center", padding:16 }}>
      <div onClick={e => e.stopPropagation()} style={{ width:"100%", maxWidth:440, maxHeight:"90vh", overflowY:"auto", background:"linear-gradient(180deg, rgba(18,22,38,.98), rgba(10,13,24,.98))", border:"1px solid rgba(74,127,255,.28)", borderRadius:18, boxShadow:"0 24px 80px rgba(0,0,0,.6)", padding:18 }}>
        <div style={{ display:"flex", alignItems:"center", gap:11, marginBottom:16 }}>
          <img src={row.proposedUrl} alt="" style={{ width:54, height:54, borderRadius:11, objectFit:"cover", border:"1px solid rgba(255,255,255,.12)", background:"#fff", flexShrink:0 }}/>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontSize:10.5, fontWeight:800, letterSpacing:1, color:"#7AA7FF" }}>✦ REGENERATE</div>
            <div style={{ fontSize:14.5, fontWeight:700, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{row.name || "(no name)"}</div>
          </div>
          <button onClick={onClose} aria-label="Close" style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.12)", color:"rgba(255,255,255,.6)", borderRadius:8, width:30, height:30, fontSize:17, cursor:"pointer", lineHeight:1, flexShrink:0 }}>×</button>
        </div>

        {!house && (<>
        <div style={lbl}>CHOOSE AI</div>
        <div style={{ display:"flex", flexWrap:"wrap", gap:7, marginBottom:16 }}>
          {ENGINES.map(([val, lab, hint]) => {
            const sel = engine === val;
            return (
              <button key={val} type="button" onClick={() => setEngine(val)}
                      style={{ flex:1, background: sel ? "linear-gradient(180deg,rgba(74,127,255,.32),rgba(74,127,255,.15))" : "rgba(255,255,255,.04)",
                               border:"1px solid "+(sel ? "rgba(74,127,255,.6)" : "rgba(255,255,255,.1)"), borderRadius:12, padding:"10px 6px", cursor:"pointer" }}>
                <div style={{ fontSize:12.5, fontWeight:800, color: sel ? "#fff" : "rgba(255,255,255,.75)" }}>{lab}</div>
                <div style={{ fontSize:9.5, color: sel ? "#9DBBFF" : "rgba(255,255,255,.4)", marginTop:2 }}>{hint}</div>
              </button>
            );
          })}
        </div>
        </>)}
        {house && (
          <div style={{ background:"rgba(167,139,250,.1)", border:"1px solid rgba(167,139,250,.35)", borderRadius:12, padding:"10px 12px", marginBottom:16 }}>
            <div style={{ fontSize:11.5, fontWeight:800, color:"#C4B5FD" }}>⌗ HOUSE STYLE · Nano Banana Pro</div>
            <div style={{ fontSize:10.5, color:"rgba(255,255,255,.55)", marginTop:3 }}>
              Re-shot in the Marathon scene using the Style Kit references (~$0.14/image).
            </div>
          </div>
        )}
        {house && isSneaker && (
          <>
            <div style={lbl}>BOX PHOTO <span style={{ fontWeight:500, color:"rgba(255,255,255,.3)" }}>attached automatically</span></div>
            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:16, padding:"10px 12px", borderRadius:12,
                          background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.12)" }}>
              {boxUrl
                ? <img src={boxUrl} alt="Box" style={{ width:46, height:46, borderRadius:9, objectFit:"cover", background:"#fff", border:"1px solid rgba(255,255,255,.12)", flexShrink:0 }}/>
                : <span style={{ width:46, height:46, borderRadius:9, border:"1px dashed rgba(255,255,255,.25)", color:"rgba(255,255,255,.3)", fontSize:17, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>▣</span>}
              <span style={{ flex:1, minWidth:0, fontSize:11, color:"rgba(255,255,255,.55)", lineHeight:1.4 }}>
                {boxErr ? <span style={{ color:"#FF8A8A" }}>{boxErr}</span>
                        : boxUrl ? "This box shot is sent with the re-shoot so the AI reproduces the real box."
                                 : "No box photo yet — the AI will render this model's retail box from its knowledge. Add a real shot for an exact match."}
              </span>
              <input ref={boxFileRef} type="file" accept="image/*" onChange={handleBoxFile} style={{ display:"none" }}/>
              <button type="button" onClick={() => boxFileRef.current?.click()} disabled={boxBusy || !product?.id}
                      style={{ background:"rgba(167,139,250,.16)", color:"#C4B5FD", border:"1px solid rgba(167,139,250,.45)", borderRadius:9, padding:"7px 12px", fontSize:11.5, fontWeight:700, cursor: boxBusy ? "wait" : "pointer", flexShrink:0, opacity: boxBusy ? .6 : 1 }}>
                {boxBusy ? "Uploading…" : boxUrl ? "Replace" : "＋ Add box photo"}
              </button>
            </div>
          </>
        )}

        <div style={lbl}>WHAT NEEDS FIXING? <span style={{ fontWeight:500, color:"rgba(255,255,255,.3)" }}>tap any</span></div>
        <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:16 }}>
          {FIX_PRESETS.map(([label, instr]) => {
            const on = note.includes(instr);
            return (
              <button key={label} type="button" onClick={() => toggle(instr)}
                      style={{ background: on ? "rgba(74,127,255,.25)" : "rgba(255,255,255,.05)", color: on ? "#cdddff" : "rgba(255,255,255,.7)",
                               border:"1px solid "+(on ? "rgba(74,127,255,.6)" : "rgba(255,255,255,.13)"), borderRadius:999, padding:"6px 12px", fontSize:11.5, fontWeight:700, cursor:"pointer" }}>
                {on ? "✓ " : ""}{label}
              </button>
            );
          })}
        </div>

        <div style={lbl}>COMMENT <span style={{ fontWeight:500, color:"rgba(255,255,255,.3)" }}>optional</span></div>
        <textarea value={note} onChange={e => setNote(e.target.value.slice(0, 240))} maxLength={240} rows={2}
                  placeholder="Tell the AI exactly what to change…"
                  style={{ width:"100%", boxSizing:"border-box", background:"rgba(255,255,255,.06)", border:"1px solid "+(note.trim() ? "rgba(74,127,255,.5)" : "rgba(255,255,255,.14)"), borderRadius:10, color:"#fff", padding:"10px 12px", fontSize:12.5, resize:"vertical", fontFamily:"inherit" }}/>

        {/* Keep the current photo as an extra angle before re-shooting — so a good
            angle you already paid for isn't lost. No extra generation cost. */}
        <label style={{ display:"flex", alignItems:"flex-start", gap:9, marginTop:16, padding:"11px 12px", borderRadius:11, cursor:"pointer",
                        background: keepFirst ? "rgba(74,202,122,.1)" : "rgba(255,255,255,.04)", border:"1px solid "+(keepFirst ? "rgba(74,202,122,.4)" : "rgba(255,255,255,.12)") }}>
          <input type="checkbox" checked={keepFirst} onChange={e => setKeepFirst(e.target.checked)} style={{ width:16, height:16, accentColor:"#4ACA7A", cursor:"pointer", marginTop:1 }}/>
          <span style={{ fontSize:12.5, color:"#fff", lineHeight:1.35 }}>
            Keep the current photo as an extra angle first
            <span style={{ display:"block", fontSize:10.5, color:"rgba(255,255,255,.5)", marginTop:2 }}>
              Saves it onto the product (no extra cost) so this re-shoot can't lose it{extraCount ? ` · ${extraCount} already kept` : ""}.
            </span>
          </span>
        </label>
        <div style={{ display:"flex", gap:9, marginTop:14 }}>
          <button type="button" onClick={onClose}
                  style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.14)", color:"rgba(255,255,255,.7)", borderRadius:11, padding:"11px 16px", fontSize:13, fontWeight:700, cursor:"pointer" }}>Cancel</button>
          <button type="button" onClick={() => onSubmit({ engine: house ? "auto" : engine, note, keepFirst })}
                  style={{ flex:1, background: house ? "linear-gradient(180deg,#A78BFA,#7C5CE0)" : "linear-gradient(180deg,#5A8BFF,#3D6BFF)", border:"none", color:"#fff", borderRadius:11, padding:"11px 0", fontSize:13.5, fontWeight:800, cursor:"pointer", boxShadow: house ? "0 6px 18px rgba(124,92,224,.4)" : "0 6px 18px rgba(61,107,255,.4)" }}>
            {house ? "⌗ Regenerate in house style" : `✦ Regenerate at ${quality}`}
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── STYLE KIT — HOUSE-STYLE REFERENCE MANAGER ────────────────────────────────
// Super-admin panel (inside AI Studio) for the reference images + locked prompts
// that drive house-style generations. Two templates keyed on productType:
// "sneaker" (shoe + its box) and "clothing" (garment sets). Everything lives at
// /aiAssistant/styleKit/{template} = { prompt, refs:{refId:{url,path,enabled,…}} }
// and Storage aiStudio/styleKit/{template}/{refId}.jpg — the generate function
// re-reads it per call, so changes apply to the NEXT generation, no redeploy.
const STYLE_KIT_TEMPLATES = [
  { key: "sneaker",  label: "Sneaker",  hint: "shoe displayed with its box" },
  { key: "clothing", label: "Clothing", hint: "garment sets on the backdrop" },
];
// Cosmetic garment-type labels for CLOTHING refs — organisation only, so the
// spread across types is visible at a glance. The generator ignores them and
// sends the first enabled clothing refs regardless of label.
const STYLE_KIT_KINDS = ["cap", "tee", "jeans", "jacket", "tracksuit", "other"];
const STYLE_KIT_MAX_SENT = 6; // KEEP IN SYNC with HOUSE_MAX_REFS in functions/index.js

// Panel starting text for the locked prompts — display copies of the function's
// code defaults. KEEP IN SYNC with HOUSE_PROMPT_* in functions/index.js: the
// function only reads /aiAssistant/styleKit/{template}/prompt when one is SAVED;
// until then it uses its own identical built-in.
const STYLE_KIT_DEFAULT_PROMPTS = {
  clothing: [
    "You are re-shooting a product photo in our store's signature house style. The STYLE REFERENCE",
    "images show our exact studio scene — recreate that scene precisely: the same backdrop and wall,",
    "the same hangers and display hardware, the same lighting direction, softness and colour grade,",
    "the same camera height, distance, angle and framing, and the same layout and spacing. The output",
    "must look like it was shot in the SAME session, in the SAME spot, with the SAME lighting rig as",
    "the references.",
    "CRITICAL — the references define ONLY the scene and styling. The garments shown in the references",
    "are DIFFERENT products: none of their design, colour, fabric, branding or details may appear in",
    "the output.",
    "The PRODUCT image shows the actual item to photograph. Keep the product's design EXACTLY —",
    "identical shape, proportions, colour, materials, patterns, logos and text. Never redesign,",
    "restyle, recolour, or invent details the real product does not have. Render every brand wordmark",
    "and logo crisply and correctly — properly letter-formed, correctly spelled, matching the real",
    "brand's exact lettering; never garbled, warped or fake-looking.",
    "Present the garments as a coordinated SET, displayed exactly the way the reference sets are",
    "displayed — every piece visible in the product photo (e.g. hoodie and matching joggers) arranged",
    "together in the same configuration, on the same hangers, with the same spacing as the references.",
    "If the product photo shows a single piece, present just that piece in the identical scene and",
    "position. Garments fully steamed and wrinkle-free with natural drape, squared shoulders and",
    "straight hems; nothing cropped or cut off.",
    "Keep the product's TRUE colours at full strength — never washed out, faded or over-exposed. Dark",
    "colours stay RICH and DEEP. Match the exposure and white balance of the reference scene so the",
    "product sits naturally in its lighting. Tack-sharp focus and fine detail throughout; a flawless,",
    "photorealistic result indistinguishable from a real photo taken in our studio.",
  ].join(" "),
  sneaker: [
    "You are re-shooting a product photo in our store's signature house style. The STYLE REFERENCE",
    "images show our exact studio scene — recreate it precisely: the same backdrop, surface, lighting",
    "direction, softness and colour grade, the same camera height, angle and framing, and the same",
    "shoe-and-box composition and spacing as the references. The output must look like it was shot in",
    "the SAME session, in the SAME spot, with the SAME lighting rig.",
    "CRITICAL — the references define ONLY the scene, layout and styling. The sneakers and boxes shown",
    "in them are DIFFERENT products: none of their design, colourway or branding may appear in the",
    "output.",
    "The PRODUCT image shows the actual sneaker to photograph. Keep its design EXACTLY — identical",
    "shape, proportions, colourway, materials, patterns, logos and text. Show the OUTER (lateral)",
    "branded display side facing the camera, keeping the SAME side and SAME left/right facing as the",
    "product photo — never flip, mirror or rotate to the plain inner side. Never redesign or invent",
    "details.",
    "Display the sneaker WITH its retail box, positioned exactly as the boxes are positioned in the",
    "references. If a BOX image is provided, reproduce that exact box — its true colours, graphics,",
    "logos and label text, correctly spelled and crisply rendered. If no box image is provided, show",
    "this exact model's authentic retail box using your knowledge of the real product; keep all box",
    "text and branding accurate and legible, and never invent box artwork that doesn't exist.",
    "True, full-strength colours — dark colours stay rich and deep; match the reference scene's",
    "exposure and white balance. Tack-sharp focus and detail; a flawless, photorealistic result",
    "indistinguishable from a real photo taken in our studio.",
  ].join(" "),
};

function StyleKitPanel() {
  const { user } = usePermissions();
  const [kit, setKit] = useState({});
  useEffect(() => {
    const unsub = onValue(ref(database, "aiAssistant/styleKit"), snap => setKit(snap.val() || {}));
    return () => unsub();
  }, []);
  const [template, setTemplate] = useState("sneaker");
  const [uploadKind, setUploadKind] = useState("other");
  const [uploading, setUploading] = useState(false);
  const [msg, setMsg] = useState(null);
  const fileRef = useRef(null);
  // Prompt draft: null = showing the saved (or default) text; a string = edited.
  const [draft, setDraft] = useState(null);
  const [savingPrompt, setSavingPrompt] = useState(false);
  useEffect(() => { setDraft(null); setMsg(null); }, [template]);

  const t = kit[template] || {};
  const refsArr = useMemo(() => Object.entries(t.refs || {})
    .map(([id, r]) => ({ id, ...r }))
    .sort((a, b) => (a.addedAt || 0) - (b.addedAt || 0)), [t.refs]);
  const enabled = refsArr.filter(r => r.enabled !== false);
  // The generator sends the FIRST STYLE_KIT_MAX_SENT enabled refs (oldest first)
  // — badge exactly those so what's "live" is never a guess.
  const sentIds = new Set(enabled.slice(0, STYLE_KIT_MAX_SENT).map(r => r.id));

  const isCustomPrompt = typeof t.prompt === "string" && t.prompt.trim().length > 0;
  const effectivePrompt = isCustomPrompt ? t.prompt : STYLE_KIT_DEFAULT_PROMPTS[template];
  const shownPrompt = draft !== null ? draft : effectivePrompt;
  const promptDirty = draft !== null && draft.trim() !== effectivePrompt.trim();

  const handleFiles = async (e) => {
    const files = [...(e.target.files || [])];
    e.target.value = "";
    if (!files.length) return;
    setUploading(true); setMsg(`Uploading ${files.length} reference${files.length === 1 ? "" : "s"}…`);
    let ok = 0, fail = 0;
    for (const file of files) {
      try {
        // References drive scene fidelity — keep more detail than product thumbs.
        const blob = await compressImageFile(file, 1600, 800 * 1024);
        const refId = `r${serverNowMs()}_${Math.random().toString(36).slice(2, 7)}`;
        const path = `aiStudio/styleKit/${template}/${refId}.jpg`;
        const sRef = storageRef(storage, path);
        await uploadBytes(sRef, blob, { contentType: "image/jpeg", cacheControl: "public, max-age=31536000, immutable" });
        const url = await getDownloadURL(sRef);
        await set(ref(database, `aiAssistant/styleKit/${template}/refs/${refId}`), {
          url, path, enabled: true, addedAt: serverNowMs(), by: user?.email || "",
          ...(template === "clothing" ? { kind: uploadKind } : {}),
        });
        ok++;
      } catch (err) { fail++; console.warn("styleKit ref upload failed:", err); }
    }
    setMsg(`Added ${ok} reference${ok === 1 ? "" : "s"}${fail ? ` · ${fail} failed` : ""}.`);
    setUploading(false);
  };
  const toggleRef = (r) => update(ref(database, `aiAssistant/styleKit/${template}/refs/${r.id}`), { enabled: r.enabled === false });
  const setRefKind = (r, kind) => update(ref(database, `aiAssistant/styleKit/${template}/refs/${r.id}`), { kind });
  const deleteRef = async (r) => {
    if (!window.confirm("Delete this reference image?")) return;
    try {
      await remove(ref(database, `aiAssistant/styleKit/${template}/refs/${r.id}`));
      if (r.path) deleteObject(storageRef(storage, r.path)).catch(() => {}); // best-effort; the RTDB entry is the source of truth
      setMsg("Reference deleted.");
    } catch (err) { setMsg(`Couldn't delete: ${err?.message || err}`); }
  };
  const savePrompt = async () => {
    const text = shownPrompt.trim();
    if (!text) { setMsg("Prompt can't be empty — use Reset to go back to the default."); return; }
    setSavingPrompt(true);
    try { await set(ref(database, `aiAssistant/styleKit/${template}/prompt`), text); setDraft(null); setMsg("Prompt saved — applies from the next generation."); }
    catch (err) { setMsg(`Couldn't save: ${err?.message || err}`); }
    finally { setSavingPrompt(false); }
  };
  const resetPrompt = async () => {
    if (!window.confirm("Reset this template's prompt to the built-in default?")) return;
    setSavingPrompt(true);
    try { await set(ref(database, `aiAssistant/styleKit/${template}/prompt`), null); setDraft(null); setMsg("Reset to the built-in default prompt."); }
    catch (err) { setMsg(`Couldn't reset: ${err?.message || err}`); }
    finally { setSavingPrompt(false); }
  };

  // Clothing tab: group by cosmetic garment-type label so the spread across
  // types is visible. Sneaker tab: one flat group.
  const groups = template === "clothing"
    ? STYLE_KIT_KINDS.map(k => ({ kind: k, items: refsArr.filter(r => (r.kind || "other") === k) })).filter(g => g.items.length)
    : [{ kind: null, items: refsArr }];

  const chip = (on, tint = "#4A7FFF") => ({
    background: on ? `${tint}38` : "rgba(255,255,255,.05)", color: on ? "#C9D9FF" : "rgba(255,255,255,.55)",
    border: "1px solid " + (on ? `${tint}90` : "rgba(255,255,255,.13)"),
    borderRadius: 999, padding: "7px 14px", fontSize: 12, fontWeight: 700, cursor: "pointer",
  });

  return (
    <div style={{ padding:"0 14px 30px" }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, padding:"6px 0 4px", flexWrap:"wrap" }}>
        <span style={{ fontSize:18, fontWeight:700, color:"#fff", letterSpacing:-.2 }}>Style Kit</span>
        <span style={{ background:"rgba(167,139,250,.14)", border:"1px solid rgba(167,139,250,.4)", color:"#C4B5FD", fontSize:11.5, fontWeight:600, padding:"3px 10px", borderRadius:999 }}>
          drives ⌗ House style
        </span>
      </div>
      <div style={{ fontSize:12, color:"rgba(255,255,255,.5)", marginBottom:12, lineHeight:1.5 }}>
        Upload 5–10 photos of the Marathon scene per template. Every house-style generation sends the product photo
        {" "}(+ box photo for sneakers) plus the first {STYLE_KIT_MAX_SENT} enabled references — changes apply from the
        next generation, no redeploy.
      </div>

      {/* Template tabs */}
      <div style={{ display:"flex", gap:8, marginBottom:14 }}>
        {STYLE_KIT_TEMPLATES.map(tp => {
          const on = template === tp.key;
          const count = Object.values((kit[tp.key] || {}).refs || {}).filter(r => r && r.enabled !== false).length;
          return (
            <button key={tp.key} onClick={() => setTemplate(tp.key)} title={tp.hint} style={chip(on, "#A78BFA")}>
              {tp.label} <span style={{ opacity:.65, fontWeight:600 }}>· {count} live</span>
            </button>
          );
        })}
      </div>

      {/* Upload row */}
      <div style={{ background:"rgba(8,11,20,.95)", border:"1px solid rgba(167,139,250,.3)", borderRadius:12, padding:12, marginBottom:14 }}>
        {template === "clothing" && (
          <div style={{ display:"flex", alignItems:"center", gap:6, flexWrap:"wrap", marginBottom:10 }}>
            <span style={{ fontSize:11, fontWeight:700, color:"rgba(255,255,255,.45)", marginRight:2 }}>LABEL UPLOADS AS</span>
            {STYLE_KIT_KINDS.map(k => (
              <button key={k} onClick={() => setUploadKind(k)} style={{ ...chip(uploadKind === k, "#A78BFA"), padding:"5px 11px", fontSize:11 }}>
                {k}
              </button>
            ))}
            <span style={{ fontSize:10, color:"rgba(255,255,255,.35)", width:"100%", marginTop:2 }}>
              Labels only organise this grid — the generator uses all enabled clothing refs regardless.
            </span>
          </div>
        )}
        <div style={{ display:"flex", alignItems:"center", gap:10, flexWrap:"wrap" }}>
          <input ref={fileRef} type="file" accept="image/*" multiple onChange={handleFiles} style={{ display:"none" }}/>
          <button onClick={() => fileRef.current?.click()} disabled={uploading}
                  style={{ background:"linear-gradient(180deg,#A78BFA,#7C5CE0)", color:"#fff", border:"none", borderRadius:9, padding:"9px 16px", fontSize:12.5, fontWeight:800, cursor: uploading ? "wait" : "pointer", opacity: uploading ? .6 : 1 }}>
            {uploading ? "Uploading…" : "＋ Add reference photos"}
          </button>
          <span style={{ fontSize:11, color:"rgba(255,255,255,.4)" }}>
            {enabled.length} enabled · first {Math.min(enabled.length, STYLE_KIT_MAX_SENT)} sent per generation
          </span>
        </div>
        {enabled.length === 0 && (
          <div style={{ marginTop:8, fontSize:11.5, color:"#FFC46B" }}>
            ⚠ No enabled references — house-style runs for this template will rely on the prompt alone until you add some.
          </div>
        )}
      </div>
      {msg && <div style={{ fontSize:11.5, color:"rgba(255,255,255,.6)", marginBottom:10 }}>{msg}</div>}

      {/* Reference grid (clothing: grouped by garment-type label) */}
      {groups.map(g => (
        <div key={g.kind || "all"} style={{ marginBottom:6 }}>
          {g.kind && (
            <div style={{ display:"flex", alignItems:"center", gap:8, margin:"10px 2px 7px" }}>
              <span style={{ fontSize:11, fontWeight:800, letterSpacing:.6, textTransform:"uppercase", color:"rgba(196,181,253,.85)" }}>{g.kind}</span>
              <span style={{ flex:1, height:1, background:"linear-gradient(90deg, rgba(167,139,250,.28), transparent)" }}/>
              <span style={{ fontSize:10.5, color:"rgba(255,255,255,.35)" }}>{g.items.length}</span>
            </div>
          )}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(130px, 1fr))", gap:10 }}>
            {g.items.map(r => {
              const on = r.enabled !== false;
              const sent = sentIds.has(r.id);
              return (
                <div key={r.id} style={{ borderRadius:12, overflow:"hidden", background:"rgba(255,255,255,.04)",
                                          border:"1px solid " + (sent ? "rgba(167,139,250,.55)" : "rgba(255,255,255,.09)") }}>
                  <div style={{ position:"relative" }}>
                    <img src={r.url} alt="" loading="lazy" decoding="async"
                         style={{ width:"100%", aspectRatio:"1", objectFit:"cover", display:"block", opacity: on ? 1 : .35, transition:"opacity .15s ease" }}/>
                    {sent && (
                      <span style={{ position:"absolute", top:6, left:6, background:"rgba(124,92,224,.85)", color:"#fff", fontSize:9, fontWeight:800, letterSpacing:.6, padding:"2px 7px", borderRadius:999 }}>SENT</span>
                    )}
                    {!on && (
                      <span style={{ position:"absolute", top:6, left:6, background:"rgba(10,12,20,.8)", color:"rgba(255,255,255,.6)", fontSize:9, fontWeight:800, letterSpacing:.6, padding:"2px 7px", borderRadius:999 }}>OFF</span>
                    )}
                    <button onClick={() => deleteRef(r)} aria-label="Delete reference" title="Delete reference"
                            style={{ position:"absolute", top:5, right:5, width:20, height:20, borderRadius:"50%", background:"rgba(10,12,20,.85)", color:"rgba(255,140,140,.9)", border:"1px solid rgba(255,255,255,.2)", fontSize:12, lineHeight:1, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", padding:0 }}>×</button>
                  </div>
                  <div style={{ display:"flex", alignItems:"center", gap:6, padding:"7px 8px" }}>
                    <button onClick={() => toggleRef(r)}
                            style={{ flex:1, background: on ? "rgba(74,202,122,.14)" : "rgba(255,255,255,.05)", color: on ? "#5FD894" : "rgba(255,255,255,.5)",
                                     border:"1px solid " + (on ? "rgba(74,202,122,.4)" : "rgba(255,255,255,.13)"), borderRadius:8, padding:"5px 0", fontSize:10.5, fontWeight:800, cursor:"pointer" }}>
                      {on ? "✓ Enabled" : "Off"}
                    </button>
                    {template === "clothing" && (
                      <select value={r.kind || "other"} onChange={e => setRefKind(r, e.target.value)} title="Garment-type label (organisation only)"
                              style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.14)", borderRadius:8, color:"rgba(255,255,255,.75)", padding:"4px 5px", fontSize:10.5, maxWidth:86 }}>
                        {STYLE_KIT_KINDS.map(k => <option key={k} value={k}>{k}</option>)}
                      </select>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}
      {refsArr.length === 0 && (
        <div style={{ textAlign:"center", color:"#555", padding:"2rem 1rem", fontSize:"0.9rem" }}>
          No {template} references yet — add the photos that define the Marathon look for this template.
        </div>
      )}

      {/* Locked prompt editor */}
      <div style={{ display:"flex", alignItems:"center", gap:8, margin:"18px 0 8px" }}>
        <span style={{ fontSize:13.5, fontWeight:800, color:"#fff" }}>Locked prompt · {template}</span>
        <span style={{ background: isCustomPrompt ? "rgba(167,139,250,.16)" : "rgba(255,255,255,.06)", border:"1px solid " + (isCustomPrompt ? "rgba(167,139,250,.45)" : "rgba(255,255,255,.13)"),
                       color: isCustomPrompt ? "#C4B5FD" : "rgba(255,255,255,.5)", fontSize:10.5, fontWeight:700, padding:"2px 9px", borderRadius:999 }}>
          {isCustomPrompt ? "custom" : "built-in default"}
        </span>
      </div>
      <textarea value={shownPrompt} onChange={e => setDraft(e.target.value)} rows={9} spellCheck={false}
                style={{ width:"100%", boxSizing:"border-box", background:"rgba(255,255,255,.05)", border:"1px solid " + (promptDirty ? "rgba(167,139,250,.55)" : "rgba(255,255,255,.13)"),
                         borderRadius:12, color:"rgba(255,255,255,.85)", padding:"12px 13px", fontSize:12, lineHeight:1.55, resize:"vertical", fontFamily:"inherit" }}/>
      <div style={{ display:"flex", gap:8, marginTop:8 }}>
        <button onClick={savePrompt} disabled={savingPrompt || !promptDirty}
                style={{ background: promptDirty ? "linear-gradient(180deg,#A78BFA,#7C5CE0)" : "rgba(255,255,255,.06)", color: promptDirty ? "#fff" : "rgba(255,255,255,.4)",
                         border: promptDirty ? "none" : "1px solid rgba(255,255,255,.12)", borderRadius:9, padding:"9px 18px", fontSize:12.5, fontWeight:800, cursor: (savingPrompt || !promptDirty) ? "default" : "pointer" }}>
          {savingPrompt ? "Saving…" : "Save prompt"}
        </button>
        {(isCustomPrompt || draft !== null) && (
          <button onClick={resetPrompt} disabled={savingPrompt}
                  style={{ background:"transparent", border:"1px solid rgba(255,255,255,.14)", color:"rgba(255,255,255,.6)", borderRadius:9, padding:"9px 14px", fontSize:12, fontWeight:700, cursor:"pointer" }}>
            Reset to default
          </button>
        )}
      </div>
      <div style={{ fontSize:10.5, color:"rgba(255,255,255,.35)", marginTop:8, lineHeight:1.5 }}>
        The prompt locks scene rules (product identity, layout, no reference-product leakage); the reference photos are
        the authority on the exact backdrop, lighting and framing. Product name + any regenerate fix-note are added
        automatically per product.
      </div>
    </div>
  );
}

const NAME_HIGH_CONFIDENCE = 0.85;
const confColor = (c) => (c >= NAME_HIGH_CONFIDENCE ? "#4ACA7A" : c >= 0.6 ? "#F59E0B" : "#FF6B6B");

// ── REVIEW UNCATEGORIZED ───────────────────────────────────────────────────────
// Admin screen to sort the "Clothing — Uncategorized" stragglers the classifier
// couldn't type (unbranded supplier codes / branded items with no type word). Each
// ── ORGANISER: bulk-sort the catalog into real categories ──────────────────────
// Work-queue for products the auto-classifier left as UNCATEGORIZED. Enhancements
// over the old one-at-a-time picker: multi-select + select-all-matching, one-shot
// BULK assign gated behind a before/after confirm table (never mass-write
// silently), single-action UNDO, and a progress bar. Writes ONLY subcategory +
// category (top-level) — NEVER productType, which is the behaviour cliff (refill /
// display-checks key off productType, so leaving it untouched keeps every product's
// refill + display-check behaviour exactly as it was). Reuses the existing
// `products` prop — no new RTDB listeners.
function AdminReviewCategoriesTab({ products = [] }) {
  const [q, setQ] = useState("");
  const [sel, setSel] = useState(() => new Set()); // selected product ids
  const [bulkSub, setBulkSub] = useState("");       // chosen target subcategory for the bulk assign
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [savingId, setSavingId] = useState(null);   // per-row single assign
  const [undo, setUndo] = useState(null);           // { items:[{id,prevSub,prevCat}], sub } — last action, reversible
  const [baseline, setBaseline] = useState(null);   // initial backlog size for the progress bar

  const SELECT_CAP = 2000; // safety cap on select-all (backlog is a few hundred; never mass-select the whole catalog)

  const subToTop = useMemo(() => {
    const m = {};
    for (const [top, subs] of Object.entries(CATEGORY_TREE)) for (const s of subs) m[s] = top;
    return m;
  }, []);

  // Full backlog (unfiltered) — drives progress + the confirm counts. Catches
  // both the "Clothing — Uncategorized" subcategory AND products with no real
  // top-level category at all, so a category-less product can actually be sorted
  // here rather than silently never appearing.
  const allUncat = useMemo(
    () => (products || []).filter(p => p && p.id && (p.subcategory === UNCATEGORIZED || topCategory(p) === UNCATEGORIZED_TOP)),
    [products]);
  const remaining = allUncat.length;

  // Capture the starting backlog once (first time data is present) so the progress
  // denominator stays stable as the list empties. Bump it up if the backlog ever
  // grows past the baseline (new imports) so "organised" can't go negative.
  useEffect(() => {
    // Re-baseline to null once the backlog fully clears, so a later import starts
    // a fresh "organised N of M" rather than inheriting the previous run's total.
    setBaseline(b => (remaining > 0 ? (b == null ? remaining : Math.max(b, remaining)) : null));
  }, [remaining]);

  // Prune ids that have left the backlog (e.g. sorted by another admin via live
  // RTDB) so sel only ever holds in-backlog products — keeps every selection
  // indicator (toolbar visibility, Clear count) consistent with what will be
  // assigned. Returns the same Set when nothing changed to avoid a render loop.
  useEffect(() => {
    const valid = new Set(allUncat.map(p => p.id));
    setSel(s => {
      let changed = false; const n = new Set();
      for (const id of s) { if (valid.has(id)) n.add(id); else changed = true; }
      return changed ? n : s;
    });
  }, [allUncat]);
  const organised = baseline == null ? 0 : Math.max(0, baseline - remaining);
  const pct = baseline ? Math.round((organised / baseline) * 100) : 0;

  // Search-filtered, name-sorted view.
  const list = useMemo(() => {
    const query = q.trim().toLowerCase();
    const filtered = query ? allUncat.filter(p => (p.name || "").toLowerCase().includes(query)) : allUncat;
    return [...filtered].sort((a, b) => (a.name || "").localeCompare(b.name || ""));
  }, [allUncat, q]);

  // Count of products currently sitting in a given subcategory (for before/after).
  const subCount = (sub) => (products || []).filter(p => p && p.subcategory === sub).length;

  const toggle = (id) => setSel(s => { const n = new Set(s); n.has(id) ? n.delete(id) : n.add(id); return n; });
  const selectAllMatching = () => setSel(s => {
    const n = new Set(s);
    for (const p of list) { if (n.size >= SELECT_CAP) break; n.add(p.id); }
    return n;
  });
  const clearSel = () => setSel(new Set());
  // Derive from the FULL backlog (not the search-filtered list) so the selection —
  // and what actually gets written — never diverges from the toolbar count when
  // the search box is changed after selecting. Products that leave the backlog
  // (already sorted elsewhere) simply drop out, which is correct.
  const selectedList = useMemo(() => allUncat.filter(p => sel.has(p.id)), [allUncat, sel]);

  // If a live update empties the selection while the confirm dialog is open, close
  // it — there is nothing left to assign. (Declared AFTER selectedList to avoid a
  // temporal-dead-zone reference.)
  useEffect(() => {
    if (confirmOpen && selectedList.length === 0) setConfirmOpen(false);
  }, [confirmOpen, selectedList.length]);

  // Write subcategory + category for a set of products in ONE multi-path update,
  // recording prior values so the action can be undone.
  const applyAssign = async (items, sub) => {
    const top = subToTop[sub];
    if (!items.length || !sub || sub === UNCATEGORIZED || !top) return;
    const updates = {};
    const undoItems = [];
    for (const p of items) {
      updates[`products/${p.id}/subcategory`] = sub;
      updates[`products/${p.id}/category`] = top;
      undoItems.push({ id: p.id, prevSub: p.subcategory ?? null, prevCat: p.category ?? null });
    }
    setBusy(true);
    try {
      await update(ref(database), updates);
      setUndo({ items: undoItems, sub });
      // Deselect only what we just assigned — so a per-row quick assign doesn't
      // wipe an in-progress multi-selection (bulk assigns everything selected, so
      // this empties the set for that path anyway).
      setSel(s => { const n = new Set(s); for (const it of undoItems) n.delete(it.id); return n; });
      setConfirmOpen(false);
    } catch (e) { alert("Save failed: " + (e?.message || e)); }
    finally { setBusy(false); }
  };

  // Per-row single assign (instant, still reversible via undo).
  const assignOne = async (p, sub) => {
    if (!sub) return;
    setSavingId(p.id);
    try { await applyAssign([p], sub); }
    finally { setSavingId(null); }
  };

  const doUndo = async () => {
    if (!undo) return;
    const updates = {};
    for (const it of undo.items) {
      updates[`products/${it.id}/subcategory`] = it.prevSub;
      updates[`products/${it.id}/category`] = it.prevCat;
    }
    setBusy(true);
    try { await update(ref(database), updates); setUndo(null); }
    catch (e) { alert("Undo failed: " + (e?.message || e)); }
    finally { setBusy(false); }
  };

  const catOptions = Object.entries(CATEGORY_TREE).map(([top, subs]) => (
    <optgroup key={top} label={top}>
      {subs.filter(s => s !== UNCATEGORIZED).map(s => <option key={s} value={s}>{s}</option>)}
    </optgroup>
  ));

  return (
    <div style={{ padding:"0 14px 30px" }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, padding:"6px 0 8px" }}>
        <span style={{ fontSize:18, fontWeight:700, color:"#fff" }}>Sort Uncategorized</span>
        <span style={{ background:"rgba(245,158,11,.15)", border:"1px solid rgba(245,158,11,.35)", color:"#F59E0B", fontSize:12, fontWeight:700, padding:"3px 10px", borderRadius:12 }}>{remaining} to sort</span>
      </div>

      {/* Progress — organised N of the starting backlog */}
      {baseline > 0 && (
        <div style={{ marginBottom:12 }}>
          <div style={{ fontSize:12, color:"rgba(255,255,255,.6)", marginBottom:4 }}>Organised <b style={{ color:"#4ACA7A" }}>{organised}</b> of {baseline}</div>
          <div style={{ height:6, borderRadius:4, background:"rgba(255,255,255,.08)", overflow:"hidden" }}>
            <div style={{ width:`${pct}%`, height:"100%", background:"#4ACA7A", transition:"width .3s" }}/>
          </div>
        </div>
      )}

      <div style={{ fontSize:12, color:"rgba(255,255,255,.45)", marginBottom:10 }}>
        Items the auto-classifier couldn’t type. Tick several (or “Select all matching”), pick one category, and assign in a single confirmed step. Only the category label changes — product type is untouched, so refill and display checks are unaffected.
      </div>

      <input value={q} onChange={e => setQ(e.target.value)} placeholder="Search these items… (e.g. “bag”)"
             style={{ width:"100%", boxSizing:"border-box", background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", borderRadius:9, color:"#fff", padding:"9px 12px", fontSize:13, marginBottom:10 }}/>

      {/* Select-all-matching row */}
      {list.length > 0 && (
        <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:10, flexWrap:"wrap" }}>
          <button onClick={selectAllMatching}
                  style={{ background:"rgba(74,127,255,.15)", border:"1px solid rgba(74,127,255,.45)", color:"#9DBCFF", borderRadius:8, padding:"6px 10px", fontSize:12, fontWeight:700, cursor:"pointer" }}>
            Select all matching ({Math.min(list.length, SELECT_CAP)})
          </button>
          {sel.size > 0 && (
            <button onClick={clearSel} style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", color:"rgba(255,255,255,.65)", borderRadius:8, padding:"6px 10px", fontSize:12, cursor:"pointer" }}>Clear ({sel.size})</button>
          )}
        </div>
      )}

      {/* Bulk assign toolbar — visible once something is selected */}
      {sel.size > 0 && (
        <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:12, padding:"10px 12px", borderRadius:10, background:"rgba(74,127,255,.08)", border:"1px solid rgba(74,127,255,.3)", flexWrap:"wrap" }}>
          <span style={{ fontSize:13, fontWeight:700, color:"#fff" }}>{selectedList.length} selected →</span>
          <select value={bulkSub} onChange={e => setBulkSub(e.target.value)}
                  style={{ background:"rgba(255,255,255,.08)", border:"1px solid rgba(255,255,255,.2)", color:"#fff", borderRadius:8, padding:"7px 8px", fontSize:12, flex:"1 1 160px", minWidth:140 }}>
            <option value="" disabled>Assign to category…</option>
            {catOptions}
          </select>
          <button disabled={!bulkSub || busy || selectedList.length === 0} onClick={() => setConfirmOpen(true)}
                  style={{ background: bulkSub ? "#4A7FFF" : "rgba(255,255,255,.08)", color:"#fff", border:"none", borderRadius:8, padding:"8px 14px", fontSize:12, fontWeight:700, cursor: bulkSub && !busy ? "pointer" : "default", opacity: bulkSub && !busy ? 1 : .5 }}>
            Review &amp; assign
          </button>
        </div>
      )}

      {/* Undo banner — last action reversible */}
      {undo && (
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10, marginBottom:12, padding:"9px 12px", borderRadius:10, background:"rgba(74,202,122,.1)", border:"1px solid rgba(74,202,122,.3)" }}>
          <span style={{ fontSize:12.5, color:"#B7F0CD" }}>Moved {undo.items.length} to <b>{undo.sub}</b>.</span>
          <div style={{ display:"flex", gap:8 }}>
            <button disabled={busy} onClick={doUndo} style={{ background:"rgba(255,255,255,.1)", border:"1px solid rgba(255,255,255,.2)", color:"#fff", borderRadius:7, padding:"5px 12px", fontSize:12, fontWeight:700, cursor: busy ? "default":"pointer" }}>Undo</button>
            <button onClick={() => setUndo(null)} style={{ background:"transparent", border:"none", color:"rgba(255,255,255,.5)", fontSize:16, cursor:"pointer", lineHeight:1 }}>×</button>
          </div>
        </div>
      )}

      {list.length === 0 && <div style={{ color:"#4ACA7A", fontSize:13, padding:"18px 4px", textAlign:"center" }}>{q ? "No matches." : "All sorted 🎉"}</div>}

      <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
        {list.map(p => {
          const checked = sel.has(p.id);
          return (
          <div key={p.id} onClick={() => toggle(p.id)}
               style={{ display:"flex", alignItems:"center", gap:10, padding:"8px 10px", borderRadius:10, cursor:"pointer",
                        background: checked ? "rgba(74,127,255,.12)" : "rgba(255,255,255,.03)",
                        border: checked ? "1px solid rgba(74,127,255,.5)" : "1px solid rgba(255,255,255,.07)" }}>
            <input type="checkbox" checked={checked} readOnly
                   style={{ width:17, height:17, accentColor:"#4A7FFF", flexShrink:0, cursor:"pointer" }}/>
            <img src={p.photoUrl || ""} alt="" loading="lazy"
                 style={{ width:40, height:40, borderRadius:7, objectFit:"cover", background:"rgba(255,255,255,.08)", flexShrink:0 }}/>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:13, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{p.name}</div>
              <div style={{ fontSize:11, color:"rgba(255,255,255,.4)" }}>{p.brand ? p.brand + " · " : ""}{Array.isArray(p.sizes) ? p.sizes.slice(0,6).join("/") : ""}</div>
            </div>
            {/* Per-row quick single assign (instant, still undoable) */}
            <select disabled={savingId === p.id} value="" onClick={e => e.stopPropagation()} onChange={e => assignOne(p, e.target.value)}
                    style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", color:"#fff", padding:"7px 8px", fontSize:12, borderRadius:8, maxWidth:132, opacity: savingId === p.id ? .5 : 1 }}>
              <option value="" disabled>Move to…</option>
              {catOptions}
            </select>
          </div>
          );
        })}
      </div>

      {/* Before/after confirm — mandatory before any bulk write */}
      {confirmOpen && bulkSub && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,.75)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:1000, padding:16 }}
             onClick={() => !busy && setConfirmOpen(false)}>
          <div onClick={e => e.stopPropagation()}
               style={{ background:"#111", border:"1px solid rgba(255,255,255,.15)", borderRadius:14, padding:20, maxWidth:440, width:"100%", maxHeight:"85vh", overflow:"auto" }}>
            <div style={{ fontSize:16, fontWeight:700, color:"#fff", marginBottom:4 }}>Confirm bulk assign</div>
            <div style={{ fontSize:13, color:"rgba(255,255,255,.6)", marginBottom:14 }}>
              Move <b style={{ color:"#fff" }}>{selectedList.length}</b> product{selectedList.length===1?"":"s"} to <b style={{ color:"#9DBCFF" }}>{bulkSub}</b> <span style={{ color:"rgba(255,255,255,.4)" }}>(under {subToTop[bulkSub]})</span>.
            </div>

            {/* Before / after counts */}
            <div style={{ border:"1px solid rgba(255,255,255,.1)", borderRadius:10, overflow:"hidden", marginBottom:14 }}>
              <div style={{ display:"grid", gridTemplateColumns:"1fr auto auto", fontSize:12, fontWeight:700, color:"rgba(255,255,255,.5)", padding:"8px 12px", borderBottom:"1px solid rgba(255,255,255,.08)" }}>
                <span>Category</span><span style={{ textAlign:"right", width:64 }}>Before</span><span style={{ textAlign:"right", width:64 }}>After</span>
              </div>
              {[
                ["Uncategorized", remaining, remaining - selectedList.length],
                [bulkSub, subCount(bulkSub), subCount(bulkSub) + selectedList.length],
              ].map(([label, before, after]) => (
                <div key={label} style={{ display:"grid", gridTemplateColumns:"1fr auto auto", fontSize:13, color:"#fff", padding:"8px 12px" }}>
                  <span>{label}</span>
                  <span style={{ textAlign:"right", width:64, color:"rgba(255,255,255,.6)" }}>{before}</span>
                  <span style={{ textAlign:"right", width:64, fontWeight:700, color:"#4ACA7A" }}>{after}</span>
                </div>
              ))}
            </div>

            {/* Side-effect statement (per governance) */}
            <div style={{ fontSize:11.5, color:"rgba(255,255,255,.45)", background:"rgba(255,255,255,.03)", borderRadius:8, padding:"8px 10px", marginBottom:14 }}>
              Product <b>type</b> is unchanged — auto-refill and display checks follow product type, so they are <b>unaffected</b>. Only the category label changes. Reversible with Undo.
            </div>

            {/* Sample of what moves */}
            <div style={{ fontSize:11, color:"rgba(255,255,255,.5)", marginBottom:14 }}>
              {selectedList.slice(0,6).map(p => p.name).join(" · ")}{selectedList.length > 6 ? ` · +${selectedList.length - 6} more` : ""}
            </div>

            <div style={{ display:"flex", gap:8 }}>
              <button disabled={busy || selectedList.length === 0} onClick={() => applyAssign(selectedList, bulkSub)}
                      style={{ flex:1, background:"#4A7FFF", color:"#fff", border:"none", borderRadius:8, padding:"10px", fontSize:13, fontWeight:700, cursor: (busy||!selectedList.length)?"default":"pointer", opacity: (busy||!selectedList.length)?.6:1 }}>
                {busy ? "Assigning…" : `Assign ${selectedList.length}`}
              </button>
              <button disabled={busy} onClick={() => setConfirmOpen(false)}
                      style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", color:"rgba(255,255,255,.6)", borderRadius:8, padding:"10px 14px", fontSize:13, fontWeight:600, cursor:"pointer" }}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { needsCost, needsRetail, needsAny, typeOf, createdAt, updatedAt, buildUpdates, validatePrices } from "./utils/missingPrices";

// Missing-Prices category chips: All + the real top-levels (so a new category
// appears automatically) + an Uncategorized catch-all. Keys match typeOf()
// outputs. Module-scope (pure, derived from constants) so it has a stable
// identity across renders and can't become a stale-closure trap.
const MISSING_PRICE_FILTERS = [
  ["all", "All"],
  ...TOP_CATEGORIES.map((c) => [c, c]),
  [UNCATEGORIZED_TOP, "Uncategorized"],
];

function MissingPricesTab({ products = [] }) {
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("newest"); // "newest" | "oldest"
  const [filter, setFilter] = useState("all"); // "all" | a TOP_CATEGORIES value | "Uncategorized"
  const [page, setPage] = useState(1);
  const [editProduct, setEditProduct] = useState(null); // product being priced
  const [costDraft, setCostDraft] = useState("");
  const [retailDraft, setRetailDraft] = useState("");
  const [saving, setSaving] = useState(false);
  // Photo expand toggle — holds { url, name } of the product photo being viewed
  // large, or null. Tapping the small photo opens it; tapping the large photo
  // (or ✕ / backdrop) closes it again.
  const [photoView, setPhotoView] = useState(null);
  const PAGE_SIZE = 50;

  const CATEGORY_FILTERS = MISSING_PRICE_FILTERS;

  const list = useMemo(() => {
    let items = (products || []).filter(p => p && p.id && needsAny(p));
    if (filter !== "all") items = items.filter(p => typeOf(p) === filter);
    const q = search.trim().toLowerCase();
    if (q) {
      items = items.filter(p =>
        (p.name || "").toLowerCase().includes(q) ||
        (p.sku || "").toLowerCase().includes(q) ||
        (p.barcode || "").toLowerCase().includes(q)
      );
    }
    items.sort((a, b) => sort === "newest" ? createdAt(b) - createdAt(a) : createdAt(a) - createdAt(b));
    return items;
  }, [products, filter, search, sort]);

  const totalPages = Math.max(1, Math.ceil(list.length / PAGE_SIZE));
  const pageItems = list.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  // Category summary counts (across ALL missing-price products, before filter)
  const summary = useMemo(() => {
    const items = (products || []).filter(p => p && p.id && needsAny(p));
    const counts = { all: items.length };
    for (const [k] of CATEGORY_FILTERS.slice(1)) counts[k] = items.filter(p => typeOf(p) === k).length;
    return counts;
  }, [products]);

  const fmtDate = (ts) => {
    if (!ts) return "—";
    const d = new Date(ts);
    return d.toLocaleDateString([], { year: "numeric", month: "short", day: "numeric" });
  };

  const openEdit = (p) => {
    setEditProduct(p);
    setCostDraft(needsCost(p) ? "" : String(p.stockPrice));
    setRetailDraft(needsRetail(p) ? "" : String(p.retailPrice));
  };

  const savePrice = async () => {
    if (saving) return;
    const validation = validatePrices(editProduct, costDraft, retailDraft);
    if (!validation.ok) {
      if (validation.needsConfirm) {
        if (!window.confirm(validation.error)) return;
      } else {
        alert(validation.error);
        return;
      }
    }

    setSaving(true);
    try {
      const updates = buildUpdates(editProduct, costDraft, retailDraft);
      await update(ref(database, `products/${editProduct.id}`), updates);
      // Open the next missing-price product for continuous entry.
      // Use openEdit so drafts are derived from the next product (preserves
      // the retail<cost confirmation for single-missing-price products).
      const idx = list.findIndex(p => p.id === editProduct.id);
      let next = idx >= 0 ? list[idx + 1] || null : null;
      // Skip products that no longer need any price (stale snapshot).
      let nextIdx = idx + 1;
      while (next && !needsAny(next)) {
        nextIdx++;
        next = list[nextIdx] || null;
      }
      if (next) {
        openEdit(next);
      } else {
        setEditProduct(null);
        setCostDraft("");
        setRetailDraft("");
        setPage(p => Math.min(p, totalPages));
      }
    } catch (e) {
      alert("Save failed: " + (e?.message || e));
    } finally {
      setSaving(false);
    }
  };

  return (
    <div style={{ padding: "0 14px 30px" }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "6px 0 12px" }}>
        <span style={{ fontSize: 18, fontWeight: 700, color: "#fff" }}>Missing Prices</span>
        <span style={{ background: "rgba(251,191,36,.15)", border: "1px solid rgba(251,191,36,.35)", color: "#FBBF24", fontSize: 12, fontWeight: 700, padding: "3px 10px", borderRadius: 12 }}>{list.length}</span>
      </div>
      <div style={{ fontSize: 12, color: "rgba(255,255,255,.45)", marginBottom: 12 }}>
        Products without a selling price. Assign prices immediately — saving opens the next one automatically.
      </div>

      {/* Category summary */}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
        {CATEGORY_FILTERS.map(([k, l]) => (
          <button key={k} onClick={() => { setFilter(k); setPage(1); }}
            style={{ background: filter === k ? "rgba(74,127,255,.2)" : "rgba(255,255,255,.04)", border: filter === k ? "1px solid rgba(74,127,255,.5)" : "1px solid rgba(255,255,255,.1)", borderRadius: 8, color: filter === k ? "#9DBCFF" : "rgba(255,255,255,.6)", padding: "6px 10px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>
            {l} <span style={{ color: filter === k ? "#fff" : "#FBBF24", fontWeight: 800 }}>{summary[k] ?? 0}</span>
          </button>
        ))}
      </div>

      {/* Controls */}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
        <select value={sort} onChange={e => { setSort(e.target.value); setPage(1); }}
          style={{ background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.15)", borderRadius: 8, color: "#fff", padding: "8px 10px", fontSize: 12, cursor: "pointer" }}>
          <option value="newest">Newest First</option>
          <option value="oldest">Oldest First</option>
        </select>
        <input value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} placeholder="Search name, SKU, barcode…"
          style={{ flex: 1, minWidth: 140, background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.15)", borderRadius: 8, color: "#fff", padding: "8px 10px", fontSize: 12 }} />
      </div>

      {/* Empty state */}
      {list.length === 0 && (
        <div style={{ textAlign: "center", padding: "60px 20px", color: "#4ACA7A", fontSize: 15, fontWeight: 600 }}>
          ✅ All products have prices.
        </div>
      )}

      {/* Table */}
      {list.length > 0 && (
        <>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {pageItems.map(p => (
              <div key={p.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 10px", borderRadius: 10, background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.07)" }}>
                <img src={p.photoUrl || ""} alt="" loading="lazy"
                  style={{ width: 44, height: 44, borderRadius: 8, objectFit: "cover", background: "rgba(255,255,255,.08)", flexShrink: 0 }} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 13, color: "#fff", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.name}</div>
                  <div style={{ fontSize: 11, color: "rgba(255,255,255,.4)", marginTop: 2 }}>
                    {p.brand ? `${p.brand} · ` : ""}{p.category || "—"} · SKU {p.sku || "—"}
                  </div>
                  <div style={{ fontSize: 10, color: "rgba(255,255,255,.3)", marginTop: 2 }}>
                    Created {fmtDate(createdAt(p))} · Updated {fmtDate(updatedAt(p))}
                  </div>
                </div>
                <div style={{ textAlign: "right", flexShrink: 0 }}>
                  <div style={{ fontSize: 12, color: "#FBBF24", fontWeight: 700, marginBottom: 4 }}>
                    {needsCost(p) && needsRetail(p) ? "No Cost/Retail" : needsCost(p) ? "No Cost" : "No Retail"}
                  </div>
                  <button onClick={() => openEdit(p)}
                    style={{ background: "#4A7FFF", color: "#fff", border: "none", borderRadius: 8, padding: "6px 12px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>
                    Edit Price
                  </button>
                </div>
              </div>
            ))}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 10, marginTop: 16 }}>
              <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
                style={{ background: page === 1 ? "rgba(255,255,255,.03)" : "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.15)", borderRadius: 8, color: page === 1 ? "rgba(255,255,255,.3)" : "#fff", padding: "7px 12px", fontSize: 12, cursor: page === 1 ? "default" : "pointer" }}>
                ← Prev
              </button>
              <span style={{ fontSize: 12, color: "rgba(255,255,255,.5)" }}>Page {page} of {totalPages} · {list.length} products</span>
              <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}
                style={{ background: page === totalPages ? "rgba(255,255,255,.03)" : "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.15)", borderRadius: 8, color: page === totalPages ? "rgba(255,255,255,.3)" : "#fff", padding: "7px 12px", fontSize: 12, cursor: page === totalPages ? "default" : "pointer" }}>
                Next →
              </button>
            </div>
          )}
        </>
      )}

      {/* Quick price-edit modal */}
      {editProduct && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.75)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: 16 }}
          onClick={() => setEditProduct(null)}>
          <div style={{ background: "#111", border: "1px solid rgba(255,255,255,.15)", borderRadius: 14, padding: 20, maxWidth: 380, width: "100%" }}
            onClick={e => e.stopPropagation()}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
              {/* Tap the photo to expand it; tap the expanded photo again to close. */}
              <img src={editProduct.photoUrl || ""} alt=""
                onClick={() => editProduct.photoUrl && setPhotoView({ url: editProduct.photoUrl, name: editProduct.name })}
                title={editProduct.photoUrl ? "Tap to expand" : ""}
                style={{ width: 48, height: 48, borderRadius: 8, objectFit: "cover", background: "rgba(255,255,255,.08)", cursor: editProduct.photoUrl ? "zoom-in" : "default", flexShrink: 0 }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: "#fff", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{editProduct.name}</div>
                <div style={{ fontSize: 11, color: "rgba(255,255,255,.4)" }}>{editProduct.brand ? `${editProduct.brand} · ` : ""}{editProduct.category || "—"}</div>
              </div>
            </div>
            {/* Pricing section — mirrors the product editor's "Pricing (ZAR)"
                block ("Stock Price" / "Retail Price" labels) but shows only the
                field(s) this product is actually missing, so Save & Next stays
                a fast single-field entry when only one price is absent. */}
            <div style={{ fontSize: 12, fontWeight: 600, color: "rgba(255,255,255,.5)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 8 }}>Pricing (ZAR)</div>
            <div style={{ display: "flex", background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.07)", borderRadius: 10, overflow: "hidden", marginBottom: 14 }}>
              {needsCost(editProduct) && (
                <div style={{ flex: 1, padding: "12px 14px", borderRight: needsRetail(editProduct) ? "1px solid rgba(255,255,255,.06)" : "none" }}>
                  <div style={{ fontSize: 11, color: "rgba(255,255,255,.45)", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 4 }}>Stock Price</div>
                  <input type="number" inputMode="decimal" min="0" step="0.01" placeholder="0.00" value={costDraft}
                    onChange={e => setCostDraft(e.target.value)}
                    onKeyDown={e => { if (e.key === "Enter") savePrice(); }}
                    autoFocus={needsCost(editProduct)}
                    style={{ width: "100%", background: "transparent", border: "none", outline: "none", color: "#fff", padding: 0, fontSize: 17, fontWeight: 500, fontFamily: "inherit", boxSizing: "border-box" }} />
                </div>
              )}
              {needsRetail(editProduct) && (
                <div style={{ flex: 1, padding: "12px 14px" }}>
                  <div style={{ fontSize: 11, color: "rgba(255,255,255,.45)", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 4 }}>Retail Price</div>
                  <input type="number" inputMode="decimal" min="0" step="0.01" placeholder="0.00" value={retailDraft}
                    onChange={e => setRetailDraft(e.target.value)}
                    onKeyDown={e => { if (e.key === "Enter") savePrice(); }}
                    autoFocus={!needsCost(editProduct)}
                    style={{ width: "100%", background: "transparent", border: "none", outline: "none", color: "#fff", padding: 0, fontSize: 17, fontWeight: 500, fontFamily: "inherit", boxSizing: "border-box" }} />
                </div>
              )}
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={savePrice} disabled={saving}
                style={{ flex: 1, background: "#4A7FFF", color: "#fff", border: "none", borderRadius: 8, padding: "10px", fontSize: 13, fontWeight: 700, cursor: saving ? "default" : "pointer", opacity: saving ? 0.6 : 1 }}>
                {saving ? "Saving…" : "Save & Next"}
              </button>
              <button onClick={() => setEditProduct(null)}
                style={{ background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.15)", borderRadius: 8, color: "rgba(255,255,255,.6)", padding: "10px 14px", fontSize: 13, fontWeight: 600, cursor: "pointer" }}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Expanded photo overlay — opened by tapping the small photo in the Edit
          Price card. Tapping the expanded photo (or the backdrop / ✕) closes it,
          so the same photo tap toggles it back. Above the modal (zIndex 1100). */}
      {photoView && (
        <div onClick={() => setPhotoView(null)}
          style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.9)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", zIndex: 1100, padding: 20 }}>
          <button onClick={() => setPhotoView(null)} aria-label="Close"
            style={{ position: "absolute", top: 16, right: 16, width: 40, height: 40, borderRadius: 20, background: "rgba(255,255,255,.12)", border: "1px solid rgba(255,255,255,.2)", color: "#fff", fontSize: 20, lineHeight: 1, cursor: "pointer" }}>×</button>
          <img src={photoView.url} alt={photoView.name || ""}
            title="Tap to close"
            style={{ maxWidth: "100%", maxHeight: "82vh", objectFit: "contain", borderRadius: 10, boxShadow: "0 20px 60px -20px rgba(0,0,0,.9)", cursor: "zoom-out" }} />
          {photoView.name && (
            <div style={{ marginTop: 14, color: "#fff", fontSize: 14, fontWeight: 600, textAlign: "center", maxWidth: 520 }}>{photoView.name}</div>
          )}
        </div>
      )}
    </div>
  );
}

function AdminReviewNamesTab({ products }) {
  const proposals = useNameProposals();
  const [edits, setEdits]   = useState({});     // id → edited name (overrides the suggestion)
  const [busyId, setBusyId] = useState(null);
  const [bulkBusy, setBulkBusy] = useState(false);
  const [runN, setRunN]     = useState(20);
  const [runBusy, setRunBusy] = useState(false);
  const [runMsg, setRunMsg] = useState(null);

  // Pending rows (undecided), highest-confidence first.
  const pending = useMemo(() => Object.entries(proposals || {})
    .filter(([, v]) => v && v.status !== "approved" && v.status !== "rejected")
    .map(([id, v]) => ({ id, ...v }))
    .sort((a, b) => (b.confidence || 0) - (a.confidence || 0)), [proposals]);
  const decidedCount = useMemo(() => Object.values(proposals || {}).filter(v => v && (v.status === "approved" || v.status === "rejected")).length, [proposals]);
  const highCount = pending.filter(r => (r.confidence || 0) >= NAME_HIGH_CONFIDENCE).length;

  const finalName = (row) => (edits[row.id] ?? row.suggested ?? "").trim();

  const approve = async (row) => {
    const name = finalName(row);
    if (!name) return false;
    setBusyId(row.id);
    try {
      await updateProductName(row.id, name);
      await update(ref(database, `aiAssistant/nameProposals/${row.id}`), { status: "approved", appliedName: name, decidedAt: serverNowMs() });
      return true;
    } catch (e) { setRunMsg(`Approve failed for “${row.current || row.id}”: ${e?.message || e}`); return false; }
    finally { setBusyId(null); }
  };
  const reject = async (row) => {
    setBusyId(row.id);
    try { await update(ref(database, `aiAssistant/nameProposals/${row.id}`), { status: "rejected", decidedAt: serverNowMs() }); }
    catch (e) { setRunMsg(`Reject failed for “${row.current || row.id}”: ${e?.message || e}`); }
    finally { setBusyId(null); }
  };
  const approveAllHigh = async () => {
    setBulkBusy(true);
    let okN = 0, failN = 0;
    try { for (const r of pending.filter(r => (r.confidence || 0) >= NAME_HIGH_CONFIDENCE)) { (await approve(r)) ? okN++ : failN++; } }
    finally { setBulkBusy(false); setRunMsg(`Approved ${okN}${failN ? `, ${failN} failed (see above)` : ""}.`); }
  };
  const approveAll = async () => {
    if (!pending.length) return;
    if (!window.confirm(`Approve ALL ${pending.length} suggestions? This renames those products to the suggested names.`)) return;
    setBulkBusy(true);
    let okN = 0, failN = 0;
    try { for (const r of pending) { (await approve(r)) ? okN++ : failN++; } }
    finally { setBulkBusy(false); setRunMsg(`Approved ${okN}${failN ? `, ${failN} failed (see above)` : ""}.`); }
  };
  const runAI = async () => {
    setRunBusy(true); setRunMsg(`Running AI on the next ${runN} products…`);
    try {
      const res = await httpsCallable(functions, "cleanProductNames")({ limit: Number(runN) || 20 });
      const d = res?.data || {};
      setRunMsg(`Done — ${d.processed} suggested, ${d.failed} failed (≈ $${Number(d.totalCostUSD || 0).toFixed(4)}).`);
    } catch (e) {
      const m = String(e?.message || e);
      setRunMsg(`Couldn't run: ${m}${m.toLowerCase().includes("not-found") || m.toLowerCase().includes("internal") ? " — is cleanProductNames deployed?" : ""}`);
    } finally { setRunBusy(false); }
  };

  return (
    <div style={{ padding:"0 14px 30px" }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, padding:"6px 0 12px" }}>
        <span style={{ fontSize:18, fontWeight:700, color:"#fff" }}>AI Name Cleanup</span>
        <span style={{ background:"rgba(74,202,122,.15)", border:"1px solid rgba(74,202,122,.35)", color:"#4ACA7A", fontSize:12, fontWeight:700, padding:"3px 10px", borderRadius:12 }}>{pending.length} to review</span>
      </div>

      {/* Generate suggestions (calls the cleanProductNames function once deployed). */}
      <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", marginBottom:10 }}>
        <span style={{ fontSize:12, color:"rgba(255,255,255,.6)" }}>Run AI on next</span>
        <input type="number" min={1} max={500} value={runN} onChange={e => setRunN(e.target.value)}
               style={{ width:64, background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", borderRadius:8, color:"#fff", padding:"7px 9px", fontSize:13 }}/>
        <button onClick={runAI} disabled={runBusy}
                style={{ background:"#4A7FFF", color:"#fff", border:"none", borderRadius:9, padding:"8px 14px", fontSize:12.5, fontWeight:700, cursor: runBusy ? "wait" : "pointer", opacity: runBusy ? .6 : 1 }}>
          {runBusy ? "Running…" : "Generate suggestions"}
        </button>
        {highCount > 0 && (
          <button onClick={approveAllHigh} disabled={bulkBusy}
                  style={{ background:"rgba(74,202,122,.16)", color:"#4ACA7A", border:"1px solid rgba(74,202,122,.4)", borderRadius:9, padding:"8px 14px", fontSize:12.5, fontWeight:700, cursor: bulkBusy ? "wait" : "pointer", opacity: bulkBusy ? .6 : 1 }}>
            {bulkBusy ? "Approving…" : `Approve ${highCount} high-confidence (≥85%)`}
          </button>
        )}
        {pending.length > 0 && (
          <button onClick={approveAll} disabled={bulkBusy}
                  style={{ background:"rgba(0,150,70,.22)", color:"#4ACA7A", border:"1px solid rgba(0,180,80,.45)", borderRadius:9, padding:"8px 14px", fontSize:12.5, fontWeight:800, cursor: bulkBusy ? "wait" : "pointer", opacity: bulkBusy ? .6 : 1 }}>
            {bulkBusy ? "Approving…" : `Approve all (${pending.length})`}
          </button>
        )}
      </div>
      {runMsg && <div style={{ fontSize:11.5, color:"rgba(255,255,255,.6)", marginBottom:10 }}>{runMsg}</div>}
      {decidedCount > 0 && <div style={{ fontSize:11, color:"rgba(255,255,255,.35)", marginBottom:10 }}>{decidedCount} already decided (hidden).</div>}

      {pending.length === 0 && (
        <div style={{ textAlign:"center", color:"#555", padding:"2.5rem 1rem", fontSize:"0.9rem" }}>
          No name suggestions to review. Use “Generate suggestions” to run the AI over products that don’t have a proposal yet.
        </div>
      )}

      <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
        {pending.map(row => {
          const busy = busyId === row.id;
          const pct = Math.round((row.confidence || 0) * 100);
          const changed = (row.suggested || "") !== (row.current || "");
          return (
            <div key={row.id} style={{ display:"flex", gap:11, background:"rgba(8,11,20,.9)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:11 }}>
              <ProductPhoto url={row.photoUrl} size={64} radius={10}/>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6 }}>
                  <span style={{ fontSize:10, fontWeight:800, color: confColor(row.confidence || 0), background:"rgba(255,255,255,.05)", border:`1px solid ${confColor(row.confidence || 0)}55`, borderRadius:10, padding:"2px 8px" }}>{pct}% sure</span>
                  {!changed && <span style={{ fontSize:10, color:"rgba(255,255,255,.35)" }}>no change suggested</span>}
                </div>
                <div style={{ fontSize:11, color:"rgba(255,255,255,.4)", textDecoration: changed ? "line-through" : "none", marginBottom:4 }}>{row.current || "(no name)"}</div>
                <input
                  value={edits[row.id] ?? row.suggested ?? ""}
                  onChange={e => setEdits(s => ({ ...s, [row.id]: e.target.value }))}
                  style={{ width:"100%", boxSizing:"border-box", background:"rgba(255,255,255,.06)", border:"1px solid rgba(74,127,255,.35)", borderRadius:8, color:"#fff", padding:"8px 10px", fontSize:13.5, fontWeight:600, marginBottom:8 }}
                  aria-label="Suggested name (editable)"
                />
                <div style={{ display:"flex", gap:8 }}>
                  <button onClick={() => approve(row)} disabled={busy || !finalName(row)}
                          style={{ flex:1, background:"rgba(0,150,70,.22)", border:"1px solid rgba(0,180,80,.4)", color:"#4ACA7A", borderRadius:9, padding:"9px 0", fontSize:12.5, fontWeight:700, cursor: busy ? "wait" : "pointer", opacity: busy ? .6 : 1 }}>
                    {busy ? "…" : "Approve"}
                  </button>
                  <button onClick={() => reject(row)} disabled={busy}
                          style={{ flex:1, background:"rgba(150,30,30,.18)", border:"1px solid rgba(200,60,60,.35)", color:"#FF6B6B", borderRadius:9, padding:"9px 0", fontSize:12.5, fontWeight:700, cursor: busy ? "wait" : "pointer", opacity: busy ? .6 : 1 }}>
                    Reject
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Shared size→quantity entry grid — used by BOTH the Add-Product "Opening stock"
// and the product-detail "Receive stock" blocks (identical layout, previously
// copy-pasted). `sizes` is the already-filtered list; values/onChange bind to the
// caller's qty state.
function SizeQtyGrid({ sizes, values, onChange }) {
  return (
    <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(64px, 1fr))", gap:10 }}>
      {sizes.map(s => (
        <div key={s} style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:2 }}>
          <div style={{ fontSize:13, fontWeight:700, color:"#6A9FFF" }}><SizeTag size={s} /></div>
          <div style={{ color:"rgba(120,150,255,.5)", fontSize:14, lineHeight:1 }}>↓</div>
          <input type="number" inputMode="numeric" min="0" placeholder="0"
            value={values[s] ?? ""}
            onChange={e => onChange(s, e.target.value)}
            style={{ ...inputStyle, width:"100%", boxSizing:"border-box", textAlign:"center", padding:"8px 4px" }} />
        </div>
      ))}
    </div>
  );
}

