// Matches the sidebar breakpoint: true below `px` wide (tablet and down).
function useIsNarrow(px = 980) {
  const [narrow, setNarrow] = useState(() => typeof window !== "undefined" && window.innerWidth <= px);
  useEffect(() => {
    const mq = window.matchMedia(`(max-width: ${px}px)`);
    const onChange = (e) => setNarrow(e.matches);
    setNarrow(mq.matches);
    // Safari < 14 only has addListener/removeListener.
    if (mq.addEventListener) mq.addEventListener("change", onChange);
    else mq.addListener(onChange);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener("change", onChange);
      else mq.removeListener(onChange);
    };
  }, [px]);
  return narrow;
}

// Tolerant epoch-ms parse for status timestamps that may be ISO strings or ms.
const aiTsMs = (v) => (typeof v === "number" ? v : Date.parse(v) || 0);

function AiStatCard({ label, value, sub, tint, icon }) {
  return (
    <div style={{ background:"rgba(255,255,255,.03)", border:"1px solid rgba(255,255,255,.08)", borderRadius:16, padding:"14px 16px", minWidth:0 }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:10 }}>
        <span style={{ fontSize:12, fontWeight:600, color:"rgba(255,255,255,.55)" }}>{label}</span>
        <span style={{ width:30, height:30, borderRadius:9, background:`${tint}22`, border:`1px solid ${tint}55`, color:tint, display:"flex", alignItems:"center", justifyContent:"center" }}>{icon}</span>
      </div>
      <div style={{ fontSize:24, fontWeight:800, letterSpacing:-.4, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{value}</div>
      {sub && <div style={{ fontSize:11.5, color:"rgba(255,255,255,.4)", marginTop:3 }}>{sub}</div>}
    </div>
  );
}

function AiStudioView({ products, onExit }) {
  const { user } = usePermissions();
  const [tool, setTool] = usePersistedTab("aistudio", "photos");
  const narrow = useIsNarrow(980);

  // Stat-row data — live, same sources the tools themselves use.
  const nameProposals  = useNameProposals();
  const photoProposals = usePhotoProposals();
  const pendingPhotos = useMemo(() => Object.values(photoProposals || {}).filter(v => v && v.status !== "approved" && v.status !== "rejected").length, [photoProposals]);
  const pendingNames  = useMemo(() => Object.values(nameProposals  || {}).filter(v => v && v.status !== "approved" && v.status !== "rejected").length, [nameProposals]);
  const [reorderStatus, setReorderStatus] = useState(null);
  useEffect(() => {
    const unsub = onValue(ref(database, "insights/reorderPlan/status"),
      snap => setReorderStatus(snap.val()),
      err  => console.warn("reorderPlan/status read error:", err.message));
    return () => unsub();
  }, []);
  const reorderValue = useMemo(() => {
    if (reorderStatus?.state === "running") return "Running…";
    const t = aiTsMs(reorderStatus?.finishedAt) || aiTsMs(reorderStatus?.startedAt);
    return t ? new Date(t).toLocaleDateString("en-ZA", { day:"numeric", month:"short" }) : "Never run";
  }, [reorderStatus]);

  // Same name → photo lookup InsightsView builds for InsightReorderTab.
  const productPhotoMap = useMemo(() => {
    const normKey = s => s.trim().replace(/\s+/g, ' ').toLowerCase().replace(/\s*-\s*/g, '-');
    const map = {};
    (products || []).forEach(p => {
      if (!p.name) return;
      const entry = { photoUrl: p.photoUrl || null, photo: p.photo || "" };
      map[p.name] = entry;
      map[normKey(p.name)] = entry;
    });
    return map;
  }, [products]);

  const badgeOf = (id) => id === "photos" ? pendingPhotos : id === "names" ? pendingNames : 0;

  const navItem = (t) => {
    const on = tool === t.id;
    const badge = badgeOf(t.id);
    return (
      <button key={t.id} onClick={() => setTool(t.id)}
              style={{ display:"flex", alignItems:"center", gap:11, width:"100%", textAlign:"left", boxSizing:"border-box",
                       background: on ? "rgba(74,127,255,.12)" : "transparent",
                       border:"1px solid " + (on ? "rgba(74,127,255,.45)" : "transparent"),
                       color: on ? "#9DBCFF" : "rgba(255,255,255,.6)",
                       borderRadius:11, padding:"11px 13px", fontSize:13.5, fontWeight:600, cursor:"pointer",
                       transition:"background .15s ease, color .15s ease, border-color .15s ease" }}>
        {AI_TOOL_ICON[t.id]}
        <span style={{ flex:1 }}>{t.label}</span>
        {badge > 0 && <span style={{ background:"rgba(74,127,255,.25)", color:"#9DBCFF", fontSize:11, fontWeight:800, borderRadius:999, padding:"1px 8px" }}>{badge}</span>}
      </button>
    );
  };

  const switchViewBtn = (
    <button onClick={onExit}
            style={{ display:"flex", alignItems:"center", gap:8, background:"rgba(255,255,255,.05)", border:"1px solid rgba(255,255,255,.12)",
                     color:"rgba(255,255,255,.7)", borderRadius:10, padding:"9px 14px", fontSize:12.5, fontWeight:600, cursor:"pointer", whiteSpace:"nowrap" }}>
      ⇄ Switch View
    </button>
  );

  const sidebar = (
    <aside style={{ width:224, flexShrink:0, position:"sticky", top:0, height:"100vh", boxSizing:"border-box",
                    display:"flex", flexDirection:"column", gap:4, padding:"24px 14px 18px",
                    background:"rgba(255,255,255,.015)", borderRight:"1px solid rgba(255,255,255,.07)" }}>
      <div style={{ padding:"0 10px 20px" }}>
        <div style={{ fontSize:22, fontWeight:800, fontStyle:"italic", letterSpacing:-.6, color:"#fff" }}>marathon</div>
        <div style={{ fontSize:10.5, fontWeight:700, letterSpacing:5, color:"#4A7FFF", marginTop:1 }}>CLUB</div>
      </div>
      {AI_TOOLS.map(navItem)}
      <div style={{ flex:1 }}/>
      {switchViewBtn}
      <div style={{ display:"flex", alignItems:"center", gap:10, marginTop:10, padding:"10px 12px", background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.08)", borderRadius:12 }}>
        <span style={{ width:30, height:30, borderRadius:"50%", flexShrink:0, background:"rgba(74,127,255,.2)", border:"1px solid rgba(74,127,255,.5)", color:"#9DBCFF", fontSize:13, fontWeight:800, display:"flex", alignItems:"center", justifyContent:"center" }}>
          {(user?.email || "?")[0].toUpperCase()}
        </span>
        <span style={{ minWidth:0 }}>
          <span style={{ display:"block", fontSize:12, fontWeight:700, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{(user?.email || "").split("@")[0]}</span>
          <span style={{ display:"block", fontSize:10.5, color:"rgba(255,255,255,.4)" }}>Super admin</span>
        </span>
      </div>
    </aside>
  );

  const chips = (
    <div style={{ display:"flex", gap:8, flexWrap:"wrap", margin:"16px 0 0" }}>
      {AI_TOOLS.map(t => {
        const on = tool === t.id;
        const badge = badgeOf(t.id);
        return (
          <button key={t.id} onClick={() => setTool(t.id)}
                  style={{ display:"flex", alignItems:"center", gap:7,
                           background: on ? "rgba(74,127,255,.22)" : "rgba(255,255,255,.05)",
                           color: on ? "#9DBCFF" : "rgba(255,255,255,.55)",
                           border:"1px solid " + (on ? "rgba(74,127,255,.55)" : "rgba(255,255,255,.12)"),
                           borderRadius:999, padding:"8px 15px", fontSize:12.5, fontWeight:700, cursor:"pointer" }}>
            {AI_TOOL_ICON[t.id]}{t.label}
            {badge > 0 && <span style={{ background:"rgba(74,127,255,.3)", color:"#BDD2FF", fontSize:10.5, fontWeight:800, borderRadius:999, padding:"0 7px" }}>{badge}</span>}
          </button>
        );
      })}
    </div>
  );

  const activeTool = AI_TOOLS.find(t => t.id === tool) || AI_TOOLS[0];
  const toolBody =
    tool === "names"    ? <AdminReviewNamesTab products={products} /> :
    tool === "reorder"  ? <InsightReorderTab productPhotoMap={productPhotoMap} /> :
    tool === "stylekit" ? <StyleKitPanel /> :
                          <AdminReviewPhotosTab products={products} />;

  return (
    <div style={{ minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, display:"flex" }}>
      {!narrow && sidebar}
      <div style={{ flex:1, minWidth:0 }}>
        <div style={{ maxWidth:1160, margin:"0 auto", padding: narrow ? "26px 16px 50px" : "30px 30px 60px", boxSizing:"border-box" }}>
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:12 }}>
            <div>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <span style={{ color:"#4A7FFF" }}>{RoleIcons.ai_studio}</span>
                <span style={{ fontSize:25, fontWeight:800, letterSpacing:-.5 }}>AI Studio</span>
              </div>
              <div style={{ fontSize:13, color:"rgba(255,255,255,.5)", marginTop:4 }}>Every AI tool in one place — super admin only.</div>
            </div>
            {narrow && switchViewBtn}
          </div>

          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(175px, 1fr))", gap:12, marginTop:20 }}>
            <AiStatCard label="Photos to review" value={pendingPhotos} sub="awaiting approve / reject" tint="#4A7FFF" icon={AI_TOOL_ICON.photos}/>
            <AiStatCard label="Names to review"  value={pendingNames}  sub="awaiting approve / reject" tint="#A78BFA" icon={AI_TOOL_ICON.names}/>
            <AiStatCard label="Reorder plan"     value={reorderValue}  sub={reorderStatus?.state === "running" ? "analysis in progress" : "last analysis run"} tint="#4ACA7A" icon={AI_TOOL_ICON.reorder}/>
          </div>

          {narrow && chips}

          <section style={{ background:"rgba(255,255,255,.03)", border:"1px solid rgba(255,255,255,.08)", borderRadius:18, marginTop:18, overflow:"hidden" }}>
            <div style={{ display:"flex", alignItems:"center", gap:9, padding:"14px 16px 0" }}>
              <span style={{ color:"#4A7FFF" }}>{AI_TOOL_ICON[activeTool.id]}</span>
              <span style={{ fontSize:14.5, fontWeight:800 }}>{activeTool.label}</span>
              <span style={{ fontSize:11.5, color:"rgba(255,255,255,.35)" }}>· {activeTool.desc}</span>
            </div>
            <div style={{ padding:"6px 2px 14px" }}>
              {toolBody}
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

function AdminView({ products, orders, onExit }) {
  // The AI features (Claude name-cleanup, Gemini/OpenAI photo generation,
  // pickup-board voice) moved to the super-admin-only AI Studio view — this
  // view is pure product management now (products + category sorting).
  // ── Add Product form state (collapsible at top of list) ─────────────────
  const [showAdd, setShowAdd] = useState(false);
  // ── TAXONOMY REBUILD (2026-07-26) ───────────────────────────────────────
  // `categoryKey` is now the ONE product-type control: it replaced both the
  // dead "Category…" text dropdown and the four-chip Product Type row, which
  // were two spellings of the same concept. It selects a registry entry, and
  // that entry supplies BOTH the size breakdown to render AND — via legacyFor()
  // — the legacy category / subcategory / productType written on save, so a
  // product created here is indistinguishable to the refill sweep, Display
  // Checks and POS from one created by the old form. NOTHING is selected by
  // default and a save without one is refused.
  //
  // `sizes` is no longer picked by hand: it IS the set of sizes with a quantity
  // box, i.e. the whole size list of the chosen category. Opening stock is a
  // required, always-visible section now, so "which sizes does it come in" and
  // "how many of each did we receive" are one question, not two.
  //
  // POS Phase 2: stockPrice / retailPrice / hasShoeBoxOption. Prices are raw
  // <input type="number"> strings here and parsed on save — an empty field
  // round-trips to "not set" instead of 0. `shoeboxTouched` tracks a manual
  // toggle; once true we stop auto-syncing it from the category.
  // sku + barcode are NOT in form state — they auto-generate at save time via
  // reserveNextSkuAndBarcode() so the sequence stays tight and gap-free.
  const [form, setForm] = useState({ name:"", categoryKey:"", photo:"", photoUrl:null, photoBlob:null, hubs:["hub1"], stockPrice:"", retailPrice:"", hasShoeBoxOption:true });
  const [shoeboxTouched, setShoeboxTouched] = useState(false);
  // Opening stock — REQUIRED and always visible (no longer collapsible). An
  // explicit 0 per size is allowed so nothing forces a fake number, but the
  // section cannot be skipped: a destination must be picked before saving.
  const [recvQtys, setRecvQtys] = useState({}); // { size: "n" }
  const [recvLoc, setRecvLoc] = useState(""); // destination — NO default; admin must pick each save
  // Set true by a blocked save attempt so required fields paint their error
  // state only AFTER the operator has tried, never on an untouched form.
  const [saveAttempted, setSaveAttempted] = useState(false);
  const [saving, setSaving] = useState(false);
  // After a save with opening stock, surface the inline Print-barcodes sheet for the
  // sizes just received (count defaults to units added). Lives at the view level so
  // it survives the New Product form unmounting on save.
  const [lastReceived, setLastReceived] = useState(null); // { productId, productName, items:[{size,added}] }
  const [printOpen, setPrintOpen] = useState(false);
  // Initial Distribution Wizard: set to the just-saved product when opening
  // stock landed at Central. Wizard shows first; the print sheet follows on close.
  const [distribProduct, setDistribProduct] = useState(null);
  const recvRegistry = useLocations();
  const fileInputRef = useRef(null);
  // ── List search + type filter ───────────────────────────────────────────
  const [productSearch, setProductSearch] = useState("");
  // Admin product list is split by top-level CATEGORY so every real category
  // (Footwear / Clothing / Accessories / Perfume, plus an Uncategorized catch-all)
  // is reachable — not just sneakers/clothing. Driven off topCategory (the real
  // `category` field), so a future 5th category surfaces automatically. Defaults
  // to Footwear.
  const [typeFilter, setTypeFilter] = useState("Footwear");
  // Admin section: the product list vs the AI name-cleanup review screen.
  // Persist the active admin tab so a refresh keeps you on the same page (role is
  // already persisted via localStorage; this keeps the section too).
  const [adminSection, setAdminSection] = useState(() => {
    try { return localStorage.getItem("marathon_admin_section") || "products"; } catch { return "products"; }
  });
  useEffect(() => { try { localStorage.setItem("marathon_admin_section", adminSection); } catch { /* storage off */ } }, [adminSection]);
  // The AI review tabs moved to AI Studio — bounce any persisted AI section
  // (pre-move localStorage) back to Products, for everyone.
  useEffect(() => {
    if (adminSection === "review-names" || adminSection === "review-photos") setAdminSection("products");
  }, [adminSection]);
  const pendingCategoryCount = useMemo(() => (products || []).filter(p => p && (p.subcategory === UNCATEGORIZED || topCategory(p) === UNCATEGORIZED_TOP)).length, [products]);
  const missingPriceCount = useMemo(() => (products || []).filter(p => p && (p.retailPrice == null || p.retailPrice === "" || p.retailPrice === 0)).length, [products]);
  // New-taxonomy backlog: products with no categoryKey, excluding legacy sneakers
  // (auto-assigned by predicate). Badges the Assign Categories tab.
  const assignCategoryCount = useMemo(() => (products || []).filter(needsAssignment).length, [products]);
  // ── Detail routing (hash-driven) — #product/{id} opens the detail page,
  //    browser back clears it. Listener stays mounted for the whole view. ──
  const [detailId, setDetailId] = useState(() => parseProductHash());
  useEffect(() => {
    const onHashChange = () => setDetailId(parseProductHash());
    window.addEventListener("hashchange", onHashChange);
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);
  // Insights log → fuels the detail page's "Last sold X · N orders all-time"
  // context line. orders[] alone isn't enough — it's daily-counter-ephemeral
  // (see project-insights-past-days-pattern memory).
  const insightsLog = useInsightsLog();
  // Desktop workspace gate (≥1024px). Mobile keeps the single column.
  const isWide = !useIsNarrow(1024);

  // ── The category registry (LIVE from /settings/productTaxonomy) ───────────
  // Replaces the old `product_categories` node, which never worked: it has no
  // entry in the live RTDB rules, so every "＋ Add new category…" push was
  // silently denied and the node is empty to this day. The registry read is
  // live, so a category added in the console appears here without a deploy.
  const { registry: taxonomy, source: taxonomySource } = useTaxonomy();
  // The chosen category's registry record — drives the size grid, the one-size
  // branch, the hub rules and the legacy derivation on save.
  const selectedCat = useMemo(() => catByKey(taxonomy, form.categoryKey), [taxonomy, form.categoryKey]);
  const formSizes = useMemo(() => (selectedCat ? sizesOf(selectedCat) : []), [selectedCat]);
  const formOneSize = !!selectedCat && isOneSize(selectedCat);
  // Legacy values this category will write. Derived here (not at save time) so
  // the form can apply the SAME hub / shoebox rules the old productType chips
  // applied, from the same single source of truth.
  const formLegacy = useMemo(() => legacyFor(taxonomy, form.categoryKey), [taxonomy, form.categoryKey]);
  const formIsClothing = formLegacy?.productType === "clothing";

  const addProduct = async () => {
    setSaveAttempted(true);
    // Category is REQUIRED — and it must resolve to a real registry entry with a
    // legacy derivation. Without it we cannot write the legacy fields, and a
    // product missing those would fall out of the refill sweep, Display Checks
    // and POS browse. Refuse rather than half-type it.
    if (!form.name.trim() || !form.categoryKey || !selectedCat || !formLegacy) return;
    if (!formSizes.length) return;
    // Opening stock is required as a SECTION: the destination must be picked.
    // The quantities themselves are not — an explicit 0 everywhere is a valid
    // answer ("received nothing yet"), it just writes no movements.
    if (!recvLoc) { alert("Pick the location this stock is being received into before saving."); return; }
    setSaving(true);
    try {
      const id = "p" + serverNowMs();
      let photoUrl = form.photoUrl; // may be null or a preview data-URL

      if (form.photoBlob) {
        // Upload compressed image to Firebase Storage; store only the HTTPS URL in RTDB.
        const sRef = storageRef(storage, `products/${id}/photo.jpg`);
        // Bounded cache (NOT immutable): products/{id}/photo.jpg is overwritten
        // in place when the photo is re-shot, so cap staleness at 7 days.
        await uploadBytes(sRef, form.photoBlob, { contentType: "image/jpeg", cacheControl: "public, max-age=604800" });
        photoUrl = await getDownloadURL(sRef);
      }

      // ── THE RECORD — legacy derivation lives in buildNewProduct (pure, and
      //    tested against the signed-off table in newProductRecord.test.js).
      //    The chosen category supplies category / subcategory / productType so
      //    the refill sweep, Display Checks and POS treat this product exactly
      //    as they treat one made by the old form. Brand stays auto-parsed from
      //    the name by the shared classifier, as before.
      const newProduct = buildNewProduct(taxonomy, form, {
        id,
        photoUrl: photoUrl ?? null,
        brand: brandOf(form.name),
        // A real photo uploaded with the product stamps the upload time (drives
        // the AI Photo Studio "Recent" view; legacy products fall back to the
        // id-encoded creation time).
        photoUploaded: !!form.photoBlob,
        photoUpdatedAt: form.photoBlob ? serverNowMs() : null,
      });
      // Category vanished mid-save (retired in the console between opening the
      // form and pressing save) — refuse rather than write a product with no
      // legacy fields, which would silently drop out of every automation.
      if (!newProduct) throw new Error("That category is no longer available. Pick a category again.");
      const sizes = newProduct.sizes;
      // MERGE NOTE (2026-07-30): prices and the shoebox flag moved INTO
      // buildNewProduct during the form rewrite — main's inline copies of those
      // are intentionally not carried over here, they would be duplicates. The
      // createdBy stamp below is genuinely new and is preserved verbatim.
      //
      // ATTRIBUTION (createdBy, #283): who + which device saved this product. Store
      // the OPAQUE uid only — NOT the email: /products is readable by every signed-in
      // staff member, so an email on every record would broadcast staff identity
      // and duplicate PII catalogue-wide. The uid resolves to a name via the
      // admin-gated /users/{uid} record at display time. deviceId is a persistent
      // per-browser id (the store-app has no server device identity), so the same
      // tablet is recognizable even under a shared PIN login. Purely additive,
      // written once at creation; NEVER gates the save (every field tolerates
      // null: signed-out/anon → null uid, private-mode browser → null deviceId).
      // Products created before this ship carry no createdBy — readers treat it
      // as unknown.
      newProduct.createdBy = {
        uid: auth.currentUser?.uid ?? null,
        deviceId: getDeviceId(),
        at: serverNowMs(),
      };
      // POS Phase 2: reserve the next sequential sku + barcode atomically
      // BEFORE the product write so two concurrent adds can't collide. If
      // reservation fails (counter exhausted or RTDB error), surface the
      // message and abort — no half-saved product, no advanced counter.
      const { sku, barcode } = await reserveNextSkuAndBarcode();
      newProduct.sku     = sku;
      newProduct.barcode = barcode;
      await addProductToFirebase(newProduct);

      // GUARANTEE ON SAVE: mint a barcode for every size now so the catalog never
      // has gaps (a sizeless/one-size product mints the "_" slot). Best-effort —
      // a creator without stockRole still saves the product; the index heals on
      // the next mint and the backfill covers anything missed.
      ensureBarcodes(id, sizes.length ? sizes : [null]).catch(() => {});

      // Opening stock: the entered quantities become `received` movements at the
      // chosen location via applyMovement — ledger-paired, never raw. A size left
      // blank or explicitly 0 writes NO movement (there is nothing to receive);
      // the product still saves. The product write already succeeded, so this
      // NEVER blocks the save; a denied movement (e.g. no stockRole) soft-warns
      // and can be entered later from Stock.
      try {
        const recvEntries = receiveEntries(sizes, recvQtys);
        if (recvEntries.length) {
          const locLabel = labelFor(recvLoc, recvRegistry);
          let recOk = 0; const savedItems = []; const failed = [];
          for (const [size, n] of recvEntries) {
            const res = await applyMovement({ type: "received", productId: id, size, qty: n, to: recvLoc });
            if (res.ok) { recOk++; savedItems.push({ size, added: n }); }
            else failed.push(`${size}×${n}`);
          }
          if (failed.length) {
            // Receiving is per-size and NOT atomic (inherited behaviour — one
            // ledger movement per size). A partial failure must therefore name
            // the exact sizes that did NOT land, or the operator has no way to
            // know what to re-enter, and re-entering everything would
            // double-receive the sizes that succeeded.
            alert(
              `Product saved, and ${recOk} size(s) received into ${locLabel}.\n\n` +
              `NOT received: ${failed.join(", ")}\n\n` +
              `You may not have stock permission (stockRole). Add exactly these sizes from Stock → Set Quantity — ` +
              `do not re-enter the whole delivery or the sizes above will be counted twice.`
            );
          }
          // Surface the inline Print-barcodes sheet for the sizes that saved.
          if (savedItems.length) {
            setLastReceived({ productId: id, productName: newProduct.name, photoUrl: newProduct.photoUrl ?? null, items: savedItems });
            // Stock landed at Central → offer initial distribution first; the
            // print sheet opens when the wizard closes. Other locations keep
            // the original save → print flow.
            if (recvLoc === "central") setDistribProduct(newProduct);
            else setPrintOpen(true);
          }
        }
      } catch (recErr) {
        console.warn("opening-stock receive failed:", recErr);
      }

      setForm({ name:"", categoryKey:"", photo:"", photoUrl:null, photoBlob:null, hubs:["hub1"], stockPrice:"", retailPrice:"", hasShoeBoxOption:true });
      setShoeboxTouched(false);
      setRecvQtys({});
      setSaveAttempted(false);
      // Keep the receiving location — an admin loading a delivery adds several
      // products into the SAME location in a row; re-picking it each time was
      // pure friction and a mis-pick risk.
      setShowAdd(false);
    } catch (err) {
      console.error("addProduct failed:", err);
      // Surface counter-exhaustion + reservation errors with their actual
      // message so the admin knows what's wrong; everything else gets the
      // generic prompt.
      const msg = /counter exhausted|reservation|no longer available/i.test(String(err?.message || ""))
        ? `Failed to save product:\n${err.message}`
        : "Failed to save product. Please try again.";
      alert(msg);
    } finally {
      setSaving(false);
    }
  };

  // Per-product edit handlers (name/sizes/hubs/photo/delete) used to live
  // here as inline-editor flows in the list. They've been moved into
  // AdminProductDetail — list rows are now navigation targets only.

  const toggleHub  = h => setForm(f => ({ ...f, hubs:  f.hubs.includes(h)  ? f.hubs.filter(x=>x!==h)  : [...f.hubs,  h] }));
  // ── Picking a category is the ONE decision that reshapes the form ─────────
  // It swaps the size grid, and it applies the two rules the removed Product
  // Type chips used to apply, driven off the DERIVED productType so behaviour is
  // identical:
  //   • clothing cannot be stocked at Hub 1 (stripped, falling back to Hub 2);
  //   • clothing never has a shoebox (forced off), footwear defaults it on —
  //     unless the operator has manually toggled it (shoeboxTouched).
  // Changing category also clears the entered quantities: the size set is
  // different, so keeping numbers keyed to the old sizes would silently receive
  // stock against sizes the product does not have.
  const selectCategory = (nextKey) => {
    if (nextKey === form.categoryKey) return;
    const legacy = legacyFor(taxonomy, nextKey);
    const clothing = legacy?.productType === "clothing";
    setForm(f => {
      const hubs = clothing ? f.hubs.filter(h => h !== "hub1") : f.hubs;
      return {
        ...f,
        categoryKey: nextKey,
        hubs: hubs.length ? hubs : (clothing ? ["hub2"] : ["hub1"]),
        // Clothing forces the shoebox off even against a manual toggle (it is a
        // shoebox — clothing does not have one). Footwear only auto-sets it
        // while the operator has not taken manual control.
        ...(clothing ? { hasShoeBoxOption: false } : (shoeboxTouched ? {} : { hasShoeBoxOption: true })),
      };
    });
    setRecvQtys({});
  };
  const toggleShoebox = () => {
    setShoeboxTouched(true);
    setForm(f => ({ ...f, hasShoeBoxOption: !f.hasShoeBoxOption }));
  };

  // Products filtered by the active category tab + the search bar (substring,
  // case-insensitive). Bucketed by topCategory (the real `category` field), so
  // perfumes and accessories land in their own tabs instead of hiding under
  // Sneakers/Clothing; products with no category fall into "Uncategorized".
  const filteredProducts = useMemo(() => {
    const q = productSearch.trim();
    return products.filter(p => {
      if (topCategory(p) !== typeFilter) return false;
      // Forgiving search: fuzzy name + barcode/sku/per-size codes (see productSearch.js).
      if (q && !productMatchesQuery(p, q)) return false;
      return true;
    });
  }, [products, productSearch, typeFilter]);

  // Category tabs above the list: the four real top-levels (from TOP_CATEGORIES,
  // so a future category appears automatically), plus an "Uncategorized" tab that
  // shows only when something actually needs it — or while it's the active tab, so
  // the selection never becomes invalid mid-organise. Each entry carries its own
  // count so nothing recomputes per-tab in the render.
  const categoryTabs = useMemo(() => {
    const counts = {};
    for (const p of products) { const c = topCategory(p); counts[c] = (counts[c] || 0) + 1; }
    const tabs = TOP_CATEGORIES.map(c => [c, c, counts[c] || 0]);
    if ((counts[UNCATEGORIZED_TOP] || 0) > 0 || typeFilter === UNCATEGORIZED_TOP) {
      tabs.push([UNCATEGORIZED_TOP, "Uncategorized", counts[UNCATEGORIZED_TOP] || 0]);
    }
    return tabs;
  }, [products, typeFilter]);

  const handleImageUpload = e => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      const img = new Image();
      img.onload = () => {
        const MAX_DIM = 800;
        const MAX_BYTES = 200 * 1024; // 200 KB target

        // Scale down if wider/taller than 800 px.
        const scale = Math.min(1, MAX_DIM / img.width, MAX_DIM / img.height);
        const canvas = document.createElement("canvas");
        canvas.width  = Math.round(img.width  * scale);
        canvas.height = Math.round(img.height * scale);
        canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);

        // Step quality from 0.85 down to 0.05 in 0.05 increments.
        // dataUrl length * 0.75 ≈ actual byte count (base64 overhead is 4/3).
        // Stop as soon as the image fits in MAX_BYTES.
        let dataUrl = canvas.toDataURL("image/jpeg", 0.05); // worst-case fallback
        for (let q = 0.85; q > 0.05; q = Math.round((q - 0.05) * 100) / 100) {
          const candidate = canvas.toDataURL("image/jpeg", q);
          if (candidate.length * 0.75 <= MAX_BYTES) {
            dataUrl = candidate;
            break;
          }
        }

        const blob = dataURLToBlob(dataUrl);
        setForm(f => ({ ...f, photoUrl: dataUrl, photoBlob: blob }));
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  };

  // Detail page: which product, and stale-hash guard. If the hash points
  // at a product that no longer exists (deleted in another tab), clear it.
  const detailProduct = detailId ? products.find(p => p.id === detailId) : null;
  useEffect(() => {
    if (detailId && products.length > 0 && !detailProduct) {
      window.history.back();
    }
  }, [detailId, products.length, detailProduct]);

  // When the detail page is mounted, render JUST the detail (no list chrome).
  // Desktop: the detail carries its own full-width workspace shell, so skip the
  // 640px mobile column wrapper.
  if (detailProduct) {
    const detail = (
      <AdminProductDetail
        product={detailProduct}
        insightsLog={insightsLog}
        onBack={() => window.history.back()}
      />
    );
    if (isWide) return detail;
    return (
      <div style={{ minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, maxWidth:640, margin:"0 auto", overflowX:"hidden", paddingBottom:40 }}>
        {detail}
      </div>
    );
  }

  // Section toggle (Products ↔ Categories ↔ Missing Prices) — the AI tabs live in AI Studio now.
  const sectionToggle = (
    <div style={{ display:"flex", flexWrap:"wrap", gap:8, padding:"0 14px 4px" }}>
      {[["products","Products"],["assign-categories","Assign"],["review-categories","Categories"],["missing-prices","Missing Prices"]]
        .map(([val, label]) => {
        const on = adminSection === val;
        const badge = val === "review-categories" ? pendingCategoryCount
          : val === "assign-categories" ? assignCategoryCount
          : val === "missing-prices" ? missingPriceCount : 0;
        return (
          <button key={val} onClick={() => setAdminSection(val)}
            style={{ flex:"1 1 88px", minWidth:88, background: on ? "#4A7FFF" : "rgba(255,255,255,.05)", color: on ? "#fff" : "rgba(255,255,255,.6)", border:"1px solid "+(on ? "#4A7FFF" : "rgba(255,255,255,.1)"), borderRadius:10, padding:"9px 6px", fontSize:13, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:6 }}>
            {label}{badge > 0 && <span style={{ background: val === "missing-prices" ? "#FBBF24" : "#4ACA7A", color: val === "missing-prices" ? "#6b4e00" : "#063", fontSize:11, fontWeight:800, borderRadius:9, padding:"0 7px" }}>{badge}</span>}
          </button>
        );
      })}
    </div>
  );

  // Shared admin chrome (was copy-pasted across the four tab branches).
  const ADMIN_WRAP = { minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, maxWidth:640, margin:"0 auto", overflowX:"hidden", paddingBottom:40 };
  const adminTopBar = (
    <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"50px 14px 12px" }}>
      <div onClick={onExit} style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.1)", borderRadius:10, padding:"8px 14px", fontSize:12, color:"rgba(255,255,255,.7)", cursor:"pointer" }}>← Switch View</div>
      <div style={{ textAlign:"center" }}>
        <div style={{ fontSize:10, color:"rgba(255,255,255,.4)", letterSpacing:"0.5px" }}>Viewing as:</div>
        <div style={{ fontSize:15, fontWeight:700, color:"#4A7FFF", letterSpacing:"0.5px" }}>ADMIN</div>
      </div>
      <div style={{ width:90 }}/>
    </div>
  );
  // A review tab (Names / Photos / Categories) is the same shell: wrapper → top bar
  // → section toggle → the tab body.
  const reviewShell = (tab) => (
    <div style={ADMIN_WRAP}>
      {adminTopBar}
      <div style={{ height:6 }}/>
      {sectionToggle}
      <div style={{ height:10 }}/>
      {tab}
    </div>
  );

  // Products body — header + add form + type filter + search + list + print sheet.
  // Shared by the mobile column and the desktop main pane.
  const productsBody = (
    <>
      <div>
        {/* PRODUCTS HEADER ROW */}
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"16px 14px 12px" }}>
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>
            <span style={{ fontSize:20, fontWeight:700, color:"#fff" }}>Products</span>
            <span style={{ background:"rgba(60,110,255,.15)", border:"1px solid rgba(60,110,255,.3)", color:"#4A7FFF", fontSize:12, fontWeight:700, padding:"3px 10px", borderRadius:12 }}>{products.length}</span>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <button onClick={() => setShowAdd(!showAdd)} style={{ background:"#4A7FFF", color:"#fff", border:"none", borderRadius:10, padding:"10px 18px", fontSize:13, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", gap:6, boxShadow:"0 0 14px rgba(60,110,255,.3)" }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
              Add Product
            </button>
          </div>
        </div>


        <div style={{ padding:"0 14px" }}>

      {showAdd && (
        <NewProductForm
          form={form} setForm={setForm}
          taxonomy={taxonomy} taxonomySource={taxonomySource}
          selectedCat={selectedCat} formSizes={formSizes} formOneSize={formOneSize}
          formIsClothing={formIsClothing}
          selectCategory={selectCategory} toggleHub={toggleHub} toggleShoebox={toggleShoebox}
          recvQtys={recvQtys} setRecvQtys={setRecvQtys}
          recvLoc={recvLoc} setRecvLoc={setRecvLoc} recvRegistry={recvRegistry}
          fileInputRef={fileInputRef} handleImageUpload={handleImageUpload}
          saving={saving} saveAttempted={saveAttempted} onSave={addProduct}
        />
      )}

      {/* CATEGORY TABS — one per real top-level category (+ Uncategorized when
          needed). Wraps to a second row on narrow screens so longer labels
          ("Accessories") stay readable. */}
      <div style={{ display:"flex", flexWrap:"wrap", background:"rgba(255,255,255,.04)", border:"1px solid rgba(60,110,255,.25)", borderRadius:12, padding:3, gap:2, marginBottom:14 }}>
        {categoryTabs.map(([val, label, count]) => {
          const on = typeFilter === val;
          return (
            <button key={val} onClick={() => setTypeFilter(val)}
              style={{ flex:"1 1 78px", minWidth:78, padding:"8px 6px", borderRadius:9, border:"none", cursor:"pointer", fontSize:13, fontWeight:700,
                       background: on ? "rgba(60,110,255,.25)" : "transparent",
                       color: on ? "#fff" : "rgba(255,255,255,.5)",
                       boxShadow: on ? "0 0 6px rgba(60,110,255,.35)" : "none" }}>
              {label} <span style={{ opacity:.7, fontWeight:600 }}>({count})</span>
            </button>
          );
        })}
      </div>

      {/* PRODUCT SEARCH BAR (Phase 12A) */}
      <div style={{ marginBottom:14 }}>
        <input
          placeholder="Search products by name…"
          value={productSearch}
          onChange={e => setProductSearch(e.target.value)}
          style={{ ...inputStyle, fontSize:14, padding:"10px 14px" }}
        />
      </div>

      {/* CLEAN PRODUCT LIST — each row is a navigation target (taps push
          #product/{id} via AdminProductRow). All edit affordances moved to
          AdminProductDetail. */}
      <div>
        {filteredProducts.length === 0 && (
          <div style={{ textAlign:"center", color:"#555", padding:"2.5rem 1rem", fontSize:"0.9rem" }}>
            {productSearch.trim() ? "No products match your search." : `No ${typeFilter} products yet. Add one above.`}
          </div>
        )}
        <div style={isWide ? { display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(320px, 1fr))", gap:10, alignItems:"start" } : undefined}>
          {filteredProducts.map(p => <AdminProductRow key={p.id} product={p} />)}
        </div>
      </div>
      <div style={{ height:20 }}/>
        </div>
      </div>

      {/* Initial Distribution Wizard — after a new-product save with opening
          stock at Central. Closing it (skip or done) opens the print sheet. */}
      {distribProduct && (
        <InitialDistributionWizard
          product={distribProduct}
          onClose={() => { setDistribProduct(null); setPrintOpen(true); }}
        />
      )}
      {/* Inline Print-barcodes sheet (#73), surfaced after a save with opening
          stock. Lives here (not in the unmounting New Product form) so it persists. */}
      {printOpen && lastReceived && (
        <BarcodePrint
          product={{ id: lastReceived.productId, name: lastReceived.productName, photoUrl: lastReceived.photoUrl }}
          items={lastReceived.items}
          onClose={() => setPrintOpen(false)}
        />
      )}
    </>
  );

  // ── DESKTOP WORKSPACE (>=1024px) — rail of sections + titled main pane.
  //    Handles both admin sections; mobile keeps the single column below. ──
  if (isWide) {
    const NAV = [["products", "Products", products.length], ["assign-categories", "Assign Categories", assignCategoryCount], ["review-categories", "Categories", pendingCategoryCount], ["missing-prices", "Missing Prices", missingPriceCount]];
    const navItem = ([key, label, count]) => {
      const on = adminSection === key;
      return (
        <button key={key} onClick={() => setAdminSection(key)}
          style={{ display:"flex", alignItems:"center", gap:11, width:"100%", textAlign:"left", cursor:"pointer", fontFamily:FONT, fontSize:13, fontWeight:600, borderRadius:10, padding:"9px 11px",
                   background: on ? "rgba(74,127,255,.13)" : "transparent", border: on ? "1px solid rgba(74,127,255,.42)" : "1px solid transparent",
                   color: on ? "#9DBCFF" : "rgba(233,238,255,.55)", transition:"background .14s, color .14s" }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink:0, opacity:.9 }}>
            {key === "products"
              ? <><path d="M20 7h-9M20 12h-9M20 17h-9" /><circle cx="4" cy="7" r="1.6" /><circle cx="4" cy="12" r="1.6" /><circle cx="4" cy="17" r="1.6" /></>
              : key === "assign-categories"
              ? <><path d="M9 11l3 3L22 4" /><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11" /></>
              : key === "review-categories"
              ? <><path d="M3 7h4l2 3h9a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7z" /></>
              : <><circle cx="12" cy="12" r="10" /><line x1="12" y1="8" x2="12" y2="12" /><line x1="12" y1="16" x2="12.01" y2="16" /></>}
          </svg>
          <span style={{ flex:1 }}>{label}</span>
          {count > 0 && (
            <span style={{ background: on ? "rgba(74,127,255,.3)" : key === "missing-prices" ? "rgba(251,191,36,.15)" : "rgba(255,255,255,.06)", color: on ? "#fff" : key === "missing-prices" ? "#FBBF24" : "rgba(233,238,255,.5)", fontSize:11, fontWeight:800, minWidth:20, textAlign:"center", borderRadius:999, padding:"1px 6px", fontVariantNumeric:"tabular-nums" }}>{count}</span>
          )}
        </button>
      );
    };
    const title = adminSection === "assign-categories" ? "Assign Categories"
      : adminSection === "review-categories" ? "Categories"
      : adminSection === "missing-prices" ? "Missing Prices" : "Products";
    const subtitle = adminSection === "assign-categories"
      ? "Give every product its real category. Nothing else changes."
      : adminSection === "review-categories"
      ? "Sort uncategorised products into the browse tree."
      : adminSection === "missing-prices"
      ? "Products without a selling price — assign prices immediately."
      : "Add products, set sizes & pricing, and manage the catalogue.";
    return (
      <div style={{ height:"100vh", maxHeight:"100dvh", background:"#000", color:"#f3f6ff", fontFamily:FONT, display:"grid", gridTemplateColumns:"236px minmax(0,1fr)", overflow:"hidden" }}>
        {/* RAIL */}
        <aside style={{ background:"rgba(255,255,255,.015)", borderRight:"1px solid rgba(255,255,255,.08)", padding:"22px 13px 16px", display:"flex", flexDirection:"column", gap:3, overflow:"auto" }}>
          <div style={{ display:"flex", alignItems:"baseline", gap:8, padding:"0 9px 10px" }}>
            <span style={{ fontSize:19, fontWeight:800, fontStyle:"italic", letterSpacing:-.6 }}>marathon</span>
            <span style={{ fontSize:9.5, fontWeight:700, letterSpacing:5, color:"#4A7FFF" }}>CLUB</span>
          </div>
          <button onClick={onExit} style={{ display:"flex", alignItems:"center", gap:8, background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.08)", color:"rgba(233,238,255,.6)", borderRadius:10, padding:"9px 12px", fontSize:12.5, fontWeight:600, cursor:"pointer", fontFamily:FONT, marginBottom:6 }}>&larr; Exit</button>
          <button onClick={() => { setAdminSection("products"); setShowAdd(true); }}
            style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:7, background:"rgba(74,127,255,.14)", border:"1px solid rgba(74,127,255,.4)", color:"#9DBCFF", borderRadius:10, padding:"10px 12px", fontSize:12.5, fontWeight:700, cursor:"pointer", fontFamily:FONT, marginBottom:8 }}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            New product
          </button>
          <div style={{ fontSize:9, letterSpacing:".2em", textTransform:"uppercase", color:"rgba(233,238,255,.3)", padding:"6px 9px", fontWeight:700 }}>Manage</div>
          {NAV.map(navItem)}
          <div style={{ flex:1 }} />
          <div style={{ display:"flex", gap:8 }}>
            <div style={{ flex:1, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", borderRadius:11, padding:"9px 10px" }}>
              <div style={{ fontSize:18, fontWeight:800, color:"#9DBCFF", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{products.length}</div>
              <div style={{ fontSize:9.5, color:"rgba(233,238,255,.45)", marginTop:3, letterSpacing:".04em", textTransform:"uppercase", fontWeight:600 }}>Products</div>
            </div>
            <div style={{ flex:1, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", borderRadius:11, padding:"9px 10px" }}>
              <div style={{ fontSize:18, fontWeight:800, color: pendingCategoryCount ? "#FBBF24" : "rgba(233,238,255,.5)", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{pendingCategoryCount}</div>
              <div style={{ fontSize:9.5, color:"rgba(233,238,255,.45)", marginTop:3, letterSpacing:".04em", textTransform:"uppercase", fontWeight:600 }}>To sort</div>
            </div>
          </div>
        </aside>
        {/* MAIN */}
        <div style={{ minWidth:0, display:"flex", flexDirection:"column", overflow:"hidden" }}>
          <div style={{ padding:"20px 30px 16px", borderBottom:"1px solid rgba(255,255,255,.08)", background:"radial-gradient(800px 280px at 15% -60%, rgba(74,127,255,.08), transparent)" }}>
            <div style={{ fontSize:23, fontWeight:800, letterSpacing:-.4 }}>{title}</div>
            <div style={{ fontSize:12.5, color:"rgba(233,238,255,.55)", marginTop:3 }}>{subtitle}</div>
          </div>
          <div style={{ flex:1, overflow:"auto", padding:"18px 30px 48px" }}>
            <div style={{ maxWidth:1160, margin:"0 auto" }}>
              {adminSection === "assign-categories" ? <AssignCategoriesTab products={products} registry={taxonomy} />
                : adminSection === "review-categories" ? <AdminReviewCategoriesTab products={products} />
                : adminSection === "missing-prices" ? <MissingPricesTab products={products} />
                : productsBody}
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (adminSection === "assign-categories") return reviewShell(<AssignCategoriesTab products={products} registry={taxonomy} />);
  if (adminSection === "review-categories") return reviewShell(<AdminReviewCategoriesTab products={products} />);
  if (adminSection === "missing-prices") return reviewShell(<MissingPricesTab products={products} />);

  return (
    <div style={ADMIN_WRAP}>
      {/* TOP BAR with Switch View */}
      {adminTopBar}

      {/* ADMIN HERO IMAGE */}
      <div style={{ position:"relative", height:200, overflow:"hidden" }}>
        <img src="/hero/admin.jpg" alt="Admin Panel" style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%", objectFit:"cover", objectPosition:"left center" }}/>
        <div style={{ position:"absolute", bottom:0, left:0, right:0, height:70, background:"linear-gradient(transparent,#000)" }}/>
      </div>

      <div style={{ height:12 }}/>
      {sectionToggle}

      {productsBody}
    </div>
  );
}

// ─── ADMIN PRODUCT ROW ───────────────────────────────────────────────────────
// Compact tappable card in the admin list. Single-line metadata combines
// type, hubs, and size count. Tap anywhere on the row → hash navigates to
// #product/{id} which AdminView's hashchange listener catches.
function AdminProductRow({ product }) {
  const isClothing = (product.productType || "sneaker") === "clothing";
  const hubs       = getProductHubs(product);
  const hubLabel   = hubs.length ? hubs.map(h => HUB_LABELS[h] || h).join(", ") : "—";
  const sizes      = Array.isArray(product.sizes) ? product.sizes : [];
  const sizeCount  = sizes.length || (isClothing && product.stock ? Object.keys(product.stock).length : 0);
  const meta       = `${isClothing ? "Clothing" : "Sneaker"} · ${hubLabel} · ${sizeCount} size${sizeCount === 1 ? "" : "s"}`;

  return (
    <div onClick={() => { window.location.hash = "product/" + product.id; }}
         style={{
           display:"flex", alignItems:"center", gap:12,
           background:"rgba(255,255,255,.03)",
           border:"1px solid rgba(255,255,255,.07)",
           borderRadius:14, padding:"10px 14px", marginBottom:8, cursor:"pointer",
         }}>
      <ProductPhoto url={product.photoUrl} photo={product.photo} size={56} radius={10}/>
      <div style={{ flex:1, minWidth:0 }}>
        <div style={{ fontSize:16, fontWeight:600, color:"#fff", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{product.name}</div>
        <div style={{ fontSize:12, color:"rgba(255,255,255,.5)", marginTop:4, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{meta}</div>
      </div>
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.3)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink:0 }}>
        <polyline points="9 18 15 12 9 6"/>
      </svg>
    </div>
  );
}

// ─── ADMIN PRODUCT DETAIL ────────────────────────────────────────────────────
// Full-page edit surface reached via #product/{id}. Every field auto-saves
// — name on blur, type/sizes/hubs on every toggle. Photo replace runs the
// existing compression pipeline and uploads immediately on file pick (no
// preview step; consistent with the auto-save theme). Delete prompts for
// confirmation then navigates back.
function AdminProductDetail({ product, insightsLog, onBack }) {
  const isClothing = (product.productType || "sneaker") === "clothing";
  const productSizes = Array.isArray(product.sizes) && product.sizes.length
    ? product.sizes
    : (isClothing && product.stock ? Object.keys(product.stock) : []);
  const productHubs = getProductHubs(product);
  // Desktop workspace gate (≥1024px). Mobile keeps the single column.
  const isWide = !useIsNarrow(1024);
  // Clothing products may use letters (tops) or the waist set (bottoms); a
  // sneaker whose sizes are ≥20 is a Kids product (26–35). Infer the breakdown
  // from the product's own sizes so editing shows the right buttons.
  const sizeChoices = isClothing ? clothingChoicesFor(productSizes)
    : isKidsSizeSet(productSizes) ? KIDS_SIZES : SNEAKER_SIZES;

  const [galleryView, setGalleryView] = useState(null); // open the photo gallery viewer
  const photos = productPhotos(product);
  const extras = Array.isArray(product.gallery) ? product.gallery.filter(Boolean) : [];

  // Name — local draft synced from RTDB, write on blur.
  const [nameDraft, setNameDraft] = useState(product.name);
  useEffect(() => { setNameDraft(product.name); }, [product.name]);
  const saveName = () => {
    const next = nameDraft.trim();
    if (next && next !== product.name) updateProductName(product.id, next);
    else if (!next) setNameDraft(product.name);
  };

  // Photo — pick file → compress in-browser → upload → set photoUrl. No
  // preview/confirm; the upload is the action. Compression pipeline is the
  // same one used by the Add Product form (800px max-dim, step quality down
  // until <200 KB).
  const fileRef = useRef(null);
  const [photoUploading, setPhotoUploading] = useState(false);
  const handlePhotoFile = (e) => {
    const file = e.target.files[0];
    e.target.value = "";
    if (!file) return;
    setPhotoUploading(true);
    const reader = new FileReader();
    reader.onload = ev => {
      const img = new Image();
      img.onload = async () => {
        try {
          const MAX_DIM = 800;
          const MAX_BYTES = 200 * 1024;
          const scale = Math.min(1, MAX_DIM / img.width, MAX_DIM / img.height);
          const canvas = document.createElement("canvas");
          canvas.width  = Math.round(img.width  * scale);
          canvas.height = Math.round(img.height * scale);
          canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
          let dataUrl = canvas.toDataURL("image/jpeg", 0.05);
          for (let q = 0.85; q > 0.05; q = Math.round((q - 0.05) * 100) / 100) {
            const candidate = canvas.toDataURL("image/jpeg", q);
            if (candidate.length * 0.75 <= MAX_BYTES) { dataUrl = candidate; break; }
          }
          const blob = dataURLToBlob(dataUrl);
          const sRef = storageRef(storage, `products/${product.id}/photo.jpg`);
          // Bounded cache (NOT immutable): photo.jpg is overwritten in place on
          // a re-shoot, so cap staleness at 7 days instead of a year.
          await uploadBytes(sRef, blob, { contentType: "image/jpeg", cacheControl: "public, max-age=604800" });
          const url = await getDownloadURL(sRef);
          // photoUpdatedAt: upload-time stamp for the AI Photo Studio "Recent"
          // view. Only human uploads stamp it — an approved AI re-shoot isn't
          // a new upload, so approve() deliberately leaves it alone.
          await update(ref(database, `products/${product.id}`), { photoUrl: url, photoUpdatedAt: serverNowMs() });
        } catch (err) {
          console.error("photo upload failed:", err);
          alert("Failed to save photo. Please try again.");
        } finally {
          setPhotoUploading(false);
        }
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  };
  const removePhoto = async () => {
    if (!product.photoUrl) return;
    if (!window.confirm(`Remove the photo for "${product.name}"?`)) return;
    await update(ref(database, `products/${product.id}`), { photoUrl: null });
  };

  // Box photo (sneakers) — the shoe's own retail-box shot, attached to AI
  // Photo Studio HOUSE-STYLE generations so the AI reproduces the real box.
  // Gate on the SAME clothing test the backend uses (category OR productType),
  // not the size-logic `isClothing` above (productType only), so the slot never
  // shows for a category:"Clothing" item whose box the function would ignore.
  const isSneakerForBox = !(product.category === "Clothing" || (product.productType || "") === "clothing");
  const boxFileRef = useRef(null);
  const [boxUploading, setBoxUploading] = useState(false);
  const handleBoxFile = async (e) => {
    const file = e.target.files[0];
    e.target.value = "";
    if (!file) return;
    setBoxUploading(true);
    try { await uploadBoxPhoto(product.id, file); }
    catch (err) { console.error("box photo upload failed:", err); alert("Failed to save the box photo. Please try again."); }
    finally { setBoxUploading(false); }
  };
  const removeBoxPhoto = async () => {
    if (!product.photoBoxUrl) return;
    if (!window.confirm(`Remove the box photo for "${product.name}"?`)) return;
    await update(ref(database, `products/${product.id}`), { photoBoxUrl: null });
  };

  // Type — switching to Clothing strips Hub 1 (mirrors the Add Product
  // form's setProductType helper). Double-writes `hub` for back-compat per
  // the project-broadcast-api-async/14A double-write pattern.
  const setType = (nextType) => {
    if (nextType === (product.productType || "sneaker")) return;
    const patch = { productType: nextType };
    if (nextType === "clothing") {
      const stripped = productHubs.filter(h => h !== "hub1");
      patch.hubs = stripped.length ? stripped : ["hub2"];
      patch.hub  = patch.hubs[0];
      // Clothing never has a shoebox — clear the flag when converting.
      patch.hasShoeBoxOption = false;
    }
    update(ref(database, `products/${product.id}`), patch);
  };

  const toggleSize = (s) => {
    const next = productSizes.includes(s)
      ? productSizes.filter(x => x !== s)
      : [...productSizes, s];
    updateProductSizes(product.id, next);
    // GUARANTEE ON EDIT: mint barcodes for the (possibly new) size set so editing
    // a product never leaves a size without a code. Best-effort; idempotent
    // (ensureBarcode reuses any existing slot, only newly-added sizes get a code).
    ensureBarcodes(product.id, next.length ? next : [null]).catch(() => {});
  };

  const toggleHub = (h) => {
    if (isClothing && h === "hub1") return;
    const next = productHubs.includes(h)
      ? productHubs.filter(x => x !== h)
      : [...productHubs, h];
    if (next.length === 0) return; // require ≥1 hub
    updateProductHubs(product.id, next);
  };

  // POS Phase 2: local drafts for the two price fields so the input still
  // works while typing (decimals, partial values like "12."). Synced from
  // RTDB on mount and on external change, written back on blur. Empty input
  // → write null so the POS reader sees "not set" instead of 0.
  const [stockPriceDraft,  setStockPriceDraft]  = useState(typeof product.stockPrice  === "number" ? String(product.stockPrice)  : "");
  const [retailPriceDraft, setRetailPriceDraft] = useState(typeof product.retailPrice === "number" ? String(product.retailPrice) : "");
  useEffect(() => { setStockPriceDraft( typeof product.stockPrice  === "number" ? String(product.stockPrice)  : ""); }, [product.stockPrice]);
  useEffect(() => { setRetailPriceDraft(typeof product.retailPrice === "number" ? String(product.retailPrice) : ""); }, [product.retailPrice]);
  const savePrice = (field, draft) => {
    const trimmed = String(draft).trim();
    if (trimmed === "") {
      update(ref(database, `products/${product.id}`), { [field]: null })
        .catch(err => console.warn(`update ${field} failed:`, err));
      return;
    }
    const num = Number(trimmed);
    // Reject 0 (and negatives / NaN) — matching the create flow's `> 0` rule.
    // The POS contract is that prices are unset/null, never `0` (a free price
    // would mis-ring at checkout). Restore the previous value from RTDB.
    if (!Number.isFinite(num) || num <= 0) {
      if (field === "stockPrice")  setStockPriceDraft( typeof product.stockPrice  === "number" ? String(product.stockPrice)  : "");
      if (field === "retailPrice") setRetailPriceDraft(typeof product.retailPrice === "number" ? String(product.retailPrice) : "");
      return;
    }
    update(ref(database, `products/${product.id}`), { [field]: num })
      .catch(err => console.warn(`update ${field} failed:`, err));
  };
  const toggleShoebox = () => {
    if (isClothing) return; // clothing never has a shoebox
    const next = !(product.hasShoeBoxOption === true);
    update(ref(database, `products/${product.id}`), { hasShoeBoxOption: next })
      .catch(err => console.warn("update hasShoeBoxOption failed:", err));
  };

  // POS Phase 2 (scanner workflow): sku + barcode are auto-assigned at
  // create time (reserveNextSkuAndBarcode + addProduct) and are displayed
  // read-only here. Editing would break the sequential invariant the POS
  // scanner workflow depends on, so there are intentionally no setters.
  // Legacy / backfilled values appear here exactly as stored; products that
  // pre-date the backfill render as "—" until PR B's script runs.

  const handleDelete = () => {
    if (!window.confirm(`Delete "${product.name}"? This cannot be undone.`)) return;
    deleteProductFromFirebase(product.id);
    onBack();
  };

  // Activity line — "Last sold X days ago · N orders all-time" from
  // insights_log (orders/{id} is daily-counter-ephemeral so can't be trusted
  // for historical aggregates; see project-insights-past-days-pattern memory).
  const activity = useMemo(() => {
    const productLog = insightsLog.filter(e => e.productName === product.name);
    const placed     = productLog.filter(e => e.action === "placed");
    const sold       = productLog.filter(e => e.action === "collected" || e.action === "ready");
    let lastSoldLabel = "Never sold";
    if (sold.length > 0) {
      const ts = sold[0].timestamp; // log is sorted newest-first
      if (ts) {
        const daysAgo = Math.floor((serverNowMs() - new Date(ts).getTime()) / (24*60*60*1000));
        if (daysAgo <= 0)    lastSoldLabel = "Last sold today";
        else if (daysAgo === 1) lastSoldLabel = "Last sold yesterday";
        else                 lastSoldLabel = `Last sold ${daysAgo} days ago`;
      }
    }
    return `${lastSoldLabel} · ${placed.length} order${placed.length === 1 ? "" : "s"} all-time`;
  }, [insightsLog, product.name]);

  // Restock-existing (Stock rework): the same optional per-size receive as the
  // product-add form, for a product already in the system (re-orders arrive
  // constantly). Its own explicit action — independent of the edits above and
  // never required. Posts `received` movements into the default receiving
  // warehouse via applyMovement; soft-warns (no block) if the user lacks the
  // stockRole the rules require.
  const [recvOpen, setRecvOpen] = useState(false);
  const [recvQtys, setRecvQtys] = useState({});
  const [recvLoc, setRecvLoc] = useState(""); // destination — NO default; must be picked before receiving
  const [recvBusy, setRecvBusy] = useState(false);
  const [recvMsg,  setRecvMsg]  = useState(null);
  const [lastReceived, setLastReceived] = useState(null); // { productId, productName, items:[{size,added}] }
  const [printOpen, setPrintOpen] = useState(false);
  // Initial Distribution Wizard: opens after a receive into Central (every
  // receiving event qualifies — owner decision). Print sheet follows on close.
  const [distribOpen, setDistribOpen] = useState(false);
  const recvRegistry = useLocations();
  const flashRecv = (ok, text) => { setRecvMsg({ ok, text }); setTimeout(() => setRecvMsg(null), 4000); };
  const doReceive = async () => {
    const entries = productSizes
      .map(s => [s, parseInt(recvQtys[s], 10)])
      .filter(([, n]) => Number.isFinite(n) && n > 0);
    if (!entries.length) return;
    if (!recvLoc) return flashRecv(false, "Choose a destination location to receive into first.");
    setRecvBusy(true);
    let ok = 0, fail = 0; const savedItems = [];
    for (const [size, n] of entries) {
      const res = await applyMovement({ type: "received", productId: product.id, size, qty: n, to: recvLoc });
      if (res.ok) { ok++; savedItems.push({ size, added: n }); }
      else fail++;
    }
    setRecvBusy(false);
    setRecvQtys({});
    const locLabel = labelFor(recvLoc, recvRegistry);
    if (fail) flashRecv(false, `${ok} received, ${fail} failed — you may not have stock permission (stockRole).`);
    else flashRecv(true, `Received ${ok} size${ok > 1 ? "s" : ""} into ${locLabel}.`);
    if (savedItems.length) {
      setLastReceived({ productId: product.id, productName: product.name, photoUrl: product.photoUrl ?? null, items: savedItems });
      // Receive into Central → offer initial distribution first; print follows.
      if (recvLoc === "central") setDistribOpen(true);
      else setPrintOpen(true);
    }
  };

  const sectionTitle = { fontSize:12, fontWeight:600, color:"rgba(255,255,255,.5)", textTransform:"uppercase", letterSpacing:"0.06em", padding: isWide ? "14px 2px 8px" : "24px 18px 8px" };
  const card         = { background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.07)", borderRadius:14, margin: isWide ? 0 : "0 14px", overflow:"hidden" };
  const cardInner    = { padding:"14px 16px" };

  // Section cards — shared by the mobile column and the desktop two-column flow.
  const detailSections = (
    <>
      <div style={{ breakInside:"avoid" }}>
      {/* PHOTO */}
      <div style={sectionTitle}>Photo{photos.length > 1 ? ` · ${photos.length}` : ""}</div>
      <div style={card}>
        <div style={{ ...cardInner, display:"flex", alignItems:"center", gap:14 }}>
          <div onClick={photos.length ? () => setGalleryView(photos) : undefined}
               title={photos.length > 1 ? `View ${photos.length} photos` : (photos.length ? "View photo" : undefined)}
               style={{ cursor: photos.length ? "zoom-in" : "default" }}>
            <ProductPhoto url={product.photoUrl} photo={product.photo} size={140} radius={12}/>
          </div>
          <div style={{ flex:1, display:"flex", flexDirection:"column", gap:8 }}>
            <input ref={fileRef} type="file" accept="image/*" onChange={handlePhotoFile} style={{ display:"none" }} />
            <button onClick={() => fileRef.current?.click()} disabled={photoUploading}
                    style={{ background:"rgba(60,110,255,.12)", border:"1px solid rgba(60,110,255,.3)", color:"#4A7FFF", fontSize:14, fontWeight:600, padding:"10px 14px", borderRadius:10, cursor: photoUploading ? "not-allowed" : "pointer", textAlign:"center", opacity: photoUploading ? 0.5 : 1 }}>
              {photoUploading ? "Uploading…" : "Replace photo"}
            </button>
            {product.photoUrl && (
              <button onClick={removePhoto} disabled={photoUploading}
                      style={{ background:"rgba(180,40,40,.08)", border:"1px solid rgba(180,40,40,.25)", color:"#FF8888", fontSize:14, fontWeight:600, padding:"10px 14px", borderRadius:10, cursor: photoUploading ? "not-allowed" : "pointer", textAlign:"center", opacity: photoUploading ? 0.5 : 1 }}>
                Remove photo
              </button>
            )}
          </div>
        </div>
        {extras.length > 0 && (
          <div style={{ ...cardInner, paddingTop:0, display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
            <span style={{ fontSize:10, fontWeight:700, color:"rgba(255,255,255,.35)", letterSpacing:1 }}>EXTRA ANGLES</span>
            {extras.map((u, k) => (
              <img key={u} src={u} alt="" onClick={() => setGalleryView(photos.length ? photos : [u])}
                   style={{ width:46, height:46, objectFit:"cover", borderRadius:9, background:"#fff", border:"1px solid rgba(255,255,255,.12)", cursor:"zoom-in" }} />
            ))}
          </div>
        )}
        {/* BOX PHOTO — sneakers only. Attached automatically to house-style AI
            re-shoots so the generated scene shows the REAL retail box. */}
        {isSneakerForBox && (
          <div style={{ ...cardInner, display:"flex", alignItems:"center", gap:10, borderTop:"1px solid rgba(255,255,255,.05)", paddingTop:12 }}>
            {product.photoBoxUrl
              ? <img src={product.photoBoxUrl} alt="Box" onClick={() => setGalleryView([product.photoBoxUrl])}
                     style={{ width:46, height:46, objectFit:"cover", borderRadius:9, background:"#fff", border:"1px solid rgba(255,255,255,.12)", cursor:"zoom-in", flexShrink:0 }}/>
              : <span style={{ width:46, height:46, borderRadius:9, border:"1px dashed rgba(255,255,255,.22)", color:"rgba(255,255,255,.28)", fontSize:16, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>▣</span>}
            <span style={{ flex:1, minWidth:0 }}>
              <span style={{ display:"block", fontSize:12.5, fontWeight:600, color:"rgba(255,255,255,.8)" }}>Box photo</span>
              <span style={{ display:"block", fontSize:10.5, color:"rgba(255,255,255,.4)", marginTop:1 }}>Used by AI house-style shots to show the real retail box.</span>
            </span>
            <input ref={boxFileRef} type="file" accept="image/*" onChange={handleBoxFile} style={{ display:"none" }}/>
            <button onClick={() => boxFileRef.current?.click()} disabled={boxUploading}
                    style={{ background:"rgba(60,110,255,.12)", border:"1px solid rgba(60,110,255,.3)", color:"#4A7FFF", fontSize:12, fontWeight:600, padding:"8px 12px", borderRadius:9, cursor: boxUploading ? "not-allowed" : "pointer", opacity: boxUploading ? 0.5 : 1, flexShrink:0 }}>
              {boxUploading ? "Uploading…" : product.photoBoxUrl ? "Replace" : "＋ Add"}
            </button>
            {product.photoBoxUrl && (
              <button onClick={removeBoxPhoto} disabled={boxUploading}
                      style={{ background:"transparent", border:"1px solid rgba(180,40,40,.25)", color:"#FF8888", fontSize:12, fontWeight:600, padding:"8px 12px", borderRadius:9, cursor: boxUploading ? "not-allowed" : "pointer", flexShrink:0 }}>
                Remove
              </button>
            )}
          </div>
        )}
      </div>
      {galleryView && <GalleryLightbox photos={galleryView} onClose={() => setGalleryView(null)} />}

      {/* NAME */}

      </div>
      <div style={{ breakInside:"avoid" }}>
      <div style={sectionTitle}>Name</div>
      <div style={card}>
        <div style={cardInner}>
          <input value={nameDraft}
                 onChange={e => setNameDraft(e.target.value)}
                 onBlur={saveName}
                 onKeyDown={e => { if (e.key === "Enter") e.target.blur(); }}
                 style={{ width:"100%", background:"transparent", border:"none", outline:"none", color:"#fff", fontSize:17, fontWeight:500, padding:0, fontFamily:"inherit" }}/>
        </div>
      </div>

      {/* TYPE */}

      </div>
      <div style={{ breakInside:"avoid" }}>
      <div style={sectionTitle}>Type</div>
      <div style={card}>
        <div style={{ display:"flex", padding:"6px" }}>
          {[["sneaker","Sneaker"],["clothing","Clothing"]].map(([val, label]) => {
            const on = (product.productType || "sneaker") === val;
            return (
              <button key={val} onClick={() => setType(val)}
                      style={{ flex:1, padding:"10px 0", borderRadius:10, border:"none", cursor:"pointer", fontSize:14, fontWeight:600,
                               background: on ? "rgba(60,110,255,.18)" : "transparent",
                               color: on ? "#4A7FFF" : "rgba(255,255,255,.55)" }}>
                {label}
              </button>
            );
          })}
        </div>
      </div>

      {/* SIZES */}

      </div>
      <div style={{ breakInside:"avoid" }}>
      <div style={sectionTitle}>Available sizes</div>
      <div style={card}>
        <div style={{ ...cardInner, display:"flex", gap:6, flexWrap:"wrap" }}>
          {sizeChoices.map(s => {
            const on = productSizes.includes(s);
            return (
              <button key={s} onClick={() => toggleSize(s)}
                      style={{ padding:"7px 14px", borderRadius:8, border:`1px solid ${on ? "#4A7FFF" : "rgba(255,255,255,.1)"}`, background: on ? "rgba(60,110,255,.18)" : "rgba(255,255,255,.03)", color: on ? "#4A7FFF" : "rgba(255,255,255,.7)", cursor:"pointer", fontSize:13, fontWeight:600 }}><SizeTag size={s} /></button>
            );
          })}
        </div>
      </div>

      {/* RECEIVE STOCK (restock existing) — Stock rework. Optional per-size
          receive into a chosen location for a re-order; independent of the edits
          above, never required. Mirrors the product-add opening-stock section. */}

      </div>
      <div style={{ breakInside:"avoid" }}>
      <div style={sectionTitle}>Receive stock</div>
      <div style={card}>
        <div style={cardInner}>
          <button onClick={() => setRecvOpen(o => !o)}
            style={{ display:"flex", alignItems:"center", gap:8, width:"100%", textAlign:"left", background:"transparent", border:"none", color:"#bbb", cursor:"pointer", fontSize:13, fontWeight:600, padding:0 }}>
            <span style={{ color:"#6A9FFF", transform: recvOpen ? "rotate(90deg)" : "none", transition:"transform .15s", display:"inline-block" }}>▸</span>
            Add re-order quantities <span style={{ color:"#555", fontWeight:500, fontStyle:"italic" }}>· optional</span>
          </button>
          {recvOpen && (
            <div style={{ marginTop:14 }}>
              {/* Destination — required, no default. Must be picked before receiving. */}
              <div style={{ marginBottom:12 }}>
                <div style={{ fontSize:11, color:"#888", textTransform:"uppercase", letterSpacing:".04em", marginBottom:4 }}>Receive into <span style={{ color:"#F87171" }}>*required</span></div>
                <LocationPicker registry={recvRegistry} value={recvLoc} onChange={setRecvLoc} filter={transferTargets} />
              </div>
              {productSizes.length === 0 ? (
                <div style={{ color:"#666", fontSize:13 }}>Add sizes above first.</div>
              ) : (
                <SizeQtyGrid sizes={sizeChoices.filter(s => productSizes.includes(s))} values={recvQtys} onChange={(s, v) => setRecvQtys(q => ({ ...q, [s]: v }))} />
              )}
              <button onClick={doReceive} disabled={recvBusy || !recvLoc}
                style={{ ...bBlue, padding:"0.55rem 1.25rem", marginTop:14, opacity: (recvBusy || !recvLoc) ? 0.5 : 1 }}>
                {recvBusy ? "Receiving…" : recvLoc ? `Receive into ${labelFor(recvLoc, recvRegistry)}` : "Pick a destination first"}
              </button>
              {recvMsg && <div style={{ marginTop:10, fontSize:12.5, fontWeight:600, color: recvMsg.ok ? "#4ADE80" : "#FF9B9B" }}>{recvMsg.text}</div>}
              <div style={{ fontSize:11, color:"#666", marginTop:8 }}>
                Posts <span style={{ color:"#4ADE80" }}>received</span> movements; changes nothing else on this product.
              </div>
            </div>
          )}
        </div>
      </div>

      {/* PRICING — POS Phase 2. Two optional ZAR price inputs (saved on blur)
          plus a shoebox checkbox. Blank input is allowed and writes null. */}

      </div>
      <div style={{ breakInside:"avoid" }}>
      <div style={sectionTitle}>Pricing (ZAR)</div>
      <div style={card}>
        <div style={{ display:"flex", padding:"0", borderBottom:"1px solid rgba(255,255,255,.06)" }}>
          <div style={{ flex:1, padding:"14px 16px", borderRight:"1px solid rgba(255,255,255,.06)" }}>
            <div style={{ fontSize:11, color:"rgba(255,255,255,.45)", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:4 }}>Stock Price</div>
            <input type="number" inputMode="decimal" min="0" step="0.01" placeholder="—"
                   value={stockPriceDraft}
                   onChange={e => setStockPriceDraft(e.target.value)}
                   onBlur={() => savePrice("stockPrice", stockPriceDraft)}
                   onKeyDown={e => { if (e.key === "Enter") e.target.blur(); }}
                   style={{ width:"100%", background:"transparent", border:"none", outline:"none", color:"#fff", fontSize:17, fontWeight:500, padding:0, fontFamily:"inherit" }}/>
          </div>
          <div style={{ flex:1, padding:"14px 16px" }}>
            <div style={{ fontSize:11, color:"rgba(255,255,255,.45)", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:4 }}>Retail Price</div>
            <input type="number" inputMode="decimal" min="0" step="0.01" placeholder="—"
                   value={retailPriceDraft}
                   onChange={e => setRetailPriceDraft(e.target.value)}
                   onBlur={() => savePrice("retailPrice", retailPriceDraft)}
                   onKeyDown={e => { if (e.key === "Enter") e.target.blur(); }}
                   style={{ width:"100%", background:"transparent", border:"none", outline:"none", color:"#fff", fontSize:17, fontWeight:500, padding:0, fontFamily:"inherit" }}/>
          </div>
        </div>
        {/* Shoebox option — sneakers only; clothing never ships with one. */}
        {!isClothing && (
        <div onClick={toggleShoebox}
             style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"14px 16px", cursor:"pointer" }}>
          <div style={{ fontSize:15, color:"#fff", fontWeight:500 }}>Shoebox option</div>
          <div style={{
            width:24, height:24, borderRadius:6,
            background: product.hasShoeBoxOption === true ? "#4A7FFF" : "rgba(255,255,255,.06)",
            border:     product.hasShoeBoxOption === true ? "none" : "1px solid rgba(255,255,255,.18)",
            display:"flex", alignItems:"center", justifyContent:"center",
          }}>
            {product.hasShoeBoxOption === true && (
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="20 6 9 17 4 12"/>
              </svg>
            )}
          </div>
        </div>
        )}
      </div>

      {/* IDENTIFIERS — POS Phase 2 (scanner workflow). Read-only display of
          the sku + barcode auto-assigned at create time. Editing is
          intentionally not exposed: a manual change would break the
          sequential invariant the POS scanner workflow depends on. Legacy
          products that pre-date the backfill render "—" until PR B runs. */}

      </div>
      <div style={{ breakInside:"avoid" }}>
      <div style={sectionTitle}>Identifiers</div>
      <div style={card}>
        <div style={{ display:"flex", padding:"0" }}>
          <div style={{ flex:1, padding:"14px 16px", borderRight:"1px solid rgba(255,255,255,.06)" }}>
            <div style={{ fontSize:11, color:"rgba(255,255,255,.45)", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:4 }}>Barcode</div>
            <div style={{ color:"#fff", fontSize:17, fontWeight:500, fontFamily:"'SF Mono', Menlo, monospace" }}>
              {(typeof product.barcode === "string" && product.barcode.trim().length > 0) ? product.barcode : "—"}
            </div>
          </div>
          <div style={{ flex:1, padding:"14px 16px" }}>
            <div style={{ fontSize:11, color:"rgba(255,255,255,.45)", textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:4 }}>SKU</div>
            <div style={{ color:"#fff", fontSize:17, fontWeight:500, fontFamily:"'SF Mono', Menlo, monospace" }}>
              {(typeof product.sku === "string" && product.sku.trim().length > 0) ? product.sku : "—"}
            </div>
          </div>
        </div>
      </div>

      {/* HUBS — iOS-style grouped list */}

      </div>
      <div style={{ breakInside:"avoid" }}>
      <div style={sectionTitle}>Hubs</div>
      <div style={card}>
        {[["hub1","Hub 1"],["hub2","Hub 2"],["hub3","Hub 3 — Pine"]].map(([val, label], i) => {
          const disabled = isClothing && val === "hub1";
          const on       = productHubs.includes(val) && !disabled;
          const isLast   = i === 2;
          return (
            <div key={val}>
              <div onClick={() => !disabled && toggleHub(val)}
                   style={{
                     display:"flex", alignItems:"center", justifyContent:"space-between",
                     padding:"14px 16px",
                     cursor: disabled ? "not-allowed" : "pointer",
                     opacity: disabled ? 0.4 : 1,
                   }}>
                <div style={{ fontSize:15, color:"#fff", fontWeight:500 }}>{label}</div>
                <div style={{
                  width:24, height:24, borderRadius:6,
                  background: on ? "#4A7FFF" : "rgba(255,255,255,.06)",
                  border: on ? "none" : "1px solid rgba(255,255,255,.18)",
                  display:"flex", alignItems:"center", justifyContent:"center",
                }}>
                  {on && (
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                      <polyline points="20 6 9 17 4 12"/>
                    </svg>
                  )}
                </div>
              </div>
              {!isLast && <div style={{ height:1, background:"rgba(255,255,255,.06)", margin:"0 16px" }}/>}
            </div>
          );
        })}
      </div>
      {isClothing && (
        <div style={{ padding:"8px 18px 0", fontSize:12, color:"rgba(255,255,255,.4)", fontStyle:"italic" }}>
          Clothing cannot be stocked at Hub 1.
        </div>
      )}

      {/* DELETE */}
      <div style={{ height:1, background:"rgba(255,255,255,.08)", margin:"32px 14px 16px" }}/>
      <div style={{ padding:"0 14px 28px" }}>
        <button onClick={handleDelete}
                style={{ width:"100%", background:"rgba(220,38,38,.1)", border:"1px solid rgba(220,38,38,.35)", color:"#F87171", fontSize:15, fontWeight:600, padding:"14px", borderRadius:12, cursor:"pointer" }}>
          Delete product
        </button>
      </div>

      {/* Initial Distribution Wizard — after a receive into Central. Closing
          it (skip or done) opens the print sheet. */}
      {distribOpen && (
        <InitialDistributionWizard
          product={product}
          onClose={() => { setDistribOpen(false); setPrintOpen(true); }}
        />
      )}
      {/* Inline Print-barcodes sheet (#73), surfaced after a re-order receive. */}
      {printOpen && lastReceived && (
        <BarcodePrint
          product={{ id: lastReceived.productId, name: lastReceived.productName, photoUrl: lastReceived.photoUrl }}
          items={lastReceived.items}
          onClose={() => setPrintOpen(false)}
        />
      )}
      </div>
    </>
  );
  // Two-column CSS multi-column on desktop (each section kept intact via
  // break-inside), single column on mobile.
  const detailColumns = (
    <div style={{ columnCount: isWide ? 2 : 1, columnGap: 28 }}>
      {detailSections}
    </div>
  );

  // ── DESKTOP WORKSPACE (>=1024px) — rail with product summary + main pane. ──
  if (isWide) {
    return (
      <div style={{ height:"100vh", maxHeight:"100dvh", background:"#000", color:"#f3f6ff", fontFamily:FONT, display:"grid", gridTemplateColumns:"250px minmax(0,1fr)", overflow:"hidden" }}>
        {/* RAIL */}
        <aside style={{ background:"rgba(255,255,255,.015)", borderRight:"1px solid rgba(255,255,255,.08)", padding:"22px 15px 18px", display:"flex", flexDirection:"column", gap:12, overflow:"auto" }}>
          <div style={{ display:"flex", alignItems:"baseline", gap:8, padding:"0 3px" }}>
            <span style={{ fontSize:19, fontWeight:800, fontStyle:"italic", letterSpacing:-.6 }}>marathon</span>
            <span style={{ fontSize:9.5, fontWeight:700, letterSpacing:5, color:"#4A7FFF" }}>CLUB</span>
          </div>
          <button onClick={onBack} style={{ display:"flex", alignItems:"center", gap:7, background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.08)", color:"rgba(233,238,255,.65)", borderRadius:10, padding:"9px 12px", fontSize:12.5, fontWeight:600, cursor:"pointer", fontFamily:FONT }}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
            All products
          </button>
          <div style={{ display:"flex", justifyContent:"center", padding:"4px 0" }}>
            <div onClick={photos.length ? () => setGalleryView(photos) : undefined} style={{ cursor: photos.length ? "zoom-in" : "default" }}>
              <ProductPhoto url={product.photoUrl} photo={product.photo} size={168} radius={16}/>
            </div>
          </div>
          <div>
            <div style={{ fontSize:15, fontWeight:800, color:"#fff", lineHeight:1.25 }}>{product.name}</div>
            <div style={{ fontSize:11.5, color:"rgba(233,238,255,.45)", marginTop:5, lineHeight:1.4 }}>{activity}</div>
          </div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
            <span style={{ fontSize:10.5, fontWeight:700, color:"#9DBCFF", background:"rgba(74,127,255,.12)", border:"1px solid rgba(74,127,255,.25)", borderRadius:7, padding:"3px 9px", textTransform:"capitalize" }}>{product.productType || "sneaker"}</span>
            <span style={{ fontSize:10.5, fontWeight:700, color:"rgba(233,238,255,.6)", background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.1)", borderRadius:7, padding:"3px 9px" }}>{productSizes.length} size{productSizes.length !== 1 ? "s" : ""}</span>
            <span style={{ fontSize:10.5, fontWeight:700, color:"rgba(233,238,255,.6)", background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.1)", borderRadius:7, padding:"3px 9px" }}>{productHubs.length} hub{productHubs.length !== 1 ? "s" : ""}</span>
          </div>
          <div style={{ flex:1 }} />
          <button onClick={handleDelete} style={{ background:"rgba(220,38,38,.1)", border:"1px solid rgba(220,38,38,.35)", color:"#F87171", fontSize:12.5, fontWeight:700, padding:"10px", borderRadius:11, cursor:"pointer", fontFamily:FONT }}>Delete product</button>
        </aside>
        {/* MAIN */}
        <div style={{ minWidth:0, display:"flex", flexDirection:"column", overflow:"hidden" }}>
          <div style={{ padding:"20px 32px 16px", borderBottom:"1px solid rgba(255,255,255,.08)", background:"radial-gradient(800px 280px at 15% -60%, rgba(74,127,255,.08), transparent)" }}>
            <div style={{ fontSize:23, fontWeight:800, letterSpacing:-.4, lineHeight:1.2 }}>{product.name}</div>
            <div style={{ fontSize:12.5, color:"rgba(233,238,255,.55)", marginTop:3 }}>{activity}</div>
          </div>
          <div style={{ flex:1, overflow:"auto", padding:"14px 32px 48px" }}>
            <div style={{ maxWidth:980, margin:"0 auto" }}>
              {detailColumns}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      {/* TOP BAR with back chevron */}
      <div style={{ padding:"44px 8px 8px", display:"flex", alignItems:"center" }}>
        <button onClick={onBack}
                style={{ display:"flex", alignItems:"center", gap:4, background:"transparent", border:"none", color:"#4A7FFF", fontSize:15, fontWeight:500, cursor:"pointer", padding:"6px 10px" }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="15 18 9 12 15 6"/>
          </svg>
          Products
        </button>
      </div>

      {/* HEADER */}
      <div style={{ padding:"4px 18px 8px" }}>
        <div style={{ fontSize:22, fontWeight:700, color:"#fff", lineHeight:1.2 }}>{product.name}</div>
        <div style={{ fontSize:13, color:"rgba(255,255,255,.45)", marginTop:6 }}>{activity}</div>
      </div>

      {detailColumns}
    </div>
  );
}

// ─── ASSISTANT VIEW ───────────────────────────────────────────────────────────
// Multi-item cart flow:
//   1. Tap product → size picker sheet → "Add to Cart"
//   2. Repeat for more items, or tap "Checkout"
//   3. Checkout sheet: review cart, enter customer details once, Place Order
//   4. One Firebase order per cart item, own order number + WA message each.
// ─── ASSISTANT: CLOTHING PRODUCT CARD (Phase 12B) ─────────────────────────────
// Renders one clothing product with per-size qty steppers. Each card owns its
// own draft qty state. Tapping "Add to Cart" reports cart lines back to the
// parent (one per non-zero size) and resets the draft to zeros.
function ClothingCard({ product, onAdd, onViewPhoto }) {
  const sizes = Array.isArray(product.sizes) ? product.sizes : [];
  // Initial state: every available size starts at 0.
  const [qty, setQty] = useState(() => sizes.reduce((m, s) => (m[s] = 0, m), {}));
  // If the product's size list changes (admin edit), preserve any existing
  // counts for sizes that remain and zero out the rest.
  useEffect(() => {
    setQty(prev => sizes.reduce((m, s) => (m[s] = prev[s] || 0, m), {}));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sizes.join("|")]);

  const total = Object.values(qty).reduce((n, v) => n + (v || 0), 0);
  const bump = (sz, delta) => setQty(prev => ({ ...prev, [sz]: Math.max(0, (prev[sz] || 0) + delta) }));
  const handleAdd = () => {
    const lines = Object.entries(qty)
      .filter(([, n]) => n > 0)
      .map(([size, n]) => ({ product, size, qty: n, productType: "clothing" }));
    if (lines.length === 0) return;
    onAdd(lines);
    setQty(sizes.reduce((m, s) => (m[s] = 0, m), {}));
  };

  return (
    <div style={{ background:"rgba(255,255,255,.03)", border:"1px solid rgba(255,255,255,.06)", borderRadius:12, overflow:"hidden" }}>
      <div style={{ display:"flex", gap:12, padding:"12px 13px 0" }}>
        <div onClick={product.photoUrl && onViewPhoto ? () => onViewPhoto(productPhotos(product)) : undefined}
             title={product.photoUrl ? (product.gallery?.length ? `View ${productPhotos(product).length} photos` : "View full photo") : undefined}
             style={{ position:"relative", width:96, height:96, flexShrink:0, background:"rgba(255,255,255,.05)", borderRadius:10, overflow:"hidden", display:"flex", alignItems:"center", justifyContent:"center", cursor: product.photoUrl && onViewPhoto ? "zoom-in" : "default" }}>
          {product.photoUrl
            ? <img src={product.photoUrl} alt={product.name} style={{ width:"100%", height:"100%", objectFit:"cover" }}/>
            : <span style={{ fontSize:36 }}>{product.photo}</span>}
          {product.gallery?.length > 0 && (
            <span style={{ position:"absolute", bottom:5, left:5, display:"inline-flex", alignItems:"center", gap:3, background:"rgba(0,0,0,.6)", color:"#fff", fontSize:10, fontWeight:600, padding:"2px 6px", borderRadius:999 }}>
              <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>
              {productPhotos(product).length}
            </span>
          )}
        </div>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontSize:15, fontWeight:700, color:"#fff", marginBottom:8 }}>{product.name}</div>
          <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
            {sizes.map(sz => {
              const n = qty[sz] || 0;
              return (
                <div key={sz} style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <div style={{ minWidth:42, padding:"3px 8px", borderRadius:7, background:"rgba(60,110,255,.1)", border:"1px solid rgba(60,110,255,.25)", color:BLUE_L, fontSize:12, fontWeight:700, textAlign:"center" }}><SizeTag size={sz} /></div>
                  <button onClick={() => bump(sz, -1)} disabled={n === 0}
                    style={{ width:28, height:28, borderRadius:7, border:"1px solid rgba(255,255,255,.12)", background: n === 0 ? "rgba(255,255,255,.02)" : "rgba(60,110,255,.08)", color: n === 0 ? "rgba(255,255,255,.25)" : BLUE_L, fontSize:16, fontWeight:700, cursor: n === 0 ? "not-allowed" : "pointer", display:"flex", alignItems:"center", justifyContent:"center", lineHeight:1 }}>
                    −
                  </button>
                  <div style={{ minWidth:24, textAlign:"center", fontSize:14, fontWeight:700, color: n > 0 ? "#fff" : "rgba(255,255,255,.4)" }}>{n}</div>
                  <button onClick={() => bump(sz, 1)}
                    style={{ width:28, height:28, borderRadius:7, border:"1px solid rgba(60,110,255,.35)", background:"rgba(60,110,255,.12)", color:BLUE_L, fontSize:16, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", lineHeight:1 }}>
                    +
                  </button>
                </div>
              );
            })}
            {sizes.length === 0 && (
              <div style={{ color:"rgba(255,255,255,.4)", fontSize:12, fontStyle:"italic" }}>No sizes set up for this product yet.</div>
            )}
          </div>
        </div>
      </div>
      <div style={{ padding:"10px 13px 12px" }}>
        <button onClick={handleAdd} disabled={total === 0}
          style={{ width:"100%", padding:"9px 12px", borderRadius:10, fontSize:13, fontWeight:700, cursor: total === 0 ? "not-allowed" : "pointer",
                   background: total === 0 ? "rgba(255,255,255,.03)" : "rgba(0,150,70,.2)",
                   border: total === 0 ? "1px solid rgba(255,255,255,.06)" : "1px solid rgba(0,180,80,.4)",
                   color: total === 0 ? "rgba(255,255,255,.3)" : "#4ADE80",
                   display:"flex", alignItems:"center", justifyContent:"center", gap:6 }}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
          {total === 0 ? "Add quantities to add" : `Add ${total} item${total !== 1 ? "s" : ""} to cart`}
        </button>
      </div>
    </div>
  );
}

// ─── SHOP STOCK (read-only) ───────────────────────────────────────────────────
// Splits the old single shop view into the three physical shops — Marathon PE,
// Trophy, Pine — each reading its OWN /stock/{shopId} location (the sellable
// store locations from the registry: marathon-pe / trophy / marathon-pine). This
// is visibility ONLY: per-size on-hand per shop, no writes, no movement logic,
// and entirely separate from the Central/Pine order-routing toggle (which is
// unchanged). Reads the same /stock cells the Set Qty / Locator / POS use, so the
// numbers can't disagree.
function ShopStockList({ shopId, products, registry }) {
  const cells = useStockCells(shopId);   // /stock/{shopId} → { pid: { size: cell } }
  const rows = useMemo(() => {
    return [...(products || [])]
      .filter(p => p && p.id && p.name && cells?.[p.id])
      .map(p => {
        const bySize = cells[p.id] || {};
        const sizes = Object.keys(bySize)
          .map(sz => ({ sz, qty: typeof bySize[sz]?.qty === "number" ? bySize[sz].qty : 0 }))
          .sort((a, b) => String(a.sz).localeCompare(String(b.sz), undefined, { numeric: true }));
        return { id: p.id, name: p.name, sizes, total: sizes.reduce((s, x) => s + x.qty, 0) };
      })
      .filter(r => r.sizes.length > 0)
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [cells, products]);

  if (!rows.length) {
    return (
      <div style={{ color:"rgba(255,255,255,.4)", fontSize:12.5, textAlign:"center", padding:"16px 8px" }}>
        No stock recorded at {labelFor(shopId, registry)} yet.
      </div>
    );
  }
  return (
    <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
      {rows.map(r => (
        <div key={r.id} style={{ background:"rgba(255,255,255,.03)", border:"1px solid rgba(60,110,255,.15)", borderRadius:10, padding:"9px 11px" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", marginBottom:5 }}>
            <span style={{ color:"#fff", fontSize:13, fontWeight:600 }}>{r.name}</span>
            <span style={{ color:"rgba(255,255,255,.45)", fontSize:11 }}>{r.total} on hand</span>
          </div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
            {r.sizes.map(({ sz, qty }) => (
              <span key={sz} style={{ fontSize:11, color: qty > 0 ? "#fff" : "rgba(255,255,255,.35)",
                background: qty > 0 ? "rgba(60,110,255,.12)" : "rgba(255,255,255,.03)",
                border:"1px solid rgba(60,110,255,.18)", borderRadius:7, padding:"2px 7px" }}>
                <SizeTag size={sz} />: {qty}
              </span>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

function ShopStockPanel({ products }) {
  const [open, setOpen] = useState(false);
  const registry = useLocations();
  const shops = sellableLocations(registry);   // marathon-pe, trophy, marathon-pine
  const [shopId, setShopId] = useState(() => shops[0]?.id || "marathon-pe");
  useEffect(() => {
    if (shops.length && !shops.some(s => s.id === shopId)) setShopId(shops[0].id);
  }, [shops, shopId]);

  return (
    <div style={{ padding:"0 14px 8px" }}>
      <button onClick={() => setOpen(o => !o)}
        style={{ width:"100%", display:"flex", alignItems:"center", justifyContent:"space-between",
                 background:"rgba(255,255,255,.04)", border:"1px solid rgba(60,110,255,.25)", borderRadius:12,
                 padding:"10px 14px", color:"#fff", cursor:"pointer", fontSize:12.5, fontWeight:700 }}>
        <span>Shop stock <span style={{ color:"rgba(255,255,255,.4)", fontWeight:500 }}>· view only</span></span>
        <span style={{ color:"#6A9FFF", transform: open ? "rotate(90deg)" : "none", transition:"transform .15s" }}>▸</span>
      </button>
      {open && (
        <div style={{ marginTop:8 }}>
          {/* Three shops — the split of the old single combined view. Each reads
              its own /stock location below. */}
          <div style={{ display:"flex", justifyContent:"center", marginBottom:10 }}>
            <div style={{ display:"flex", background:"rgba(255,255,255,.04)", border:"1px solid rgba(60,110,255,.25)", borderRadius:12, padding:3, gap:2 }}>
              {shops.map(s => {
                const on = shopId === s.id;
                return (
                  <button key={s.id} onClick={() => setShopId(s.id)}
                    style={{ padding:"6px 16px", borderRadius:9, border:"none", cursor:"pointer", fontSize:11.5, fontWeight:700,
                             background: on ? "rgba(60,110,255,.25)" : "transparent",
                             color: on ? "#fff" : "rgba(255,255,255,.5)" }}>
                    {labelFor(s.id, registry)}
                  </button>
                );
              })}
            </div>
          </div>
          <ShopStockList shopId={shopId} products={products} registry={registry} />
        </div>
      )}
    </div>
  );
}

// ── REFILL TRACKING CARD ──────────────────────────────────────────────────────
// Read-only status view for the requesting shop. After a store places a CR
// (Clothing Refill) request the staff were "blind" — the confirmation banner is
// transient and gone on reload, and all live status lived on the warehouse side.
// This card reads the SAME /orders the warehouse resolves (customerName ===
// "Shop Refill", scoped to this shop) and surfaces each line's status so staff can
// see what's ready, what's still pending, and what the warehouse couldn't fill.
//   clothingRefillStatus:  null → Pending  ·  "available" → Ready  ·  "outOfStock" → Out of stock
const REFILL_STATUS = {
  pending: { label: "Pending",      fg: "#F5C451", bg: "rgba(245,196,81,.12)",  bd: "rgba(245,196,81,.35)" },
  ready:   { label: "Ready",        fg: "#4ADE80", bg: "rgba(74,222,128,.12)",  bd: "rgba(74,222,128,.4)"  },
  oos:     { label: "Rejected",     fg: "#FF8B8B", bg: "rgba(255,90,90,.12)",   bd: "rgba(255,90,90,.4)"   },
};
const refillStatusOf = (o) => {
  const st = o.clothingRefillStatus;
  return st === "available" ? "ready" : (st === "rejected" || st === "outOfStock") ? "oos" : "pending";
};

// One collapsible card per product (Marathon Glass, matching Source/Clothing-Sold):
// photo (tap → shared lightbox) + name + status-count chips; expand for per-size
// status rows. Waiting-on (pending) sizes first.
function RefillTrackingProductCard({ group, onViewPhoto }) {
  // Auto-open while the shop has pending lines; a manual toggle overrides until
  // the pending state CHANGES (new request / resolution), which resets the
  // override so fresh activity is never hidden behind a stale collapse.
  const [userOpen, setUserOpen] = useState(null);
  const hasPending = group.counts.pending > 0;
  useEffect(() => { setUserOpen(null); }, [hasPending]);
  const open = userOpen ?? hasPending;
  const setOpen = (fn) => setUserOpen(prev => fn(prev ?? hasPending));
  const hasPhotos = onViewPhoto && group.photos.length > 0;

  // Combine identical (size, status) lines — a shop that re-requested the same
  // size across days shows as ONE chip with the summed qty — then lay them out
  // sideways (wrap) instead of a long vertical run. Pending first, then ready,
  // then rejected.
  const combined = useMemo(() => {
    const map = new Map();
    for (const r of group.lines) {
      const key = `${r.size}__${r.status}`;
      if (!map.has(key)) map.set(key, { key, size: r.size, status: r.status, qty: 0, sent: 0, sentUnknown: false });
      const c = map.get(key);
      c.qty += r.qty;
      if (r.status === "ready") { if (r.sentQty == null) c.sentUnknown = true; else c.sent += r.sentQty; }
    }
    const rank = { pending: 0, ready: 1, oos: 2 };
    return [...map.values()].sort((a, b) => rank[a.status] - rank[b.status]);
  }, [group.lines]);
  return (
    <div style={{ background:CARD, border:"1px solid rgba(60,110,255,.45)", borderRadius:RADIUS, boxShadow:"0 0 10px rgba(60,110,255,.12)", overflow:"hidden" }}>
      <div style={{ display:"flex", alignItems:"center", gap:11, padding:11 }}>
        <div onClick={hasPhotos ? (e) => { e.stopPropagation(); onViewPhoto(group.photos); } : undefined}
             title={hasPhotos ? "Tap to enlarge" : undefined}
             style={{ position:"relative", flexShrink:0, cursor: hasPhotos ? "zoom-in" : "default", borderRadius:10 }}>
          <ProductPhoto url={group.photoUrl} photo={group.photo} size={48} radius={10}/>
          {hasPhotos && (
            <div style={{ position:"absolute", right:-4, bottom:-4, width:18, height:18, borderRadius:9, background:"rgba(4,5,10,.9)", border:"1px solid rgba(60,110,255,.5)", display:"flex", alignItems:"center", justifyContent:"center" }}>
              <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#6A9FFF" strokeWidth="2.5" strokeLinecap="round"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
            </div>
          )}
        </div>
        <div onClick={() => setOpen(o => !o)} style={{ flex:1, minWidth:0, cursor:"pointer" }}>
          <div style={{ fontSize:14, fontWeight:700, color:"#fff", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{group.name}</div>
          <div style={{ display:"flex", gap:5, marginTop:5, flexWrap:"wrap" }}>
            {(["pending","ready","oos"]).filter(k => group.counts[k] > 0).map(k => (
              <span key={k} style={{ fontSize:10.5, fontWeight:700, color:REFILL_STATUS[k].fg, background:REFILL_STATUS[k].bg, border:`1px solid ${REFILL_STATUS[k].bd}`, borderRadius:999, padding:"2px 8px" }}>
                {group.counts[k]} {REFILL_STATUS[k].label}
              </span>
            ))}
          </div>
        </div>
        <span onClick={() => setOpen(o => !o)} style={{ color:"#4A7FFF", transform: open ? "rotate(90deg)" : "none", transition:"transform .15s", fontSize:14, cursor:"pointer", padding:"0 4px" }}>▸</span>
      </div>
      {open && (
        <div style={{ padding:"2px 11px 10px", display:"flex", flexWrap:"wrap", gap:6, borderTop:"1px solid rgba(255,255,255,.06)" }}>
          {combined.map(c => {
            const s = REFILL_STATUS[c.status];
            const qtyText = c.status === "ready"
              ? (c.sentUnknown || c.sent >= c.qty ? `✓${c.qty}` : `✓${c.sent}/${c.qty}`)
              : c.status === "oos" ? `✕${c.qty}` : `×${c.qty}`;
            return (
              <span key={c.key} title={s.label}
                    style={{ display:"inline-flex", alignItems:"center", gap:5, fontSize:12, fontWeight:700, color:s.fg, background:s.bg, border:`1px solid ${s.bd}`, borderRadius:8, padding:"4px 9px" }}>
                <SizeTag size={c.size} /><span style={{ fontSize:10.5 }}>{qtyText}</span>
              </span>
            );
          })}
        </div>
      )}
    </div>
  );
}

function RefillTrackingCard({ orders = [], shop, registry, products = [], onViewPhoto, showEmpty = false }) {
  const groups = useMemo(() => {
    const rank = { pending: 0, oos: 1, ready: 2 };
    const byProduct = new Map();
    (orders || [])
      .filter(o => o && o.customerName === "Shop Refill" && o.destShop === shop)
      .forEach(o => {
        const status = refillStatusOf(o);
        const ts = (status === "ready" ? o.clothingRefilledAt : status === "oos" ? o.clothingOutOfStockAt : o.createdAt) || o.createdAt;
        if (!byProduct.has(o.productId)) {
          const product = (products || []).find(p => p.id === o.productId);
          byProduct.set(o.productId, {
            productId: o.productId, name: o.productName,
            photoUrl: o.productPhotoUrl, photo: o.productPhoto,
            photos: product ? productPhotos(product) : (o.productPhotoUrl ? [o.productPhotoUrl] : []),
            lines: [], counts: { pending: 0, ready: 0, oos: 0 }, latestTs: ts,
          });
        }
        const g = byProduct.get(o.productId);
        g.lines.push({ id: o.id, size: o.size, qty: o.qty || 1, sentQty: o.clothingRefilledQty ?? null, status, ts });
        g.counts[status]++;
        if (String(ts) > String(g.latestTs)) g.latestTs = ts;
      });
    const list = [...byProduct.values()];
    list.forEach(g => g.lines.sort((a, b) => (rank[a.status] - rank[b.status]) || String(b.ts).localeCompare(String(a.ts))));
    // Products with pending lines first (what the shop is waiting on), then recent.
    list.sort((a, b) => (Number(b.counts.pending > 0) - Number(a.counts.pending > 0)) || String(b.latestTs).localeCompare(String(a.latestTs)));
    return list.slice(0, 30);
  }, [orders, shop, products]);

  if (groups.length === 0) {
    if (!showEmpty) return null;
    return (
      <div style={{ textAlign:"center", padding:"3rem 1rem" }}>
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeOpacity="0.4" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M16 4l-4 4-4-4M3 7l5-3h8l5 3M3 7v13a1 1 0 001 1h16a1 1 0 001-1V7M3 7l4 4M21 7l-4 4"/></svg>
        <div style={{ fontSize:"0.95rem", marginTop:"0.75rem", color:"rgba(255,255,255,.55)" }}>No refill requests yet.</div>
        <div style={{ fontSize:"0.8rem", color:"#333", marginTop:"0.4rem" }}>Placed refills will show their live status here.</div>
      </div>
    );
  }

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
      {groups.map(g => <RefillTrackingProductCard key={g.productId} group={g} onViewPhoto={onViewPhoto} />)}
    </div>
  );
}

// Full-screen TRACKING PAGE (shop side) — reached via the "Track requests" button
// in the CR tab, not inlined there. Header + back, then the per-product status
// cards. Sits under the GalleryLightbox (z 2000) so photo taps still enlarge.
function RefillTrackingPage({ orders, shop, registry, products, onViewPhoto, onClose }) {
  return (
    <div style={{ position:"fixed", inset:0, zIndex:1500, background:BG, overflowY:"auto", fontFamily:FONT }}>
      <div style={{ position:"sticky", top:0, zIndex:1, background:"rgba(0,0,0,.85)", backdropFilter:"blur(14px)", WebkitBackdropFilter:"blur(14px)", borderBottom:"1px solid rgba(60,110,255,.2)", display:"flex", alignItems:"center", gap:10, padding:"14px 14px" }}>
        <button onClick={onClose} aria-label="Back"
                style={{ width:34, height:34, borderRadius:10, border:"1px solid rgba(60,110,255,.35)", background:"rgba(60,110,255,.1)", color:"#9CB8FF", fontSize:16, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
          ←
        </button>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontSize:14, fontWeight:800, color:"#fff", letterSpacing:".02em" }}>Refill tracking</div>
          <div style={{ fontSize:10.5, color:"rgba(255,255,255,.45)" }}>{labelFor(shop, registry)} · live status &amp; availability</div>
        </div>
      </div>
      <div style={{ padding:"12px 13px 40px" }}>
        <RefillTrackingCard orders={orders} shop={shop} registry={registry} products={products} onViewPhoto={onViewPhoto} showEmpty />
      </div>
    </div>
  );
}

// ─── ASSISTANT · DESKTOP WORKSPACE ────────────────────────────────────────────
// Full-screen laptop layout (AI Studio shell): sidebar (shop + flow) · sneaker
// catalog (search · brand-from-data · sort · hover quick-add) · live order drawer
// · quick-view stage. Rendered by AssistantView only when NOT narrow; phone/iPad
// keep the existing tap→sheet flow. Reuses AssistantView's cart + checkout via
// props (onQuickAdd/onRemoveOne/onCheckout); clothing is CR-only, so the catalog
// is sneakers only. Committed dark — the POS's world.
function AssistantDesktop({ products, effectiveShop, availableShops, onSelectShop, shopRegistry,
                            search, setSearch, cart, onQuickAdd, onRemoveOne, onAddDisplayPartner,
                            onViewPhoto, onSwitchView, onSignOut, userEmail, mode, setMode,
                            customerName, setCustomerName, customerPhone, setCustomerPhone,
                            marketingOptIn, setMarketingOptIn, submitting, onPlaceOrder,
                            customerIndex, onPickCustomer,
                            onAddClothing, onPlaceRefill, onOpenTracking, trackingPending,
                            hubQty, servingHubLabel }) {
  const flow = mode === "cr" ? "refill" : "order";   // the two workspace flows
  // Clothing customer mode: same "order" flow as sneakers, but browsing the
  // clothing catalog with live per-size availability at the serving CR hub
  // (hubQty/servingHubLabel from AssistantView) greying out zero-stock sizes.
  const clothingOrder = mode === "clothing";
  // Cart units of a clothing product+size — mirrors AssistantView's helper so
  // the quick-view can explain adds blocked by cart-vs-hub availability.
  const clothingInCart = (pid, size) =>
    (cart || []).filter(l => l.productType === "clothing" && l.product?.id === pid && l.size === size).length;
  const [brand, setBrand] = useState("All");
  const [sort, setSort]   = useState("feat");
  const [qv, setQv]       = useState(null);   // quick-view product
  const [qvSize, setQvSize] = useState(null);
  const [qvQty, setQvQty] = useState(1);
  const [qvDP, setQvDP]   = useState(false);  // request Display Partner (sneakers)
  const [coOpen, setCoOpen] = useState(false); // desktop checkout modal
  const [nameDD, setNameDD] = useState(false);
  const [phoneDD, setPhoneDD] = useState(false);
  const [pendingShop, setPendingShop] = useState(null); // shop-switch confirm
  const searchRef = useRef(null);

  // Catalog by MODE: sneaker mode browses sneakers; clothing (customer order)
  // and cr (refill) both browse the clothing catalog.
  const catalog = useMemo(() => {
    const isClothing = p => (p.productType || "sneaker") === "clothing";
    const wantClothing = mode !== "sneaker";
    return (products || []).filter(p => p && p.id && p.name && (wantClothing ? isClothing(p) : !isClothing(p)));
  }, [products, mode]);

  // Brand dropdown options FROM the data (product.brand), counted, most-stocked
  // first; unbranded/code-only (brand == null) collapse into "Other".
  const brandOpts = useMemo(() => {
    const m = new Map();
    catalog.forEach(p => { const k = p.brand || "Other"; m.set(k, (m.get(k) || 0) + 1); });
    const other = m.get("Other") || 0; m.delete("Other");
    const ranked = [...m.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    const out = [["All", catalog.length], ...ranked];
    if (other) out.push(["Other", other]);
    return out;
  }, [catalog]);

  const shown = useMemo(() => {
    let list = catalog.filter(p =>
      (brand === "All" || (brand === "Other" ? !p.brand : p.brand === brand)) &&
      (!search.trim() || p.name.toLowerCase().includes(search.toLowerCase())));
    if (sort === "ph") list = [...list].sort((a, b) => (b.retailPrice || 0) - (a.retailPrice || 0));
    else if (sort === "pl") list = [...list].sort((a, b) => (a.retailPrice || 0) - (b.retailPrice || 0));
    else if (sort === "az") list = [...list].sort((a, b) => a.name.localeCompare(b.name));
    return list;
  }, [catalog, brand, search, sort]);

  // Reset the brand filter when switching modes (brands differ per catalog).
  useEffect(() => { setBrand("All"); }, [mode]);

  // Cart → grouped by product+size for the drawer (the cart is one line per unit).
  const grouped = useMemo(() => {
    const m = new Map();
    (cart || []).forEach(l => {
      if (l.intent === "refill") return;                 // desktop = customer orders
      const dp = !!l.requestDisplayPartner;
      const key = `${l.product?.id}__${l.size}__${dp ? "dp" : ""}`;
      if (!m.has(key)) m.set(key, { key, product: l.product, size: l.size, dp, qty: 0 });
      m.get(key).qty++;
    });
    return [...m.values()];
  }, [cart]);
  const units = grouped.reduce((s, g) => s + g.qty, 0);
  // Refill cart (intent:"refill") — each line carries its own qty; sum per size.
  const groupedRefill = useMemo(() => {
    const m = new Map();
    (cart || []).forEach(l => {
      if (l.intent !== "refill") return;
      const key = `${l.product?.id}__${l.size}`;
      if (!m.has(key)) m.set(key, { key, product: l.product, size: l.size, qty: 0 });
      m.get(key).qty += (l.qty || 1);
    });
    return [...m.values()];
  }, [cart]);
  const refillUnits = groupedRefill.reduce((s, g) => s + g.qty, 0);
  const fmtR = n => "R" + Number(n).toLocaleString("en-ZA", { maximumFractionDigits: 0 });
  const sizesOf = p => { const s = (Array.isArray(p.sizes) ? p.sizes : []).filter(x => x && String(x).trim() && x !== "_"); return s.length ? s : ["Free Size"]; };

  useEffect(() => {
    const h = e => {
      if (e.key === "/" && document.activeElement !== searchRef.current) { e.preventDefault(); searchRef.current?.focus(); }
      if (e.key === "Escape") setQv(null);
    };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, []);

  const [qvRefill, setQvRefill] = useState({});   // { size: qty } for refill quick-view
  // Quick-view availability note — { size, left } (mirrors the mobile sheet's
  // naNote; live via hubQty/cart every render).
  const [qvNa, setQvNa] = useState(null);
  const openQv = (p) => {
    setQv(p); setQvSize(null); setQvQty(1); setQvDP(false); setQvNa(null);
    setQvRefill((Array.isArray(p.sizes) ? p.sizes : []).reduce((m, s) => (m[s] = 0, m), {}));
  };
  const Photo = ({ p, big }) => p.photoUrl
    ? <img src={p.photoUrl} alt={p.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} onError={e => { e.currentTarget.style.display = "none"; }} />
    : <span style={{ fontSize: big ? 110 : 52 }}>{p.photo || "👟"}</span>;

  return (
    <div className="ad-root">
      <style>{`
        .ad-root{position:fixed;inset:0;z-index:50;background:#000;color:#f4f6ff;font-family:${FONT.replace(/`/g,"")};display:grid;grid-template-columns:184px minmax(0,1fr) 288px;overflow:hidden}
        .ad-root *{box-sizing:border-box}
        @media(max-width:1180px){.ad-root{grid-template-columns:184px minmax(0,1fr)} .ad-drawer{position:fixed;right:0;top:0;bottom:0;width:288px}}
        .ad-side{background:rgba(255,255,255,.015);border-right:1px solid rgba(255,255,255,.08);padding:22px 12px 16px;display:flex;flex-direction:column;gap:4px;overflow:auto}
        .ad-wm .m{font-size:21px;font-weight:800;font-style:italic;letter-spacing:-.6px;color:#fff}
        .ad-wm .c{font-size:10px;font-weight:700;letter-spacing:5px;color:#4A7FFF;margin-top:1px}
        .ad-lab{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:rgba(233,238,255,.3);padding:14px 10px 6px}
        .ad-nav{display:flex;align-items:center;gap:10px;width:100%;text-align:left;background:transparent;border:1px solid transparent;color:rgba(233,238,255,.55);border-radius:10px;padding:9px 11px;font-size:13px;font-weight:600;cursor:pointer;transition:.15s;font-family:inherit}
        .ad-nav:hover{background:rgba(255,255,255,.04);color:#fff}
        .ad-nav[aria-current="true"]{background:rgba(74,127,255,.14);border-color:rgba(74,127,255,.45);color:#9DBCFF}
        .ad-nav .ic{width:16px;height:16px;flex:0 0 auto;opacity:.9}
        .ad-who{display:flex;align-items:center;gap:9px;margin-top:8px;padding:9px 11px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:11px}
        .ad-av{width:28px;height:28px;border-radius:50%;flex:0 0 auto;background:rgba(74,127,255,.2);border:1px solid rgba(74,127,255,.5);color:#9DBCFF;font-size:12px;font-weight:800;display:grid;place-items:center}
        .ad-main{min-width:0;display:flex;flex-direction:column;overflow:hidden}
        .ad-top{padding:16px 22px 13px;border-bottom:1px solid rgba(255,255,255,.08);display:flex;gap:10px;align-items:center;background:radial-gradient(900px 260px at 18% -60%,rgba(74,127,255,.08),transparent)}
        .ad-search{flex:1;position:relative;min-width:0}
        .ad-search svg{position:absolute;left:13px;top:50%;transform:translateY(-50%);opacity:.4}
        .ad-search input{width:100%;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:12px;color:#fff;font-size:13.5px;padding:11px 14px 11px 38px;outline:none;font-family:inherit}
        .ad-search input:focus{border-color:rgba(74,127,255,.6);box-shadow:0 0 0 3px rgba(74,127,255,.12)}
        .ad-sel{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:12px;color:rgba(233,238,255,.75);font-size:12.5px;font-weight:600;padding:10px 12px;cursor:pointer;font-family:inherit}
        .ad-scroll{flex:1;overflow:auto;padding:16px 22px 40px}
        .ad-count{font-size:11px;color:rgba(233,238,255,.3);margin:0 2px 12px}
        .ad-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:14px}
        .ad-card{position:relative;background:linear-gradient(180deg,rgba(255,255,255,.02),transparent 45%),rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.08);border-radius:16px;overflow:hidden;cursor:pointer;display:flex;flex-direction:column;transition:transform .2s cubic-bezier(.2,.7,.2,1),border-color .2s,box-shadow .2s}
        .ad-card:hover,.ad-card:focus-visible{transform:translateY(-5px);border-color:rgba(74,127,255,.55);box-shadow:0 18px 42px -20px rgba(60,110,255,.6);outline:none}
        .ad-thumb{aspect-ratio:16/11;position:relative;overflow:hidden;background:#0a1020;display:grid;place-items:center}
        .ad-cat{position:absolute;top:9px;left:9px;font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#9DBCFF;background:rgba(4,6,14,.72);border:1px solid rgba(255,255,255,.08);padding:3px 8px;border-radius:999px}
        .ad-zoom{position:absolute;top:8px;right:8px;width:29px;height:29px;border:0;border-radius:9px;background:rgba(0,0,0,.5);color:#fff;display:grid;place-items:center;cursor:pointer;opacity:0;transform:translateY(-4px);transition:.18s}
        .ad-card:hover .ad-zoom,.ad-card:focus-within .ad-zoom{opacity:1;transform:none}
        .ad-body{padding:11px 12px 12px;display:flex;flex-direction:column;gap:6px;flex:1}
        .ad-name{font-size:13.5px;font-weight:650;line-height:1.25;min-height:2.5em;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
        .ad-crow{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-top:auto}
        .ad-price{font-size:17px;font-weight:800;font-variant-numeric:tabular-nums;background:linear-gradient(90deg,#6e7bff,#5d8bff,#8a6dff,#7f5af0,#8a6dff,#5d8bff,#6e7bff);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent;animation:adSiri 4s linear infinite}
        @keyframes adSiri{from{background-position:0 0}to{background-position:300% 0}}
        .ad-price.no{-webkit-text-fill-color:initial;color:rgba(233,238,255,.3);font-size:12px}
        .ad-szn{font-size:10px;color:rgba(233,238,255,.3);font-weight:700}
        .ad-hint{font-size:12px;font-weight:600;color:#4A7FFF}
        .ad-quick{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows .22s ease,opacity .18s}
        .ad-card:hover .ad-quick,.ad-card:focus-within .ad-quick{grid-template-rows:1fr;opacity:1}
        .ad-card:hover .ad-hint,.ad-card:focus-within .ad-hint{display:none}
        .ad-quick>div{overflow:hidden;min-height:0}
        .ad-qlab{font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:rgba(233,238,255,.3);margin:2px 0 6px}
        .ad-szrow{display:flex;flex-wrap:wrap;gap:5px}
        .ad-sz{font-size:12px;font-weight:700;font-variant-numeric:tabular-nums;padding:6px 9px;min-width:34px;text-align:center;border-radius:8px;cursor:pointer;color:#dfe7ff;background:rgba(74,127,255,.08);border:1px solid rgba(255,255,255,.12);transition:.13s;font-family:inherit}
        .ad-sz:hover{background:rgba(74,127,255,.24);border-color:rgba(74,127,255,.6);color:#fff;transform:translateY(-1px)}
        .ad-sz.flash{background:#4ADE80;border-color:#4ADE80;color:#04120a}
        .ad-drawer{background:rgba(255,255,255,.015);border-left:1px solid rgba(255,255,255,.08);display:flex;flex-direction:column;overflow:hidden;z-index:40}
        .ad-dhead{padding:18px 16px 13px;border-bottom:1px solid rgba(255,255,255,.08);display:flex;align-items:center;gap:9px}
        .ad-dhead h2{margin:0;font-size:15px;font-weight:800}
        .ad-dn{font-size:11px;font-weight:800;background:rgba(74,127,255,.2);color:#9DBCFF;border-radius:999px;padding:2px 9px;font-variant-numeric:tabular-nums}
        .ad-dlist{flex:1;overflow:auto;padding:12px 13px;display:flex;flex-direction:column;gap:9px}
        .ad-empty{margin:auto;text-align:center;color:rgba(233,238,255,.3);padding:36px 16px;font-size:12.5px}
        .ad-line{display:flex;gap:10px;background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:8px}
        .ad-li{width:44px;height:44px;border-radius:9px;background:#0a1020;display:grid;place-items:center;font-size:20px;flex:0 0 auto;overflow:hidden}
        .ad-ln{font-size:12px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
        .ad-lm{font-size:10px;color:rgba(233,238,255,.5);margin-top:1px}
        .ad-step{display:inline-flex;align-items:center;border:1px solid rgba(255,255,255,.12);border-radius:8px;overflow:hidden;margin-top:5px}
        .ad-step button{width:22px;height:22px;border:0;background:rgba(255,255,255,.04);color:#fff;cursor:pointer;font-size:13px}
        .ad-step span{min-width:24px;text-align:center;font-size:11.5px;font-weight:700;font-variant-numeric:tabular-nums}
        .ad-lp{font-size:12px;font-weight:800;font-variant-numeric:tabular-nums;color:#9DBCFF;text-align:right}
        .ad-dfoot{border-top:1px solid rgba(255,255,255,.08);padding:15px 16px 16px;display:flex;flex-direction:column;gap:11px}
        .ad-trow{display:flex;justify-content:space-between;font-size:12.5px;color:rgba(233,238,255,.55)}
        .ad-trow.tot{color:#fff;font-size:15px;font-weight:800}
        .ad-place{width:100%;padding:13px;border:0;border-radius:12px;font-size:13.5px;font-weight:800;color:#04120a;background:linear-gradient(90deg,#6e7bff,#7f5af0);cursor:pointer;box-shadow:0 8px 22px -8px rgba(127,90,240,.7)}
        .ad-place:disabled{opacity:.4;box-shadow:none;cursor:not-allowed;filter:grayscale(.5)}
        .ad-stage{position:fixed;inset:0;z-index:60;background:rgba(0,0,0,.72);display:grid;place-items:center;padding:26px}
        .ad-sv{width:min(820px,100%);max-height:86vh;overflow:auto;background:#06080f;border:1px solid rgba(255,255,255,.12);border-radius:22px;display:grid;grid-template-columns:1.1fr 1fr;box-shadow:0 40px 120px rgba(0,0,0,.7);position:relative}
        @media(max-width:680px){.ad-sv{grid-template-columns:1fr}}
        .ad-svimg{position:relative;background:#0a1020;min-height:320px;display:grid;place-items:center;overflow:hidden}
        .ad-svbody{padding:24px 24px 22px;display:flex;flex-direction:column;gap:15px}
        .ad-svname{font-size:21px;font-weight:800;letter-spacing:-.4px;line-height:1.15}
        .ad-svprice{font-size:25px;font-weight:800;font-variant-numeric:tabular-nums;background:linear-gradient(90deg,#6e7bff,#5d8bff,#8a6dff,#7f5af0,#8a6dff,#5d8bff,#6e7bff);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:adSiri 5s linear infinite}
        .ad-svsz button{min-width:46px;padding:11px 12px;border-radius:10px;font-size:14px;font-weight:700;font-variant-numeric:tabular-nums;cursor:pointer;color:#dfe7ff;background:rgba(74,127,255,.06);border:1px solid rgba(255,255,255,.12);transition:.13s;font-family:inherit}
        .ad-svsz button[aria-pressed="true"]{background:rgba(74,127,255,.22);border-color:#4A7FFF;color:#fff}
        .ad-svadd{flex:1;padding:14px;border:0;border-radius:12px;font-size:14px;font-weight:800;color:#04120a;background:linear-gradient(90deg,#6e7bff,#7f5af0);cursor:pointer;box-shadow:0 8px 22px -8px rgba(127,90,240,.7)}
        .ad-svadd:disabled{opacity:.4;cursor:not-allowed;filter:grayscale(.5);box-shadow:none}
        .ad-svclose{position:absolute;top:12px;right:12px;width:34px;height:34px;border:0;border-radius:10px;background:rgba(0,0,0,.5);color:#fff;font-size:16px;cursor:pointer;z-index:2}
        .ad-danger{border:1px solid rgba(255,70,70,.55)!important;box-shadow:0 40px 120px rgba(0,0,0,.7),0 0 60px rgba(255,40,40,.28)!important;animation:adShake .5s cubic-bezier(.36,.07,.19,.97)}
        @keyframes adShake{10%,90%{transform:translateX(-1px)}20%,80%{transform:translateX(2px)}30%,50%,70%{transform:translateX(-5px)}40%,60%{transform:translateX(5px)}}
        .ad-warnpulse{animation:adPulse 1.3s ease-in-out infinite}
        @keyframes adPulse{0%,100%{box-shadow:0 0 0 0 rgba(255,60,60,.45)}50%{box-shadow:0 0 0 12px rgba(255,60,60,0)}}
        @keyframes adFade{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}
        .ad-scroll{animation:adFade .26s ease}
        .ad-dbody{display:flex;flex-direction:column;flex:1;overflow:hidden;animation:adFade .26s ease}
        .ad-trackbar{width:100%;display:flex;align-items:center;gap:10px;padding:11px 13px;margin-bottom:14px;border-radius:12px;cursor:pointer;background:rgba(60,110,255,.08);border:1px solid rgba(60,110,255,.35);color:#fff;font-family:inherit;font-size:13px;font-weight:700}
        .ad-trackbar:hover{background:rgba(60,110,255,.14)}
        .ad-trackn{background:rgba(245,196,81,.15);color:#F5C451;border:1px solid rgba(245,196,81,.4);border-radius:999px;padding:2px 9px;font-size:11px;font-weight:700}
        .ad-hint2{font-size:12px;font-weight:600;color:#4A7FFF}
        .ad-rqty{display:inline-flex;align-items:center;border:1px solid rgba(255,255,255,.12);border-radius:8px;overflow:hidden}
        .ad-rqty button{width:28px;height:32px;border:0;background:rgba(255,255,255,.04);color:#fff;cursor:pointer;font-size:15px}
        .ad-rqty input{width:40px;height:32px;text-align:center;border:0;background:rgba(0,0,0,.3);color:#fff;font-size:13px;font-weight:700;outline:none;font-family:inherit}
        @media(prefers-reduced-motion:reduce){.ad-price,.ad-svprice{animation:none} .ad-card,.ad-quick,.ad-scroll,.ad-dbody,.ad-danger,.ad-warnpulse{animation:none;transition:none}}
      `}</style>

      {/* SIDEBAR */}
      <aside className="ad-side">
        <div className="ad-wm" style={{ padding: "0 8px 14px" }}><div className="m">marathon</div><div className="c">CLUB</div></div>
        <div className="ad-lab">Order for</div>
        {(availableShops || []).map(s => (
          <button key={s.id} className="ad-nav" aria-current={effectiveShop === s.id}
                  onClick={() => { if (s.id !== effectiveShop) setPendingShop(s.id); }}>
            <svg className="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>
            {labelFor(s.id, shopRegistry)}
          </button>
        ))}
        <div className="ad-lab">Flow</div>
        <button className="ad-nav" aria-current={mode === "sneaker"} onClick={() => setMode("sneaker")}>
          <svg className="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.7 13.4a2 2 0 0 0 2 1.6h9.7a2 2 0 0 0 2-1.6L23 6H6"/></svg>
          Sneaker order
        </button>
        {/* Clothing customer orders (restored 2026-07-16) — same order flow,
            clothing catalog, routed to the serving CR hub with live per-size
            availability. */}
        <button className="ad-nav" aria-current={mode === "clothing"} onClick={() => setMode("clothing")}>
          <svg className="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M20.38 3.46 16 2a4 4 0 0 1-8 0L3.62 3.46a2 2 0 0 0-1.34 2.23l.58 3.47a1 1 0 0 0 .99.84H6v10a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1V10h2.15a1 1 0 0 0 .99-.84l.58-3.47a2 2 0 0 0-1.34-2.23z"/></svg>
          Clothing order
        </button>
        {/* "Refill tracking" rail slot REMOVED (owner decision 2026-07-16) —
            engine refills are the warehouse's concern, not the shop's. The
            onOpenTracking/trackingPending props stay threaded for the CR
            fallback's trackbar (unreachable while CR is retired). */}
        <div style={{ flex: 1 }} />
        <button className="ad-nav" onClick={onSwitchView}>
          <svg className="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-3M18 2l4 4-9 9H9v-4z"/></svg>
          Switch view
        </button>
        <div className="ad-who">
          <span className="ad-av">{(userEmail || "?")[0].toUpperCase()}</span>
          <span style={{ minWidth: 0, flex: 1 }}>
            <span style={{ display: "block", fontSize: 12, fontWeight: 700, color: "#fff", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{(userEmail || "").split("@")[0] || "assistant"}</span>
            <span style={{ display: "block", fontSize: 10, color: "rgba(233,238,255,.4)" }}>Store assistant</span>
          </span>
          <button onClick={onSignOut} title="Sign out" aria-label="Sign out"
                  style={{ width: 28, height: 28, flexShrink: 0, borderRadius: 8, border: "1px solid rgba(255,255,255,.12)", background: "transparent", color: "rgba(233,238,255,.5)", cursor: "pointer", display: "grid", placeItems: "center" }}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/></svg>
          </button>
        </div>
      </aside>

      {/* MAIN */}
      <div className="ad-main">
        <div className="ad-top">
          <div className="ad-search">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.3-4.3"/></svg>
            <input ref={searchRef} value={search} onChange={e => setSearch(e.target.value)} placeholder="Search products…  ( / )" autoComplete="off" />
          </div>
          <select className="ad-sel" value={brand} onChange={e => setBrand(e.target.value)} aria-label="Brand">
            {brandOpts.map(([b, n]) => <option key={b} value={b}>{b === "All" ? "All brands" : b} ({n})</option>)}
          </select>
          <select className="ad-sel" value={sort} onChange={e => setSort(e.target.value)} aria-label="Sort">
            <option value="feat">Featured</option>
            <option value="ph">Price · high</option>
            <option value="pl">Price · low</option>
            <option value="az">Name · A–Z</option>
          </select>
        </div>
        <div className="ad-scroll" key={flow}>
          {flow === "refill" && (
            <button className="ad-trackbar" onClick={onOpenTracking}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#6A9FFF" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 16V8a2 2 0 00-1-1.73l-7-4a2 2 0 00-2 0l-7 4A2 2 0 003 8v8a2 2 0 001 1.73l7 4a2 2 0 002 0l7-4A2 2 0 0021 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/></svg>
              <span style={{ flex: 1, textAlign: "left" }}>Track requests</span>
              {trackingPending > 0 && <span className="ad-trackn">{trackingPending} pending</span>}
              <span style={{ color: "#4A7FFF" }}>→</span>
            </button>
          )}
          <div className="ad-count">{shown.length} {flow === "refill" ? "clothing item" : "product"}{shown.length !== 1 ? "s" : ""}</div>
          {shown.length === 0 ? (
            <div style={{ textAlign: "center", color: "#444", padding: "3rem", fontSize: 14 }}>{flow === "refill" ? "No clothing products yet." : "No products match."}</div>
          ) : (
            <div className="ad-grid">
              {shown.map(p => {
                const priced = typeof p.retailPrice === "number" && p.retailPrice > 0;
                const szs = sizesOf(p);
                return (
                  <article key={p.id} className="ad-card" tabIndex={0}
                           onClick={() => openQv(p)} onKeyDown={e => { if (e.key === "Enter") openQv(p); }}>
                    <div className="ad-thumb">
                      <span className="ad-cat">{p.brand || p.subcategory || (mode !== "sneaker" ? "Clothing" : "Sneakers")}</span>
                      {p.photoUrl && (
                        <button className="ad-zoom" aria-label="Quick view" onClick={e => { e.stopPropagation(); onViewPhoto(productPhotos(p)); }}>
                          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg>
                        </button>
                      )}
                      <Photo p={p} />
                    </div>
                    <div className="ad-body">
                      <div className="ad-name">{p.name}</div>
                      <div className="ad-crow">
                        {priced ? <span className="ad-price">{fmtR(p.retailPrice)}</span> : <span className="ad-price no">No price set</span>}
                        <span className="ad-szn">{szs.length} size{szs.length !== 1 ? "s" : ""}</span>
                      </div>
                      {/* Order flow: hover reveals per-size quick-add. Refill flow:
                          multi-size qty is set in the quick-view (tap the card). */}
                      {flow === "order" ? (
                        <div className="ad-quick"><div>
                          <div className="ad-qlab">Add a size</div>
                          <div className="ad-szrow">
                            {szs.map(sz => {
                              // Clothing: a size the serving hub has zero of is
                              // greyed/disabled here (hover quick-add has no room
                              // for the inline note — the quick-view carries it).
                              const out = clothingOrder && hubQty(p.id, sz) <= 0;
                              return (
                                <button key={sz} className="ad-sz" disabled={out}
                                  title={out ? `Not available at ${servingHubLabel}` : undefined}
                                  style={out ? { opacity:.3, cursor:"not-allowed", textDecoration:"line-through" } : undefined}
                                  onClick={e => {
                                    e.stopPropagation(); if (out) return;
                                    // quickAdd returns 0 when the cart already
                                    // holds everything the hub has — no ✓ flash
                                    // for an add that didn't happen.
                                    if (!onQuickAdd(p, sz, 1)) return;
                                    const b = e.currentTarget, t = b.textContent; b.classList.add("flash"); b.textContent = "✓";
                                    setTimeout(() => { b.classList.remove("flash"); b.textContent = t; }, 430);
                                  }}>{sz === "Free Size" ? "OS" : sz}</button>
                              );
                            })}
                          </div>
                        </div></div>
                      ) : (
                        <div className="ad-hint2">Set quantities →</div>
                      )}
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* DRAWER — order cart (→ checkout) or refill cart (→ place refill request),
          cross-fading with the flow. */}
      <aside className="ad-drawer">
        <div className="ad-dhead"><h2>{flow === "refill" ? "Refill request" : "Order"}</h2><span className="ad-dn">{flow === "refill" ? refillUnits : units}</span></div>
        <div className="ad-dbody" key={flow}>
          {flow === "order" ? (
            <>
              <div className="ad-dlist">
                {grouped.length === 0 ? (
                  <div className="ad-empty">
                    <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{ opacity: .5, marginBottom: 10 }}><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.7 13.4a2 2 0 0 0 2 1.6h9.7a2 2 0 0 0 2-1.6L23 6H6"/></svg>
                    <div style={{ fontWeight: 600 }}>Order is empty</div>
                    <div style={{ marginTop: 4, fontSize: 11 }}>Hover a product and tap a size.</div>
                  </div>
                ) : grouped.map(g => (
                  <div key={g.key} className="ad-line">
                    <div className="ad-li">{g.product?.photoUrl ? <img src={g.product.photoUrl} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : (g.product?.photo || "👟")}</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div className="ad-ln">{g.product?.name}</div>
                      <div className="ad-lm">
                        {g.dp
                          ? <span style={{ color: "#9DBCFF" }}>Display Partner{g.size ? ` · Sz ${formatSize(g.size)}` : ""}</span>
                          : `Size ${g.size === "Free Size" ? "OS" : formatSize(g.size)} · ${typeof g.product?.retailPrice === "number" ? fmtR(g.product.retailPrice) : "—"}`}
                      </div>
                      <div className="ad-step">
                        <button onClick={() => onRemoveOne(g.product.id, g.size, g.dp)}>−</button>
                        <span>{g.qty}</span>
                        <button onClick={() => g.dp ? onAddDisplayPartner(g.product, g.size) : onQuickAdd(g.product, g.size, 1)}>+</button>
                      </div>
                    </div>
                    <div className="ad-lp">{g.dp ? "—" : (typeof g.product?.retailPrice === "number" ? fmtR(g.product.retailPrice * g.qty) : "—")}</div>
                  </div>
                ))}
              </div>
              <div className="ad-dfoot">
                {/* Ordering system, not POS — no money total. */}
                <div className="ad-trow"><span>{units} item{units !== 1 ? "s" : ""}</span><span>{grouped.length} line{grouped.length !== 1 ? "s" : ""}</span></div>
                <button className="ad-place" disabled={!units} onClick={() => setCoOpen(true)}>Place order</button>
              </div>
            </>
          ) : (
            <>
              <div className="ad-dlist">
                {groupedRefill.length === 0 ? (
                  <div className="ad-empty">
                    <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{ opacity: .5, marginBottom: 10 }}><path d="M20 7h-9M14 17H5M17 3l3 4-3 4M7 21l-3-4 3-4"/></svg>
                    <div style={{ fontWeight: 600 }}>No refills yet</div>
                    <div style={{ marginTop: 4, fontSize: 11 }}>Open a product and set per-size quantities.</div>
                  </div>
                ) : groupedRefill.map(g => (
                  <div key={g.key} className="ad-line">
                    <div className="ad-li">{g.product?.photoUrl ? <img src={g.product.photoUrl} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : (g.product?.photo || "👕")}</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div className="ad-ln">{g.product?.name}</div>
                      <div className="ad-lm">Size {formatSize(g.size)}</div>
                    </div>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <span style={{ fontSize: 13, fontWeight: 800, color: "#9DBCFF", fontVariantNumeric: "tabular-nums" }}>×{g.qty}</span>
                      <button onClick={() => onRemoveOne(g.product.id, g.size)} aria-label="Remove" style={{ background: "transparent", border: 0, color: "rgba(233,238,255,.4)", cursor: "pointer", fontSize: 14 }}>✕</button>
                    </div>
                  </div>
                ))}
              </div>
              <div className="ad-dfoot">
                <div className="ad-trow"><span>{refillUnits} unit{refillUnits !== 1 ? "s" : ""}</span><span>{groupedRefill.length} line{groupedRefill.length !== 1 ? "s" : ""}</span></div>
                <button className="ad-place" disabled={!refillUnits || submitting} onClick={() => onPlaceRefill()}>{submitting ? "Placing…" : "Place refill request"}</button>
              </div>
            </>
          )}
        </div>
      </aside>

      {/* QUICK-VIEW STAGE */}
      {qv && (
        <div className="ad-stage" onClick={e => { if (e.currentTarget === e.target) setQv(null); }}>
          <div className="ad-sv">
            <button className="ad-svclose" onClick={() => setQv(null)} aria-label="Close">✕</button>
            <div className="ad-svimg" onClick={() => qv.photoUrl && onViewPhoto(productPhotos(qv))} style={{ cursor: qv.photoUrl ? "zoom-in" : "default" }}>
              <span className="ad-cat" style={{ top: 14, left: 14 }}>{qv.brand || (mode !== "sneaker" ? "Clothing" : "Sneakers")}</span>
              <Photo p={qv} big />
            </div>
            <div className="ad-svbody">
              <div>
                <div className="ad-svname">{qv.name}</div>
                {typeof qv.retailPrice === "number" && qv.retailPrice > 0
                  ? <div className="ad-svprice" style={{ marginTop: 6 }}>{fmtR(qv.retailPrice)}</div>
                  : <div style={{ marginTop: 6, color: "rgba(233,238,255,.35)", fontWeight: 700 }}>No price set</div>}
              </div>
              {flow === "order" ? (
                <>
                  <div>
                    <div className="ad-qlab">Select a size</div>
                    {/* Inline availability note — above the size row, shown when
                        a greyed (zero-at-hub) size is tapped or an add asked for
                        more than the hub can still cover. Live: recomputes
                        remaining (hub minus cart) every render and hides once
                        more is addable than when it was raised. */}
                    {clothingOrder && qvNa && (() => {
                      const have = hubQty(qv.id, qvNa.size);
                      const rem = have - clothingInCart(qv.id, qvNa.size);
                      if (rem > qvNa.left) return null;
                      const text = have <= 0
                        ? `Size ${formatSize(qvNa.size)} isn't available at ${servingHubLabel} right now — it can't be ordered.`
                        : rem <= 0
                          ? `Your cart already has all ${have} of size ${formatSize(qvNa.size)} that ${servingHubLabel} holds.`
                          : `Only ${rem} more of size ${formatSize(qvNa.size)} can be added — ${servingHubLabel} holds ${have}.`;
                      return (
                        <div style={{ background:"rgba(255,170,40,.1)", border:"1px solid rgba(255,170,40,.35)", color:"#FFC46B", borderRadius:10, padding:"9px 12px", fontSize:12.5, fontWeight:600, marginBottom:8 }}>
                          {text}
                        </div>
                      );
                    })()}
                    <div className="ad-svsz" style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                      {sizesOf(qv).map(sz => {
                        const out = clothingOrder && hubQty(qv.id, sz) <= 0;
                        return (
                          <button key={sz} aria-pressed={qvSize === sz} aria-disabled={out}
                            style={out ? { opacity:.35, cursor:"not-allowed", textDecoration:"line-through" } : undefined}
                            onClick={() => { if (out) { setQvNa({ size: sz, left: 0 }); return; } setQvNa(null); setQvSize(sz); }}>
                            {sz === "Free Size" ? "One size" : formatSize(sz)}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                  {/* Display Partner request — sneakers only; one line, size optional. */}
                  {!clothingOrder && (
                  <div>
                    <div className="ad-qlab">Display Partner (optional)</div>
                    <button onClick={() => setQvDP(v => !v)}
                            style={{ padding: "9px 15px", borderRadius: 10, fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit",
                                     border: `1px solid ${qvDP ? "#4A7FFF" : "rgba(255,255,255,.14)"}`,
                                     background: qvDP ? "rgba(74,127,255,.18)" : "rgba(255,255,255,.03)",
                                     color: qvDP ? "#9DBCFF" : "rgba(233,238,255,.55)", display: "inline-flex", alignItems: "center", gap: 8 }}>
                      <span style={{ width: 15, height: 15, borderRadius: 4, border: `1px solid ${qvDP ? "#4A7FFF" : "rgba(255,255,255,.25)"}`, background: qvDP ? "#4A7FFF" : "transparent", color: "#04120a", fontSize: 11, fontWeight: 900, display: "grid", placeItems: "center" }}>{qvDP ? "✓" : ""}</span>
                      Request Display Partner
                    </button>
                  </div>
                  )}
                  {(() => {
                    // Clothing: size mandatory, no Display Partner (its UI is
                    // hidden above; ignore any lingering qvDP from sneaker mode).
                    const dp = !clothingOrder && qvDP;
                    const canAdd = clothingOrder ? !!qvSize : (!!qvSize || dp);
                    const doAdd = () => {
                      if (!canAdd) return;
                      if (dp) { onAddDisplayPartner(qv, qvSize || null); setQv(null); return; }
                      // Clothing: quickAdd caps at hub-minus-cart availability
                      // and returns what it actually added — a short add keeps
                      // the quick-view open with the explanatory note.
                      const added = onQuickAdd(qv, qvSize, qvQty);
                      if (clothingOrder && added < qvQty) { setQvNa({ size: qvSize, left: 0 }); return; }
                      setQv(null);
                    };
                    const label = dp
                      ? (qvSize ? `Add size ${formatSize(qvSize)} + Display Partner` : "Add Display Partner request")
                      : (qvSize ? `Add ${qvQty} × ${qvSize === "Free Size" ? "OS" : formatSize(qvSize)} to order` : (clothingOrder ? "Select a size" : "Select a size or Display Partner"));
                    return (
                      <div style={{ display: "flex", gap: 10, alignItems: "center", marginTop: "auto" }}>
                        <div className="ad-step" style={{ height: 48, opacity: dp ? .4 : 1 }}>
                          <button style={{ width: 34, height: 46, fontSize: 18 }} disabled={dp} onClick={() => setQvQty(q => Math.max(1, q - 1))}>−</button>
                          <span style={{ minWidth: 34, fontSize: 14 }}>{qvQty}</span>
                          <button style={{ width: 34, height: 46, fontSize: 18 }} disabled={dp} onClick={() => setQvQty(q => Math.min(10, q + 1))}>+</button>
                        </div>
                        <button className="ad-svadd" disabled={!canAdd} onClick={doAdd}>{label}</button>
                      </div>
                    );
                  })()}
                </>
              ) : (
                <>
                  {/* Refill: multi-size quantity grid (mirrors ClothingCard). */}
                  <div>
                    <div className="ad-qlab">Quantities per size</div>
                    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(118px,1fr))", gap: 8 }}>
                      {sizesOf(qv).map(sz => {
                        const n = qvRefill[sz] || 0;
                        const setN = v => setQvRefill(q => ({ ...q, [sz]: Math.max(0, Math.min(99, Math.floor(Number(v) || 0))) }));
                        return (
                          <div key={sz} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 6, background: "rgba(255,255,255,.03)", border: `1px solid ${n ? "rgba(74,222,128,.4)" : "rgba(255,255,255,.1)"}`, borderRadius: 10, padding: "6px 8px" }}>
                            <span style={{ fontSize: 12.5, fontWeight: 700, color: "#dfe7ff" }}>{sz === "Free Size" ? "OS" : formatSize(sz)}</span>
                            <div className="ad-rqty">
                              <button onClick={() => setN(n - 1)}>−</button>
                              <input value={n || ""} placeholder="0" inputMode="numeric" onChange={e => setN(e.target.value)} />
                              <button onClick={() => setN(n + 1)}>+</button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                  {(() => {
                    const totalR = Object.values(qvRefill).reduce((s, v) => s + (v || 0), 0);
                    const doAddR = () => {
                      const lines = Object.entries(qvRefill).filter(([, n]) => n > 0).map(([size, n]) => ({ product: qv, size, qty: n, productType: "clothing" }));
                      if (!lines.length) return;
                      onAddClothing(lines); setQv(null);
                    };
                    return (
                      <button className="ad-svadd" style={{ marginTop: "auto" }} disabled={!totalR} onClick={doAddR}>
                        {totalR ? `Add ${totalR} unit${totalR !== 1 ? "s" : ""} to refill` : "Set a quantity"}
                      </button>
                    );
                  })()}
                </>
              )}
            </div>
          </div>
        </div>
      )}

      {/* CHECKOUT — ordering system (NO money total). Summary + customer + place. */}
      {coOpen && (
        <div className="ad-stage" onClick={e => { if (e.currentTarget === e.target && !submitting) setCoOpen(false); }}>
          <div className="ad-sv" style={{ gridTemplateColumns: "1fr", width: "min(460px,100%)" }}>
            <button className="ad-svclose" onClick={() => !submitting && setCoOpen(false)} aria-label="Close">✕</button>
            <div className="ad-svbody" style={{ gap: 13 }}>
              <div className="ad-svname" style={{ fontSize: 19 }}>Confirm order</div>
              <div style={{ background: "rgba(74,127,255,.05)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 12, padding: "9px 12px", maxHeight: 172, overflow: "auto" }}>
                <div className="ad-qlab" style={{ margin: "0 0 6px" }}>Order · {units} item{units !== 1 ? "s" : ""}</div>
                {grouped.map(g => (
                  <div key={g.key} style={{ display: "flex", justifyContent: "space-between", gap: 8, fontSize: 12.5, color: "#dfe7ff", padding: "4px 0" }}>
                    <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{g.product?.name}</span>
                    <span style={{ color: "#9DBCFF", fontWeight: 700, flexShrink: 0 }}>{g.dp ? "Display" : `Sz ${formatSize(g.size)}`}{g.qty > 1 ? ` ×${g.qty}` : ""}</span>
                  </div>
                ))}
              </div>
              <div style={{ position: "relative" }}>
                <div className="ad-qlab">Customer name *</div>
                <input value={customerName} placeholder="e.g. Ahmed" style={{ ...inputStyle, width: "100%", boxSizing: "border-box" }}
                       onChange={e => { setCustomerName(e.target.value); setNameDD(true); }}
                       onFocus={() => setNameDD(true)} onBlur={() => setTimeout(() => setNameDD(false), 150)} />
                {nameDD && <CustomerSuggestionDropdown query={customerName} mode="name" customers={customerIndex} onPick={p => { onPickCustomer(p); setNameDD(false); }} onAddNew={() => setNameDD(false)} />}
              </div>
              <div style={{ position: "relative" }}>
                <div className="ad-qlab">Phone *</div>
                <input value={customerPhone} placeholder="0712345678" inputMode="numeric" maxLength={10} style={{ ...inputStyle, width: "100%", boxSizing: "border-box" }}
                       onChange={e => { setCustomerPhone(e.target.value.replace(/\D/g, "").slice(0, 10)); setPhoneDD(true); }}
                       onFocus={() => setPhoneDD(true)} onBlur={() => setTimeout(() => setPhoneDD(false), 150)} />
                {phoneDD && <CustomerSuggestionDropdown query={customerPhone} mode="phone" customers={customerIndex} onPick={p => { onPickCustomer(p); setPhoneDD(false); }} onAddNew={() => setPhoneDD(false)} />}
                {customerPhone && !isValidLocalSAPhone(customerPhone) && <div style={{ color: "#FF6B6B", fontSize: 11, marginTop: 5 }}>Enter a 10-digit number starting with 0.</div>}
              </div>
              <label style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer", fontSize: 12.5, color: "#dfe7ff" }}>
                <input type="checkbox" checked={marketingOptIn} onChange={e => setMarketingOptIn(e.target.checked)} style={{ width: 17, height: 17, accentColor: "#4A7FFF" }} />
                Customer wants Marathon Club deals
              </label>
              {(() => {
                const phoneOk = isValidLocalSAPhone(customerPhone);
                const canPlace = customerName && phoneOk && units && !submitting;
                const label = !customerName ? "Enter customer name" : !phoneOk ? "Enter a valid phone" : `Place ${grouped.length} order${grouped.length > 1 ? "s" : ""}`;
                return <button className="ad-svadd" disabled={!canPlace} onClick={async () => { await onPlaceOrder(); setCoOpen(false); }}>{submitting ? "Placing…" : label}</button>;
              })()}
            </div>
          </div>
        </div>
      )}

      {/* SHOP SWITCH — a deliberately ALARMING confirm: changing shop re-routes
          every order to a different physical store. */}
      {pendingShop && (
        <div className="ad-stage" onClick={e => { if (e.currentTarget === e.target) setPendingShop(null); }}>
          <div className="ad-sv ad-danger" style={{ gridTemplateColumns: "1fr", width: "min(430px,100%)" }}>
            <div className="ad-svbody" style={{ gap: 15, alignItems: "center", textAlign: "center", padding: "30px 26px 26px" }}>
              <span className="ad-warnpulse" style={{ width: 64, height: 64, borderRadius: "50%", flexShrink: 0, background: "rgba(255,60,60,.14)", border: "2px solid rgba(255,70,70,.6)", display: "grid", placeItems: "center" }}>
                <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#FF5A5A" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="14"/><line x1="12" y1="18" x2="12.01" y2="18"/></svg>
              </span>
              <div style={{ fontSize: 11, letterSpacing: ".18em", textTransform: "uppercase", color: "#FF6B6B", fontWeight: 800 }}>Warning · this re-routes orders</div>
              <div className="ad-svname" style={{ fontSize: 21, color: "#fff" }}>Change shop to {labelFor(pendingShop, shopRegistry)}?</div>
              <div style={{ fontSize: 13.5, color: "rgba(233,238,255,.72)", lineHeight: 1.55 }}>
                You're ordering for <b style={{ color: "#fff" }}>{labelFor(effectiveShop, shopRegistry)}</b> right now. Every order you place next goes to <b style={{ color: "#FF8B8B" }}>{labelFor(pendingShop, shopRegistry)}</b> — <b style={{ color: "#fff" }}>if this is a mistake, the wrong store gets the stock.</b>{units ? ` Your ${units} unplaced item${units !== 1 ? "s" : ""} stay in the cart.` : ""}
              </div>
              <div style={{ display: "flex", gap: 10, width: "100%", marginTop: 4 }}>
                <button onClick={() => setPendingShop(null)} style={{ flex: 1, padding: 13, borderRadius: 11, border: "1px solid rgba(255,255,255,.2)", background: "rgba(255,255,255,.05)", color: "#fff", fontWeight: 800, cursor: "pointer", fontFamily: "inherit" }}>Cancel</button>
                <button onClick={() => { onSelectShop(pendingShop); setPendingShop(null); }} style={{ flex: "0 0 auto", padding: "13px 20px", borderRadius: 11, border: "1px solid rgba(255,80,80,.7)", background: "rgba(230,40,40,.92)", color: "#fff", fontWeight: 800, cursor: "pointer", fontFamily: "inherit", boxShadow: "0 8px 26px -8px rgba(255,50,50,.75)" }}>Yes, switch</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function AssistantView({ products, onExit, orders = [] }) {
  const [search, setSearch]                             = useState("");
  // Mode selector — a 2-way toggle (Sneakers / Clothing), both CUSTOMER flows:
  //   "sneaker"  → sneakers, customer order (photo grid + size sheet)
  //   "clothing" → clothing, customer order (same grid + size sheet UX),
  //                RESTORED 2026-07-16: now routed to the universe's CR hub
  //                (hub2/hub3 — real stock, real transfer on Send) instead of
  //                the retired hubC trial, with live per-size hub availability
  //                greying out sizes the hub has zero of.
  //   "cr"       → Clothing Refill (bulk multi-size qty list → hub2/hub3) —
  //                RETIRED from the toggle (engine go-live 2026-07-12): the
  //                auto-refill engine owns shop refills. Its plumbing stays
  //                intact behind mode==="cr" as the manual fallback.
  // Helpers below derive product-type filtering, the card layout, and the
  // per-line intent from this one value.
  const [mode, setMode]                                 = useState("sneaker");
  const wantsClothing = mode === "clothing" || mode === "cr"; // product-type filter
  const isRefillMode  = mode === "cr";                        // bulk refill card UX
  // SHOP toggle (was the Central/Pine universe toggle). The assistant now picks a
  // physical SHOP — Marathon PE / Trophy / Pine — so each order records WHICH shop
  // it's for (order.destShop), which is what lets dispatch record a real
  // warehouse→shop stock transfer. The central/pine ROUTING universe is derived
  // from the chosen shop via shopUniverse(), so every downstream consumer (product
  // filter, computeHubForItem, placedHub/placedStore) is unchanged. Persists per
  // device so the Pine iPad stays Pine across reloads.
  const shopRegistry = useLocations();
  const allShops = sellableLocations(shopRegistry);  // marathon-pe, trophy, marathon-pine
  const [selectedShop, setSelectedShop] = useState(() => {
    const saved = localStorage.getItem("storeAssistantShop");
    if (saved) return saved;
    // One-time migration from the old central/pine universe key.
    return localStorage.getItem("storeAssistantMode") === "pine" ? "marathon-pine" : "marathon-pe";
  });
  const selectShop = (next) => {
    localStorage.setItem("storeAssistantShop", next);
    setSelectedShop(next);
  };
  // Phase 15: per-user store assignment stays at central/pine granularity
  // (STORE_IDS / storeIds / UserManagement / POS posAccess are untouched).
  // `availableShops` expands that assignment into the physical shops the user may
  // pick: a "central" user → Marathon PE + Trophy; "pine" → Pine. Drives the
  // toggle below: 0 → block screen, 1 → auto-select + hide toggle, ≥2 → show.
  // (isSuperAdmin/hasPermission no longer destructured here — their only
  // consumer, the "Shop stock · view only" card's canAccessStock gate, was
  // removed with the card. Owner decision 2026-07-16.)
  const { user: assistantUser, signOut: assistantSignOut, storeIds: allowedStores, permRecord: stockPermRecord } = usePermissions();
  // Desktop workspace kicks in at ≥1024px (laptop); phone + iPad keep tap→sheet.
  const isDesktop = !useIsNarrow(1024);
  // Single-store assignment (destShop) locks the picker to exactly that shop — the
  // user can only place/act on their store. Falls back to the older central/pine
  // storeIds gating when no destShop is set (warehouse/admin/unassigned).
  const myShop = stockPermRecord?.destShop || null;
  const availableShops = myShop
    ? allShops.filter(s => s.id === myShop)
    : allShops.filter(s => allowedStores.includes(shopUniverse(s.id)));
  const noStoreAccess = availableShops.length === 0;
  const singleShop    = availableShops.length === 1;
  useEffect(() => {
    if (availableShops.length === 0) return;        // block screen handles this
    if (!availableShops.some(s => s.id === selectedShop)) selectShop(availableShops[0].id);
  }, [availableShops, selectedShop]);
  // Clamp at RENDER too: the effect above persists the correction but only runs
  // after commit, so the first paint (and the product filtering / order routing it
  // drives) must use this derived value — never a stale per-device shop the user
  // isn't assigned to.
  const effectiveShop = availableShops.some(s => s.id === selectedShop)
    ? selectedShop
    : (availableShops[0]?.id || selectedShop);
  // Routing universe derived from the chosen shop. THIS keeps every downstream
  // consumer keyed on central/pine unchanged.
  const effectiveStoreMode = shopUniverse(effectiveShop);
  // Live per-size availability at the SERVING CR hub (hub2 for PE/Trophy,
  // hub3 for Pine — CR_HUB_BY_UNIVERSE). Drives the clothing size grey-out:
  // a size the hub shows zero of can't be added (tap → inline "not available"
  // note), so staff learn on the spot instead of ordering into nothing. Live
  // RTDB subscription — one hub subtree only; /stock is readable by any
  // signed-in (non-anonymous) staff account, no stockRole needed for reads.
  const servingHub = CR_HUB_BY_UNIVERSE[effectiveStoreMode] || "hub2";
  const servingHubCells = useStockCells(servingHub);   // { pid: { size: cell } }
  const hubQty = (pid, size) => Number(servingHubCells?.[pid]?.[size]?.qty) || 0;
  // ── SHOP-SWITCH GUARD ─────────────────────────────────────────────────────
  // The SHOP toggle silently re-routes EVERY order placed afterwards to that
  // store's warehouse→shop transfer (order.destShop). A single mis-tap here
  // (Trophy → Marathon PE, etc.) sends real stock to the wrong branch with no
  // undo. So the toggle no longer switches on tap — it stages the target shop
  // and a hard, red confirm modal stands between the tap and the switch.
  // `pendingShopSwitch` holds the target shop id awaiting confirmation (null =
  // no prompt showing).
  const [pendingShopSwitch, setPendingShopSwitch] = useState(null);
  const requestShopSwitch = (next) => {
    if (!next || next === effectiveShop) return;   // tapping the current shop is a no-op
    setPendingShopSwitch(next);
  };
  const confirmShopSwitch = () => {
    // An explicit, confirmed switch IS an affirmation of the destination, so the
    // placement guard below won't prompt again for the shop they just chose.
    if (pendingShopSwitch) { selectShop(pendingShopSwitch); setAffirmedShop(pendingShopSwitch); }
    setPendingShopSwitch(null);
  };
  // ── PLACEMENT DESTINATION GUARD ────────────────────────────────────────────
  // The shop-switch modal above only fires when the toggle is TAPPED. It does
  // nothing for a device left on the wrong shop from an earlier session that is
  // never switched — the exact hole behind the cross-shop mis-routes (a device
  // serving Marathon PE but stuck on "Trophy" silently shipped PE orders into
  // Trophy's stock cell; PE then sold from a cell that never received the +1 and
  // went negative). So for multi-shop users, the FIRST placement after load or a
  // shop change must AFFIRM the destination shop before any order is written.
  // Single-shop-locked users can't mis-route, so they are never prompted.
  const [affirmedShop, setAffirmedShop] = useState(null);
  const [destConfirm,  setDestConfirm]  = useState(null);   // { run } — a placement awaiting affirmation
  const needsDestConfirm = !singleShop && !noStoreAccess && affirmedShop !== effectiveShop;
  const runDestConfirm = () => {
    setAffirmedShop(effectiveShop);
    const pending = destConfirm;
    setDestConfirm(null);
    pending?.run?.();
  };
  const [selected, setSelected]                         = useState(null);   // product in size picker
  // Tapping a product photo opens a full-screen lightbox so staff can see the
  // complete (uncropped) image. Holds the photo URL to show, or null.
  const [fullPhoto, setFullPhoto]                       = useState(null);
  // Refill tracking page (CR tab) — opened via the "Track requests" button.
  const [trackingOpen, setTrackingOpen]                 = useState(false);
  const trackingPending = useMemo(
    () => (orders || []).filter(o => o && o.customerName === "Shop Refill" && o.destShop === effectiveShop && !o.clothingRefillStatus).length,
    [orders, effectiveShop]
  );
  // Scroll-to-top FAB: appears once the user has scrolled past the search box so
  // a single tap returns to the top (the search bar) after browsing the grid.
  const [showScrollTop, setShowScrollTop]               = useState(false);
  useEffect(() => {
    const onScroll = () => setShowScrollTop(window.scrollY > 400);
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  const scrollToTop = () => window.scrollTo({ top: 0, behavior: "smooth" });
  const [pendingSize, setPendingSize]                   = useState("");
  // Clothing availability note — { size, left } for the size the assistant
  // tapped/added that the serving hub can't (fully) cover; `left` is how many
  // more units could still be added when it was raised (0 = none). Renders
  // the inline note above the size row. Self-clears live: it only shows while
  // remaining-at-hub (hub qty minus units already in the cart) is still ≤
  // `left`, so arriving stock or a shrinking cart drops it on the next
  // snapshot.
  const [naNote, setNaNote]                             = useState(null);
  // No-size products (bags, accessories, perfume, one-size) order as "Free Size" —
  // "_"/blank placeholders aren't real sizes. Keeps the size sheet from dead-ending.
  const selectedSizes = useMemo(() => {
    const real = (selected?.sizes || []).filter(s => s && String(s).trim() && s !== "_");
    return real.length ? real : ["Free Size"];
  }, [selected]);
  const [pendingQty,  setPendingQty]                    = useState(1);
  const [pendingDisplayRequest, setPendingDisplay]      = useState(false);
  const [pendingDisplayPartner, setPendingDisplayPartner] = useState(false);
  // Cart line shape:
  //   sneaker: { product, size, requestDisplay, requestDisplayPartner }
  //   clothing: { product, size, qty, productType:"clothing" }
  const [cart, setCart]                                 = useState([]);
  // Units of a clothing product+size already in the cart — availability checks
  // compare against hubQty MINUS these, so stacked adds (stepper, repeated
  // quick-adds) can never order more than the hub actually holds.
  const clothingInCart = (pid, size) =>
    cart.filter(l => l.productType === "clothing" && l.product?.id === pid && l.size === size).length;
  const [checkoutOpen, setCheckoutOpen]                 = useState(false);
  const [customerName, setCustomerName]                 = useState("");
  const [customerPhone, setCustomerPhone]               = useState("");
  const [marketingOptIn, setMarketingOptIn]             = useState(false);
  const [lastOrders, setLastOrders]                     = useState([]);
  const [submitting, setSubmitting]                     = useState(false);
  // Autocomplete dropdown open-state per input. Tap a suggestion or the
  // "+ Add new" row to dismiss; typing in the input reopens.
  const [nameDropdownOpen, setNameDropdownOpen]   = useState(false);
  const [phoneDropdownOpen, setPhoneDropdownOpen] = useState(false);
  const customerIndex = useCustomerIndex();
  const pickCustomer = (c) => {
    setCustomerName(c.name || "");
    // Existing customers are stored normalised (+27…); show the strict local
    // 0XXXXXXXXX form so the required-phone validation passes.
    setCustomerPhone(toLocalSA(c.phone || ""));
    setNameDropdownOpen(false);
    setPhoneDropdownOpen(false);
  };

  // Filter products by the active mode (sneaker vs clothing) + search box.
  // Existing products without productType are treated as sneakers.
  // SNEAKERS stay store-gated: Phase 14B Central shows hub1/hub2 products, Pine
  // shows hub3. CLOTHING (both customer + refill) is visible to ALL stores — no
  // hub gating — so every assistant can order/refill clothing regardless of
  // which store they're on.
  // Products matching the active mode (sneaker/clothing) + store universe,
  // BEFORE any text search. The fuzzy search runs over this candidate set so a
  // typo can never pull in products from the wrong mode/hub.
  const base = useMemo(() =>
    products.filter(p => {
      const isClothingProduct = (p.productType || "sneaker") === "clothing";
      if (isClothingProduct !== wantsClothing) return false;
      if (!wantsClothing) {
        const hubs = getProductHubs(p);
        if (effectiveStoreMode === "pine") {
          if (!hubs.includes("hub3")) return false;
        } else {
          if (hubs.length && !hubs.includes("hub1") && !hubs.includes("hub2")) return false;
        }
      }
      return true;
    }),
  [products, wantsClothing, effectiveStoreMode]);

  // Fuzzy search (Fuse.js): typo- and case-tolerant matching over name +
  // category. Rebuilt only when `base` changes (memoised — fine for ~1.2k
  // products). Tuned to surface close matches ("avryn"/"avrn"/"avryen" →
  // "Adidas Avryn") without going so loose it returns everything:
  //   threshold 0.4  → moderate fuzziness
  //   ignoreLocation → match anywhere in the string (partial matches)
  //   minMatchCharLength 2 → ignore 1-char noise (1-char queries handled below)
  const fuse = useMemo(() => new Fuse(base, {
    keys: [{ name: "name", weight: 0.85 }, { name: "category", weight: 0.15 }],
    threshold: 0.4,
    ignoreLocation: true,
    minMatchCharLength: 2,
  }), [base]);

  const filtered = useMemo(() => {
    const q = search.trim();
    if (!q) return base;
    // BARCODE / SKU match — typing or SCANNING a product code finds the product
    // directly, not just its name. Matches the product-level barcode + sku and any
    // per-size code (products/{id}/barcodes/{sizeKey}, carried on the product). Exact
    // match for a full scan; 3+ digit substring for partial typing. Code hits come
    // first so a scan jumps straight to the product.
    const codeHits = /\d/.test(q) ? base.filter(p => {
      const codes = [];
      if (p.barcode != null) codes.push(String(p.barcode));
      if (p.sku != null) codes.push(String(p.sku));
      if (p.barcodes && typeof p.barcodes === "object")
        for (const c of Object.values(p.barcodes)) if (c != null) codes.push(String(c));
      return codes.some(c => c === q || (q.length >= 3 && c.includes(q)));
    }) : [];
    const merge = (rest) => {
      if (!codeHits.length) return rest;
      const seen = new Set(codeHits.map(p => p.id));
      return [...codeHits, ...rest.filter(p => !seen.has(p.id))];
    };
    // 1-char queries: Fuse's minMatchCharLength would return nothing, so fall
    // back to a plain case-insensitive substring match for the first letter.
    if (q.length < 2) {
      const lc = q.toLowerCase();
      return merge(base.filter(p =>
        p.name.toLowerCase().includes(lc) || (p.category || "").toLowerCase().includes(lc)));
    }
    return merge(fuse.search(q).map(r => r.item));
  }, [search, base, fuse]);

  // Compute the hub an order placed right now should land in. Single source
  // of truth used for both `hub` (legacy field) and `placedAtHub` (Phase 14B).
  const computeHubForItem = (item) => {
    if (effectiveStoreMode === "pine") return "hub3";
    // Display (partner) requests route to the hub where the PRODUCT actually
    // lives — not a forced global default. (Previously partner requests always
    // returned "hub1"; now they resolve to the product's own hub like every
    // other line, so a hub2 product's display request lands in hub2, etc.)
    return getProductHubs(item.product).find(h => h === "hub1" || h === "hub2") || "hub1";
  };

  const hasClothingInCart = cart.some(it => it.productType === "clothing");
  // Cart-driven submit decision: a line needs the customer Checkout
  // (name/phone/WhatsApp) when it's a sneaker OR a clothing line tagged
  // "customer" (trial). Any such line forces the Checkout flow; an all-refill
  // clothing cart skips the sheet and goes straight through placeRefillRequests.
  const isCustomerLine    = (it) => (it.productType || "sneaker") === "sneaker"
                                 || (it.productType === "clothing" && it.intent === "customer");
  const hasCustomerInCart = cart.some(isCustomerLine);
  // Counts for the action labels: a mixed cart (customer + refill, reachable by
  // switching modes mid-cart) is placed in two steps, so each label should show
  // only the lines its action will actually submit.
  const customerCount     = cart.filter(isCustomerLine).length;
  const refillCount       = cart.length - customerCount;

  const resetSheet = () => { setSelected(null); setPendingSize(""); setNaNote(null); setPendingQty(1); setPendingDisplay(false); setPendingDisplayPartner(false); };

  const addToCart = () => {
    if (!selected) return;
    // Clothing customer orders use the SAME size-sheet UX as sneakers, but a
    // size is mandatory (no Display Partner for clothing) and each line is
    // tagged clothing/customer so it routes to Hub C via Checkout.
    const isClothingCustomer = (selected.productType || "sneaker") === "clothing";
    if (isClothingCustomer) {
      if (!pendingSize) return;
      // Availability check at Add time, net of units already in the cart —
      // covers both the sold-out-since-tap race AND a quantity larger than
      // the hub can supply (a 10-qty add into a hub holding 1). Blocks with
      // the explanatory note rather than silently clamping; the dispatch-side
      // negative guard stays the concurrency backstop.
      const reps = Math.max(1, Math.min(10, pendingQty));
      const remaining = hubQty(selected.id, pendingSize) - clothingInCart(selected.id, pendingSize);
      if (reps > remaining) {
        setNaNote({ size: pendingSize, left: Math.max(0, remaining) });
        if (remaining <= 0) setPendingSize("");
        return;
      }
      setNaNote(null);
      const line = { product: selected, size: pendingSize, productType: "clothing", intent: "customer" };
      setCart(c => [...c, ...Array.from({ length: reps }, () => ({ ...line }))]);
      resetSheet();
      return;
    }
    // Sneakers: size is optional when a Display Partner request is set.
    if (!pendingSize && !pendingDisplayPartner) return;
    // Quantity expansion: pendingQty > 1 → push N identical cart lines so the
    // warehouse fulfils one box per pair (no "qty" multiplier on a single
    // line). Display Partner rows ignore qty (one-off by nature).
    const reps = (pendingSize && !pendingDisplayPartner)
      ? Math.max(1, Math.min(10, pendingQty))
      : 1;
    const line = { product: selected, size: pendingSize || null, requestDisplay: false, requestDisplayPartner: pendingDisplayPartner };
    setCart(c => [...c, ...Array.from({ length: reps }, () => ({ ...line }))]);
    resetSheet();
  };

  // The bulk ClothingCard (CR / refill mode only) reports a batch of cart lines
  // at once (one per non-zero size). Each line is tagged intent:"refill" so the
  // submit decision sends them through placeRefillRequests (hub2/hub3), never
  // the customer Checkout.
  const addClothingLines = (lines) =>
    setCart(c => [...c, ...lines.map(l => ({ ...l, intent: "refill" }))]);

  // Desktop quick-add: add a size straight to the cart (qty lines) — the pointer
  // shortcut past the bottom sheet. Same line shapes as addToCart (clothing→
  // customer order, else sneaker); the sheet stays available on mobile.
  // Returns the number of units actually added — clothing adds are capped at
  // what the hub can still cover beyond the cart (repeated quick-adds can't
  // stack past availability); desktop uses the return value to explain a
  // blocked/partial add. Sneakers always add the full amount.
  const quickAdd = (p, size, qty = 1) => {
    let reps = Math.max(1, Math.min(10, qty | 0 || 1));
    const isClothingCustomer = (p.productType || "sneaker") === "clothing";
    if (isClothingCustomer) {
      reps = Math.min(reps, Math.max(0, hubQty(p.id, size) - clothingInCart(p.id, size)));
      if (reps <= 0) return 0;
    }
    const line = isClothingCustomer
      ? { product: p, size, productType: "clothing", intent: "customer" }
      : { product: p, size, requestDisplay: false, requestDisplayPartner: false };
    setCart(c => [...c, ...Array.from({ length: reps }, () => ({ ...line }))]);
    return reps;
  };
  // Remove one cart line matching a product+size (+ display-partner flag) — the
  // desktop drawer − / remove.
  const removeOneLine = (productId, size, dp = false) => setCart(c => {
    const i = c.findIndex(l => l.product?.id === productId && l.size === size && !!l.requestDisplayPartner === !!dp);
    return i < 0 ? c : [...c.slice(0, i), ...c.slice(i + 1)];
  });
  // Desktop Display-Partner request — ONE line, size optional (sneakers only),
  // mirroring addToCart's requestDisplayPartner branch.
  const addDisplayPartner = (p, size) =>
    setCart(c => [...c, { product: p, size: size || null, requestDisplay: false, requestDisplayPartner: true }]);

  const removeFromCart = idx => setCart(c => c.filter((_, i) => i !== idx));

  const openCheckout = () => { resetSheet(); setCheckoutOpen(true); };
  const closeCheckout = () => { setCheckoutOpen(false); setCustomerName(""); setCustomerPhone(""); setMarketingOptIn(false); };

  const placeOrders = async (bypassDestConfirm = false) => {
    if (!cart.length || !customerName || submitting) return;
    // Phone is required for customer orders and must be a valid 10-digit SA
    // number starting with 0 (the Place button enforces this too).
    if (!isValidLocalSAPhone(customerPhone)) return;
    if (noStoreAccess) { alert("No store assigned — contact admin."); return; }
    // Affirm the destination shop once per shop-session (see PLACEMENT
    // DESTINATION GUARD). The modal's confirm re-invokes with bypass=true.
    if (!bypassDestConfirm && needsDestConfirm) { setDestConfirm({ run: () => placeOrders(true) }); return; }
    setSubmitting(true);
    try {
      const normalizedPhone = normalizeSAPhone(customerPhone);
      const now = serverNowIso();
      // Resolve the customer identity ONCE per checkout (all lines share it):
      // canonical 0… customerId + C-number, claimed race-safely at order time
      // so the POS loads the customer instead of re-resolving by phone.
      // NEVER blocks placement — on failure the orders go out with
      // customerPending: true and the POS falls back to its own phone-key
      // resolution. (Also replaces the old post-placement upsertCustomer:
      // the record's order bookkeeping is upserted inside.)
      const identity = await resolveOrderCustomer(normalizedPhone, customerName, now, marketingOptIn);
      const placed = [];
      // The checkout flow handles every line that needs customer info: sneakers
      // (always) plus clothing tagged "customer" (trial). Clothing "refill"
      // lines stay in the cart and get placed via the floating Place Refill
      // Request bar (different shape, no customer info).
      const customerCart = cart.filter(isCustomerLine);
      for (const item of customerCart) {
        const orderNum = await getNextOrderNumber();
        // Customer clothing orders route to the universe's CR hub (hub2 for
        // PE/Trophy, hub3 for Pine — CR_HUB_BY_UNIVERSE), where the clothing
        // stock actually lives. Unlike the retired hubC trial (not a stock
        // location, so dispatch never moved stock), a CR-hub order rides the
        // normal dispatch path: Send fires the real hub→destShop transfer.
        // Sneakers keep their existing hub routing.
        const isClothingCustomer = item.productType === "clothing";
        const placedHub = isClothingCustomer
          ? (CR_HUB_BY_UNIVERSE[effectiveStoreMode] || "hub2")
          : computeHubForItem(item);
        const order = {
          id: orderNum,
          productId: item.product.id,
          productName: item.product.name,
          productPhoto: item.product.photo ?? null,
          productPhotoUrl: item.product.photoUrl ?? null,
          size: item.size,
          sentSize: null,
          // Explicit type so the warehouse/inference treats a clothing customer
          // order as clothing (size letters already imply it, but be explicit).
          productType: isClothingCustomer ? "clothing" : (item.product.productType || "sneaker"),
          customerName,
          customerPhone: normalizedPhone,
          // Customer identity resolved at order time (utils/orderCustomer).
          // customerPending: true means resolution failed and the POS must
          // fall back to its own phone-key lookup for this order.
          customerId: identity?.customerId ?? null,
          customerCode: identity?.customerCode ?? null,
          customerPending: identity?.customerPending === true,
          // Phase 14B: hub mirrors placedAtHub (Central pine routing) — Display
          // Partner stays hub1 in Central; Pine always routes to hub3. Clothing
          // customer orders land in the universe's CR hub (hub2/hub3).
          hub: placedHub,
          placedAtHub: placedHub,
          // Record which operational store (central/pine) the order was placed
          // from. The hub usually implies it, but persist the store explicitly
          // for tracking.
          placedStore: effectiveStoreMode,
          // The physical shop the order is for (marathon-pe / trophy / marathon-pine).
          // Drives the warehouse→shop stock transfer recorded on dispatch.
          destShop: effectiveShop,
          requestDisplay: item.requestDisplay || false,
          requestDisplayPartner: item.requestDisplayPartner || false,
          status: STATUS.INCOMING,
          createdAt: now,
          updatedAt: now,
          readyAt: null,
          outOfStockAt: null,
          comingTomorrowAt: null,
          collectedAt: null,
          // Display partner refill tracking (Phase 9 / 9.5). Populated by Warehouse
          // updateStatus when a partner order transitions to READY; cleared on
          // any revert. Resolved from the product's stocking hub (which the order
          // is now also placed into — display requests route to the product's hub).
          // displayRefillStatus enum: null = active task, 'refilled' = display
          // replenished, 'stockDepleted' = no inventory left to refill (feeds
          // Phase 11 Insights via order filter, no separate log).
          displayRefillScheduledAt:    null,
          displayRefillHub:            null,
          displayRefillStatus:         null,
          displayRefilledAt:           null,
          displayRefillStockDepletedAt:null,
          displayRefilledBy:           null,
        };
        await writeOrder(order);
        logInsight({
          timestamp: now,
          // productId (p{timestamp}) is the durable product key. Logging it on
          // every event lets analytics join on id instead of name-matching,
          // which only resolves ~55-66% of historical events. Consumers still
          // fall back to productName for events written before this field.
          productId: item.product.id,
          productName: item.product.name,
          productCategory: item.product.category || "",
          productType: item.product.productType || "sneaker",
          size: item.size,
          customerName,
          customerPhone: normalizedPhone,
          orderNumber: orderNum,
          action: "placed",
          placedAtHub: placedHub,
          // Stamp the destination store so Insights' PE/Trophy/Pine filter works
          // (placedAtHub can't distinguish PE vs Trophy — both are central hubs).
          destShop: effectiveShop,
        });
        sendWhatsAppTemplate(normalizedPhone, "order_placed", [customerName, orderNum, item.product.name, item.size]);
        placed.push(order);
        // Drop THIS line from the cart the instant it's written. writeOrder now
        // rethrows async failures, so if a LATER line in the batch throws the
        // catch preserves the (remaining) cart — pruning per-line here means a
        // retry re-places only the unplaced remainder instead of duplicating
        // already-written lines with fresh order numbers. Object identity (not a
        // productId/size key) so qty>1 duplicate lines prune individually.
        setCart(prev => prev.filter(it => it !== item));
      }
      setLastOrders(placed);
      // Print the customer order slip(s) — one per order, in a single 80mm print
      // job (thermal via the browser dialog, same as the POS). Fire-and-forget so
      // a print hiccup never blocks the placement; WhatsApp still goes out above.
      // DESKTOP ONLY: the thermal printer lives at the assistant desk. On phones/
      // tablets (narrow) this would just pop the mobile browser's print dialog with
      // no printer attached, so suppress it there.
      if (isDesktop && placed.length) printOrderSlips(placed).catch(err => console.warn("order slip print failed:", err));
      // Keep clothing REFILL items in the cart so the user can place them next
      // via the floating Place Refill Request bar. Just-placed customer lines
      // (sneakers + clothing-customer) drop out.
      setCart(prev => prev.filter(it => !isCustomerLine(it)));
      closeCheckout();
    } catch (e) {
      console.error("Failed to place orders:", e);
      // Surface the REAL reason instead of always blaming the connection — a
      // write rejected for a data problem (e.g. a missing product field) is not
      // a network fault, and mislabelling it as one hid this bug for weeks.
      alert(
        `Couldn't place the order.\n\nReason: ${e?.message || "unknown error"}\n\n` +
        `If this keeps happening it may not be your internet — tell a manager and mention this message.`
      );
    } finally {
      setSubmitting(false);
    }
  };

  // Phase 12B: places one Firebase order per clothing cart line. No customer
  // info, no WhatsApp send, hub forced to hub2, qty stored on the order.
  // Clothing items are removed from the cart on success; any sneaker items
  // remain (rare — usually clothing-only cart triggers this path).
  const placeRefillRequests = async (bypassDestConfirm = false) => {
    // Refills are clothing lines NOT tagged "customer" (those go through
    // Checkout → Hub C). Call sites already gate on hasCustomerInCart, but
    // keep the filter intent-aware so it stays correct if that ever changes.
    const isRefillLine = (it) => it.productType === "clothing" && it.intent !== "customer";
    const clothingCart = cart.filter(isRefillLine);
    if (!clothingCart.length || submitting) return;
    if (noStoreAccess) { alert("No store assigned — contact admin."); return; }
    // CR refill orders also carry destShop:effectiveShop and ship on fulfil, so
    // they mis-route the same way — affirm the destination shop here too.
    if (!bypassDestConfirm && needsDestConfirm) { setDestConfirm({ run: () => placeRefillRequests(true) }); return; }
    setSubmitting(true);
    try {
      const now = serverNowIso();
      const placed = [];
      // ONE refill number for the WHOLE cart (not per line) — clothing refills
      // must not consume the sneaker sequence one-per-size. Each line still needs
      // its own /orders node (per-size CR fulfilment + insights key off it), so
      // the line id is R{n}-{i} — a unique node key under the single cart number.
      const refillNum = await getNextRefillNumber();
      let lineIdx = 0;
      for (const item of clothingCart) {
        lineIdx += 1;
        const orderNum = `${refillNum}-${lineIdx}`;
        // CR routing is THE one map: Pine → hub3, Central (PE/Trophy) → hub2.
        const placedHub = CR_HUB_BY_UNIVERSE[effectiveStoreMode] || "hub2";
        const order = {
          id: orderNum,
          productId: item.product.id,
          productName: item.product.name,
          productPhoto: item.product.photo ?? null,
          productPhotoUrl: item.product.photoUrl ?? null,
          size: item.size,
          sentSize: null,
          qty: item.qty || 1,
          customerName: "Shop Refill",
          customerPhone: null,
          hub: placedHub,
          placedAtHub: placedHub,
          placedStore: effectiveStoreMode,
          // Physical shop this refill is for — drives the warehouse→shop transfer
          // recorded on dispatch.
          destShop: effectiveShop,
          productType: "clothing",
          requestDisplay: false,
          requestDisplayPartner: false,
          status: STATUS.INCOMING,
          createdAt: now,
          updatedAt: now,
          readyAt: null,
          outOfStockAt: null,
          comingTomorrowAt: null,
          collectedAt: null,
          // Display refill fields kept null for shape consistency — clothing
          // never participates in the partner display flow.
          displayRefillScheduledAt:    null,
          displayRefillHub:            null,
          displayRefillStatus:         null,
          displayRefilledAt:           null,
          displayRefillStockDepletedAt:null,
          displayRefilledBy:           null,
          // Phase 12C: clothing-refill resolution fields. Set by Hub 2
          // Warehouse staff via the new Clothing tab.
          clothingRefillStatus:        null,
          clothingRefilledAt:          null,
          clothingOutOfStockAt:        null,
          clothingRefilledBy:          null,
        };
        await writeOrder(order);
        logInsight({
          timestamp: now,
          // productId joins analytics on the durable key; see the note at the
          // checkout logInsight site. Older events fall back to productName.
          productId: item.product.id,
          productName: item.product.name,
          productCategory: item.product.category || "",
          productType: "clothing",
          size: item.size,
          // qty on the event so the Clothing Refills tab can sum UNITS from the
          // log for past windows (a refill line is one event with qty>1, unlike
          // sneaker checkout which expands qty into one event per unit). Legacy
          // events predate this field — readers fall back to 1.
          qty: item.qty || 1,
          customerName: "Shop Refill",
          customerPhone: null,
          orderNumber: orderNum,
          action: "placed",
          placedAtHub: placedHub,
          // Stamp the destination store so Insights' PE/Trophy/Pine filter works
          // (placedAtHub can't distinguish PE vs Trophy — both are central hubs).
          destShop: effectiveShop,
        });
        placed.push(order);
        // Per-line prune — same rationale as placeOrders: a later throw must not
        // let a retry duplicate the refill lines already written.
        setCart(prev => prev.filter(it => it !== item));
      }
      setLastOrders(placed);
      // Drop the placed refill lines; leave sneakers and any clothing-customer
      // lines in place (the latter still need to go through Checkout).
      setCart(prev => prev.filter(it => !(it.productType === "clothing" && it.intent !== "customer")));
    } catch (e) {
      console.error("Failed to place refill requests:", e);
      // Same as placeOrders: report the real reason, don't default to blaming
      // the connection for what is often a data-shaped write rejection.
      alert(
        `Couldn't place the refill request.\n\nReason: ${e?.message || "unknown error"}\n\n` +
        `If this keeps happening it may not be your internet — tell a manager and mention this message.`
      );
    } finally {
      setSubmitting(false);
    }
  };

  const sheetStyle = {
    background:CARD, border:BORDER,
    borderTopLeftRadius:RADIUS, borderTopRightRadius:RADIUS,
    padding:"2rem", width:"100%", maxWidth:"520px", maxHeight:"85vh", overflowY:"auto",
    boxShadow: "0 -4px 30px rgba(60,110,255,.12)",
  };

  // Phase 15: a user assigned to zero stores can't place orders anywhere. Block
  // the whole order surface with a clear message rather than showing an empty
  // store toggle + product grid that would route nowhere.
  if (noStoreAccess) {
    return (
      <div style={{ minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, maxWidth:430, margin:"0 auto",
                    display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:18, padding:"0 28px", textAlign:"center" }}>
        <div style={{ fontSize:40 }}>🔒</div>
        <div style={{ fontSize:18, fontWeight:700 }}>No store assigned</div>
        <div style={{ fontSize:14, color:"rgba(255,255,255,.5)", lineHeight:1.5, maxWidth:300 }}>
          Your account isn't assigned to any store yet, so you can't place orders. Contact an admin to get access.
        </div>
        <button onClick={onExit}
                style={{ marginTop:6, background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)",
                         borderRadius:10, padding:"10px 18px", color:"#fff", fontSize:13, fontWeight:600, cursor:"pointer", fontFamily:FONT }}>
          ← Switch View
        </button>
      </div>
    );
  }

  return (
    <div style={{ minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, maxWidth:880, margin:"0 auto", overflowX:"hidden", paddingBottom: cart.length > 0 ? 90 : 40 }}>
      {/* Desktop workspace (≥1024px, sneaker + clothing customer orders) —
          full-screen overlay reusing this view's cart + checkout. Phone/iPad
          + CR fall through to the existing layout below. The shared Checkout
          sheet and photo lightbox (rendered later) surface over it. */}
      {isDesktop && !noStoreAccess && (
        <AssistantDesktop
          products={products} effectiveShop={effectiveShop} availableShops={availableShops}
          onSelectShop={selectShop} shopRegistry={shopRegistry}
          search={search} setSearch={setSearch}
          cart={cart} onQuickAdd={quickAdd} onRemoveOne={removeOneLine} onAddDisplayPartner={addDisplayPartner}
          onViewPhoto={setFullPhoto} onSwitchView={onExit} onSignOut={assistantSignOut}
          userEmail={assistantUser?.email || ""} mode={mode} setMode={setMode}
          customerName={customerName} setCustomerName={setCustomerName}
          customerPhone={customerPhone} setCustomerPhone={setCustomerPhone}
          marketingOptIn={marketingOptIn} setMarketingOptIn={setMarketingOptIn}
          submitting={submitting} onPlaceOrder={placeOrders}
          customerIndex={customerIndex} onPickCustomer={pickCustomer}
          onAddClothing={addClothingLines} onPlaceRefill={placeRefillRequests}
          onOpenTracking={() => setTrackingOpen(true)} trackingPending={trackingPending}
          hubQty={hubQty} servingHubLabel={HUB_LABELS[servingHub] || servingHub} />
      )}
      {/* Responsive product-grid columns: phone stays 2-up (photo) / 1-up (refill);
          iPad (≥768px) goes 5-up (photo) / 2-up (refill). Fixed counts (not auto-fill)
          so it's exactly 5 across on tablet regardless of orientation. */}
      <style>{`
        .mc-grid-photo  { grid-template-columns: repeat(2, 1fr); }
        .mc-grid-refill { grid-template-columns: 1fr; }
        @media (min-width: 768px) {
          .mc-grid-photo  { grid-template-columns: repeat(5, 1fr); }
          .mc-grid-refill { grid-template-columns: repeat(2, 1fr); }
        }
        /* Siri-style price: all 4 candidate hues mixed into one animated,
           iridescent gradient that drifts across the text. */
        .mc-price-siri {
          background: linear-gradient(90deg, #6E7BFF, #5D8BFF, #8A6DFF, #7F5AF0, #8A6DFF, #5D8BFF, #6E7BFF);
          background-size: 300% 100%;
          -webkit-background-clip: text; background-clip: text;
          -webkit-text-fill-color: transparent; color: transparent;
          animation: mcPriceSiri 4s linear infinite;
        }
        @keyframes mcPriceSiri { from { background-position: 0% 0; } to { background-position: 300% 0; } }
        @media (prefers-reduced-motion: reduce) { .mc-price-siri { animation: none; } }
      `}</style>
      {/* TOP BAR */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"50px 14px 12px" }}>
        <div onClick={onExit}
             style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.1)", borderRadius:10, padding:"8px 14px", display:"flex", alignItems:"center", gap:6, cursor:"pointer" }}>
          <span style={{ fontSize:12, color:"rgba(255,255,255,.7)" }}>← Switch View</span>
        </div>
        <div style={{ textAlign:"center" }}>
          <div style={{ fontSize:10, color:"rgba(255,255,255,.4)", letterSpacing:"0.5px" }}>Viewing as:</div>
          <div style={{ fontSize:15, fontWeight:700, color:"#4A7FFF", letterSpacing:"0.5px" }}>ASSISTANT</div>
        </div>
        {/* Spacer balances the ← Switch View button so "ASSISTANT" stays
            centred; the product mode selector now lives in its own row below. */}
        <div style={{ width:92 }} />
      </div>

      {/* Product mode — Sneakers / Clothing, both CUSTOMER order flows.
          Clothing was restored 2026-07-16, now routed to the universe's CR hub
          (hub2/hub3) with live per-size availability. The CR (manual Clothing
          Refill) option stays RETIRED (owner decision 2026-07-12, engine
          go-live) — the auto-refill engine detects sales and creates refill
          requests itself; the CR plumbing (ClothingCard / addClothingLines /
          placeRefillRequests) is kept intact behind mode==="cr" as the manual
          fallback if automation ever needs bypassing. */}
      <div style={{ display:"flex", justifyContent:"center", padding:"0 14px 8px" }}>
        <div style={{ display:"flex", width:"100%", maxWidth:360, background:"rgba(255,255,255,.04)", border:"1px solid rgba(60,110,255,.25)", borderRadius:12, padding:3, gap:2 }}>
          {[["sneaker","Sneakers"],["clothing","Clothing"]].map(([val, label]) => {
            const on = mode === val;
            return (
              <button key={val} onClick={() => { setMode(val); resetSheet(); }}
                style={{ flex:1, padding:"7px 6px", borderRadius:9, border:"none", cursor:"pointer", fontSize:12, fontWeight:700,
                         background: on ? "rgba(60,110,255,.25)" : "transparent",
                         color: on ? "#fff" : "rgba(255,255,255,.5)",
                         boxShadow: on ? "0 0 6px rgba(60,110,255,.35)" : "none" }}>
                {label}
              </button>
            );
          })}
        </div>
      </div>

      {/* SHOP toggle — the assistant picks which physical shop (Marathon PE /
          Trophy / Pine) the order is for; this is recorded as order.destShop and
          drives the warehouse→shop transfer on dispatch. Per-device localStorage.
          Only renders shops this user is assigned to (expanded from their
          central/pine assignment); hidden entirely when they have exactly one
          (auto-selected by the clamp effect) so there's zero chance of mis-picking. */}
      {!singleShop && (
      <div style={{ display:"flex", justifyContent:"center", padding:"0 14px 8px" }}>
        <div style={{ display:"flex", background:"rgba(255,255,255,.04)", border:"1px solid rgba(60,110,255,.25)", borderRadius:12, padding:3, gap:2 }}>
          {availableShops.map((s) => {
            const on = effectiveShop === s.id;
            return (
              <button key={s.id} onClick={() => requestShopSwitch(s.id)}
                style={{ padding:"6px 22px", borderRadius:9, border:"none", cursor:"pointer", fontSize:11.5, fontWeight:700,
                         background: on ? "rgba(60,110,255,.25)" : "transparent",
                         color: on ? "#fff" : "rgba(255,255,255,.5)",
                         boxShadow: on ? "0 0 6px rgba(60,110,255,.35)" : "none" }}>
                {labelFor(s.id, shopRegistry)}
              </button>
            );
          })}
        </div>
      </div>
      )}

      {/* ── SHOP-SWITCH WARNING MODAL ──────────────────────────────────────────
          Red, blocking, deliberately alarming. Fires when the assistant taps a
          DIFFERENT shop on the toggle. Names the from/to shops in plain words,
          spells out that every future order routes to the new store, and flags
          any cart lines that would go with it. Only "Yes, switch" commits. */}
      {pendingShopSwitch && (() => {
        const fromLabel = labelFor(effectiveShop, shopRegistry);
        const toLabel   = labelFor(pendingShopSwitch, shopRegistry);
        const cartCount = cart.length;
        return (
          <div onClick={() => setPendingShopSwitch(null)}
               style={{ position:"fixed", inset:0, zIndex:9999, background:"rgba(0,0,0,.8)", backdropFilter:"blur(3px)",
                        display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
            <div onClick={e => e.stopPropagation()}
                 style={{ width:"100%", maxWidth:380, background:"#1c0e0e", border:"2px solid rgba(255,70,70,.6)",
                          borderRadius:18, padding:"26px 22px", textAlign:"center", fontFamily:FONT,
                          boxShadow:"0 0 44px rgba(255,45,45,.4)" }}>
              <div style={{ fontSize:46, lineHeight:1, marginBottom:12 }}>⚠️</div>
              <div style={{ color:"#FF5C5C", fontWeight:800, fontSize:19, letterSpacing:".4px", marginBottom:12 }}>
                CHANGING STORE
              </div>
              <div style={{ color:"#fff", fontSize:14.5, lineHeight:1.55, marginBottom:9 }}>
                Switching from <strong style={{ color:"#FFD166" }}>{fromLabel}</strong> to{" "}
                <strong style={{ color:"#FF8A8A" }}>{toLabel}</strong>.
              </div>
              <div style={{ color:"rgba(255,255,255,.78)", fontSize:13.5, lineHeight:1.55, marginBottom: cartCount ? 12 : 22 }}>
                Every order you place will now go to <strong style={{ color:"#FF8A8A" }}>{toLabel}</strong>.
                If this is the wrong store, the stock ships to the wrong branch.
              </div>
              {cartCount > 0 && (
                <div style={{ color:"#FFD166", fontSize:12.5, fontWeight:700, marginBottom:22, lineHeight:1.5,
                              background:"rgba(245,196,81,.1)", border:"1px solid rgba(245,196,81,.35)",
                              borderRadius:10, padding:"9px 11px" }}>
                  You have {cartCount} item{cartCount > 1 ? "s" : ""} in the cart — they’ll be placed for {toLabel}.
                </div>
              )}
              <div style={{ display:"flex", gap:10 }}>
                <button onClick={() => setPendingShopSwitch(null)}
                        style={{ flex:1, padding:"13px 0", borderRadius:11, border:"1px solid rgba(255,255,255,.28)",
                                 background:"transparent", color:"#fff", fontWeight:700, fontSize:14, cursor:"pointer", fontFamily:FONT }}>
                  Cancel
                </button>
                <button onClick={confirmShopSwitch}
                        style={{ flex:1.4, padding:"13px 8px", borderRadius:11, border:"none",
                                 background:"#E03131", color:"#fff", fontWeight:800, fontSize:14, cursor:"pointer", fontFamily:FONT }}>
                  Switch to {toLabel}
                </button>
              </div>
            </div>
          </div>
        );
      })()}

      {/* ── Placement destination confirm ── fires on the FIRST order of a shop-
          session for multi-shop users (see PLACEMENT DESTINATION GUARD). Calmer
          than the red switch modal — it's a routine "confirm where this ships",
          the backstop for a device left on the wrong shop that never switched. */}
      {destConfirm && (() => {
        const toLabel = labelFor(effectiveShop, shopRegistry);
        return (
          <div onClick={() => { setDestConfirm(null); setCheckoutOpen(false); }}
               style={{ position:"fixed", inset:0, zIndex:9999, background:"rgba(0,0,0,.8)", backdropFilter:"blur(3px)",
                        display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
            <div onClick={e => e.stopPropagation()}
                 style={{ width:"100%", maxWidth:380, background:"#0c1730", border:"2px solid rgba(74,127,255,.6)",
                          borderRadius:18, padding:"26px 22px", textAlign:"center", fontFamily:FONT,
                          boxShadow:"0 0 44px rgba(60,110,255,.35)" }}>
              <div style={{ fontSize:42, lineHeight:1, marginBottom:12 }}>🏬</div>
              <div style={{ color:"#6A9FFF", fontWeight:800, fontSize:18, letterSpacing:".4px", marginBottom:12 }}>
                CONFIRM STORE
              </div>
              <div style={{ color:"#fff", fontSize:14.5, lineHeight:1.55, marginBottom:9 }}>
                This order ships to <strong style={{ color:"#FFD166" }}>{toLabel}</strong>.
              </div>
              <div style={{ color:"rgba(255,255,255,.72)", fontSize:13, lineHeight:1.55, marginBottom:22 }}>
                If the customer is at a different branch, tap <strong style={{ color:"#fff" }}>Wrong store</strong> and switch
                stores first — otherwise the stock ships to the wrong shop.
              </div>
              <div style={{ display:"flex", gap:10 }}>
                <button onClick={() => { setDestConfirm(null); setCheckoutOpen(false); }}
                        style={{ flex:1, padding:"13px 0", borderRadius:11, border:"1px solid rgba(255,255,255,.28)",
                                 background:"transparent", color:"#fff", fontWeight:700, fontSize:14, cursor:"pointer", fontFamily:FONT }}>
                  Wrong store
                </button>
                <button onClick={runDestConfirm}
                        style={{ flex:1.4, padding:"13px 8px", borderRadius:11, border:"none",
                                 background:"#2F6FE0", color:"#fff", fontWeight:800, fontSize:14, cursor:"pointer", fontFamily:FONT }}>
                  Send to {toLabel}
                </button>
              </div>
            </div>
          </div>
        );
      })()}

      {/* Mode hint line — clarifies where CR refill orders go. (The customer
          "Clothing → Hub C" mode was removed; only Sneakers + CR remain.) */}
      {mode === "cr" && (
        <div style={{ textAlign:"center", fontSize:10, color:"rgba(255,255,255,.4)", letterSpacing:"0.3px", padding:"0 14px 8px" }}>
          Store refill — set quantities per size
        </div>
      )}

      {/* "Shop stock · view only" card REMOVED from the assistant view (owner
          decision 2026-07-16). The ShopStockPanel/ShopStockList components are
          kept intact above in case the card returns elsewhere. */}

      {/* PLACE ORDER HERO */}
      <div style={{ position:"relative", width:"100%", height:160, overflow:"hidden", marginBottom:4 }}>
        <img src="/hero/place-order.jpg" alt="Place Order" style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%", objectFit:"cover", objectPosition:"center" }}/>
        <div style={{ position:"absolute", inset:0, background:"linear-gradient(to right,rgba(0,0,0,.3),transparent 30%,transparent 60%,rgba(0,0,0,.3))" }}/>
        <div style={{ position:"absolute", bottom:0, left:0, right:0, height:50, background:"linear-gradient(transparent,#000)" }}/>
        <div style={{ position:"absolute", top:0, left:0, right:0, height:30, background:"linear-gradient(#000,transparent)" }}/>
      </div>
      <div style={{ fontSize:14, color:"rgba(255,255,255,.35)", padding:"2px 14px 14px" }}>Tap a product to add it to the cart</div>

      <div style={{ padding:"0 13px" }}>
      {/* ── Confirmation banner ── */}
      {lastOrders.length > 0 && (() => {
        // Clothing now appears in both flows, so key the headline off the
        // refill marker rather than productType (customer clothing → Hub C
        // reads as a normal customer order).
        const isRefill = lastOrders[0].customerName === "Shop Refill";
        const headline = isRefill
          ? `Refill request placed — ${lastOrders.length} line${lastOrders.length > 1 ? "s" : ""}`
          : `${lastOrders.length} order${lastOrders.length > 1 ? "s" : ""} placed for ${lastOrders[0].customerName}`;
        return (
          <div style={{ background:"rgba(0,150,70,.1)", border:"1px solid rgba(0,150,70,.3)", borderRadius:RADIUS, padding:"1.25rem", marginBottom:"1.5rem", display:"flex", alignItems:"flex-start", gap:"1rem" }}>
            <div style={{ flex:1 }}>
              <div style={{ color:"#4ADE80", fontWeight:"600", marginBottom:"0.3rem", fontSize:"0.9rem" }}>
                {headline}
              </div>
              {lastOrders.map(o => (
                <div key={o.id} style={{ color:"#888", fontSize:"0.82rem" }}>
                  <strong style={{ color:"#ccc" }}>#{o.id}</strong> — {o.productName}{o.size ? ` Sz ${formatSize(o.size)}` : ""}{o.qty && o.qty > 1 ? ` × ${o.qty}` : ""}
                </div>
              ))}
            </div>
            <div style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:8 }}>
              <button onClick={() => setLastOrders([])} style={{ background:"transparent", border:"none", color:"#555", cursor:"pointer", fontSize:"1rem" }}>✕</button>
              {/* Reprint the slip if the auto-print was dismissed or failed — the
                  only recovery path for a physical hand-to-customer receipt.
                  Desktop-only, matching the auto-print: no thermal printer on phones. */}
              {isDesktop && !isRefill && (
                <button onClick={() => printOrderSlips(lastOrders).catch(err => console.warn("reprint slip failed:", err))}
                        title="Reprint the order slip"
                        style={{ display:"flex", alignItems:"center", gap:6, background:"rgba(255,255,255,.05)", border:"1px solid rgba(255,255,255,.14)", borderRadius:8, color:"#cfd6e4", cursor:"pointer", fontSize:"0.72rem", fontFamily:FONT, padding:"5px 10px", whiteSpace:"nowrap" }}>
                  🖨 Reprint slip
                </button>
              )}
            </div>
          </div>
        );
      })()}

      {/* "Track requests" (refill tracking) button REMOVED from the assistant
          view (owner decision 2026-07-16) — the engine's refill requests are
          the warehouse's concern; shop staff don't need the card. The tracking
          page (RefillTrackingPage / trackingOpen) is kept intact below in case
          an entry point ever returns. */}


      {/* Inline cart summary removed (Phase 12B) — the floating bottom bar
          below the screen is now the single cart trigger. Sneaker users still
          see the cart review inside the Checkout sheet. */}

      {/* SEARCH BAR */}
      <div style={{ paddingBottom:14 }}>
        <div style={{ background:"rgba(255,255,255,.04)", border:"1px solid rgba(60,110,255,.3)", borderRadius:22, padding:"12px 16px", display:"flex", alignItems:"center", gap:10 }}>
          <svg width="16" height="16" viewBox="0 0 24 24" stroke="rgba(255,255,255,.35)" fill="none" strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search products..." style={{ background:"transparent", border:"none", outline:"none", color:"#fff", fontSize:14, flex:1 }}/>
        </div>
      </div>

      {/* PRODUCT GRID — Sneakers AND clothing-for-customer use the 2-col
          tappable photo grid + size-picker sheet. CR (Clothing Refill) uses the
          1-col bulk list with inline qty steppers per size. */}
      {filtered.length === 0 ? (
        <div style={{ textAlign:"center", color:"#444", padding:"3rem 1rem", fontSize:14 }}>
          {wantsClothing
            ? "No clothing products yet. Add one from Admin."
            : "No products match your search."}
        </div>
      ) : isRefillMode ? (
        // Responsive: 1 column on a phone, 2 on iPad (see .mc-grid-refill above).
        <div className="mc-grid-refill" style={{ display:"grid", gap:10 }}>
          {filtered.map(p => (
            <ClothingCard key={p.id} product={p} onAdd={addClothingLines} onViewPhoto={setFullPhoto} />
          ))}
        </div>
      ) : (
        // Responsive: 2 columns on a phone, 5 on iPad (see .mc-grid-photo above).
        <div className="mc-grid-photo" style={{ display:"grid", gap:10 }}>
          {filtered.map(p => {
            const isSel = selected && selected.id === p.id;
            return (
              <div key={p.id} onClick={() => { resetSheet(); setSelected(p); }}
                   style={{ background: isSel ? "rgba(20,40,100,.25)" : "rgba(255,255,255,.03)",
                            border: isSel ? "2px solid #4A7FFF" : "1px solid rgba(255,255,255,.06)",
                            borderRadius:12, overflow:"hidden", cursor:"pointer", position:"relative",
                            boxShadow: isSel ? "0 0 16px rgba(60,110,255,.2)" : "none" }}>
                <div style={{ width:"100%", height:140, position:"relative", background: isSel ? "rgba(60,110,255,.05)" : "rgba(255,255,255,.05)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:52 }}>
                  {p.photoUrl
                    ? <img src={p.photoUrl} alt={p.name} style={{ width:"100%", height:"100%", objectFit:"cover" }}/>
                    : <span>{p.photo}</span>}
                  {/* View full photo(s) — opens the gallery viewer (primary + extra
                      angles) without triggering the card's add-to-cart tap. */}
                  {p.photoUrl && (
                    <button onClick={(e) => { e.stopPropagation(); setFullPhoto(productPhotos(p)); }}
                      title={p.gallery?.length ? `View ${productPhotos(p).length} photos` : "View full photo"}
                      style={{ position:"absolute", top:8, right:8, width:30, height:30, borderRadius:8, border:"none", cursor:"pointer",
                               background:"rgba(0,0,0,.55)", color:"#fff", display:"flex", alignItems:"center", justifyContent:"center", padding:0 }}>
                      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M15 3h6v6"/><path d="M9 21H3v-6"/><path d="M21 3l-7 7"/><path d="M3 21l7-7"/></svg>
                    </button>
                  )}
                  {p.gallery?.length > 0 && (
                    <span style={{ position:"absolute", bottom:8, left:8, display:"inline-flex", alignItems:"center", gap:4, background:"rgba(0,0,0,.6)", color:"#fff", fontSize:11, fontWeight:600, padding:"3px 8px", borderRadius:999 }}>
                      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>
                      {productPhotos(p).length}
                    </span>
                  )}
                </div>
                <div style={{ padding:"12px 13px 14px" }}>
                  <div style={{ fontSize:15, fontWeight:700, color:"#fff", marginBottom:4 }}>{p.name}</div>
                  {typeof p.retailPrice === "number" && p.retailPrice > 0 ? (
                    <div className="mc-price-siri" style={{ fontSize:16, fontWeight:800, marginBottom:4, width:"fit-content" }}>
                      R{p.retailPrice.toLocaleString("en-ZA", { minimumFractionDigits:0, maximumFractionDigits:2 })}
                    </div>
                  ) : (
                    <div style={{ fontSize:12, fontWeight:600, color:"rgba(255,255,255,.35)", marginBottom:4 }}>No price set</div>
                  )}
                  <div style={{ fontSize:13, fontWeight:500, color:"#4A7FFF" }}>Tap to add →</div>
                </div>
                <div style={{ position:"absolute", bottom:12, right:12, width:28, height:28,
                              background: isSel ? "rgba(60,110,255,.2)" : "rgba(60,110,255,.1)",
                              border: isSel ? "1px solid #4A7FFF" : "1px solid rgba(60,110,255,.3)",
                              borderRadius:8, display:"flex", alignItems:"center", justifyContent:"center", color:"#4A7FFF", fontSize:16, fontWeight:600 }}>+</div>
              </div>
            );
          })}
        </div>
      )}
      <div style={{ height:20 }}/>
      </div>

      {/* ── Size picker bottom sheet ── */}
      {selected && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.85)", display:"flex", alignItems:"flex-end", justifyContent:"center", zIndex:1000 }}>
          <div style={sheetStyle}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"1.5rem" }}>
              <div style={{ display:"flex", alignItems:"center", gap:"1rem" }}>
                {selected.photoUrl
                  ? <div style={{ position:"relative" }}>
                      <img src={selected.photoUrl} alt={selected.name} onClick={() => setFullPhoto(productPhotos(selected))}
                           title={selected.gallery?.length ? `View ${productPhotos(selected).length} photos` : "View full photo"}
                           style={{ width:"56px", height:"56px", objectFit:"cover", borderRadius:RADIUS, cursor:"zoom-in" }} />
                      {selected.gallery?.length > 0 && (
                        <span style={{ position:"absolute", bottom:-4, right:-4, background:"#4A7FFF", color:"#fff", fontSize:10, fontWeight:700, padding:"1px 6px", borderRadius:999, border:"2px solid #0b0e18" }}>{productPhotos(selected).length}</span>
                      )}
                    </div>
                  : <div style={{ fontSize:"2.8rem" }}>{selected.photo}</div>}
                <div>
                  <div style={{ fontWeight:"700", fontSize:"1.05rem" }}>{selected.name}</div>
                  <div style={{ color:"#555", fontSize:"0.8rem" }}>{selected.category}</div>
                </div>
              </div>
              <button onClick={resetSheet}
                style={{ ...bGray, borderRadius:"50%", width:"32px", height:"32px", padding:0, display:"flex", alignItems:"center", justifyContent:"center" }}>✕</button>
            </div>

            <div style={{ color:"#888", fontSize:"0.75rem", marginBottom:"0.5rem", textTransform:"uppercase", letterSpacing:"0.08em" }}>Select Size</div>
            {/* Inline availability note — shows ABOVE the size row when a
                greyed (zero-at-hub) size is tapped or an Add asks for more
                than the hub can still cover. Live: it recomputes remaining
                (hub qty minus cart) every render and hides the moment more
                stock is actually addable than when it was raised. */}
            {(selected.productType || "sneaker") === "clothing" && naNote && (() => {
              const have = hubQty(selected.id, naNote.size);
              const rem = have - clothingInCart(selected.id, naNote.size);
              if (rem > naNote.left) return null;
              const label = HUB_LABELS[servingHub] || servingHub;
              const text = have <= 0
                ? `Size ${formatSize(naNote.size)} isn't available at ${label} right now — it can't be ordered.`
                : rem <= 0
                  ? `Your cart already has all ${have} of size ${formatSize(naNote.size)} that ${label} holds.`
                  : `Only ${rem} more of size ${formatSize(naNote.size)} can be added — ${label} holds ${have}.`;
              return (
                <div style={{ background:"rgba(255,170,40,.1)", border:"1px solid rgba(255,170,40,.35)", color:"#FFC46B", borderRadius:10, padding:"9px 12px", fontSize:"0.82rem", fontWeight:600, marginBottom:"0.65rem" }}>
                  {text}
                </div>
              );
            })()}
            <div style={{ display:"flex", gap:"0.5rem", flexWrap:"wrap", marginBottom:"1.25rem" }}>
              {selectedSizes.map(s => {
                // Clothing sizes the serving hub has ZERO of are greyed out and
                // not selectable — tapping one raises the note above instead of
                // silently ordering into nothing. Sneakers are untouched (their
                // availability lives with the warehouse, not a single CR hub).
                const out = (selected.productType || "sneaker") === "clothing" && hubQty(selected.id, s) <= 0;
                return (
                  <button key={s} onClick={() => { if (out) { setNaNote({ size: s, left: 0 }); return; } setNaNote(null); setPendingSize(s); }}
                    style={out
                      ? { padding:"10px 18px", borderRadius:"10px", border:"2px dashed rgba(255,255,255,.14)", background:"transparent", color:"rgba(255,255,255,.28)", cursor:"not-allowed", fontWeight:"700", fontSize:"1rem" }
                      : { padding:"10px 18px", borderRadius:"10px", border:"2px solid", borderColor: pendingSize===s?BLUE:"rgba(60,110,255,.15)", background: pendingSize===s?"rgba(60,110,255,.15)":"transparent", color: pendingSize===s?BLUE_L:"#888", cursor:"pointer", fontWeight:"700", fontSize:"1rem" }}>
                    <SizeTag size={s} />
                  </button>
                );
              })}
            </div>

            {/* Quantity stepper — same-size, multiple-pair shortcut. Pushes
                N identical cart lines on Add to Cart (one box per pair). */}
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"1.25rem", padding:"4px 0" }}>
              <div style={{ color:"#ccc", fontSize:"0.95rem", fontWeight:600 }}>Quantity</div>
              <div style={{ display:"flex", alignItems:"center", gap:"0.5rem" }}>
                <button onClick={() => setPendingQty(q => Math.max(1, q - 1))} disabled={pendingQty <= 1}
                        style={{ width:36, height:36, borderRadius:10, border:"1px solid rgba(60,110,255,.25)", background:"rgba(60,110,255,.08)", color: pendingQty <= 1 ? "rgba(255,255,255,.25)" : "#4A7FFF", fontSize:18, fontWeight:700, cursor: pendingQty <= 1 ? "not-allowed" : "pointer", display:"flex", alignItems:"center", justifyContent:"center", lineHeight:1 }}>−</button>
                <div style={{ minWidth:34, textAlign:"center", color:"#fff", fontSize:"1.05rem", fontWeight:700, fontVariantNumeric:"tabular-nums" }}>{pendingQty}</div>
                <button onClick={() => setPendingQty(q => Math.min(10, q + 1))} disabled={pendingQty >= 10}
                        style={{ width:36, height:36, borderRadius:10, border:"1px solid rgba(60,110,255,.35)", background:"rgba(60,110,255,.12)", color: pendingQty >= 10 ? "rgba(255,255,255,.25)" : "#4A7FFF", fontSize:18, fontWeight:700, cursor: pendingQty >= 10 ? "not-allowed" : "pointer", display:"flex", alignItems:"center", justifyContent:"center", lineHeight:1 }}>+</button>
              </div>
            </div>

            {/* Display Partner request — sneakers only (it routes to Hub 1, which
                clothing can't use). Hidden for clothing customer orders. */}
            {(selected.productType || "sneaker") !== "clothing" && (
            <div style={{ marginBottom:"1.25rem" }}>
              <div style={{ color:"#555", fontSize:"0.72rem", marginBottom:"0.5rem", textTransform:"uppercase", letterSpacing:"0.08em" }}>Display Partner (optional)</div>
              <div style={{ display:"flex", gap:"0.5rem", flexWrap:"wrap" }}>
                <button onClick={() => setPendingDisplayPartner(v => !v)}
                  style={{ padding:"8px 16px", borderRadius:"10px", border:`2px solid ${pendingDisplayPartner?BLUE_L:"rgba(60,110,255,.15)"}`, background:pendingDisplayPartner?"rgba(60,110,255,.12)":"transparent", color:pendingDisplayPartner?BLUE_L:"#666", cursor:"pointer", fontWeight:"600", fontSize:"0.85rem" }}>
                  Request Display Partner
                </button>
              </div>
            </div>
            )}

            {(() => {
              const canAdd = !!(pendingSize || pendingDisplayPartner);
              const qtyOnly = pendingSize && !pendingDisplayPartner;
              // Display Partner adds exactly one cart line regardless of pendingQty
              // (addToCart forces reps=1 — one-off by nature). Drop the "N ×"
              // prefix so the CTA doesn't promise a quantity the cart will ignore.
              const btnLabel = pendingDisplayPartner
                ? (pendingSize
                    ? `Add Size ${formatSize(pendingSize)} + Display Partner to Cart`
                    : "Add Display Partner Request to Cart")
                : pendingSize
                  ? (qtyOnly && pendingQty > 1
                      ? `Add ${pendingQty} × Size ${formatSize(pendingSize)} to Cart`
                      : `Add Size ${formatSize(pendingSize)} to Cart`)
                  : ((selected.productType || "sneaker") === "clothing" ? "Select a size" : "Select a size or display option");
              return (
                <button onClick={addToCart} disabled={!canAdd}
                  style={{ width:"100%", ...bBlue, borderRadius:"10px", padding:"0.9rem", fontSize:"1rem", marginBottom:"0.65rem", opacity:canAdd?1:0.4, cursor:canAdd?"pointer":"not-allowed" }}>
                  {btnLabel}
                </button>
              );
            })()}

            {cart.length > 0 && (
              <button onClick={() => { resetSheet(); (hasCustomerInCart ? openCheckout() : placeRefillRequests()); }}
                style={{ width:"100%", ...bGhost, borderRadius:"10px", padding:"0.75rem", fontSize:"0.95rem" }}>
                {hasCustomerInCart
                  ? `Checkout (${customerCount} item${customerCount > 1 ? "s" : ""}) →`
                  : `Place Refill Request (${refillCount} item${refillCount > 1 ? "s" : ""}) →`}
              </button>
            )}
          </div>
        </div>
      )}

      {/* ── Checkout bottom sheet ── */}
      {checkoutOpen && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.85)", display:"flex", alignItems:"flex-end", justifyContent:"center", zIndex:1000 }}>
          <div style={sheetStyle}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"1.25rem" }}>
              <span style={{ fontWeight:"800", fontSize:"1.2rem" }}>Checkout</span>
              <button onClick={closeCheckout} style={{ ...bGray, borderRadius:"50%", width:"32px", height:"32px", padding:0, display:"flex", alignItems:"center", justifyContent:"center" }}>✕</button>
            </div>

            {/* Cart review */}
            <div style={{ background:"rgba(60,110,255,.04)", borderRadius:"12px", padding:"0.85rem 1rem", marginBottom:"1.25rem", border:BORDER }}>
              <div style={{ color:"#555", fontSize:"0.72rem", marginBottom:"0.5rem", textTransform:"uppercase", letterSpacing:"0.08em" }}>Order Summary</div>
              {/* Only the lines this Checkout will place (sneakers + clothing
                  customer). Clothing refill lines stay in the cart for the
                  Place Refill Request bar, so they're not listed here. Remove
                  by index against the full cart to delete the right line. */}
              {cart.map((item, idx) => ({ item, idx })).filter(({ item }) => isCustomerLine(item)).map(({ item, idx }, i, arr) => (
                <div key={idx} style={{ display:"flex", alignItems:"center", gap:"0.75rem", padding:"0.45rem 0", borderBottom: i < arr.length-1 ? "1px solid rgba(60,110,255,.06)" : "none" }}>
                  {item.product.photoUrl
                    ? <img src={item.product.photoUrl} alt="" style={{ width:34, height:34, objectFit:"cover", borderRadius:6, flexShrink:0 }} />
                    : <span style={{ fontSize:"1.3rem", flexShrink:0 }}>{item.product.photo}</span>}
                  <span style={{ flex:1, color:"#ccc", fontSize:"0.87rem" }}>{item.product.name}</span>
                  <span style={{ color:BLUE_L, fontWeight:"700", fontSize:"0.87rem", flexShrink:0 }}>{item.size ? `Sz ${item.size}` : "Display"}{item.qty > 1 ? ` × ${item.qty}` : ""}</span>
                  <button onClick={() => removeFromCart(idx)} style={{ background:"transparent", border:"none", color:"#444", cursor:"pointer", fontSize:"0.9rem", flexShrink:0 }}>✕</button>
                </div>
              ))}
            </div>

            <div style={{ marginBottom:"1rem", position:"relative" }}>
              <div style={{ color:"#888", fontSize:"0.78rem", marginBottom:"0.4rem" }}>Customer Name *</div>
              <input placeholder="e.g. Ahmed" value={customerName}
                     onChange={e => { setCustomerName(e.target.value); setNameDropdownOpen(true); }}
                     onFocus={() => setNameDropdownOpen(true)}
                     onBlur={() => setTimeout(() => setNameDropdownOpen(false), 150)}
                     style={inputStyle} />
              {nameDropdownOpen && (
                <CustomerSuggestionDropdown
                  query={customerName} mode="name" customers={customerIndex}
                  onPick={pickCustomer}
                  onAddNew={() => setNameDropdownOpen(false)}
                />
              )}
            </div>
            <div style={{ marginBottom:"1rem", position:"relative" }}>
              <div style={{ color:"#888", fontSize:"0.78rem", marginBottom:"0.4rem" }}>Phone *</div>
              {/* Required for customer orders. Input is restricted to digits and
                  capped at 10 so a short/overlong number can't be entered; it
                  must be the standard 10-digit SA mobile starting with 0. */}
              <input placeholder="0712345678" inputMode="numeric" maxLength={10} value={customerPhone}
                     onChange={e => { setCustomerPhone(e.target.value.replace(/\D/g, "").slice(0, 10)); setPhoneDropdownOpen(true); }}
                     onFocus={() => setPhoneDropdownOpen(true)}
                     onBlur={() => setTimeout(() => setPhoneDropdownOpen(false), 150)}
                     style={inputStyle} />
              {phoneDropdownOpen && (
                <CustomerSuggestionDropdown
                  query={customerPhone} mode="phone" customers={customerIndex}
                  onPick={pickCustomer}
                  onAddNew={() => setPhoneDropdownOpen(false)}
                />
              )}
              {customerPhone && !isValidLocalSAPhone(customerPhone) && (
                <div style={{ color:"#FF6B6B", fontSize:"0.72rem", marginTop:"0.35rem" }}>
                  Enter a 10-digit number starting with 0 (e.g. 0712345678).
                </div>
              )}
            </div>
            <label style={{ display:"flex", alignItems:"center", gap:"0.6rem", marginBottom:"1.5rem", cursor:"pointer", padding:"0.75rem", background:"rgba(60,110,255,.04)", borderRadius:"10px", border:BORDER }}>
              <input type="checkbox" checked={marketingOptIn} onChange={e => setMarketingOptIn(e.target.checked)}
                style={{ width:18, height:18, accentColor:BLUE, cursor:"pointer" }} />
              <span style={{ color:"#ccc", fontSize:"0.88rem" }}>Customer wants to receive Marathon Club deals?</span>
            </label>

            {(() => {
              // Button label reflects the qty shortcut: if every cart line
              // is the same product + size (the "3 pairs of size 8" case),
              // show "Place order — size 8 × 3". Mixed carts fall back to
              // the count.
              // Count only the lines this Checkout places (sneakers + clothing
              // customer); clothing refill lines are placed separately.
              const customerLines = cart.filter(isCustomerLine);
              const sample = customerLines[0];
              const singleSku = sample && customerLines.every(it =>
                it.product?.id === sample.product?.id &&
                it.size === sample.size &&
                !it.requestDisplay && !it.requestDisplayPartner
              );
              const n = customerLines.length;
              const phoneOk = isValidLocalSAPhone(customerPhone);
              const canPlace = customerName && phoneOk && customerLines.length && !submitting;
              // Multi-shop users see the destination shop on the button itself —
              // a persistent, un-missable reminder of where this order ships.
              const shopTag = singleShop ? "" : ` · ${labelFor(effectiveShop, shopRegistry)}`;
              const placeLabel = !customerName
                ? "Enter customer name"
                : !phoneOk
                  ? "Enter a valid phone number"
                  : singleSku && sample.size
                    ? (n > 1 ? `Place order${shopTag} — size ${formatSize(sample.size)} × ${n}` : `Place order${shopTag} — size ${formatSize(sample.size)}`)
                    : `Place ${n} Order${n > 1 ? "s" : ""}${shopTag} →`;
              return (
                <button onClick={() => placeOrders()} disabled={!canPlace}
                  style={{ ...bBlue, borderRadius:"10px", padding:"0.9rem 2rem", fontSize:"1rem", width:"100%", opacity:canPlace?1:0.4, cursor:canPlace?"pointer":"not-allowed" }}>
                  {submitting ? "Placing orders…" : placeLabel}
                </button>
              );
            })()}
          </div>
        </div>
      )}

      {/* ── Refill tracking page ── full-screen, opened from the CR tab button.
          Rendered below the lightbox so photo taps inside it still enlarge. */}
      {trackingOpen && (
        <RefillTrackingPage orders={orders} shop={effectiveShop} registry={shopRegistry}
                            products={products} onViewPhoto={setFullPhoto} onClose={() => setTrackingOpen(false)} />
      )}

      {/* ── Full-photo lightbox ── tap a product photo to see the complete,
          uncropped image; tap anywhere (or ✕) to dismiss. */}
      {fullPhoto && <GalleryLightbox photos={fullPhoto} onClose={() => setFullPhoto(null)} />}

      {/* ── Phase 12B: Floating cart trigger ── (desktop has its own drawer) */}
      {cart.length > 0 && !checkoutOpen && !selected && !isDesktop && (
        <div style={{ position:"fixed", bottom:0, left:0, right:0, padding:"12px 14px 14px", background:"linear-gradient(transparent, rgba(0,0,0,.92) 30%)", zIndex:50, pointerEvents:"none" }}>
          <div style={{ maxWidth:880, margin:"0 auto", pointerEvents:"auto" }}>
            <button
              onClick={hasCustomerInCart ? openCheckout : () => placeRefillRequests()}
              disabled={submitting}
              style={{ width:"100%", padding:"13px 16px", borderRadius:12, border:"1px solid rgba(60,110,255,.55)",
                       background:"#4A7FFF", color:"#fff",
                       fontSize:14, fontWeight:700, cursor:"pointer",
                       display:"flex", alignItems:"center", justifyContent:"center", gap:8,
                       boxShadow:"0 4px 20px rgba(60,110,255,.45)",
                       opacity: submitting ? 0.7 : 1 }}>
              <span>
                {submitting
                  ? (hasCustomerInCart ? "Placing orders…" : "Placing refill…")
                  : (hasCustomerInCart
                      ? `Checkout (${customerCount})`
                      : `Place Refill Request (${refillCount})${singleShop ? "" : ` · ${labelFor(effectiveShop, shopRegistry)}`}`)
                }
              </span>
              <span style={{ fontSize:16 }}>→</span>
            </button>
          </div>
        </div>
      )}

      {/* ── Scroll-to-top FAB ── appears after scrolling down; one tap returns
          to the search box. Sits above the floating cart bar when it's shown. */}
      {showScrollTop && !isDesktop && (
        <button onClick={scrollToTop} aria-label="Scroll to top"
          style={{ position:"fixed", right:16, bottom: cart.length > 0 && !checkoutOpen && !selected ? 92 : 24, zIndex:60,
                   width:46, height:46, borderRadius:"50%", cursor:"pointer",
                   background:"#4A7FFF", border:"1px solid rgba(60,110,255,.55)", color:"#fff",
                   boxShadow:"0 4px 16px rgba(0,0,0,.45)", display:"flex", alignItems:"center", justifyContent:"center" }}>
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="19" x2="12" y2="5"/><polyline points="5 12 12 5 19 12"/></svg>
        </button>
      )}
    </div>
  );
}

// Per-queue nav glyphs for the desktop workspace rail (mirrors the mobile tab
// strip icons). Keyed by the same tab keys used in tabDefs.
const WH_TAB_ICON = {
  queue:    <><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></>,
  clothing: <path d="M16 4l-4 4-4-4M3 7l5-3h8l5 3M3 7v13a1 1 0 001 1h16a1 1 0 001-1V7M3 7l4 4M21 7l-4 4"/>,
  refills:  <><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></>,
  layby:    <path d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-14L4 7m8 4v10m0-10L4 7v10l8 4"/>,
};

// ─── WAREHOUSE VIEW ───────────────────────────────────────────────────────────
function WarehouseView({ products = [], orders, onExit }) {
  const [mainTab, setMainTab] = usePersistedTab("warehouse", "queue");
  const [filter, setFilter] = useState("incoming");
  const [onHoldExpanded, setOnHoldExpanded] = useState(false);
  const [selectedHub, setSelectedHub] = useState(() => localStorage.getItem("warehouseHub") || null);
  // Phase 12C/14B: clamp mainTab when the user switches hubs and the previously
  // selected tab no longer exists for the new hub (CR Orders on the CR hubs,
  // hub2+hub3). Fall back to Order Queue. NOTE: must come AFTER selectedHub's
  // declaration — placing this useEffect before it triggers a TDZ
  // ReferenceError on the dependency array evaluation at render time.
  useEffect(() => {
    // The Restock Status tab was removed from the warehouse — Source owns
    // restock now. Clamp any persisted "restock" selection back to the queue.
    if (mainTab === "restock") setMainTab("queue");
    // CR Orders exists on every CR hub (hub2 + hub3, from CR_HUBS); clamp the rest.
    if (!CR_HUBS.includes(selectedHub) && mainTab === "clothing") setMainTab("queue");
    // Trial: hubC has only the Order Queue tab — clamp anything else back.
    if (selectedHub === "hubC" && mainTab !== "queue") setMainTab("queue");
    // Phase 15: the Depleted tab was removed from the warehouse (moved to the
    // home-page tile). Clamp any persisted "depleted" selection back to the
    // queue so returning users don't land on a now-nonexistent blank tab.
    if (mainTab === "depleted") setMainTab("queue");
  }, [selectedHub, mainTab]);
  // Phase 14B: hub3 filters by placedAtHub (the source of truth for the Pine
  // universe); hub1/hub2 still use the legacy order.hub field for back-compat.
  // Trial: hubC (customer clothing) also filters by placedAtHub.
  const orderInHub = (o, h) => (h === "hub3" || h === "hubC")
    ? o.placedAtHub === h
    : (o.hub || "hub1") === h;

  const selectHub = (hub) => {
    localStorage.setItem("warehouseHub", hub);
    setSelectedHub(hub);
  };

  // ── Hooks hoisted before the conditional return ────────────────────────
  // Every useState/useMemo/useEffect must run in the same order on every
  // render. With these declared after the (!selectedHub) early return,
  // toggling between the landing screen and a hub-active view misaligns
  // React's internal hook indices — post-return state (refills, clothing
  // batches, 30s ticker, pickerOpenId) leaked between hubs and a hard
  // refresh was the only way to realign them. dueRefills short-circuits
  // when selectedHub is null so the landing-screen pass is harmless.
  const [pickerOpenId, setPickerOpenId] = useState(null);
  // Which Ready-tab row's ⋮ action menu is open (one at a time). A dispatched
  // order lives in the Ready tab — there is no separate "Sent" tab.
  const [menuOpenId, setMenuOpenId] = useState(null);
  // Dispatch-label print toast (non-blocking — Send never waits on the printer).
  const [printToast, setPrintToast] = useState(null);
  const [nowTick, setNowTick] = useState(() => serverNowMs());
  useEffect(() => {
    const id = setInterval(() => setNowTick(serverNowMs()), 30 * 1000);
    return () => clearInterval(id);
  }, []);
  // ── Layby (warehouse side) ───────────────────────────────────────────────
  // Live subscriptions to the shared /laybys + /laybyPulls nodes. Hoisted above
  // the hub-selector early return like every other hook here (Rules of Hooks).
  // Read-only until a hub is picked; LaybyTab/banner filter by selectedHub.
  const laybys = useLaybys();
  const laybyPulls = useLaybyPulls();
  // Which layby sub-queue to open on next mount. The exceptions banner flips this
  // to "exceptions" so a tap jumps straight there; keyed remount applies it.
  const [laybySub, setLaybySub] = useState("receiving");
  const DISPLAY_REFILL_DELAY_MS = 15 * 60 * 1000;
  const RESOLVED_VISIBLE_MS     = 24 * 60 * 60 * 1000;
  const { dueRefills, completedRefills } = useMemo(() => {
    if (!selectedHub) return { dueRefills: [], completedRefills: [] };
    const due = [];
    const completed = [];
    const resolvedAtMs = (o) => {
      const iso = o.displayRefilledAt || o.displayRefillStockDepletedAt;
      return iso ? new Date(iso).getTime() : 0;
    };
    (orders || []).forEach(o => {
      if (!o.requestDisplayPartner) return;
      if (!o.displayRefillScheduledAt) return;
      if (o.displayRefillHub !== selectedHub) return;
      if (o.displayRefillStatus) {
        const rAt = resolvedAtMs(o);
        if (rAt && nowTick - rAt < RESOLVED_VISIBLE_MS) completed.push(o);
      } else {
        const scheduledAt = new Date(o.displayRefillScheduledAt).getTime();
        if (nowTick - scheduledAt >= DISPLAY_REFILL_DELAY_MS) due.push(o);
      }
    });
    due.sort((a, b) =>
      new Date(a.displayRefillScheduledAt).getTime() -
      new Date(b.displayRefillScheduledAt).getTime()
    );
    completed.sort((a, b) => resolvedAtMs(b) - resolvedAtMs(a));
    return { dueRefills: due, completedRefills: completed };
  }, [orders, selectedHub, nowTick]);
  const [showRefilledCompleted, setShowRefilledCompleted] = useState(false);
  const CANONICAL_SIZE_ORDER = ["3","4","5","5.5","6","7","8","9","10","11","S","M","L","XL","XXL","XXXL","4XL","28","30","32","34","36","38","40"];
  const sizeRank = (s) => {
    const i = CANONICAL_SIZE_ORDER.indexOf(s);
    return i === -1 ? 999 : i;
  };
  const { clothingActiveBatches, clothingCompletedBatches } = useMemo(() => {
    const byKey = new Map();
    (orders || []).forEach(o => {
      // CR Orders = "Shop Refill" requests ONLY. Customer clothing orders now
      // also land on this hub (they route via CR_HUB_BY_UNIVERSE since
      // 2026-07-16) but belong to the main Order Queue, whose Send fires the
      // dispatch transfer — accepting them here too would let staff move the
      // same stock twice (CR fulfil + queue dispatch). Mirrors the main
      // queue's inverse filter (customerName !== "Shop Refill").
      if (o.productType !== "clothing" || o.customerName !== "Shop Refill") return;
      // Each CR hub sees ONLY its own requests: PE/Trophy CRs land on hub2,
      // Pine CRs on hub3 (placedAtHub, written by placeRefillRequests via
      // CR_HUB_BY_UNIVERSE; o.hub fallback covers legacy hub2-era orders).
      if ((o.placedAtHub || o.hub || "hub2") !== selectedHub) return;
      // destShop in the key: PE and Trophy requests must NEVER share a card —
      // warehouse staff always know exactly which store a batch is for (and the
      // engine stamps one createdAt per store per scan, so its lines group into
      // one card per product per store).
      const key = `${o.productId}__${o.destShop || ""}__${o.createdAt}`;
      if (!byKey.has(key)) {
        byKey.set(key, {
          batchKey: key,
          productId: o.productId,
          productName: o.productName,
          productPhoto: o.productPhoto,
          productPhotoUrl: o.productPhotoUrl,
          createdAt: o.createdAt,
          items: [],
        });
      }
      const b = byKey.get(key);
      // destShop drives the hub→shop transfer on fulfil; all lines of one request
      // share it, so stamp the batch from the first line that carries it.
      if (!b.destShop && o.destShop) b.destShop = o.destShop;
      // Engine-created requests get an AUTO chip so staff know no human placed it.
      if (o.autoRefill) b.autoRefill = true;
      // Shadow-mode previews are READ-ONLY: they show exactly how Live Mode will
      // look but can't be fulfilled (fulfillCRBatch also refuses them).
      if (o.autoShadow) b.shadow = true;
      b.items.push({
        orderId: o.id,
        size: o.size,
        qty: o.qty || 1,
        status: o.clothingRefillStatus || null,
        refilledQty: o.clothingRefilledQty ?? null,   // units actually sent (partial-aware)
        refilledCountedQty: o.clothingRefilledCountedQty ?? null,     // portion that was a real hub transfer
        refilledUncountedQty: o.clothingRefilledUncountedQty ?? null, // portion added to shop from nothing
        refilledAt: o.clothingRefilledAt || null,
        outOfStockAt: o.clothingOutOfStockAt || null,
        placedAtHub: o.placedAtHub || o.hub || "hub2",
        gen: o.clothingRefillGen || 0,                // fulfil generation — keys idempotent movementIds
        uncounted: !!o.clothingUncounted,             // fulfilled via the uncounted override (no source deduction)
        // Locked split for a partially-attempted line: reused verbatim on retry so the
        // counted/uncounted split can't be re-derived from a hub cell that changed between
        // taps (guards the concurrency double-count). planGen ties the lock to this gen.
        planGen: o.clothingPlanGen ?? null,
        planCountedQty: o.clothingPlanCountedQty ?? null,
        planUncountedQty: o.clothingPlanUncountedQty ?? null,
      });
    });
    const active = [];
    const completed = [];
    byKey.forEach(batch => {
      batch.items.sort((a, b) => sizeRank(a.size) - sizeRank(b.size));
      // Per-size fulfil (Approach B): a batch can now resolve to a MIX — some
      // sizes fulfilled (available), some declined (rejected/outOfStock). It's
      // "resolved" once every line has a status; batch.status rolls up to
      // available | partial | rejected for the completed card.
      const isDeclined = (s) => s === "rejected" || s === "outOfStock";
      const allResolved = batch.items.length > 0 && batch.items.every(it => it.status);
      if (allResolved) {
        const availCount = batch.items.filter(it => it.status === "available").length;
        const declCount  = batch.items.filter(it => isDeclined(it.status)).length;
        batch.status = availCount === 0 ? "rejected" : declCount === 0 ? "available" : "partial";
        // Pick the most recent resolution timestamp as the batch's resolvedAt.
        const stamps = batch.items.map(it => it.refilledAt || it.outOfStockAt).filter(Boolean);
        batch.resolvedAt = stamps.sort().pop() || batch.createdAt;
        const resolvedMs = new Date(batch.resolvedAt).getTime();
        if (nowTick - resolvedMs < RESOLVED_VISIBLE_MS) completed.push(batch);
      } else {
        batch.status = null;
        active.push(batch);
      }
    });
    // Active: newest first (within DayCollapsible's bucket logic).
    active.sort((a, b) => tsMs(b.createdAt) - tsMs(a.createdAt));
    completed.sort((a, b) => tsMs(b.resolvedAt) - tsMs(a.resolvedAt));
    return { clothingActiveBatches: active, clothingCompletedBatches: completed };
  }, [orders, nowTick, selectedHub]);
  // CR fulfil (Approach B): firing a real hub2→store transfer needs a stock-capable
  // role (applyMovement is rule-gated on stockRole), plus live Hub 2 on-hand to cap
  // per-size fulfil qty, plus a photo lightbox for the cards.
  const { permRecord: whStockPerm, isSuperAdmin: whStockSuper } = usePermissions();
  const crActorRole = whStockSuper ? "admin" : (whStockPerm?.stockRole || null);
  const canFulfilCR = crActorRole === "admin" || crActorRole === "warehouse";
  // Subscribe to THIS hub's stock only when it's a CR hub (hub2/hub3) — the CR
  // tab fulfils from the selected hub's own cells. "__off__" resolves to an
  // empty node elsewhere, so hub1/hubC devices don't stream a stock subtree.
  const crHubCells = useStockCells(CR_HUBS.includes(selectedHub) ? selectedHub : "__off__"); // { pid: { size: cell } }
  const [crPhoto, setCrPhoto] = useState(null);
  // Desktop workspace gate (≥1024px). Mobile keeps the existing single-column
  // layout below; wide screens get a left rail of queues + a titled main pane.
  const isWide = !useIsNarrow(1024);

  // Hub selector screen — shown until staff pick a hub
  if (!selectedHub) {
    return (
      <div style={{ minHeight:"100vh", background:BG, color:"#fff", fontFamily:FONT, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:"2rem" }}>
        <div style={{ fontWeight:"800", fontSize:"1.5rem", letterSpacing:"0.06em", marginBottom:"0.5rem", color:"#fff" }}>WAREHOUSE</div>
        <p style={{ color:"#555", marginBottom:"2.5rem", fontSize:"0.9rem" }}>Select your hub to continue</p>
        <div style={{ display:"flex", gap:"1rem", width:"100%", maxWidth:"520px" }}>
          {[["hub1","Hub 1"],["hub2","Hub 2"],["hub3","Hub 3"],["hubC","Hub C"]].map(([val, label]) => (
            <button key={val} onClick={() => selectHub(val)}
              style={{ flex:1, background:CARD, border:BORDER, borderRadius:RADIUS, padding:"2.2rem 0.75rem", cursor:"pointer", color:"#fff", textAlign:"center", boxShadow:GLOW, transition:"border-color 0.15s" }}
              onMouseEnter={e => { e.currentTarget.style.borderColor=`rgba(60,110,255,.5)`; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor=`rgba(60,110,255,.12)`; }}>
              <div style={{ fontWeight:"800", fontSize:"2rem", color:BLUE, marginBottom:"0.3rem" }}>{label}</div>
              <div style={{ color:"#555", fontSize:"0.85rem" }}>Tap to select</div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // Filter orders to only this hub. hub1/hub2: legacy order.hub field.
  // hub3 (Phase 14B): placedAtHub field — orders flow in here based on which
  // Store Assistant universe they were placed in.
  //
  // Layby pull requests surface in the SAME main queue (no separate Layby box):
  // a pending pull → Incoming, a sent pull → Ready, so they flow through the same
  // status pills + day grouping as orders. Each carries _pull + isLayby so the
  // queue renders the real PullCard (L-xxxxx invoice + Sent/Reject/Return) — layby
  // behaviour is unchanged, they're just seen with everything else. Matches the
  // TV board's existing orders+laybys merge.
  const hubLaybyOrders = (laybyPulls || [])
    .filter(p => p && p.invoiceNo && (p.storageHub || DEFAULT_STORAGE_HUB) === selectedHub)
    .map(p => {
      const st = p.status || PULL_STATUS.PENDING;
      // PENDING = unactioned work: bucket it as current-day so the queue's 3-day
      // window can NEVER hide it (the whole point — never miss a layby). The card
      // still shows the true requested-age via the pull's requestedAt.
      if (st === PULL_STATUS.PENDING) return { id: p.invoiceNo, status: STATUS.INCOMING, isLayby: true, _pull: p, createdAt: serverNowIso() };
      if (st === PULL_STATUS.SENT)    return { id: p.invoiceNo, status: STATUS.READY,    isLayby: true, _pull: p, readyAt: p.sentAt, updatedAt: p.sentAt, createdAt: p.sentAt || p.requestedAt || "" };
      return null; // rejected / returnedToStock → resolved, not shown in the queue
    })
    .filter(Boolean);
  // CR / clothing-refill requests (customerName "Shop Refill") live in the SAME
  // /orders node but belong only in the CR Orders tab — exclude them from the main
  // queue feeder so both the visible list AND every pill count/badge drop them in
  // one place. Regular orders always carry a validated non-empty customerName, and
  // layby pull rows have no customerName, so this can't hide a real order.
  const hubOrders = [...orders.filter(o => orderInHub(o, selectedHub) && o.customerName !== "Shop Refill"), ...hubLaybyOrders];

  // extraPatch is merged into the Firebase update — used to stamp sentSize when
  // the warehouse picks a substitute size. Insights/restock logs continue to
  // log order.size (the customer-requested value); only Source view surfaces
  // sentSize, by design.
  const updateStatus = async (order, status, extraPatch = {}) => {
    const now = serverNowIso();
    // When an item is COLLECTED (sold/given to customer), log a refill request so
    // Source knows what needs restocking. OOS items are NOT logged — they're
    // completely unavailable and can't be refilled.
    if (status === STATUS.COLLECTED) {
      await logRestock({
        timestamp: now,
        date: getSADateString(),
        productName: order.productName,
        photoUrl: order.productPhotoUrl || null,
        photo: order.productPhoto || "",
        size: order.size,
        orderNumber: order.id,
        hub: order.hub || selectedHub,
        placedAtHub: order.placedAtHub || order.hub || selectedHub,
      }).catch(err => console.warn("logRestock failed:", err));
    }
    const patch = { status, updatedAt: now, ...extraPatch };
    if (status === STATUS.READY)           patch.readyAt = now;
    if (status === STATUS.OUT_OF_STOCK)    patch.outOfStockAt = now;
    // Hub 2 dispatch hold: a Hub 2 order going READY holds its customer-facing
    // reveal (TV + voice + WhatsApp) until notifyReadyAt = now + HUB2_DISPATCH_HOLD_MS.
    // readyNotifyPending flags it for the server reveal sweep (which sends the
    // WhatsApp when due). The flag is written on EVERY transition — true only for a
    // Hub 2 Ready, false otherwise — so a revert / OOS / collected clears it and a
    // held send can never fire late. Non-hub2 Ready keeps the instant path below.
    const isHeldReady = status === STATUS.READY && HELD_DISPATCH_HUBS.has(order.placedAtHub || order.hub || "hub1");
    patch.readyNotifyPending = isHeldReady;
    // Write the reveal instant for a held Ready; clear any stale one otherwise so a
    // later non-held transition can never be wrongly held by a leftover notifyReadyAt.
    patch.notifyReadyAt = isHeldReady ? new Date(serverNowMs() + HUB2_DISPATCH_HOLD_MS).toISOString() : null;
    if (status === STATUS.COMING_TOMORROW) patch.comingTomorrowAt = now;
    if (status === STATUS.COLLECTED)       patch.collectedAt = now;

    // ── Display Partner refill scheduling (Phase 9) ────────────────────────
    // When a Display Partner order is marked READY, schedule a refill task on
    // the hub where it was placed (display requests now route to the product's
    // own hub, so placedAtHub == the product's stocking hub). Resets refilled
    // state so a re-sent order starts a fresh 15-min window. When the order
    // leaves READY for anything other than COLLECTED, cancel the scheduled refill.
    if (order.requestDisplayPartner) {
      if (status === STATUS.READY) {
        const product = products.find(p => p.id === order.productId);
        patch.displayRefillScheduledAt     = now;
        // Phase 14B: refill task routes by where the order was placed —
        // Pine-placed orders go to Hub 3's refill section. Falls back to the
        // product's stocking hub for legacy orders without placedAtHub.
        patch.displayRefillHub             = order.placedAtHub || getProductHubs(product)[0] || "hub1";
        patch.displayRefillStatus          = null;
        patch.displayRefilledAt            = null;
        patch.displayRefillStockDepletedAt = null;
        patch.displayRefilledBy            = null;
      } else if (status !== STATUS.COLLECTED) {
        patch.displayRefillScheduledAt = null;
        patch.displayRefillHub         = null;
      }
    }

    updateOrder(order.id, patch);
    const insightAction = { [STATUS.READY]:"ready", [STATUS.OUT_OF_STOCK]:"out_of_stock", [STATUS.COMING_TOMORROW]:"tomorrow", [STATUS.COLLECTED]:"collected" }[status];
    if (insightAction) logInsight({
      timestamp: now,
      // productId joins analytics on the durable key; see the note at the
      // checkout logInsight site. Older events fall back to productName.
      // ?? null keeps the key present for legacy orders lacking productId —
      // RTDB drops undefined fields, which would break the "always present"
      // contract and force consumers to guess.
      productId: order.productId ?? null,
      productName: order.productName,
      productCategory: order.productCategory || "",
      productType: order.productType || "sneaker",
      size: order.size,
      customerName: order.customerName,
      customerPhone: order.customerPhone,
      orderNumber: order.id,
      action: insightAction,
      placedAtHub: order.placedAtHub || order.hub || "hub1",
      destShop: order.destShop ?? null,
    });
    // ── WhatsApp notifications ───────────────────────────────────────────────
    // order_ready template: pass customer_name and order_number ONLY.
    // No timer/minutes — the customer should not feel time pressure.
    // Template body suggested: "Hi {{1}}, your order #{{2}} is ready to collect
    // at Marathon Club. See you soon!"
    // A held-hub Ready is deferred — the server reveal sweep sends order_ready at
    // notifyReadyAt. Every other Ready notifies immediately, as before.
    if (status === STATUS.READY && !isHeldReady)
      sendWhatsAppTemplate(order.customerPhone, "order_ready", [order.customerName || "there", order.id]);
    if (status === STATUS.OUT_OF_STOCK)
      sendWhatsAppTemplate(order.customerPhone, "rder_out_of_stock", [order.id]);
    if (status === STATUS.COMING_TOMORROW)
      sendWhatsAppTemplate(order.customerPhone, "order_tomorrow", [order.id]);
  };

  // Mark an order Sent AND auto-print its dispatch label — but ONLY when the hub→shop
  // transfer actually moves stock. The label is the physical signal that the transfer
  // succeeded (the item is counted & in-system): if no stock moved (uncounted hub /
  // insufficient stock / not recordable) there is NO label, so the picker knows to
  // route the item through Lightspeed instead. The order is still marked Sent either
  // way — only the label is gated.
  // GESTURE NOTE: connectTransport (inside printDispatchLabel) only needs the click's
  // user-gesture for the FIRST device pairing; reconnects need none. We await the
  // (sub-second) transfer before printing, so the first pairing's chooser still opens
  // well within the browser's ~5s transient-activation window.
  // extraPatch.sentSize carries a warehouse size substitution → the label barcodes
  // the size physically shipping.
  // A3 (stock-integrity) — transfer FIRST, then flip the status, so a skipped
  // ledger move can never hide behind an already-Sent order. The order is
  // marked Sent either way (the parcel physically leaves regardless), but a
  // failed/unrecordable transfer is STAMPED on the order (transferFailed:
  // reason) — an auditable flag a sweep can query, not a toast that fades.
  // Returns the transfer result so callers can gate their own follow-ups.
  const markSentWithTransfer = async (order, extraPatch = {}) => {
    const sentSize = extraPatch.sentSize ?? order.sentSize ?? order.size ?? null;
    const transfer = await recordDispatchTransfer(order, sentSize);
    // Clothing negative guard: a clothing order whose size the hub no longer
    // has does NOT get marked Sent — the order stays pending and the toast
    // tells the picker to mark it Out of Stock instead. (The assistant-side
    // grey-out means a zero at send time is "reality changed" — that deserves
    // a stop, not a silent negative. Sneakers keep the A1 always-move
    // behavior below: their parcels physically leave regardless.)
    if (transfer.blockSend) return transfer;
    // `skipped` is a DELIBERATE no-move (footwear now sells from the hub), not a
    // failure — it must not stamp transferFailed, which drives the "route via
    // Lightspeed" warnings and the reconciliation reports.
    updateStatus(order, STATUS.READY, {
      ...extraPatch,
      ...(transfer.moved || transfer.skipped
        ? { transferFailed: null }
        : { transferFailed: transfer.reason || "unknown" }),
    });
    return transfer;
  };

  const markSentAndPrint = async (order, extraPatch = {}) => {
    const sentSize = extraPatch.sentSize ?? order.sentSize ?? order.size ?? null;
    const transfer = await markSentWithTransfer(order, extraPatch);
    // A skipped footwear transfer still gets its label — the parcel physically
    // travels to the shop exactly as before; only the ledger move is gone.
    if (!transfer.moved && !transfer.skipped) return;  // recordDispatchTransfer already raised the explaining toast
    printDispatchLabel({ ...order, sentSize })
      .then((res) => {
        const diag = res?.diag ? ` [${res.diag}]` : "";
        if (res?.ok) setPrintToast({ kind: "ok", text: `Dispatch label printed for #${order.id}.${diag}` });
        else setPrintToast({ kind: "err", text: `Label didn't print (${res?.error || "unknown"}). Order sent — retry print.${diag}` });
        setTimeout(() => setPrintToast(null), 7000);
      })
      .catch(() => {
        setPrintToast({ kind: "err", text: "Label didn't print. Order sent — retry print." });
        setTimeout(() => setPrintToast(null), 4200);
      });
  };

  // Reprint a dispatched order's label on demand — these sit in the Ready tab — for when
  // the original auto-print (the Mark-as-Sent gate, #109) was lost to a printer trip.
  // PRINT-ONLY: it reuses the exact same printDispatchLabel path/transport/layout,
  // barcoding the SENT size from the order's saved data, but deliberately does NOT call
  // recordDispatchTransfer — the stock already moved on the original send, so a reprint
  // must never write the ledger or double-deduct. Fired straight from the ⋮ menu click
  // (no await before connect) so the BLE chooser keeps its user-gesture, like the original.
  const reprintDispatchLabel = (order) => {
    setMenuOpenId(null);
    const sentSize = order.sentSize ?? order.size ?? null;
    printDispatchLabel({ ...order, sentSize })
      .then((res) => {
        const diag = res?.diag ? ` [${res.diag}]` : "";
        if (res?.ok) setPrintToast({ kind: "ok", text: `Label reprinted for #${order.id}.${diag}` });
        else setPrintToast({ kind: "err", text: `Reprint failed (${res?.error || "unknown"}). Try again.${diag}` });
        setTimeout(() => setPrintToast(null), 7000);
      })
      .catch(() => {
        setPrintToast({ kind: "err", text: "Reprint failed. Try again." });
        setTimeout(() => setPrintToast(null), 4200);
      });
  };

  // Record the physical move of stock OUT of the source warehouse hub and INTO the
  // destination shop, so each shop's on-hand is the running total of its own
  // recorded transfers (reuses the existing ledger — applyMovement writes the
  // /stock_movements audit row + both balance cells atomically). The transfer call
  // itself is UNCHANGED; this now RETURNS whether stock actually moved so the caller
  // can gate the dispatch label on it. Returns true only when stock moved (incl. an
  // idempotent re-send); returns false — with a non-blocking toast telling the picker
  // to route via Lightspeed — when the move isn't recordable or the hub is short.
  const recordDispatchTransfer = async (order, sentSize) => {
    // ── SNEAKERS NO LONGER MOVE ON SEND (2026-07-29) ─────────────────────────
    // Footwear stock stays booked at its hub. The parcel still physically travels
    // and the order still flows exactly as before — but no ledger transfer is
    // written, because the POS now deducts the sale at the hub instead.
    //
    // This is the half of the change that must NEVER run alone. If the transfer
    // stops while the POS still deducts at the shop, every sneaker sale hits a
    // shop cell holding zero and goes negative — precisely the 361-cell hole at
    // Marathon PE that this work exists to remove. Deploy both apps together.
    //
    // Why this is safe for everything else: the gate needs the CATALOGUE and the
    // SIZE to positively agree (see utils/footwearLine.js). Clothing, perfume,
    // bags, an unknown product, a missing size — all fall through and keep
    // writing the transfer exactly as they do today.
    const orderProduct = products.find((p) => p && p.id === order.productId) || null;
    if (isFootwearLine(orderProduct, sentSize ?? order.size)) {
      return { moved: false, reason: "footwear_sells_from_hub", skipped: true };
    }
    // New orders carry destShop; legacy pine orders infer marathon-pine; legacy
    // central orders can't be disambiguated (Marathon PE vs Trophy) → not recordable.
    const toShop = order.destShop || (order.placedStore === "pine" ? "marathon-pine" : null);
    // Prefer placedAtHub, but fall back to order.hub — legacy orders in this component
    // are routed by order.hub, and (now that the label is gated on the transfer) an
    // unrecognised hub would wrongly suppress the label. VALID_HUBS still filters it.
    const fromHub = order.placedAtHub || order.hub;
    // hubC (clothing-customer trials) isn't a stock location — only real hub→shop
    // sends are recorded.
    const VALID_HUBS = ["hub1", "hub2", "hub3"];
    if (!toShop || !VALID_HUBS.includes(fromHub)) {
      // No recordable hub→shop transfer → no stock moved → no label.
      setPrintToast({ kind: "err", text: `Sent — no hub→shop transfer recorded for #${order.id}. No label — route via Lightspeed.` });
      setTimeout(() => setPrintToast(null), 7000);
      return { moved: false, reason: "no_route" };
    }
    // Idempotent + date-unique movementId: order.id is the DAILY counter (reused
    // across days), so scope by createdAt — a re-tap is a no-op, but #042 on two
    // different days stay distinct movements. Strip RTDB-illegal key chars.
    // Clothing orders KEEP the disp_ prefix (the return flow reconstructs it to
    // reverse the exact dispatch), but are ledger-tagged reason:"clothing_order"
    // so their movements stay separable from clothing_refill / clothing_cr.
    const movementId = `disp_${order.id}_${order.createdAt || ""}`.replace(/[.#$[\]/\s:]/g, "_");
    const isClothing = order.productType === "clothing";
    try {
      const res = await applyMovement({
        type: "transfer_out",            // ledger's from→to type (−from, +to)
        productId: order.productId,
        size: sentSize ?? order.size ?? null,  // applyMovement encodes via stockCellPath
        qty: order.qty || 1,
        from: fromHub,
        to: toShop,
        actorRole: "warehouse",
        reason: isClothing ? "clothing_order" : null,
        link: { orderId: order.id },
        ts: serverNowIso(),
        movementId,
        // A1 (stock-integrity) — a SNEAKER dispatch ALWAYS moves the ledger. A
        // short or never-counted hub cell goes NEGATIVE instead of silently
        // skipping the transfer (the old behavior shipped the parcel with zero
        // ledger effect, and the shop cell then went negative at the till — the
        // −534 hole at PE). The hub negative is the honest shortage signal for
        // the count team. CLOTHING is the opposite: the assistant could only
        // order sizes the hub showed stock for, so a zero at send time means
        // reality changed — the send is BLOCKED (insufficient_stock below)
        // rather than driving the hub negative.
        allowNegative: !isClothing,
      });
      if (res && res.ok === false) {
        if (isClothing && res.reason === "insufficient_stock") {
          // Clothing negative guard tripped — stock vanished between order and
          // send. Do NOT mark Sent (blockSend); the picker resolves it via the
          // Out of Stock action, which notifies the customer.
          setPrintToast({ kind: "err", text: `#${order.id} NOT sent — ${HUB_LABELS[fromHub] || fromHub} shows ${res.available ?? 0} on this size. Mark it Out of Stock instead.` });
          setTimeout(() => setPrintToast(null), 9000);
          return { moved: false, reason: "insufficient_stock", blockSend: true };
        }
        // Sneakers (allowNegative): only a genuine write/auth failure lands here.
        setPrintToast({ kind: "err", text: `Sent — but stock not deducted (${res.reason || "write failed"}). No label — route via Lightspeed.` });
        setTimeout(() => setPrintToast(null), 7000);
        return { moved: false, reason: res.reason || "write_failed" };
      }
      // Warn (don't block) when the move drove the hub cell negative — the item
      // shipped before the hub counted it. One extra read, only for the warning.
      try {
        const cellSnap = await get(ref(database, stockCellPath(fromHub, order.productId, sentSize ?? order.size ?? null)));
        const q = cellSnap.val()?.qty;
        if (typeof q === "number" && q < 0) {
          setPrintToast({ kind: "err", text: `#${order.id} sent — ${fromHub} is now ${q} on this size (dispatched before counted). Flag for recount.` });
          setTimeout(() => setPrintToast(null), 9000);
        }
      } catch { /* warning only — never affects the dispatch */ }
      return { moved: true };
    } catch {
      // Ledger write error — we can't confirm stock moved, so withhold the label.
      setPrintToast({ kind: "err", text: `Sent — but stock not deducted (write error). No label — route via Lightspeed.` });
      setTimeout(() => setPrintToast(null), 7000);
      return { moved: false, reason: "write_error" };
    }
  };

  // ── Display refill helpers (Phase 9 / 9.5) ───────────────────────────────
  // Resolve a partner-order refill task to one of two terminal states:
  // 'refilled' (display replenished) or 'stockDepleted' (no inventory left,
  // feeds Phase 11 Insights). displayRefilledBy stores the hub label
  // (anonymous auth has no email; selectedHub is the meaningful signal).
  const setDisplayRefillStatus = (order, status, refillSize = null) => {
    const now = serverNowIso();
    const patch = {
      displayRefillStatus: status,
      displayRefilledBy:   selectedHub,
      updatedAt:           now,
    };
    if (status === "refilled") {
      patch.displayRefilledAt            = now;
      patch.displayRefillStockDepletedAt = null;
      // ── THE SIZE OF THE PAIR NOW ON THE DISPLAY ────────────────────────────
      // This is the moment a specific pair goes onto the shelf, so this is where
      // its size becomes a fact worth recording. A Display Partner REQUEST is
      // deliberately size-optional ("send a pair, any size"); the pair itself
      // never is. Recording it here is what lets the register say what is
      // actually on the floor — and what stops the sale of that pair being
      // unattributable to a hub cell later.
      if (refillSize) {
        patch.displayRefillSize = String(refillSize);
        // Feed the register from the same action — one physical fact, recorded
        // once. Fire-and-forget: the refill is what matters and a register write
        // must never block it.
        const prod = products.find((p) => p && p.id === order.productId) || null;
        if (order.destShop && prod) {
          registerDisplayPair({
            store: order.destShop, product: prod, size: refillSize,
            actorName: selectedHub, orderId: order.id,
          }).catch(() => {});
        }
      }
    } else if (status === "stockDepleted") {
      patch.displayRefillStockDepletedAt = now;
      patch.displayRefilledAt            = null;
    }

    // Resolve the refill task on the order. (Product-level depletion blocking
    // was retired — a "stock depleted" resolution no longer flags the product
    // un-orderable; it only resolves this task and feeds Insights below. So this
    // is now a plain per-order write for both outcomes.)
    updateOrder(order.id, patch);

    // Stock-deplete: append an insights_log entry so the Stock Depleted tab
    // can show past-day counts. Without this, the tab only ever sees today's
    // events because orders/{id} gets overwritten when the daily orderNumber
    // counter wraps. Mirrors the action="out_of_stock" pattern used by OOS
    // Tracker. dedupeByOrderNumber + composite key handle re-fires. This stays a
    // separate best-effort append (a push, not part of the atomic update above);
    // a lost insight entry never affects whether a product is orderable.
    if (status === "stockDepleted") {
      logInsight({
        timestamp:        now,
        // productId joins analytics on the durable key; see the note at the
        // checkout logInsight site. Older events fall back to productName.
        // ?? null keeps the key present for legacy orders (RTDB drops undefined).
        productId:        order.productId ?? null,
        productName:      order.productName,
        productCategory:  order.productCategory || "",
        productType:      order.productType || "sneaker",
        size:             order.size,
        customerName:     order.customerName,
        customerPhone:    order.customerPhone,
        orderNumber:      order.id,
        action:           "stock_depleted",
        placedAtHub:      order.placedAtHub || order.hub || "hub1",
        destShop:         order.destShop ?? null,
        displayRefilledBy: selectedHub,
      });
    }
  };
  // Reverse a refill resolution — clears status + both timestamps + by-hub so
  // the task reappears in the active list. Leaves displayRefillScheduledAt
  // alone so the original 15-min window resumes from where it was.
  const undoDisplayRefill = (order) => {
    updateOrder(order.id, {
      displayRefillStatus:          null,
      displayRefilledAt:            null,
      displayRefillStockDepletedAt: null,
      displayRefilledBy:            null,
      updatedAt:                    serverNowIso(),
    });
  };

  // ── Display Refills data (Phase 9 / 9.5) ─────────────────────────────────
  // Hooks for refills (nowTick, dueRefills) live at the top of this function
  // alongside the other hoisted hooks — see the Rules-of-Hooks note above.
  const refillsBadge = dueRefills.length;

  // ── Clothing refill (CR) batches — per CR hub: hub2 = PE/Trophy, hub3 = Pine ──
  // Hook + helpers (clothingActiveBatches/Completed, CANONICAL_SIZE_ORDER,
  // sizeRank) live at the top of this function alongside the other hoisted
  // hooks — see the Rules-of-Hooks note above.
  const clothingBadge = clothingActiveBatches.length;

  // ── Layby badges (warehouse side) ────────────────────────────────────────
  // Pull requests now live in the MAIN queue, so this tab's badge = parcels
  // awaiting scan-in (Receiving) for this hub — the tab's remaining job.
  // Missing-in-transit exceptions get the louder banner above the tabs.
  const laybyHubOf = (x) => x?.storageHub || DEFAULT_STORAGE_HUB;
  const laybyBadge = laybys.filter(l =>
    laybyHubOf(l) === selectedHub && (l.status || LAYBY_STATUS.IN_TRANSIT) === LAYBY_STATUS.IN_TRANSIT
  ).length;

  // PER-SIZE CR FULFIL (Approach B). plan = { qtys:{orderId:qty}, rejects:{orderId:true} }.
  // For each still-pending line: qty>0 → fire a REAL hub2→store transfer_out then
  // mark it available (recording the sent qty); rejected → mark rejected; else leave
  // pending. One insights_log entry per resolved line (action "ready"/"out_of_stock")
  // so historical Insights + the OOS Tracker see it, exactly as before.
  // Returns { ok, fail, errors[] } so the sheet can surface partial failures.
  const fulfillCRBatch = async (batch, plan) => {
    // Shadow previews are never fulfillable — hard guard in case any UI path
    // slips one through (the card itself renders read-only).
    if (batch?.shadow) return { ok: 0, fail: 0, errors: ["Shadow preview — enable Live Mode to fulfil"] };
    const now = serverNowIso();
    const store = batch.destShop;
    let ok = 0, fail = 0; const errors = [];
    for (const it of batch.items) {
      if (it.status) continue;                                   // already resolved
      // A line whose split was LOCKED by a prior partial attempt (of this same gen) is
      // driven by that locked plan, not the freshly-entered qty — see the split below.
      const locked = it.planGen === it.gen && it.planCountedQty != null;
      let qty = locked
        ? (it.planCountedQty + it.planUncountedQty)
        : Math.max(0, Math.floor(plan.qtys?.[it.orderId] || 0));
      const reject = !locked && !!plan.rejects?.[it.orderId];
      if (qty > 0) {
        if (!store) { fail++; errors.push(`${formatSize(it.size)}: no destination shop on this request`); continue; }
        // STALE-QTY CLAMP (review 2026-07-13): the engine may auto-resize an
        // order between render and this tap. Re-read the live quantity and
        // never send more than the request currently asks — the entered
        // number was captured against a card that may have shrunk.
        if (!locked) {
          try {
            const liveQ = (await get(ref(database, `orders/${it.orderId}/qty`))).val();
            if (typeof liveQ === "number" && liveQ >= 0 && qty > liveQ) qty = liveQ;
            if (qty <= 0) { errors.push(`${formatSize(it.size)}: request was resized to 0 — refresh`); fail++; continue; }
          } catch { /* offline read — proceed with entered qty; movement idempotency still guards */ }
        }
        const from = it.placedAtHub || "hub2";
        // SILENT SPLIT: whatever the hub has COUNTED for this size goes as a real
        // hub→shop transfer (deducts the hub); any OVERAGE is booked as an uncounted
        // add to the shop (received — +shop, no deduction, the units weren't in the
        // system). The warehouse just typed a number and hit Send; it never sees this.
        // The split is derived from the LIVE hub cell, so on a RETRY we must reuse the
        // split LOCKED by the first attempt (below) — never re-derive it from a hub cell
        // that a concurrent writer may have changed, which would misalign the per-leg
        // idempotency keys and double-/under-count.
        let countedQty, uncountedQty;
        if (locked) {
          countedQty = it.planCountedQty;
          uncountedQty = it.planUncountedQty;
        } else {
          const availHere = Number(crHubCells?.[batch.productId]?.[it.size]?.qty) || 0;
          countedQty = Math.min(qty, Math.max(0, availHere));
          uncountedQty = qty - countedQty;
        }
        // Fire both legs INDEPENDENTLY (a failed counted leg must not block the
        // uncounted overage). Each movementId is idempotent per line+gen, so re-tapping
        // Send after a transient failure completes the rest without double-moving stock.
        let sentCounted = 0, sentUncounted = 0, legErr = null;
        if (countedQty > 0) {
          const r = await runCRLeg(() => fireCRRefill({ store, productId: batch.productId, size: it.size, qty: countedQty, from, actorRole: crActorRole, orderId: it.orderId, createdAt: batch.createdAt, gen: it.gen }));
          if (r.ok) sentCounted = countedQty; else legErr = r;
        }
        if (uncountedQty > 0) {
          const r = await runCRLeg(() => fireCRUncounted({ store, productId: batch.productId, size: it.size, qty: uncountedQty, actorRole: crActorRole, orderId: it.orderId, createdAt: batch.createdAt, gen: it.gen }));
          if (r.ok) sentUncounted = uncountedQty; else legErr = r;
        }
        const sent = sentCounted + sentUncounted;
        // Once the counted leg lands (hub mutated), lock in exactly what was sent — a
        // re-split of the now-drained hub would double-count. Otherwise leave the line
        // pending AND persist the split (below) so the retry reuses it verbatim.
        const hubMutated = sentCounted > 0;
        if (sent === qty || hubMutated) {
          ok++;
          // AWAITED (review 2026-07-13): the status write must land before this
          // function returns — the engine's scan treats an unresolved order
          // whose source just emptied as withdrawable, and a fire-and-forget
          // write here widens that race for no benefit.
          await updateOrder(it.orderId, { clothingRefillStatus: "available", clothingRefilledQty: sent, clothingRefilledCountedQty: sentCounted, clothingRefilledUncountedQty: sentUncounted, clothingRefilledAt: now, clothingOutOfStockAt: null, clothingRefilledBy: selectedHub, clothingUncounted: sentUncounted > 0, clothingPlanGen: null, clothingPlanCountedQty: null, clothingPlanUncountedQty: null, updatedAt: now });
          logInsight({ timestamp: now, productId: batch.productId ?? null, productName: batch.productName, productCategory: "", productType: "clothing", size: it.size, qty: sent, customerName: "Shop Refill", customerPhone: null, orderNumber: it.orderId, action: "ready", placedAtHub: it.placedAtHub || "hub2", destShop: batch.destShop ?? null });
          if (sent < qty) errors.push(`${formatSize(it.size)}: only ${sent}/${qty} sent — re-request the remaining ${qty - sent}`);
        } else {
          // Nothing moved at the hub → leave pending for an idempotent re-tap, and LOCK
          // this split so the retry reuses it even if the hub cell changes in between.
          fail++;
          if (!locked) updateOrder(it.orderId, { clothingPlanGen: it.gen, clothingPlanCountedQty: countedQty, clothingPlanUncountedQty: uncountedQty, updatedAt: now });
          errors.push(`${formatSize(it.size)}: ${legErr && legErr.reason === "insufficient_stock" ? `only ${legErr.available} at ${HUB_LABELS[from] || "the hub"}` : (legErr && legErr.reason) || "transfer failed"}`);
        }
      } else if (reject) {
        // Reject is a flag-only write (no stock) — allowed without a stockRole.
        ok++;
        updateOrder(it.orderId, { clothingRefillStatus: "rejected", clothingOutOfStockAt: now, clothingRefilledAt: null, clothingRefilledQty: null, clothingRefilledBy: selectedHub, updatedAt: now });
        logInsight({ timestamp: now, productId: batch.productId ?? null, productName: batch.productName, productCategory: "", productType: "clothing", size: it.size, qty: it.qty, customerName: "Shop Refill", customerPhone: null, orderNumber: it.orderId, action: "out_of_stock", placedAtHub: it.placedAtHub || "hub2", destShop: batch.destShop ?? null });
      }
      // qty 0 & not rejected → left pending for a later pass.
    }
    return { ok, fail, errors };
  };
  // Undo a resolved batch — reverse the REAL stock for every fulfilled line
  // (store→hub2). A line's flags are cleared ONLY if its reversal succeeded (or it
  // never moved stock): a refused reversal (e.g. the shop already sold the units)
  // keeps the line resolved so re-fulfil can't double-deduct the hub. Each cleared
  // line bumps clothingRefillGen, giving the next fulfil cycle fresh idempotency
  // keys. Returns { ok, fail, errors } for the button to surface.
  const undoClothingRefill = async (batch) => {
    const now = serverNowIso();
    let ok = 0, fail = 0; const errors = [];
    for (const it of batch.items) {
      if (it.status === "available" && (it.refilledQty || 0) > 0 && batch.destShop) {
        // Reverse each leg by its own qty: the COUNTED portion goes store→hub (like a
        // normal undo); the UNCOUNTED portion is DESTROYED via a negative adjustment
        // (admin-only per rules), since it was created from nothing on the way out.
        // Legacy lines (fulfilled before the split existed) carry no split fields — fall
        // back to the whole qty being counted, or uncounted if the old flag was set.
        const hasSplit  = it.refilledCountedQty != null || it.refilledUncountedQty != null;
        const countedQ   = hasSplit ? (it.refilledCountedQty || 0)   : (it.uncounted ? 0 : it.refilledQty);
        const uncountedQ = hasSplit ? (it.refilledUncountedQty || 0) : (it.uncounted ? it.refilledQty : 0);
        if (uncountedQ > 0 && crActorRole !== "admin") {
          fail++;
          errors.push(`${formatSize(it.size)}: undoing an uncounted send needs an admin`);
          continue;                                              // keep resolved — don't leave phantom stock
        }
        let legFail = null;
        if (countedQ > 0) {
          const r = await runCRLeg(() => reverseCRRefill({ store: batch.destShop, productId: batch.productId, size: it.size, qty: countedQ, hub: it.placedAtHub || "hub2", orderId: it.orderId, createdAt: batch.createdAt, gen: it.gen, actorRole: crActorRole }));
          if (!r.ok) legFail = r;
        }
        if (uncountedQ > 0 && !legFail) {
          const r = await runCRLeg(() => reverseCRUncounted({ store: batch.destShop, productId: batch.productId, size: it.size, qty: uncountedQ, orderId: it.orderId, createdAt: batch.createdAt, gen: it.gen, actorRole: crActorRole }));
          if (!r.ok) legFail = r;
        }
        if (legFail) {
          fail++;
          errors.push(`${formatSize(it.size)}: ${legFail.reason === "insufficient_stock" ? `shop only has ${legFail.available} left` : (legFail.reason) || "reverse failed"}`);
          continue;                                              // keep the line resolved — stock stands
        }
      }
      ok++;
      updateOrder(it.orderId, { clothingRefillStatus: null, clothingRefilledAt: null, clothingRefilledQty: null, clothingRefilledCountedQty: null, clothingRefilledUncountedQty: null, clothingUncounted: null, clothingPlanGen: null, clothingPlanCountedQty: null, clothingPlanUncountedQty: null, clothingOutOfStockAt: null, clothingRefilledBy: null, clothingRefillGen: (it.gen || 0) + 1, updatedAt: now });
    }
    return { ok, fail, errors };
  };

  const onHoldOrders = hubOrders.filter(o => o.status === STATUS.COMING_TOMORROW);

  const queueFilters = [
    { key:"incoming",     label:"Incoming",     count: hubOrders.filter(o=>o.status===STATUS.INCOMING).length },
    { key:"ready",        label:"Ready",        count: hubOrders.filter(o=>o.status===STATUS.READY).length },
    { key:"out_of_stock", label:"Out of Stock", count: hubOrders.filter(o=>o.status===STATUS.OUT_OF_STOCK).length },
    { key:"all",          label:"All",          count: hubOrders.filter(o=>o.status!==STATUS.COMING_TOMORROW).length },
  ];

  // Queue date-of resolver — adapts to the active filter so each section
  // groups by its most meaningful date.
  const queueDateOf = (o) => {
    if (filter === "ready")        return o.readyAt;
    if (filter === "out_of_stock") return o.outOfStockAt;
    return o.createdAt; // incoming + all
  };

  const filtered = hubOrders
    .filter(o => filter === "all" ? o.status !== STATUS.COMING_TOMORROW : o.status === filter)
    .sort((a, b) => (queueDateOf(b) || "").localeCompare(queueDateOf(a) || ""));

  // Tally for the incoming pill at top right
  const incomingCount = hubOrders.filter(o => o.status === STATUS.INCOMING).length;

  // Tab set for the active hub — shared by the mobile strip and the desktop rail.
  const tabDefs = (selectedHub === "hubC"
    ? [["queue", "Order Queue", null]]
    : selectedHub === "hub2"
    ? [["queue","Order Queue",null],["clothing","CR Orders",clothingBadge],["refills","Display Refills",refillsBadge],["layby","Layby",laybyBadge]]
    : selectedHub === "hub3"
    ? [["queue","Order Queue",null],["clothing","CR Orders",clothingBadge],["refills","Display Refills",refillsBadge],["layby","Layby",laybyBadge]]
    : [["queue","Order Queue",null],["refills","Display Refills",refillsBadge],["layby","Layby",laybyBadge]]);

  // ON-HOLD card — actionable next-day follow-up list, shared by both layouts.
  const onHoldCard = (
    <>
      {onHoldOrders.length > 0 && (
        <div style={{ margin:"0 13px 10px", background:"rgba(20,40,100,.3)", border:"1px solid rgba(60,110,255,.3)", borderRadius:14, padding:"13px 14px" }}>
          <div onClick={() => setOnHoldExpanded(e => !e)} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", cursor:"pointer" }}>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ filter:"drop-shadow(0 0 4px rgba(60,110,255,.5))" }}><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
              <div style={{ fontSize:14, fontWeight:700, color:"#4A7FFF", letterSpacing:"0.3px" }}>ON HOLD</div>
              <div style={{ width:28, height:28, borderRadius:"50%", background:"rgba(60,110,255,.25)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:700, color:"#6A9FFF", boxShadow:"0 0 8px rgba(60,110,255,.4)" }}>{onHoldOrders.length}</div>
              <div style={{ fontSize:11, color:"rgba(255,255,255,.4)", lineHeight:1.4 }}>Next-day<br/>follow-up</div>
            </div>
            <div style={{ fontSize:12, color:"#4A7FFF", fontWeight:600 }}>{onHoldExpanded ? "Hide ∧" : "Show all ∨"}</div>
          </div>
          {!onHoldExpanded && onHoldOrders[0] && (
            <div style={{ display:"flex", alignItems:"center", gap:10, marginTop:10, paddingTop:10, borderTop:"1px solid rgba(255,255,255,.06)" }}>
              <ProductPhoto url={onHoldOrders[0].productPhotoUrl} photo={onHoldOrders[0].productPhoto} size={44} radius={8}/>
              <div style={{ fontSize:13, fontWeight:700, color:"#4A7FFF" }}>#{onHoldOrders[0].id}</div>
              <div style={{ fontSize:13, color:"rgba(255,255,255,.8)", flex:1 }}>{onHoldOrders[0].productName}{onHoldOrders[0].size ? ` — Size ${onHoldOrders[0].size}` : ""}</div>
              {onHoldOrders.length > 1 && <div style={{ fontSize:12, color:"#4A7FFF", fontWeight:600 }}>+{onHoldOrders.length - 1} more</div>}
            </div>
          )}
          {onHoldExpanded && (
            <div style={{ marginTop:10, paddingTop:10, borderTop:"1px solid rgba(255,255,255,.06)", display:"flex", flexDirection:"column", gap:10 }}>
              {onHoldOrders.map(order => (
                <div key={order.id} style={{ background:"rgba(60,110,255,.05)", border:"1px solid rgba(60,110,255,.15)", borderRadius:12, padding:12, display:"flex", alignItems:"center", gap:10, flexWrap:"wrap" }}>
                  <ProductPhoto url={order.productPhotoUrl} photo={order.productPhoto} size={40} radius={8}/>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontWeight:800, color:"#6A9FFF", fontSize:14 }}>#{order.id}</div>
                    <div style={{ fontWeight:600, fontSize:13 }}>{order.productName}{order.size ? ` — Sz ${order.size}` : ""}</div>
                    <div style={{ color:"#555", fontSize:11 }}>{order.customerName}</div>
                  </div>
                  <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                    {/* A2 (stock-integrity): "Available" is a dispatch — route it through the
                        SAME transfer-then-status path as Mark-as-Sent (it previously flipped the
                        status directly and never moved stock, one of the −534 leak paths).
                        No label here — PR #92 removed auto-print on this path on purpose. */}
                    <button onClick={() => markSentWithTransfer(order)} style={{ background:"rgba(0,150,70,.2)", border:"1px solid rgba(0,180,80,.3)", color:"#4ACA7A", borderRadius:8, padding:"6px 10px", fontSize:11, fontWeight:700, cursor:"pointer" }}>Available</button>
                    <button onClick={() => updateStatus(order, STATUS.OUT_OF_STOCK)} style={{ background:"rgba(150,20,20,.15)", border:"1px solid rgba(180,40,40,.25)", color:"#FF6B6B", borderRadius:8, padding:"6px 10px", fontSize:11, fontWeight:700, cursor:"pointer" }}>Still OOS</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </>
  );

  // Active-tab content — shared by the mobile column and the desktop main pane.
  const content = (
    <>
      {mainTab === "queue" && (
        <>
          {/* PILLS */}
          <div style={{ display:"flex", gap:7, padding:"0 13px 12px", overflowX:"auto", scrollbarWidth:"none" }}>
            {queueFilters.map(t => {
              const on = filter === t.key;
              return (
                <div key={t.key} onClick={() => setFilter(t.key)}
                     style={{ padding:"6px 14px", borderRadius:20, fontSize:12, fontWeight:600, whiteSpace:"nowrap", cursor:"pointer", display:"flex", alignItems:"center", gap:5,
                              background: on ? "rgba(60,110,255,.12)" : "rgba(6,9,20,1)",
                              border:"1px solid " + (on ? "rgba(60,110,255,.4)" : "rgba(255,255,255,.07)"),
                              color: on ? "#4A7FFF" : "rgba(255,255,255,.35)" }}>
                  {t.label}
                  {t.count > 0 && (
                    <span style={{ background: on ? "#4A7FFF" : "rgba(255,255,255,.15)", color: on ? "#000" : "#fff", fontSize:10, fontWeight:on?800:700, width:18, height:18, borderRadius:"50%", display:"flex", alignItems:"center", justifyContent:"center" }}>{t.count}</span>
                  )}
                </div>
              );
            })}
          </div>

          {/* ORDER CARDS — grouped by day, last 3 days only (Phase 10) */}
          <div style={{ padding:"0 13px" }}>
            <DayCollapsible
              sectionKey={`wh-${filter}`}
              items={filtered}
              dateOf={queueDateOf}
              columns={isWide ? 2 : 1}
              emptyMessage="No orders in the last 3 days."
              renderItem={(order) => {
            // Layby pull request — render the real PullCard inline (same L-xxxxx
            // invoice + Sent/Reject/Return); it actions via markPullSent, never the
            // order print flow.
            if (order.isLayby) {
              return (
                <PullCard pull={order._pull} selectedHub={selectedHub} nowMs={nowTick}
                  onSent={()   => { setPrintToast({ kind:"ok", text:`${order.id} marked sent to store.` }); setTimeout(() => setPrintToast(null), 4000); }}
                  onReject={() => { setPrintToast({ kind:"ok", text:`${order.id} rejected — store notified.` });  setTimeout(() => setPrintToast(null), 4000); }}
                  onReturn={() => { setPrintToast({ kind:"ok", text:`${order.id} returned to stock.` });          setTimeout(() => setPrintToast(null), 4000); }}/>
              );
            }
            const status = order.status;
            const incoming = status === STATUS.INCOMING;
            const ready    = status === STATUS.READY;
            const oos      = status === STATUS.OUT_OF_STOCK;
            // Card backgrounds + bar by status
            const cardBg = incoming ? "rgba(15,25,60,.5)"
                          : ready   ? "rgba(0,30,15,.4)"
                          : oos     ? "rgba(40,10,10,.4)"
                                    : "rgba(6,9,20,1)";
            const cardBorder = incoming ? "1px solid rgba(60,110,255,.2)"
                              : ready   ? "1px solid rgba(0,180,80,.15)"
                              : oos     ? "1px solid rgba(200,40,40,.15)"
                                        : "1px solid rgba(255,255,255,.07)";
            const barColor = incoming ? "rgba(60,110,255,.8)"
                            : ready   ? "rgba(0,180,80,.8)"
                            : oos     ? "rgba(200,40,40,.8)"
                                      : "rgba(200,140,0,.8)";
            const chipBg = incoming ? "rgba(60,110,255,.15)" : ready ? "rgba(0,180,80,.12)" : oos ? "rgba(200,40,40,.12)" : "rgba(255,255,255,.05)";
            const chipColor = incoming ? "#6A9FFF" : ready ? "#4ACA7A" : oos ? "#FF6B6B" : "#888";
            const chipLabel = incoming ? "Incoming" : ready ? "Ready" : oos ? "Out of Stock" : (STATUS_CONFIG[status]?.label || status);
            return (
              <div style={{ borderRadius:14, overflow:"hidden", position:"relative", background:cardBg, border:cardBorder }}>
                {/* color bar */}
                <div style={{ position:"absolute", left:0, top:0, bottom:0, width:3, background:`linear-gradient(180deg,transparent,${barColor},transparent)` }}/>
                <div style={{ padding:"12px 12px 12px 16px", display:"flex", alignItems:"flex-start", gap:11 }}>
                  <ProductPhoto url={order.productPhotoUrl} photo={order.productPhoto} size={60} radius={10}/>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                      <div style={{ fontSize:13, fontWeight:800, color:"#4A7FFF", letterSpacing:"0.5px" }}>#{order.id}</div>
                      <div style={{ fontSize:10, fontWeight:600, padding:"2px 8px", borderRadius:10, display:"flex", alignItems:"center", gap:4, background:chipBg, color:chipColor }}>
                        {incoming && <span style={{ width:5, height:5, borderRadius:"50%", background:"#4A7FFF", boxShadow:"0 0 3px #4A7FFF", display:"inline-block" }}/>}
                        {chipLabel}
                      </div>
                      {ready ? (
                        // Ready-tab ⋮ menu — reprint the dispatch label if the original
                        // auto-print was lost to a printer trip (print-only; no re-deduct).
                        // Styled as a clearly tappable bordered control, not a faint dot.
                        <div style={{ marginLeft:"auto", position:"relative" }}>
                          <button onClick={() => setMenuOpenId(menuOpenId === order.id ? null : order.id)}
                                  aria-label="Order actions"
                                  style={{ display:"flex", alignItems:"center", justifyContent:"center", minWidth:34, height:28, background:"rgba(74,202,128,.14)", border:"1px solid rgba(74,202,128,.45)", borderRadius:8, color:"#4ACA7A", fontSize:18, fontWeight:800, lineHeight:1, cursor:"pointer", padding:"0 8px" }}>⋮</button>
                          {menuOpenId === order.id && (
                            <>
                              {/* click-away backdrop */}
                              <div onClick={() => setMenuOpenId(null)} style={{ position:"fixed", inset:0, zIndex:40 }}/>
                              <div style={{ position:"absolute", right:0, top:32, zIndex:50, minWidth:160, background:"#0d1322", border:"1px solid rgba(255,255,255,.14)", borderRadius:10, boxShadow:"0 8px 24px rgba(0,0,0,.5)", overflow:"hidden" }}>
                                <button onClick={() => reprintDispatchLabel(order)}
                                        style={{ display:"flex", alignItems:"center", gap:8, width:"100%", padding:"11px 13px", background:"none", border:"none", color:"#fff", fontSize:12.5, fontWeight:600, textAlign:"left", cursor:"pointer" }}>
                                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
                                  Reprint label
                                </button>
                              </div>
                            </>
                          )}
                        </div>
                      ) : (
                        <div style={{ marginLeft:"auto", color:"rgba(255,255,255,.2)", fontSize:16 }}>···</div>
                      )}
                    </div>
                    <div style={{ fontSize:15, fontWeight:600, color:"#fff" }}>{order.productName}{order.size ? ` — Size ${order.size}` : ""}{order.qty > 1 ? ` × ${order.qty}` : ""}</div>
                    <div style={{ fontSize:11, color:"rgba(255,255,255,.4)", marginTop:3, display:"flex", alignItems:"center", gap:4 }}>
                      <svg width="10" height="10" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
                      {order.customerName}{order.customerPhone ? ` · ${order.customerPhone}` : ""}
                    </div>
                    {(order.requestDisplay || order.requestDisplayPartner) && (
                      <div style={{ display:"flex", gap:4, flexWrap:"wrap", marginTop:3 }}>
                        {order.requestDisplay && <span style={{ background:"rgba(60,110,255,.1)", color:"#4A7FFF", border:"1px solid rgba(60,110,255,.25)", borderRadius:10, padding:"1px 7px", fontSize:9, fontWeight:600 }}>Display</span>}
                        {order.requestDisplayPartner && <span style={{ background:"rgba(60,110,255,.12)", color:"#4A7FFF", border:"1px solid rgba(60,110,255,.3)", borderRadius:10, padding:"1px 7px", fontSize:9, fontWeight:600 }}>Partner</span>}
                      </div>
                    )}
                    <div style={{ fontSize:10, color:"rgba(255,255,255,.25)", marginTop:1 }}>{new Date(order.createdAt).toLocaleTimeString()}</div>
                  </div>
                </div>

                {incoming && (() => {
                  const { below, above } = subSizeOptions(order.size);
                  const subAvailable = !!(below || above);
                  const pickerOpen = pickerOpenId === order.id;
                  const commitSub = (chosen) => {
                    setPickerOpenId(null);
                    markSentAndPrint(order, { sentSize: chosen });
                  };
                  // ── SIZE-LESS DISPLAY PARTNER GUARD (2026-07-29) ───────────
                  // A Display Partner request is deliberately size-optional —
                  // the shop wants "a pair for the display", any size. But the
                  // PAIR THAT ACTUALLY GOES has a size, and until now nobody
                  // recorded it: 17 of 51 live partner footwear orders (33%)
                  // carry no size at all. Those orders then fail their dispatch
                  // transfer with `missing_product_or_size`, and the POS — which
                  // takes the size from the order and so never prompts — writes
                  // a sale line with no size. The unit leaves the building and
                  // the books never lose it.
                  //
                  // So the size is captured HERE, at the one moment it becomes a
                  // fact: when the picker takes a specific pair off the shelf.
                  // Nothing changes for the shop, and nothing changes for any
                  // order that already has a size.
                  const guardProduct = products.find((p) => p && p.id === order.productId) || null;
                  const needsSentSize = !order.size && !order.sentSize && productIsFootwear(guardProduct);
                  // Real sizes only — the "_" one-size sentinel is not a choice.
                  const sizeChoices = (Array.isArray(guardProduct?.sizes) ? guardProduct.sizes : [])
                    .map(String).map((s) => s.trim()).filter((s) => s && s !== "_");
                  if (needsSentSize) {
                    return (
                      <div style={{ padding:"0 12px 10px 16px" }}>
                        <div style={{ background:"rgba(251,191,36,.09)", border:"1px solid rgba(251,191,36,.35)",
                                      borderRadius:10, padding:"9px 11px", marginBottom:8 }}>
                          <div style={{ fontSize:11.5, fontWeight:800, color:"#FBBF24", letterSpacing:".03em" }}>
                            WHICH SIZE ARE YOU SENDING?
                          </div>
                          <div style={{ fontSize:11, color:"rgba(251,191,36,.75)", marginTop:3, lineHeight:1.45 }}>
                            This display request came through without a size. Pick the pair you are actually sending —
                            the till needs it to take the sale off the right hub.
                          </div>
                        </div>
                        <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                          {sizeChoices.length ? sizeChoices.map((s) => (
                            <button key={s} onClick={() => {
                                // The size chosen here IS the display registration —
                                // one physical fact, recorded once. Fire-and-forget so
                                // it can never hold up the send.
                                registerDisplayPair({
                                  store: order.destShop, product: guardProduct, size: s,
                                  actorName: null, orderId: order.id,
                                }).catch(() => {});
                                markSentAndPrint(order, { sentSize: s });
                              }}
                              style={{ padding:"10px 14px", borderRadius:10, fontSize:13, fontWeight:800, cursor:"pointer",
                                       background:"rgba(60,110,255,.14)", border:"1px solid rgba(74,127,255,.45)", color:"#9DBCFF",
                                       minWidth:52 }}>
                              <SizeTag size={s} />
                            </button>
                          )) : (
                            <div style={{ fontSize:11.5, color:"rgba(255,255,255,.45)", fontStyle:"italic" }}>
                              This product has no sizes on record — fix the product first, then send.
                            </div>
                          )}
                          <button onClick={() => updateStatus(order, STATUS.OUT_OF_STOCK)}
                            style={{ padding:"10px 14px", borderRadius:10, fontSize:12, fontWeight:700, cursor:"pointer",
                                     background:"rgba(150,20,20,.15)", border:"1px solid rgba(180,40,40,.25)", color:"#FF6B6B" }}>
                            Out of Stock
                          </button>
                        </div>
                      </div>
                    );
                  }
                  return (
                    <div style={{ padding:"0 12px 10px 16px" }}>
                      {!pickerOpen ? (
                        // 2×2 action grid — Sent / OOS on top row, Tomorrow / Substitute on bottom.
                        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                          <button onClick={() => markSentAndPrint(order)}
                                  style={{ padding:"11px 8px", borderRadius:10, fontSize:12, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:5, background:"rgba(0,150,70,.2)", border:"1px solid rgba(0,180,80,.3)", color:"#4ACA7A" }}>
                            <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2.5" strokeLinecap="round"><polyline points="20 6 9 17 4 12"/></svg>
                            Mark as Sent
                          </button>
                          <button onClick={() => updateStatus(order, STATUS.OUT_OF_STOCK)}
                                  style={{ padding:"11px 8px", borderRadius:10, fontSize:12, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:5, background:"rgba(150,20,20,.15)", border:"1px solid rgba(180,40,40,.25)", color:"#FF6B6B" }}>
                            <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2.5" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                            Mark as Out of Stock
                          </button>
                          <button onClick={() => updateStatus(order, STATUS.COMING_TOMORROW)}
                                  style={{ padding:"11px 8px", borderRadius:10, fontSize:12, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:5, background:"rgba(60,110,255,.08)", border:"1px solid rgba(60,110,255,.2)", color:"#4A7FFF" }}>
                            <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2.5" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                            Schedule for Tomorrow
                          </button>
                          <button onClick={() => subAvailable && setPickerOpenId(order.id)}
                                  disabled={!subAvailable}
                                  title={subAvailable ? "" : "No valid substitute size in range"}
                                  style={{ padding:"11px 8px", borderRadius:10, fontSize:12, fontWeight:700, cursor: subAvailable ? "pointer" : "not-allowed", display:"flex", alignItems:"center", justifyContent:"center", gap:5,
                                           background: subAvailable ? "rgba(245,158,11,.12)" : "rgba(255,255,255,.03)",
                                           border:"1px solid " + (subAvailable ? "rgba(245,158,11,.35)" : "rgba(255,255,255,.06)"),
                                           color: subAvailable ? "#F59E0B" : "rgba(255,255,255,.25)",
                                           opacity: subAvailable ? 1 : 0.6 }}>
                            <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                              <polyline points="17 1 21 5 17 9"/><path d="M3 11V9a4 4 0 0 1 4-4h14"/><polyline points="7 23 3 19 7 15"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/>
                            </svg>
                            Substitute Size
                          </button>
                        </div>
                      ) : (
                        // Inline picker — pick a size below/above the requested, or cancel.
                        <div style={{ background:"rgba(245,158,11,.06)", border:"1px solid rgba(245,158,11,.25)", borderRadius:10, padding:"10px 10px 8px" }}>
                          <div style={{ fontSize:11, fontWeight:600, color:"#F59E0B", marginBottom:8, display:"flex", alignItems:"center", gap:6 }}>
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><polyline points="17 1 21 5 17 9"/><path d="M3 11V9a4 4 0 0 1 4-4h14"/><polyline points="7 23 3 19 7 15"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/></svg>
                            Pick a substitute for Size <SizeTag size={order.size} />
                          </div>
                          <div style={{ display:"flex", gap:8 }}>
                            {below && (
                              <button onClick={() => commitSub(below)}
                                      style={{ flex:1, padding:"11px 8px", borderRadius:10, fontSize:12, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:5, background:"rgba(245,158,11,.15)", border:"1px solid rgba(245,158,11,.4)", color:"#F59E0B" }}>
                                <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="19 12 12 19 5 12"/><line x1="12" y1="5" x2="12" y2="19"/></svg>
                                Size <SizeTag size={below} />
                              </button>
                            )}
                            {above && (
                              <button onClick={() => commitSub(above)}
                                      style={{ flex:1, padding:"11px 8px", borderRadius:10, fontSize:12, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:5, background:"rgba(245,158,11,.15)", border:"1px solid rgba(245,158,11,.4)", color:"#F59E0B" }}>
                                <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="5 12 12 5 19 12"/><line x1="12" y1="19" x2="12" y2="5"/></svg>
                                Size <SizeTag size={above} />
                              </button>
                            )}
                            <button onClick={() => setPickerOpenId(null)}
                                    style={{ padding:"11px 12px", borderRadius:10, fontSize:12, fontWeight:600, cursor:"pointer", background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.1)", color:"rgba(255,255,255,.7)" }}>
                              Cancel
                            </button>
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })()}
                {/* Manual "Mark as Collected" removed — an order is collected ONLY by
                    a real POS sale (marathon-pos-app sell-by-order-number). The
                    warehouse view no longer hand-retires orders, so a still-browsing
                    customer's order can't be collected out from under the POS. */}
              </div>
            );
              }}
            />
          </div>
        </>
      )}

      {mainTab === "clothing" && (
        <div style={{ padding:"0 13px" }}>
          <ClothingRefillsTab
            activeBatches={clothingActiveBatches}
            completedBatches={clothingCompletedBatches}
            onFulfill={fulfillCRBatch}
            onUndo={undoClothingRefill}
            hubCells={crHubCells}
            hubLabel={HUB_LABELS[selectedHub] || selectedHub}
            canFulfil={canFulfilCR}
            onViewPhoto={setCrPhoto}
            products={products}
          />
        </div>
      )}

      {crPhoto && <GalleryLightbox photos={crPhoto} onClose={() => setCrPhoto(null)} />}

      {mainTab === "refills" && (
        <div style={{ padding:"0 13px" }}>
          <DisplayRefillsTab
            dueRefills={dueRefills}
            completedRefills={completedRefills}
            showCompleted={showRefilledCompleted}
            setShowCompleted={setShowRefilledCompleted}
            onSetStatus={setDisplayRefillStatus}
            onUndo={undoDisplayRefill}
            products={products}
            nowTick={nowTick}
            selectedHub={selectedHub}
          />
        </div>
      )}

      {mainTab === "layby" && (
        // Keyed on laybySub so the exceptions-banner tap remounts straight to the
        // Exceptions sub-queue. nowTick (30s) drives age/exception recomputation.
        <LaybyTab
          key={`layby-${laybySub}`}
          selectedHub={selectedHub}
          laybys={laybys}
          pulls={laybyPulls}
          nowMs={nowTick}
          initialSub={laybySub}
        />
      )}
    </>
  );

  // ── DESKTOP WORKSPACE (>=1024px) — left rail of queues + titled main pane.
  //    Mobile keeps the single-column layout below. ──
  if (isWide) {
    const activeTab = tabDefs.some(([k]) => k === mainTab) ? mainTab : "queue";
    const activeLabel = (tabDefs.find(([k]) => k === activeTab) || [null, "Order Queue"])[1];
    const navItem = ([key, label, badge]) => {
      const on = activeTab === key;
      return (
        <button key={key} onClick={() => setMainTab(key)}
          style={{ display:"flex", alignItems:"center", gap:11, width:"100%", textAlign:"left", cursor:"pointer", fontFamily:FONT, fontSize:13, fontWeight:600, borderRadius:10, padding:"9px 11px",
                   background: on ? "rgba(74,127,255,.13)" : "transparent", border: on ? "1px solid rgba(74,127,255,.42)" : "1px solid transparent",
                   color: on ? "#9DBCFF" : "rgba(233,238,255,.55)", transition:"background .14s, color .14s" }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink:0, opacity:.9 }}>{WH_TAB_ICON[key]}</svg>
          <span style={{ flex:1 }}>{label}</span>
          {badge != null && badge > 0 && (
            <span style={{ background:"#F59E0B", color:"#000", fontSize:10.5, fontWeight:800, minWidth:19, height:19, borderRadius:"50%", padding:"0 5px", display:"inline-flex", alignItems:"center", justifyContent:"center" }}>{badge}</span>
          )}
        </button>
      );
    };
    return (
      <div style={{ height:"100vh", maxHeight:"100dvh", background:"#000", color:"#f3f6ff", fontFamily:FONT, display:"grid", gridTemplateColumns:"236px minmax(0,1fr)", overflow:"hidden" }}>
        {printToast && (
          <div style={{ position:"fixed", left:"50%", transform:"translateX(-50%)", bottom:24, zIndex:9999, maxWidth:400, width:"90%",
                        background: printToast.kind === "ok" ? "rgba(6,20,12,.97)" : "rgba(24,8,8,.97)",
                        border:"1px solid " + (printToast.kind === "ok" ? "rgba(74,222,128,.4)" : "rgba(248,113,113,.4)"),
                        color:"#fff", borderRadius:12, padding:"12px 16px", fontSize:13, fontWeight:600, boxShadow:"0 20px 50px -20px rgba(0,0,0,.8)" }}>
            {printToast.text}
          </div>
        )}
        {/* RAIL */}
        <aside style={{ background:"rgba(255,255,255,.015)", borderRight:"1px solid rgba(255,255,255,.08)", padding:"22px 13px 16px", display:"flex", flexDirection:"column", gap:3, overflow:"auto" }}>
          <div style={{ display:"flex", alignItems:"baseline", gap:8, padding:"0 9px 10px" }}>
            <span style={{ fontSize:19, fontWeight:800, fontStyle:"italic", letterSpacing:-.6 }}>marathon</span>
            <span style={{ fontSize:9.5, fontWeight:700, letterSpacing:5, color:"#4A7FFF" }}>CLUB</span>
          </div>
          <button onClick={onExit} style={{ display:"flex", alignItems:"center", gap:8, background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.08)", color:"rgba(233,238,255,.6)", borderRadius:10, padding:"9px 12px", fontSize:12.5, fontWeight:600, cursor:"pointer", fontFamily:FONT, marginBottom:6 }}>&larr; Exit</button>
          {/* Hub chip + switch */}
          <div style={{ display:"flex", alignItems:"center", gap:8, background:"rgba(74,127,255,.1)", border:"1px solid rgba(74,127,255,.32)", borderRadius:11, padding:"9px 12px", marginBottom:8 }}>
            <span style={{ width:7, height:7, borderRadius:"50%", background:"#4A7FFF", boxShadow:"0 0 8px #4A7FFF", flexShrink:0 }}/>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:9, letterSpacing:".14em", textTransform:"uppercase", color:"rgba(233,238,255,.4)", fontWeight:700 }}>Hub</div>
              <div style={{ fontSize:13.5, fontWeight:800, color:"#cfe0ff", lineHeight:1.1 }}>{HUB_LABELS[selectedHub] || selectedHub}</div>
            </div>
            <button onClick={() => { localStorage.removeItem("warehouseHub"); setSelectedHub(null); }} title="Switch hub"
              style={{ background:"transparent", border:"none", color:"#9DBCFF", cursor:"pointer", padding:4, display:"flex" }}>
              <svg width="14" height="14" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="17 1 21 5 17 9"/><path d="M3 11V9a4 4 0 014-4h14"/><polyline points="7 23 3 19 7 15"/><path d="M21 13v2a4 4 0 01-4 4H3"/></svg>
            </button>
          </div>
          <div style={{ fontSize:9, letterSpacing:".2em", textTransform:"uppercase", color:"rgba(233,238,255,.3)", padding:"6px 9px", fontWeight:700 }}>Queues</div>
          {tabDefs.map(navItem)}
          <div style={{ flex:1 }} />
          <div style={{ display:"flex", gap:8 }}>
            <div style={{ flex:1, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", borderRadius:11, padding:"9px 10px" }}>
              <div style={{ fontSize:18, fontWeight:800, color:"#9DBCFF", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{incomingCount}</div>
              <div style={{ fontSize:9.5, color:"rgba(233,238,255,.45)", marginTop:3, letterSpacing:".04em", textTransform:"uppercase", fontWeight:600 }}>Incoming</div>
            </div>
            <div style={{ flex:1, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", borderRadius:11, padding:"9px 10px" }}>
              <div style={{ fontSize:18, fontWeight:800, color: onHoldOrders.length ? "#F59E0B" : "rgba(233,238,255,.5)", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{onHoldOrders.length}</div>
              <div style={{ fontSize:9.5, color:"rgba(233,238,255,.45)", marginTop:3, letterSpacing:".04em", textTransform:"uppercase", fontWeight:600 }}>On hold</div>
            </div>
          </div>
        </aside>
        {/* MAIN */}
        <div style={{ minWidth:0, display:"flex", flexDirection:"column", overflow:"hidden" }}>
          <div style={{ padding:"20px 30px 16px", borderBottom:"1px solid rgba(255,255,255,.08)", background:"radial-gradient(800px 280px at 15% -60%, rgba(74,127,255,.08), transparent)" }}>
            <div style={{ fontSize:23, fontWeight:800, letterSpacing:-.4 }}>{activeLabel}</div>
            <div style={{ fontSize:12.5, color:"rgba(233,238,255,.55)", marginTop:3 }}>{HUB_LABELS[selectedHub] || selectedHub} &middot; real-time order status</div>
          </div>
          <div style={{ flex:1, overflow:"auto", padding:"18px 30px 48px" }}>
            <div style={{ maxWidth:1200, margin:"0 auto" }}>
              {selectedHub !== "hubC" && (
                <LaybyExceptionsBanner laybys={laybys} selectedHub={selectedHub} nowMs={nowTick}
                  onOpen={() => { setLaybySub("exceptions"); setMainTab("layby"); }} />
              )}
              {/* On-Hold card on EVERY desktop tab (matches mobile) — it holds
                  live "Available"/"Still OOS" actions, so gating it to the Queue
                  tab stranded those actions on desktop. Self-hides when empty. */}
              {onHoldCard}
              {content}
            </div>
          </div>
        </div>
      </div>
    );
  }


  return (
    <div style={{ minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, maxWidth:430, margin:"0 auto", overflowX:"hidden", paddingBottom:40 }}>
      {/* Dispatch-label print toast — auto-print result on "Mark as Sent" (non-blocking). */}
      {printToast && (
        <div style={{ position:"fixed", left:"50%", transform:"translateX(-50%)", bottom:24, zIndex:9999, maxWidth:400, width:"90%",
                      padding:"11px 14px", borderRadius:10, fontSize:12, fontWeight:600, textAlign:"center",
                      background: printToast.kind === "ok" ? "rgba(0,150,70,.92)" : "rgba(150,30,30,.94)",
                      color:"#fff", border:"1px solid rgba(255,255,255,.18)", boxShadow:"0 6px 24px rgba(0,0,0,.4)" }}>
          {printToast.text}
        </div>
      )}
      {/* TOP BAR */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"50px 14px 10px" }}>
        <div onClick={onExit}
             style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.1)", borderRadius:10, padding:"8px 14px", fontSize:12, color:"rgba(255,255,255,.7)", cursor:"pointer" }}>
          ← Switch View
        </div>
        <div style={{ textAlign:"center" }}>
          <div style={{ fontSize:10, color:"rgba(255,255,255,.4)", letterSpacing:"0.5px" }}>Viewing as:</div>
          <div style={{ fontSize:15, fontWeight:700, color:"#fff", letterSpacing:"0.5px" }}>WAREHOUSE</div>
        </div>
        <div style={{ background:"rgba(20,40,100,.6)", border:"1px solid rgba(60,110,255,.35)", borderRadius:12, padding:"7px 12px", display:"flex", alignItems:"center", gap:6, cursor:"pointer" }}>
          <div style={{ width:7, height:7, background:"#4A7FFF", borderRadius:"50%", boxShadow:"0 0 6px rgba(60,110,255,.8)" }}/>
          <div>
            <div style={{ fontSize:14, fontWeight:700, color:"#fff", lineHeight:1 }}>{incomingCount}</div>
            <div style={{ fontSize:9, color:"rgba(255,255,255,.5)" }}>incoming</div>
          </div>
          <span style={{ color:"#4A7FFF", fontSize:13 }}>›</span>
        </div>
      </div>

      {/* CIRCUIT LINE */}
      <div style={{ height:20, padding:"0 14px", margin:"4px 0 2px", overflow:"hidden" }}>
        <svg width="100%" height="100%" viewBox="0 0 400 20" preserveAspectRatio="none">
          <path d="M0,10 L60,10 L80,3 L140,3 L160,10 L220,10 L240,17 L300,17 L320,10 L400,10" stroke="rgba(60,110,255,.4)" strokeWidth="1" fill="none" strokeLinecap="round"/>
          <circle cx="80" cy="3" r="2.5" fill="rgba(74,127,255,.7)"/>
          <circle cx="160" cy="10" r="2.5" fill="rgba(74,127,255,.7)"/>
          <circle cx="240" cy="17" r="2.5" fill="rgba(74,127,255,.7)"/>
          <circle cx="320" cy="10" r="2.5" fill="rgba(74,127,255,.7)"/>
        </svg>
      </div>

      {/* WAREHOUSE QUEUE HERO IMAGE */}
      <div style={{ position:"relative", width:"100%", height:130, overflow:"hidden", margin:"4px 0 0" }}>
        <img src="/hero/warehouse.jpg" alt="Warehouse Queue" style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%", objectFit:"cover", objectPosition:"center" }}/>
        <div style={{ position:"absolute", bottom:0, left:0, right:0, height:50, background:"linear-gradient(transparent,#000)" }}/>
        <div style={{ position:"absolute", top:0, left:0, right:0, height:20, background:"linear-gradient(#000,transparent)" }}/>
      </div>

      {/* HUB ROW */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"0 14px 10px" }}>
        <div style={{ background:"rgba(20,40,120,.5)", border:"1px solid rgba(60,110,255,.5)", borderRadius:10, padding:"7px 16px", color:"#4A7FFF", fontSize:13, fontWeight:700 }}>
          {HUB_LABELS[selectedHub] || selectedHub}
        </div>
        <div onClick={() => { localStorage.removeItem("warehouseHub"); setSelectedHub(null); }}
             style={{ background:"rgba(255,255,255,.05)", border:"1px solid rgba(255,255,255,.1)", borderRadius:10, padding:"7px 16px", color:"rgba(255,255,255,.7)", fontSize:12, fontWeight:500, cursor:"pointer", display:"flex", alignItems:"center", gap:6 }}>
          <svg width="11" height="11" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2">
            <polyline points="17 1 21 5 17 9"/><path d="M3 11V9a4 4 0 014-4h14"/><polyline points="7 23 3 19 7 15"/><path d="M21 13v2a4 4 0 01-4 4H3"/>
          </svg>
          Switch Hub
        </div>
      </div>

      <div style={{ fontSize:12, color:"rgba(255,255,255,.3)", padding:"2px 14px 10px" }}>Update order status in real time.</div>

      {/* ON HOLD CARD */}
      {onHoldCard}

      {/* LAYBY EXCEPTIONS — loud banner above the tabs on every tab. Self-hides
          when there are no missing-in-transit parcels. Tap → Layby tab,
          Exceptions sub-queue. (hubC never stores laybys, so skip it there.) */}
      {selectedHub !== "hubC" && (
        <LaybyExceptionsBanner laybys={laybys} selectedHub={selectedHub} nowMs={nowTick}
          onOpen={() => { setLaybySub("exceptions"); setMainTab("layby"); }} />
      )}

      {/* TABS — same hub→tabs wiring as the desktop rail; tabDefs is the single
          source of truth (CR Orders on the CR hubs: hub2 for PE/Trophy, hub3 for
          Pine — see CR_HUB_BY_UNIVERSE). Only the mobile chrome differs below. */}
      <div style={{ display:"flex", gap:6, padding:"0 13px 10px" }}>
        {tabDefs.map(([key, label, badge]) => (
          <div key={key} onClick={() => setMainTab(key)}
               style={{ flex:1, padding:"10px 6px", borderRadius:10, fontSize:11.5, fontWeight:600, textAlign:"center", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:5,
                        background: mainTab===key ? "rgba(60,110,255,.12)" : "rgba(6,9,20,1)",
                        border: mainTab===key ? "1px solid rgba(60,110,255,.4)" : "1px solid rgba(255,255,255,.07)",
                        color: mainTab===key ? "#4A7FFF" : "rgba(255,255,255,.3)" }}>
            {key === "queue"    && <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2" strokeLinecap="round"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>}
            {key === "clothing" && <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M16 4l-4 4-4-4M3 7l5-3h8l5 3M3 7v13a1 1 0 001 1h16a1 1 0 001-1V7M3 7l4 4M21 7l-4 4"/></svg>}
            {key === "refills"  && <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>}
            {key === "layby"    && <svg width="13" height="13" viewBox="0 0 24 24" stroke="currentColor" fill="none" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-14L4 7m8 4v10m0-10L4 7v10l8 4"/></svg>}
            <span>{label}</span>
            {badge != null && badge > 0 && (
              <span style={{ background: mainTab===key ? "#F59E0B" : "rgba(245,158,11,.85)", color:"#000", fontSize:10, fontWeight:800, minWidth:18, height:18, borderRadius:"50%", padding:"0 5px", display:"inline-flex", alignItems:"center", justifyContent:"center" }}>{badge}</span>
            )}
          </div>
        ))}
      </div>

      {content}
    </div>
  );
}

// ─── DISPLAY REFILLS TAB (Phase 9 / 9.5) ──────────────────────────────────────
// Hub-scoped list of partner-order refill tasks that have crossed the 15-min
// post-send threshold. Each due task resolves to one of two terminal states:
// 'refilled' (display replenished) or 'stockDepleted' (no inventory left to
// refill — feeds Phase 11 Insights by filtering orders). Show Completed
// toggle reveals both kinds with status-colored borders and a per-row Undo.
// nowTick is the parent's 30s ticker — used for "waiting Xm" chips so they
// update live without a render storm.
function DisplayRefillsTab({ dueRefills, completedRefills, showCompleted, setShowCompleted, onSetStatus, onUndo, nowTick, selectedHub, products = [] }) {
  // Does this refill need a size picked before it can be marked done? Only for
  // FOOTWEAR that carries no size anywhere on the order — clothing and one-size
  // items are untouched, and a partner order that already named a size just uses it.
  // Two-step confirm for a size-less footwear refill. A single tap on a size
  // button marked the task done irreversibly — too easy to fumble on a phone in
  // a warehouse. Pick, see it selected, then Send.
  const [sizeSheet, setSizeSheet] = useState(null);   // { order, options, picked }

  const refillSizeChoices = (order) => {
    const known = order.sentSize || order.size || null;
    const prod = products.find((p) => p && p.id === order.productId) || null;
    if (known || !productIsFootwear(prod)) return { needed: false, options: [] };
    const options = (Array.isArray(prod?.sizes) ? prod.sizes : [])
      .map(String).map((x) => x.trim()).filter((x) => x && x !== "_");
    return { needed: true, options };
  };
  const fmtWaiting = (iso) => {
    const ms = nowTick - new Date(iso).getTime();
    const mins = Math.floor(ms / 60000);
    if (mins < 60) return `${mins}m`;
    const hrs = Math.floor(mins / 60);
    return `${hrs}h ${mins % 60}m`;
  };

  if (!dueRefills.length && !completedRefills.length) return (
    <div style={{ textAlign:"center", color:"#444", padding:"4rem" }}>
      <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#F59E0B" strokeOpacity="0.4" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>
      <div style={{ fontSize:"1rem", marginTop:"0.75rem", color:"rgba(255,255,255,.55)" }}>No display refills pending.</div>
      <div style={{ fontSize:"0.85rem", color:"#333", marginTop:"0.5rem" }}>Partner orders sent from {HUB_LABELS[selectedHub] || selectedHub} appear here 15 minutes after they're marked sent.</div>
    </div>
  );

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
      {/* Header: count + instruction */}
      {dueRefills.length > 0 && (
        <div style={{ background:"rgba(245,158,11,.06)", border:"1px solid rgba(245,158,11,.3)", borderRadius:14, padding:"12px 14px", display:"flex", alignItems:"center", gap:12 }}>
          <div style={{ fontWeight:800, fontSize:30, color:"#F59E0B", lineHeight:1, letterSpacing:"-1px" }}>{dueRefills.length}</div>
          <div style={{ flex:1 }}>
            <div style={{ fontWeight:700, color:"#fff", fontSize:13 }}>Display Refill{dueRefills.length !== 1 ? "s" : ""} Due</div>
            <div style={{ color:"rgba(255,255,255,.5)", fontSize:11, marginTop:2 }}>Put each item back on the display shelf, then tap Refilled.</div>
          </div>
        </div>
      )}

      {/* Show / Hide Completed toggle */}
      {completedRefills.length > 0 && (
        <button onClick={() => setShowCompleted(v => !v)}
                style={{ alignSelf:"flex-start", display:"flex", alignItems:"center", gap:6, padding:"7px 11px", borderRadius:999,
                         border: showCompleted ? "1px solid rgba(60,110,255,.5)" : "1px solid rgba(255,255,255,.1)",
                         background: showCompleted ? "rgba(60,110,255,.12)" : "rgba(255,255,255,.03)",
                         color: showCompleted ? BLUE_L : "rgba(255,255,255,.55)",
                         fontWeight:600, fontSize:12, cursor:"pointer" }}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            {showCompleted
              ? <><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></>
              : <><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></>}
          </svg>
          {showCompleted ? "Hide" : "Show"} Completed ({completedRefills.length})
        </button>
      )}

      {/* All-caught-up state */}
      {dueRefills.length === 0 && completedRefills.length > 0 && !showCompleted && (
        <div style={{ background:CARD, border:"1px solid rgba(74,222,128,.4)", borderRadius:14, padding:"22px 18px", textAlign:"center", boxShadow:"0 0 12px rgba(74,222,128,.12)" }}>
          <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="#4ADE80" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ filter:"drop-shadow(0 0 6px rgba(74,222,128,.35))" }}>
            <circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/>
          </svg>
          <div style={{ color:"#fff", fontSize:14, fontWeight:700, marginTop:10 }}>All caught up</div>
          <div style={{ color:"rgba(255,255,255,.55)", fontSize:12, marginTop:4 }}>{completedRefills.length} task{completedRefills.length !== 1 ? "s" : ""} resolved.</div>
        </div>
      )}

      {/* ── SIZE CONFIRM SHEET ──────────────────────────────────────────────
          Pick a size, see it selected, then Send. Two deliberate actions, so a
          mis-tap costs nothing — it was one tap and irreversible before. */}
      {sizeSheet && (
        <div onClick={() => setSizeSheet(null)}
             style={{ position:"fixed", inset:0, background:"rgba(0,0,0,.78)", backdropFilter:"blur(4px)",
                      display:"flex", alignItems:"center", justifyContent:"center", padding:16, zIndex:80 }}>
          <div onClick={(e) => e.stopPropagation()}
               style={{ background:"rgba(10,13,24,.97)", border:"1px solid rgba(74,127,255,.32)", borderRadius:18,
                        padding:"20px 20px 16px", maxWidth:420, width:"100%", boxShadow:"0 24px 60px rgba(0,0,0,.6)" }}>
            <div style={{ fontSize:16.5, fontWeight:800, color:"#fff", marginBottom:3 }}>
              Which size are you sending?
            </div>
            <div style={{ fontSize:12.5, color:"rgba(233,238,255,.55)", lineHeight:1.5, marginBottom:14 }}>
              #{sizeSheet.order.id} · {sizeSheet.order.productName}
              <br />
              This goes on the display register, and the till uses it to take the sale off the right hub.
            </div>

            <div style={{ display:"flex", gap:8, flexWrap:"wrap", marginBottom:16 }}>
              {sizeSheet.options.length ? sizeSheet.options.map((sz) => {
                const on = sizeSheet.picked === sz;
                return (
                  <button key={sz} onClick={() => setSizeSheet((v) => ({ ...v, picked: sz }))}
                    style={{ padding:"13px 17px", borderRadius:12, fontSize:15, fontWeight:800, cursor:"pointer", minWidth:56,
                             background: on ? "#4A7FFF" : "rgba(74,127,255,.10)",
                             border: `2px solid ${on ? "#4A7FFF" : "rgba(74,127,255,.30)"}`,
                             color: on ? "#fff" : "#9DBCFF",
                             boxShadow: on ? "0 0 16px rgba(74,127,255,.35)" : "none",
                             transition:"background .12s, border-color .12s" }}>
                    <SizeTag size={sz} />
                  </button>
                );
              }) : (
                <div style={{ fontSize:12.5, color:"#FBBF24" }}>
                  This product has no sizes on record — fix the product first.
                </div>
              )}
            </div>

            <div style={{ display:"flex", gap:9, justifyContent:"flex-end", flexWrap:"wrap" }}>
              <button onClick={() => setSizeSheet(null)}
                style={{ background:"transparent", border:"1px solid rgba(255,255,255,.18)", color:"rgba(233,238,255,.7)",
                         borderRadius:11, padding:"11px 17px", fontSize:13, fontWeight:700, cursor:"pointer" }}>
                Cancel
              </button>
              <button
                disabled={!sizeSheet.picked}
                onClick={() => { const { order, picked } = sizeSheet; setSizeSheet(null); onSetStatus(order, "refilled", picked); }}
                style={{ background: sizeSheet.picked ? "#4ADE80" : "rgba(255,255,255,.06)",
                         border:"none", color: sizeSheet.picked ? "#04351a" : "rgba(233,238,255,.32)",
                         borderRadius:11, padding:"11px 22px", fontSize:13.5, fontWeight:800,
                         cursor: sizeSheet.picked ? "pointer" : "not-allowed" }}>
                {sizeSheet.picked ? `Send size ${sizeSheet.picked}` : "Pick a size"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Due cards — grouped by day, oldest-first within each bucket.
          includeOlder=true preserves the Phase 9.5 "never lose a due refill"
          semantic by collapsing >3-day-old tasks into a separate Older bucket. */}
      {dueRefills.length > 0 && (
        <DayCollapsible
          sectionKey="refills-due"
          items={dueRefills}
          dateOf={(o) => o.displayRefillScheduledAt}
          includeOlder={true}
          emptyMessage="No display refills due."
          renderItem={(order) => (
            <div style={{ background:CARD, border:"1px solid rgba(245,158,11,.4)", borderLeft:"3px solid #F59E0B", borderRadius:RADIUS, padding:14, boxShadow:"0 0 12px rgba(245,158,11,.1)" }}>
              <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:10 }}>
                <ProductPhoto url={order.productPhotoUrl} photo={order.productPhoto} size={48} radius={10}/>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:2 }}>
                    <span style={{ fontFamily:"'SF Pro Display',-apple-system,sans-serif", fontWeight:800, fontSize:"1.1rem", color:BLUE_L, lineHeight:1 }}>#{order.id}</span>
                    <span style={{ background:"rgba(245,158,11,.15)", color:"#F59E0B", border:"1px solid rgba(245,158,11,.35)", borderRadius:999, padding:"1px 8px", fontSize:9, fontWeight:700, textTransform:"uppercase", letterSpacing:".5px" }}>Partner</span>
                    <span style={{ marginLeft:"auto", background:"rgba(255,255,255,.04)", color:"rgba(255,255,255,.55)", border:"1px solid rgba(255,255,255,.08)", borderRadius:999, padding:"1px 8px", fontSize:10, fontWeight:600 }}>
                      waiting {fmtWaiting(order.displayRefillScheduledAt)}
                    </span>
                  </div>
                  <div style={{ fontWeight:700, color:"#fff", fontSize:13 }}>{order.productName}{order.size || order.sentSize ? ` — Size ${formatSize(sourceDisplaySize(order))}` : ""}</div>
                </div>
              </div>
              <div style={{ display:"flex", gap:8 }}>
                <button onClick={() => {
                          const sz = refillSizeChoices(order);
                          // Footwear with no size on the order opens the confirm
                          // sheet; everything else keeps the direct action.
                          if (sz.needed) setSizeSheet({ order, options: sz.options, picked: null });
                          else onSetStatus(order, "refilled", order.sentSize || order.size || null);
                        }}
                        style={{ flex:1, padding:"11px 8px", borderRadius:10, fontSize:12, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:6, background:"rgba(0,150,70,.2)", border:"1px solid rgba(0,180,80,.4)", color:"#4ADE80" }}>
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><polyline points="20 6 9 17 4 12"/></svg>
                  Refilled
                </button>
                <button onClick={() => onSetStatus(order, "stockDepleted")}
                        style={{ flex:1, padding:"11px 8px", borderRadius:10, fontSize:12, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:6, background:"rgba(150,20,20,.15)", border:"1px solid rgba(180,40,40,.4)", color:"#F87171" }}>
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                  Stock Depleted
                </button>
              </div>
            </div>
          )}
        />
      )}

      {/* Completed cards — revealed by toggle. Day-grouped (24h cap upstream
          means at most today + yesterday will ever have items). */}
      {showCompleted && completedRefills.length > 0 && (
        <>
          <div style={{ marginTop:10, marginBottom:2, display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ height:1, flex:1, background:"rgba(255,255,255,.06)" }} />
            <div style={{ fontSize:10, fontWeight:700, color:"rgba(255,255,255,.4)", letterSpacing:"1.2px" }}>COMPLETED</div>
            <div style={{ height:1, flex:1, background:"rgba(255,255,255,.06)" }} />
          </div>
          <DayCollapsible
            sectionKey="refills-done"
            items={completedRefills}
            dateOf={(o) => o.displayRefilledAt || o.displayRefillStockDepletedAt}
            emptyMessage="No completed refills."
            renderItem={(order) => {
              const isDepleted = order.displayRefillStatus === "stockDepleted";
              const accent = isDepleted ? "rgba(248,113,113,.5)"  : "rgba(74,222,128,.5)";
              const tint   = isDepleted ? "rgba(248,113,113,.1)"  : "rgba(74,222,128,.1)";
              const text   = isDepleted ? "#F87171"               : "#4ADE80";
              return (
                <div style={{ background:CARD, border:`1px solid ${accent}`, borderLeft:`3px solid ${accent}`, borderRadius:RADIUS, padding:14, opacity:0.85 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:8 }}>
                    <ProductPhoto url={order.productPhotoUrl} photo={order.productPhoto} size={44} radius={10}/>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:2 }}>
                        <span style={{ fontFamily:"'SF Pro Display',-apple-system,sans-serif", fontWeight:800, fontSize:"1rem", color:"rgba(255,255,255,.85)", lineHeight:1 }}>#{order.id}</span>
                        <span style={{ display:"inline-flex", alignItems:"center", gap:4, background:tint, color:text, border:`1px solid ${accent}`, borderRadius:999, padding:"1px 7px", fontSize:9, fontWeight:700, textTransform:"uppercase", letterSpacing:".5px" }}>
                          <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round">
                            {isDepleted
                              ? <><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></>
                              : <polyline points="20 6 9 17 4 12"/>}
                          </svg>
                          {isDepleted ? "Stock Depleted" : "Refilled"}
                        </span>
                      </div>
                      <div style={{ fontWeight:600, color:"rgba(255,255,255,.85)", fontSize:12 }}>{order.productName}{order.size || order.sentSize ? ` — Size ${formatSize(sourceDisplaySize(order))}` : ""}</div>
                    </div>
                  </div>
                  <div style={{ display:"flex", justifyContent:"flex-end" }}>
                    <button onClick={() => onUndo(order)}
                            style={{ padding:"7px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.12)", background:"rgba(255,255,255,.04)", color:"rgba(255,255,255,.7)", fontWeight:600, fontSize:11, cursor:"pointer", display:"flex", alignItems:"center", gap:5 }}>
                      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                        <polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/>
                      </svg>
                      Undo
                    </button>
                  </div>
                </div>
              );
            }}
          />
        </>
      )}
    </div>
  );
}

// ─── CR ORDERS TAB (per CR hub: hub2 = PE/Trophy, hub3 = Pine) ────────────────
// Each card represents one refill batch — clothing orders that share a
// (productId, createdAt) pair. The Phase 12B writer puts all sizes from one
// "Place Refill Request" tap into a single loop with one shared timestamp,
// so this groups by batch cleanly. Fulfilment is per size from the SELECTED
// hub's own stock (hubCells/hubLabel props); the same engine serves both hubs.
//
// Active list: last 3 days (strict, no Older bucket — clothing requests don't
// stay due indefinitely like display refills do).
// Completed list: 24h window after resolution (mirrors Phase 9.5 cleanup),
// applied upstream in the parent memo. Undo clears the status fields and
// returns the batch to the active list.
// Stepper button — verbatim copy of the Transfer screen's stepBtn
// (components/stock/Transfer.jsx) so the CR size boxes match it exactly.
// (Copied, not imported: Transfer.jsx is being modified on another branch.)
const crStepBtn = {
  width: 26, height: 30, flexShrink: 0, borderRadius: 8, border: "1px solid rgba(60,110,255,.3)",
  background: "rgba(60,110,255,.1)", color: "#9CB8FF", fontSize: 16, fontWeight: 700, cursor: "pointer",
  fontFamily: FONT, lineHeight: 1, display: "flex", alignItems: "center", justifyContent: "center",
};

// Per-size status chips for a batch's items (green ✓ fulfilled · red ✕ rejected ·
// blue ×qty still pending). Shared by the active resolved-row and completed cards.
function SizeStatusChips({ items }) {
  return (
    <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginTop:6 }}>
      {items.map(it => {
        const done = it.status === "available";
        const rej  = it.status === "rejected" || it.status === "outOfStock";
        const border = done ? "rgba(74,222,128,.4)" : rej ? "rgba(248,113,113,.4)" : "rgba(60,110,255,.25)";
        const bg     = done ? "rgba(74,222,128,.08)" : rej ? "rgba(248,113,113,.08)" : "rgba(60,110,255,.08)";
        const badge  = done ? { c:"#4ADE80", t:`✓${it.refilledQty ?? it.qty}${(it.refilledQty != null && it.refilledQty < it.qty) ? `/${it.qty}` : ""}` }
                     : rej  ? { c:"#F87171", t:"rejected" }
                     :        { c:BLUE_L, t:`×${it.qty}` };
        return (
          <span key={it.orderId} style={{ display:"inline-flex", alignItems:"center", gap:5, background:bg, border:`1px solid ${border}`, borderRadius:7, padding:"3px 8px", fontSize:11, fontWeight:600, color:"#fff" }}>
            <SizeTag size={it.size} />
            <span style={{ color:badge.c, fontSize:10, fontWeight:700 }}>{badge.t}</span>
          </span>
        );
      })}
    </div>
  );
}

// One CR request = ONE COMPACT card (accordion). Collapsed: small photo (tap →
// lightbox), name, destination shop, and a coverage summary chip — many fit on
// screen, scannable like the Clothing-Sold list. Tap to expand THAT card into the
// per-size fulfil/reject steppers + Send; the parent keeps one card open at a time.
// Send fires a real hub2→store transfer per fulfilled size (onFulfill →
// fulfillCRBatch, idempotent per line+generation).
function CRFulfillCard({ batch, hubCells, hubLabel, canFulfil, onFulfill, onViewPhoto, products, fmtTime, open, onToggle }) {
  const [qtys, setQtys]       = useState({});   // { orderId: qty } (only for touched lines)
  const [touched, setTouched] = useState({});   // { orderId: true }
  const [rejects, setRejects] = useState({});   // { orderId: true }
  const [busy, setBusy]       = useState(false);
  const [msg, setMsg]         = useState(null);

  const availAt = (size) => Number(hubCells?.[batch.productId]?.[size]?.qty) || 0;
  const pending  = batch.items.filter(it => !it.status);
  const resolved = batch.items.filter(it => it.status);

  // The stepper defaults to what the hub has COUNTED for this size, but the + button /
  // input can be raised all the way to the full requested qty — the counted stock is
  // NOT a hard cap. If they send more than is counted, fulfillCRBatch silently books
  // the overage as an uncounted add to the shop (received, no deduction). The warehouse
  // UI shows nothing about this — it just looks like a normal send.
  // Without a stock role, fulfil qtys are forced to 0 — reject stays available.
  // A line whose split is LOCKED (a prior partial attempt is being finished) defaults to
  // its locked total so Send stays enabled and re-tapping completes exactly that plan —
  // fulfillCRBatch ignores the entered qty for a locked line anyway.
  const lockedTotal = (it) => (it.planGen === it.gen && it.planCountedQty != null) ? (it.planCountedQty + it.planUncountedQty) : null;
  const defaultQ = (it) => lockedTotal(it) ?? Math.min(it.qty, availAt(it.size));   // pre-fill = counted here (or locked total)
  const capOf    = (it) => lockedTotal(it) ?? it.qty;                               // they can send up to the full request
  const displayQ = (it) => (!canFulfil || rejects[it.orderId]) ? 0 : (touched[it.orderId] ? Math.min(qtys[it.orderId] || 0, capOf(it)) : defaultQ(it));
  const setQ = (orderId, v, max) => { setTouched(t => ({ ...t, [orderId]: true })); setQtys(q => ({ ...q, [orderId]: Math.max(0, Math.min(max, Math.floor(Number(v) || 0))) })); };
  const toggleReject = (orderId) => setRejects(r => { const n = { ...r }; if (n[orderId]) delete n[orderId]; else n[orderId] = true; return n; });

  const product = (products || []).find(p => p.id === batch.productId);
  const photos = product ? productPhotos(product) : (batch.productPhotoUrl ? [batch.productPhotoUrl] : []);
  const hasPhotos = onViewPhoto && photos.length > 0;

  const totalSend   = pending.reduce((s, it) => s + displayQ(it), 0);
  const totalReject = pending.filter(it => rejects[it.orderId]).length;
  const canSend = !busy && (totalSend > 0 || totalReject > 0);

  const send = async () => {
    if (!canSend) return;
    setBusy(true); setMsg(null);
    try {
      const plan = { qtys: {}, rejects };
      pending.forEach(it => { plan.qtys[it.orderId] = displayQ(it); });
      const res = await onFulfill(batch, plan);
      if (res?.errors?.length) setMsg(`${res.ok} done · ${res.fail} failed — ${res.errors.join("; ")}`);
      else { setTouched({}); setRejects({}); setQtys({}); }
    } catch (e) {
      setMsg("Send failed — check your connection and try again.");
      console.warn("CR send failed:", e);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div style={{ background:CARD, border: open ? "1px solid rgba(60,110,255,.55)" : "1px solid rgba(60,110,255,.3)", borderLeft:"3px solid #4A7FFF", borderRadius:RADIUS, boxShadow: open ? "0 0 12px rgba(60,110,255,.15)" : "none", overflow:"hidden" }}>
      {/* Compact header row — always visible; tap to expand/collapse. */}
      <div onClick={onToggle} role="button" tabIndex={0} aria-expanded={open}
           onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onToggle(); } }}
           style={{ display:"flex", alignItems:"center", gap:10, padding:"9px 11px", cursor:"pointer" }}>
        <div onClick={hasPhotos ? (e) => { e.stopPropagation(); onViewPhoto(photos); } : undefined}
             title={hasPhotos ? "Tap to enlarge" : undefined}
             style={{ position:"relative", flexShrink:0, cursor: hasPhotos ? "zoom-in" : "default", borderRadius:8 }}>
          <ProductPhoto url={batch.productPhotoUrl} photo={batch.productPhoto} size={38} radius={8}/>
          {hasPhotos && (
            <div style={{ position:"absolute", right:-3, bottom:-3, width:14, height:14, borderRadius:7, background:"rgba(4,5,10,.9)", border:"1px solid rgba(60,110,255,.5)", display:"flex", alignItems:"center", justifyContent:"center" }}>
              <svg width="7" height="7" viewBox="0 0 24 24" fill="none" stroke="#6A9FFF" strokeWidth="3" strokeLinecap="round"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
            </div>
          )}
        </div>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:13, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{batch.productName}</div>
          <div style={{ color:"rgba(255,255,255,.45)", fontSize:10, marginTop:1 }}>
            {batch.destShop ? `${labelFor(batch.destShop)} · ` : ""}{relativeTimeFromIso(batch.createdAt) || fmtTime(batch.createdAt)}
            {batch.autoRefill && (
              <span style={{ marginLeft:6, fontSize:9, fontWeight:700, color:"#FBBF24", border:"1px solid rgba(251,191,36,.4)", borderRadius:5, padding:"1px 5px", verticalAlign:"middle" }}>
                {batch.shadow ? "AUTO (SHADOW)" : "AUTO"}
              </span>
            )}
          </div>
        </div>
        <span style={{ flexShrink:0, fontSize:10.5, fontWeight:700, color:BLUE_L, background:"rgba(60,110,255,.1)", border:"1px solid rgba(60,110,255,.3)", borderRadius:999, padding:"3px 9px", whiteSpace:"nowrap" }}>
          {pending.length} size{pending.length === 1 ? "" : "s"}
          {resolved.length > 0 ? ` · ${resolved.length} done` : ""}
        </span>
        <span style={{ color:"#4A7FFF", transform: open ? "rotate(90deg)" : "none", transition:"transform .15s", fontSize:13, flexShrink:0 }}>▸</span>
      </div>

      {open && batch.shadow && (
        // Shadow preview: exactly what Live Mode will create, but read-only.
        <div style={{ padding:"2px 11px 11px", borderTop:"1px solid rgba(251,191,36,.2)" }}>
          <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginTop:10 }}>
            {pending.map(it => (
              <span key={it.orderId} style={{ border:"1px solid rgba(251,191,36,.35)", background:"rgba(251,191,36,.07)", borderRadius:10, padding:"6px 11px", fontSize:12.5 }}>
                <b style={{ color:"#fff" }}>{it.size}</b>
                <span style={{ color:"#FBBF24", fontWeight:700 }}> ×{it.qty}</span>
              </span>
            ))}
          </div>
          <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:10 }}>
            Shadow preview — the engine would create this request for real in Live Mode. Nothing to action yet.
          </div>
        </div>
      )}

      {open && !batch.shadow && (
        <div style={{ padding:"2px 11px 11px", borderTop:"1px solid rgba(60,110,255,.12)" }}>
          {resolved.length > 0 && <SizeStatusChips items={resolved} />}

          {/* Per-size stepper GRID — verbatim the Transfer screen's size boxes
              (Transfer.jsx expanded product: compact box per size, several per
              row, −/[number]/+ capped at hub stock) plus a corner ✕ to reject
              the size. Stepper is ALWAYS visible — 0-stock sizes just cap at 0
              ("0 here" in amber) instead of hiding the input. */}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(118px, 1fr))", gap:8, marginTop:10 }}>
            {pending.map(it => {
              const cap = capOf(it);                           // = requested qty; the + button goes this high
              const rejected = !!rejects[it.orderId];
              const q = displayQ(it);
              return (
                <div key={it.orderId} style={{ position:"relative", background:CARD, borderRadius:10, padding:"7px 8px",
                       border: rejected ? "1px solid rgba(248,113,113,.5)" : q ? "1px solid rgba(74,222,128,.4)" : "1px solid rgba(60,110,255,.12)" }}>
                  {/* Corner ✕ — reject this size (tap again to undo). */}
                  <button onClick={() => toggleReject(it.orderId)} title={rejected ? "Undo reject" : "Reject this size"}
                          style={{ position:"absolute", top:-7, right:-7, width:20, height:20, borderRadius:10, fontSize:10, fontWeight:700, cursor:"pointer", lineHeight:1, display:"flex", alignItems:"center", justifyContent:"center", padding:0,
                                   border: rejected ? "1px solid rgba(248,113,113,.7)" : "1px solid rgba(180,40,40,.45)",
                                   background: rejected ? "rgba(248,113,113,.3)" : "rgba(15,6,6,.95)", color:"#F87171" }}>
                    ✕
                  </button>
                  <div style={{ display:"flex", alignItems:"baseline", justifyContent:"space-between", marginBottom:5 }}>
                    <span style={{ fontSize:12, color:BLUE_L, fontWeight:700 }}><SizeTag size={it.size} /></span>
                    <span style={{ fontSize:9, color:"rgba(255,255,255,.4)" }}>×{it.qty}</span>
                  </div>
                  {rejected ? (
                    <div style={{ height:30, display:"flex", alignItems:"center", justifyContent:"center", fontSize:11, fontWeight:700, color:"#F87171" }}>rejected</div>
                  ) : (
                    <div style={{ display:"flex", alignItems:"center", gap:4 }}>
                      <button onClick={() => setQ(it.orderId, q - 1, cap)} style={{ ...crStepBtn, opacity: q <= 0 ? 0.4 : 1 }}>−</button>
                      <input type="number" inputMode="numeric" min="0" max={cap} value={q || ""} placeholder="0"
                             disabled={!canFulfil || cap <= 0}
                             onChange={(e) => setQ(it.orderId, e.target.value, cap)}
                             style={{ ...stockInput, width:"100%", minWidth:0, boxSizing:"border-box", textAlign:"center", padding:"6px 2px", opacity: (!canFulfil || cap <= 0) ? 0.5 : 1 }} />
                      <button onClick={() => setQ(it.orderId, q + 1, cap)} style={{ ...crStepBtn, opacity: q >= cap ? 0.4 : 1 }}>+</button>
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          {msg && <div style={{ marginTop:10, fontSize:11.5, color:"#F5A623" }}>{msg}</div>}

          <div style={{ display:"flex", alignItems:"center", gap:10, marginTop:12 }}>
            <div style={{ flex:1, fontSize:11, color:"rgba(255,255,255,.45)" }}>
              {canFulfil
                ? `Send ${totalSend} unit(s)${totalReject ? ` · reject ${totalReject}` : ""} → ${batch.destShop ? labelFor(batch.destShop) : "shop"}`
                : "No stock role — you can Reject; transfers need a warehouse/admin stock role."}
            </div>
            <button onClick={send} disabled={!canSend}
                    style={{ padding:"11px 20px", borderRadius:10, fontSize:12.5, fontWeight:700, cursor: canSend ? "pointer" : "not-allowed",
                             background: canSend ? "rgba(0,150,70,.22)" : "rgba(255,255,255,.04)",
                             border: `1px solid ${canSend ? "rgba(0,180,80,.5)" : "rgba(255,255,255,.1)"}`,
                             color: canSend ? "#4ADE80" : "rgba(255,255,255,.35)", display:"flex", alignItems:"center", gap:6 }}>
              {busy ? "Sending…" : "Send"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// Busy-guarded Undo for completed CR batches — undo now reverses REAL stock, so
// the button disables while in flight and surfaces refused reversals.
function UndoCRButton({ batch, onUndo }) {
  const [busy, setBusy] = useState(false);
  const run = async () => {
    if (busy) return;
    setBusy(true);
    try {
      const res = await onUndo(batch);
      if (res?.errors?.length) alert(`Undo: ${res.ok} line(s) reversed, ${res.fail} kept — ${res.errors.join("; ")}`);
    } catch (e) {
      alert("Undo failed — check your connection and try again.");
      console.warn("CR undo failed:", e);
    } finally {
      setBusy(false);
    }
  };
  return (
    <button onClick={run} disabled={busy}
            style={{ padding:"7px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.12)", background:"rgba(255,255,255,.04)", color:"rgba(255,255,255,.7)", fontWeight:600, fontSize:11, cursor: busy ? "wait" : "pointer", opacity: busy ? 0.6 : 1, display:"flex", alignItems:"center", gap:5 }}>
      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/>
      </svg>
      {busy ? "Undoing…" : "Undo"}
    </button>
  );
}

function ClothingRefillsTab({ activeBatches, completedBatches, onFulfill, onUndo, hubCells, hubLabel, canFulfil, onViewPhoto, products }) {
  // Accordion — one request expanded at a time so the whole queue stays scannable.
  const [openKey, setOpenKey] = useState(null);
  // Open = the working queue (only unresolved requests); History = resolved ones
  // (24h window upstream). Resolved requests LEAVE the main page entirely.
  const [view, setView] = useState("open");
  // Store filter — PE and Trophy requests are separate cards (grouping key
  // includes destShop) and this filter lets staff work ONE store's pile at a
  // time, so pickers always know exactly which store they're fulfilling.
  const [storeFilter, setStoreFilter] = useState("all");
  const forStore = (arr) => storeFilter === "all" ? arr : arr.filter(b => (b.destShop || "") === storeFilter);
  const storeCount = (arr, s) => arr.filter(b => (b.destShop || "") === s).length;
  const shownActive = forStore(activeBatches);
  const shownCompleted = forStore(completedBatches);
  const fmtTime = (iso) => {
    if (!iso) return "—";
    return new Date(iso).toLocaleTimeString([], { hour:"2-digit", minute:"2-digit" });
  };

  const pill = (on) => ({
    padding:"7px 16px", borderRadius:999, fontSize:12, fontWeight:700, cursor:"pointer",
    border: on ? "1px solid rgba(60,110,255,.5)" : "1px solid rgba(255,255,255,.1)",
    background: on ? "rgba(60,110,255,.14)" : "rgba(255,255,255,.03)",
    color: on ? BLUE_L : "rgba(255,255,255,.45)",
  });

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
      {/* Open / History pills */}
      <div style={{ display:"flex", gap:6 }}>
        <button onClick={() => setView("open")} style={pill(view === "open")}>Open{shownActive.length ? ` (${shownActive.length})` : ""}</button>
        <button onClick={() => setView("history")} style={pill(view === "history")}>History{shownCompleted.length ? ` (${shownCompleted.length})` : ""}</button>
      </div>
      {/* Store pills — Marathon PE / Trophy refills never mix */}
      <div style={{ display:"flex", gap:6 }}>
        {[["all", "All stores"], ["marathon-pe", "Marathon PE"], ["trophy", "Trophy"]].map(([val, label]) => (
          <button key={val} onClick={() => setStoreFilter(val)} style={pill(storeFilter === val)}>
            {label}{val !== "all" && storeCount(activeBatches, val) ? ` (${storeCount(activeBatches, val)})` : ""}
          </button>
        ))}
      </div>

      {/* OPEN — the working queue, ONE flat list (owner directive 2026-07-13):
          this is operational work, not a history view. Every unfulfilled
          request stays visible until fulfilled, withdrawn, or cancelled —
          sorted oldest-first so nothing rots at the bottom of a collapsed
          "yesterday" section. Age shows on each card; day-grouping lives only
          in History below. */}
      {view === "open" && (activeBatches.length > 0 ? (
        <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
          {[...shownActive]
            .sort((a, b) => String(a.createdAt || "").localeCompare(String(b.createdAt || "")))
            .map((batch) => (
              <CRFulfillCard key={batch.batchKey}
                             batch={batch} hubCells={hubCells} hubLabel={hubLabel} canFulfil={canFulfil}
                             onFulfill={onFulfill} onViewPhoto={onViewPhoto} products={products} fmtTime={fmtTime}
                             open={openKey === batch.batchKey}
                             onToggle={() => setOpenKey(k => k === batch.batchKey ? null : batch.batchKey)} />
            ))}
        </div>
      ) : (
        <div style={{ textAlign:"center", color:"#444", padding:"3rem 1rem" }}>
          <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#4ADE80" strokeOpacity="0.6" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/></svg>
          <div style={{ fontSize:"0.95rem", marginTop:"0.75rem", color:"rgba(255,255,255,.55)" }}>No open CR requests.</div>
          <div style={{ fontSize:"0.8rem", color:"#333", marginTop:"0.4rem" }}>Shop refill requests appear here; resolved ones move to History.</div>
        </div>
      ))}

      {/* HISTORY — resolved requests (fulfilled / partial / rejected), day-grouped. */}
      {view === "history" && (completedBatches.length === 0 ? (
        <div style={{ textAlign:"center", color:"#444", padding:"3rem 1rem", fontSize:"0.9rem" }}>Nothing resolved recently.</div>
      ) : (
        <DayCollapsible
          sectionKey="clothing-done"
          items={shownCompleted}
          dateOf={(b) => b.resolvedAt || b.createdAt}
          keyOf={(b) => b.batchKey}
          emptyMessage="No completed clothing refills."
          renderItem={(batch) => {
            const st = batch.status;                         // "available" | "partial" | "rejected"
            const accent = st === "rejected" ? "rgba(248,113,113,.5)" : st === "partial" ? "rgba(245,166,35,.5)" : "rgba(74,222,128,.5)";
            const tint   = st === "rejected" ? "rgba(248,113,113,.1)"  : st === "partial" ? "rgba(245,166,35,.1)"  : "rgba(74,222,128,.1)";
            const text   = st === "rejected" ? "#F87171"              : st === "partial" ? "#F5A623"              : "#4ADE80";
            const label  = st === "rejected" ? "Rejected" : st === "partial" ? "Partial" : "Fulfilled";
            return (
              <div style={{ background:CARD, border:`1px solid ${accent}`, borderLeft:`3px solid ${accent}`, borderRadius:RADIUS, padding:14, opacity:0.85 }}>
                <div style={{ display:"flex", alignItems:"flex-start", gap:12, marginBottom:8 }}>
                  <ProductPhoto url={batch.productPhotoUrl} photo={batch.productPhoto} size={48} radius={10}/>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:2 }}>
                      <span style={{ fontWeight:700, color:"rgba(255,255,255,.85)", fontSize:13 }}>{batch.productName}</span>
                      <span style={{ display:"inline-flex", alignItems:"center", gap:4, background:tint, color:text, border:`1px solid ${accent}`, borderRadius:999, padding:"1px 7px", fontSize:9, fontWeight:700, textTransform:"uppercase", letterSpacing:".5px" }}>
                        {label}
                      </span>
                    </div>
                    <div style={{ color:"rgba(255,255,255,.4)", fontSize:10 }}>
                      Submitted {fmtTime(batch.createdAt)}{batch.destShop ? ` · → ${labelFor(batch.destShop)}` : ""}
                    </div>
                    <SizeStatusChips items={batch.items} />
                  </div>
                </div>
                <div style={{ display:"flex", justifyContent:"flex-end" }}>
                  <UndoCRButton batch={batch} onUndo={onUndo} />
                </div>
              </div>
            );
          }}
        />
      ))}
    </div>
  );
}

// ─── CUSTOMER VIEW ────────────────────────────────────────────────────────────
// Shop the order was placed for. destShop is the source of truth; fall back to
// the Pine universe for legacy orders that only carry placedAtHub.
function orderShopLabel(o) {
  if (o?.destShop && SHOP_LABELS[o.destShop]) return SHOP_LABELS[o.destShop];
  if (o?.placedAtHub === "hub3") return "Pine";
  return null;
}
// "2h ago" / "just now" relative time (recomputed on render).
function relTime(iso) {
  if (!iso) return null;
  const mins = Math.floor((serverNowMs() - new Date(iso).getTime()) / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}
function absTime(iso) {
  if (!iso) return null;
  return new Date(iso).toLocaleString([], { weekday: "short", hour: "2-digit", minute: "2-digit" });
}


function CustomerView({ orders, onExit }) {
  const [orderId, setOrderId] = useState("");
  const [found, setFound] = useState(null);
  const [searched, setSearched] = useState(false);
  // Use the whole screen on desktop (≥1024px); phones keep the single column.
  const isWide = !useIsNarrow(1024);
  // Respect the Hub-2 dispatch hold on this customer-facing page: a READY order
  // whose reveal instant hasn't passed must read as "being prepared". Ticks every
  // 10s so the hold releases at the reveal time (mirrors the TV board).
  const [revealClock, setRevealClock] = useState(() => serverNowMs());
  useEffect(() => { const id = setInterval(() => setRevealClock(serverNowMs()), 10000); return () => clearInterval(id); }, []);
  const heldOrders = useMemo(() => (orders || []).map(o => holdHub2Ready(o, revealClock)), [orders, revealClock]);
  // Keep an open detail pane live: re-sync `found` from heldOrders as the reveal
  // clock ticks and as orders update — else a held order never flips to Ready at
  // its reveal, and later live status changes (Ready→Collected/OOS) stay hidden
  // until the customer re-searches. No-op when nothing is open.
  useEffect(() => {
    setFound(prev => (prev ? (heldOrders.find(o => o.id === prev.id) || prev) : prev));
  }, [heldOrders]);

  const doSearch = (idOverride) => {
    const raw = (idOverride ?? orderId).toString();
    const clean = raw.trim().replace(/^#/, "");
    if (!clean) return;
    const o = heldOrders.find(o => o.id === clean.padStart(3, "0") || o.id === clean);
    setOrderId(clean);
    setFound(o || null);
    setSearched(true);
  };
  const reset = () => { setFound(null); setSearched(false); setOrderId(""); };

  const cfg = found ? STATUS_CONFIG[found.status] : null;

  // Lifecycle timeline — adapts to the order's status/branch. Each step:
  // { label, time, state: done | current | pending | error }.
  const steps = useMemo(() => {
    if (!found) return [];
    const s = found.status;
    const out = [{ label: "Order placed", sub: "Sent to the warehouse", time: found.createdAt, state: "done" }];
    if (s === STATUS.OUT_OF_STOCK) {
      out.push({ label: "Out of stock", sub: "Speak to an assistant", time: found.outOfStockAt, state: "error" });
    } else if (s === STATUS.COMING_TOMORROW) {
      out.push({ label: "Preparing", sub: "Being picked", time: null, state: "done" });
      out.push({ label: "Available tomorrow", sub: "Come back tomorrow to collect", time: found.comingTomorrowAt, state: "current" });
    } else {
      const readyDone = s === STATUS.READY || s === STATUS.COLLECTED;
      out.push({ label: "Preparing", sub: "Being picked & checked", time: null, state: readyDone ? "done" : "current" });
      out.push({ label: "Ready to collect", sub: "Waiting for you at the store", time: readyDone ? found.readyAt : null, state: readyDone ? (s === STATUS.COLLECTED ? "done" : "current") : "pending" });
      out.push({ label: "Collected", sub: "Enjoy!", time: found.collectedAt, state: s === STATUS.COLLECTED ? "done" : "pending" });
    }
    return out;
  }, [found]);

  const STEP_C = {
    done:    { dot: "#4ADE80", ring: "rgba(74,222,128,.25)", text: "#fff" },
    current: { dot: "#4A7FFF", ring: "rgba(74,127,255,.3)",  text: "#fff" },
    error:   { dot: "#F87171", ring: "rgba(248,113,113,.25)", text: "#FCA5A5" },
    pending: { dot: "rgba(255,255,255,.18)", ring: "transparent", text: "rgba(255,255,255,.4)" },
  };

  const shopLabel = found ? orderShopLabel(found) : null;

  const STATUS_MSG = {
    [STATUS.INCOMING]:        "Your order is being prepared. We'll have it ready soon.",
    [STATUS.READY]:           "Your order is ready. Please collect it at the store.",
    [STATUS.OUT_OF_STOCK]:    "Sorry, this item is out of stock. Please speak to an assistant.",
    [STATUS.COLLECTED]:       "This order has been collected. Thank you.",
    [STATUS.COMING_TOMORROW]: "Your item will be available tomorrow. Please come back then.",
  };

  // ── FULL-SCREEN DESKTOP WORKSPACE (≥1024px) — search/recent rail + rich pane ──
  if (isWide) {
    const q = orderId.trim().toLowerCase();
    const railList = (q ? heldOrders.filter(o => o.id.includes(q) || (o.customerName || "").toLowerCase().includes(q)) : heldOrders).slice(0, 60);
    const statusAt = found ? ({ [STATUS.INCOMING]: found.createdAt, [STATUS.READY]: found.readyAt, [STATUS.OUT_OF_STOCK]: found.outOfStockAt, [STATUS.COMING_TOMORROW]: found.comingTomorrowAt, [STATUS.COLLECTED]: found.collectedAt }[found.status] || found.updatedAt) : null;
    const subbed = found && found.sentSize && found.sentSize !== found.size ? found.sentSize : null;
    const tags = [];
    if (found?.isLayby) tags.push("Layby");
    if (found?.requestDisplayPartner) tags.push("Display Partner");
    else if (found?.requestDisplay) tags.push("Display");
    const detailRow = (label, value) => value == null || value === "" ? null : (
      <div style={{ display: "flex", justifyContent: "space-between", gap: 14, padding: "11px 0", borderBottom: "1px solid rgba(255,255,255,.06)" }}>
        <span style={{ fontSize: 12.5, color: "rgba(233,238,255,.5)", flexShrink: 0 }}>{label}</span>
        <span style={{ fontSize: 13.5, fontWeight: 600, color: "#fff", textAlign: "right", overflow: "hidden", textOverflow: "ellipsis" }}>{value}</span>
      </div>
    );
    return (
      <div style={{ height: "100vh", maxHeight: "100dvh", background: "#000", color: "#f3f6ff", fontFamily: FONT, display: "grid", gridTemplateColumns: "340px minmax(0,1fr)", overflow: "hidden" }}>
        <style>{`@keyframes otPulse{0%,100%{box-shadow:0 0 0 0 rgba(74,127,255,.5)}50%{box-shadow:0 0 0 6px rgba(74,127,255,0)}}
          .ot-press{transition:transform .1s ease, filter .12s ease}.ot-press:active{transform:scale(.98)}.ot-press:hover{filter:brightness(1.08)}
          .ot-row{transition:background .12s ease, border-color .12s ease}.ot-row:hover{background:rgba(255,255,255,.05)}`}</style>
        {/* RAIL — search + orders */}
        <aside style={{ background: "rgba(255,255,255,.015)", borderRight: "1px solid rgba(255,255,255,.08)", display: "flex", flexDirection: "column", overflow: "hidden" }}>
          <div style={{ padding: "22px 16px 12px" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
              <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                <span style={{ fontSize: 19, fontWeight: 800, fontStyle: "italic", letterSpacing: "-0.6px" }}>marathon</span>
                <span style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: 5, color: "#4A7FFF" }}>CLUB</span>
              </div>
              {onExit && <button onClick={onExit} className="ot-press" style={{ background: "rgba(255,255,255,.05)", border: "1px solid rgba(255,255,255,.1)", color: "rgba(233,238,255,.6)", borderRadius: 9, padding: "6px 11px", fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: FONT }}>← Exit</button>}
            </div>
            <div style={{ fontSize: 20, fontWeight: 800, letterSpacing: "-0.3px", marginBottom: 12 }}>Order Tracking</div>
            <div style={{ position: "relative" }}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ position: "absolute", left: 11, top: "50%", transform: "translateY(-50%)", opacity: .4 }}><circle cx="11" cy="11" r="8" /><path d="M21 21l-4.3-4.3" /></svg>
              <input value={orderId} onChange={e => setOrderId(e.target.value)} onKeyDown={e => e.key === "Enter" && doSearch()} placeholder="Order # or customer…"
                style={{ width: "100%", boxSizing: "border-box", padding: "10px 12px 10px 34px", borderRadius: 11, fontSize: 13.5, background: "rgba(255,255,255,.05)", border: "1px solid rgba(255,255,255,.12)", color: "#fff", outline: "none", fontFamily: FONT }} />
            </div>
          </div>
          <div style={{ flex: 1, overflow: "auto", padding: "4px 10px 16px", display: "flex", flexDirection: "column", gap: 7 }}>
            {railList.length === 0 && <div style={{ padding: 24, textAlign: "center", color: "rgba(233,238,255,.4)", fontSize: 13 }}>No matching orders.</div>}
            {railList.map(o => {
              const c = STATUS_CONFIG[o.status];
              const on = found && found.id === o.id;
              return (
                <button key={o.id} className="ot-row" onClick={() => { setOrderId(o.id); setFound(o); setSearched(true); }}
                  style={{ display: "flex", alignItems: "center", gap: 10, padding: 8, borderRadius: 12, cursor: "pointer", textAlign: "left", fontFamily: FONT,
                           background: on ? "rgba(74,127,255,.14)" : "transparent", border: on ? "1px solid rgba(74,127,255,.45)" : "1px solid transparent" }}>
                  <ProductPhoto url={o.productPhotoUrl} photo={o.productPhoto} size={40} radius={9} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 700, color: "#fff", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>#{o.id} · {o.productName}</div>
                    <div style={{ fontSize: 11, color: "rgba(233,238,255,.45)", marginTop: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{o.customerName || "—"}</div>
                  </div>
                  {c && <span style={{ flexShrink: 0, width: 8, height: 8, borderRadius: "50%", background: c.color, boxShadow: `0 0 6px ${c.color}` }} title={c.label} />}
                </button>
              );
            })}
          </div>
        </aside>

        {/* MAIN — detail or empty state */}
        <div style={{ minWidth: 0, overflow: "auto" }}>
          {found && cfg ? (
            <div style={{ padding: "36px 40px 60px", maxWidth: 880, margin: "0 auto" }}>
              {/* HERO — compact, cohesive */}
              <div style={{ display: "flex", gap: 20, alignItems: "center", background: "linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02))", border: "1px solid rgba(255,255,255,.1)", borderRadius: 22, padding: 20, boxShadow: "0 26px 60px -36px rgba(0,0,0,.9), inset 0 1px 0 rgba(255,255,255,.08)", marginBottom: 16 }}>
                <div style={{ width: 116, height: 116, borderRadius: 18, overflow: "hidden", border: "1px solid rgba(255,255,255,.12)", background: "rgba(255,255,255,.06)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 50, flexShrink: 0 }}>
                  {found.productPhotoUrl ? <img src={found.productPhotoUrl} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} onError={e => { e.currentTarget.style.display = "none"; }} /> : (found.productPhoto || "👟")}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
                    <span style={{ fontSize: 15, fontWeight: 800, color: "#9DBCFF", letterSpacing: ".02em", fontVariantNumeric: "tabular-nums" }}>#{found.id}</span>
                    <span style={{ background: cfg.bg, color: cfg.color, border: `1px solid ${cfg.border}`, borderRadius: 999, padding: "5px 13px", fontWeight: 800, fontSize: 12.5, display: "flex", alignItems: "center", gap: 6 }}>
                      <span style={{ width: 6, height: 6, borderRadius: "50%", background: cfg.color, boxShadow: `0 0 7px ${cfg.color}` }} />
                      {cfg.label}
                    </span>
                  </div>
                  <div style={{ fontSize: 22, fontWeight: 800, color: "#fff", marginTop: 7, lineHeight: 1.2 }}>{found.productName}</div>
                  <div style={{ display: "flex", flexWrap: "wrap", gap: 7, marginTop: 12 }}>
                    <span style={{ fontSize: 11.5, fontWeight: 700, color: "#cfe0ff", background: "rgba(74,127,255,.14)", border: "1px solid rgba(74,127,255,.28)", borderRadius: 8, padding: "3px 10px" }}>Size <SizeTag size={found.size} /></span>
                    {found.qty > 1 && <span style={{ fontSize: 11.5, fontWeight: 700, color: "rgba(233,238,255,.7)", background: "rgba(255,255,255,.05)", border: "1px solid rgba(255,255,255,.1)", borderRadius: 8, padding: "3px 10px" }}>×{found.qty}</span>}
                    {shopLabel && <span style={{ fontSize: 11.5, fontWeight: 700, color: "rgba(233,238,255,.7)", background: "rgba(255,255,255,.05)", border: "1px solid rgba(255,255,255,.1)", borderRadius: 8, padding: "3px 10px" }}>{shopLabel}</span>}
                    {tags.map(t => <span key={t} style={{ fontSize: 11.5, fontWeight: 700, color: "#FBBF24", background: "rgba(251,191,36,.12)", border: "1px solid rgba(251,191,36,.3)", borderRadius: 8, padding: "3px 10px" }}>{t}</span>)}
                  </div>
                </div>
              </div>

              {/* Status message strip */}
              <div style={{ background: `linear-gradient(90deg, ${cfg.color}22, transparent)`, borderLeft: `3px solid ${cfg.color}`, borderRadius: 12, padding: "13px 16px", marginBottom: 16, fontSize: 13.5, color: "rgba(233,238,255,.85)", lineHeight: 1.5 }}>
                <b style={{ color: cfg.color }}>{cfg.label}{statusAt ? ` · ${relTime(statusAt)}` : ""}</b> — {STATUS_MSG[found.status] || ""}
              </div>

              {/* Two columns: timeline + details */}
              <div style={{ display: "grid", gridTemplateColumns: "1.3fr 1fr", gap: 16, alignItems: "start" }}>
                <div style={{ background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.09)", borderRadius: 18, padding: "20px 22px 8px", boxShadow: "0 18px 44px -30px rgba(0,0,0,.8), inset 0 1px 0 rgba(255,255,255,.05)" }}>
                  <div style={{ fontSize: 11, color: "rgba(233,238,255,.4)", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", marginBottom: 18 }}>Progress</div>
                  {steps.map((st, i) => {
                    const c = STEP_C[st.state];
                    const last = i === steps.length - 1;
                    return (
                      <div key={st.label} style={{ display: "flex", gap: 15 }}>
                        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", flexShrink: 0 }}>
                          <div style={{ width: 20, height: 20, borderRadius: "50%", background: c.dot, border: `2px solid ${c.ring === "transparent" ? "rgba(255,255,255,.14)" : c.ring}`, display: "flex", alignItems: "center", justifyContent: "center", animation: st.state === "current" ? "otPulse 1.8s infinite" : "none" }}>
                            {st.state === "done" && <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#04120a" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>}
                            {st.state === "error" && <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#1a0606" strokeWidth="4" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" /></svg>}
                          </div>
                          {!last && <div style={{ width: 2, flex: 1, minHeight: 30, background: st.state === "done" ? "rgba(74,222,128,.35)" : "rgba(255,255,255,.08)", margin: "4px 0" }} />}
                        </div>
                        <div style={{ flex: 1, paddingBottom: last ? 12 : 18, marginTop: -1 }}>
                          <div style={{ display: "flex", justifyContent: "space-between", gap: 12, alignItems: "baseline" }}>
                            <div style={{ fontSize: 15, fontWeight: 700, color: c.text }}>{st.label}</div>
                            {st.time && <div style={{ fontSize: 11.5, color: "rgba(233,238,255,.45)", whiteSpace: "nowrap", fontVariantNumeric: "tabular-nums" }}>{absTime(st.time)}</div>}
                          </div>
                          <div style={{ fontSize: 12.5, color: st.state === "pending" ? "rgba(233,238,255,.3)" : "rgba(233,238,255,.55)", marginTop: 3 }}>{st.sub}</div>
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div style={{ background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.09)", borderRadius: 18, padding: "20px 20px 8px", boxShadow: "0 18px 44px -30px rgba(0,0,0,.8), inset 0 1px 0 rgba(255,255,255,.05)" }}>
                  <div style={{ fontSize: 11, color: "rgba(233,238,255,.4)", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", marginBottom: 6 }}>Details</div>
                  {detailRow("Customer", found.customerName)}
                  {detailRow("Phone", found.customerPhone)}
                  {detailRow("Ordered from", shopLabel)}
                  {subbed && detailRow("Sent instead", <span style={{ color: "#FBBF24" }}><SizeTag size={subbed} /></span>)}
                  {detailRow("Placed", absTime(found.createdAt))}
                </div>
              </div>
            </div>
          ) : (
            <div style={{ height: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 14, textAlign: "center", padding: 40, color: "rgba(233,238,255,.4)" }}>
              <svg width="54" height="54" viewBox="0 0 24 24" fill="none" stroke="rgba(74,127,255,.55)" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 11 12 14 22 4" /><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11" /></svg>
              <div style={{ fontSize: 17, fontWeight: 700, color: "rgba(233,238,255,.7)" }}>{searched ? `No order #${orderId} found` : "Select an order to track"}</div>
              <div style={{ fontSize: 13, maxWidth: 340, lineHeight: 1.5 }}>{searched ? "Double-check the number on the slip, or pick one from the list." : "Search by order number or customer, or pick one from the list on the left."}</div>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: "#000", color: "#fff", fontFamily: FONT, maxWidth: isWide ? 1120 : 480, margin: "0 auto", padding: isWide ? "40px 40px 64px" : "34px 18px 48px", boxSizing: "border-box" }}>
      <style>{`@keyframes otPulse{0%,100%{box-shadow:0 0 0 0 rgba(74,127,255,.5)}50%{box-shadow:0 0 0 6px rgba(74,127,255,0)}}
        .ot-press{transition:transform .1s ease, filter .12s ease}.ot-press:active{transform:scale(.98)}.ot-press:hover{filter:brightness(1.08)}`}</style>

      {/* Brand header */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 22 }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
          <span style={{ fontSize: 20, fontWeight: 800, fontStyle: "italic", letterSpacing: "-0.6px" }}>marathon</span>
          <span style={{ fontSize: 10, fontWeight: 700, letterSpacing: 5, color: "#4A7FFF" }}>CLUB</span>
        </div>
        {onExit && <button onClick={onExit} className="ot-press" style={{ background: "rgba(255,255,255,.05)", border: "1px solid rgba(255,255,255,.1)", color: "rgba(233,238,255,.6)", borderRadius: 9, padding: "7px 12px", fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: FONT }}>← Back</button>}
      </div>

      <h1 style={{ fontSize: 26, fontWeight: 800, letterSpacing: "-0.5px", marginBottom: 4 }}>Order Tracking</h1>
      <div style={{ fontSize: 13, color: "rgba(233,238,255,.5)", marginBottom: 22 }}>Enter your order number to see live status.</div>

      {/* Search */}
      {!found && (
        <div style={{ maxWidth: isWide ? 460 : "100%" }}>
          <input placeholder="000" value={orderId} onChange={e => setOrderId(e.target.value.replace(/[^0-9]/g, ""))}
                 onKeyDown={e => e.key === "Enter" && doSearch()} maxLength={4} inputMode="numeric"
                 style={{ width: "100%", boxSizing: "border-box", background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.12)", borderRadius: 16, padding: "18px", color: "#fff", fontSize: 34, fontWeight: 800, textAlign: "center", letterSpacing: "12px", outline: "none", marginBottom: 10, fontVariantNumeric: "tabular-nums" }} />
          <button onClick={() => doSearch()} className="ot-press"
                  style={{ width: "100%", background: "linear-gradient(180deg, #5A8BFF, #4A7FFF)", color: "#fff", border: "none", borderRadius: 13, padding: 15, fontSize: 14.5, fontWeight: 700, cursor: "pointer", fontFamily: FONT, boxShadow: "0 10px 24px -10px rgba(74,127,255,.8)" }}>
            Track order →
          </button>
        </div>
      )}

      {searched && !found && (
        <div style={{ maxWidth: isWide ? 460 : "100%", marginTop: 16, color: "#F87171", background: "rgba(248,113,113,.1)", border: "1px solid rgba(248,113,113,.35)", borderRadius: 14, padding: "14px 16px", fontSize: 13.5, textAlign: "center" }}>
          No order <b>#{orderId}</b> found. Double-check the number on your slip.
        </div>
      )}

      {/* Result */}
      {found && cfg && (
        <div style={{ display: isWide ? "grid" : "block", gridTemplateColumns: isWide ? "minmax(0, 460px) minmax(0, 1fr)" : undefined, gap: isWide ? 18 : 0, alignItems: "start" }}>
          {/* Hero card — photo, product, shop, status */}
          <div style={{ background: "linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02))", border: "1px solid rgba(255,255,255,.1)", borderRadius: 20, padding: isWide ? 22 : 18, boxShadow: "0 20px 50px -24px rgba(0,0,0,.8), inset 0 1px 0 rgba(255,255,255,.08)", marginBottom: isWide ? 0 : 14 }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
              <div>
                <div style={{ fontSize: 11, color: "rgba(233,238,255,.4)", fontWeight: 600, letterSpacing: ".08em", textTransform: "uppercase" }}>Order</div>
                <div style={{ fontSize: 30, fontWeight: 800, color: "#fff", lineHeight: 1, letterSpacing: ".02em", fontVariantNumeric: "tabular-nums" }}>#{found.id}</div>
              </div>
              <div style={{ background: cfg.bg, color: cfg.color, border: `1px solid ${cfg.border}`, borderRadius: 999, padding: "7px 15px", fontWeight: 700, fontSize: 13.5, display: "flex", alignItems: "center", gap: 6 }}>
                <span style={{ width: 7, height: 7, borderRadius: "50%", background: cfg.color, boxShadow: `0 0 8px ${cfg.color}` }} />
                {cfg.label}
              </div>
            </div>
            <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
              <ProductPhoto url={found.productPhotoUrl} photo={found.productPhoto} size={78} radius={14} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 16, fontWeight: 700, color: "#fff", lineHeight: 1.25 }}>{found.productName}</div>
                <div style={{ display: "flex", alignItems: "center", gap: 7, marginTop: 7, flexWrap: "wrap" }}>
                  <span style={{ fontSize: 12, fontWeight: 700, color: "#cfe0ff", background: "rgba(74,127,255,.12)", border: "1px solid rgba(74,127,255,.25)", borderRadius: 7, padding: "2px 9px" }}>Size <SizeTag size={found.size} /></span>
                  {found.qty > 1 && <span style={{ fontSize: 12, fontWeight: 700, color: "rgba(233,238,255,.6)", background: "rgba(255,255,255,.05)", border: "1px solid rgba(255,255,255,.1)", borderRadius: 7, padding: "2px 9px" }}>×{found.qty}</span>}
                </div>
              </div>
            </div>
            {/* Meta row: shop + placed time + customer */}
            <div style={{ display: "flex", flexWrap: "wrap", gap: "10px 18px", marginTop: 16, paddingTop: 14, borderTop: "1px solid rgba(255,255,255,.07)" }}>
              {shopLabel && (
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontSize: 10, color: "rgba(233,238,255,.4)", fontWeight: 600, letterSpacing: ".06em", textTransform: "uppercase", marginBottom: 3, display: "flex", alignItems: "center", gap: 5 }}>
                    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 9l1-5h16l1 5M4 9v11a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V9M3 9h18" /></svg>
                    Ordered from
                  </div>
                  <div style={{ fontSize: 14, fontWeight: 700, color: "#fff" }}>{shopLabel}</div>
                </div>
              )}
              <div style={{ minWidth: 0 }}>
                <div style={{ fontSize: 10, color: "rgba(233,238,255,.4)", fontWeight: 600, letterSpacing: ".06em", textTransform: "uppercase", marginBottom: 3 }}>Placed</div>
                <div style={{ fontSize: 14, fontWeight: 700, color: "#fff" }}>{relTime(found.createdAt) || "—"}</div>
              </div>
              {found.customerName && (
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontSize: 10, color: "rgba(233,238,255,.4)", fontWeight: 600, letterSpacing: ".06em", textTransform: "uppercase", marginBottom: 3 }}>Customer</div>
                  <div style={{ fontSize: 14, fontWeight: 700, color: "#fff", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{found.customerName}</div>
                </div>
              )}
            </div>
          </div>

          {/* Timeline */}
          <div style={{ background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 18, padding: "18px 18px 8px" }}>
            <div style={{ fontSize: 11, color: "rgba(233,238,255,.4)", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", marginBottom: 14 }}>Progress</div>
            {steps.map((st, i) => {
              const c = STEP_C[st.state];
              const last = i === steps.length - 1;
              return (
                <div key={st.label} style={{ display: "flex", gap: 14, position: "relative" }}>
                  {/* dot + connector */}
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", flexShrink: 0 }}>
                    <div style={{ width: 18, height: 18, borderRadius: "50%", background: c.dot, border: `2px solid ${c.ring === "transparent" ? "rgba(255,255,255,.14)" : c.ring}`, display: "flex", alignItems: "center", justifyContent: "center",
                                  animation: st.state === "current" ? "otPulse 1.8s infinite" : "none" }}>
                      {st.state === "done" && <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#04120a" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>}
                      {st.state === "error" && <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#1a0606" strokeWidth="4" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" /></svg>}
                    </div>
                    {!last && <div style={{ width: 2, flex: 1, minHeight: 26, background: st.state === "done" ? "rgba(74,222,128,.35)" : "rgba(255,255,255,.08)", margin: "3px 0" }} />}
                  </div>
                  {/* label + time */}
                  <div style={{ flex: 1, paddingBottom: last ? 10 : 16, marginTop: -2 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "baseline" }}>
                      <div style={{ fontSize: 14.5, fontWeight: 700, color: c.text }}>{st.label}</div>
                      {st.time && <div style={{ fontSize: 11, color: "rgba(233,238,255,.4)", whiteSpace: "nowrap", fontVariantNumeric: "tabular-nums" }}>{absTime(st.time)}</div>}
                    </div>
                    <div style={{ fontSize: 12, color: st.state === "pending" ? "rgba(233,238,255,.3)" : "rgba(233,238,255,.55)", marginTop: 2 }}>{st.sub}</div>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Search another */}
          <button onClick={reset} className="ot-press"
                  style={{ gridColumn: isWide ? "1 / -1" : undefined, width: isWide ? "auto" : "100%", justifySelf: isWide ? "start" : undefined, marginTop: 16, background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.12)", color: "rgba(233,238,255,.75)", borderRadius: 13, padding: isWide ? "12px 22px" : 14, fontSize: 14, fontWeight: 700, cursor: "pointer", fontFamily: FONT }}>
            ← Track another order
          </button>
        </div>
      )}

      {/* Recent orders (before searching) */}
      {!found && !searched && heldOrders.length > 0 && (
        <div style={{ marginTop: 26 }}>
          <div style={{ fontSize: 11, color: "rgba(233,238,255,.4)", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", marginBottom: 10 }}>Recent orders</div>
          <div style={{ display: "grid", gridTemplateColumns: isWide ? "repeat(auto-fill, minmax(320px, 1fr))" : "1fr", gap: 10 }}>
            {heldOrders.slice(0, isWide ? 12 : 5).map(o => {
              const c = STATUS_CONFIG[o.status];
              return (
                <button key={o.id} onClick={() => doSearch(o.id)} className="ot-press"
                        style={{ width: "100%", background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 14, padding: 10, cursor: "pointer", textAlign: "left", display: "flex", alignItems: "center", gap: 11, fontFamily: FONT }}>
                  <ProductPhoto url={o.productPhotoUrl} photo={o.productPhoto} size={44} radius={10} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13.5, fontWeight: 700, color: "#fff", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>#{o.id} · {o.productName}</div>
                    <div style={{ fontSize: 11.5, color: "rgba(233,238,255,.45)", marginTop: 2 }}>{o.customerName || "—"}{orderShopLabel(o) ? ` · ${orderShopLabel(o)}` : ""}</div>
                  </div>
                  {c && <span style={{ flexShrink: 0, background: c.bg, color: c.color, border: `1px solid ${c.border}`, borderRadius: 999, padding: "3px 10px", fontSize: 11, fontWeight: 700 }}>{c.label}</span>}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── TV DISPLAY VIEW ──────────────────────────────────────────────────────────
// Customer-centric layout for a 1920×1080 TV. The single thing a waiting
// customer cares about is "is my order ready to collect?" — so READY gets a
// hero card occupying ~60% of the screen with very large numbers, while the
// other three statuses share a 3-up row of compact cards below.
//
// Layout (top → bottom, all flex with min-height:0 plumbing so nothing
// overflows 100vh):
//   - Header (70px): Marathon wordmark + shoe icon, time + date
//   - Hero READY card (flex 1.6) with checkmark icon, "Ready to Collect"
//     title, total count, and a number area whose layout adapts to count:
//        0       → "No orders ready right now"
//        1 or 2  → giant centered numbers (~180px)
//        3–8     → 8-column 1-row grid (larger numbers)
//        9–36    → 12-column grid with rows depending on count
//        > 36    → paginated 36 at a time, calm fade between pages
//   - Three-up secondary row (flex 1): Incoming, Out of Stock, Coming
//     Tomorrow each in a small card with icon + title + total + 6-column
//     number grid (paginated at 18 per page).
//
// Pagination: each section rotates pages every TV_PAGE_ROTATE_MS with a
// TV_PAGE_FADE_MS opacity fade. Sections cycle independently from a shared
// pageTick.
//
// Side effects: only IN-STOCK READY orders past TV_EXPIRY_MS are auto-moved to
// COLLECTED (with restock log). OUT-OF-STOCK orders are NEVER auto-collected and
// write no restock (we only restock what we have) — they stay OOS as kept demand
// and are merely display-hidden from the customer screen past TV_EXPIRY_MS, like
// Coming Tomorrow rows past TV_COMING_TOMORROW_VISIBLE_MS (no RTDB mutation).
// Ref-Sets dedupe across multiple TV screens and prune entries on daily reset.
const TV_HERO_PAGE_SIZE             = 36;
const TV_SECONDARY_PAGE_SIZE        = 18;
const TV_PAGE_ROTATE_MS             = 120 * 1000;
const TV_PAGE_FADE_MS               = 250;
const TV_EXPIRY_MS                  = 8 * 60 * 1000;
const TV_EXPIRY_CHECK_MS            = 10 * 1000;
const TV_COMING_TOMORROW_VISIBLE_MS = 10 * 60 * 1000;
const TV_COLORS = {
  incoming:       "#6FA8FF",
  ready:          "#4ADE80",
  outOfStock:     "#F87171",
  comingTomorrow: "#FBBF24",
};
const TV_DAY_NAMES   = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
const TV_MONTH_NAMES = ["January","February","March","April","May","June","July","August","September","October","November","December"];

function DisplayView({ orders }) {
  // 1s tick — keeps the clock fresh and re-evaluates derived filters
  const [, setTick] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setTick(n => n + 1), 1000);
    return () => clearInterval(t);
  }, []);

  // Page-rotation tick — each paginated section computes its page from this
  const [pageTick, setPageTick] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setPageTick(n => n + 1), TV_PAGE_ROTATE_MS);
    return () => clearInterval(t);
  }, []);

  // Customer-facing TV clock — server-anchored so a TV with a wrong clock can't
  // display the wrong date/time to the shop floor.
  const now     = new Date(serverNowMs());
  const timeStr = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
  const dateStr = `${TV_DAY_NAMES[now.getDay()]} ${now.getDate()} ${TV_MONTH_NAMES[now.getMonth()]}`;

  // Background sweep. IN-STOCK READY past 8 min → auto-collect + restock (the real
  // "order done" event — mutates RTDB). OUT-OF-STOCK is EXCLUDED from auto-collect:
  // we only restock what we HAVE, so an OOS order gets no restock and is never
  // collected — it stays OOS (unfulfilled-demand data, already logged to insights_log
  // at mark-OOS time) and remains in the warehouse OOS tab. OOS + Coming Tomorrow are
  // only DISPLAY-hidden from the customer TV after their windows (no RTDB write).
  // Ref-Sets dedupe across multiple TV screens; stale entries pruned on daily reset.
  const expiredRef           = useRef(new Set());  // READY orders already auto-collected
  const hiddenOos            = useRef(new Set());  // OOS hidden from the TV (display-only)
  const hiddenComingTomorrow = useRef(new Set());
  useEffect(() => {
    const check = () => {
      const nowMs = serverNowMs();
      const liveIds = new Set(orders.map(o => o.id));
      // Prune refs of orders no longer present (daily counter reset, etc.)
      for (const id of expiredRef.current)           if (!liveIds.has(id)) expiredRef.current.delete(id);
      for (const id of hiddenOos.current)            if (!liveIds.has(id)) hiddenOos.current.delete(id);
      for (const id of hiddenComingTomorrow.current) if (!liveIds.has(id)) hiddenComingTomorrow.current.delete(id);

      orders.forEach(o => {
        // NOTE: DisplayView is LEGACY/unused — the DISPLAY role renders
        // <TvWithAutoCollect> (above), not this. Auto-collect was removed here too
        // so this dead path can never flip READY→COLLECTED if it's ever re-mounted.
        // Collection is confirmed only by a real POS sale; the timer is display-only.
        if (o.status === STATUS.READY && !expiredRef.current.has(o.id)) {
          const ts = o.readyAt || o.updatedAt;
          if (ts && nowMs - new Date(ts).getTime() >= TV_EXPIRY_MS) {
            expiredRef.current.add(o.id);   // display-only marker; no RTDB write
          }
        }
        // OUT-OF-STOCK → display-only hide from the customer TV (NO RTDB write; the
        // order stays OOS as kept demand). Same expiry window as Ready.
        if (o.status === STATUS.OUT_OF_STOCK && !hiddenOos.current.has(o.id)) {
          const ts = o.outOfStockAt || o.updatedAt;
          if (ts && nowMs - new Date(ts).getTime() >= TV_EXPIRY_MS) {
            hiddenOos.current.add(o.id);
          }
        }
        // Coming Tomorrow → display-only hide
        if (o.status === STATUS.COMING_TOMORROW && !hiddenComingTomorrow.current.has(o.id)) {
          const ts = o.comingTomorrowAt || o.updatedAt;
          if (ts && nowMs - new Date(ts).getTime() >= TV_COMING_TOMORROW_VISIBLE_MS) {
            hiddenComingTomorrow.current.add(o.id);
          }
        }
      });
    };
    check();
    const id = setInterval(check, TV_EXPIRY_CHECK_MS);
    return () => clearInterval(id);
  }, [orders]);

  const incoming       = orders.filter(o => o.status === STATUS.INCOMING);
  const ready          = orders.filter(o => o.status === STATUS.READY);
  const outOfStock     = orders.filter(o => o.status === STATUS.OUT_OF_STOCK && !hiddenOos.current.has(o.id));
  const comingTomorrow = orders.filter(o =>
    o.status === STATUS.COMING_TOMORROW && !hiddenComingTomorrow.current.has(o.id)
  );

  return (
    <div style={{
      height:"100vh", width:"100vw",
      background:"#0B0F1A", color:"#fff", fontFamily:FONT,
      padding:"24px", boxSizing:"border-box",
      display:"flex", flexDirection:"column", overflow:"hidden",
    }}>
      <style>{`@keyframes tvFade { from { opacity: 0 } to { opacity: 1 } }`}</style>

      {/* HEADER */}
      <div style={{ height:"70px", flexShrink:0, display:"flex", alignItems:"center", justifyContent:"space-between" }}>
        <div style={{ display:"flex", alignItems:"center", gap:"14px" }}>
          <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M2 17h13a4 4 0 003-1.4l3-3.4a2 2 0 00-1.5-3.3l-5.4-.1a2 2 0 01-1.5-.7l-1.7-2A3 3 0 008.4 5H4a2 2 0 00-2 2v10z"/>
            <line x1="2" y1="14" x2="20" y2="14"/>
          </svg>
          <span style={{ fontSize:"40px", fontWeight:700, color:"#fff", lineHeight:1 }}>Marathon</span>
        </div>
        <div style={{ textAlign:"right" }}>
          <div style={{ fontSize:"44px", fontWeight:700, color:"#fff", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{timeStr}</div>
          <div style={{ fontSize:"18px", fontWeight:400, color:"#9CA3AF", marginTop:"6px" }}>{dateStr}</div>
        </div>
      </div>

      {/* HERO READY — ~60% of remaining height */}
      <div style={{ flex:"1.6 1 0", minHeight:0, marginTop:"16px" }}>
        <HeroReadyCard orders={ready} pageTick={pageTick} />
      </div>

      {/* SECONDARY ROW — three compact cards sharing ~40% */}
      <div style={{ flex:"1 1 0", minHeight:0, marginTop:"16px", display:"flex", gap:"16px" }}>
        <SecondaryCard label="Incoming"        color={TV_COLORS.incoming}       orders={incoming}       Icon={IconShoppingBag} pageTick={pageTick} />
        <SecondaryCard label="Out of Stock"    color={TV_COLORS.outOfStock}     orders={outOfStock}     Icon={IconX}           pageTick={pageTick} />
        <SecondaryCard label="Coming Tomorrow" color={TV_COLORS.comingTomorrow} orders={comingTomorrow} Icon={IconClock}       pageTick={pageTick} />
      </div>
    </div>
  );
}

// ─── HERO READY CARD ─────────────────────────────────────────────────────────
// The dominant focal point. Title row at top; below it, a number area that
// switches layout by count to keep digits as large as possible:
//   0       → "no orders ready" muted text
//   1 or 2  → giant centered numbers (~180px)
//   3–8     → 8-column 1-row grid (very large numbers)
//   9–36    → 12-column grid (rows scale with count)
//   > 36    → paginated 36 at a time
function HeroReadyCard({ orders, pageTick }) {
  const color    = TV_COLORS.ready;
  const total    = orders.length;
  const numPages = Math.max(1, Math.ceil(total / TV_HERO_PAGE_SIZE));
  const page     = numPages === 1 ? 0 : pageTick % numPages;
  const visible  = orders.slice(page * TV_HERO_PAGE_SIZE, (page + 1) * TV_HERO_PAGE_SIZE);
  const count    = visible.length;
  // For 3–8 use a tighter 8-col grid so each number stays huge.
  const cols     = count <= 8 ? Math.min(8, count) : 12;

  const gridRef = useRef(null);
  const [cellFontSize, setCellFontSize] = useState(60);
  useEffect(() => {
    if (count <= 2) return;
    const el = gridRef.current;
    if (!el) return;
    const compute = () => {
      const w = el.clientWidth, h = el.clientHeight;
      if (!w || !h) return;
      const gap  = 16;
      const rows = Math.max(1, Math.ceil(count / cols));
      const cellW = (w - (cols - 1) * gap) / cols;
      const cellH = rows === 1 ? h : (h - (rows - 1) * gap) / rows;
      const size  = Math.max(20, Math.min(220, Math.round(Math.min(cellW * 0.5, cellH * 0.85))));
      setCellFontSize(size);
    };
    compute();
    const ro = new ResizeObserver(compute);
    ro.observe(el);
    return () => ro.disconnect();
  }, [count, cols]);

  return (
    <div style={{
      width:"100%", height:"100%",
      background:"#141A2A", borderRadius:"24px",
      padding:"32px 40px", boxSizing:"border-box",
      display:"flex", flexDirection:"column", overflow:"hidden",
      position:"relative",
    }}>
      {/* Title bar */}
      <div style={{ flexShrink:0, display:"flex", alignItems:"center", gap:"16px", marginBottom:"16px" }}>
        <div style={{ color, display:"flex" }}>
          <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="20 6 9 17 4 12"/>
          </svg>
        </div>
        <div style={{ fontSize:"34px", fontWeight:700, color, lineHeight:1 }}>Ready to Collect</div>
        <div style={{ marginLeft:"auto", display:"flex", alignItems:"baseline", gap:"10px" }}>
          <div style={{ fontSize:"14px", color:"#9CA3AF", textTransform:"uppercase", letterSpacing:"0.1em", fontWeight:600 }}>Total</div>
          <div style={{ fontSize:"44px", fontWeight:800, color, lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{total}</div>
        </div>
        {numPages > 1 && (
          <div style={{ fontSize:"14px", color:"rgba(255,255,255,.4)", fontVariantNumeric:"tabular-nums", marginLeft:"12px" }}>
            {page + 1}/{numPages}
          </div>
        )}
      </div>

      {/* Number area */}
      <div style={{ flex:"1 1 0", minHeight:0 }}>
        {count === 0 ? (
          <div style={{
            height:"100%", display:"flex", alignItems:"center", justifyContent:"center",
            color:"rgba(255,255,255,.22)", fontSize:"28px", fontWeight:400,
          }}>
            No orders ready right now
          </div>
        ) : count <= 2 ? (
          <div key={page} style={{
            height:"100%", display:"flex", alignItems:"center", justifyContent:"center", gap:"80px",
            animation:`tvFade ${TV_PAGE_FADE_MS}ms ease`,
          }}>
            {visible.map(o => (
              <div key={o.id} style={{
                fontSize:"180px", fontWeight:800, color, lineHeight:1,
                fontVariantNumeric:"tabular-nums",
              }}>{o.id}</div>
            ))}
          </div>
        ) : (
          <div key={page} ref={gridRef} style={{
            width:"100%", height:"100%",
            display:"grid",
            gridTemplateColumns:`repeat(${cols}, minmax(0, 1fr))`,
            gridAutoRows:"minmax(0, 1fr)",
            gap:"16px", overflow:"hidden",
            animation:`tvFade ${TV_PAGE_FADE_MS}ms ease`,
          }}>
            {visible.map(o => (
              <div key={o.id} style={{
                minWidth:0, minHeight:0,
                display:"flex", alignItems:"center", justifyContent:"center",
                fontSize:`${cellFontSize}px`, fontWeight:800, color, lineHeight:1,
                fontVariantNumeric:"tabular-nums", overflow:"hidden",
              }}>{o.id}</div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ─── SECONDARY STATUS CARD ───────────────────────────────────────────────────
// Compact card for Incoming / Out of Stock / Coming Tomorrow. Title bar with
// icon + label + total, then a 6-column number grid below. Pages at 18.
function SecondaryCard({ label, color, orders, Icon, pageTick }) {
  const total    = orders.length;
  const numPages = Math.max(1, Math.ceil(total / TV_SECONDARY_PAGE_SIZE));
  const page     = numPages === 1 ? 0 : pageTick % numPages;
  const visible  = orders.slice(page * TV_SECONDARY_PAGE_SIZE, (page + 1) * TV_SECONDARY_PAGE_SIZE);
  const count    = visible.length;

  const gridRef = useRef(null);
  const [cellFontSize, setCellFontSize] = useState(28);
  useEffect(() => {
    if (count === 0) return;
    const el = gridRef.current;
    if (!el) return;
    const compute = () => {
      const w = el.clientWidth, h = el.clientHeight;
      if (!w || !h) return;
      const cols = 6, gap = 10;
      const rows = Math.max(1, Math.ceil(count / cols));
      const cellW = (w - (cols - 1) * gap) / cols;
      const cellH = rows === 1 ? h : (h - (rows - 1) * gap) / rows;
      const size  = Math.max(14, Math.min(96, Math.round(Math.min(cellW * 0.45, cellH * 0.8))));
      setCellFontSize(size);
    };
    compute();
    const ro = new ResizeObserver(compute);
    ro.observe(el);
    return () => ro.disconnect();
  }, [count]);

  return (
    <div style={{
      flex:"1 1 0", minWidth:0,
      background:"#141A2A", borderRadius:"24px",
      padding:"22px 26px", boxSizing:"border-box",
      display:"flex", flexDirection:"column", overflow:"hidden",
      position:"relative",
    }}>
      {/* Title row */}
      <div style={{ flexShrink:0, display:"flex", alignItems:"center", gap:"12px", marginBottom:"14px" }}>
        <div style={{ color, display:"flex" }}>
          <Icon size={28} strokeWidth={2.6} />
        </div>
        <div style={{ fontSize:"22px", fontWeight:600, color, lineHeight:1 }}>{label}</div>
        <div style={{ marginLeft:"auto", fontSize:"32px", fontWeight:800, color, lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{total}</div>
      </div>

      {/* Number grid */}
      <div style={{ flex:"1 1 0", minHeight:0 }}>
        {count === 0 ? (
          <div style={{
            height:"100%", display:"flex", alignItems:"center", justifyContent:"center",
            color:"rgba(255,255,255,.2)", fontSize:"15px", fontWeight:400, fontStyle:"italic",
          }}>
            none
          </div>
        ) : (
          <div key={page} ref={gridRef} style={{
            width:"100%", height:"100%",
            display:"grid",
            gridTemplateColumns:"repeat(6, minmax(0, 1fr))",
            gridAutoRows:"minmax(0, 1fr)",
            gap:"10px", overflow:"hidden",
            animation:`tvFade ${TV_PAGE_FADE_MS}ms ease`,
          }}>
            {visible.map(o => (
              <div key={o.id} style={{
                minWidth:0, minHeight:0,
                display:"flex", alignItems:"center", justifyContent:"center",
                fontSize:`${cellFontSize}px`, fontWeight:700, color, lineHeight:1,
                fontVariantNumeric:"tabular-nums", overflow:"hidden",
              }}>{o.id}</div>
            ))}
          </div>
        )}
      </div>

      {/* Page indicator */}
      {numPages > 1 && (
        <div style={{
          position:"absolute", bottom:"10px", right:"18px",
          fontSize:"11px", color:"rgba(255,255,255,.3)",
          fontVariantNumeric:"tabular-nums", letterSpacing:"0.04em",
        }}>
          {page + 1}/{numPages}
        </div>
      )}
    </div>
  );
}

// ── TV display icons. Configurable size + strokeWidth; inherit accent via
//    currentColor on the parent. Used by both the hero (inline 40px check)
//    and the secondary cards (28px stroke 2.6) ──────────────────────────────
function IconShoppingBag({ size = 28, strokeWidth = 2.6 }) {
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
    <path d="M6 2L3 6v14a2 2 0 002 2h14a2 2 0 002-2V6l-3-4z"/>
    <line x1="3" y1="6" x2="21" y2="6"/>
    <path d="M16 10a4 4 0 01-8 0"/>
  </svg>;
}
function IconCheck({ size = 28, strokeWidth = 2.6 }) {
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
    <polyline points="20 6 9 17 4 12"/>
  </svg>;
}
function IconX({ size = 28, strokeWidth = 2.6 }) {
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
    <line x1="18" y1="6" x2="6" y2="18"/>
    <line x1="6" y1="6" x2="18" y2="18"/>
  </svg>;
}
function IconClock({ size = 28, strokeWidth = 2.6 }) {
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10"/>
    <polyline points="12 6 12 12 16 14"/>
  </svg>;
}

// ─── SOURCE VIEW + COMPONENTS ────────────────────────────────────────────────
//
// HUB-SCOPED SOURCE FLOW
// ----------------------
// SourceView owns the active hub (hub1/hub2). It pre-filters orders by hub
// before computing rawCounts, so each tab component renders only its hub's
// items and never sees the other hub's data. React keys include the hub
// prefix to keep DOM nodes from colliding even when SourceView re-renders
// at a moment React reconciles tabs in the wrong order. Product-name
// collisions (e.g. "Air Max 90" vs "Air.Max.90" → "Air_Max_90") are
// detected in computeCollectedCounts and warned to console once each.
//
// "Available" and "Out of Stock" responses live at:
//   restock_requests/{date}/{productKey}/{size} = { response, respondedOn }
// Today's active list filters those cells OUT. The Completed toggle reveals
// them with green/red indicators and an Undo button (clearSourceResponse).

// Inline pill toggle used by Today / On Hold to reveal completed items.
function CompletedTogglePill({ on, count, onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        display:"flex", alignItems:"center", gap:6,
        padding:"7px 11px",
        borderRadius:999,
        border: on ? "1px solid rgba(60,110,255,.5)" : "1px solid rgba(255,255,255,.1)",
        background: on ? "rgba(60,110,255,.12)" : "rgba(255,255,255,.03)",
        color: on ? BLUE_L : "rgba(255,255,255,.55)",
        fontWeight:600, fontSize:12, cursor:"pointer",
        marginBottom:12,
      }}>
      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        {on
          ? <><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></>
          : <><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></>}
      </svg>
      {on ? "Hide" : "Show"} Completed ({count})
    </button>
  );
}

// rawCounts  = { productKey: { productName, photo, photoUrl, sizes: { size: count } } }
// responses  = { productKey: { size: { response, respondedOn } } }  — live from Firebase
// hub        = "hub1" | "hub2"  — used only for keying/labels; data is already filtered upstream.
function SourceTodayTab({ rawCounts, responses, date, hub, onResponse, onUndo, wide = false, fulfilCtx, progress, onFulfilProgress }) {
  // Desktop lays the pending / completed cells in a responsive grid so the wide
  // pane isn't a single stretched column; mobile stays a vertical stack.
  const listStyle = wide
    ? { display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(300px, 1fr))", gap:12, alignItems:"start" }
    : { display:"flex", flexDirection:"column", gap:10 };
  // Per-hub toggle — each hub remembers whether its completed list is open.
  const [showCompletedByHub, setShowCompletedByHub] = useState({ hub1: false, hub2: false });
  const showCompleted = !!showCompletedByHub[hub];
  const setShowCompleted = (next) => setShowCompletedByHub(prev => ({
    ...prev,
    [hub]: typeof next === "function" ? next(!!prev[hub]) : next,
  }));

  // Build flat cell lists. Sort by product name then numeric size for stable
  // ordering — keeps cards from jumping when responses flow in.
  const { pending, completed, totalUnits, totalProducts } = useMemo(() => {
    const pending = [];
    const completed = [];
    let totalUnits = 0;
    const productsSeen = new Set();
    Object.entries(rawCounts)
      .sort(([, a], [, b]) => a.productName.localeCompare(b.productName))
      .forEach(([key, product]) => {
        const sizes = Object.keys(product.sizes || {}).sort((a, b) => Number(a) - Number(b));
        sizes.forEach(size => {
          const count = typeof product.sizes[size] === "number" ? product.sizes[size] : 1;
          totalUnits += count;
          productsSeen.add(key);
          const resp = responses[key]?.[size]?.response;
          const cell = { key, product, size, count };
          if (resp) completed.push({ ...cell, response: resp });
          else pending.push(cell);
        });
      });
    return { pending, completed, totalUnits, totalProducts: productsSeen.size };
  }, [rawCounts, responses]);

  // True empty state — nothing came in today at all.
  if (!pending.length && !completed.length) return (
    <div style={{ textAlign:"center", color:"#444", padding:"4rem" }}>
      <ProductIcon size={32} opacity={0.5}/>
      <div style={{ fontSize:"1rem", marginTop:"0.75rem" }}>No restock requests for this hub yet.</div>
      <div style={{ fontSize:"0.85rem", color:"#333", marginTop:"0.5rem" }}>Items collected by customers appear here for restocking.</div>
    </div>
  );

  const pendingUnits = pending.reduce((n, c) => n + c.count, 0);

  return (
    <div>
      {/* Summary headline — pending units, falls to "all done" tone when zero */}
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(74,127,255,.35)", borderRadius:16, padding:"14px 16px", marginBottom:14, display:"flex", alignItems:"center", gap:14, boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
        <div style={{ fontWeight:800, fontSize:36, color:"#4A7FFF", lineHeight:1, letterSpacing:"-1px" }}>{pendingUnits}</div>
        <div style={{ flex:1 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Refill Pending</div>
          <div style={{ color:"rgba(255,255,255,.5)", fontSize:11, marginTop:3, lineHeight:1.4 }}>
            {totalUnits} item{totalUnits !== 1 ? "s" : ""} sold today · {totalProducts} product{totalProducts !== 1 ? "s" : ""} · {date}
          </div>
        </div>
      </div>

      {/* Show / Hide Completed toggle (session state) */}
      {completed.length > 0 && (
        <CompletedTogglePill on={showCompleted} count={completed.length} onClick={() => setShowCompleted(v => !v)} />
      )}

      {/* Empty-active-but-completed state */}
      {pending.length === 0 && completed.length > 0 && !showCompleted && (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(74,222,128,.4)", borderRadius:16, padding:"22px 18px", textAlign:"center", boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
          <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="#4ADE80" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ filter:"drop-shadow(0 0 6px rgba(74,222,128,.35))" }}>
            <circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/>
          </svg>
          <div style={{ color:"#fff", fontSize:14, fontWeight:700, marginTop:10 }}>All caught up</div>
          <div style={{ color:"rgba(255,255,255,.55)", fontSize:12, marginTop:4 }}>{completed.length} item{completed.length !== 1 ? "s" : ""} completed in this hub.</div>
          <button onClick={() => setShowCompleted(true)}
                  style={{ marginTop:14, padding:"8px 16px", borderRadius:10, border:"1px solid rgba(60,110,255,.5)", background:"rgba(60,110,255,.12)", color:BLUE_L, fontWeight:600, fontSize:12, cursor:"pointer" }}>
            Show Completed
          </button>
        </div>
      )}

      {/* Active list — pending cells only. Cards vanish on response. */}
      <div style={listStyle}>
        {pending.map(cell => (
          <PendingCard
            key={`${hub}-${cell.key}-${cell.size}`}
            product={cell.product}
            size={cell.size}
            count={cell.count}
            fulfil={fulfilCtx ? {
              enabled: fulfilCtx.canTransfer,
              productId: fulfilCtx.resolveId(cell.product),
              destHub: hub,
              sent: progress?.[cell.key]?.[cell.size]?.fulfilledQty || 0,
              movementIdSeed: `srcful_${date}_${cell.key}_${encodeSizeKey(cell.size)}`,
              locationsReg: fulfilCtx.locationsReg,
              actorRole: fulfilCtx.actorRole,
              onProgress: (newSent, complete, meta) => onFulfilProgress(date, cell.key, cell.size, newSent, complete, meta),
            } : null}
            onAvailable={() => onResponse(cell.key, cell.size, "available")}
            onOutOfStock={() => onResponse(cell.key, cell.size, "out_of_stock")}
          />
        ))}
      </div>

      {/* Completed list — revealed by toggle */}
      {showCompleted && completed.length > 0 && (
        <>
          <div style={{ marginTop:18, marginBottom:10, display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ height:1, flex:1, background:"rgba(255,255,255,.06)" }} />
            <div style={{ fontSize:10, fontWeight:700, color:"rgba(255,255,255,.4)", letterSpacing:"1.2px" }}>COMPLETED</div>
            <div style={{ height:1, flex:1, background:"rgba(255,255,255,.06)" }} />
          </div>
          <div style={listStyle}>
            {completed.map(cell => (
              <CompletedCard
                key={`${hub}-done-${cell.key}-${cell.size}`}
                product={cell.product}
                size={cell.size}
                count={cell.count}
                response={cell.response}
                onUndo={() => onUndo(cell.key, cell.size)}
              />
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// ─── SOURCE: TRANSFER & FULFIL ────────────────────────────────────────────────
// Source is the inventory transfer engine (owner redesign 2026-07-13): fulfilling
// a refill card MOVES REAL STOCK. The runner picks the supply location, picks the
// quantity, and "Transfer & Fulfil" fires ONE applyMovement from that location to
// the requesting hub — no manual inventory adjustment afterwards, ever.
//
// Mechanics, all reusing established precedents:
//   • Counted source cell → `transfer_out` source→hub with allowNegative:true —
//     the parcel physically leaves whether or not the count is right, and a
//     resulting negative is the same honest shortage signal a dispatch leaves
//     (A1 rule in applyMovement).
//   • Source cell that has never been counted (absent) → `received` into the hub
//     only, reason source_uncounted_send — the CR-uncounted precedent (#191-193):
//     the hub gains real stock, nothing phantom is deducted.
//   • Idempotency: movementId = {seed}_{unitsAlreadySent}. A double-tap resolves
//     to the same id and applyMovement no-ops; the next partial gets a fresh id.
//   • Partial fulfilment: fewer units than requested leaves the cell OPEN with a
//     "n of m sent" badge (progress leaf, see saveSourceFulfilProgress); the
//     response record only closes it when the last unit ships.
//   • Users without a stockRole (can't write /stock) and legacy cards with no
//     resolvable productId keep the original plain buttons — nothing breaks.
const SOURCE_REFILL_REASON    = "source_refill";
const SOURCE_UNCOUNTED_REASON = "source_uncounted_send";
const SOURCE_TRANSFER_ROLES   = ["store", "warehouse", "admin"];

// Inline expandable panel: supply-location chips (with live counted qty), a qty
// stepper when more than one unit is open, and the Transfer & Fulfil confirm.
function SourceFulfilPanel({ productId, size, destHub, remaining, alreadySent, movementIdSeed, locationsReg, actorRole, onDone, onCancel, onWithoutTransfer }) {
  const [avail, setAvail] = useState(null);   // { locId: qty | null } — null = never counted there
  const [pick, setPick]   = useState(null);
  const [qty, setQty]     = useState(Math.max(1, remaining));
  const [busy, setBusy]   = useState(false);
  const [err, setErr]     = useState(null);

  const sources = useMemo(
    () => warehouseLocations(locationsReg).filter(l => l.id !== destHub),
    [locationsReg, destHub]
  );

  // One targeted read per warehouse for THIS product+size — cheap on phones,
  // no /stock-wide listener. Best-stocked location is pre-selected.
  useEffect(() => {
    let dead = false;
    (async () => {
      const out = {};
      for (const l of sources) {
        try {
          const snap = await get(ref(database, stockCellPath(l.id, productId, size)));
          const cell = snap.val();
          out[l.id] = cell && typeof cell.qty === "number" ? cell.qty : null;
        } catch { out[l.id] = null; }
      }
      if (dead) return;
      setAvail(out);
      setPick(p => {
        if (p) return p;
        const best = sources.slice().sort((a, b) => (out[b.id] ?? -1) - (out[a.id] ?? -1))[0];
        return best ? best.id : null;
      });
    })();
    return () => { dead = true; };
  }, [productId, size, destHub, sources]);

  const doTransfer = async () => {
    if (!pick || busy) return;
    setBusy(true); setErr(null);
    const counted = !!avail && typeof avail[pick] === "number";
    const q = Math.max(1, Math.min(Math.round(qty) || 1, remaining));
    const mvId = `${movementIdSeed}_${alreadySent}`;
    let res;
    try {
      res = await applyMovement(counted ? {
        type: "transfer_out", productId, size, qty: q,
        from: pick, to: destHub, actorRole,
        allowNegative: true,
        reason: SOURCE_REFILL_REASON,
        movementId: mvId, link: { refillId: movementIdSeed },
      } : {
        type: "received", productId, size, qty: q,
        to: destHub, actorRole,
        reason: SOURCE_UNCOUNTED_REASON,
        movementId: mvId, link: { refillId: movementIdSeed },
      });
    } catch (e) { res = { ok: false, reason: String(e?.message || e) }; }
    setBusy(false);
    if (res.ok) onDone(q, pick, counted);
    else setErr(`Transfer failed: ${res.reason || "unknown"}. Check your stock access and retry.`);
  };

  const chip = (l) => {
    const q = avail ? avail[l.id] : undefined;
    const active = pick === l.id;
    return (
      <button key={l.id} onClick={() => setPick(l.id)} disabled={busy}
              style={{ display:"flex", alignItems:"center", gap:6, padding:"7px 10px", borderRadius:10,
                       border: active ? "1px solid rgba(60,110,255,.7)" : "1px solid rgba(255,255,255,.1)",
                       background: active ? "rgba(60,110,255,.16)" : "rgba(255,255,255,.03)",
                       color: active ? "#6A9FFF" : "rgba(255,255,255,.65)", fontWeight:700, fontSize:11, cursor:"pointer" }}>
        {l.label || labelFor(l.id, locationsReg)}
        <span style={{ fontSize:10, fontWeight:600, color: q == null ? "rgba(255,255,255,.35)" : (q > 0 ? "#4ADE80" : "#F87171") }}>
          {avail == null ? "…" : (q == null ? "uncounted" : q)}
        </span>
      </button>
    );
  };

  const pickedUncounted = !!pick && !!avail && avail[pick] == null;
  return (
    <div style={{ marginTop:10, borderTop:"1px solid rgba(60,110,255,.15)", paddingTop:10 }}>
      <div style={{ fontSize:10, fontWeight:700, letterSpacing:".8px", color:"rgba(255,255,255,.45)", marginBottom:7 }}>SUPPLY FROM</div>
      <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:10 }}>{sources.map(chip)}</div>
      {pickedUncounted && (
        <div style={{ fontSize:10, color:"rgba(255,255,255,.4)", marginBottom:8 }}>
          Not counted at {labelFor(pick, locationsReg)} — units will be added to {labelFor(destHub, locationsReg)} only.
        </div>
      )}
      {remaining > 1 && (
        <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:10 }}>
          <span style={{ fontSize:11, color:"rgba(255,255,255,.55)", fontWeight:600 }}>Quantity</span>
          <button onClick={() => setQty(v => Math.max(1, v - 1))} disabled={busy}
                  style={{ width:30, height:30, borderRadius:8, border:"1px solid rgba(255,255,255,.14)", background:"rgba(255,255,255,.04)", color:"#fff", fontWeight:800, cursor:"pointer" }}>−</button>
          <span style={{ minWidth:24, textAlign:"center", fontWeight:800, color:"#fff", fontSize:15 }}>{Math.max(1, Math.min(qty, remaining))}</span>
          <button onClick={() => setQty(v => Math.min(remaining, v + 1))} disabled={busy}
                  style={{ width:30, height:30, borderRadius:8, border:"1px solid rgba(255,255,255,.14)", background:"rgba(255,255,255,.04)", color:"#fff", fontWeight:800, cursor:"pointer" }}>+</button>
          <span style={{ fontSize:10, color:"rgba(255,255,255,.35)" }}>of {remaining} open</span>
        </div>
      )}
      {err && <div style={{ fontSize:11, color:"#F87171", marginBottom:8 }}>{err}</div>}
      <div style={{ display:"flex", gap:8 }}>
        <button onClick={doTransfer} disabled={busy || !pick}
                style={{ flex:1, padding:"10px 12px", borderRadius:10, border:"1px solid rgba(74,222,128,.5)", background:"rgba(74,222,128,.12)", color:"#4ADE80", fontWeight:700, fontSize:12, cursor: busy ? "default" : "pointer", opacity: busy ? 0.6 : 1 }}>
          {busy ? "Transferring…" : "Transfer & Fulfil"}
        </button>
        <button onClick={onCancel} disabled={busy}
                style={{ padding:"10px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.12)", background:"rgba(255,255,255,.03)", color:"rgba(255,255,255,.6)", fontWeight:600, fontSize:12, cursor:"pointer" }}>
          Cancel
        </button>
      </div>
      {onWithoutTransfer && (
        <button onClick={onWithoutTransfer} disabled={busy}
                style={{ marginTop:8, width:"100%", padding:"7px", borderRadius:8, border:"none", background:"transparent", color:"rgba(255,255,255,.35)", fontSize:10, fontWeight:600, cursor:"pointer", textDecoration:"underline" }}>
          Complete without stock transfer
        </button>
      )}
    </div>
  );
}

// Single pending (product, size) cell. With transfer access + a resolvable
// productId, the primary action is Fulfil → SourceFulfilPanel (real stock
// movement); otherwise the original Available button. Out of Stock unchanged.
// Local pending state suppresses double-taps while Firebase echoes the write back.
function PendingCard({ product, size, count, onAvailable, onOutOfStock, fulfil, subtitle }) {
  const [busy, setBusy] = useState(false);
  const [open, setOpen] = useState(false);
  const tap = (fn) => {
    if (busy) return;
    setBusy(true);
    fn();
    // Card will unmount when responses echo back; this is the belt-and-braces
    // guard for the tiny window between tap and Firebase round-trip.
    setTimeout(() => setBusy(false), 1500);
  };
  const sent = fulfil?.sent || 0;
  const remaining = Math.max(1, count - sent);
  const canFulfil = !!(fulfil && fulfil.enabled && fulfil.productId);
  return (
    <div style={{
      background:"rgba(4,5,10,1)",
      border:"1px solid rgba(60,110,255,.6)",
      borderRadius:14,
      padding:14,
      boxShadow:"0 0 10px rgba(60,110,255,.15)",
      opacity: busy ? 0.7 : 1,
      transition:"opacity 120ms ease",
    }}>
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:12 }}>
        <ProductPhoto url={product.photoUrl} photo={product.photo} size={48} radius={10}/>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>{product.productName}</div>
          {subtitle && <div style={{ color:"rgba(255,255,255,.4)", fontSize:10, marginTop:2 }}>{subtitle}</div>}
        </div>
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:10, flexWrap:"wrap" }}>
        <div style={{ display:"inline-flex", alignItems:"center", gap:8, background:"rgba(60,110,255,.1)", border:"1px solid rgba(60,110,255,.25)", borderRadius:8, padding:"6px 10px" }}>
          <span style={{ fontSize:13, fontWeight:700, color:"#fff" }}>Size <SizeTag size={size} /></span>
          {count > 1 && <span style={{ fontSize:10, color:"#4A7FFF", fontWeight:600 }}>×{count}</span>}
        </div>
        {sent > 0 && (
          <span style={{ fontSize:10, fontWeight:700, color:"#4ADE80", background:"rgba(74,222,128,.1)", border:"1px solid rgba(74,222,128,.3)", borderRadius:999, padding:"3px 9px" }}>
            {sent} of {count} sent
          </span>
        )}
      </div>
      <div style={{ display:"flex", gap:8 }}>
        {canFulfil ? (
          <button disabled={busy} onClick={() => setOpen(v => !v)}
                  style={{ flex:1, padding:"10px 12px", borderRadius:10, border: open ? "1px solid rgba(74,222,128,.5)" : "1px solid rgba(255,255,255,.1)", background: open ? "rgba(74,222,128,.08)" : "rgba(255,255,255,.03)", color: open ? "#4ADE80" : "rgba(255,255,255,.7)", cursor: busy ? "default" : "pointer", fontWeight:600, fontSize:12, display:"flex", alignItems:"center", justifyContent:"center", gap:5 }}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="5 12 3 12 12 3 21 12 19 12"/><path d="M5 12v7a2 2 0 002 2h10a2 2 0 002-2v-7"/></svg>
            Fulfil
          </button>
        ) : (
          <button disabled={busy} onClick={() => tap(onAvailable)}
                  style={{ flex:1, padding:"10px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.1)", background:"rgba(255,255,255,.03)", color:"rgba(255,255,255,.7)", cursor: busy ? "default" : "pointer", fontWeight:600, fontSize:12, display:"flex", alignItems:"center", justifyContent:"center", gap:5 }}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><polyline points="20 6 9 17 4 12"/></svg>
            Available
          </button>
        )}
        <button disabled={busy} onClick={() => tap(onOutOfStock)}
                style={{ flex:1, padding:"10px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.1)", background:"rgba(255,255,255,.03)", color:"rgba(255,255,255,.7)", cursor: busy ? "default" : "pointer", fontWeight:600, fontSize:12, display:"flex", alignItems:"center", justifyContent:"center", gap:5 }}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          Out of Stock
        </button>
      </div>
      {canFulfil && open && (
        <SourceFulfilPanel
          productId={fulfil.productId}
          size={size}
          destHub={fulfil.destHub}
          remaining={remaining}
          alreadySent={sent}
          movementIdSeed={fulfil.movementIdSeed}
          locationsReg={fulfil.locationsReg}
          actorRole={fulfil.actorRole}
          onDone={(q, from, counted) => {
            setOpen(false);
            fulfil.onProgress(sent + q, sent + q >= count, { lastFrom: from, counted });
          }}
          onCancel={() => setOpen(false)}
          onWithoutTransfer={() => { setOpen(false); tap(onAvailable); }}
        />
      )}
    </div>
  );
}

// Single completed cell — colored indicator + Undo.
function CompletedCard({ product, size, count, response, onUndo }) {
  const isAvail = response === "available";
  const accent  = isAvail ? "rgba(74,222,128,.5)"  : "rgba(248,113,113,.5)";
  const tint    = isAvail ? "rgba(74,222,128,.08)" : "rgba(248,113,113,.08)";
  const text    = isAvail ? "#4ADE80"              : "#F87171";
  return (
    <div style={{
      background:"rgba(4,5,10,1)",
      border:`1px solid ${accent}`,
      borderLeft:`3px solid ${accent}`,
      borderRadius:14, padding:14,
      opacity:0.85,
    }}>
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:10 }}>
        <ProductPhoto url={product.photoUrl} photo={product.photo} size={48} radius={10}/>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>{product.productName}</div>
          <div style={{ display:"inline-flex", alignItems:"center", gap:5, marginTop:4, padding:"2px 8px", borderRadius:999, background:tint, border:`1px solid ${accent}`, color:text, fontSize:10, fontWeight:700, letterSpacing:".5px", textTransform:"uppercase" }}>
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round">
              {isAvail ? <polyline points="20 6 9 17 4 12"/> : <><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></>}
            </svg>
            {isAvail ? "Available" : "Out of Stock"}
          </div>
        </div>
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:10 }}>
        <div style={{ display:"inline-flex", alignItems:"center", gap:8, background:"rgba(60,110,255,.08)", border:"1px solid rgba(60,110,255,.2)", borderRadius:8, padding:"5px 10px" }}>
          <span style={{ fontSize:12, fontWeight:700, color:"rgba(255,255,255,.7)" }}>Size <SizeTag size={size} /></span>
          {count > 1 && <span style={{ fontSize:10, color:BLUE, fontWeight:600 }}>×{count}</span>}
        </div>
        <div style={{ flex:1 }} />
        <button onClick={onUndo}
                style={{ padding:"7px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.12)", background:"rgba(255,255,255,.04)", color:"rgba(255,255,255,.7)", fontWeight:600, fontSize:11, cursor:"pointer", display:"flex", alignItems:"center", gap:5 }}>
          <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/>
          </svg>
          Undo
        </button>
      </div>
    </div>
  );
}

// Returns YYYY-MM-DD for `daysAgo` days before today in SA time.
function getSAPastDateString(daysAgo) {
  const t = serverNowMs() + 2 * 60 * 60 * 1000 - daysAgo * 24 * 60 * 60 * 1000;
  return new Date(t).toISOString().slice(0, 10);
}

const HISTORY_DAY_LABELS = { 1: "YESTERDAY", 2: "2 DAYS AGO", 3: "3 DAYS AGO", 4: "4 DAYS AGO", 5: "5 DAYS AGO" };
const HISTORY_RETENTION_DAYS = 5;

// History tab shows pending stragglers from the past 1–5 days (excluding today,
// which is shown on Today's Request). A "straggler" = a (productKey, size) cell
// whose order was ready/collected on day-N, not OOS, not returned-on-day-N, and
// for which restock_requests/{day-N}/{key}/{size} has no response yet.
//
// Reactions write to restock_requests/{day-N}/{key}/{size} = { response, respondedOn:NOW }
// — see saveSourceResponse. The original-day path is what makes resolution
// stick across page loads; respondedOn carries "today's stamp" for the audit.
function SourceHistoryTab({ log, returnsLog, allResponses, hub, photoForName, onResponse, fulfilCtx, fulfilProgress, onFulfilProgress }) {
  // Default expand: yesterday open, older closed. Stored by daysAgo number.
  const [openDays, setOpenDays] = useState(() => new Set([1]));
  const toggle = (d) => setOpenDays(prev => {
    const next = new Set(prev);
    next.has(d) ? next.delete(d) : next.add(d);
    return next;
  });

  // Per past day: rebuild the rawCounts shape SourceTodayTab uses from the
  // durable insights_log (action="ready") instead of live /orders — the live
  // orders that carried these requests were overwritten by the daily orderNumber
  // rollover. Then strip (key, size) cells that already have a response that day.
  // Photos aren't in the log, so join them from the catalog by product name.
  const groups = useMemo(() => {
    return Array.from({ length: HISTORY_RETENTION_DAYS }, (_, i) => i + 1).map(daysAgo => {
      const dateStr   = getSAPastDateString(daysAgo);
      const returned  = returnedOrderIdsOnSADate(returnsLog, dateStr);
      const rawCounts = restockCountsFromLog({ log, dateStr, hub, returnedIds: returned });
      const dayResponses = allResponses[dateStr] || {};
      // Drop responded (key, size) cells; drop products that end up with no pending sizes.
      const pending = {};
      let pendingUnits = 0;
      Object.entries(rawCounts).forEach(([key, product]) => {
        const sizes = {};
        Object.entries(product.sizes || {}).forEach(([size, count]) => {
          if (dayResponses[key]?.[size]) return;
          sizes[size] = count;
          pendingUnits += (typeof count === "number" ? count : 1);
        });
        if (Object.keys(sizes).length) {
          const ph = photoForName(product.productName);
          pending[key] = { ...product, sizes, photoUrl: ph.photoUrl, photo: ph.photo };
        }
      });
      return { daysAgo, dateStr, label: HISTORY_DAY_LABELS[daysAgo], pending, pendingUnits };
    }).filter(g => g.pendingUnits > 0);
  }, [log, returnsLog, allResponses, hub, photoForName]);

  if (!groups.length) return (
    <div style={{ background:"rgba(4,5,10,1)", border:"1px solid rgba(60,110,255,.3)", borderRadius:14, padding:"3rem 1.5rem", textAlign:"center", boxShadow:"0 0 16px rgba(60,110,255,.08)" }}>
      <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#4ADE80" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ filter:"drop-shadow(0 0 8px rgba(74,222,128,.4))" }}>
        <circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/>
      </svg>
      <div style={{ color:"#fff", fontSize:14, fontWeight:600, marginTop:12 }}>Nothing pending for this hub. You're caught up.</div>
    </div>
  );

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
      {groups.map(g => {
        const isOpen = openDays.has(g.daysAgo);
        return (
          <div key={g.daysAgo} style={{ background:"rgba(4,5,10,1)", border:"1px solid rgba(60,110,255,.3)", borderRadius:14, overflow:"hidden" }}>
            {/* Header bar */}
            <div onClick={() => toggle(g.daysAgo)}
                 style={{ display:"flex", alignItems:"center", padding:"14px 16px", cursor:"pointer", gap:12 }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink:0 }}>
                <circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>
              </svg>
              <div style={{ flex:1, fontWeight:700, fontSize:12, letterSpacing:"1.2px", color:"#fff" }}>{g.label}</div>
              <div style={{ background:"rgba(60,110,255,.15)", color:"#4A7FFF", border:"1px solid rgba(60,110,255,.3)", borderRadius:999, padding:"3px 10px", fontSize:11, fontWeight:700 }}>
                {g.pendingUnits} pending
              </div>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"
                   style={{ transition:"transform 150ms ease", transform: isOpen ? "rotate(180deg)" : "rotate(0deg)", flexShrink:0 }}>
                <polyline points="6 9 12 15 18 9"/>
              </svg>
            </div>
            {/* Animated body */}
            <div style={{ maxHeight: isOpen ? 5000 : 0, overflow:"hidden", transition:"max-height 150ms ease" }}>
              <div style={{ borderTop:"1px solid rgba(60,110,255,.1)", padding:"12px 14px", display:"flex", flexDirection:"column", gap:10 }}>
                {Object.entries(g.pending).flatMap(([key, product]) => {
                  const sizes = Object.keys(product.sizes).sort((a, b) => Number(a) - Number(b));
                  return sizes.map(size => {
                    const count = typeof product.sizes[size] === "number" ? product.sizes[size] : 1;
                    return (
                      <PendingCard
                        key={`${hub}-${g.daysAgo}-${key}-${size}`}
                        product={product}
                        size={size}
                        count={count}
                        subtitle={`Requested ${g.daysAgo === 1 ? "yesterday" : `${g.daysAgo} days ago`}`}
                        fulfil={fulfilCtx ? {
                          enabled: fulfilCtx.canTransfer,
                          productId: fulfilCtx.resolveId(product),
                          destHub: hub,
                          sent: fulfilProgress?.[g.dateStr]?.[key]?.[size]?.fulfilledQty || 0,
                          movementIdSeed: `srcful_${g.dateStr}_${key}_${encodeSizeKey(size)}`,
                          locationsReg: fulfilCtx.locationsReg,
                          actorRole: fulfilCtx.actorRole,
                          onProgress: (newSent, complete, meta) => onFulfilProgress(g.dateStr, key, size, newSent, complete, meta),
                        } : null}
                        onAvailable={() => onResponse(g.dateStr, key, size, "available")}
                        onOutOfStock={() => onResponse(g.dateStr, key, size, "out_of_stock")}
                      />
                    );
                  });
                })}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ─── SOURCE: ON HOLD TAB ─────────────────────────────────────────────────────
// Tracks per-order responses at source_onhold_responses/{key}. Cards vanish
// when responded; the Completed toggle reveals them with green/red indicators
// and Undo removes the response so the order returns to the active list.
function SourceOnHoldTab({ items, fulfilCtx }) {
  const [showCompleted, setShowCompleted] = useState(false);
  // Composite key of the card whose Transfer & Fulfil panel is open (one at a time).
  const [openComposite, setOpenComposite] = useState(null);

  // `items` is the shared merged on-hold list (live today + durable log for past
  // days), already newest-first, returned-excluded, with a `responded` flag and
  // the raw `response` record attached. Split into active vs completed here.
  const { pending, completed } = useMemo(() => {
    const pending = [];
    const completed = [];
    (items || []).forEach(item => {
      if (item.responded && item.response?.response) completed.push(item);
      else pending.push(item);
    });
    return { pending, completed };
  }, [items]);

  // Responses are keyed by the composite date::orderNumber (item.composite) —
  // orderNumber alone is daily-reused, so a bare key let a past day's handled
  // order mask a fresh same-numbered one.
  const handleRespond = (item, response) => {
    set(ref(database, `source_onhold_responses/${item.composite}`), {
      orderNumber: item.orderNumber,
      saDate: item.saDate,
      productName: item.productName,
      size: item.size,
      customerName: item.customerName || null,
      response,
      timestamp: serverNowIso(),
    }).catch(err => console.warn("saveOnHoldResponse failed:", err));
  };

  const handleUndo = (item) => {
    remove(ref(database, `source_onhold_responses/${item.composite}`))
      .catch(err => console.warn("clearOnHoldResponse failed:", err));
  };

  const fmt = iso => iso ? new Date(iso).toLocaleString([], { day:"numeric", month:"short", hour:"2-digit", minute:"2-digit" }) : "—";

  // True empty — nothing on hold anywhere, completed or otherwise.
  if (!pending.length && !completed.length) return (
    <div style={{ textAlign:"center", color:"#444", padding:"4rem" }}>
      <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeOpacity="0.4" strokeWidth="1.5" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
      <div style={{ fontSize:"1rem", marginTop:"0.75rem" }}>No orders on hold.</div>
      <div style={{ fontSize:"0.85rem", color:"#333", marginTop:"0.5rem" }}>Orders marked "Coming Tomorrow" appear here in real time.</div>
    </div>
  );

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:"0.85rem" }}>
      {/* Instruction note */}
      <div style={{ background:CARD, border:BORDER_BRIGHT, borderRadius:RADIUS, padding:"0.75rem 1rem", color:BLUE_L, fontSize:"0.82rem", boxShadow:"0 0 12px rgba(60,110,255,.12)" }}>
        Tap <strong>Sent</strong> or <strong>Out of Stock</strong> to confirm each order
      </div>
      <div style={{ color:"#555", fontSize:"0.82rem" }}>
        {pending.length} order{pending.length !== 1 ? "s" : ""} waiting for next-day stock
      </div>

      {/* Show / Hide Completed toggle (session state) */}
      {completed.length > 0 && (
        <CompletedTogglePill on={showCompleted} count={completed.length} onClick={() => setShowCompleted(v => !v)} />
      )}

      {/* Empty-active-but-completed state */}
      {pending.length === 0 && completed.length > 0 && !showCompleted && (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(74,222,128,.4)", borderRadius:16, padding:"22px 18px", textAlign:"center", boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
          <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="#4ADE80" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ filter:"drop-shadow(0 0 6px rgba(74,222,128,.35))" }}>
            <circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/>
          </svg>
          <div style={{ color:"#fff", fontSize:14, fontWeight:700, marginTop:10 }}>All caught up</div>
          <div style={{ color:"rgba(255,255,255,.55)", fontSize:12, marginTop:4 }}>{completed.length} order{completed.length !== 1 ? "s" : ""} completed.</div>
          <button onClick={() => setShowCompleted(true)}
                  style={{ marginTop:14, padding:"8px 16px", borderRadius:10, border:"1px solid rgba(60,110,255,.5)", background:"rgba(60,110,255,.12)", color:BLUE_L, fontWeight:600, fontSize:12, cursor:"pointer" }}>
            Show Completed
          </button>
        </div>
      )}

      {/* Active list. Customer info, collection date and the "sent" response
          record are untouched by the transfer redesign — with transfer access
          the Sent button becomes Fulfil (real stock movement to the order's
          hub, then the exact same response write); without it, plain Sent. */}
      {pending.map(item => {
        const pid = fulfilCtx ? fulfilCtx.resolveId({ productId: item.productId, productName: item.productName }) : null;
        const canFulfil = !!(fulfilCtx?.canTransfer && pid && item.size && fulfilCtx.knownLoc(item.hub));
        const isOpen = openComposite === item.composite;
        return (
        <div key={`onhold-${item.composite}`} style={{ background:CARD, border:BORDER_BRIGHT, borderRadius:RADIUS, padding:"1.1rem 1.25rem", boxShadow:"0 0 16px rgba(60,110,255,.15)", borderLeft:`3px solid ${BLUE}` }}>
          <div style={{ display:"flex", alignItems:"center", gap:"1rem", marginBottom:"0.85rem" }}>
            <ProductPhoto url={item.photoUrl} photo={item.photo} size={48} radius={8}/>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:"0.6rem", marginBottom:"0.2rem" }}>
                <span style={{ fontFamily:"'SF Pro Display',-apple-system,sans-serif", fontWeight:"800", fontSize:"1.4rem", color:BLUE_L, lineHeight:1, letterSpacing:"0.05em" }}>#{item.orderNumber}</span>
                <span style={{ background:"rgba(60,110,255,.12)", color:BLUE_L, border:BORDER, borderRadius:"999px", padding:"1px 8px", fontSize:"0.7rem", fontWeight:"600" }}>On Hold</span>
              </div>
              <div style={{ fontWeight:"600", fontSize:"0.92rem", color:"#fff" }}>{item.productName} — Size <SizeTag size={item.size} /></div>
              <div style={{ color:"#888", fontSize:"0.8rem" }}>{item.customerName}</div>
              <div style={{ color:"#444", fontSize:"0.72rem", marginTop:"0.2rem" }}>Put on hold: {fmt(item.ts)}</div>
            </div>
          </div>
          <div style={{ display:"flex", gap:"0.6rem" }}>
            <button
              onClick={() => canFulfil ? setOpenComposite(isOpen ? null : item.composite) : handleRespond(item, "sent")}
              style={{ ...bGreen, flex:1, padding:"0.55rem", display:"flex", alignItems:"center", justifyContent:"center", gap:5 }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><polyline points="20 6 9 17 4 12"/></svg>
              {canFulfil ? "Fulfil" : "Sent"}
            </button>
            <button
              onClick={() => handleRespond(item, "out_of_stock")}
              style={{ ...bRed, flex:1, padding:"0.55rem", display:"flex", alignItems:"center", justifyContent:"center", gap:5 }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              Out of Stock
            </button>
          </div>
          {canFulfil && isOpen && (
            <SourceFulfilPanel
              productId={pid}
              size={item.size}
              destHub={item.hub}
              remaining={1}
              alreadySent={0}
              movementIdSeed={`srcoh_${item.composite}`}
              locationsReg={fulfilCtx.locationsReg}
              actorRole={fulfilCtx.actorRole}
              onDone={() => { setOpenComposite(null); handleRespond(item, "sent"); }}
              onCancel={() => setOpenComposite(null)}
              onWithoutTransfer={() => { setOpenComposite(null); handleRespond(item, "sent"); }}
            />
          )}
        </div>
        );
      })}

      {/* Completed list — revealed by toggle */}
      {showCompleted && completed.length > 0 && (
        <>
          <div style={{ marginTop:8, marginBottom:2, display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ height:1, flex:1, background:"rgba(255,255,255,.06)" }} />
            <div style={{ fontSize:10, fontWeight:700, color:"rgba(255,255,255,.4)", letterSpacing:"1.2px" }}>COMPLETED</div>
            <div style={{ height:1, flex:1, background:"rgba(255,255,255,.06)" }} />
          </div>
          {completed.map(item => {
            const response = item.response?.response;
            const isSent = response === "sent";
            const accent = isSent ? "rgba(74,222,128,.5)"  : "rgba(248,113,113,.5)";
            const tint   = isSent ? "rgba(74,222,128,.08)" : "rgba(248,113,113,.08)";
            const text   = isSent ? "#4ADE80"              : "#F87171";
            return (
              <div key={`onhold-done-${item.composite}`} style={{ background:CARD, border:`1px solid ${accent}`, borderLeft:`3px solid ${accent}`, borderRadius:RADIUS, padding:"1.1rem 1.25rem", opacity:0.85 }}>
                <div style={{ display:"flex", alignItems:"center", gap:"1rem", marginBottom:"0.6rem" }}>
                  <ProductPhoto url={item.photoUrl} photo={item.photo} size={48} radius={8}/>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:"0.6rem", marginBottom:"0.2rem" }}>
                      <span style={{ fontFamily:"'SF Pro Display',-apple-system,sans-serif", fontWeight:"800", fontSize:"1.2rem", color:"rgba(255,255,255,.85)", lineHeight:1, letterSpacing:"0.05em" }}>#{item.orderNumber}</span>
                      <span style={{ display:"inline-flex", alignItems:"center", gap:5, padding:"2px 8px", borderRadius:999, background:tint, border:`1px solid ${accent}`, color:text, fontSize:10, fontWeight:700, letterSpacing:".5px", textTransform:"uppercase" }}>
                        <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round">
                          {isSent ? <polyline points="20 6 9 17 4 12"/> : <><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></>}
                        </svg>
                        {isSent ? "Sent" : "Out of Stock"}
                      </span>
                    </div>
                    <div style={{ fontWeight:"600", fontSize:"0.9rem", color:"rgba(255,255,255,.85)" }}>{item.productName} — Size <SizeTag size={item.size} /></div>
                    <div style={{ color:"#888", fontSize:"0.78rem" }}>{item.customerName}</div>
                  </div>
                </div>
                <div style={{ display:"flex", justifyContent:"flex-end" }}>
                  <button onClick={() => handleUndo(item)}
                          style={{ padding:"7px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.12)", background:"rgba(255,255,255,.04)", color:"rgba(255,255,255,.7)", fontWeight:600, fontSize:11, cursor:"pointer", display:"flex", alignItems:"center", gap:5 }}>
                    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                      <polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/>
                    </svg>
                    Undo
                  </button>
                </div>
              </div>
            );
          })}
        </>
      )}
    </div>
  );
}

// Returns "YYYY-MM-DD" for yesterday in SA time.
function getSAYesterdayString() {
  const now = new Date(serverNowMs() + 2 * 60 * 60 * 1000);
  now.setUTCDate(now.getUTCDate() - 1);
  return now.toISOString().slice(0, 10);
}

// ─── CLOTHING-SOLD REFILL TAB ─────────────────────────────────────────────────
// One card per (store, product) with a per-size qty breakdown — NOT one per
// (sale,size) cell (which fragmented a popular item into dozens of ×1 cards). The
// data is /stock_movements-native; the action is a single "Refilled" confirm.

// Canonical section order — Clothing subcategories first (catalogue order), then
// any others (e.g. mis-tagged accessories) alphabetically after.
const CLOTHING_SECTION_ORDER = CATEGORY_TREE.Clothing || [];

// Buckets refill cards under collapsible category/subcategory headers (T-Shirts,
// Jackets, Tracksuits…) so the crew scans by section. Same collapsible furniture
// as DayCollapsible; open state persists in sessionStorage. Defaults all open.
// Flat, type-ordered worklist: products are grouped by clothing type (T-Shirts,
// Hoodies, …) in CLOTHING_SECTION_ORDER and listed one after another under a
// lightweight, ALWAYS-VISIBLE header — no collapsing. Same-type products follow
// each other so the refill crew reads straight down the rail.
function ClothingSoldSections({ items, sectionOf, renderItem, emptyMessage }) {
  const buckets = new Map();
  (items || []).forEach(item => {
    const label = sectionOf(item);
    if (!buckets.has(label)) buckets.set(label, []);
    buckets.get(label).push(item);
  });

  const orderIdx = (label) => {
    const i = CLOTHING_SECTION_ORDER.indexOf(label);
    return i >= 0 ? i : CLOTHING_SECTION_ORDER.length + 1;
  };
  const sections = Array.from(buckets.entries())
    .sort((a, b) => orderIdx(a[0]) - orderIdx(b[0]) || a[0].localeCompare(b[0]));

  if (!sections.length) {
    return <div style={{ textAlign:"center", color:"#444", padding:"3rem 1rem", fontSize:"0.95rem" }}>{emptyMessage || "Nothing to show."}</div>;
  }

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:20 }}>
      {sections.map(([label, list]) => {
        const units = list.reduce((n, g) => n + (g.total || 0), 0);
        return (
          <div key={label}>
            {/* Non-collapsible type header — a labelled divider, always open. */}
            <div style={{ display:"flex", alignItems:"center", gap:8, margin:"0 2px 10px" }}>
              <div style={{ fontSize:11, fontWeight:800, color:"#4A7FFF", letterSpacing:"1px", textTransform:"uppercase" }}>{label}</div>
              <div style={{ background:"rgba(60,110,255,.12)", color:"#4A7FFF", border:"1px solid rgba(60,110,255,.3)", borderRadius:999, padding:"1px 8px", fontSize:10, fontWeight:700 }}>
                {list.length}{units !== list.length ? ` · ${units}u` : ""}
              </div>
              <div style={{ height:1, flex:1, background:"rgba(60,110,255,.12)" }} />
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
              {list.map((item, i) => <div key={item.key || i}>{renderItem(item)}</div>)}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// Product refill card. Pending → big "Refilled" button; done → Refilled tag + Undo.
// `group` is a clothingSoldGroups() row: { productName, photo, sizes:[{size,qty}],
// total, store, ts, ... }. `showStore` adds the store label (used in Backlog,
// where stores are merged; redundant in a single-store daily tab).
// Which SA-day(s) a daily-tab card covers. A card sums a (store, product) across
// the today+yesterday window, so it can span both days — label the actual span
// ("Today", "Yesterday", or "Yesterday → Today") instead of an ambiguous "20h ago".
// `fresh` (has a sale today) drives the accent so leftover-only cards read amber.
function clothingSoldDayLabel(group) {
  const today = getSAPastDateString(0);
  const yest  = getSAPastDateString(1);
  const name  = (d) => (d === today ? "Today" : d === yest ? "Yesterday" : d);
  const late  = saDateOf(group.ts);
  const early = saDateOf(group.earliestTs || group.ts);
  const label = early === late ? name(late) : `${name(early)} → ${name(late)}`;
  return { label, fresh: late === today };
}

// The inline refill sheet: the SOURCE is the tab-wide picked hub (fromLoc). For
// each outstanding size, set the qty to move (default = min(outstanding, available
// at the hub), capped at available so nothing goes negative), confirm → one tagged
// hub→store transfer per size via applyMovement. A per-size "Out" flags a size the
// hub is short on (it stays outstanding). The card updates itself from the ledger.
function ClothingRefillSheet({ group, fromLoc, fromLabel, availAt, storeQtyAt, actorRole, onMarkOut, onRefilled, onClose }) {
  const outSizes = group.sizes.filter(s => s.outstanding > 0);
  const [qtys, setQtys] = useState({});
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState(null);

  // Seed per-size defaults from the picked hub's availability.
  useEffect(() => {
    const next = {};
    outSizes.forEach(s => { next[s.size] = Math.min(s.outstanding, availAt(s.size)); });
    setQtys(next);
    setMsg(null);
  }, [fromLoc]); // eslint-disable-line react-hooks/exhaustive-deps

  const setQ = (size, v, max) => setQtys(q => ({ ...q, [size]: Math.max(0, Math.min(max, Math.floor(Number(v) || 0))) }));
  const movingTotal = outSizes.reduce((n, s) => n + (qtys[s.size] || 0), 0);

  const confirm = async () => {
    if (busy || !fromLoc) return;
    setBusy(true); setMsg(null);
    let ok = 0; const fails = []; const moved = [];
    for (const s of outSizes) {
      const qty = qtys[s.size] || 0;
      if (qty <= 0) continue;
      const before = storeQtyAt(s.size);  // store qty pre-move → expected qty after
      const res = await fireClothingRefill({ store: group.store, productId: group.productId, size: s.size, qty, from: fromLoc, actorRole });
      if (res && res.ok) {
        ok++; moved.push({ size: s.size, qty, expect: before + qty });
        // Zero a moved size immediately: fireClothingRefill isn't idempotent, so if
        // the sheet stays open on a partial failure, a second Confirm must only send
        // the legs that still haven't moved — never re-send this one.
        setQtys(prev => ({ ...prev, [s.size]: 0 }));
      }
      else fails.push(`${s.size}: ${res && res.reason === "insufficient_stock" ? `only ${res.available} at source` : (res && res.reason) || "failed"}`);
    }
    setBusy(false);
    if (ok > 0 && onRefilled) onRefilled({ store: group.store, productId: group.productId, productName: group.productName, from: fromLoc, lines: moved });
    if (!fails.length && ok > 0) onClose();       // live ledger recomputes the card
    else if (!ok && !fails.length) setMsg("Enter a quantity for at least one size.");
    else setMsg(`${ok} moved · ${fails.length} failed — ${fails.join("; ")}`);
  };

  return (
    <div style={{ marginTop:10, background:"rgba(60,110,255,.05)", border:"1px solid rgba(60,110,255,.25)", borderRadius:12, padding:12 }}>
      <div style={{ fontSize:10, fontWeight:700, color:"rgba(255,255,255,.4)", letterSpacing:".6px", marginBottom:8 }}>PULL FROM <span style={{ color:BLUE_L }}>{fromLabel}</span></div>
      <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
        {outSizes.map(s => {
          const avail = availAt(s.size);
          const q = qtys[s.size] || 0;
          return (
            <div key={s.size} style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ minWidth:56 }}><span style={{ fontSize:13, fontWeight:700, color:"#fff" }}>Size <SizeTag size={s.size} /></span></div>
              <div style={{ fontSize:11, color: avail > 0 ? "rgba(255,255,255,.45)" : "#F5A623", flex:1 }}>
                need {s.outstanding}{s.refilled > 0 ? ` · ${s.refilled} done` : ""} · {avail} at {fromLabel}
              </div>
              {avail > 0 ? (
                <div style={{ display:"flex", alignItems:"center", gap:0, border:"1px solid rgba(60,110,255,.3)", borderRadius:8, overflow:"hidden" }}>
                  <button onClick={() => setQ(s.size, q - 1, avail)} disabled={q <= 0} style={{ width:28, height:30, border:"none", background:"rgba(255,255,255,.04)", color:"#fff", cursor: q<=0?"default":"pointer", fontSize:16 }}>−</button>
                  <input value={q} onChange={e => setQ(s.size, e.target.value, avail)} inputMode="numeric"
                         style={{ width:34, height:30, textAlign:"center", border:"none", background:"rgba(0,0,0,.3)", color: q>avail?"#F87171":"#fff", fontSize:13, fontWeight:700, outline:"none" }} />
                  <button onClick={() => setQ(s.size, q + 1, avail)} disabled={q >= avail} style={{ width:28, height:30, border:"none", background:"rgba(255,255,255,.04)", color:"#fff", cursor: q>=avail?"default":"pointer", fontSize:16 }}>+</button>
                </div>
              ) : (
                <button onClick={() => onMarkOut(group.store, group.productId, s.size)}
                        title={`${fromLabel} has none — flag this size out at ${fromLabel}`}
                        style={{ padding:"6px 11px", borderRadius:8, border:"1px solid rgba(245,166,35,.45)", background:"rgba(245,166,35,.1)", color:"#F5A623", fontWeight:700, fontSize:11, cursor:"pointer" }}>
                  Out here
                </button>
              )}
            </div>
          );
        })}
      </div>
      {msg && <div style={{ marginTop:10, fontSize:11, color:"#F59E0B", fontWeight:600 }}>{msg}</div>}
      <div style={{ display:"flex", gap:8, marginTop:12 }}>
        <button onClick={onClose} style={{ padding:"9px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.12)", background:"rgba(255,255,255,.04)", color:"rgba(255,255,255,.7)", fontWeight:600, fontSize:12, cursor:"pointer" }}>Cancel</button>
        <button onClick={confirm} disabled={busy || movingTotal <= 0}
                style={{ flex:1, padding:"9px 12px", borderRadius:10, border:"1px solid rgba(74,222,128,.5)", background: movingTotal>0?"rgba(74,222,128,.15)":"rgba(255,255,255,.03)", color: movingTotal>0?"#4ADE80":"rgba(255,255,255,.35)", fontWeight:700, fontSize:13, cursor: (busy||movingTotal<=0)?"default":"pointer", display:"flex", alignItems:"center", justifyContent:"center", gap:6 }}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
          {busy ? "Transferring…" : `Transfer ${movingTotal} → ${SHOP_LABELS[group.store] || group.store}`}
        </button>
      </div>
    </div>
  );
}

// Product refill card. Shows per-size OUTSTANDING (sold − refilled) and a Refill
// button that opens the transfer sheet, sourced from the tab-wide picked hub.
// Sizes the hub is short on can be flagged "Out at <hub>" (stays outstanding).
// Done (every size fully refilled) shows a cleared state. `canTransfer` gates the
// transfer UI on a stock-capable role; `refillFrom` must be picked to transfer.
function ClothingSoldCard({ group, showStore, onViewPhoto, allCells, registry, actorRole, canTransfer, refillFrom, onMarkOut, onClearOut, onRefilled }) {
  const [openSheet, setOpenSheet] = useState(false);
  const done = group.done;
  const accent = done ? "rgba(74,222,128,.5)" : "rgba(60,110,255,.6)";
  const hasPhotos = onViewPhoto && Array.isArray(group.photos) && group.photos.length > 0;
  // Availability of THIS product at the tab-wide picked hub, per size.
  const hubCells = (refillFrom && allCells && allCells[refillFrom] && allCells[refillFrom][group.productId]) || {};
  const availAt = (size) => Number(hubCells[size] && hubCells[size].qty) || 0;
  // Current on-hand at the STORE — the baseline for the 60s undo's intact-check.
  const storeCells = (allCells && allCells[group.store] && allCells[group.store][group.productId]) || {};
  const storeQtyAt = (size) => Number(storeCells[size] && storeCells[size].qty) || 0;
  const hubLabel = refillFrom ? labelFor(refillFrom, registry) : null;

  return (
    <div style={{
      background:CARD, border:`1px solid ${accent}`,
      borderLeft: done ? `3px solid ${accent}` : `1px solid ${accent}`,
      borderRadius:14, padding:14,
      opacity: done ? 0.9 : 1,
      boxShadow: done ? "none" : "0 0 10px rgba(60,110,255,.15)",
    }}>
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:10 }}>
        <div onClick={hasPhotos ? () => onViewPhoto(group.photos) : undefined}
             title={hasPhotos ? "Tap to enlarge" : undefined}
             style={{ position:"relative", flexShrink:0, cursor: hasPhotos ? "zoom-in" : "default", borderRadius:10 }}>
          <ProductPhoto url={group.photoUrl} photo={group.photo} size={48} radius={10}/>
          {hasPhotos && (
            <div style={{ position:"absolute", right:-3, bottom:-3, width:16, height:16, borderRadius:"50%", background:"rgba(4,5,10,.95)", border:"1px solid rgba(60,110,255,.5)", display:"flex", alignItems:"center", justifyContent:"center" }}>
              <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#6A9FFF" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3M11 8v6M8 11h6"/></svg>
            </div>
          )}
        </div>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>{group.productName}</div>
          <div style={{ display:"flex", alignItems:"center", gap:6, marginTop:3, color:"rgba(255,255,255,.45)", fontSize:11 }}>
            {showStore && <><span style={{ color:BLUE_L, fontWeight:600 }}>{SHOP_LABELS[group.store] || group.store}</span><span style={{ opacity:.4 }}>·</span></>}
            {showStore ? (
              <span>{relativeTimeFromIso(group.ts)}</span>
            ) : (() => {
              // Daily tabs merge today+yesterday — mark the day(s) explicitly.
              const { label, fresh } = clothingSoldDayLabel(group);
              return (
                <span style={{
                  display:"inline-flex", alignItems:"center", padding:"1px 8px", borderRadius:999,
                  fontSize:10, fontWeight:700, letterSpacing:".3px", textTransform:"uppercase",
                  color: fresh ? "#4A7FFF" : "#F5A623",
                  background: fresh ? "rgba(60,110,255,.12)" : "rgba(245,166,35,.1)",
                  border: `1px solid ${fresh ? "rgba(60,110,255,.4)" : "rgba(245,166,35,.4)"}`,
                }}>{label}</span>
              );
            })()}
          </div>
        </div>
        <div style={{ textAlign:"center", flexShrink:0 }}>
          <div style={{ fontWeight:800, fontSize:22, color: done ? "#4ADE80" : "#4A7FFF", lineHeight:1 }}>{done ? "✓" : group.total}</div>
          <div style={{ fontSize:9, color:"rgba(255,255,255,.4)", fontWeight:700, letterSpacing:".5px" }}>{done ? "DONE" : "TO REFILL"}</div>
        </div>
      </div>

      {/* Per-size rows: outstanding, refill progress, out-flag. */}
      <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom: done ? 0 : 10 }}>
        {group.sizes.map(s => {
          const zero = s.outstanding === 0;
          const border = s.outHub ? "rgba(245,166,35,.4)" : zero ? "rgba(74,222,128,.4)" : "rgba(60,110,255,.25)";
          const bg = s.outHub ? "rgba(245,166,35,.08)" : zero ? "rgba(74,222,128,.08)" : "rgba(60,110,255,.1)";
          return (
            <div key={s.size} title={`sold ${s.sold} · refilled ${s.refilled}${s.outHub ? ` · out at ${labelFor(s.outHub, registry)}` : ""}${refillFrom ? ` · ${availAt(s.size)} at ${hubLabel}` : ""}`}
                 style={{ display:"inline-flex", alignItems:"center", gap:5, background:bg, border:`1px solid ${border}`, borderRadius:8, padding:"4px 8px", opacity: zero ? 0.75 : 1 }}>
              <span style={{ fontSize:12, fontWeight:700, color:"#fff" }}><SizeTag size={s.size} /></span>
              {zero
                ? <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#4ADE80" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6L9 17l-5-5"/></svg>
                : <span style={{ fontSize:11, color:BLUE_L, fontWeight:700 }}>×{s.outstanding}{s.refilled > 0 ? <span style={{ color:"rgba(255,255,255,.35)" }}> /{s.sold}</span> : null}</span>}
              {s.outHub && !zero && <span style={{ fontSize:9, color:"#F5A623", fontWeight:800, letterSpacing:".3px" }}>OUT</span>}
            </div>
          );
        })}
      </div>

      {!done && !openSheet && (
        <div style={{ display:"flex", gap:8 }}>
          {!canTransfer ? (
            <div style={{ flex:1, padding:"10px 12px", borderRadius:10, border:"1px dashed rgba(255,255,255,.15)", color:"rgba(255,255,255,.4)", fontSize:11.5, textAlign:"center" }}>
              Refill needs stock permission — ask an admin for a stock role.
            </div>
          ) : !refillFrom ? (
            <div style={{ flex:1, padding:"10px 12px", borderRadius:10, border:"1px dashed rgba(245,166,35,.35)", color:"#F5A623", fontSize:11.5, textAlign:"center" }}>
              Pick a “Refill from” hub above to transfer.
            </div>
          ) : (
            <button onClick={() => setOpenSheet(true)}
                    style={{ flex:1, padding:"11px 12px", borderRadius:10, border:"1px solid rgba(74,222,128,.5)", background:"rgba(74,222,128,.12)", color:"#4ADE80", cursor:"pointer", fontWeight:700, fontSize:13, display:"flex", alignItems:"center", justifyContent:"center", gap:6 }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
              Refill from {hubLabel}
            </button>
          )}
        </div>
      )}

      {!done && openSheet && (
        <ClothingRefillSheet group={group} fromLoc={refillFrom} fromLabel={hubLabel} availAt={availAt} storeQtyAt={storeQtyAt}
          actorRole={actorRole} onMarkOut={onMarkOut} onRefilled={onRefilled} onClose={() => setOpenSheet(false)} />
      )}

      {/* Out-flagged sizes — a tag naming the hub, tap to clear (pending or done). */}
      {group.sizes.some(s => s.outHub) && (
        <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginTop:10, alignItems:"center" }}>
          <span style={{ fontSize:10, color:"#F5A623", fontWeight:800, letterSpacing:".4px" }}>OUT:</span>
          {group.sizes.filter(s => s.outHub).map(s => (
            <button key={s.size} onClick={() => onClearOut(group.store, group.productId, s.size)}
                    title={`Out at ${labelFor(s.outHub, registry)} — tap to clear`}
                    style={{ display:"inline-flex", alignItems:"center", gap:4, padding:"3px 8px", borderRadius:999, border:"1px solid rgba(245,166,35,.4)", background:"rgba(245,166,35,.08)", color:"#F5A623", fontSize:10.5, fontWeight:700, cursor:"pointer" }}>
              <SizeTag size={s.size} /> @{labelFor(s.outHub, registry)} ✕
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// One scope's worklist (a store's daily list, or the merged Backlog). Groups are
// split pending/done by ledger-derived outstanding (group.done); pending are laid
// out flat, type-ordered (ClothingSoldSections); done sit under a Show-Completed toggle.
function ClothingSoldScopePanel({ events, isBacklog, onViewPhoto, allCells, registry, actorRole, canTransfer, refillFrom, onMarkOut, onClearOut, onRefilled }) {
  const [showCompleted, setShowCompleted] = useState(false);

  // With a "Refill from" hub picked, the PENDING list is filtered to only what that
  // hub can actually fill: qty > 0 of at least one still-outstanding size. Partial
  // counts (needs M×2, hub has M×1 → shown; they send 1, the rest stays). A card the
  // hub has zero of every outstanding size is hidden — it reappears under a hub that
  // holds it. No hub picked → show the full pending list.
  const { pending, completed, hiddenByHub } = useMemo(() => {
    const pend = [], completed = [];
    events.forEach(g => (g.done ? completed : pend).push(g));
    const canFill = (g) => {
      if (!refillFrom) return true;
      const cells = (allCells && allCells[refillFrom] && allCells[refillFrom][g.productId]) || {};
      return g.sizes.some(s => s.outstanding > 0 && (Number(cells[s.size] && cells[s.size].qty) || 0) > 0);
    };
    const pending = pend.filter(canFill);
    const hiddenByHub = refillFrom ? pend.length - pending.length : 0;
    pending.sort((a, b) => (b.ts || "").localeCompare(a.ts || ""));
    completed.sort((a, b) => (b.ts || "").localeCompare(a.ts || ""));
    return { pending, completed, hiddenByHub };
  }, [events, refillFrom, allCells]);
  const cardProps = { showStore: isBacklog, onViewPhoto, allCells, registry, actorRole, canTransfer, refillFrom, onMarkOut, onClearOut, onRefilled };

  if (!pending.length && !completed.length) return (
    <div style={{ textAlign:"center", color:"#444", padding:"4rem 1rem" }}>
      <ProductIcon size={32} opacity={0.5}/>
      <div style={{ fontSize:"1rem", marginTop:"0.75rem" }}>
        {hiddenByHub > 0
          ? `${labelFor(refillFrom, registry)} can't fill anything here — ${hiddenByHub} item${hiddenByHub !== 1 ? "s" : ""} need a different hub.`
          : isBacklog ? "No older clothing sales pending." : "No clothing sold here today or yesterday."}
      </div>
      <div style={{ fontSize:"0.85rem", color:"#333", marginTop:"0.5rem" }}>
        {hiddenByHub > 0 ? "Switch the “Refill from” hub above." : "Clothing sold at the till appears here for restocking."}
      </div>
    </div>
  );

  const pendingUnits = pending.reduce((n, g) => n + g.total, 0);

  return (
    <div>
      {/* Summary headline — pending units across pending products */}
      <div style={{ background:"rgba(4,5,10,1)", border:"1px solid rgba(60,110,255,.6)", borderRadius:14, padding:"14px 16px", marginBottom:14, display:"flex", alignItems:"center", gap:14, boxShadow:"0 0 16px rgba(60,110,255,.2)" }}>
        <div style={{ fontWeight:800, fontSize:36, color:"#4A7FFF", lineHeight:1, letterSpacing:"-1px" }}>{pendingUnits}</div>
        <div style={{ flex:1 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Units to refill</div>
          <div style={{ color:"rgba(255,255,255,.5)", fontSize:11, marginTop:3, lineHeight:1.4 }}>
            {pending.length} product{pending.length !== 1 ? "s" : ""} {refillFrom ? `fillable from ${labelFor(refillFrom, registry)}` : "pending"}{completed.length ? ` · ${completed.length} refilled` : ""}{hiddenByHub > 0 ? ` · ${hiddenByHub} on other hubs` : ""}
          </div>
        </div>
      </div>

      {completed.length > 0 && (
        <CompletedTogglePill on={showCompleted} count={completed.length} onClick={() => setShowCompleted(v => !v)} />
      )}

      {pending.length === 0 && completed.length > 0 && !showCompleted && (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(74,222,128,.4)", borderRadius:16, padding:"22px 18px", textAlign:"center", boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
          <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="#4ADE80" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ filter:"drop-shadow(0 0 6px rgba(74,222,128,.35))" }}>
            <circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/>
          </svg>
          <div style={{ color:"#fff", fontSize:14, fontWeight:700, marginTop:10 }}>All caught up</div>
          <div style={{ color:"rgba(255,255,255,.55)", fontSize:12, marginTop:4 }}>{completed.length} product{completed.length !== 1 ? "s" : ""} refilled.</div>
          <button onClick={() => setShowCompleted(true)}
                  style={{ marginTop:14, padding:"8px 16px", borderRadius:10, border:"1px solid rgba(60,110,255,.5)", background:"rgba(60,110,255,.12)", color:BLUE_L, fontWeight:600, fontSize:12, cursor:"pointer" }}>
            Show Refilled
          </button>
        </div>
      )}

      {/* Active list — flat, type-ordered (T-Shirts, Hoodies, …), no collapsing. */}
      <ClothingSoldSections
        items={pending}
        sectionOf={clothingSectionLabel}
        emptyMessage="Nothing to refill."
        renderItem={g => <ClothingSoldCard group={g} {...cardProps} />}
      />

      {showCompleted && completed.length > 0 && (
        <>
          <div style={{ marginTop:18, marginBottom:10, display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ height:1, flex:1, background:"rgba(255,255,255,.06)" }} />
            <div style={{ fontSize:10, fontWeight:700, color:"rgba(255,255,255,.4)", letterSpacing:"1.2px" }}>REFILLED</div>
            <div style={{ height:1, flex:1, background:"rgba(255,255,255,.06)" }} />
          </div>
          <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
            {completed.map(g => <ClothingSoldCard key={g.key} group={g} {...cardProps} />)}
          </div>
        </>
      )}
    </div>
  );
}

// Clothing-Sold view mounted inside SOURCE's "Clothing Sold" top tab. Scope pills
// put the actionable per-store DAILY lists first; the merged aging "Backlog" is
// last and secondary. Reads the bounded movements window + products + refills once.
function ClothingSoldView({ products }) {
  const [scope, setScope] = usePersistedTab("clothingSold", CLOTHING_SOLD_STORES[0]);
  const [fullPhoto, setFullPhoto] = useState(null); // GalleryLightbox photos array | null
  const [search, setSearch] = useState("");

  // Per-store daily tabs cover today + yesterday (the actionable "sold, refill it"
  // window); Backlog is everything strictly older than yesterday. So the split
  // cutoff the tabs filter on is YESTERDAY, not today.
  const perStoreCutoff = getSAPastDateString(1);   // yesterday — daily = saDate >= this
  const dayBeforeYest  = getSAPastDateString(2);   // backlog upper bound (strictly < yesterday)
  // Backlog date window (SA-dates). Default: the recent BACKLOG_DAYS window ending
  // the day before yesterday. The picker widens it back to the 90-day cap or
  // narrows to a single day (from === to).
  const maxBack   = getSAPastDateString(CLOTHING_SOLD_MAX_RANGE_DAYS);
  const defaultFrom = getSAPastDateString(CLOTHING_SOLD_BACKLOG_DAYS);
  const [backlogWindow, setBacklogWindow] = useState(() => ({ from: defaultFrom, to: dayBeforeYest }));

  // The movements query starts at the backlog window's `from` (clamped in the
  // hook to ≤ 90 days) and stays open-ended to now, so the daily tabs always see
  // today. Picking an older `from` re-subscribes to a wider (still bounded) window.
  const movements = useClothingSoldMovements(backlogWindow.from);
  const oos       = useClothingOos();
  const allCells  = useStockCells();     // { loc: { pid: { size: cell } } } — source availability
  const registry  = useLocations();      // location labels/kinds for the source picker
  const { permRecord: clothPerm, isSuperAdmin: clothSuper } = usePermissions();
  const actorRole = clothSuper ? "admin" : (clothPerm && clothPerm.stockRole) || null;
  const canTransfer = ["store", "warehouse", "admin"].includes(actorRole);

  // ONE "Refill from" hub for the whole tab — pick it once and every card refills
  // from it (required, no default). Options = every non-shop location, whether or
  // not it currently holds stock (availability shows per card).
  const [refillFrom, setRefillFrom] = useState("");
  const refillSourceOpts = useMemo(
    () => transferTargets(registry).filter(l => l.kind !== "store")
      .map(l => ({ id: l.id, label: labelFor(l.id, registry) })),
    [registry]
  );

  const productsById = useMemo(() => {
    const m = {};
    (products || []).forEach(p => { if (p && p.id) m[p.id] = p; });
    return m;
  }, [products]);

  // Groups per scope. Daily tabs cover today + yesterday (saDate >= perStoreCutoff);
  // Backlog is everything strictly older than yesterday, bounded to the picked
  // [from, to] window. Outstanding = sold − refilled (ledger) with skips applied —
  // all derived inside clothingSoldEventsForPeriod.
  const eventsByScope = useMemo(() => {
    const out = {};
    CLOTHING_SOLD_STORES.forEach(s => {
      out[s] = clothingSoldEventsForPeriod({ movements, productsById, cutoff: perStoreCutoff, store: s, oos });
    });
    out.backlog = clothingSoldEventsForPeriod({
      movements, productsById, cutoff: perStoreCutoff, store: null, stores: CLOTHING_SOLD_STORES,
      fromSaDate: backlogWindow.from, toSaDate: backlogWindow.to, oos,
    });
    return out;
  }, [movements, productsById, perStoreCutoff, backlogWindow.from, backlogWindow.to, oos]);

  const pendingUnits = (evs) => evs.reduce((n, g) => n + (g.done ? 0 : g.total), 0);

  // Backlog search filter (name + category/subcategory), live as you type.
  const backlogEvents = useMemo(() => {
    const q = search.trim().toLowerCase();
    const evs = eventsByScope.backlog || [];
    if (!q) return evs;
    return evs.filter(g =>
      (g.productName || "").toLowerCase().includes(q) ||
      (g.subcategory || "").toLowerCase().includes(q) ||
      (g.category || "").toLowerCase().includes(q)
    );
  }, [eventsByScope, search]);

  // Daily per-store lists first (the crew's actual work), aging Backlog last.
  const SCOPES = [
    ...CLOTHING_SOLD_STORES.map(s => ({ key: s, label: SHOP_LABELS[s] || s })),
    { key: "backlog", label: "Backlog" },
  ];

  // Mark a size OUT from the currently-picked hub (keeps it outstanding), or clear.
  const handleMarkOut = (store, pid, size) => saveClothingOut(store, pid, size, refillFrom);
  const handleClearOut = (store, pid, size) => clearClothingOut(store, pid, size);

  // 60-second accidental-transfer undo. A successful refill registers its moved
  // lines; within 60s "Undo" reverses each (store→hub) — but ONLY sizes whose store
  // cell is still EXACTLY what the refill left (nothing sold/moved since). Changed
  // sizes are left alone (reverse them by hand); after 60s the affordance is gone.
  const [undo, setUndo] = useState(null);   // { id, store, productId, productName, from, lines:[{size,qty,expect}], units }
  const [undoMsg, setUndoMsg] = useState(null);
  const [undoLeft, setUndoLeft] = useState(0);
  const undoTimer = useRef(null);
  const handleRefilled = (batch) => {
    if (undoTimer.current) clearTimeout(undoTimer.current);
    const units = batch.lines.reduce((n, l) => n + l.qty, 0);
    setUndoMsg(null);
    setUndo({ ...batch, id: String(serverNowMs()), units });
    setUndoLeft(60);
    undoTimer.current = setTimeout(() => setUndo(null), 60000);
  };
  useEffect(() => {
    if (!undo) return;
    const iv = setInterval(() => setUndoLeft(n => (n > 1 ? n - 1 : 0)), 1000);
    return () => clearInterval(iv);
  }, [undo]);
  const runUndo = async () => {
    if (!undo) return;
    const cur = (allCells && allCells[undo.store] && allCells[undo.store][undo.productId]) || {};
    let reversed = 0, blocked = 0;
    for (const ln of undo.lines) {
      const nowQty = Number(cur[ln.size] && cur[ln.size].qty) || 0;
      if (nowQty !== ln.expect) { blocked++; continue; }   // store cell changed → don't claw back
      const res = await reverseClothingRefill({ store: undo.store, productId: undo.productId, size: ln.size, qty: ln.qty, hub: undo.from, batchId: undo.id, actorRole });
      if (res && res.ok) reversed++; else blocked++;
    }
    if (undoTimer.current) clearTimeout(undoTimer.current);
    setUndo(null);
    setUndoMsg(blocked
      ? `Reversed ${reversed}; ${blocked} already moved since — reverse those with a manual transfer.`
      : `Reversed ${reversed} unit${reversed !== 1 ? "s" : ""} back to ${labelFor(undo.from, registry)}.`);
    setTimeout(() => setUndoMsg(null), 6000);
  };

  // Date-picker clamps: keep maxBack ≤ from ≤ to ≤ dayBeforeYest and the span ≤ cap.
  const addDays  = (d, n) => new Date(new Date(`${d}T00:00:00.000Z`).getTime() + n * 86400000).toISOString().slice(0, 10);
  const spanDays = (a, b) => Math.round((new Date(`${b}T00:00:00.000Z`).getTime() - new Date(`${a}T00:00:00.000Z`).getTime()) / 86400000);
  const clamp    = (v, lo, hi) => (v < lo ? lo : (v > hi ? hi : v));
  const setFrom = (v) => setBacklogWindow(w => {
    let from = clamp(v, maxBack, w.to);
    if (spanDays(from, w.to) > CLOTHING_SOLD_MAX_RANGE_DAYS) from = addDays(w.to, -CLOTHING_SOLD_MAX_RANGE_DAYS);
    return { ...w, from };
  });
  const setTo = (v) => setBacklogWindow(w => {
    let to = clamp(v, w.from, dayBeforeYest);
    if (spanDays(w.from, to) > CLOTHING_SOLD_MAX_RANGE_DAYS) to = addDays(w.from, CLOTHING_SOLD_MAX_RANGE_DAYS);
    return { ...w, to };
  });
  const resetWindow    = () => { setBacklogWindow({ from: defaultFrom, to: dayBeforeYest }); setSearch(""); };
  const isDefaultWindow = backlogWindow.from === defaultFrom && backlogWindow.to === dayBeforeYest;

  const dateInput = { padding:"7px 9px", borderRadius:10, border:"1px solid rgba(60,110,255,.25)", background:"rgba(255,255,255,.03)", color:"#fff", fontSize:12, colorScheme:"dark", outline:"none" };
  const isBacklog = scope === "backlog";
  const backlogTotal = (eventsByScope.backlog || []).length;
  const panelEvents = isBacklog ? backlogEvents : (eventsByScope[scope] || []);

  return (
    <div>
      {/* Scope segmented pills — daily stores first, Backlog (secondary) last */}
      <div style={{ display:"flex", gap:8, marginBottom:8, overflowX:"auto" }}>
        {SCOPES.map(({ key, label }) => {
          const active = scope === key;
          const backlog = key === "backlog";
          const badge = pendingUnits(eventsByScope[key] || []);
          return (
            <button key={key} onClick={() => setScope(key)}
                    style={{
                      flex:"1 0 auto",
                      padding:"10px 12px",
                      borderRadius:14,
                      border: active ? "1px solid rgba(60,110,255,.6)" : "1px solid rgba(255,255,255,.08)",
                      background: active ? "rgba(60,110,255,.14)" : "rgba(255,255,255,.02)",
                      color: active ? BLUE_L : (backlog ? "rgba(255,255,255,.4)" : "rgba(255,255,255,.55)"),
                      fontWeight:700, fontSize:13, cursor:"pointer",
                      display:"flex", alignItems:"center", justifyContent:"center", gap:8, whiteSpace:"nowrap",
                      boxShadow: active ? "0 0 12px rgba(60,110,255,.18)" : "none",
                      transition:"background 120ms ease, border-color 120ms ease",
                    }}>
              <span>{label}</span>
              <span style={{
                background: active ? "rgba(60,110,255,.25)" : "rgba(255,255,255,.06)",
                color: active ? "#fff" : "rgba(255,255,255,.5)",
                borderRadius:999, padding:"1px 8px", fontSize:11, fontWeight:700, minWidth:22, textAlign:"center",
              }}>{badge}</span>
            </button>
          );
        })}
      </div>

      {/* ONE global "Refill from" hub — drives availability + transfers on every
          card. Required (no default); until it's picked, cards can't transfer. */}
      {canTransfer && (
        <div style={{ marginBottom:12 }}>
          <div style={{ fontSize:10, fontWeight:800, color:"rgba(255,255,255,.4)", letterSpacing:".6px", textTransform:"uppercase", marginBottom:6 }}>Refill from</div>
          <div style={{ display:"flex", gap:7, flexWrap:"wrap" }}>
            {refillSourceOpts.map(o => {
              const on = refillFrom === o.id;
              return (
                <button key={o.id} onClick={() => setRefillFrom(o.id)}
                        style={{ padding:"7px 12px", borderRadius:999, cursor:"pointer", fontSize:12, fontWeight:700,
                                 border: on ? "1px solid #4A7FFF" : "1px solid rgba(60,110,255,.22)",
                                 background: on ? "rgba(60,110,255,.2)" : "rgba(255,255,255,.03)", color: on ? "#fff" : "rgba(255,255,255,.55)" }}>
                  {o.label}
                </button>
              );
            })}
          </div>
          {!refillFrom && <div style={{ fontSize:11, color:"#F5A623", marginTop:6 }}>Pick a hub to refill from — availability shows on each card.</div>}
        </div>
      )}

      {isBacklog ? (
        <div style={{ marginBottom:14, display:"flex", flexDirection:"column", gap:10 }}>
          {/* Search — live filter by product name / category */}
          <div style={{ position:"relative" }}>
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.4)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
                 style={{ position:"absolute", left:11, top:"50%", transform:"translateY(-50%)" }}><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/></svg>
            <input value={search} onChange={e => setSearch(e.target.value)}
                   placeholder={`Search ${backlogTotal} products by name or category…`}
                   style={{ width:"100%", boxSizing:"border-box", padding:"10px 34px 10px 34px", borderRadius:12, border:"1px solid rgba(60,110,255,.25)", background:"rgba(255,255,255,.03)", color:"#fff", fontSize:13, outline:"none" }} />
            {search && (
              <button onClick={() => setSearch("")} aria-label="Clear search"
                      style={{ position:"absolute", right:8, top:"50%", transform:"translateY(-50%)", width:22, height:22, borderRadius:"50%", border:"none", background:"rgba(255,255,255,.08)", color:"rgba(255,255,255,.6)", cursor:"pointer", fontSize:15, lineHeight:1 }}>×</button>
            )}
          </div>
          {/* Date range — bounded ts window, capped at 90 days */}
          <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
            <span style={{ fontSize:11, color:"rgba(255,255,255,.4)" }}>From</span>
            <input type="date" value={backlogWindow.from} min={maxBack} max={backlogWindow.to}
                   onChange={e => e.target.value && setFrom(e.target.value)} style={dateInput} />
            <span style={{ fontSize:11, color:"rgba(255,255,255,.4)" }}>to</span>
            <input type="date" value={backlogWindow.to} min={backlogWindow.from} max={dayBeforeYest}
                   onChange={e => e.target.value && setTo(e.target.value)} style={dateInput} />
            {!(isDefaultWindow && !search) && (
              <button onClick={resetWindow}
                      style={{ padding:"6px 12px", borderRadius:10, border:"1px solid rgba(255,255,255,.12)", background:"rgba(255,255,255,.04)", color:"rgba(255,255,255,.7)", fontWeight:600, fontSize:11, cursor:"pointer" }}>Reset</button>
            )}
          </div>
          <div style={{ fontSize:11, color:"rgba(255,255,255,.4)", lineHeight:1.4 }}>
            {search
              ? `${backlogEvents.length} of ${backlogTotal} products match “${search}”`
              : `${backlogTotal} product${backlogTotal !== 1 ? "s" : ""} sold ${backlogWindow.from === backlogWindow.to ? `on ${backlogWindow.from}` : `${backlogWindow.from} → ${backlogWindow.to}`} — mostly already restocked; work the daily tabs first.`}
          </div>
        </div>
      ) : (
        <div style={{ fontSize:11, color:"rgba(255,255,255,.4)", marginBottom:14, lineHeight:1.4 }}>
          {`Sold today & yesterday at ${SHOP_LABELS[scope] || scope} — refill it.`}
        </div>
      )}

      <ClothingSoldScopePanel
        events={panelEvents}
        isBacklog={isBacklog}
        onViewPhoto={setFullPhoto}
        allCells={allCells}
        registry={registry}
        actorRole={actorRole}
        canTransfer={canTransfer}
        refillFrom={refillFrom}
        onMarkOut={handleMarkOut}
        onClearOut={handleClearOut}
        onRefilled={handleRefilled}
      />

      {/* 60-second accidental-transfer undo — reverses only untouched store cells. */}
      {undo && (
        <div style={{ position:"fixed", left:12, right:12, bottom:16, zIndex:70, maxWidth:430, margin:"0 auto",
                      background:"rgba(4,5,10,.97)", border:"1px solid rgba(74,222,128,.5)", borderRadius:14, padding:"12px 14px",
                      display:"flex", alignItems:"center", gap:12, boxShadow:"0 10px 30px rgba(0,0,0,.5)" }}>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ color:"#fff", fontSize:13, fontWeight:700 }}>Refilled {undo.units} unit{undo.units !== 1 ? "s" : ""} → {SHOP_LABELS[undo.store] || undo.store}</div>
            <div style={{ color:"rgba(255,255,255,.5)", fontSize:11, marginTop:2 }}>{undo.productName} · from {labelFor(undo.from, registry)}</div>
          </div>
          <button onClick={runUndo}
                  style={{ padding:"8px 14px", borderRadius:10, border:"1px solid rgba(248,113,113,.5)", background:"rgba(248,113,113,.12)", color:"#F87171", fontWeight:800, fontSize:12.5, cursor:"pointer", whiteSpace:"nowrap" }}>
            Undo ({undoLeft}s)
          </button>
        </div>
      )}
      {undoMsg && !undo && (
        <div style={{ position:"fixed", left:12, right:12, bottom:16, zIndex:70, maxWidth:430, margin:"0 auto",
                      background:"rgba(4,5,10,.97)", border:"1px solid rgba(60,110,255,.4)", borderRadius:14, padding:"11px 14px",
                      color:"rgba(255,255,255,.85)", fontSize:12, boxShadow:"0 10px 30px rgba(0,0,0,.5)" }}>
          {undoMsg}
        </div>
      )}
      {fullPhoto && <GalleryLightbox photos={fullPhoto} onClose={() => setFullPhoto(null)} />}
    </div>
  );
}

// Per-tab nav glyphs for the Source desktop workspace rail.
const SOURCE_TAB_ICON = {
  today:    <><rect x="2" y="7" width="20" height="14" rx="2"/><path d="M16 21V5a2 2 0 00-2-2h-4a2 2 0 00-2 2v16"/></>,
  history:  <><path d="M3 3v5h5"/><path d="M3.05 13A9 9 0 1 0 6 5.3L3 8"/><path d="M12 7v5l4 2"/></>,
  onhold:   <><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></>,
  clothing: <path d="M16 4l-4 4-4-4M3 7l5-3h8l5 3M3 7v13a1 1 0 001 1h16a1 1 0 001-1V7M3 7l4 4M21 7l-4 4"/>,
};
const SOURCE_TABS = [["today","Today's Request"],["history","History"],["onhold","On Hold"],["clothing","Hub 2 Refill"]];

function SourceView({ onExit, orders, returnsLog, products }) {
  const [tab, setTab] = usePersistedTab("source", "today");
  // Active hub — shared across all three top tabs. Defaults to Hub 1.
  const [hub, setHub] = useState("hub1");
  const todayDate   = getSADateString();
  // Desktop workspace gate (>=1024px). Mobile keeps the single-column layout.
  const isWide = !useIsNarrow(1024);

  // ── Transfer & Fulfil context (shared by all three tabs) ────────────────────
  // Same access gate as every other stock-writing surface (Hub2RefillQueue):
  // a stockRole is required to move inventory. Users without one keep the
  // original Available / Sent buttons — the tab never breaks for them.
  const { permRecord, isSuperAdmin } = usePermissions();
  const actorRole = isSuperAdmin ? "admin" : (permRecord?.stockRole || null);
  const canTransfer = SOURCE_TRANSFER_ROLES.includes(actorRole);
  const locationsReg = useLocations();
  // Fallback productId resolution by (normalized) product name — for cells
  // rebuilt from log events or orders that predate the productId field.
  const productIdByName = useMemo(() => {
    const normKey = s => s.trim().replace(/\s+/g, ' ').toLowerCase().replace(/\s*-\s*/g, '-');
    const map = {};
    (products || []).forEach(p => {
      if (!p.name || !p.id) return;
      map[p.name] = p.id;
      map[normKey(p.name)] = p.id;
    });
    return map;
  }, [products]);
  const fulfilCtx = useMemo(() => ({
    canTransfer, actorRole, locationsReg,
    // A transfer destination must be a REGISTERED stock location — On Hold
    // items can carry hubC (clothing-customer routing), which has no /stock
    // presence; those cards keep the plain Sent button instead.
    knownLoc: (id) => !!id && transferTargets(locationsReg).some(l => l.id === id),
    resolveId: (product) => {
      if (!product) return null;
      if (product.productId) return product.productId;
      const name = product.productName;
      if (!name) return null;
      const normKey = s => s.trim().replace(/\s+/g, ' ').toLowerCase().replace(/\s*-\s*/g, '-');
      return productIdByName[name] || productIdByName[normKey(name)] || null;
    },
  }), [canTransfer, actorRole, locationsReg, productIdByName]);
  // Partial complete → progress leaf (cell stays open); final units → the exact
  // same response record the old Available button wrote, plus audit extras.
  const handleFulfilProgress = useCallback((date, key, size, newQty, complete, meta) => {
    if (complete) saveSourceResponse(date, key, size, "available", { fulfilledQty: newQty, transferred: true, ...(meta || {}) });
    else saveSourceFulfilProgress(date, key, size, newQty, meta);
  }, []);

  // Immutable insights_log — the durable source for PAST-day History and On Hold.
  // Live /orders is keyed by the daily orderNumber (resets each morning), so
  // today's orders overwrite yesterday's slots; past-day + on-hold requests read
  // straight from /orders vanished. The log keeps every ready/tomorrow transition
  // forever, so past days survive. Today's tabs still use live /orders (no lag).
  const insightsLog = useInsightsLog();

  // name → { photoUrl, photo } lookup so log-reconstructed cards (the log carries
  // no photo) still render a thumbnail. Mirrors the Insights productPhotoMap.
  const sourcePhotoMap = useMemo(() => {
    const normKey = s => s.trim().replace(/\s+/g, ' ').toLowerCase().replace(/\s*-\s*/g, '-');
    const map = {};
    (products || []).forEach(p => {
      if (!p.name) return;
      const entry = { photoUrl: p.photoUrl || null, photo: p.photo || "" };
      map[p.name] = entry;
      map[normKey(p.name)] = entry;
    });
    return map;
  }, [products]);
  const photoForName = useCallback((name) => {
    if (!name) return { photoUrl: null, photo: "" };
    const normKey = s => s.trim().replace(/\s+/g, ' ').toLowerCase().replace(/\s*-\s*/g, '-');
    return sourcePhotoMap[name] || sourcePhotoMap[normKey(name)] || { photoUrl: null, photo: "" };
  }, [sourcePhotoMap]);

  // On Hold response state — read once here so badges and the On Hold tab
  // share the same source of truth (no duplicate Firebase listeners).
  const [onHoldResponses, setOnHoldResponses] = useState({});
  useEffect(() => {
    const unsub = onValue(ref(database, "source_onhold_responses"), snap => {
      setOnHoldResponses(snap.val() || {});
    });
    return () => unsub();
  }, []);

  // Returned-today orderIds: same-period subtraction the Insights Net Sales
  // card applies. Returned items are physically back in the warehouse, so
  // they generate no restock work — drop them from the pull list and the
  // headline / per-product / X-products counts that derive from it.
  const returnedTodayIds = useMemo(
    () => returnedOrderIdsOnSADate(returnsLog, todayDate),
    [returnsLog, todayDate]
  );

  // ── Restock data filter rules ─────────────────────────────────────────────
  // Source has 3 tabs, each with a strict status filter.
  // Today's Request: READY + COLLECTED today           (sold/sent today)
  // On Hold:         COMING_TOMORROW                   (committed for tomorrow)
  // History:         READY + COLLECTED past dates      (historical sales)
  // EVERY tab + the home-page badge MUST exclude OUT_OF_STOCK.
  // OOS items have been confirmed gone by the warehouse — they generate
  // zero restock work for Source.
  // All three tabs are then sliced by the active hub (hub1/hub2). Orders
  // without an explicit hub field default to "hub1", matching the rest of
  // the app.

  // All-hub today list — keep one shared filter, then slice per-hub for counts
  // and the active tab. Cheap enough that we don't memo separately per hub.
  const todayRestockOrdersAll = useMemo(() =>
    orders.filter(o =>
      o.status !== STATUS.OUT_OF_STOCK &&
      (o.status === STATUS.READY || o.status === STATUS.COLLECTED) &&
      orderSaleDate(o) === todayDate &&
      !returnedTodayIds.has(o.id)
    ),
    [orders, todayDate, returnedTodayIds]
  );
  const todayRestockOrders = useMemo(
    () => todayRestockOrdersAll.filter(o => (o.hub || "hub1") === hub),
    [todayRestockOrdersAll, hub]
  );
  const rawCounts = useMemo(() => computeCollectedCounts(todayRestockOrders), [todayRestockOrders]);

  // All Source responses: { date: { productKey: { size: { response, respondedOn } } } }
  // History tab derives its straggler list from this + live orders (5-day window).
  // fulfilProgress carries the partial Transfer & Fulfil leaves (same node).
  const { responses: allResponses, progress: fulfilProgress } = useAllSourceResponses();

  // SA-time (UTC+2) YYYY-MM-DD of any timestamp — same convention as orderSaleDate.
  const saDateOfTs = (ts) => ts ? new Date(new Date(ts).getTime() + 2 * 60 * 60 * 1000).toISOString().slice(0, 10) : null;

  // ── On Hold list (shared by the tab, the hub badges AND the top-bar count) ──
  // Today's on-holds come from live /orders (current status COMING_TOMORROW —
  // no lag, and an UNDONE on-hold correctly disappears). Past-day on-holds come
  // from the immutable log (action="tomorrow"), because the live order that held
  // them was overwritten by the daily orderNumber rollover. Deduped by the
  // composite date::orderNumber key — orderNumber alone is daily-reused, so a
  // bare key made yesterday's on-hold collide with today's. Returned orders drop
  // out (no restock work). `responded` is the source_onhold_responses flag.
  const onHoldMerged = useMemo(() => {
    const pastDates = Array.from({ length: HISTORY_RETENTION_DAYS }, (_, i) => getSAPastDateString(i + 1));
    const byComposite = new Map();

    // Live: every current COMING_TOMORROW order (today + any not-yet-clobbered past).
    (orders || []).forEach(o => {
      if (o.status !== STATUS.COMING_TOMORROW) return;
      const saDate = saDateOfTs(o.comingTomorrowAt || o.updatedAt) || todayDate;
      const composite = onHoldKey(saDate, o.id);
      byComposite.set(composite, {
        composite, orderNumber: o.id, saDate,
        productName: o.productName, productId: o.productId || null,
        size: sourceDisplaySize(o), hub: (o.hub || "hub1"),
        customerName: o.customerName || null,
        photoUrl: o.productPhotoUrl || null, photo: o.productPhoto || "",
        ts: o.comingTomorrowAt || o.updatedAt,
      });
    });

    // Log (past days only): fill in on-holds whose live order was overwritten.
    onHoldEventsFromLog({ log: insightsLog, dates: pastDates }).forEach(e => {
      const composite = onHoldKey(e.saDate, e.orderNumber);
      if (byComposite.has(composite)) return;
      const ph = photoForName(e.productName);
      byComposite.set(composite, {
        composite, orderNumber: e.orderNumber, saDate: e.saDate,
        productName: e.productName, productId: e.productId || null,
        size: e.size, hub: e.hub,
        customerName: e.customerName || null,
        photoUrl: ph.photoUrl, photo: ph.photo, ts: e.timestamp,
      });
    });

    // Returned-order composites across the window → excluded (no restock needed).
    const returnedComposites = new Set();
    [todayDate, ...pastDates].forEach(d =>
      returnedOrderIdsOnSADate(returnsLog, d).forEach(num => returnedComposites.add(onHoldKey(d, num)))
    );

    const respondedKeys = new Set(Object.keys(onHoldResponses));
    const list = [];
    byComposite.forEach(item => {
      if (returnedComposites.has(item.composite)) return;
      item.responded = respondedKeys.has(item.composite);
      item.response = onHoldResponses[item.composite] || null;
      list.push(item);
    });
    return list.sort((a, b) => tsMs(b.ts) - tsMs(a.ts));
  }, [insightsLog, orders, onHoldResponses, returnsLog, todayDate, sourcePhotoMap]);

  // Per-hub pending counts for the Hub 1 / Hub 2 sub-tab badges. Mirrors the
  // exact same pending logic each tab uses (Today excludes responded cells,
  // History sums per-day stragglers, On Hold subtracts source_onhold_responses).
  const hubBadges = useMemo(() => {
    const counts = { hub1: 0, hub2: 0 };
    const todayResponses = allResponses[todayDate] || {};

    // -- Today: pending = unresponded cells from today's collected orders (live).
    ["hub1", "hub2"].forEach(h => {
      const hubOrders = todayRestockOrdersAll.filter(o => (o.hub || "hub1") === h);
      const counts2 = computeCollectedCounts(hubOrders);
      Object.entries(counts2).forEach(([key, product]) => {
        Object.entries(product.sizes || {}).forEach(([size, count]) => {
          if (todayResponses[key]?.[size]) return;
          counts[h] += (typeof count === "number" ? count : 1);
        });
      });
    });

    // -- History: pending = unresponded cells per past 1..N days, rebuilt from
    // the durable log (live /orders is clobbered by the daily orderNumber reset).
    for (let daysAgo = 1; daysAgo <= HISTORY_RETENTION_DAYS; daysAgo++) {
      const dateStr  = getSAPastDateString(daysAgo);
      const returned = returnedOrderIdsOnSADate(returnsLog, dateStr);
      const dayResponses = allResponses[dateStr] || {};
      ["hub1", "hub2"].forEach(h => {
        const counts2 = restockCountsFromLog({ log: insightsLog, dateStr, hub: h, returnedIds: returned });
        Object.entries(counts2).forEach(([key, product]) => {
          Object.entries(product.sizes || {}).forEach(([size, count]) => {
            if (dayResponses[key]?.[size]) return;
            counts[h] += (typeof count === "number" ? count : 1);
          });
        });
      });
    }

    // -- On Hold: pending (unresponded) on-holds from the shared merged list.
    onHoldMerged.forEach(item => {
      if (item.responded) return;
      if (item.hub === "hub1" || item.hub === "hub2") counts[item.hub] += 1;
    });

    return counts;
  }, [todayRestockOrdersAll, allResponses, todayDate, insightsLog, returnsLog, onHoldMerged]);

  // Top-tab On Hold badge — total pending across ALL hubs (matches old behavior).
  const onHoldCount = useMemo(
    () => onHoldMerged.filter(item => !item.responded).length,
    [onHoldMerged]
  );

  // DEBUG — paste in browser console to inspect counted vs leaked orders.
  // Removed once you've verified the math is right. Lives in useEffect so it
  // doesn't get reassigned every render.
  useEffect(() => {
    if (typeof window === "undefined") return;
    window.__sourceDebug = () => {
      const candidates = orders.filter(o =>
        (o.status === STATUS.READY || o.status === STATUS.COLLECTED) &&
        o.status !== STATUS.OUT_OF_STOCK
      );
      const today = todayDate;
      const counted = candidates.filter(o => orderSaleDate(o) === today && !returnedTodayIds.has(o.id));
      const noReadyAt = candidates.filter(o => !o.readyAt && !o.collectedAt);
      const otherDays = candidates.filter(o => orderSaleDate(o) && orderSaleDate(o) !== today);
      const returnedOut = candidates.filter(o => orderSaleDate(o) === today && returnedTodayIds.has(o.id));
      const onHold = orders.filter(o => o.status === STATUS.COMING_TOMORROW);
      console.log("=== SOURCE DEBUG ===");
      console.log("Today:", today, "Active hub:", hub);
      console.log("Counted in TODAY's request (all hubs):", counted.length, counted.map(o => ({id:o.id, hub:o.hub || "hub1", status:o.status, readyAt:o.readyAt, collectedAt:o.collectedAt})));
      console.log("Hub badges (pending):", hubBadges);
      console.log("Excluded — no readyAt:", noReadyAt.length);
      console.log("Excluded — readyAt on other day:", otherDays.length);
      console.log("Excluded — returned today:", returnedOut.length);
      console.log("On Hold (Tomorrow, all hubs):", onHold.length);
      console.log("By status:", {
        READY:     candidates.filter(o => o.status === STATUS.READY).length,
        COLLECTED: candidates.filter(o => o.status === STATUS.COLLECTED).length,
        OOS:       orders.filter(o => o.status === STATUS.OUT_OF_STOCK).length,
        TOMORROW:  onHold.length,
        INCOMING:  orders.filter(o => o.status === STATUS.INCOMING).length,
      });
    };
  }, [orders, todayDate, returnedTodayIds, hub, hubBadges]);

  const handleResponse = (date, productKey, size, response) => {
    saveSourceResponse(date, productKey, size, response);
  };
  const handleUndo = (date, productKey, size) => {
    clearSourceResponse(date, productKey, size);
  };

  // Shared between the mobile column and the desktop rail/pane.
  const hubSelector = (
    <>
      {tab !== "clothing" && tab !== "onhold" && (
      <div style={{ padding:"10px 13px 0", display:"flex", gap:8 }}>
        {[["hub1","Hub 1"],["hub2","Hub 2"]].map(([val, label]) => {
          const active = hub === val;
          const badge = hubBadges[val] || 0;
          return (
            <button key={val} onClick={() => setHub(val)}
                    style={{
                      flex:1,
                      padding:"10px 12px",
                      borderRadius:14,
                      border: active ? "1px solid rgba(60,110,255,.6)" : "1px solid rgba(255,255,255,.08)",
                      background: active ? "rgba(60,110,255,.14)" : "rgba(255,255,255,.02)",
                      color: active ? BLUE_L : "rgba(255,255,255,.55)",
                      fontWeight:700, fontSize:13, cursor:"pointer",
                      display:"flex", alignItems:"center", justifyContent:"center", gap:8,
                      boxShadow: active ? "0 0 12px rgba(60,110,255,.18)" : "none",
                      transition:"background 120ms ease, border-color 120ms ease",
                    }}>
              <span>{label}</span>
              <span style={{
                background: active ? "rgba(60,110,255,.25)" : "rgba(255,255,255,.06)",
                color: active ? "#fff" : "rgba(255,255,255,.5)",
                borderRadius:999,
                padding:"1px 8px",
                fontSize:11,
                fontWeight:700,
                minWidth:22,
                textAlign:"center",
              }}>{badge}</span>
            </button>
          );
        })}
      </div>
      )}
    </>
  );
  const content = (
    <>
        {tab==="today"   && <SourceTodayTab
                              rawCounts={rawCounts}
                              responses={allResponses[todayDate] || {}}
                              date={todayDate}
                              hub={hub}
                              wide={isWide}
                              fulfilCtx={fulfilCtx}
                              progress={fulfilProgress[todayDate] || {}}
                              onFulfilProgress={handleFulfilProgress}
                              onResponse={(key, size, resp) => handleResponse(todayDate, key, size, resp)}
                              onUndo={(key, size) => handleUndo(todayDate, key, size)} />}
        {tab==="history" && <SourceHistoryTab
                              log={insightsLog}
                              returnsLog={returnsLog}
                              allResponses={allResponses}
                              hub={hub}
                              photoForName={photoForName}
                              fulfilCtx={fulfilCtx}
                              fulfilProgress={fulfilProgress}
                              onFulfilProgress={handleFulfilProgress}
                              onResponse={handleResponse} />}
        {tab==="onhold"  && <SourceOnHoldTab items={onHoldMerged} fulfilCtx={fulfilCtx} />}
        {/* "Clothing Sold" (per-store manual worklist) replaced by the Hub 2
            auto-refill queue — the engine detects sold→below-target itself and
            Central fulfils from this single tab (owner decision 2026-07-12). */}
        {tab==="clothing" && <Hub2RefillQueue products={products} />}
    </>
  );

  // ── DESKTOP WORKSPACE (>=1024px) — left rail of restock queues + main pane. ──
  if (isWide) {
    const activeTab = SOURCE_TABS.some(([k]) => k === tab) ? tab : "today";
    const activeLabel = (SOURCE_TABS.find(([k]) => k === activeTab) || [null, "Today's Request"])[1];
    const totalPending = (hubBadges.hub1 || 0) + (hubBadges.hub2 || 0);
    const navItem = ([key, label]) => {
      const on = activeTab === key;
      const badge = key === "onhold" ? onHoldCount : 0;
      return (
        <button key={key} onClick={() => setTab(key)}
          style={{ display:"flex", alignItems:"center", gap:11, width:"100%", textAlign:"left", cursor:"pointer", fontFamily:FONT, fontSize:13, fontWeight:600, borderRadius:10, padding:"9px 11px",
                   background: on ? "rgba(74,127,255,.13)" : "transparent", border: on ? "1px solid rgba(74,127,255,.42)" : "1px solid transparent",
                   color: on ? "#9DBCFF" : "rgba(233,238,255,.55)", transition:"background .14s, color .14s" }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink:0, opacity:.9 }}>{SOURCE_TAB_ICON[key]}</svg>
          <span style={{ flex:1 }}>{label}</span>
          {badge > 0 && (
            <span style={{ background:"#F59E0B", color:"#000", fontSize:10.5, fontWeight:800, minWidth:19, height:19, borderRadius:"50%", padding:"0 5px", display:"inline-flex", alignItems:"center", justifyContent:"center" }}>{badge}</span>
          )}
        </button>
      );
    };
    return (
      <div style={{ height:"100vh", maxHeight:"100dvh", background:"#000", color:"#f3f6ff", fontFamily:FONT, display:"grid", gridTemplateColumns:"236px minmax(0,1fr)", overflow:"hidden" }}>
        {/* RAIL */}
        <aside style={{ background:"rgba(255,255,255,.015)", borderRight:"1px solid rgba(255,255,255,.08)", padding:"22px 13px 16px", display:"flex", flexDirection:"column", gap:3, overflow:"auto" }}>
          <div style={{ display:"flex", alignItems:"baseline", gap:8, padding:"0 9px 10px" }}>
            <span style={{ fontSize:19, fontWeight:800, fontStyle:"italic", letterSpacing:-.6 }}>marathon</span>
            <span style={{ fontSize:9.5, fontWeight:700, letterSpacing:5, color:"#4A7FFF" }}>CLUB</span>
          </div>
          <button onClick={onExit} style={{ display:"flex", alignItems:"center", gap:8, background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.08)", color:"rgba(233,238,255,.6)", borderRadius:10, padding:"9px 12px", fontSize:12.5, fontWeight:600, cursor:"pointer", fontFamily:FONT, marginBottom:8 }}>&larr; Exit</button>
          <div style={{ fontSize:9, letterSpacing:".2em", textTransform:"uppercase", color:"rgba(233,238,255,.3)", padding:"6px 9px", fontWeight:700 }}>Restock</div>
          {SOURCE_TABS.map(navItem)}
          <div style={{ flex:1 }} />
          <div style={{ display:"flex", gap:8 }}>
            <div style={{ flex:1, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", borderRadius:11, padding:"9px 10px" }}>
              <div style={{ fontSize:18, fontWeight:800, color: totalPending ? "#9DBCFF" : "rgba(233,238,255,.5)", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{totalPending}</div>
              <div style={{ fontSize:9.5, color:"rgba(233,238,255,.45)", marginTop:3, letterSpacing:".04em", textTransform:"uppercase", fontWeight:600 }}>To restock</div>
            </div>
            <div style={{ flex:1, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", borderRadius:11, padding:"9px 10px" }}>
              <div style={{ fontSize:18, fontWeight:800, color: onHoldCount ? "#F59E0B" : "rgba(233,238,255,.5)", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{onHoldCount}</div>
              <div style={{ fontSize:9.5, color:"rgba(233,238,255,.45)", marginTop:3, letterSpacing:".04em", textTransform:"uppercase", fontWeight:600 }}>On hold</div>
            </div>
          </div>
        </aside>
        {/* MAIN */}
        <div style={{ minWidth:0, display:"flex", flexDirection:"column", overflow:"hidden" }}>
          <div style={{ padding:"20px 30px 14px", borderBottom:"1px solid rgba(255,255,255,.08)", background:"radial-gradient(800px 280px at 15% -60%, rgba(74,127,255,.08), transparent)" }}>
            <div style={{ fontSize:23, fontWeight:800, letterSpacing:-.4 }}>{activeLabel}</div>
            <div style={{ fontSize:12.5, color:"rgba(233,238,255,.55)", marginTop:3 }}>What sold &mdash; and what to restock.</div>
          </div>
          <div style={{ flex:1, overflow:"auto", padding:"14px 30px 48px" }}>
            <div style={{ maxWidth:1160, margin:"0 auto", display:"flex", flexDirection:"column", gap:16 }}>
              <div style={{ maxWidth:380, width:"100%" }}>{hubSelector}</div>
              {content}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, maxWidth:430, margin:"0 auto", overflowX:"hidden", paddingBottom:40 }}>
      {/* TOP BAR */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"50px 14px 10px", position:"relative" }}>
        <div onClick={onExit} style={{ color:"#4A7FFF", fontSize:13, fontWeight:500, cursor:"pointer" }}>← Exit</div>
        <div style={{ display:"flex", alignItems:"center", gap:5 }}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeWidth="1.6" strokeLinecap="round"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="M16 21V5a2 2 0 00-2-2h-4a2 2 0 00-2 2v16"/></svg>
          <div style={{ fontSize:13, fontWeight:600, color:"#fff" }}>SOURCE</div>
        </div>
        <div style={{ display:"flex", alignItems:"center", gap:5, background:"rgba(60,110,255,.08)", borderRadius:14, padding:"4px 8px" }}>
          <span style={{ fontSize:10, color:"rgba(255,255,255,.4)" }}>On Hold</span>
          <span style={{ background:"rgba(60,110,255,.15)", color:"#4A7FFF", fontSize:10, fontWeight:600, width:20, height:20, borderRadius:"50%", display:"flex", alignItems:"center", justifyContent:"center", boxShadow:"0 0 6px rgba(60,110,255,.25)" }}>{onHoldCount}</span>
        </div>
      </div>
      <div style={{ height:1, background:"linear-gradient(90deg,transparent,rgba(60,110,255,.25),transparent)", margin:"0 14px" }}/>
      {/* TOP TABS — Today / History / On Hold */}
      <div style={{ display:"flex", gap:0, padding:"0 13px 10px", borderBottom:"1px solid rgba(255,255,255,.05)", marginBottom:4, marginTop:8 }}>
        {[["today","Today's Request"],["history","History"],["onhold","On Hold"],["clothing","Hub 2 Refill"]].map(([key, label]) => (
          <div key={key} onClick={() => setTab(key)}
               style={{ flex:1, padding:"10px 6px", fontSize:12, fontWeight:600, textAlign:"center", cursor:"pointer", borderBottom:"2px solid " + (tab===key ? "#4A7FFF" : "transparent"), color: tab===key ? "#4A7FFF" : "rgba(255,255,255,.35)" }}>
            {label}{key === "onhold" && onHoldCount > 0 && ` ${onHoldCount}`}
          </div>
        ))}
      </div>
      {/* HUB SUB-TABS — segmented pill, shared by Today + History. Hidden for
          Clothing Sold (own store pills) and On Hold (shows all hubs together). */}
      {hubSelector}
      <div style={{ padding:"1.5rem" }}>
        {content}
      </div>
    </div>
  );
}

// ─── RETURNS VIEW ────────────────────────────────────────────────────────────
const RETURN_REASONS = ["Too Small", "Too Big", "Wrong Item", "Other"];

function ReturnsView({ orders, products = [], onExit }) {
  const [search,      setSearch]      = useState("");
  const [expandedId,  setExpandedId]  = useState(null);
  const [failure,     setFailure]     = useState(null);  // { orderId, kind, message } — a return that did NOT ledger
  const [retFilter,   setRetFilter]   = useState("all"); // all | toreturn | returned
  const returnsLog = useReturnsLog();
  const todayDate  = getSADateString();
  // Desktop workspace gate (>=1024px). Mobile keeps the single column.
  const isWide = !useIsNarrow(1024);

  // Ready/Collected orders from the last 3 days (Phase 10). DayCollapsible
  // buckets these into Today / Yesterday / 2 days ago. SA-time slices match
  // the convention used elsewhere in the file (+2h shift before slicing).
  const last3DaysOrders = useMemo(() => {
    const allowed = new Set([todayDate, getSAPastDateString(1), getSAPastDateString(2)]);
    return orders
      .filter(o => {
        if (o.status !== STATUS.READY && o.status !== STATUS.COLLECTED) return false;
        const ts = o.readyAt || o.updatedAt;
        if (!ts) return false;
        const saDate = new Date(new Date(ts).getTime() + 2 * 60 * 60 * 1000).toISOString().slice(0, 10);
        return allowed.has(saDate);
      })
      .sort((a, b) => tsMs(b.readyAt || b.updatedAt) - tsMs(a.readyAt || a.updatedAt));
  }, [orders, todayDate]);

  // Composite `${SA-date}::${orderNumber}` set of already-returned orders. NOT a
  // bare orderNumber set: numbers reset daily, so a bare set flags every later
  // day's same-numbered SALE as "Returned" (the false-positive bug). Matched
  // per-order below via orderSaleDate(order).
  const returnedKeys = useMemo(() => returnedCompositeKeySet(returnsLog), [returnsLog]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return last3DaysOrders;
    return last3DaysOrders.filter(o =>
      o.id.toLowerCase().includes(q) || (o.customerName || "").toLowerCase().includes(q)
    );
  }, [last3DaysOrders, search]);

  // R1 (stock-integrity) — a confirmed return MOVES THE LEDGER, not just the log.
  // The dispatch wrote a deterministic disp_ transfer (hub→shop); its id is
  // reconstructible from the order, so we reverse EXACTLY that movement
  // (shop→origin hub, same qty/size) — and ONLY when it exists. Orders whose
  // dispatch never transferred (pre-fix leaks, hubC, legacy) are logged
  // ledgered:false instead of guessing a move that would corrupt a hub cell.
  // returns_log keeps its role as the human report feed, now enriched with
  // productId/qty/ledgered so it can always be audited against the ledger.
  // RETAINED, NOT WIRED (2026-07-29, owner). The Returns list still renders and
  // returns_log still feeds Insights, but no UI calls this: nothing goes back to
  // a hub any more — sneakers never left it, and clothing that reaches the shop
  // stays as shop stock. Kept whole (with resolveReturnDestination, the disp_
  // reversal and logReturn) because "returning to a hub" is a policy that could
  // come back, and re-deriving this reversal logic from scratch — including the
  // date-scoped disp_ id and the negative-tolerant reversal — would be a far
  // bigger job than re-attaching a button. Do not delete as dead code.
  // eslint-disable-next-line no-unused-vars
  const submitReturn = async (order) => {
    const scrub = (s) => s.replace(/[.#$[\]/\s:]/g, "_");
    const dispId = scrub(`disp_${order.id}_${order.createdAt || ""}`);
    const retId  = scrub(`ret_${order.id}_${order.createdAt || ""}`);
    let ledgered = false;
    let ledgerNote = "no_dispatch_transfer";
    let failMsg = null;          // set → surfaced in the UI; card stays actionable
    let failKind = "error";      // "error" (retryable write fail) | "notice" (route by hand)
    try {
      const dispSnap = await get(ref(database, `stock_movements/${dispId}`));
      const disp = dispSnap.val();
      if (disp && disp.type === "transfer_out" && disp.from && disp.to) {
        // PRIMARY — reverse the recorded dispatch EXACTLY (shop→origin hub, same
        // qty/size). The unit demonstrably left the shop, so the shop cell may
        // legitimately pass through negative (allowNegative; the rule now permits
        // a transfer_out leg to go negative, matching sold/return).
        const res = await applyMovement({
          type: "transfer_out",
          productId: disp.productId,
          size: disp.size,            // the size that actually shipped (incl. substitutions)
          qty: disp.qty || 1,
          from: disp.to,              // shop the parcel was sent to…
          to: disp.from,              // …back to the hub the dispatch debited
          actorRole: "warehouse",
          reason: "order return (reverses dispatch)",
          link: { orderId: order.id, reverses: dispId },
          ts: serverNowIso(),
          movementId: retId,
          allowNegative: true,
        });
        if (res?.ok) { ledgered = true; ledgerNote = res.idempotent ? "already_reversed" : "reversed"; }
        else {
          ledgerNote = `reverse_failed:${res?.reason || "unknown"}`;
          failMsg = `Stock NOT returned (${res?.reason || "write failed"}). Not marked returned — tap Confirm again to retry.`;
        }
      } else {
        // FALLBACK — no recorded dispatch transfer to reverse. Resolve intent.
        // Read the product's stored category (orders don't carry it) so kids sneaker
        // sizes 26–35 aren't misread as clothing by the size-based classifier.
        const prod = products.find(p => p.id === order.productId);
        const dest = resolveReturnDestination(order, prod?.category);
        if (dest.mode === "stay") {
          // Clothing / accessory / perfume: never a tracked hub→shop transfer, so
          // there is nothing to reverse in the hub ledger. Processed successfully.
          ledgered = true;
          ledgerNote = `no_transfer_needed:${dest.reason}`;
        } else if (isFootwearLine(prod, order.sentSize ?? order.size)) {
          // ── FOOTWEAR NOW SELLS FROM THE HUB (2026-07-29) ───────────────────
          // Send writes no transfer, so a return has NOTHING to reverse — the
          // stock never left the hub's books. This is the normal, expected path
          // for a shoe that came back, not an error: the pair physically goes
          // to the shelf and the ledger was already correct.
          //
          // This branch REPLACES the old "no dispatch to reverse — restock by
          // hand via Lightspeed" warning, which would now fire on every single
          // returned sneaker and train staff to ignore it.
          ledgered = true;
          ledgerNote = "footwear_no_transfer_to_reverse";
        } else {
          // Non-footwear with no disp_ record — do NOT fire a phantom hub credit
          // (would hide a shortage). Surface it for manual routing; the recon pass
          // restocks the backlog honestly.
          ledgerNote = "no_dispatch_transfer";
          failKind = "notice";
          const where = dest.originHub ? (HUB_LABELS[dest.originHub] || dest.originHub) : "its origin hub";
          failMsg = `No recorded dispatch to reverse. Restock this shoe to ${where} by hand (Lightspeed) — not marked returned.`;
        }
      }
    } catch (err) {
      ledgerNote = `reverse_failed:${String(err?.message || err).slice(0, 60)}`;
      failMsg = `Return error — stock not moved. Not marked returned.`;
    }
    logReturn({
      timestamp:   serverNowIso(),
      date:        todayDate,
      orderNumber: order.id,
      productName: order.productName,
      productId:   order.productId || null,
      qty:         order.qty || 1,
      size:        order.size,
      customerName:order.customerName,
      reason:      null,
      placedAtHub: order.placedAtHub || order.hub || "hub1",
      destShop: order.destShop ?? null,
      ledgered,
      ledgerNote,
    });
    if (failMsg) {
      // Keep the card expanded so the operator sees the reason and can act/retry.
      setFailure({ orderId: order.id, kind: failKind, message: failMsg });
    } else {
      setFailure(f => (f && f.orderId === order.id ? null : f));
      setExpandedId(null);
    }
  };

  // Returned-state test + derived lists for the filter chips.
  const isRet = (o) => returnedKeys.has(`${orderSaleDate(o)}::${o.id}`);
  const returnedCount = filtered.filter(isRet).length;
  const toReturnCount = filtered.length - returnedCount;
  const viewList = retFilter === "returned" ? filtered.filter(isRet)
                 : retFilter === "toreturn" ? filtered.filter(o => !isRet(o))
                 : filtered;

  // Search box (icon + input) — sits in the header on desktop, in the body on mobile.
  const searchEl = (
    <div style={{ position:"relative", width:"100%", maxWidth: isWide ? 300 : 560 }}>
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ position:"absolute", left:12, top:"50%", transform:"translateY(-50%)", opacity:.4 }}><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.3-4.3"/></svg>
      <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search order # or customer…"
        style={{ width:"100%", boxSizing:"border-box", background:"rgba(255,255,255,.05)", border:"1px solid rgba(255,255,255,.14)", borderRadius:11, color:"#fff", fontSize:13.5, padding:"10px 12px 10px 36px", outline:"none" }}/>
    </div>
  );

  // Filter chips with live counts.
  const filterEl = (
    <div style={{ display:"flex", gap:7, marginBottom:16, flexWrap:"wrap" }}>
      {[["all","All",filtered.length],["toreturn","To return",toReturnCount],["returned","Returned",returnedCount]].map(([key,label,n]) => {
        const on = retFilter === key;
        return (
          <button key={key} onClick={() => setRetFilter(key)}
            style={{ display:"inline-flex", alignItems:"center", gap:7, padding:"7px 13px", borderRadius:999, fontSize:12.5, fontWeight:700, cursor:"pointer",
                     background: on ? "rgba(74,127,255,.16)" : "rgba(255,255,255,.03)",
                     border: "1px solid " + (on ? "rgba(74,127,255,.45)" : "rgba(255,255,255,.1)"),
                     color: on ? "#9DBCFF" : "rgba(233,238,255,.55)" }}>
            {label}
            <span style={{ fontSize:11, fontWeight:800, minWidth:18, textAlign:"center", borderRadius:999, padding:"1px 6px", fontVariantNumeric:"tabular-nums",
                           background: on ? "rgba(74,127,255,.3)" : "rgba(255,255,255,.06)", color: on ? "#fff" : "rgba(233,238,255,.5)" }}>{n}</span>
          </button>
        );
      })}
    </div>
  );

  const failureEl = failure ? (
    <div role="alert" style={{ marginBottom:16, padding:"11px 14px", borderRadius:12, fontSize:12.5, lineHeight:1.5, display:"flex", gap:10, alignItems:"flex-start",
        background: failure.kind === "notice" ? "rgba(245,158,11,.1)" : "rgba(239,68,68,.1)",
        border: "1px solid " + (failure.kind === "notice" ? "rgba(245,158,11,.35)" : "rgba(239,68,68,.35)"),
        color: failure.kind === "notice" ? "#FBBF24" : "#F87171" }}>
      <span style={{ flex:1 }}><strong>#{failure.orderId}</strong> — {failure.message}</span>
      <span onClick={() => setFailure(null)} style={{ cursor:"pointer", opacity:.7, fontWeight:700 }}>×</span>
    </div>
  ) : null;

  // Purpose-built return card — product photo, order/size/customer, status, and a
  // confirm panel that spells out exactly what the reversal does.
  const returnCard = (order) => {
    const isReturned = isRet(order);
    const isExpanded = expandedId === order.id;
    return (
      <div style={{ background:"rgba(255,255,255,.024)", border: isReturned ? "1px solid rgba(74,222,128,.28)" : isExpanded ? "1px solid rgba(74,127,255,.5)" : "1px solid rgba(255,255,255,.08)", borderRadius:16, overflow:"hidden", transition:"border-color .18s, box-shadow .18s", boxShadow: isExpanded ? "0 18px 44px -26px rgba(74,127,255,.55)" : "none", opacity: isReturned ? .78 : 1 }}>
        <div style={{ display:"flex", alignItems:"center", gap:13, padding:14 }}>
          <ProductPhoto url={order.productPhotoUrl} photo={order.productPhoto} size={52} radius={11}/>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
              <span className="ret-siri" style={{ fontSize:14, fontWeight:800, letterSpacing:".04em", fontVariantNumeric:"tabular-nums" }}>#{order.id}</span>
              <span style={{ fontSize:9.5, fontWeight:700, color:"rgba(233,238,255,.4)", textTransform:"uppercase", letterSpacing:".07em" }}>{order.status === STATUS.COLLECTED ? "Collected" : "Ready"}</span>
            </div>
            <div style={{ fontSize:14, fontWeight:600, color:"#fff", marginTop:3, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{order.productName}</div>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:6, minWidth:0 }}>
              <span style={{ flexShrink:0, fontSize:11, fontWeight:700, color:"#cfe0ff", background:"rgba(74,127,255,.12)", border:"1px solid rgba(74,127,255,.25)", borderRadius:7, padding:"2px 8px" }}>Size <SizeTag size={order.size}/></span>
              <span style={{ fontSize:11.5, color:"rgba(233,238,255,.5)", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", minWidth:0 }}>{order.customerName || "—"}</span>
            </div>
          </div>
          <div style={{ flexShrink:0 }}>
            {isReturned ? (
              <span style={{ display:"inline-flex", alignItems:"center", gap:5, color:"#4ADE80", fontSize:12, fontWeight:700, background:"rgba(74,222,128,.12)", border:"1px solid rgba(74,222,128,.3)", borderRadius:999, padding:"5px 13px" }}>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                Returned
              </span>
            ) : (
              // The "Log Return" action is GONE (owner, 2026-07-29): nothing goes
              // back to a hub, so there is nothing to log. Leaving the button
              // while its confirm panel says "nothing to send back" was the worst
              // of both — a control that opens onto a dead end. The row is now
              // read-only history. submitReturn and the whole reversal path stay
              // in the file, deliberately unwired; see the note on submitReturn.
              <span style={{ display:"inline-flex", alignItems:"center", gap:5, color:"rgba(233,238,255,.4)", fontSize:11.5, fontWeight:600, background:"rgba(255,255,255,.03)", border:"1px solid rgba(255,255,255,.08)", borderRadius:999, padding:"5px 12px", whiteSpace:"nowrap" }}>
                Stock stays put
              </span>
            )}
          </div>
        </div>
        {/* ── RETURN ACTION REMOVED (2026-07-29, owner) ─────────────────────
            Nothing goes back to a hub, so there is nothing to return:
              • SNEAKERS were never transferred to the shop — the stock stayed
                booked at the hub, so a pair coming back has nothing to reverse.
              • CLOTHING that reaches the shop STAYS there as shop stock.
            Both the "Log Return" button and its confirm panel are gone; the row
            is read-only history now.

            THE CODE IS DELIBERATELY RETAINED — submitReturn, the date-scoped
            disp_ reversal, resolveReturnDestination, logReturn and the
            returns_log feed are untouched, and the Returns list still renders.
            See the note on submitReturn. This is a UI change, not a rebuild. */}
      </div>
    );
  };

  const listEl = (
    <DayCollapsible
      sectionKey="returns"
      items={viewList}
      columns={isWide ? 2 : 1}
      dateOf={(o) => o.readyAt || o.updatedAt}
      emptyMessage={
        last3DaysOrders.length === 0
          ? "No orders marked Ready or Collected in the last 3 days."
          : retFilter === "returned" ? "Nothing returned in this window yet."
          : retFilter === "toreturn" ? "Everything in view has been returned."
          : "No orders match your search."
      }
      renderItem={returnCard}
    />
  );

  const body = (
    <>
      <style>{`
        .ret-siri{background:linear-gradient(90deg,#6e7bff,#5d8bff,#8a6dff,#7f5af0,#8a6dff,#5d8bff,#6e7bff);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent;animation:retSiri 4s linear infinite}
        @keyframes retSiri{from{background-position:0 0}to{background-position:300% 0}}
        @media (prefers-reduced-motion: reduce){.ret-siri{animation:none}}
      `}</style>
      {failureEl}{filterEl}{listEl}
    </>
  );

  // ── DESKTOP WORKSPACE (>=1024px). Mobile keeps the single column below. ──
  if (isWide) {
    return (
      <div style={{ height:"100vh", maxHeight:"100dvh", background:"#000", color:"#f3f6ff", fontFamily:FONT, display:"grid", gridTemplateColumns:"236px minmax(0,1fr)", overflow:"hidden" }}>
        {/* RAIL */}
        <aside style={{ background:"rgba(255,255,255,.015)", borderRight:"1px solid rgba(255,255,255,.08)", padding:"22px 13px 16px", display:"flex", flexDirection:"column", gap:3, overflow:"auto" }}>
          <div style={{ display:"flex", alignItems:"baseline", gap:8, padding:"0 9px 10px" }}>
            <span style={{ fontSize:19, fontWeight:800, fontStyle:"italic", letterSpacing:-.6 }}>marathon</span>
            <span style={{ fontSize:9.5, fontWeight:700, letterSpacing:5, color:"#4A7FFF" }}>CLUB</span>
          </div>
          <button onClick={onExit} style={{ display:"flex", alignItems:"center", gap:8, background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.08)", color:"rgba(233,238,255,.6)", borderRadius:10, padding:"9px 12px", fontSize:12.5, fontWeight:600, cursor:"pointer", fontFamily:FONT, marginBottom:10 }}>&larr; Exit</button>
          <div style={{ display:"flex", alignItems:"center", gap:10, background:"rgba(74,127,255,.1)", border:"1px solid rgba(74,127,255,.32)", borderRadius:11, padding:"10px 12px" }}>
            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#9DBCFF" strokeWidth="2" strokeLinecap="round"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 102.13-9.36L1 10"/></svg>
            <div style={{ fontSize:13.5, fontWeight:800, color:"#cfe0ff" }}>Returns</div>
          </div>
          <div style={{ flex:1 }} />
          <div style={{ display:"flex", gap:8 }}>
            <div style={{ flex:1, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", borderRadius:11, padding:"9px 10px" }}>
              <div style={{ fontSize:18, fontWeight:800, color: toReturnCount ? "#9DBCFF" : "rgba(233,238,255,.5)", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{toReturnCount}</div>
              <div style={{ fontSize:9.5, color:"rgba(233,238,255,.45)", marginTop:3, letterSpacing:".04em", textTransform:"uppercase", fontWeight:600 }}>To return</div>
            </div>
            <div style={{ flex:1, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", borderRadius:11, padding:"9px 10px" }}>
              <div style={{ fontSize:18, fontWeight:800, color: returnedCount ? "#4ADE80" : "rgba(233,238,255,.5)", lineHeight:1, fontVariantNumeric:"tabular-nums" }}>{returnedCount}</div>
              <div style={{ fontSize:9.5, color:"rgba(233,238,255,.45)", marginTop:3, letterSpacing:".04em", textTransform:"uppercase", fontWeight:600 }}>Returned</div>
            </div>
          </div>
        </aside>
        {/* MAIN */}
        <div style={{ minWidth:0, display:"flex", flexDirection:"column", overflow:"hidden" }}>
          <div style={{ padding:"20px 30px 18px", borderBottom:"1px solid rgba(255,255,255,.08)", background:"radial-gradient(800px 280px at 15% -60%, rgba(74,127,255,.08), transparent)", display:"flex", alignItems:"center", gap:24 }}>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:23, fontWeight:800, letterSpacing:-.4 }}>Returns</div>
              <div style={{ fontSize:12.5, color:"rgba(233,238,255,.55)", marginTop:3 }}>Find a recent sale, then confirm — it reverses the dispatch and restocks the item.</div>
            </div>
            {searchEl}
          </div>
          <div style={{ flex:1, overflow:"auto", padding:"20px 30px 48px" }}>
            <div style={{ maxWidth:1160, margin:"0 auto" }}>
              {body}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, maxWidth:430, margin:"0 auto", overflowX:"hidden", paddingBottom:40 }}>
      {/* TOP BAR */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"50px 14px 10px" }}>
        <div onClick={onExit} style={{ color:"#4A7FFF", fontSize:13, fontWeight:500, cursor:"pointer" }}>← Exit</div>
        <div style={{ display:"flex", alignItems:"center", gap:5 }}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeWidth="2" strokeLinecap="round"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 102.13-9.36L1 10"/></svg>
          <div style={{ fontSize:13, fontWeight:600, color:"#fff" }}>RETURNS</div>
        </div>
        <div style={{ fontSize:10, color:"rgba(255,255,255,.4)" }}>{last3DaysOrders.length} done</div>
      </div>

      <div style={{ padding:"1.25rem" }}>
        <div style={{ marginBottom:14 }}>{searchEl}</div>
        {body}
      </div>
    </div>
  );
}

// ─── INSIGHTS: HELPERS ───────────────────────────────────────────────────────
function periodStart(p) {
  // Server-anchored: these boundaries are compared against stored (server-stamped)
  // timestamps, so a wrong device clock would silently shift every Insights window.
  const d = new Date(serverNowMs());
  if (p === "today") { d.setHours(0,0,0,0); }
  if (p === "week")  { d.setDate(d.getDate() - ((d.getDay()+6)%7)); d.setHours(0,0,0,0); }
  if (p === "month") { d.setDate(1); d.setHours(0,0,0,0); }
  if (p === "year")  { d.setMonth(0,1); d.setHours(0,0,0,0); }
  return d.toISOString();
}

function groupCount(arr, keyFn) {
  const map = {};
  arr.forEach(item => { const k = keyFn(item); map[k] = (map[k]||0)+1; });
  return Object.entries(map).map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value);
}

const INSIGHT_ACTION = {
  placed:       { label:"Placed",       color:"#4ADE80", bg:"rgba(74,222,128,.15)" },
  ready:        { label:"Ready",        color:"#4A7FFF", bg:"rgba(60,110,255,.15)" },
  out_of_stock: { label:"Out of Stock", color:"#F87171", bg:"rgba(248,113,113,.15)" },
  tomorrow:     { label:"Tomorrow",     color:BLUE_L,   bg:"rgba(74,130,255,.15)" },
};

function InsightStatCard({ icon, label, value, color=BLUE, sub, photoEl }) {
  return (
    <div style={{ background:CARD, border:BORDER, borderRadius:RADIUS, padding:"1.25rem", boxShadow:GLOW }}>
      <div style={{ fontSize:"1.5rem", marginBottom:"0.25rem" }}>{photoEl || icon}</div>
      <div style={{ fontFamily:"'SF Pro Display',-apple-system,sans-serif", fontWeight:"800", fontSize:"2.2rem", color, lineHeight:1, letterSpacing:"0.02em" }}>{value}</div>
      {sub && <div style={{ color:"#888", fontSize:"0.75rem", marginTop:"0.2rem" }}>{sub}</div>}
      <div style={{ color:"#555", fontSize:"0.72rem", marginTop:"0.3rem", textTransform:"uppercase", letterSpacing:"0.05em" }}>{label}</div>
    </div>
  );
}

function InsightBarChart({ items, color=BLUE, emptyMsg="No data yet", photoMap }) {
  if (!items.length) return <div style={{ color:"rgba(233,238,255,.3)", textAlign:"center", padding:"2rem", fontSize:"0.9rem" }}>{emptyMsg}</div>;
  const max = Math.max(...items.map(i=>i.value), 1);
  return (
    <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
      {items.map(({ label, value }, idx) => {
        const lookupName = label.includes(" — Size ") ? label.split(" — Size ")[0] : label;
        return (
          <div key={label}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6, gap:8 }}>
              <div style={{ display:"flex", alignItems:"center", gap:9, flex:1, minWidth:0 }}>
                {idx < 3 && <span style={{ fontSize:10, fontWeight:800, color:"rgba(233,238,255,.3)", fontVariantNumeric:"tabular-nums", width:12 }}>{idx+1}</span>}
                {photoMap && <ProductThumb name={lookupName} photoMap={photoMap} size={28} />}
                <span style={{ color:"#e7ecff", fontSize:12.5, fontWeight:600, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{label}</span>
              </div>
              <span style={{ fontWeight:800, color:"#fff", fontSize:12.5, flexShrink:0, fontVariantNumeric:"tabular-nums" }}>{value}</span>
            </div>
            <div style={{ background:"rgba(255,255,255,.05)", borderRadius:5, height:8 }}>
              <div style={{ background:`linear-gradient(90deg, ${color}, ${color}cc)`, borderRadius:5, height:8, width:`${Math.max(3,(value/max)*100)}%`, transition:"width .5s cubic-bezier(.2,.7,.2,1)" }} />
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ─── GLOBAL INSIGHTS DATE PICKER ─────────────────────────────────────────────
// ─── INSIGHTS: GLOBAL DATE PICKER ────────────────────────────────────────────
// Three modes: Day (date input + arrows), Week (Mon–Sun + arrows), Month (+ arrows).
// Sits between the tab bar and tab content; state lives in InsightsView.
const _MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];

function InsightsDatePicker({ mode, setMode, dateStr, setDateStr }) {
  const navigate = (delta) => {
    const base = dateStrToLocal(dateStr);
    if (mode === "day")   base.setDate(base.getDate() + delta);
    if (mode === "week")  base.setDate(base.getDate() + delta * 7);
    if (mode === "month") base.setMonth(base.getMonth() + delta);
    if (mode === "year")  base.setFullYear(base.getFullYear() + delta);
    const y  = base.getFullYear();
    const mo = String(base.getMonth() + 1).padStart(2, "0");
    const d  = String(base.getDate()).padStart(2, "0");
    setDateStr(`${y}-${mo}-${d}`);
  };

  const base = dateStrToLocal(dateStr);
  let displayLabel = "";
  if (mode === "week") {
    const dow    = (base.getDay() + 6) % 7;
    const monday = new Date(base); monday.setDate(base.getDate() - dow);
    const sunday = new Date(monday); sunday.setDate(monday.getDate() + 6);
    const fmt    = (d) => `${d.getDate()} ${_MONTHS[d.getMonth()].slice(0,3)}`;
    displayLabel = `${fmt(monday)} – ${fmt(sunday)} ${sunday.getFullYear()}`;
  } else if (mode === "month") {
    displayLabel = `${_MONTHS[base.getMonth()]} ${base.getFullYear()}`;
  } else if (mode === "year") {
    displayLabel = `${base.getFullYear()}`;
  }

  const modeBtn = (key) => ({
    ...(mode===key ? tabOn : tabOff),
    padding:"0.45rem 1rem", minHeight:"44px",
  });
  const navBtn = {
    background:CARD, border:BORDER, borderRadius:"8px",
    color:"#888", cursor:"pointer", fontSize:"1rem",
    padding:"0.4rem 0.75rem", minHeight:"44px", minWidth:"44px",
    display:"flex", alignItems:"center", justifyContent:"center",
  };

  return (
    <div style={{ background:BG, borderBottom:"1px solid rgba(60,110,255,.08)", padding:"0.75rem 1.5rem" }}>
      {/* Mode toggle */}
      <div style={{ display:"flex", gap:"0.4rem", marginBottom:"0.65rem", flexWrap:"wrap" }}>
        {[["day","Day"],["week","Week"],["month","Month"],["year","Year"],["all","All Time"]].map(([k, label]) => (
          <button key={k} onClick={() => setMode(k)} style={modeBtn(k)}>
            {label}
          </button>
        ))}
      </div>
      {/* Navigator — hidden in All Time mode (no period to advance/anchor). */}
      {mode === "all" ? (
        <div style={{ textAlign:"center", color:"#fff", fontWeight:"600", fontSize:"0.95rem", padding:"0.5rem 0", letterSpacing:"0.04em" }}>
          All Time
        </div>
      ) : (
        <div style={{ display:"flex", alignItems:"center", gap:"0.5rem" }}>
          <button onClick={() => navigate(-1)} style={navBtn}>◀</button>
          {mode === "day" ? (
            <input
              type="date"
              value={dateStr}
              onChange={e => e.target.value && setDateStr(e.target.value)}
              style={{
                flex:1, background:"#1a1a1a", border:"1px solid #333", borderRadius:"8px",
                color:"#fff", fontSize:"0.95rem", padding:"0.5rem 0.75rem",
                minHeight:"44px", outline:"none", colorScheme:"dark",
              }}
            />
          ) : (
            <div style={{ flex:1, textAlign:"center", color:"#fff", fontWeight:"600", fontSize:"0.95rem", padding:"0.5rem 0" }}>
              {displayLabel}
            </div>
          )}
          <button onClick={() => navigate(1)} style={navBtn}>▶</button>
        </div>
      )}
    </div>
  );
}

// ─── INSIGHTS: OVERVIEW TAB ───────────────────────────────────────────────────
// Trend chart — 1–2 aligned series (area for the first, line for the rest),
// recessive grid, a legend, and a hover crosshair whose tooltip lists every
// series. One y-axis (both series are the same unit: order counts).
function InsightTrendChart({ labels, series, height = 180 }) {
  const [hi, setHi] = useState(null);
  if (!labels || labels.length === 0) return <div style={{ color: "rgba(233,238,255,.3)", textAlign: "center", padding: "2.5rem 1rem", fontSize: 13 }}>No sales in this period.</div>;
  const W = 620, H = 150, PL = 6, PR = 6, PT = 10, PB = 8;
  const iw = W - PL - PR, ih = H - PT - PB;
  const n = labels.length;
  const max = Math.max(1, ...series.flatMap(s => s.data));
  const X = i => (n === 1 ? PL + iw / 2 : PL + (i / (n - 1)) * iw);
  const Y = v => PT + ih - (v / max) * ih;
  const built = series.map(s => {
    const pts = s.data.map((v, i) => [X(i), Y(v)]);
    const line = pts.map((p, i) => (i ? "L" : "M") + p[0].toFixed(1) + " " + p[1].toFixed(1)).join(" ");
    const area = s.fill ? `M ${pts[0][0].toFixed(1)} ${(PT + ih).toFixed(1)} ` + pts.map(p => `L ${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join(" ") + ` L ${pts[n - 1][0].toFixed(1)} ${(PT + ih).toFixed(1)} Z` : null;
    return { ...s, pts, line, area };
  });
  const labelIdx = n <= 7 ? labels.map((_, i) => i) : [0, Math.floor((n - 1) / 2), n - 1];
  return (
    <div>
      {series.length > 1 && (
        <div style={{ display: "flex", gap: 14, marginBottom: 10 }}>
          {series.map(s => <span key={s.name} style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 11, color: "rgba(233,238,255,.6)" }}><span style={{ width: 9, height: 9, borderRadius: 3, background: s.color }} />{s.name}</span>)}
        </div>
      )}
      <div style={{ position: "relative" }}>
        <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={height} preserveAspectRatio="none" style={{ display: "block", overflow: "visible" }}>
          <defs>{built.map((s, si) => s.area && <linearGradient key={si} id={`itg${si}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={s.color} stopOpacity="0.3" /><stop offset="100%" stopColor={s.color} stopOpacity="0" /></linearGradient>)}</defs>
          {[0.5, 1].map((f, i) => <line key={i} x1={PL} x2={W - PR} y1={PT + ih - f * ih} y2={PT + ih - f * ih} stroke="rgba(255,255,255,.06)" strokeWidth="1" />)}
          {built.map((s, si) => s.area && <path key={si} d={s.area} fill={`url(#itg${si})`} />)}
          {built.map((s, si) => <path key={si} d={s.line} fill="none" stroke={s.color} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" opacity={s.fill ? 1 : 0.85} />)}
          {hi !== null && <line x1={X(hi)} x2={X(hi)} y1={PT} y2={PT + ih} stroke="rgba(255,255,255,.2)" strokeWidth="1" />}
          {hi !== null && built.map((s, si) => <circle key={si} cx={s.pts[hi][0]} cy={s.pts[hi][1]} r="4" fill="#fff" stroke={s.color} strokeWidth="2" vectorEffect="non-scaling-stroke" />)}
          {labels.map((d, i) => { const bw = iw / Math.max(1, n); return <rect key={i} x={X(i) - bw / 2} y={PT} width={bw} height={ih} fill="transparent" onMouseEnter={() => setHi(i)} onMouseLeave={() => setHi(null)} style={{ cursor: "crosshair" }} />; })}
        </svg>
        <div style={{ position: "relative", height: 14, marginTop: 4 }}>
          {labelIdx.map(i => <span key={i} style={{ position: "absolute", left: `${(X(i) / W) * 100}%`, transform: "translateX(-50%)", fontSize: 9.5, color: "rgba(233,238,255,.35)", whiteSpace: "nowrap" }}>{labels[i]}</span>)}
        </div>
        {hi !== null && (
          <div style={{ position: "absolute", top: -6, left: `${(X(hi) / W) * 100}%`, transform: "translate(-50%,-100%)", pointerEvents: "none", background: "rgba(10,14,24,.96)", border: "1px solid rgba(255,255,255,.14)", borderRadius: 8, padding: "6px 10px", whiteSpace: "nowrap", fontSize: 11, boxShadow: "0 8px 20px rgba(0,0,0,.5)", minWidth: 120 }}>
            <div style={{ color: "rgba(233,238,255,.5)", marginBottom: 4 }}>{labels[hi]}</div>
            {series.map(s => <div key={s.name} style={{ display: "flex", alignItems: "center", gap: 7, marginTop: 2 }}><span style={{ width: 7, height: 7, borderRadius: 2, background: s.color }} /><span style={{ color: "rgba(233,238,255,.6)" }}>{s.name}</span><b style={{ color: "#fff", marginLeft: "auto", paddingLeft: 14, fontVariantNumeric: "tabular-nums" }}>{s.data[hi]}</b></div>)}
          </div>
        )}
      </div>
    </div>
  );
}

function InsightOverviewTab({ log, returnsLog, productPhotoMap, filterStart, filterEnd, filterLabel, orders, filterMode, filterDate, category = "both" }) {
  // Phase 12D: every reads-from-log path also filters by category. Live-order
  // paths (today's day-mode branch) filter by category at point-of-use below.
  const catMatch = (entry) => category === "both" || inferProductType(entry) === category;
  const periodLog = useMemo(
    () => log.filter(e => e.timestamp >= filterStart && e.timestamp < filterEnd && catMatch(e)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [log, filterStart, filterEnd, category]
  );
  const filteredReturns = useMemo(
    () => returnsLog.filter(r => (r.timestamp||"") >= filterStart && (r.timestamp||"") < filterEnd && catMatch(r)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [returnsLog, filterStart, filterEnd, category]
  );
  const isToday = filterMode === "day" && filterDate === getSADateString();

  // Net Sales + OOS both read insights_log for EVERY period (incl. today) via the
  // shared helpers, so today reconciles with the historical days. The former
  // live-orders "today" paths drifted: OOS undercounted (auto-collect drained
  // status===OUT_OF_STOCK) and Net Sales OVER-counted (an auto-collected OOS
  // order flips to COLLECTED and was wrongly counted as a sale). "ready" /
  // "out_of_stock" log events are immutable and never cross over.
  const netSales = useMemo(
    () => readyEventsForPeriod({ log, returnsLog, filterStart, filterEnd, category }),
    [log, returnsLog, filterStart, filterEnd, category]
  );
  const oosLog = useMemo(
    () => oosEventsForPeriod({ log, returnsLog, filterStart, filterEnd, category }),
    [log, returnsLog, filterStart, filterEnd, category]
  );
  const topProd  = useMemo(() => groupCount(netSales, e => e.productName)[0], [netSales]);
  const hourData = useMemo(() => {
    const counts = {};
    netSales.forEach(e => { const h=new Date(e.timestamp).getHours(); counts[h]=(counts[h]||0)+1; });
    return Array.from({length:24},(_,h)=>({ label:`${h%12||12}${h<12?"am":"pm"}`, value:counts[h]||0 })).filter(c=>c.value>0);
  }, [netSales]);
  const topHour = hourData.reduce((b,c)=>c.value>(b?.value||0)?c:b, null);
  const topProducts = useMemo(() => groupCount(netSales, e => e.productName).slice(0, 7), [netSales]);
  // Aligned net-sales vs out-of-stock over time (hourly today, daily otherwise) —
  // one x-axis, one unit (order counts), so it's a legit two-series overlay.
  const series = useMemo(() => {
    const saDay = ts => new Date(new Date(ts).getTime() + 7200000).toISOString().slice(0, 10);
    const keyOf = ts => isToday ? new Date(ts).getHours() : saDay(ts);
    const labelOf = k => isToday ? `${k % 12 || 12}${k < 12 ? "a" : "p"}` : String(k).slice(5).replace("-", "/");
    const cs = {}, co = {}, set = new Set();
    netSales.forEach(e => { const k = keyOf(e.timestamp); set.add(k); cs[k] = (cs[k] || 0) + 1; });
    oosLog.forEach(e => { const k = keyOf(e.timestamp); set.add(k); co[k] = (co[k] || 0) + 1; });
    let keys = [...set];
    if (!keys.length) return { labels: [], sales: [], oos: [] };
    if (isToday) { const nums = keys.map(Number); const lo = Math.min(8, ...nums), hi = Math.max(18, ...nums); keys = []; for (let h = lo; h <= hi; h++) keys.push(h); }
    else { keys.sort(); const end = new Date(keys[keys.length - 1] + "T00:00:00Z"); const minStart = new Date(end); minStart.setUTCDate(minStart.getUTCDate() - 91); let d = new Date(keys[0] + "T00:00:00Z"); if (d < minStart) d = minStart; /* cap daily bars at the most RECENT ~92 days (anchored to end) — a long Year/All-Time window shows current activity instead of silently truncating to the oldest 92 days */ const out = []; while (d <= end) { out.push(d.toISOString().slice(0, 10)); d.setUTCDate(d.getUTCDate() + 1); } keys = out; }
    return { labels: keys.map(labelOf), sales: keys.map(k => cs[k] || 0), oos: keys.map(k => co[k] || 0) };
  }, [netSales, oosLog, isToday]);
  // Period-over-period deltas vs the previous equal-length window.
  const deltas = useMemo(() => {
    const a = new Date(filterStart).getTime(), b = new Date(filterEnd).getTime();
    if (!(b > a)) return null;
    const pStart = new Date(a - (b - a)).toISOString(), pEnd = filterStart;
    const cm = e => category === "both" || inferProductType(e) === category;
    return {
      net: readyEventsForPeriod({ log, returnsLog, filterStart: pStart, filterEnd: pEnd, category }).length,
      oos: oosEventsForPeriod({ log, returnsLog, filterStart: pStart, filterEnd: pEnd, category }).length,
      ret: returnsLog.filter(r => (r.timestamp || "") >= pStart && (r.timestamp || "") < pEnd && cm(r)).length,
    };
  }, [log, returnsLog, filterStart, filterEnd, category]);
  const pct = (cur, prev) => prev > 0 ? Math.round((cur - prev) / prev * 100) : null;
  const lostPct = (netSales.length + oosLog.length) > 0 ? Math.round(oosLog.length / (netSales.length + oosLog.length) * 100) : 0;
  const maxHour = Math.max(1, ...hourData.map(h => h.value));
  const GLASS_STOCK = { background: "rgba(255,255,255,.022)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 16 };

  const kpi = (color, glyph, value, label, sub, dv, goodUp) => {
    const show = deltas && dv !== null && dv !== 0;
    const good = (dv > 0) === goodUp;
    return (
      <div style={{ ...GLASS_STOCK, padding: "15px 16px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 11, marginBottom: 9 }}>
          <span style={{ width: 40, height: 40, flexShrink: 0, borderRadius: 11, display: "grid", placeItems: "center", background: `${color}22`, border: `1px solid ${color}55`, color, overflow: "hidden" }}>{glyph}</span>
          <div style={{ fontSize: 30, fontWeight: 800, color: "#fff", letterSpacing: "-.02em", lineHeight: 1, fontVariantNumeric: "tabular-nums" }}>{value}</div>
          {show && <span style={{ marginLeft: "auto", fontSize: 11.5, fontWeight: 800, color: good ? "#4ADE80" : "#F87171", fontVariantNumeric: "tabular-nums" }}>{dv > 0 ? "▲" : "▼"} {Math.abs(dv)}%</span>}
        </div>
        <div style={{ fontSize: 12.5, fontWeight: 700, color: "#fff" }}>{label}</div>
        <div style={{ fontSize: 10.5, color: "rgba(233,238,255,.4)", marginTop: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{sub}{deltas ? " · vs prev" : ""}</div>
      </div>
    );
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      {/* KPI tiles */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(158px, 1fr))", gap: 12 }}>
        {kpi("#4ADE80", <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M6 2L3 6v14a2 2 0 002 2h14a2 2 0 002-2V6l-3-4z" /><line x1="3" y1="6" x2="21" y2="6" /><path d="M16 10a4 4 0 01-8 0" /></svg>, netSales.length, "Net Sales", "Ready − Returns", pct(netSales.length, deltas?.net), true)}
        {kpi("#F87171", <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 16V8a2 2 0 00-1-1.73l-7-4a2 2 0 00-2 0l-7 4A2 2 0 003 8v8a2 2 0 001 1.73l7 4a2 2 0 002 0l7-4A2 2 0 0021 16z" /><polyline points="3.27 6.96 12 12.01 20.73 6.96" /><line x1="12" y1="22.08" x2="12" y2="12" /></svg>, oosLog.length, "Out of Stock", filterLabel, pct(oosLog.length, deltas?.oos), false)}
        {kpi("#4A7FFF", <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="1 4 1 10 7 10" /><path d="M3.51 15a9 9 0 102.13-9.36L1 10" /></svg>, filteredReturns.length, "Returns", filterLabel, pct(filteredReturns.length, deltas?.ret), false)}
        <div style={{ ...GLASS_STOCK, padding: "15px 16px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 11, marginBottom: 9 }}>
            <span style={{ width: 40, height: 40, flexShrink: 0, borderRadius: 11, display: "grid", placeItems: "center", background: "rgba(255,255,255,.05)", border: "1px solid rgba(255,255,255,.12)", overflow: "hidden" }}>
              {topProd ? <ProductThumb name={topProd.label} photoMap={productPhotoMap} size={40} /> : <ProductIcon size={20} />}
            </span>
            <div style={{ fontSize: 30, fontWeight: 800, color: "#fff", letterSpacing: "-.02em", lineHeight: 1, fontVariantNumeric: "tabular-nums" }}>{topProd?.value || "—"}</div>
          </div>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#fff" }}>Top Product</div>
          <div style={{ fontSize: 10.5, color: "rgba(233,238,255,.4)", marginTop: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{topProd?.label || "No orders yet"}</div>
        </div>
      </div>

      {/* Insight strip — demand lost to out-of-stock. */}
      {oosLog.length > 0 && (
        <div style={{ display: "flex", alignItems: "center", gap: 13, padding: "13px 16px", borderRadius: 14, background: "linear-gradient(90deg, rgba(248,113,113,.12), rgba(255,255,255,.02))", border: "1px solid rgba(248,113,113,.3)" }}>
          <span style={{ width: 34, height: 34, flexShrink: 0, borderRadius: 10, display: "grid", placeItems: "center", background: "rgba(248,113,113,.16)", border: "1px solid rgba(248,113,113,.4)", color: "#F87171" }}>
            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" /><line x1="12" y1="9" x2="12" y2="13" /><line x1="12" y1="17" x2="12.01" y2="17" /></svg>
          </span>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: "#fff" }}>Lost to out-of-stock</div>
            <div style={{ fontSize: 11.5, color: "rgba(233,238,255,.55)" }}><b style={{ color: "#F87171" }}>{oosLog.length}</b> orders couldn't be filled — that's <b style={{ color: "#fff" }}>{lostPct}%</b> of demand this period.</div>
          </div>
        </div>
      )}

      {/* Sales vs OOS trend (hero) */}
      <div style={{ ...GLASS_STOCK, padding: "16px 17px 12px" }}>
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 12 }}>
          <div style={{ fontSize: 13.5, fontWeight: 750, color: "#fff" }}>Sales vs out-of-stock <span style={{ color: "rgba(233,238,255,.4)", fontWeight: 600 }}>· {filterLabel}</span></div>
          <div style={{ fontSize: 11.5, color: "rgba(233,238,255,.5)" }}>{netSales.length} sold{topHour ? ` · peak ${topHour.label.toUpperCase()}` : ""}</div>
        </div>
        <InsightTrendChart labels={series.labels} series={[
          { name: "Net sales", color: "#4A7FFF", data: series.sales, fill: true },
          { name: "Out of stock", color: "#F87171", data: series.oos },
        ]} />
      </div>

      {/* Top products + busiest hours */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 14 }}>
        <div style={{ ...GLASS_STOCK, padding: "16px 17px" }}>
          <div style={{ fontSize: 13.5, fontWeight: 750, color: "#fff", marginBottom: 12 }}>Top products</div>
          <InsightBarChart items={topProducts} color={BLUE} emptyMsg="No sales yet" photoMap={productPhotoMap} />
        </div>
        <div style={{ ...GLASS_STOCK, padding: "16px 17px" }}>
          <div style={{ fontSize: 13.5, fontWeight: 750, color: "#fff", marginBottom: 14 }}>Busiest hours</div>
          {hourData.length === 0 ? <div style={{ color: "rgba(233,238,255,.3)", textAlign: "center", padding: "1.5rem", fontSize: 13 }}>No sales yet.</div> : (
            <div style={{ display: "flex", alignItems: "flex-end", gap: 5, height: 120 }}>
              {hourData.map((h, i) => {
                const peak = topHour && h.label === topHour.label;
                return (
                  <div key={i} title={`${h.label} · ${h.value}`} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 5, minWidth: 0 }}>
                    <div style={{ fontSize: 9, color: peak ? "#9DBCFF" : "rgba(233,238,255,.35)", fontWeight: 700 }}>{h.value}</div>
                    <div style={{ width: "100%", height: `${Math.max(4, (h.value / maxHour) * 92)}px`, borderRadius: "4px 4px 2px 2px", background: peak ? "linear-gradient(180deg,#6A9FFF,#4A7FFF)" : "rgba(74,127,255,.35)" }} />
                    <div style={{ fontSize: 8.5, color: "rgba(233,238,255,.3)", whiteSpace: "nowrap" }}>{h.label}</div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* Recent activity */}
      <div style={{ ...GLASS_STOCK, padding: "16px 17px" }}>
        <div style={{ fontSize: 13.5, fontWeight: 750, color: "#fff", marginBottom: 10 }}>Recent activity <span style={{ color: "rgba(233,238,255,.35)", fontWeight: 600 }}>· {filterLabel}</span></div>
        {periodLog.length === 0
          ? <div style={{ color: "rgba(233,238,255,.3)", textAlign: "center", padding: "1.5rem", fontSize: 13 }}>No activity in this period.</div>
          : periodLog.slice(0, 30).map((e, i) => {
              const ac = INSIGHT_ACTION[e.action] || { color: "#888", bg: "rgba(255,255,255,.06)", label: e.action };
              return (
                <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "8px 0", borderTop: i ? "1px solid rgba(255,255,255,.06)" : "none" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
                    <ProductThumb name={e.productName} photoMap={productPhotoMap} size={34} />
                    <div style={{ minWidth: 0 }}>
                      <span style={{ fontWeight: 600, color: "#fff", fontSize: "0.88rem" }}>{e.productName}</span>
                      <span style={{ color: "rgba(233,238,255,.35)", marginLeft: "0.4rem", fontSize: "0.78rem" }}>Sz {e.size}</span>
                      <span style={{ marginLeft: "0.4rem", background: ac.bg, color: ac.color, borderRadius: "999px", padding: "1px 8px", fontSize: "0.7rem", fontWeight: 700 }}>{ac.label}</span>
                    </div>
                  </div>
                  <div style={{ color: "rgba(233,238,255,.35)", fontSize: "0.72rem", whiteSpace: "nowrap", flexShrink: 0 }}>
                    #{e.orderNumber} · {new Date(e.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
                  </div>
                </div>
              );
            })}
      </div>
    </div>
  );
}

// ─── INSIGHTS: PRODUCT SEARCH TAB ────────────────────────────────────────────
function InsightProductSearchTab({ log, productPhotoMap, filterStart, filterEnd, category = "both" }) {
  const [query,  setQuery]  = useState("");

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const catMatch = (e) => category === "both" || inferProductType(e) === category;
    return log.filter(e =>
      e.timestamp >= filterStart && e.timestamp < filterEnd &&
      catMatch(e) &&
      (q==="" || (e.productName||"").toLowerCase().includes(q))
    );
  }, [log, query, filterStart, filterEnd, category]);

  const placedFiltered  = useMemo(() => filtered.filter(e=>e.action==="placed"), [filtered]);
  const productCounts   = useMemo(() => groupCount(placedFiltered, e=>e.productName), [placedFiltered]);
  const sizeCounts      = useMemo(() => groupCount(placedFiltered, e=>`Size ${formatSize(e.size)}`), [placedFiltered]);

  return (
    <div>
      <div style={{ display:"flex", gap:"0.75rem", marginBottom:"1rem", flexWrap:"wrap" }}>
        <input placeholder="Search product name…" value={query} onChange={e=>setQuery(e.target.value)}
          style={{ ...inputStyle, flex:1, minWidth:"180px" }} />
      </div>
      {query.trim() && (
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:"1rem", marginBottom:"1rem" }}>
          <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:RADIUS, padding:"1.25rem" }}>
            <div style={{ fontWeight:"700", marginBottom:"0.75rem", color:"#fff", fontSize:"0.9rem" }}>Orders by Product</div>
            <InsightBarChart items={productCounts} color={BLUE} emptyMsg="No orders found" photoMap={productPhotoMap} />
          </div>
          <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:RADIUS, padding:"1.25rem" }}>
            <div style={{ fontWeight:"700", marginBottom:"0.75rem", color:"#fff", fontSize:"0.9rem" }}>Size Breakdown</div>
            <InsightBarChart items={sizeCounts} color="#4A7FFF" emptyMsg="No orders found" />
          </div>
        </div>
      )}
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:RADIUS, padding:"1.25rem" }}>
        <div style={{ fontWeight:"700", marginBottom:"0.75rem", color:"#fff", fontSize:"0.9rem" }}>
          Order History {query?`· "${query}"`:""}
          <span style={{ color:"#555", marginLeft:"0.5rem", fontWeight:"400", fontSize:"0.8rem" }}>{filtered.length} entries</span>
        </div>
        {filtered.length===0
          ? <div style={{ color:"#444", textAlign:"center", padding:"2rem", fontSize:"0.9rem" }}>No orders found</div>
          : <div style={{ maxHeight:"420px", overflowY:"auto" }}>
              {filtered.map((e,i)=>{
                const ac=INSIGHT_ACTION[e.action]||{color:"#666",bg:"#333",label:e.action};
                return (
                  <div key={i} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"0.5rem 0", borderBottom:"1px solid rgba(60,110,255,.08)" }}>
                    <div style={{ display:"flex", alignItems:"center", gap:"0.45rem" }}>
                      <ProductThumb name={e.productName} photoMap={productPhotoMap} size={32} />
                      <div>
                        <span style={{ fontWeight:"600", color:"#fff", fontSize:"0.85rem" }}>{e.productName}</span>
                        <span style={{ color:"#555", fontSize:"0.78rem", marginLeft:"0.4rem" }}>Sz {e.size}</span>
                        <span style={{ marginLeft:"0.4rem", background:ac.bg, color:ac.color, borderRadius:"999px", padding:"1px 7px", fontSize:"0.7rem", fontWeight:"600" }}>{ac.label}</span>
                      </div>
                    </div>
                    <div style={{ textAlign:"right" }}>
                      <div style={{ color:"#888", fontSize:"0.75rem" }}>{e.customerName}</div>
                      <div style={{ color:"#555", fontSize:"0.7rem" }}>{new Date(e.timestamp).toLocaleString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}</div>
                    </div>
                  </div>
                );
              })}
            </div>
        }
      </div>
    </div>
  );
}

// ─── INSIGHTS: OOS TRACKER TAB ────────────────────────────────────────────────
function InsightOOSTrackerTab({ log, returnsLog, productPhotoMap, filterStart, filterEnd, filterLabel, category = "both" }) {
  // OOS count for EVERY period (incl. today) reads the immutable insights_log
  // (action==="out_of_stock") within [filterStart, filterEnd).
  //
  // This replaces a former today-only branch that derived from LIVE orders
  // filtered by *current* status===OUT_OF_STOCK. That undercounted today: the
  // 8-min TV auto-collect sweep flips OOS→collected, so most of the day's OOS
  // orders had already left OUT_OF_STOCK and dropped out of the count (e.g. 60
  // events → 1 shown). insights_log records every OOS transition (sneaker AND
  // clothing — clothing OOS is logged with action "out_of_stock" by
  // setClothingRefillStatus), so today now matches the historical days exactly.
  // dedupe-by-orderNumber (a flapped order counts once) + exclude returned
  // orderNumbers (if ultimately returned, its OOS transitions don't count —
  // same rule as Net Sales).
  const oosLog = useMemo(
    () => oosEventsForPeriod({ log, returnsLog, filterStart, filterEnd, category }),
    [log, returnsLog, filterStart, filterEnd, category]
  );
  const [openProduct, setOpenProduct] = useState(null);

  // Group OOS events by product, then by size
  const byProductData = useMemo(() => {
    const map = {};
    oosLog.forEach(e => {
      const name = e.productName || "Unknown";
      if (!map[name]) map[name] = { name, total: 0, sizes: {} };
      map[name].total += 1;
      const sz = e.size || "—";
      map[name].sizes[sz] = (map[name].sizes[sz] || 0) + 1;
    });
    return Object.values(map).sort((a, b) => b.total - a.total);
  }, [oosLog]);

  const totalOOS = oosLog.length;

  if (oosLog.length === 0) {
    return (
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:"3rem", textAlign:"center", color:"rgba(255,255,255,.4)", fontSize:14 }}>
        <ProductIcon size={32} opacity={0.4}/>
        <div style={{ marginTop:12 }}>No out-of-stock events in this period</div>
      </div>
    );
  }

  return (
    <div>
      {/* SUMMARY BOX */}
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(74,127,255,.35)", borderRadius:14, padding:"16px 18px", marginBottom:12, display:"flex", alignItems:"center", gap:14, boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
        <div style={{ fontWeight:800, fontSize:42, color:"#4A7FFF", lineHeight:1, letterSpacing:"-1.5px" }}>{totalOOS}</div>
        <div style={{ flex:1 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Total Out of Stock</div>
          <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:2 }}>{byProductData.length} product{byProductData.length !== 1 ? "s" : ""} affected · {filterLabel}</div>
        </div>
      </div>

      {/* PRODUCT LIST — collapsible rows */}
      <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
        {byProductData.map(p => {
          const isOpen = openProduct === p.name;
          const sizes = Object.entries(p.sizes).sort((a, b) => b[1] - a[1]);
          return (
            <div key={p.name} style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:12, overflow:"hidden", transition:"all 0.2s" }}>
              <div onClick={() => setOpenProduct(isOpen ? null : p.name)}
                   style={{ display:"flex", alignItems:"center", padding:"12px 14px", cursor:"pointer", gap:12 }}>
                <ProductThumb name={p.name} photoMap={productPhotoMap} size={36}/>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontWeight:700, fontSize:14, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{p.name}</div>
                  <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:2 }}>{Object.keys(p.sizes).length} size{Object.keys(p.sizes).length !== 1 ? "s" : ""} affected</div>
                </div>
                <div style={{ background:"rgba(60,110,255,.15)", color:"#4A7FFF", border:"1px solid rgba(255,255,255,.08)", borderRadius:999, padding:"4px 12px", fontSize:13, fontWeight:700 }}>{p.total}</div>
                <span style={{ color:"#4A7FFF", fontSize:14, transition:"transform 0.2s", display:"inline-block", transform: isOpen ? "rotate(90deg)" : "rotate(0deg)" }}>›</span>
              </div>
              {isOpen && (
                <div style={{ borderTop:"1px solid rgba(60,110,255,.1)", padding:"10px 14px 14px", display:"flex", flexWrap:"wrap", gap:6 }}>
                  {sizes.map(([size, count]) => (
                    <div key={size} style={{ background:"rgba(60,110,255,.08)", border:"1px solid rgba(255,255,255,.08)", borderRadius:8, padding:"6px 10px", display:"flex", alignItems:"center", gap:6 }}>
                      <span style={{ fontSize:12, fontWeight:700, color:"#fff" }}>Size <SizeTag size={size} /></span>
                      <span style={{ background:"rgba(60,110,255,.2)", color:"#4A7FFF", borderRadius:999, padding:"2px 7px", fontSize:10, fontWeight:700 }}>×{count}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── INSIGHTS: SIZE POPULARITY TAB ───────────────────────────────────────────
// Phase 12D correction: respects the global Sneaker/Clothing/Both toggle and
// drops entries with no size (Display / Display Partner orders are
// legitimately size-less but used to show up as a "Size undefined" bucket).
// In "Both" mode, sneaker and clothing sizes render as two separate charts
// with their own normalization — the two size systems (numeric 3..11 and
// letters S..XXXL) don't share a meaningful axis.
function InsightSizePopularityTab({ log, filterStart, filterEnd, filterLabel, category = "both" }) {
  const [catFilter, setCat] = useState("all");
  const catMatch = (e) => category === "both" || inferProductType(e) === category;

  // Demand histogram, NOT fulfilment. Counts `action === "placed"` events
  // (one per cart line at checkout). A subsequent return doesn't erase the
  // customer's expressed intent, so we deliberately do not exclude returned
  // orderNumbers here — but we DO dedupe by orderNumber so a duplicate
  // `placed` write (rare but possible) doesn't inflate the histogram.
  const placed = useMemo(
    () => {
      const raw = log.filter(e => e.action === "placed" && e.timestamp >= filterStart && e.timestamp < filterEnd && e.size && catMatch(e));
      return dedupeByOrderNumber(raw);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [log, filterStart, filterEnd, category]
  );
  const cats   = useMemo(() => ["all", ...new Set(placed.map(e => e.productCategory).filter(Boolean))], [placed]);
  const subset = useMemo(() => catFilter === "all" ? placed : placed.filter(e => e.productCategory === catFilter), [placed, catFilter]);

  // Split by productType so each chart bucketizes only its own size system.
  const sneakerSizes = useMemo(() => {
    const grouped = groupCount(subset.filter(e => inferProductType(e) === "sneaker"), e => e.size);
    return grouped.sort((a, b) => parseFloat(a.label) - parseFloat(b.label));
  }, [subset]);
  const clothingSizes = useMemo(() => {
    const grouped = groupCount(subset.filter(e => inferProductType(e) === "clothing"), e => e.size);
    return grouped.sort((a, b) => CLOTHING_SIZES.indexOf(a.label) - CLOTHING_SIZES.indexOf(b.label));
  }, [subset]);

  const showSneaker  = (category === "sneaker"  || category === "both") && sneakerSizes.length > 0;
  const showClothing = (category === "clothing" || category === "both") && clothingSizes.length > 0;

  // One bar chart panel — shared by both sneaker and clothing renders. Each
  // panel normalizes to its own max so a small clothing group doesn't appear
  // dwarfed by a busy sneaker group when both are shown side-by-side.
  const Panel = ({ heading, sizes }) => {
    const max = sizes.length ? Math.max(...sizes.map(s => s.value)) : 1;
    return (
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:18 }}>
        <div style={{ marginBottom:14 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>{heading}</div>
          <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:2 }}>{catFilter === "all" ? "All categories" : catFilter} · {sizes.reduce((n, s) => n + s.value, 0)} order{sizes.reduce((n, s) => n + s.value, 0) !== 1 ? "s" : ""} placed</div>
        </div>
        <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
          {sizes.map(({ label, value }) => {
            const isPeak = value === max;
            const pct = (value / max) * 100;
            return (
              <div key={label} style={{ display:"flex", alignItems:"center", gap:12 }}>
                <div style={{ width:64, color: isPeak ? "#fff" : "rgba(255,255,255,.7)", fontSize:13, fontWeight: isPeak ? 700 : 500 }}>
                  Size <SizeTag size={label} />
                </div>
                <div style={{ flex:1, position:"relative", height:24, background:"rgba(60,110,255,.05)", borderRadius:6, overflow:"hidden" }}>
                  <div style={{
                    width:`${Math.max(2, pct)}%`,
                    height:"100%",
                    background: isPeak
                      ? "linear-gradient(90deg, rgba(60,110,255,.85), rgba(60,110,255,.3))"
                      : "linear-gradient(90deg, rgba(60,110,255,.6), rgba(60,110,255,.2))",
                    boxShadow: isPeak ? "0 0 10px rgba(60,110,255,.5)" : "none",
                    borderRadius:6,
                    transition:"width 0.4s",
                  }}/>
                </div>
                <div style={{ width:36, textAlign:"right", color: isPeak ? "#4A7FFF" : "rgba(255,255,255,.7)", fontSize:14, fontWeight: isPeak ? 800 : 600 }}>{value}</div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div>
      {/* productCategory free-text pills (existing) — orthogonal to the
          global productType toggle and cascade after it. */}
      <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:14 }}>
        {cats.map(cat => {
          const on = catFilter === cat;
          return (
            <button key={cat} onClick={() => setCat(cat)}
                    style={{ padding:"6px 14px", borderRadius:999, border: on ? "1px solid rgba(60,110,255,.5)" : "1px solid rgba(255,255,255,.1)", background: on ? "rgba(60,110,255,.15)" : "rgba(255,255,255,.04)", color: on ? "#4A7FFF" : "rgba(255,255,255,.5)", cursor:"pointer", fontWeight:600, fontSize:12, textTransform:"capitalize" }}>
              {cat}
            </button>
          );
        })}
      </div>

      {/* No data in either group → single empty state. */}
      {!showSneaker && !showClothing && (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:"3rem", textAlign:"center", color:"rgba(255,255,255,.4)", fontSize:14 }}>
          No orders in this period
        </div>
      )}

      {/* Demand-vs-fulfilment clarification — this tab counts cart checkouts
          (action === "placed"), NOT ready / collected sales. The label makes
          the distinction explicit so the totals here aren't mis-read against
          the Sales Summary / Overview · Net Sales totals. */}
      <div style={{ background:"rgba(60,110,255,.05)", border:"1px solid rgba(60,110,255,.18)", borderRadius:10, padding:"8px 12px", marginBottom:12, color:"rgba(255,255,255,.55)", fontSize:11, lineHeight:1.45 }}>
        Counts orders <strong style={{ color:"#fff" }}>placed at checkout</strong> (demand) — not ready / collected sales. A return doesn't erase the original demand, so totals here will differ from Net Sales.
      </div>

      {/* Two panels in Both mode; one panel in single-category mode. Heading
          carries the "(by demand)" suffix so the metric is unambiguous even
          when the user lands on this tab without reading the intro card. */}
      <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
        {showSneaker && (
          <Panel heading={category === "both" ? "Sneaker Sizes (by demand)" : "Size Popularity (by demand)"} sizes={sneakerSizes} />
        )}
        {showClothing && (
          <Panel heading={category === "both" ? "Clothing Sizes (by demand)" : "Size Popularity (by demand)"} sizes={clothingSizes} />
        )}
      </div>
    </div>
  );
}

// ─── INSIGHTS: BUSIEST TIMES TAB ─────────────────────────────────────────────
function InsightBusiestTimesTab({ log, filterStart, filterEnd, filterLabel, category = "both" }) {
  // Same dedupe rule as Size Popularity — one placed event per orderNumber,
  // so a double-fire checkout doesn't bias the hour/day histograms.
  const placed = useMemo(() => {
    const catMatch = (e) => category === "both" || inferProductType(e) === category;
    const raw = log.filter(e => e.action === "placed" && e.timestamp >= filterStart && e.timestamp < filterEnd && catMatch(e));
    return dedupeByOrderNumber(raw);
  }, [log, filterStart, filterEnd, category]);

  // Build all 24 hours (8am-8pm shown), use full hour granularity
  const hourData = useMemo(() => {
    const counts = {};
    placed.forEach(e => { const h=new Date(e.timestamp).getHours(); counts[h]=(counts[h]||0)+1; });
    return Array.from({length:24},(_,h)=>({
      hour: h,
      label: `${h%12||12}${h<12?"a":"p"}`,
      value: counts[h] || 0,
    }));
  }, [placed]);
  const hourMax = Math.max(...hourData.map(d => d.value), 1);
  const peakHour = hourData.reduce((b, c) => c.value > (b?.value || 0) ? c : b, null);

  const DAYS = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
  const dayData = useMemo(() =>
    DAYS.map((label,d)=>({ label, value:placed.filter(e=>new Date(e.timestamp).getDay()===d).length })),
  [placed]);
  const dayMax = Math.max(...dayData.map(d => d.value), 1);
  const peakDay = dayData.reduce((b, c) => c.value > (b?.value || 0) ? c : b, null);

  return (
    <div>
      {/* BUSIEST HOURS — vertical bar chart */}
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:18, marginBottom:12 }}>
        <div style={{ marginBottom:14 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Busiest Hours</div>
          <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:2 }}>
            {placed.length === 0
              ? "No orders in this period"
              : <>Peak hour: <span style={{ color:"#4A7FFF", fontWeight:700 }}>{peakHour ? `${peakHour.hour % 12 || 12}${peakHour.hour < 12 ? "AM" : "PM"}` : "—"}</span> · {placed.length} order{placed.length !== 1 ? "s" : ""} total</>}
          </div>
        </div>
        {placed.length > 0 && (
          <div>
            <div style={{ display:"flex", alignItems:"flex-end", gap:3, height:140, padding:"0 4px" }}>
              {hourData.map(d => {
                const isPeak = d.value === hourMax && d.value > 0;
                const pct = d.value === 0 ? 0 : Math.max(6, (d.value / hourMax) * 100);
                return (
                  <div key={d.hour} title={`${d.label} — ${d.value} order${d.value !== 1 ? "s" : ""}`}
                       style={{ flex:1, height:"100%", display:"flex", flexDirection:"column", justifyContent:"flex-end", alignItems:"center" }}>
                    <div style={{
                      width:"100%",
                      height:`${pct}%`,
                      background: d.value === 0 ? "rgba(60,110,255,.04)" : isPeak ? "linear-gradient(180deg, rgba(60,110,255,1), rgba(60,110,255,.4))" : "linear-gradient(180deg, rgba(60,110,255,.55), rgba(60,110,255,.15))",
                      borderRadius:"4px 4px 0 0",
                      boxShadow: isPeak ? "0 0 12px rgba(60,110,255,.6)" : "none",
                      transition:"height 0.4s",
                    }}/>
                  </div>
                );
              })}
            </div>
            <div style={{ display:"flex", gap:3, marginTop:6, padding:"0 4px" }}>
              {hourData.map(d => (
                <div key={d.hour} style={{ flex:1, textAlign:"center", color: d.value === hourMax && d.value > 0 ? "#4A7FFF" : "rgba(255,255,255,.3)", fontSize:9, fontWeight: d.value === hourMax && d.value > 0 ? 700 : 500 }}>
                  {d.hour % 3 === 0 ? d.label : ""}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* BUSIEST DAYS */}
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:18 }}>
        <div style={{ marginBottom:14 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Busiest Days</div>
          <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:2 }}>
            {placed.length === 0
              ? "No orders in this period"
              : <>Peak day: <span style={{ color:"#4A7FFF", fontWeight:700 }}>{peakDay?.value > 0 ? peakDay.label : "—"}</span></>}
          </div>
        </div>
        <div style={{ display:"flex", alignItems:"flex-end", gap:8, height:120 }}>
          {dayData.map(d => {
            const isPeak = d.value === dayMax && d.value > 0;
            const pct = d.value === 0 ? 0 : Math.max(8, (d.value / dayMax) * 100);
            return (
              <div key={d.label} style={{ flex:1, height:"100%", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"flex-end" }}>
                <div style={{ color: isPeak ? "#4A7FFF" : "rgba(255,255,255,.5)", fontSize:11, fontWeight: isPeak ? 700 : 500, marginBottom:4 }}>{d.value}</div>
                <div style={{
                  width:"100%",
                  height:`${pct}%`,
                  background: d.value === 0 ? "rgba(60,110,255,.04)" : isPeak ? "linear-gradient(180deg, rgba(60,110,255,1), rgba(60,110,255,.4))" : "linear-gradient(180deg, rgba(60,110,255,.55), rgba(60,110,255,.15))",
                  borderRadius:"6px 6px 0 0",
                  boxShadow: isPeak ? "0 0 12px rgba(60,110,255,.6)" : "none",
                  transition:"height 0.4s",
                }}/>
                <div style={{ color: isPeak ? "#4A7FFF" : "rgba(255,255,255,.4)", fontSize:11, fontWeight: isPeak ? 700 : 500, marginTop:6 }}>{d.label}</div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ─── INSIGHTS: RETURNS TAB ───────────────────────────────────────────────────
function InsightReturnsTab({ returnsLog, productPhotoMap, filterStart, filterEnd, filterLabel, category = "both" }) {
  const filtered = useMemo(() => {
    const catMatch = (r) => category === "both" || inferProductType(r) === category;
    return returnsLog.filter(r => (r.timestamp||"") >= filterStart && (r.timestamp||"") < filterEnd && catMatch(r));
  }, [returnsLog, filterStart, filterEnd, category]);
  const byProduct = useMemo(() => groupCount(filtered, r => r.productName || "Unknown"),  [filtered]);

  return (
    <div>
      {filtered.length === 0 ? (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:"3rem", textAlign:"center", color:"rgba(255,255,255,.4)", fontSize:14 }}>
          <ProductIcon size={32} opacity={0.4}/>
          <div style={{ marginTop:12 }}>No returns in this period</div>
        </div>
      ) : (
        <>
          {/* Summary card */}
          <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(74,127,255,.35)", borderRadius:14, padding:"16px 18px", marginBottom:12, display:"flex", alignItems:"center", gap:14, boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
            <div style={{ fontWeight:800, fontSize:42, color:"#4A7FFF", lineHeight:1, letterSpacing:"-1.5px" }}>{filtered.length}</div>
            <div style={{ flex:1 }}>
              <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Total Returns</div>
              <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:2 }}>Items logged via Returns view · {filterLabel}</div>
            </div>
          </div>

          {/* Most returned products bar chart */}
          <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:16, marginBottom:12 }}>
            <div style={{ fontWeight:700, marginBottom:12, color:"#fff", fontSize:13 }}>Most Returned Products</div>
            <InsightBarChart items={byProduct} color={BLUE} photoMap={productPhotoMap} />
          </div>

          {/* Return Log */}
          <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:16 }}>
            <div style={{ fontWeight:700, marginBottom:10, color:"#fff", fontSize:13 }}>Return Log <span style={{ color:"rgba(255,255,255,.4)", fontWeight:400, fontSize:11 }}>· {filtered.length} entries</span></div>
            <div style={{ maxHeight:"380px", overflowY:"auto" }}>
              {filtered.slice(0, 50).map((r, i) => (
                <div key={i} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"8px 0", borderBottom:"1px solid rgba(60,110,255,.08)" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                    <ProductThumb name={r.productName} photoMap={productPhotoMap} size={32} />
                    <div>
                      <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                        <span style={{ fontWeight:800, fontSize:14, color:"#6A9FFF", letterSpacing:"0.5px" }}>#{r.orderNumber}</span>
                        <span style={{ color:"#ccc", fontWeight:600, fontSize:13 }}>{r.productName}</span>
                      </div>
                      <span style={{ color:"rgba(255,255,255,.4)", fontSize:11 }}>Size <SizeTag size={r.size} /></span>
                    </div>
                  </div>
                  <div style={{ textAlign:"right", flexShrink:0 }}>
                    <div style={{ color:"rgba(255,255,255,.5)", fontSize:11 }}>{r.customerName}</div>
                    <div style={{ color:"rgba(255,255,255,.3)", fontSize:10 }}>{new Date(r.timestamp).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

// ─── INSIGHTS: CLOTHING REFILLS TAB (Phase 12D) ───────────────────────────────
// Demand-signal view of every clothing refill request placed in the active
// date window. Filters orders by productType==="clothing" and createdAt
// inside [filterStart, filterEnd). Read-only. Filters by createdAt only —
// immutable — so historical periods aren't affected by later resolutions or
// undos. Aggregates by (productId, productName); each row shows total units
// requested, per-size breakdown, and last-requested timestamp.
function InsightClothingRefillsTab({ orders, log, productPhotoMap, filterStart, filterEnd, filterLabel, filterMode, filterDate }) {
  // TODAY reads live /orders (real-time, qty present); past windows read
  // insights_log "placed" clothing events — /orders rolls over daily, so the old
  // all-live-orders path undercounted closed windows. Both branches normalise to
  // { productName, size, qty, timestamp } via the shared helper.
  const isToday = filterMode === "day" && filterDate === getSADateString();
  const refillEvents = useMemo(
    () => clothingRefillEventsForPeriod({ isToday, orders, log, filterStart, filterEnd }),
    [isToday, orders, log, filterStart, filterEnd]
  );

  const rows = useMemo(() => {
    const map = {};
    refillEvents.forEach(e => {
      const key = e.productName || "Unknown";
      if (!map[key]) map[key] = { productName: key, total: 0, sizes: {}, lastAt: "" };
      map[key].total += e.qty;
      const sz = e.size || "—";
      map[key].sizes[sz] = (map[key].sizes[sz] || 0) + e.qty;
      if ((e.timestamp || "") > map[key].lastAt) map[key].lastAt = e.timestamp || "";
    });
    return Object.values(map).sort((a, b) => b.total - a.total || b.lastAt.localeCompare(a.lastAt));
  }, [refillEvents]);

  const totalUnits     = rows.reduce((n, r) => n + r.total, 0);
  const totalRequests  = refillEvents.length;
  const distinctProducts = rows.length;

  const fmtAgo = (iso) => {
    if (!iso) return "—";
    const mins = Math.floor((serverNowMs() - new Date(iso).getTime()) / 60000);
    if (mins < 1)    return "just now";
    if (mins < 60)   return `${mins}m ago`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24)    return `${hrs}h ago`;
    const days = Math.floor(hrs / 24);
    if (days < 30)   return `${days}d ago`;
    const months = Math.floor(days / 30);
    return `${months}mo ago`;
  };

  return (
    <div>
      {/* SUMMARY CARD — mirrors OOS Tracker visual */}
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(74,127,255,.35)", borderRadius:14, padding:"16px 18px", marginBottom:12, display:"flex", alignItems:"center", gap:14, boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
        <div style={{ fontWeight:800, fontSize:42, color:"#4A7FFF", lineHeight:1, letterSpacing:"-1.5px" }}>{totalUnits}</div>
        <div style={{ flex:1 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Clothing Units Requested</div>
          <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:2 }}>{totalRequests} request{totalRequests !== 1 ? "s" : ""} · {distinctProducts} product{distinctProducts !== 1 ? "s" : ""} · {filterLabel}</div>
        </div>
      </div>

      {rows.length === 0 ? (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:"3rem", textAlign:"center", color:"rgba(255,255,255,.4)", fontSize:14 }}>
          <ProductIcon size={32} opacity={0.4}/>
          <div style={{ marginTop:12 }}>No clothing refill requests in this period</div>
        </div>
      ) : (
        <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
          {rows.map(r => {
            const sizeEntries = Object.entries(r.sizes).sort((a, b) => b[1] - a[1]);
            return (
              <div key={r.productName} style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderLeft:"3px solid rgba(60,110,255,.55)", borderRadius:12, padding:"12px 14px" }}>
                <div style={{ display:"flex", alignItems:"center", gap:12 }}>
                  <ProductThumb name={r.productName} photoMap={productPhotoMap} size={40}/>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontWeight:700, fontSize:13, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{r.productName}</div>
                    <div style={{ color:"rgba(255,255,255,.4)", fontSize:10, marginTop:2 }}>last {fmtAgo(r.lastAt)}</div>
                  </div>
                  <div style={{ background:"rgba(60,110,255,.15)", color:"#4A7FFF", border:"1px solid rgba(60,110,255,.35)", borderRadius:999, padding:"4px 12px", fontSize:13, fontWeight:700 }}>×{r.total}</div>
                </div>
                {sizeEntries.length > 0 && (
                  <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginTop:10 }}>
                    {sizeEntries.map(([sz, count]) => (
                      <span key={sz} style={{ display:"inline-flex", alignItems:"center", gap:5, background:"rgba(60,110,255,.08)", border:"1px solid rgba(60,110,255,.22)", borderRadius:7, padding:"3px 9px", fontSize:11, fontWeight:600, color:"#fff" }}>
                        <span><SizeTag size={sz} /></span>
                        <span style={{ background:"rgba(60,110,255,.2)", color:BLUE_L, borderRadius:999, padding:"0 6px", fontSize:10, fontWeight:700 }}>{count}</span>
                      </span>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ─── INSIGHTS: STOCK DEPLETED TAB (Phase 11) ──────────────────────────────────
// Reads partner-order refill tasks resolved as 'stockDepleted' from live orders
// (no separate Firebase log — Phase 9.5 wrote the depletion event onto the
// order itself, so Undo is a single field clear and there's nothing to keep in
// sync). Aggregates by (productName, size) so restock planning sees the most
// frequently depleted SKUs at the top. Sort: count desc, tiebreak by most
// recent depletion desc. Local filters: hub pills + product-name search.
function InsightStockDepletedTab({ orders, log, productPhotoMap, filterStart, filterEnd, filterLabel, filterMode, filterDate }) {
  const [hubFilter, setHubFilter] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");

  // Day-mode + today uses live orders (no log lag); every other window pulls
  // from insights_log filtered to action="stock_depleted" so past days survive
  // the daily orderNumber reset that overwrites /orders/{id}. Same pattern as
  // InsightOOSTrackerTab. dedupeByOrderNumber handles re-fires from undo-redo.
  const events = useMemo(() => {
    const q = searchTerm.trim().toLowerCase();
    let raw;
    if (filterMode === "day" && filterDate === getSADateString()) {
      raw = (orders || [])
        .filter(o => o.displayRefillStatus === "stockDepleted")
        .filter(o => {
          const ts = o.displayRefillStockDepletedAt;
          return ts && ts >= filterStart && ts < filterEnd;
        })
        .map(o => ({
          orderNumber:  o.id,
          productName:  o.productName || "Unknown",
          size:         sourceDisplaySize(o) || "—",
          hub:          o.displayRefilledBy || o.displayRefillHub || "—",
          timestamp:    o.displayRefillStockDepletedAt,
        }));
    } else {
      raw = (log || [])
        .filter(e => e.action === "stock_depleted" && e.timestamp >= filterStart && e.timestamp < filterEnd)
        .map(e => ({
          orderNumber:  e.orderNumber,
          productName:  e.productName || "Unknown",
          size:         e.size || "—",
          hub:          e.displayRefilledBy || e.placedAtHub || "—",
          timestamp:    e.timestamp,
        }));
    }
    return dedupeByOrderNumber(raw)
      .filter(e => hubFilter === "all" || e.hub === hubFilter)
      .filter(e => !q || (e.productName || "").toLowerCase().includes(q));
  }, [orders, log, filterStart, filterEnd, filterMode, filterDate, hubFilter, searchTerm]);

  // Group by (product, size), keep total + lastTimestamp + hub set.
  const rows = useMemo(() => {
    const map = {};
    events.forEach(e => {
      const k = `${e.productName}__${e.size}`;
      if (!map[k]) map[k] = { productName: e.productName, size: e.size, count: 0, lastAt: "", hubs: new Set() };
      map[k].count += 1;
      if (e.timestamp > map[k].lastAt) map[k].lastAt = e.timestamp;
      if (e.hub && e.hub !== "—") map[k].hubs.add(e.hub);
    });
    return Object.values(map)
      .map(r => ({ ...r, hubs: [...r.hubs] }))
      .sort((a, b) => b.count - a.count || b.lastAt.localeCompare(a.lastAt));
  }, [events]);

  // "X ago" using the same nowTick-free approach as the other Insights tabs —
  // good-enough relative time, recomputed on each render (parent re-renders on
  // filter changes; absolute precision isn't needed).
  const fmtAgo = (iso) => {
    if (!iso) return "—";
    const mins = Math.floor((serverNowMs() - new Date(iso).getTime()) / 60000);
    if (mins < 1)    return "just now";
    if (mins < 60)   return `${mins}m ago`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24)    return `${hrs}h ago`;
    const days = Math.floor(hrs / 24);
    if (days < 30)   return `${days}d ago`;
    const months = Math.floor(days / 30);
    return `${months}mo ago`;
  };

  const hubLabel = (h) => h === "hub1" ? "Hub 1" : h === "hub2" ? "Hub 2" : h;
  const totalEvents = events.length;
  const distinctSkus = rows.length;

  return (
    <div>
      {/* SUMMARY BOX — mirrors InsightOOSTrackerTab layout */}
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(248,113,113,.6)", borderRadius:14, padding:"16px 18px", marginBottom:12, display:"flex", alignItems:"center", gap:14, boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
        <div style={{ fontWeight:800, fontSize:42, color:"#F87171", lineHeight:1, letterSpacing:"-1.5px" }}>{totalEvents}</div>
        <div style={{ flex:1 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Stock Depleted Events</div>
          <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, marginTop:2 }}>{distinctSkus} product–size combo{distinctSkus !== 1 ? "s" : ""} · {filterLabel}</div>
        </div>
      </div>

      {/* HUB FILTER + SEARCH */}
      <div style={{ display:"flex", gap:6, marginBottom:10, flexWrap:"wrap" }}>
        {[["all","All"],["hub1","Hub 1"],["hub2","Hub 2"]].map(([val, label]) => {
          const on = hubFilter === val;
          return (
            <button key={val} onClick={() => setHubFilter(val)}
                    style={{ padding:"7px 14px", borderRadius:999, fontSize:12, fontWeight:600, cursor:"pointer",
                             background: on ? "rgba(60,110,255,.14)" : "rgba(255,255,255,.03)",
                             border: "1px solid " + (on ? "rgba(60,110,255,.5)" : "rgba(255,255,255,.08)"),
                             color: on ? BLUE_L : "rgba(255,255,255,.55)" }}>
              {label}
            </button>
          );
        })}
      </div>
      <div style={{ marginBottom:12 }}>
        <input type="search" placeholder="Search product name…"
               value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
               style={{ width:"100%", boxSizing:"border-box", padding:"9px 12px", borderRadius:10, fontSize:13,
                        background:"rgba(255,255,255,.03)", border:"1px solid rgba(255,255,255,.1)", color:"#fff",
                        outline:"none" }}/>
      </div>

      {/* EMPTY STATE / LIST */}
      {rows.length === 0 ? (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:"3rem", textAlign:"center", color:"rgba(255,255,255,.4)", fontSize:14 }}>
          <ProductIcon size={32} opacity={0.4}/>
          <div style={{ marginTop:12 }}>No display stock depletions in this period{searchTerm || hubFilter !== "all" ? " for the current filters" : ""}.</div>
        </div>
      ) : (
        <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
          {rows.map((r, i) => (
            <div key={`${r.productName}__${r.size}`} style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(248,113,113,.3)", borderLeft:"3px solid rgba(248,113,113,.6)", borderRadius:12, padding:"12px 14px", display:"flex", alignItems:"center", gap:12 }}>
              <ProductThumb name={r.productName} photoMap={productPhotoMap} size={36}/>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontWeight:700, fontSize:13, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{r.productName}</div>
                <div style={{ display:"flex", alignItems:"center", gap:6, marginTop:4, flexWrap:"wrap" }}>
                  <span style={{ background:"rgba(60,110,255,.1)", border:"1px solid rgba(255,255,255,.08)", color:"#fff", borderRadius:8, padding:"2px 8px", fontSize:11, fontWeight:600 }}>Size <SizeTag size={r.size} /></span>
                  {r.hubs.map(h => (
                    <span key={h} style={{ background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.1)", color:"rgba(255,255,255,.6)", borderRadius:8, padding:"2px 8px", fontSize:10, fontWeight:600 }}>{hubLabel(h)}</span>
                  ))}
                  <span style={{ color:"rgba(255,255,255,.4)", fontSize:10 }}>· last {fmtAgo(r.lastAt)}</span>
                </div>
              </div>
              <div style={{ background:"rgba(248,113,113,.15)", color:"#F87171", border:"1px solid rgba(248,113,113,.4)", borderRadius:999, padding:"4px 12px", fontSize:13, fontWeight:700 }}>×{r.count}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ─── INSIGHTS: SALES SUMMARY TAB ─────────────────────────────────────────────
// Counts orders marked "ready" (not placed), deducts returns for the same
// period, then ranks products by net units sold. Cards are tappable to reveal
// a size breakdown for that product.
function InsightSalesSummaryTab({ log, returnsLog, productPhotoMap, filterStart, filterEnd, filterLabel, orders, filterMode, filterDate, category = "both" }) {
  const [expanded, setExpanded] = useState(new Set());

  // Today (day mode anchored on today's date): derive from live orders so the
  // headline matches Source's "Today's Request" in real time. Historical
  // days + week/month/year/all-time read from insights_log (immutable). Both
  // branches → dedupe by orderNumber + exclude returned orderNumbers so this
  // tab's totals reconcile exactly with Overview · Net Sales.
  // Net entries = "ready" log events for the period (incl. today), deduped by
  // orderNumber with returns excluded — shared with Overview · Net Sales via
  // readyEventsForPeriod, so the two reconcile exactly. The former live-orders
  // "today" path over-counted auto-collected OOS orders (OUT_OF_STOCK→COLLECTED)
  // as sales; "ready" log events never include those.
  const readyLog = useMemo(
    () => readyEventsForPeriod({ log, returnsLog, filterStart, filterEnd, category }),
    [log, returnsLog, filterStart, filterEnd, category]
  );

  const netByProduct = useMemo(() => {
    const map = {};
    readyLog.forEach(e => {
      const name = e.productName || "Unknown";
      map[name] = (map[name] || 0) + 1;
    });
    return map;
  }, [readyLog]);

  const sizesByProduct = useMemo(() => {
    const map = {};
    readyLog.forEach(e => {
      const name = e.productName || "Unknown";
      const sz   = String(e.size || "?");
      if (!map[name]) map[name] = {};
      map[name][sz] = (map[name][sz] || 0) + 1;
    });
    return map;
  }, [readyLog]);

  const ranked = useMemo(() =>
    Object.entries(netByProduct)
      .map(([name, net]) => ({ name, net }))
      .filter(p => p.net > 0)
      .sort((a, b) => b.net - a.net),
    [netByProduct]
  );

  const totalNet   = useMemo(() => ranked.reduce((s, p) => s + p.net, 0), [ranked]);
  const maxNet     = ranked[0]?.net || 1;

  const toggleCard = (name) => {
    setExpanded(prev => {
      const next = new Set(prev);
      next.has(name) ? next.delete(name) : next.add(name);
      return next;
    });
  };

  return (
    <div>
      {/* ── Headline ── */}
      <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(74,127,255,.35)", borderRadius:14, padding:"16px 18px", marginBottom:14, display:"flex", alignItems:"center", gap:14, boxShadow:"0 10px 30px -18px rgba(0,0,0,.55)" }}>
        <div style={{ fontWeight:800, fontSize:42, color:BLUE, lineHeight:1, flexShrink:0, letterSpacing:"-1.5px" }}>{totalNet}</div>
        <div style={{ flex:1 }}>
          <div style={{ fontWeight:700, color:"#fff", fontSize:14 }}>Net Sales · {filterLabel}</div>
          <div style={{ color:"rgba(255,255,255,.5)", fontSize:11, marginTop:3, lineHeight:1.4 }}>Same as Net Sales total above, broken down by product. Ready orders minus returns. {ranked.length} product{ranked.length!==1?"s":""}.</div>
        </div>
      </div>

      {/* ── Ranked product list ── */}
      {ranked.length === 0 ? (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:RADIUS, padding:"3rem", textAlign:"center", color:"#444", fontSize:"0.9rem" }}>
          No sales recorded in this period
        </div>
      ) : (
        <div style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:RADIUS, padding:"1.5rem", display:"flex", flexDirection:"column", gap:"0" }}>
          {ranked.map(({ name, net }, idx) => {
            const isOpen  = expanded.has(name);
            const sizes   = sizesByProduct[name] || {};
            const sizeRows = Object.entries(sizes)
              .sort((a, b) => parseFloat(a[0]) - parseFloat(b[0]));
            const isLast  = idx === ranked.length - 1;

            return (
              <div key={name}
                style={{ borderBottom: isLast ? "none" : "1px solid #1e1e1e", paddingTop: idx===0?"0":"0.85rem", paddingBottom:"0.85rem", cursor:"pointer" }}
                onClick={() => toggleCard(name)}>

                {/* ── Card header row ── */}
                <div style={{ display:"flex", alignItems:"center", gap:"0.75rem" }}>
                  {/* Rank */}
                  <span style={{ fontFamily:"'SF Pro Display',-apple-system,sans-serif", fontWeight:"800", letterSpacing:"0.04em", fontSize:"1rem", color:"#444", width:"1.4rem", textAlign:"right", flexShrink:0 }}>
                    {idx + 1}
                  </span>
                  {/* Thumbnail */}
                  <ProductThumb name={name} photoMap={productPhotoMap} size={44} />
                  {/* Name + count + arrow */}
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"0.35rem" }}>
                      <span style={{ fontWeight:"600", color:"#fff", fontSize:"0.9rem", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{name}</span>
                      <div style={{ display:"flex", alignItems:"center", gap:"0.45rem", flexShrink:0, marginLeft:"0.5rem" }}>
                        <span style={{ fontFamily:"'SF Pro Display',-apple-system,sans-serif", fontWeight:"800", fontSize:"1.15rem", color: idx===0 ? BLUE : "#ccc", letterSpacing:"0.03em" }}>
                          {net} sold
                        </span>
                        <span style={{ fontSize:"0.65rem", color:"#555", transition:"transform 0.2s", display:"inline-block", transform: isOpen?"rotate(90deg)":"rotate(0deg)" }}>▶</span>
                      </div>
                    </div>
                    <div style={{ background:"rgba(60,110,255,.08)", borderRadius:"4px", height:"8px" }}>
                      <div style={{
                        background: idx === 0 ? BLUE : "rgba(60,110,255,.4)",
                        borderRadius:"4px",
                        height:"8px",
                        width:`${Math.max(2, (net / maxNet) * 100)}%`,
                        transition:"width 0.4s",
                      }} />
                    </div>
                  </div>
                </div>

                {/* ── Expanded size breakdown ── */}
                {isOpen && (
                  <div style={{ marginTop:"0.75rem", marginLeft:"calc(1.4rem + 44px + 1.5rem)", background:"#0f0f0f", borderRadius:"10px", padding:"0.6rem 0.9rem" }}>
                    {sizeRows.length === 0 ? (
                      <div style={{ color:"#444", fontSize:"0.82rem" }}>No size data</div>
                    ) : sizeRows.map(([sz, count]) => (
                      <div key={sz} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"0.25rem 0", borderBottom:"1px solid rgba(60,110,255,.08)" }}>
                        <span style={{ color:"#888", fontSize:"0.82rem" }}>Size <SizeTag size={sz} /></span>
                        <span style={{ color:BLUE_L, fontFamily:"'SF Pro Display',-apple-system,sans-serif", fontWeight:"800", fontSize:"1rem", letterSpacing:"0.03em" }}>{count} sold</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ─── AI REORDER TAB ───────────────────────────────────────────────────────────
// Subscribes to /insights/reorderPlan/status and /insights/reorderPlan/latest
// (both written by the analyzeReorderNeeds Cloud Function in functions/index.js).
// A real run takes ~5 min — well past the 70 s httpsCallable client timeout —
// so the UI fires the call but does NOT await: status writes from the function
// drive the display via the onValue subscription.
//
// Status state machine (idle → running → idle | error) is the source of truth.
// Three steady displays:
//   • idle  + plan exists → render the cached plan + "Run Again"
//   • idle  + no plan     → empty state with first-run CTA
//   • running             → progress card; cached plan (if any) stays visible muted
//   • error               → error card with retry; cached plan stays visible muted
//
// Triggering: callable runs analyzeReorderNeeds (region europe-west1). The
// expected happy path returns deadline-exceeded after ~70 s while the function
// keeps running server-side; status subscription will flip to "running" on its
// own. Synchronous rejections (rate limit, concurrent run, permission) surface
// as triggerError. The Run buttons are super-admin-only because the function's
// assertAdmin only accepts ADMIN_EMAIL.
function InsightReorderTab({ productPhotoMap }) {
  const { isSuperAdmin } = usePermissions();
  const [status, setStatus]   = useState(null);
  const [latest, setLatest]   = useState(null);
  const [statusLoaded, setStatusLoaded] = useState(false);
  const [latestLoaded, setLatestLoaded] = useState(false);
  const [triggering,   setTriggering]   = useState(false);
  const [triggerError, setTriggerError] = useState(null);

  // ── Subscribe to both RTDB nodes for the duration of the tab's mount.
  // Cancel callbacks (third arg to onValue) ensure statusLoaded/latestLoaded
  // flip even when Firebase denies the read, so the tab never hangs on
  // "Loading…" forever. CR finding #1.
  useEffect(() => {
    const u1 = onValue(
      ref(database, "insights/reorderPlan/status"),
      snap => { setStatus(snap.val()); setStatusLoaded(true); },
      err  => { console.warn("reorderPlan/status read error:", err.message); setStatusLoaded(true); }
    );
    const u2 = onValue(
      ref(database, "insights/reorderPlan/latest"),
      snap => { setLatest(snap.val()); setLatestLoaded(true); },
      err  => { console.warn("reorderPlan/latest read error:", err.message);  setLatestLoaded(true); }
    );
    return () => { u1(); u2(); };
  }, []);

  const runAnalysis = (force = false) => {
    setTriggering(true);
    setTriggerError(null);
    const callable = httpsCallable(functions, "analyzeReorderNeeds");
    callable(force ? { force: true } : {}).catch(err => {
      const code = err.code || "";
      // deadline-exceeded ≈ "still working" — expected for real runs.
      if (code === "deadline-exceeded" || code === "functions/deadline-exceeded") return;
      setTriggerError(err.message || "Failed to start analysis.");
    });
    // Re-enable the button after ~2 s. By then the function has either rejected
    // at the gate (catch above fires) or written state:"running" (subscription
    // updates the UI). Re-clicking after the lock is held just gets rejected.
    setTimeout(() => setTriggering(false), 2000);
  };

  // ── Display helpers (scoped to this component to keep them grep-near the JSX).
  const fmtDate = ms => {
    if (!ms) return "—";
    const d = new Date(ms);
    return d.toLocaleDateString("en-ZA", { year:"numeric", month:"short", day:"numeric" })
         + " · " + d.toLocaleTimeString("en-ZA", { hour:"2-digit", minute:"2-digit" });
  };
  const fmtDuration = ms => {
    if (!ms || ms < 0) return "—";
    const s = Math.round(ms / 1000);
    if (s < 60) return `${s}s`;
    return `${Math.floor(s / 60)}m ${s % 60}s`;
  };

  const allLoaded = statusLoaded && latestLoaded;
  const state     = status?.state ?? null;
  const running   = state === "running";
  const errored   = state === "error";
  const hasPlan   = !!(latest && latest.plan);
  const canRun    = isSuperAdmin && !triggering && !running;

  // ── Action / priority styling. Kept inline so the badge meaning is visible
  // when reading the JSX below.
  const ACTION_STYLE = {
    reorder:    { label: "Reorder",    bg: "rgba(34,197,94,.12)",  border: "rgba(34,197,94,.5)",  color: "#86EFAC" },
    review:     { label: "Review",     bg: "rgba(245,158,11,.12)", border: "rgba(245,158,11,.5)", color: "#FCD34D" },
    slow_mover: { label: "Slow mover", bg: "rgba(251,146,60,.12)", border: "rgba(251,146,60,.5)", color: "#FDBA74" },
    skip:       { label: "Skip",       bg: "rgba(255,255,255,.04)", border: "rgba(255,255,255,.18)", color: "rgba(255,255,255,.5)" },
  };
  const PRIORITY_COLOR = { high: "#F87171", medium: "#F59E0B", low: "rgba(255,255,255,.45)" };
  const ACTION_ORDER   = ["reorder", "review", "slow_mover", "skip"];
  const PRIORITY_ORDER = { high: 0, medium: 1, low: 2 };

  // ── Group + sort recommendations once per plan change.
  const groupedRecs = useMemo(() => {
    if (!hasPlan || !Array.isArray(latest.plan.recommendations)) return {};
    const groups = { reorder: [], review: [], slow_mover: [], skip: [] };
    for (const r of latest.plan.recommendations) {
      const action = ACTION_STYLE[r.action] ? r.action : "skip";
      groups[action].push(r);
    }
    for (const k of Object.keys(groups)) {
      groups[k].sort((a, b) => {
        const ap = PRIORITY_ORDER[a.priority] ?? 9;
        const bp = PRIORITY_ORDER[b.priority] ?? 9;
        if (ap !== bp) return ap - bp;
        return (b.totalSuggested || 0) - (a.totalSuggested || 0);
      });
    }
    return groups;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [latest && latest.generatedAt]);

  // ── Style fragments reused inside the render below.
  const cardBase = { background:"rgba(255,255,255,.024)", border:"1px solid rgba(255,255,255,.08)", borderRadius:14, padding:"14px 16px", marginBottom:10 };
  const sectionLabel = { fontSize:10, fontWeight:700, color:"rgba(255,255,255,.35)", textTransform:"uppercase", letterSpacing:"1.5px", marginBottom:8 };
  const runBtnStyle = (disabled) => ({
    background: disabled ? "rgba(60,110,255,.15)" : "rgba(60,110,255,.22)",
    color: disabled ? "rgba(255,255,255,.4)" : "#fff",
    border: "1px solid " + (disabled ? "rgba(60,110,255,.3)" : "rgba(60,110,255,.55)"),
    borderRadius: 10, padding: "9px 18px", fontSize: 13, fontWeight: 700,
    cursor: disabled ? "not-allowed" : "pointer",
    boxShadow: disabled ? "none" : "0 0 8px rgba(60,110,255,.3)",
  });

  // ── Loading skeleton: first paint before either subscription has fired.
  if (!allLoaded) {
    return (
      <div style={{ ...cardBase, borderColor:"rgba(60,110,255,.15)", padding:"3rem", textAlign:"center", color:"rgba(255,255,255,.4)", fontSize:13 }}>
        Loading…
      </div>
    );
  }

  // ── Trigger error banner (renders above everything when present).
  const TriggerErrorBanner = () => triggerError ? (
    <div style={{ background:"rgba(248,113,113,.1)", border:"1px solid rgba(248,113,113,.45)", borderRadius:12, padding:"10px 14px", marginBottom:10, display:"flex", alignItems:"center", gap:10 }}>
      <div style={{ fontSize:12, color:"#F87171", flex:1 }}>{triggerError}</div>
      <button onClick={() => setTriggerError(null)} style={{ background:"transparent", border:"none", color:"#F87171", cursor:"pointer", fontSize:18, lineHeight:1, padding:0 }}>×</button>
    </div>
  ) : null;

  // ── Empty state — first-ever load, nothing cached, nothing running.
  if (!hasPlan && !running && !errored) {
    return (
      <div>
        <TriggerErrorBanner />
        <div style={{ ...cardBase, borderColor:"rgba(60,110,255,.3)", padding:"2.5rem 1.5rem", textAlign:"center" }}>
          <div style={{ marginBottom:14, display:"flex", justifyContent:"center" }}>
            <svg width="44" height="44" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" style={{ filter:"drop-shadow(0 0 8px rgba(60,110,255,.45))" }}>
              <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
              <circle cx="12" cy="12" r="3"/>
            </svg>
          </div>
          <div style={{ fontWeight:700, color:"#fff", fontSize:15, marginBottom:6 }}>No reorder analysis yet</div>
          <div style={{ color:"rgba(255,255,255,.45)", fontSize:12, marginBottom:22, maxWidth:300, marginLeft:"auto", marginRight:"auto", lineHeight:1.5 }}>
            Run a fresh analysis to surface what to reorder for the next cycle and which products have gone quiet.
          </div>
          {isSuperAdmin ? (
            <button onClick={() => runAnalysis(false)} disabled={!canRun} style={runBtnStyle(!canRun)}>
              {triggering ? "Starting…" : "Run Analysis"}
            </button>
          ) : (
            <div style={{ color:"rgba(255,255,255,.35)", fontSize:11 }}>Only the super-admin can trigger a fresh analysis.</div>
          )}
        </div>
      </div>
    );
  }

  // ── Main render: status banner (if any) + cached plan body.
  const plan      = latest?.plan;
  const meta      = latest?.meta;
  const summary   = plan?.summary;
  const topSellers = Array.isArray(plan?.topSellers) ? plan.topSellers : [];
  const sleepers   = Array.isArray(plan?.sleepers)   ? plan.sleepers   : [];
  const qualityNotes = Array.isArray(plan?.dataQualityNotes) ? plan.dataQualityNotes : [];

  return (
    <div>
      <TriggerErrorBanner />

      {/* RUNNING BANNER */}
      {running && (
        <div style={{ background:"rgba(60,110,255,.1)", border:"1px solid rgba(60,110,255,.55)", borderRadius:14, padding:"14px 16px", marginBottom:10, display:"flex", alignItems:"center", gap:12, boxShadow:"0 0 12px rgba(60,110,255,.2)" }}>
          <div style={{ width:14, height:14, borderRadius:"50%", border:"2px solid rgba(60,110,255,.3)", borderTopColor:"#4A7FFF", animation:"spin 0.9s linear infinite", flexShrink:0 }} />
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontWeight:700, color:"#fff", fontSize:13 }}>Analysis in progress…</div>
            <div style={{ color:"rgba(255,255,255,.55)", fontSize:11, marginTop:2 }}>
              Started {fmtDate(status?.startedAt)} · typically 4–5 minutes
            </div>
          </div>
          {/* Inline keyframes (no global stylesheet to extend). */}
          <style>{"@keyframes spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}"}</style>
        </div>
      )}

      {/* ERROR BANNER */}
      {errored && (
        <div style={{ background:"rgba(248,113,113,.1)", border:"1px solid rgba(248,113,113,.5)", borderRadius:14, padding:"14px 16px", marginBottom:10 }}>
          <div style={{ display:"flex", alignItems:"flex-start", gap:10 }}>
            <div style={{ fontSize:18, lineHeight:1 }}>⚠</div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontWeight:700, color:"#F87171", fontSize:13 }}>Last analysis failed</div>
              <div style={{ color:"rgba(255,255,255,.6)", fontSize:11, marginTop:4, lineHeight:1.5, wordBreak:"break-word" }}>
                {status?.errorMessage || "Unknown error."}
              </div>
              <div style={{ color:"rgba(255,255,255,.35)", fontSize:10, marginTop:6 }}>
                Failed {fmtDate(status?.erroredAt)}
              </div>
              {isSuperAdmin && (
                <button onClick={() => runAnalysis(true)} disabled={!canRun}
                  style={{ ...runBtnStyle(!canRun), marginTop:12, padding:"7px 14px", fontSize:12 }}>
                  {triggering ? "Retrying…" : "Retry"}
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {hasPlan && (
        // Dim the cached plan while a run or error is active so it's obvious
        // the visible recommendations may be stale. CR finding #3.
        <div style={{ opacity: running || errored ? 0.55 : 1, transition:"opacity 150ms ease" }}>
          {/* HEADER: summary text + run-again button */}
          <div style={{ ...cardBase, borderColor:"rgba(60,110,255,.55)", boxShadow:"0 0 14px rgba(60,110,255,.15)" }}>
            <div style={sectionLabel}>Plan Summary</div>
            <div style={{ color:"#fff", fontSize:13, lineHeight:1.55, marginBottom:12 }}>
              {summary || "No summary provided."}
            </div>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:12 }}>
              <div style={{ color:"rgba(255,255,255,.4)", fontSize:11 }}>
                Generated {fmtDate(latest.generatedAt)}
              </div>
              {isSuperAdmin && !running && (
                <button onClick={() => runAnalysis(false)} disabled={!canRun}
                  style={{ ...runBtnStyle(!canRun), padding:"7px 14px", fontSize:12 }}>
                  {triggering ? "Starting…" : "Run Again"}
                </button>
              )}
            </div>
          </div>

          {/* META STRIP */}
          {meta && (
            <div style={{ ...cardBase, padding:"12px 14px" }}>
              <div style={sectionLabel}>Run Details</div>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(2, 1fr)", gap:8, fontSize:11 }}>
                <MetaRow label="Cycle" value={`${meta.cycleDays ?? "?"} days`} />
                <MetaRow label="Active products" value={`${meta.activeProductsTotal ?? 0}${meta.paginatedActive ? " (top 200)" : ""}`} />
                <MetaRow label="Dormant products" value={`${meta.dormantProductsTotal ?? 0}${meta.paginatedDormant ? " (top 200)" : ""}`} />
                <MetaRow label="Analysed" value={`${meta.productsAnalyzed ?? 0} / ${meta.catalogTotal ?? 0}`} />
                <MetaRow label="Duration" value={fmtDuration(latest.durationMs ?? meta.durationMs)} />
                <MetaRow label="Cost (USD)" value={meta.estimatedCostUSD != null ? `$${meta.estimatedCostUSD.toFixed(4)}` : "—"} />
              </div>
            </div>
          )}

          {/* DATA QUALITY NOTES (model-emitted) */}
          {qualityNotes.length > 0 && (
            <div style={{ ...cardBase, borderColor:"rgba(245,158,11,.35)", background:"rgba(245,158,11,.05)" }}>
              <div style={{ ...sectionLabel, color:"#F59E0B" }}>Data Quality Notes</div>
              <ul style={{ margin:0, padding:"0 0 0 18px", color:"rgba(255,255,255,.7)", fontSize:11, lineHeight:1.6 }}>
                {qualityNotes.map((n, i) => <li key={i}>{n}</li>)}
              </ul>
            </div>
          )}

          {/* RECOMMENDATIONS — grouped by action, ordered reorder → review → slow_mover → skip */}
          {ACTION_ORDER.map(action => {
            const list = groupedRecs[action] || [];
            if (!list.length) return null;
            const style = ACTION_STYLE[action];
            return (
              <div key={action} style={{ marginBottom:14 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, padding:"4px 2px 8px" }}>
                  <span style={{ background:style.bg, border:`1px solid ${style.border}`, color:style.color, padding:"3px 10px", borderRadius:999, fontSize:11, fontWeight:700, textTransform:"uppercase", letterSpacing:"0.5px" }}>
                    {style.label}
                  </span>
                  <span style={{ color:"rgba(255,255,255,.45)", fontSize:11, fontWeight:600 }}>{list.length}</span>
                </div>
                <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                  {list.map(rec => {
                    const sizes = rec.suggestedQuantity && typeof rec.suggestedQuantity === "object"
                      ? Object.entries(rec.suggestedQuantity).filter(([, q]) => q > 0)
                      : [];
                    return (
                      <div key={rec.productId || rec.productName} style={{ background:"rgba(255,255,255,.024)", border:"1px solid rgba(60,110,255,.22)", borderLeft:`3px solid ${style.border}`, borderRadius:12, padding:"12px 14px" }}>
                        <div style={{ display:"flex", alignItems:"center", gap:12 }}>
                          <ProductThumb name={rec.productName} photoMap={productPhotoMap} size={40}/>
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ fontWeight:700, fontSize:13, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{rec.productName || "(no name)"}</div>
                            <div style={{ display:"flex", alignItems:"center", gap:6, marginTop:3 }}>
                              {rec.priority && (
                                <span style={{ fontSize:10, fontWeight:700, color:PRIORITY_COLOR[rec.priority] || PRIORITY_COLOR.low, textTransform:"uppercase", letterSpacing:"0.5px" }}>
                                  {rec.priority}
                                </span>
                              )}
                              {action === "reorder" && rec.totalSuggested != null && (
                                <span style={{ color:"rgba(255,255,255,.55)", fontSize:10 }}>· {rec.totalSuggested} units</span>
                              )}
                            </div>
                          </div>
                          {action === "reorder" && rec.totalSuggested != null && (
                            <div style={{ background:style.bg, color:style.color, border:`1px solid ${style.border}`, borderRadius:999, padding:"4px 12px", fontSize:13, fontWeight:700, flexShrink:0 }}>
                              ×{rec.totalSuggested}
                            </div>
                          )}
                        </div>

                        {sizes.length > 0 && (
                          <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginTop:10 }}>
                            {sizes.map(([sz, count]) => (
                              <span key={sz} style={{ display:"inline-flex", alignItems:"center", gap:5, background:"rgba(60,110,255,.08)", border:"1px solid rgba(60,110,255,.22)", borderRadius:7, padding:"3px 9px", fontSize:11, fontWeight:600, color:"#fff" }}>
                                <span><SizeTag size={sz} /></span>
                                <span style={{ background:"rgba(60,110,255,.2)", color:BLUE_L, borderRadius:999, padding:"0 6px", fontSize:10, fontWeight:700 }}>{count}</span>
                              </span>
                            ))}
                          </div>
                        )}

                        {rec.reasoning && (
                          <div style={{ color:"rgba(255,255,255,.62)", fontSize:11, lineHeight:1.55, marginTop:sizes.length > 0 ? 10 : 8 }}>
                            {rec.reasoning}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}

          {/* TOP SELLERS */}
          {topSellers.length > 0 && (
            <div style={{ ...cardBase }}>
              <div style={sectionLabel}>Top Sellers</div>
              <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
                {topSellers.map((t, i) => (
                  <div key={i} style={{ display:"flex", justifyContent:"space-between", padding:"5px 0", borderBottom: i < topSellers.length - 1 ? "1px solid rgba(255,255,255,.05)" : "none" }}>
                    <span style={{ color:"#fff", fontSize:12, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", flex:1, marginRight:8 }}>{t.productName}</span>
                    <span style={{ color:BLUE_L, fontSize:12, fontWeight:700, flexShrink:0 }}>{t.totalSales}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* SLEEPERS */}
          {sleepers.length > 0 && (
            <div style={{ ...cardBase }}>
              <div style={sectionLabel}>Sleepers</div>
              <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                {sleepers.map((s, i) => (
                  <div key={i} style={{ padding:"6px 0", borderBottom: i < sleepers.length - 1 ? "1px solid rgba(255,255,255,.05)" : "none" }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", gap:8 }}>
                      <span style={{ color:"#fff", fontSize:12, fontWeight:600, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", flex:1 }}>{s.productName}</span>
                      <span style={{ color:"rgba(255,255,255,.45)", fontSize:10, flexShrink:0 }}>
                        last {s.lastSaleDate || "—"} · {s.totalSales ?? 0} sales
                      </span>
                    </div>
                    {s.note && <div style={{ color:"rgba(255,255,255,.55)", fontSize:11, marginTop:3, lineHeight:1.5 }}>{s.note}</div>}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// Small label/value row used inside the AI Reorder meta strip.
function MetaRow({ label, value }) {
  return (
    <div style={{ display:"flex", justifyContent:"space-between", gap:6, alignItems:"baseline" }}>
      <span style={{ color:"rgba(255,255,255,.4)" }}>{label}</span>
      <span style={{ color:"#fff", fontWeight:600 }}>{value}</span>
    </div>
  );
}

// Insights auth persists for the session via sessionStorage.
// Cleared when the user taps Exit so the next visit re-asks for the password.
const INSIGHTS_SESSION_KEY = "insightsAuth";

// ─── INSIGHTS VIEW ────────────────────────────────────────────────────────────
// Sidebar icons for the desktop Insights workspace (one per report).
const INSIGHT_TAB_ICON = {
  overview:         <path d="M4 20V10M10 20V4M16 20v-7M22 20H2" />,
  sales:            <><path d="M3 17l6-6 4 4 8-8" /><path d="M17 7h4v4" /></>,
  search:           <><circle cx="11" cy="11" r="7" /><path d="M21 21l-4-4" /></>,
  oos:              <><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" /><line x1="12" y1="9" x2="12" y2="13" /><line x1="12" y1="17" x2="12.01" y2="17" /></>,
  sizes:            <><path d="M2 12h20M6 12V8M10 12V6M14 12V6M18 12V8" /></>,
  times:            <><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></>,
  returns:          <><polyline points="9 14 4 9 9 4" /><path d="M20 20v-7a4 4 0 0 0-4-4H4" /></>,
  "clothing-refills": <path d="M16 4l-4 4-4-4M4 8v12a1 1 0 001 1h14a1 1 0 001-1V8" />,
  depleted:         <><path d="M21 8v13H3V8M1 3h22v5H1z" /><path d="M9 12h6" /></>,
  reorder:          <path d="M12 3l1.9 4.6L18.5 9l-4.6 1.9L12 15l-1.9-4.1L5.5 9l4.6-1.4L12 3z" />,
};

function InsightsView({ onExit }) {
  const isDesktop = !useIsNarrow(1024);
  const [tab,        setTab]        = usePersistedTab("insights", "overview");
  const [filterMode, setFilterMode] = useState("day");
  const [filterDate, setFilterDate] = useState(() => getSADateString());
  // Phase 12D: product-type filter ("sneaker" | "clothing" | "both"). Applied
  // in 6 of 9 tabs; hidden on tabs where it doesn't make sense (sizes,
  // depleted, clothing-refills).
  const category = "both";   // category toggle removed — reports show all types
  // Phase 14C: top-level store filter — slices every Insights tab to a
  // subset of events tagged with placedAtHub. "all" is current behavior,
  // "central" keeps hub1/hub2 events, "pine" keeps hub3 events. Events
  // missing placedAtHub (pre-14B history) are excluded by Central/Pine
  // until the backfill stamps them.
  const [storeFilter, setStoreFilter] = useState("all");
  const [auditOpen,  setAuditOpen]  = useState(false);
  const touchStartX = useRef(null);
  const log        = useInsightsLog();
  const returnsLog = useReturnsLog();
  const products   = useProducts();
  const orders     = useOrders();

  // Pre-filter the three event streams by storeFilter so every downstream
  // tab/audit consumes an already-narrowed slice. dedupeByOrderNumber and
  // excludeReturnedOrderNumbers continue to operate on whatever passes through.
  // Central treats missing placedAtHub as Central — historical events
  // pre-date Phase 14B and were all placed in the central universe, so the
  // filter is self-healing without a backfill. Pine stays strict.
  // Stores are now three: Marathon PE, Trophy, Pine. Events tag placedAtHub
  // (hub1/hub2 = the central pair, hub3 = Pine) and newer ones a destShop. Pine =
  // hub3. Trophy = events explicitly tagged trophy. Marathon PE = the main store:
  // its own destShop OR the untagged central history (so nothing goes missing).
  const matchesStore = useMemo(() => {
    if (storeFilter === "all") return () => true;
    if (storeFilter === "pine")   return (e) => e && (e.destShop === "marathon-pine" || e.placedAtHub === "hub3");
    if (storeFilter === "trophy") return (e) => e && e.destShop === "trophy";
    return (e) => e && (e.destShop === "marathon-pe" || (e.destShop == null && e.placedAtHub !== "hub3")); // marathon-pe
  }, [storeFilter]);
  const filteredLog        = useMemo(() => log.filter(matchesStore),         [log, matchesStore]);
  const filteredReturnsLog = useMemo(() => returnsLog.filter(matchesStore),  [returnsLog, matchesStore]);
  const filteredOrders     = useMemo(() => orders.filter(matchesStore),      [orders, matchesStore]);

  // ── ORDER AUDIT — runs in-memory, renders to a modal ─────────────────────
  // Phase 14C: respects the storeFilter via filteredOrders / filteredReturnsLog,
  // so the audit reflects the same slice the user is viewing.
  const audit = useMemo(() => {
    const today = getSADateString();
    const KNOWN = new Set(["ready","collected","out_of_stock","tomorrow","on_hold","incoming","coming_tomorrow"]);
    const onTodayCreated = filteredOrders.filter(o => o.createdAt && o.createdAt.slice(0,10) === today);

    // Status distributions
    const byStatusAll = {};
    const byStatusToday = {};
    filteredOrders.forEach(o => {
      const s = o.status === undefined ? "(undefined)" : (o.status || "(empty)");
      byStatusAll[s] = (byStatusAll[s] || 0) + 1;
    });
    onTodayCreated.forEach(o => {
      const s = o.status === undefined ? "(undefined)" : (o.status || "(empty)");
      byStatusToday[s] = (byStatusToday[s] || 0) + 1;
    });

    // Order number gaps + duplicates. Sneaker orders only — clothing "Shop
    // Refill" ids are R{n}-{i} (their own counter), which would digit-strip to
    // bogus numbers (R001-1 → 11) and fake duplicates/gaps in this sneaker audit.
    const todayNums = onTodayCreated
      .filter(o => o.customerName !== "Shop Refill")
      .map(o => parseInt(String(o.id).replace(/[^0-9]/g, ""), 10))
      .filter(n => !isNaN(n));
    const minNum = todayNums.length ? Math.min(...todayNums) : null;
    const maxNum = todayNums.length ? Math.max(...todayNums) : null;
    const present = new Set(todayNums);
    const gaps = [];
    if (minNum !== null && maxNum !== null) {
      for (let i = minNum; i <= maxNum; i++) if (!present.has(i)) gaps.push(i);
    }
    const dupCount = {};
    todayNums.forEach(n => { dupCount[n] = (dupCount[n] || 0) + 1; });
    const dups = Object.entries(dupCount).filter(([, c]) => c > 1).map(([n, c]) => ({ orderNumber: n, count: c }));

    const ordersNoStatus = onTodayCreated.filter(o => !o.status || String(o.status).trim() === "");
    const ordersUnknownStatus = onTodayCreated.filter(o => o.status && !KNOWN.has(o.status));
    const softDeleted = onTodayCreated.filter(o => o.deleted === true || o.removed === true || o.archived === true);
    const multiStamp = onTodayCreated.filter(o => {
      const stamps = [o.readyAt, o.outOfStockAt, o.comingTomorrowAt].filter(Boolean);
      return stamps.length > 1;
    });

    const ready     = onTodayCreated.filter(o => o.status === STATUS.READY).length;
    const collected = onTodayCreated.filter(o => o.status === STATUS.COLLECTED).length;
    const oos       = onTodayCreated.filter(o => o.status === STATUS.OUT_OF_STOCK).length;
    const tomorrow  = onTodayCreated.filter(o => o.status === STATUS.COMING_TOMORROW).length;
    const incoming  = onTodayCreated.filter(o => o.status === STATUS.INCOMING).length;
    const sumByStatus = ready + collected + oos + tomorrow + incoming;

    const accounted = new Set([STATUS.READY, STATUS.COLLECTED, STATUS.OUT_OF_STOCK, STATUS.COMING_TOMORROW, STATUS.INCOMING]);
    const unaccounted = onTodayCreated.filter(o => !accounted.has(o.status));

    const returnsToday = filteredReturnsLog.filter(r => (r.timestamp||"").slice(0,10) === today).length;

    return {
      today,
      totalAll: filteredOrders.length,
      totalToday: onTodayCreated.length,
      byStatusAll, byStatusToday,
      minNum, maxNum, gaps, dups,
      ordersNoStatus, ordersUnknownStatus, softDeleted, multiStamp, unaccounted,
      ready, collected, oos, tomorrow, incoming, sumByStatus,
      diff: onTodayCreated.length - sumByStatus,
      returnsToday,
      netSales: (ready + collected) - returnsToday,
    };
  }, [filteredOrders, filteredReturnsLog]);

  // Compute filterStart / filterEnd (exclusive) / filterLabel from mode + anchor date.
  const { filterStart, filterEnd, filterLabel } = useMemo(() => {
    // All Time short-circuit — sentinel ISO strings that pass every
    // existing `iso >= filterStart && iso < filterEnd` comparison in tabs.
    // Day-mode special branches naturally skip because filterMode !== "day".
    if (filterMode === "all") {
      return {
        filterStart: "0000-01-01T00:00:00.000Z",
        filterEnd:   "9999-12-31T23:59:59.999Z",
        filterLabel: "All Time",
      };
    }
    const base = dateStrToLocal(filterDate);
    let start, end, label;
    if (filterMode === "day") {
      start = new Date(base); start.setHours(0,0,0,0);
      end   = new Date(base); end.setDate(end.getDate()+1); end.setHours(0,0,0,0);
      label = filterDate === getSADateString() ? "today"
        : base.toLocaleDateString([], { day:"numeric", month:"short", year:"numeric" });
    } else if (filterMode === "week") {
      const dow = (base.getDay()+6)%7;
      start = new Date(base); start.setDate(base.getDate()-dow); start.setHours(0,0,0,0);
      end   = new Date(start); end.setDate(start.getDate()+7);
      const sunday = new Date(end.getTime()-1);
      const fmt = d => `${d.getDate()} ${_MONTHS[d.getMonth()].slice(0,3)}`;
      label = `${fmt(start)} – ${fmt(sunday)}`;
    } else if (filterMode === "month") {
      start = new Date(base.getFullYear(), base.getMonth(), 1);
      end   = new Date(base.getFullYear(), base.getMonth()+1, 1);
      label = `${_MONTHS[base.getMonth()]} ${base.getFullYear()}`;
    } else {
      // year
      start = new Date(base.getFullYear(), 0, 1);
      end   = new Date(base.getFullYear()+1, 0, 1);
      label = `${base.getFullYear()}`;
    }
    return { filterStart: start.toISOString(), filterEnd: end.toISOString(), filterLabel: label };
  }, [filterMode, filterDate]);

  // Build name → { photoUrl, photo } lookup for thumbnail display in every tab.
  // Also indexes by normalized name (lowercase, collapsed spaces, no spaces around
  // hyphens) so old order names that drifted from the catalog still resolve.
  const productPhotoMap = useMemo(() => {
    const normKey = s => s.trim().replace(/\s+/g, ' ').toLowerCase().replace(/\s*-\s*/g, '-');
    const map = {};
    products.forEach(p => {
      if (!p.name) return;
      const entry = { photoUrl: p.photoUrl || null, photo: p.photo || "" };
      map[p.name] = entry;
      map[normKey(p.name)] = entry;
    });
    return map;
  }, [products]);

  // Password gate removed — access is governed by the Insights role permission.
  const handleExit = () => { onExit(); };

  const TABS = [
    { key:"overview",         label:"Overview" },
    { key:"sales",            label:"Sales Summary" },
    { key:"search",           label:"Product Search" },
    { key:"oos",              label:"Out of Stock" },
    { key:"sizes",            label:"Size Popularity" },
    { key:"times",            label:"Busiest Times" },
    { key:"returns",          label:"Returns" },
    { key:"clothing-refills", label:"Clothing Refills" },
    { key:"depleted",         label:"Stock Depleted" },
    { key:"reorder",          label:"AI Reorder" },
  ];
  const tabKeys = TABS.map(t => t.key);

  const handleSwipe = (e) => {
    if (touchStartX.current === null) return;
    const dx = e.changedTouches[0].clientX - touchStartX.current;
    touchStartX.current = null;
    if (Math.abs(dx) < 50) return;
    const idx = tabKeys.indexOf(tab);
    if (dx < 0 && idx < tabKeys.length - 1) setTab(tabKeys[idx + 1]); // left → next
    if (dx > 0 && idx > 0)                  setTab(tabKeys[idx - 1]); // right → prev
  };

  // Shared tab content — rendered by both the desktop workspace and mobile.
  const content = (
    <>
      {tab==="overview"         && <InsightOverviewTab        log={filteredLog} returnsLog={filteredReturnsLog} productPhotoMap={productPhotoMap} filterStart={filterStart} filterEnd={filterEnd} filterLabel={filterLabel} orders={filteredOrders} filterMode={filterMode} filterDate={filterDate} category={category} />}
      {tab==="sales"            && <InsightSalesSummaryTab    log={filteredLog} returnsLog={filteredReturnsLog} productPhotoMap={productPhotoMap} filterStart={filterStart} filterEnd={filterEnd} filterLabel={filterLabel} orders={filteredOrders} filterMode={filterMode} filterDate={filterDate} category={category} />}
      {tab==="search"           && <InsightProductSearchTab   log={filteredLog} productPhotoMap={productPhotoMap} filterStart={filterStart} filterEnd={filterEnd} category={category} />}
      {tab==="oos"              && <InsightOOSTrackerTab      log={filteredLog} returnsLog={filteredReturnsLog} productPhotoMap={productPhotoMap} filterStart={filterStart} filterEnd={filterEnd} filterLabel={filterLabel} category={category} />}
      {tab==="sizes"            && <InsightSizePopularityTab  log={filteredLog} filterStart={filterStart} filterEnd={filterEnd} filterLabel={filterLabel} category={category} />}
      {tab==="times"            && <InsightBusiestTimesTab    log={filteredLog} filterStart={filterStart} filterEnd={filterEnd} filterLabel={filterLabel} category={category} />}
      {tab==="returns"          && <InsightReturnsTab         returnsLog={filteredReturnsLog} productPhotoMap={productPhotoMap} filterStart={filterStart} filterEnd={filterEnd} filterLabel={filterLabel} category={category} />}
      {tab==="clothing-refills" && <InsightClothingRefillsTab orders={filteredOrders} log={filteredLog} productPhotoMap={productPhotoMap} filterStart={filterStart} filterEnd={filterEnd} filterLabel={filterLabel} filterMode={filterMode} filterDate={filterDate} />}
      {tab==="depleted"         && <InsightStockDepletedTab   orders={filteredOrders} log={filteredLog} productPhotoMap={productPhotoMap} filterStart={filterStart} filterEnd={filterEnd} filterLabel={filterLabel} filterMode={filterMode} filterDate={filterDate} />}
      {tab==="reorder"          && <InsightReorderTab          productPhotoMap={productPhotoMap} />}
    </>
  );

  // Segmented control — one grouped track, active segment lit. Cleaner than a
  // row of separate pills, and reused for store + category.
  const STORE_OPTS = [["all", "All"], ["marathon-pe", "Marathon PE"], ["trophy", "Trophy"], ["pine", "Pine"]];
  const seg = (options, val, setVal) => (
    <div style={{ display: "inline-flex", background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.1)", borderRadius: 12, padding: 3, gap: 2 }}>
      {options.map(([v, l]) => {
        const on = val === v;
        return (
          <button key={v} onClick={() => setVal(v)}
            style={{ border: 0, background: on ? "rgba(74,127,255,.22)" : "transparent", color: on ? "#fff" : "rgba(233,238,255,.5)",
                     fontSize: 12, fontWeight: 700, padding: "7px 14px", borderRadius: 9, cursor: "pointer", fontFamily: FONT,
                     boxShadow: on ? "0 0 8px rgba(60,110,255,.3)" : "none", whiteSpace: "nowrap" }}>{l}</button>
        );
      })}
    </div>
  );
  const storePills = () => (tab === "reorder" ? null : seg(STORE_OPTS, storeFilter, setStoreFilter));
  const auditBtn = (
    <button onClick={() => setAuditOpen(true)}
      style={{ background: audit.diff !== 0 ? "rgba(248,113,113,.12)" : "rgba(74,127,255,.08)",
               border: audit.diff !== 0 ? "1px solid rgba(248,113,113,.4)" : "1px solid rgba(74,127,255,.3)",
               color: audit.diff !== 0 ? "#F87171" : "#9DBCFF", borderRadius:11, padding:"9px 14px", fontSize:12.5, fontWeight:700, cursor:"pointer",
               display:"flex", alignItems:"center", justifyContent:"center", gap:8, whiteSpace:"nowrap", fontFamily:FONT }}>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 9v2m0 4h.01M5 19h14a2 2 0 002-2v-1a8 8 0 10-16 0v1a2 2 0 002 2z"/></svg>
      Run Order Audit{audit.diff !== 0 && <span style={{ fontWeight:800 }}>· {audit.diff}</span>}
    </button>
  );

  // ── DESKTOP INSIGHTS WORKSPACE (≥1024px) — sidebar of views + a filter toolbar
  //    over the active report. Mobile keeps the tab strip below. ──
  if (isDesktop) {
    return (
      <div style={{ height:"100vh", maxHeight:"100dvh", background:"#000", color:"#f3f6ff", fontFamily:FONT, display:"grid", gridTemplateColumns:"236px minmax(0,1fr)", overflow:"hidden" }}>
        <aside style={{ background:"rgba(255,255,255,.015)", borderRight:"1px solid rgba(255,255,255,.08)", padding:"22px 13px 16px", display:"flex", flexDirection:"column", gap:3, overflow:"auto" }}>
          <div style={{ display:"flex", alignItems:"baseline", gap:8, padding:"0 9px 6px" }}>
            <span style={{ fontSize:19, fontWeight:800, fontStyle:"italic", letterSpacing:-.6 }}>marathon</span>
            <span style={{ fontSize:9.5, fontWeight:700, letterSpacing:5, color:"#4A7FFF" }}>CLUB</span>
          </div>
          <button onClick={handleExit} style={{ display:"flex", alignItems:"center", gap:8, background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.08)", color:"rgba(233,238,255,.6)", borderRadius:10, padding:"9px 12px", fontSize:12.5, fontWeight:600, cursor:"pointer", fontFamily:FONT, marginBottom:8 }}>← Exit</button>
          <div style={{ fontSize:9, letterSpacing:".2em", textTransform:"uppercase", color:"rgba(233,238,255,.3)", padding:"10px 9px 6px", fontWeight:700 }}>Reports</div>
          {TABS.map(t => {
            const on = tab === t.key;
            return (
              <button key={t.key} onClick={() => setTab(t.key)}
                style={{ display:"flex", alignItems:"center", gap:11, width:"100%", textAlign:"left", cursor:"pointer", fontFamily:FONT, fontSize:13, fontWeight:600, borderRadius:10, padding:"9px 11px",
                         background: on ? "rgba(74,127,255,.13)" : "transparent", border: on ? "1px solid rgba(74,127,255,.42)" : "1px solid transparent",
                         color: on ? "#9DBCFF" : "rgba(233,238,255,.55)" }}>
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" style={{ flexShrink:0, opacity:.9 }}>{INSIGHT_TAB_ICON[t.key] || <path d="M4 20V10M10 20V4M16 20v-7" />}</svg>
                <span style={{ flex:1 }}>{t.label}</span>
              </button>
            );
          })}
          <div style={{ flex:1 }} />
          <div style={{ padding:"9px 11px", borderRadius:11, background:"rgba(255,255,255,.022)", border:"1px solid rgba(255,255,255,.08)", fontSize:11, color:"rgba(233,238,255,.5)" }}>
            <span style={{ color:"#9DBCFF", fontWeight:800, fontVariantNumeric:"tabular-nums" }}>{filteredLog.length.toLocaleString()}</span> events in view
          </div>
        </aside>

        <div style={{ minWidth:0, display:"flex", flexDirection:"column", overflow:"hidden" }}>
          <div style={{ padding:"20px 28px 14px", borderBottom:"1px solid rgba(255,255,255,.08)", background:"radial-gradient(800px 280px at 15% -60%, rgba(74,127,255,.08), transparent)" }}>
            <div style={{ fontSize:23, fontWeight:800, letterSpacing:-.4 }}>{(TABS.find(t=>t.key===tab)||{}).label || "Insights"}</div>
            <div style={{ fontSize:12.5, color:"rgba(233,238,255,.5)", marginTop:3 }}>Internal insights · {filterLabel}</div>
            <div style={{ display:"flex", alignItems:"center", gap:10, flexWrap:"wrap", marginTop:14 }}>
              {storePills()}
              <div style={{ flex:1 }} />
              {auditBtn}
            </div>
            {tab !== "reorder" && (
              <div style={{ marginTop:12 }}>
                <InsightsDatePicker mode={filterMode} setMode={setFilterMode} dateStr={filterDate} setDateStr={setFilterDate} />
              </div>
            )}
          </div>
          <div style={{ flex:1, overflow:"auto", padding:"18px 28px 48px" }}>
            <div style={{ maxWidth:1080, margin:"0 auto" }}>{content}</div>
          </div>
        </div>
        {auditOpen && <AuditModal audit={audit} onClose={() => setAuditOpen(false)} />}
      </div>
    );
  }

  return (
    <div style={{ minHeight:"100vh", background:"#000", color:"#fff", fontFamily:FONT, maxWidth:430, margin:"0 auto", overflowX:"hidden", paddingBottom:40 }}>
      {/* TOP BAR */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"50px 14px 0" }}>
        <div onClick={handleExit} style={{ color:"#4A7FFF", fontSize:13, fontWeight:500, cursor:"pointer" }}>← Exit</div>
        <div style={{ display:"flex", alignItems:"center", gap:6 }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeWidth="2" strokeLinecap="round" style={{ filter:"drop-shadow(0 0 4px rgba(60,110,255,.5))" }}>
            <line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/>
          </svg>
          <div style={{ fontSize:12, fontWeight:700, color:"#fff", letterSpacing:"0.5px" }}>INTERNAL INSIGHTS</div>
        </div>
        <div style={{ fontSize:10, color:"#4A7FFF", fontWeight:500 }}>{filteredLog.length} entries</div>
      </div>
      {/* Store filter — All / Marathon PE / Trophy / Pine. Hidden on the AI
          Reorder tab (global analysis, not store-sliced). */}
      <div style={{ padding:"10px 14px 0", display:"flex", gap:6, overflowX:"auto", visibility: tab === "reorder" ? "hidden" : "visible" }}>
        {[["all","All"],["marathon-pe","Marathon PE"],["trophy","Trophy"],["pine","Pine"]].map(([val, label]) => {
          const on = storeFilter === val;
          return (
            <button key={val} onClick={() => setStoreFilter(val)}
              style={{ flexShrink:0, padding:"7px 12px", borderRadius:999, fontSize:11.5, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap",
                       background: on ? "rgba(60,110,255,.22)" : "rgba(255,255,255,.03)",
                       border: "1px solid " + (on ? "rgba(60,110,255,.55)" : "rgba(255,255,255,.08)"),
                       color: on ? "#fff" : "rgba(255,255,255,.5)",
                       boxShadow: on ? "0 0 6px rgba(60,110,255,.35)" : "none" }}>
              {label}
            </button>
          );
        })}
      </div>
      {/* TAB BAR */}
      <div style={{ display:"flex", overflowX:"auto", scrollbarWidth:"none", padding:"10px 14px 0", gap:0, borderBottom:"1px solid rgba(255,255,255,.06)", marginBottom:12 }}>
        {TABS.map(t => {
          const on = tab === t.key;
          return (
            <div key={t.key} onClick={() => setTab(t.key)}
                 style={{ padding:"8px 14px", fontSize:12, fontWeight: on ? 600 : 500, color: on ? "#4A7FFF" : "rgba(255,255,255,.3)", borderBottom: on ? "2px solid #4A7FFF" : "2px solid transparent", whiteSpace:"nowrap", cursor:"pointer", display:"flex", alignItems:"center", gap:5 }}>
              {t.icon ? <span style={{ fontSize:13 }}>{t.icon}</span> : null} {t.label}
            </div>
          );
        })}
      </div>
      {/* Date picker is hidden on the reorder tab — InsightReorderTab does not
          consume filterMode/filterDate, so showing it would imply a filter that
          is actually a no-op. CR finding (outside-diff). */}
      {tab !== "reorder" && (
        <InsightsDatePicker mode={filterMode} setMode={setFilterMode} dateStr={filterDate} setDateStr={setFilterDate} />
      )}

      {/* Order Audit button — admin-protected (Insights password gate already passed) */}
      <div style={{ padding:"0 14px 12px" }}>
        <button onClick={() => setAuditOpen(true)}
                style={{
                  width:"100%",
                  background: audit.diff !== 0 ? "rgba(248,113,113,.12)" : "rgba(60,110,255,.08)",
                  border: audit.diff !== 0 ? "1px solid rgba(248,113,113,.4)" : "1px solid rgba(60,110,255,.3)",
                  color: audit.diff !== 0 ? "#F87171" : "#4A7FFF",
                  borderRadius:10, padding:"10px 14px", fontSize:13, fontWeight:600, cursor:"pointer",
                  display:"flex", alignItems:"center", justifyContent:"center", gap:8,
                }}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 9v2m0 4h.01M5 19h14a2 2 0 002-2v-1a8 8 0 10-16 0v1a2 2 0 002 2z"/></svg>
          Run Order Audit
          {audit.diff !== 0 && <span style={{ marginLeft:4, fontSize:11, fontWeight:700 }}>· {audit.diff} unaccounted</span>}
        </button>
      </div>

      <div style={{ padding:"0 14px 16px" }}
        onTouchStart={e => { touchStartX.current = e.touches[0].clientX; }}
        onTouchEnd={handleSwipe}>
        {content}
      </div>

      {/* AUDIT MODAL */}
      {auditOpen && <AuditModal audit={audit} onClose={() => setAuditOpen(false)} />}
    </div>
  );
}

// ─── AUDIT MODAL ──────────────────────────────────────────────────────────────
function AuditModal({ audit, onClose }) {
  const Section = ({ title, children, count, danger }) => (
    <div style={{ marginBottom:16, background:"rgba(4,5,10,1)", border: danger ? "1px solid rgba(248,113,113,.4)" : "1px solid rgba(60,110,255,.2)", borderRadius:10, padding:14 }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:10 }}>
        <div style={{ fontSize:12, fontWeight:700, color: danger ? "#F87171" : "#4A7FFF", textTransform:"uppercase", letterSpacing:"0.8px" }}>{title}</div>
        {count != null && <div style={{ fontSize:11, fontWeight:700, color:"#fff", background: danger ? "rgba(248,113,113,.2)" : "rgba(60,110,255,.2)", padding:"2px 9px", borderRadius:999 }}>{count}</div>}
      </div>
      {children}
    </div>
  );
  const Row = ({ label, value, highlight }) => (
    <div style={{ display:"flex", justifyContent:"space-between", padding:"4px 0", borderBottom:"1px solid rgba(255,255,255,.05)" }}>
      <span style={{ color:"rgba(255,255,255,.6)", fontSize:12 }}>{label}</span>
      <span style={{ color: highlight ? "#F87171" : "#fff", fontSize:12, fontWeight:600 }}>{value}</span>
    </div>
  );
  const fmt = (s) => s ? String(s).slice(0, 19).replace("T", " ") : "—";

  const OrderTable = ({ orders }) => {
    if (!orders.length) return <div style={{ color:"rgba(255,255,255,.4)", fontSize:11, padding:"4px 0" }}>None.</div>;
    return (
      <div style={{ overflowX:"auto", marginTop:6 }}>
        <table style={{ width:"100%", fontSize:10, borderCollapse:"collapse", color:"#ddd" }}>
          <thead>
            <tr style={{ color:"rgba(255,255,255,.5)" }}>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>#</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>status</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>customer</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>product</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>created</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>readyAt</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>collectedAt</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>oosAt</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>tomorrowAt</th>
              <th style={{ textAlign:"left", padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.1)" }}>flags</th>
            </tr>
          </thead>
          <tbody>
            {orders.map(o => (
              <tr key={o.id}>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)", color:"#6A9FFF", fontWeight:700 }}>{o.id}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)", color: o.status ? "#fff" : "#F87171" }}>{o.status === undefined ? "(undefined)" : (o.status || "(empty)")}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)" }}>{o.customerName || "—"}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)" }}>{(o.productName || "—") + (o.size ? ` Sz${formatSize(o.size)}` : "")}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)" }}>{fmt(o.createdAt)}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)" }}>{fmt(o.readyAt)}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)" }}>{fmt(o.collectedAt)}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)" }}>{fmt(o.outOfStockAt)}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)" }}>{fmt(o.comingTomorrowAt)}</td>
                <td style={{ padding:"4px 6px", borderBottom:"1px solid rgba(255,255,255,.04)", fontSize:9, color:"#F87171" }}>
                  {[o.deleted&&"deleted", o.removed&&"removed", o.archived&&"archived"].filter(Boolean).join(",") || "—"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,.85)", zIndex:9999, display:"flex", alignItems:"flex-start", justifyContent:"center", padding:"20px 8px", overflowY:"auto" }}
         onClick={onClose}>
      <div onClick={e => e.stopPropagation()}
           style={{ width:"100%", maxWidth:560, background:"#000", border:"1px solid rgba(60,110,255,.4)", borderRadius:14, padding:16, color:"#fff", fontFamily:FONT, boxShadow:"0 0 32px rgba(60,110,255,.2)" }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:12, paddingBottom:10, borderBottom:"1px solid rgba(60,110,255,.2)" }}>
          <div>
            <div style={{ fontSize:14, fontWeight:800, color:"#fff" }}>Order Audit</div>
            <div style={{ fontSize:11, color:"rgba(255,255,255,.4)", marginTop:2 }}>{audit.today} · live snapshot</div>
          </div>
          <button onClick={onClose} style={{ background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.15)", color:"#fff", borderRadius:8, padding:"6px 12px", fontSize:12, cursor:"pointer" }}>Close</button>
        </div>

        {/* Reconciliation */}
        <Section title="Reconciliation (today)" danger={audit.diff !== 0} count={audit.diff !== 0 ? `Δ ${audit.diff}` : "OK"}>
          <Row label="Total orders in Firebase (all dates)" value={audit.totalAll} />
          <Row label="Orders created today (createdAt)" value={audit.totalToday} />
          <Row label="READY" value={audit.ready} />
          <Row label="COLLECTED" value={audit.collected} />
          <Row label="OUT_OF_STOCK" value={audit.oos} />
          <Row label="COMING_TOMORROW" value={audit.tomorrow} />
          <Row label="INCOMING" value={audit.incoming} />
          <Row label="Sum of all 5 statuses" value={audit.sumByStatus} />
          <Row label="Diff (unaccounted)" value={audit.diff} highlight={audit.diff !== 0} />
          <Row label="Returns logged today" value={audit.returnsToday} />
          <Row label="Net Sales (READY+COLLECTED − returns)" value={audit.netSales} />
        </Section>

        {/* Status distribution */}
        <Section title="Status distribution — today" count={audit.totalToday}>
          {Object.entries(audit.byStatusToday).sort((a,b) => b[1] - a[1]).map(([s, c]) => (
            <Row key={s} label={s} value={c} />
          ))}
        </Section>

        <Section title="Status distribution — all orders" count={audit.totalAll}>
          {Object.entries(audit.byStatusAll).sort((a,b) => b[1] - a[1]).map(([s, c]) => (
            <Row key={s} label={s} value={c} />
          ))}
        </Section>

        {/* Order number gaps + dups */}
        <Section title="Order number gaps (today)" count={audit.gaps.length} danger={audit.gaps.length > 0}>
          <Row label="Range" value={audit.minNum != null ? `#${audit.minNum} → #${audit.maxNum}` : "—"} />
          <Row label="Span" value={audit.minNum != null ? (audit.maxNum - audit.minNum + 1) : 0} />
          <Row label="Found" value={audit.totalToday} />
          <Row label="Missing" value={audit.gaps.length} highlight={audit.gaps.length > 0} />
          {audit.gaps.length > 0 && (
            <div style={{ marginTop:8, padding:8, background:"rgba(248,113,113,.06)", border:"1px solid rgba(248,113,113,.2)", borderRadius:6, color:"#F87171", fontSize:11, wordBreak:"break-all" }}>
              {audit.gaps.map(n => `#${n.toString().padStart(3,"0")}`).join("  ")}
            </div>
          )}
        </Section>

        <Section title="Duplicate order numbers" count={audit.dups.length} danger={audit.dups.length > 0}>
          {audit.dups.length === 0 ? <div style={{ color:"rgba(255,255,255,.4)", fontSize:11 }}>None.</div> :
            audit.dups.map(d => <Row key={d.orderNumber} label={`#${d.orderNumber}`} value={`${d.count}×`} highlight />)}
        </Section>

        {/* Anomaly tables */}
        <Section title="Orders with NO status" count={audit.ordersNoStatus.length} danger={audit.ordersNoStatus.length > 0}>
          <OrderTable orders={audit.ordersNoStatus} />
        </Section>

        <Section title="Orders with UNKNOWN/legacy status" count={audit.ordersUnknownStatus.length} danger={audit.ordersUnknownStatus.length > 0}>
          <OrderTable orders={audit.ordersUnknownStatus} />
        </Section>

        <Section title="Soft-deleted orders" count={audit.softDeleted.length} danger={audit.softDeleted.length > 0}>
          <OrderTable orders={audit.softDeleted} />
        </Section>

        <Section title="Multi-timestamp orders (changed mind)" count={audit.multiStamp.length}>
          <OrderTable orders={audit.multiStamp} />
        </Section>

        <Section title="UNACCOUNTED orders (the ghosts)" count={audit.unaccounted.length} danger={audit.unaccounted.length > 0}>
          {audit.unaccounted.length === 0
            ? <div style={{ color:"rgba(74,222,128,.7)", fontSize:11 }}>All today's orders fall into a known status. ✓</div>
            : <OrderTable orders={audit.unaccounted} />}
        </Section>

        <div style={{ textAlign:"center", paddingTop:8, color:"rgba(255,255,255,.3)", fontSize:10 }}>
          Tap outside or Close to dismiss · screenshot to share
        </div>
      </div>
    </div>
  );
}

// ─── PRIVACY POLICY PAGE ─────────────────────────────────────────────────────
function PrivacyPage() {
  const section = (num, title, children) => (
    <div style={{ marginBottom: "2rem" }}>
      <h2 style={{ fontSize: "1.1rem", fontWeight: "700", color: "#111", marginBottom: "0.5rem" }}>
        {num}. {title}
      </h2>
      <p style={{ color: "#444", lineHeight: "1.75", margin: 0 }}>{children}</p>
    </div>
  );

  return (
    <div style={{ minHeight: "100vh", background: "#fff", fontFamily: "-apple-system, BlinkMacSystemFont, 'SF Pro Display', sans-serif", color: "#111" }}>
      <style>{`/* SF Pro Display — system font, no import needed */`}</style>

      {/* Header */}
      <div style={{ borderBottom: "1px solid #e5e7eb", padding: "1.25rem 1.5rem", display: "flex", alignItems: "center", gap: "0.75rem" }}>
        <span style={{ fontFamily: "'Bebas Neue', system-ui", fontSize: "1.4rem", letterSpacing: "0.05em", color: "#111" }}>MARATHON CLUB</span>
      </div>

      {/* Content */}
      <div style={{ maxWidth: "680px", margin: "0 auto", padding: "2.5rem 1.5rem" }}>
        <h1 style={{ fontFamily: "'Bebas Neue'", fontSize: "2.2rem", letterSpacing: "0.04em", color: "#111", marginBottom: "0.4rem" }}>
          Privacy Policy
        </h1>
        <p style={{ color: "#9ca3af", fontSize: "0.88rem", marginBottom: "2.5rem" }}>Last updated: May 2026</p>

        {section(1, "Introduction",
          `Marathon Club ("we", "our", "us") is committed to protecting your privacy. This policy explains how we collect and use your information.`)}
        {section(2, "Information We Collect",
          "We collect your name and phone number when you place an order at our store. This information is provided by our store staff on your behalf.")}
        {section(3, "How We Use Your Information",
          "We use your phone number to send you WhatsApp notifications about your order status, including when your order is placed, ready for collection, out of stock, or available the next day.")}
        {section(4, "Data Storage",
          "Your order information is stored securely in Google Firebase. We retain order data for operational and business analytics purposes.")}
        {section(5, "WhatsApp Messages",
          "By placing an order at Marathon Club, you consent to receiving WhatsApp notifications about your order. Messages are sent via the Meta WhatsApp Business API.")}
        {section(6, "Your Rights",
          <>You may contact us at any time to request removal of your data by contacting us at{" "}
            <a href="mailto:distreda@gmail.com" style={{ color: "#FF3D00", textDecoration: "none" }}>distreda@gmail.com</a>.
          </>)}
        {section(7, "Contact",
          <>For any privacy-related questions, contact us at{" "}
            <a href="mailto:distreda@gmail.com" style={{ color: "#FF3D00", textDecoration: "none" }}>distreda@gmail.com</a>
            {" "}or visit us at Marathon Club, Durban, South Africa.
          </>)}
      </div>

      {/* Footer */}
      <div style={{ borderTop: "1px solid #e5e7eb", padding: "1.25rem 1.5rem", textAlign: "center" }}>
        <span style={{ color: "#9ca3af", fontSize: "0.8rem" }}>© {new Date().getFullYear()} Marathon Club. All rights reserved.</span>
      </div>
    </div>
  );
}

// ─── PWA: update banner + install prompts ────────────────────────────────────
// Listens for the custom events main.jsx dispatches on SW updates and the
// Android beforeinstallprompt capture. iOS prompt is detection-based.
function PWAUpdateBanner() {
  const [show, setShow] = useState(false);
  useEffect(() => {
    const onUpdate = () => setShow(true);
    window.addEventListener("pwa-update-available", onUpdate);
    return () => window.removeEventListener("pwa-update-available", onUpdate);
  }, []);
  if (!show) return null;
  const reload = () => {
    const w = window.__pwaWaiting;
    if (w) w.postMessage("skipWaiting"); // controllerchange in main.jsx triggers reload
    else window.location.reload();
  };
  return (
    <div onClick={reload} role="button"
         style={{ position:"fixed", top:0, left:0, right:0, zIndex:10000, background:"#4A7FFF", color:"#fff",
                  fontFamily:"-apple-system,BlinkMacSystemFont,'SF Pro Display',sans-serif", fontSize:13, fontWeight:600,
                  padding:"10px 14px", display:"flex", alignItems:"center", justifyContent:"center", gap:8,
                  cursor:"pointer", boxShadow:"0 2px 12px rgba(0,0,0,.4)" }}>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 11-2.12-9.36L23 10"/>
      </svg>
      <span style={{ flex:1, textAlign:"center" }}>Update available — tap to refresh.</span>
      <span onClick={(e) => { e.stopPropagation(); setShow(false); }}
            style={{ padding:"0 6px", fontSize:18, lineHeight:1, opacity:0.85 }}>×</span>
    </div>
  );
}

function AndroidInstallChip() {
  const DISMISS_KEY = "pwa.installPrompt.dismissed";
  const [available, setAvailable] = useState(!!window.__pwaInstallPrompt);
  const [dismissed, setDismissed] = useState(() => localStorage.getItem(DISMISS_KEY) === "1");
  useEffect(() => {
    const on = () => setAvailable(true);
    window.addEventListener("pwa-install-available", on);
    return () => window.removeEventListener("pwa-install-available", on);
  }, []);
  if (!available || dismissed) return null;
  const install = async () => {
    const e = window.__pwaInstallPrompt;
    if (!e) return;
    e.prompt();
    await e.userChoice.catch(() => {});
    window.__pwaInstallPrompt = null;
    setAvailable(false);
  };
  const dismiss = () => { localStorage.setItem(DISMISS_KEY, "1"); setDismissed(true); };
  return (
    <div style={{ position:"fixed", top:10, right:10, zIndex:9999, display:"flex", alignItems:"center", gap:6,
                  background:"rgba(60,110,255,.15)", border:"1px solid rgba(60,110,255,.5)", borderRadius:999,
                  padding:"6px 10px", backdropFilter:"blur(8px)" }}>
      <button onClick={install}
              style={{ background:"none", border:"none", color:"#4A7FFF", fontSize:12, fontWeight:700, cursor:"pointer", padding:0, display:"flex", alignItems:"center", gap:5 }}>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/>
        </svg>
        Install Marathon
      </button>
      <span onClick={dismiss} style={{ color:"rgba(255,255,255,.5)", fontSize:14, cursor:"pointer", lineHeight:1, padding:"0 2px" }}>×</span>
    </div>
  );
}

function IOSInstallTooltip() {
  const DISMISS_KEY = "pwa.iosTooltip.dismissed";
  const [show, setShow] = useState(false);
  useEffect(() => {
    if (localStorage.getItem(DISMISS_KEY) === "1") return;
    const ua = navigator.userAgent;
    const isIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
    const isSafari = /^((?!chrome|android|crios|fxios).)*safari/i.test(ua);
    const isStandalone = window.navigator.standalone === true ||
      window.matchMedia("(display-mode: standalone)").matches;
    if (isIOS && isSafari && !isStandalone) setShow(true);
  }, []);
  if (!show) return null;
  const dismiss = () => { localStorage.setItem(DISMISS_KEY, "1"); setShow(false); };
  return (
    <div style={{ position:"fixed", left:10, right:10, bottom:14, zIndex:9999,
                  background:"rgba(4,5,10,.95)", border:"1px solid rgba(60,110,255,.5)", borderRadius:14,
                  padding:"12px 14px", display:"flex", alignItems:"center", gap:10,
                  boxShadow:"0 4px 24px rgba(0,0,0,.6)", backdropFilter:"blur(8px)",
                  fontFamily:"-apple-system,BlinkMacSystemFont,'SF Pro Display',sans-serif" }}>
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#4A7FFF" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink:0 }}>
        <path d="M4 12v7a2 2 0 002 2h12a2 2 0 002-2v-7"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/>
      </svg>
      <div style={{ flex:1, color:"#fff", fontSize:12, lineHeight:1.4 }}>
        Tap the share icon, then <strong style={{ color:"#4A7FFF" }}>Add to Home Screen</strong> to install Marathon.
      </div>
      <span onClick={dismiss} style={{ color:"rgba(255,255,255,.5)", fontSize:18, cursor:"pointer", lineHeight:1, padding:"0 4px" }}>×</span>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Group Broadcast (Phase 3)
// ─────────────────────────────────────────────────────────────────────────────
// Admin-only screen for sending caption + media broadcasts to selected
// WhatsApp groups via the broadcast service VM. Access is gated in
// RoleSelector (the card only renders when isAdmin === true) and in the
// App view cascade (BROADCAST_GROUPS branch checks isAdmin).
//
// Flow:
//   1. Fetch groups on mount via getBroadcastGroups Cloud Function (us-central1).
//   2. Multi-select groups, write caption, optionally attach up to 5 media
//      (uploaded in parallel via uploadBroadcastMedia → Firebase Storage).
//   3. Send button opens a confirmation modal showing recipient count.
//   4. On confirm, calls sendBroadcast Cloud Function → on success, pushes
//      history record to /broadcastHistory and resets the form.
//   5. Recent Broadcasts section reads /broadcastHistory (top 10).

const MAX_PHOTOS = 50;
const MAX_VIDEOS = 50;

function BroadcastGroupsView({ authUser, onExit }) {
  const [groups,      setGroups]      = useState(null);     // null = loading
  const [loadError,   setLoadError]   = useState(null);
  const [selectedIds, setSelectedIds] = useState(() => new Set());
  const [caption,     setCaption]     = useState("");
  const [media,       setMedia]       = useState([]);
  const [showConfirm, setShowConfirm] = useState(false);
  const [sending,     setSending]     = useState(false);
  const [sendError,   setSendError]   = useState(null);
  const [sendSuccess, setSendSuccess] = useState(null);
  const fileInputRef = useRef(null);
  const history      = useGroupBroadcastHistory();

  async function fetchGroups() {
    setGroups(null);
    setLoadError(null);
    try {
      const callable = httpsCallable(functionsUS, "getBroadcastGroups");
      const result   = await callable({});
      const list     = result.data?.groups || [];
      list.sort((a, b) => {
        if (a.isAdmin !== b.isAdmin) return a.isAdmin ? -1 : 1;
        return String(a.name || "").localeCompare(String(b.name || ""));
      });
      setGroups(list);
    } catch (err) {
      console.error("getBroadcastGroups failed:", err);
      setLoadError(err.message || "Failed to load groups.");
      setGroups([]);
    }
  }
  useEffect(() => { fetchGroups(); }, []);

  const selectedGroups = useMemo(
    () => (groups || []).filter(g => selectedIds.has(g.id)),
    [groups, selectedIds]
  );
  const totalRecipients = useMemo(
    () => selectedGroups.reduce((sum, g) => sum + (g.participantCount || 0), 0),
    [selectedGroups]
  );

  const photoCount = media.filter(m => m.kind === "image").length;
  const videoCount = media.filter(m => m.kind === "video").length;

  const hasGroups       = selectedIds.size > 0;
  const hasCaption      = caption.trim().length > 0;
  const hasDoneMedia    = media.some(m => m.status === "done");
  const anyMediaPending = media.some(m => m.status === "uploading");
  const canSend         = hasGroups && (hasCaption || hasDoneMedia) && !anyMediaPending && !sending;

  function toggleGroup(id) {
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }

  function handleAddMedia(e) {
    const files = Array.from(e.target.files || []);
    if (e.target) e.target.value = "";
    let photosRoom = MAX_PHOTOS - photoCount;
    let videosRoom = MAX_VIDEOS - videoCount;
    const items = [];
    for (const file of files) {
      const kind = file.type.startsWith("video") ? "video" : "image";
      if (kind === "image" && photosRoom > 0) {
        items.push({ id: crypto.randomUUID(), file, previewUrl: URL.createObjectURL(file), kind, name: file.name, status: "uploading" });
        photosRoom--;
      } else if (kind === "video" && videosRoom > 0) {
        items.push({ id: crypto.randomUUID(), file, previewUrl: URL.createObjectURL(file), kind, name: file.name, status: "uploading" });
        videosRoom--;
      }
      // Files past their per-type limit are silently dropped — counts are visible in the UI so the user can see why.
    }
    if (items.length === 0) return;
    setMedia(prev => [...prev, ...items]);
    items.forEach(item => {
      uploadBroadcastMedia(item.file)
        .then(({ url, path }) => {
          setMedia(prev => prev.map(m => m.id === item.id ? { ...m, status:"done", url, path } : m));
        })
        .catch(err => {
          console.error("Broadcast media upload failed:", item.file?.name, "| type:", item.file?.type || "(empty)", "| size:", item.file?.size, "| err:", err);
          setMedia(prev => prev.map(m => m.id === item.id ? { ...m, status:"error", error: err.message || String(err) } : m));
        });
    });
  }

  function removeMedia(id) {
    setMedia(prev => {
      const item = prev.find(m => m.id === id);
      if (item?.previewUrl) URL.revokeObjectURL(item.previewUrl);
      return prev.filter(m => m.id !== id);
    });
  }

  async function handleConfirmSend() {
    setSending(true);
    setSendError(null);
    setSendSuccess(null);
    const t0 = performance.now();
    try {
      const mediaUrls = media.filter(m => m.status === "done").map(m => m.url);
      const groupIds  = [...selectedIds];
      const callable  = httpsCallable(functionsUS, "sendBroadcast");
      const result    = await callable({ groupIds, caption: caption.trim(), mediaUrls });
      const durationMs  = Math.round(performance.now() - t0);
      const broadcastId = result.data?.broadcastId ?? null;

      push(ref(database, "broadcastHistory"), {
        timestamp:       serverNowIso(),
        userEmail:       authUser?.email || null,
        groupCount:      groupIds.length,
        totalRecipients,
        captionPreview:  caption.trim().slice(0, 80),
        mediaCount:      mediaUrls.length,
        status:          "ok",
        broadcastId,
        durationMs,
      }).catch(err => console.warn("Failed to save broadcast history:", err));

      setSendSuccess({ broadcastId, durationMs });
      media.forEach(m => m.previewUrl && URL.revokeObjectURL(m.previewUrl));
      setSelectedIds(new Set());
      setCaption("");
      setMedia([]);
    } catch (err) {
      console.error("sendBroadcast failed:", err);
      setSendError(err.message || "Send failed.");
    } finally {
      setSending(false);
    }
  }

  function closeModal() {
    if (sending) return;
    setShowConfirm(false);
    setSendError(null);
    setSendSuccess(null);
  }

  return (
    <div style={{ minHeight:"100vh", background:BG, color:"#fff", fontFamily:FONT, paddingBottom:"3rem" }}>
      <BroadcastTopBar onExit={onExit} onRefresh={fetchGroups} refreshing={groups === null} />

      <div style={{ maxWidth:430, margin:"0 auto", padding:"1rem", display:"flex", flexDirection:"column", gap:"1rem" }}>

        <BroadcastSection title="Groups" trailing={hasGroups ? `${selectedIds.size} selected` : null}>
          {groups === null && !loadError && <div style={{ color:"#555", fontSize:"0.85rem", padding:"0.5rem 0" }}>Loading groups…</div>}
          {loadError && <BroadcastErrorBlock onRetry={fetchGroups}>{loadError}</BroadcastErrorBlock>}
          {groups && groups.length === 0 && !loadError && (
            <div style={{ color:"#666", fontSize:"0.85rem", padding:"0.5rem 0" }}>No groups returned by the broadcast service.</div>
          )}
          {groups && groups.map(g => (
            <BroadcastGroupRow key={g.id} group={g} selected={selectedIds.has(g.id)} onToggle={() => toggleGroup(g.id)} />
          ))}
        </BroadcastSection>

        <BroadcastSection title="Caption" trailing={`${caption.length}/1024`}>
          <textarea
            value={caption}
            onChange={e => setCaption(e.target.value.slice(0, 1024))}
            placeholder="Write your broadcast message…"
            rows={4}
            style={{ width:"100%", background:"transparent", color:"#fff", border:"none", outline:"none", padding:"0.25rem 0", fontSize:"0.95rem", fontFamily:FONT, resize:"vertical" }}
          />
        </BroadcastSection>

        <BroadcastSection
          title="Media"
          trailing={(photoCount < MAX_PHOTOS || videoCount < MAX_VIDEOS) ? (
            <button onClick={() => fileInputRef.current?.click()} style={{ ...bBlue, padding:"0.35rem 0.75rem" }}>+ Add</button>
          ) : null}
        >
          <input ref={fileInputRef} type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/3gpp,video/webm,.jpg,.jpeg,.png,.webp,.mp4,.mov,.3gp,.webm" onChange={handleAddMedia} style={{ display:"none" }} />
          <div style={{ fontSize:"0.75rem", color:"#9CA3AF", marginBottom: media.length > 0 ? "0.55rem" : "0.4rem" }}>
            Photos: <span style={{ color: photoCount >= MAX_PHOTOS ? "#F87171" : "#fff", fontWeight:600 }}>{photoCount}/{MAX_PHOTOS}</span>
            <span style={{ color:"#444", padding:"0 8px" }}>·</span>
            Videos: <span style={{ color: videoCount >= MAX_VIDEOS ? "#F87171" : "#fff", fontWeight:600 }}>{videoCount}/{MAX_VIDEOS}</span>
          </div>
          {media.length === 0 && (
            <div style={{ color:"#666", fontSize:"0.85rem" }}>Optional. Up to {MAX_PHOTOS} photos (JPG/PNG/WEBP, 16 MB each) and {MAX_VIDEOS} videos (MP4/MOV, 200 MB each).</div>
          )}
          {media.length > 0 && (
            <div style={{ display:"flex", flexWrap:"wrap", gap:"0.5rem" }}>
              {media.map(m => <BroadcastMediaThumb key={m.id} item={m} onRemove={() => removeMedia(m.id)} />)}
            </div>
          )}
        </BroadcastSection>

        {(hasGroups || hasCaption || hasDoneMedia) && (
          <BroadcastSection>
            <div style={{ color:"#9CA3AF", fontSize:"0.85rem", marginBottom:"0.75rem", lineHeight:1.4 }}>
              {hasGroups
                ? <>Sending to <span style={{ color:BLUE_L, fontWeight:600 }}>{selectedIds.size}</span> group{selectedIds.size === 1 ? "" : "s"} · ~<span style={{ color:BLUE_L, fontWeight:600 }}>{totalRecipients.toLocaleString()}</span> recipient{totalRecipients === 1 ? "" : "s"}</>
                : "Select at least one group to send."}
            </div>
            <button
              onClick={() => setShowConfirm(true)}
              disabled={!canSend}
              style={{
                width:"100%", padding:"0.9rem",
                background: canSend ? BLUE : "rgba(60,110,255,.15)",
                color: canSend ? "#fff" : "rgba(255,255,255,.4)",
                border:"none", borderRadius:RADIUS, fontSize:"1rem", fontWeight:600,
                cursor: canSend ? "pointer" : "default",
              }}>
              {anyMediaPending ? "Uploading media…" : "Send Broadcast"}
            </button>
          </BroadcastSection>
        )}

        <BroadcastSection title="Recent Broadcasts">
          {history.length === 0 && <div style={{ color:"#666", fontSize:"0.85rem" }}>No broadcasts yet.</div>}
          {history.map(item => <BroadcastHistoryRow key={item.id} item={item} />)}
        </BroadcastSection>
      </div>

      {showConfirm && (
        <BroadcastConfirmModal
          selectedGroups={selectedGroups}
          totalRecipients={totalRecipients}
          caption={caption.trim()}
          donePhotoCount={media.filter(m => m.status === "done" && m.kind === "image").length}
          doneVideoCount={media.filter(m => m.status === "done" && m.kind === "video").length}
          sending={sending}
          sendError={sendError}
          sendSuccess={sendSuccess}
          onCancel={closeModal}
          onConfirm={handleConfirmSend}
        />
      )}
    </div>
  );
}

function BroadcastTopBar({ onExit, onRefresh, refreshing }) {
  return (
    <div style={{ position:"sticky", top:0, zIndex:10, background:"rgba(0,0,0,.85)", backdropFilter:"blur(10px)", borderBottom:BORDER, padding:"0.75rem 1rem", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
      <button onClick={onExit} style={{ background:"transparent", border:"none", color:BLUE, cursor:"pointer", fontSize:"0.9rem", fontWeight:600, padding:"4px 8px", display:"flex", alignItems:"center", gap:6 }}>
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
        Exit
      </button>
      <div style={{ fontSize:"0.95rem", fontWeight:600, color:"#fff" }}>Group Broadcast</div>
      <button onClick={onRefresh} disabled={refreshing} style={{ background:"transparent", border:"none", color:BLUE, cursor: refreshing ? "default" : "pointer", padding:"4px 8px", opacity: refreshing ? 0.4 : 1 }}>
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ animation: refreshing ? "bcastSpin 1s linear infinite" : "none" }}>
          <polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0114.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0020.49 15"/>
        </svg>
      </button>
    </div>
  );
}

function BroadcastSection({ title, trailing, children }) {
  return (
    <div style={{ background:CARD, border:BORDER, borderRadius:RADIUS, padding:"0.9rem", boxShadow:GLOW }}>
      {title && (
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"0.6rem", gap:8 }}>
          <div style={{ fontSize:"0.7rem", fontWeight:800, color:BLUE, letterSpacing:"2px", textTransform:"uppercase" }}>{title}</div>
          {trailing != null && <div style={{ fontSize:"0.75rem", color:"#666" }}>{trailing}</div>}
        </div>
      )}
      {children}
    </div>
  );
}

function BroadcastErrorBlock({ children, onRetry }) {
  return (
    <div style={{ background:"rgba(248,113,113,.08)", border:"1px solid rgba(248,113,113,.3)", borderRadius:10, padding:"0.7rem", color:"#F87171", fontSize:"0.85rem", display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
      <div>{children}</div>
      {onRetry && (
        <button onClick={onRetry} style={{ background:"transparent", border:"1px solid rgba(248,113,113,.3)", color:"#F87171", borderRadius:10, padding:"0.35rem 0.75rem", fontWeight:600, fontSize:"0.8rem", cursor:"pointer" }}>Retry</button>
      )}
    </div>
  );
}

function BroadcastGroupRow({ group, selected, onToggle }) {
  return (
    <div onClick={onToggle} style={{ display:"flex", alignItems:"center", gap:10, padding:"0.6rem 0", borderBottom:"1px solid rgba(255,255,255,.04)", cursor:"pointer" }}>
      <div style={{ width:22, height:22, borderRadius:6, background: selected ? BLUE : "transparent", border: selected ? `1px solid ${BLUE}` : "1px solid rgba(255,255,255,.18)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
        {selected && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>}
      </div>
      <div style={{ flex:1, minWidth:0 }}>
        <div style={{ fontSize:"0.9rem", color:"#fff", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{group.name || group.id}</div>
        <div style={{ fontSize:"0.75rem", color:"#666", display:"flex", alignItems:"center", gap:6, marginTop:2 }}>
          <span>{(group.participantCount || 0).toLocaleString()} {group.participantCount === 1 ? "person" : "people"}</span>
          {group.isAdmin && <span style={{ background:"rgba(60,110,255,.15)", color:BLUE_L, padding:"1px 7px", borderRadius:999, fontSize:"0.7rem", fontWeight:600 }}>admin</span>}
        </div>
      </div>
    </div>
  );
}

function BroadcastMediaThumb({ item, onRemove }) {
  return (
    <div style={{ position:"relative", width:72, height:72, borderRadius:10, overflow:"hidden", background:"rgba(255,255,255,.05)", border:BORDER, flexShrink:0 }}>
      {item.kind === "image"
        ? <img src={item.previewUrl} alt="" style={{ width:"100%", height:"100%", objectFit:"cover" }} />
        : <div style={{ width:"100%", height:"100%", display:"flex", alignItems:"center", justifyContent:"center" }}>
            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="23 7 16 12 23 17 23 7"/><rect x="1" y="5" width="15" height="14" rx="2"/></svg>
          </div>}
      {item.status === "uploading" && (
        <div style={{ position:"absolute", inset:0, background:"rgba(0,0,0,.55)", display:"flex", alignItems:"center", justifyContent:"center", color:BLUE_L, fontSize:"0.7rem", fontWeight:600 }}>Uploading…</div>
      )}
      {item.status === "error" && (
        <div
          onClick={() => item.error && alert(item.error)}
          title={item.error || ""}
          style={{ position:"absolute", inset:0, background:"rgba(150,20,20,.7)", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", color:"#fff", textAlign:"center", padding:4, cursor: item.error ? "pointer" : "default" }}>
          <div style={{ fontSize:"0.7rem", fontWeight:600 }}>Failed</div>
          {item.error && (
            <div style={{ fontSize:"0.55rem", marginTop:2, opacity:0.9, lineHeight:1.15, display:"-webkit-box", WebkitLineClamp:2, WebkitBoxOrient:"vertical", overflow:"hidden", padding:"0 2px" }}>
              {item.error}
            </div>
          )}
        </div>
      )}
      <button onClick={onRemove} style={{ position:"absolute", top:3, right:3, width:20, height:20, borderRadius:999, background:"rgba(0,0,0,.7)", border:"none", color:"#fff", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", padding:0 }}>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </div>
  );
}

function BroadcastHistoryRow({ item }) {
  const when = item.timestamp ? new Date(item.timestamp) : null;
  const rel  = when ? bcastRelTime(when) : "";
  const errored = item.status && item.status !== "ok";
  return (
    <div style={{ padding:"0.6rem 0", borderBottom:"1px solid rgba(255,255,255,.04)" }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:8 }}>
        <div style={{ fontSize:"0.8rem", color:"#888" }}>{rel}</div>
        {errored && <span style={{ color:"#F87171", fontSize:"0.7rem", fontWeight:600 }}>FAILED</span>}
      </div>
      <div style={{ fontSize:"0.78rem", color:"#9CA3AF", marginTop:2 }}>
        {(item.groupCount || 0)} group{item.groupCount === 1 ? "" : "s"} · ~{(item.totalRecipients || 0).toLocaleString()} recipient{item.totalRecipients === 1 ? "" : "s"} · {(item.mediaCount || 0)} media
      </div>
      {item.captionPreview && (
        <div style={{ fontSize:"0.82rem", color:"#fff", marginTop:4, fontStyle:"italic" }}>"{item.captionPreview}"</div>
      )}
    </div>
  );
}

function bcastRelTime(date) {
  const diff = Math.floor((serverNowMs() - date.getTime()) / 1000);
  if (diff < 60)     return "just now";
  if (diff < 3600)   { const m = Math.floor(diff / 60);    return `${m} min${m === 1 ? "" : "s"} ago`; }
  if (diff < 86400)  { const h = Math.floor(diff / 3600);  return `${h} hr${h === 1 ? "" : "s"} ago`; }
  if (diff < 604800) { const d = Math.floor(diff / 86400); return `${d} day${d === 1 ? "" : "s"} ago`; }
  return date.toLocaleDateString();
}

function BroadcastConfirmModal({ selectedGroups, totalRecipients, caption, donePhotoCount, doneVideoCount, sending, sendError, sendSuccess, onCancel, onConfirm }) {
  const success = !!sendSuccess;
  return (
    <div style={{ position:"fixed", inset:0, zIndex:10000, background:"rgba(0,0,0,.7)", backdropFilter:"blur(4px)", display:"flex", alignItems:"center", justifyContent:"center", padding:"1rem" }}>
      <div style={{ width:"100%", maxWidth:400, background:CARD, border:BORDER_BRIGHT, borderRadius:RADIUS, padding:"1.25rem", boxShadow:GLOW, fontFamily:FONT }}>
        <h2 style={{ margin:0, fontSize:"1.1rem", color:"#fff", fontWeight:600 }}>
          {success ? "Broadcast sent" : "Confirm broadcast"}
        </h2>

        {!success && (
          <>
            <div style={{ marginTop:"0.85rem", fontSize:"0.85rem", color:"#9CA3AF", lineHeight:1.4 }}>
              Sending to <span style={{ color:BLUE_L, fontWeight:600 }}>{selectedGroups.length}</span> group{selectedGroups.length === 1 ? "" : "s"}, ~<span style={{ color:BLUE_L, fontWeight:600 }}>{totalRecipients.toLocaleString()}</span> recipient{totalRecipients === 1 ? "" : "s"}:
            </div>
            <ul style={{ margin:"0.5rem 0 0", padding:"0 0 0 1rem", color:"#bbb", fontSize:"0.82rem", maxHeight:150, overflowY:"auto" }}>
              {selectedGroups.map(g => (
                <li key={g.id}>{g.name || g.id} ({(g.participantCount || 0).toLocaleString()})</li>
              ))}
            </ul>

            {caption && (
              <div style={{ marginTop:"0.85rem" }}>
                <div style={{ fontSize:"0.7rem", color:"#666", letterSpacing:"1.5px", textTransform:"uppercase", fontWeight:600 }}>Caption</div>
                <div style={{ marginTop:4, fontSize:"0.85rem", color:"#ddd", lineHeight:1.4, maxHeight:120, overflow:"auto", whiteSpace:"pre-wrap" }}>{caption}</div>
              </div>
            )}

            {(donePhotoCount > 0 || doneVideoCount > 0) && (
              <div style={{ marginTop:"0.6rem", fontSize:"0.8rem", color:"#9CA3AF" }}>
                Media: {donePhotoCount} photo{donePhotoCount === 1 ? "" : "s"}, {doneVideoCount} video{doneVideoCount === 1 ? "" : "s"}
              </div>
            )}

            {sendError && (
              <div style={{ marginTop:"0.85rem", color:"#F87171", fontSize:"0.85rem", background:"rgba(248,113,113,.08)", border:"1px solid rgba(248,113,113,.3)", borderRadius:10, padding:"0.6rem" }}>
                {sendError}
              </div>
            )}

            <div style={{ marginTop:"1rem", display:"flex", gap:"0.6rem" }}>
              <button onClick={onCancel} disabled={sending} style={{ flex:1, padding:"0.7rem", background:"transparent", border:"1px solid rgba(255,255,255,.18)", color:"#9CA3AF", borderRadius:RADIUS, fontSize:"0.9rem", fontWeight:600, cursor: sending ? "default" : "pointer", opacity: sending ? 0.5 : 1 }}>
                Cancel
              </button>
              <button onClick={onConfirm} disabled={sending} style={{ flex:1.4, padding:"0.7rem", background: sending ? "rgba(60,110,255,.4)" : BLUE, border:"none", color:"#fff", borderRadius:RADIUS, fontSize:"0.9rem", fontWeight:600, cursor: sending ? "default" : "pointer" }}>
                {sending ? "Sending…" : (sendError ? "Retry" : "Confirm & Send")}
              </button>
            </div>
          </>
        )}

        {success && (
          <>
            <div style={{ marginTop:"0.85rem", color:"#4ADE80", fontSize:"0.9rem" }}>
              Broadcast queued successfully.
            </div>
            <div style={{ marginTop:"0.6rem", fontSize:"0.78rem", color:"#666", lineHeight:1.5 }}>
              {sendSuccess.broadcastId && <div>Broadcast ID: <code style={{ color:"#9CA3AF" }}>{sendSuccess.broadcastId}</code></div>}
              {sendSuccess.durationMs != null && <div>Took {(sendSuccess.durationMs / 1000).toFixed(1)} s</div>}
            </div>
            <button onClick={onCancel} style={{ marginTop:"1rem", width:"100%", padding:"0.7rem", background:BLUE, border:"none", color:"#fff", borderRadius:RADIUS, fontSize:"0.9rem", fontWeight:600, cursor:"pointer" }}>
              Done
            </button>
          </>
        )}
      </div>
    </div>
  );
}

// One-time global keyframe for the refresh-icon spin animation.
if (typeof document !== "undefined" && !document.getElementById("__bcast_spin")) {
  const s = document.createElement("style");
  s.id = "__bcast_spin";
  s.textContent = "@keyframes bcastSpin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}";
  document.head.appendChild(s);
}

// ─────────────────────────────────────────────────────────────────────────────
// Admin Google Sign-In (Phase 1.5)
// ─────────────────────────────────────────────────────────────────────────────
// Triggered by visiting the site with #admin in the URL, e.g.
//   https://marathon-club.web.app/#admin
// Sign-in opens a Google popup. Only ADMIN_EMAIL is allowed; any other Google
// account is signed out immediately and an error is shown.
//
// While admin is signed in:
//   • A small pill (top-right) shows "Signed in: gunid · Sign Out".
//   • All other views render normally.
//   • request.auth.token.email === ADMIN_EMAIL → broadcast Cloud Functions
//     and broadcast-media writes are allowed.
//
// Sign-out drops back to anonymous (not fully out) so the database keeps
// working for the next visitor on the device.

const ADMIN_EMAIL = "gunidmoh@gmail.com";

function AdminSignInScreen({ onCancel }) {
  const [busy,  setBusy]  = useState(false);
  const [error, setError] = useState(null);

  async function handleSignIn() {
    setBusy(true); setError(null);
    try {
      const result = await signInWithPopup(auth, googleProvider);
      if (result.user.email !== ADMIN_EMAIL) {
        const wrong = result.user.email;
        await signOut(auth); // existing onAuthStateChanged effect re-signs anonymously
        setError(`Wrong account: ${wrong}. Sign in with ${ADMIN_EMAIL}.`);
        return;
      }
      window.location.hash = ""; // success → parent unmounts this screen
    } catch (err) {
      if (err.code === "auth/popup-closed-by-user") return;
      if (err.code === "auth/operation-not-allowed") {
        setError("Google Sign-In is not enabled in Firebase Console.");
        return;
      }
      setError(err.message || String(err));
    } finally {
      setBusy(false);
    }
  }

  return (
    <div style={{ minHeight:"100vh", background:BG, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:FONT, padding:"1rem" }}>
      <div style={{ width:"100%", maxWidth:380, background:CARD, border:BORDER, borderRadius:RADIUS, padding:"2rem 1.5rem", boxShadow:GLOW }}>
        <h1 style={{ margin:0, fontSize:"1.5rem", color:"#fff", fontWeight:600 }}>Admin Sign In</h1>
        <p style={{ marginTop:"0.5rem", marginBottom:"1.5rem", color:"#888", fontSize:"0.875rem", lineHeight:1.5 }}>
          Use the <span style={{ color:BLUE_L }}>{ADMIN_EMAIL}</span> Google account.
        </p>
        <button
          onClick={handleSignIn}
          disabled={busy}
          style={{ width:"100%", padding:"0.875rem", background:BLUE, color:"#fff", border:"none", borderRadius:"10px", fontSize:"1rem", fontWeight:600, cursor:busy ? "default" : "pointer", opacity:busy ? 0.6 : 1 }}>
          {busy ? "Signing in…" : "Sign in with Google"}
        </button>
        {error && (
          <div style={{ marginTop:"1rem", color:"#F87171", fontSize:"0.875rem", lineHeight:1.4 }}>{error}</div>
        )}
        <div style={{ marginTop:"1.5rem", textAlign:"center" }}>
          <span onClick={onCancel} style={{ color:"#666", fontSize:"0.85rem", cursor:"pointer" }}>Cancel</span>
        </div>
      </div>
    </div>
  );
}

// Top-right pill shown for any signed-in non-anonymous user (super-admin via
// Google OR a staff PIN account). Tap "Sign Out" to return to the Login screen.
function UserIndicator({ label, onSignOut }) {
  return (
    <div style={{ position:"fixed", top:10, right:10, zIndex:9998, background:CARD, border:BORDER_BRIGHT, borderRadius:999, padding:"6px 12px", display:"flex", alignItems:"center", gap:8, fontFamily:FONT, fontSize:"0.75rem", boxShadow:GLOW, backdropFilter:"blur(8px)" }}>
      <span style={{ color:"#9CA3AF" }}>Signed in: <span style={{ color:BLUE_L, fontWeight:600 }}>{label}</span></span>
      <span style={{ color:"#444" }}>·</span>
      <span onClick={onSignOut} style={{ color:BLUE, cursor:"pointer", fontWeight:600 }}>Sign Out</span>
    </div>
  );
}

// ─── APP INNER ────────────────────────────────────────────────────────────────
// The post-AuthGate shell. Auth state + permissions arrive via the
// PermissionsContext provided by <AuthGate>; we no longer manage anon sign-in
// here (AuthGate handles the #tv anon path; everything else requires real
// login). Junid's #admin Google popup path still works for super-admin —
// the wantAdmin/AdminSignInScreen render happens when an unauthenticated
// session navigates to #admin, *before* AuthGate has provided context
// (which means this branch only ever fires when isSuperAdmin === false from
// AuthGate's perspective, e.g. signed out from the Google session).
function AppInner() {
  const { user: authUser, permRecord, isSuperAdmin, hasPermission, signOut: doSignOut } = usePermissions();
  // Display Checks route access — master flag + module gate (super-admin, or a
  // store-scoped display_checks grant). Used both to guard a stale persisted role
  // and to mount the view. Dark by default (master flag off).
  const displayChecksRouteOpen = displayChecksVisibleForViewer(
    { email: authUser?.email, permissions: permRecord?.permissions, destShop: permRecord?.destShop },
    isSuperAdmin ? null : (permRecord?.destShop || null)
  );
  // Stock access is gated by stockRole, NOT an app permission, so warehouse seed
  // counters keep it. canMint = may create NEW barcodes (writes /barcodes — any
  // stockRole); everyone else can still reprint EXISTING codes (read-only).
  const stockRole = isSuperAdmin ? "admin" : (permRecord?.stockRole || null);
  // UI access = a stock PERMISSION (granted in User Management) OR a stock-capable
  // stockRole (so seed counters with stockRole=warehouse keep access without a
  // permission). Actual WRITES are still gated by stockRole in the RTDB rules.
  const canAccessStock = stockRole === "admin" || stockRole === "warehouse" || hasPermission("stock_management");
  const canMint = isSuperAdmin || !!permRecord?.stockRole || hasPermission("barcode");

  // hash tracks the URL fragment for the #admin sign-in trigger and any
  // future client-side routing.
  const [hash, setHash] = useState(() => window.location.hash);
  useEffect(() => {
    const onHashChange = () => setHash(window.location.hash);
    window.addEventListener("hashchange", onHashChange);
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);
  // The desktop Assistant workspace carries its own sign-out in the sidebar, so
  // the global top-right pill is suppressed there (≥1024px) to avoid two.
  const isNarrowApp = useIsNarrow(1024);
  const wantAdmin = hash === "#admin";
  // /#admin/users (list) and /#admin/users/<uid> (detail) both mount the
  // UserManagement view. The component itself gates non-super-admin viewers
  // with a NotAuthorized screen — see src/components/UserManagement.jsx.
  const wantUserMgmt = hash === "#admin/users" || hash === "#admin/users/" || hash.startsWith("#admin/users/");
  // Legacy isAdmin alias — true for super-admin only. Some downstream views
  // (e.g. BroadcastGroupsView role check) still read this; the right gate is
  // hasPermission("broadcast"), but we keep isAdmin for back-compat.
  const isAdmin = isSuperAdmin;

  async function handleAdminSignOut() {
    await doSignOut();
    if (window.location.hash === "#admin") window.location.hash = "";
  }

  const [role, setRole] = useState(() => localStorage.getItem("marathon_role") || null);
  useEffect(() => {
    if (role) localStorage.setItem("marathon_role", role);
    else localStorage.removeItem("marathon_role");
  }, [role]);

  // Safety: if the persisted role isn't available to this user's permission
  // set (signed out, switched account, permissions revoked), drop them back
  // to RoleSelector. Prevents a blank screen and avoids exposing a view the
  // user shouldn't see.
  useEffect(() => {
    if (!role) return;
    // Stock is stockRole-gated (not permission-mapped) — drop non-stock users back home.
    if ((role === ROLES.STOCK || role === ROLES.HEALTH) && !canAccessStock) { setRole(null); return; }
    // AI Studio is isSuperAdmin-gated (not permission-mapped) — drop anyone
    // else (e.g. a stale persisted role) back to the selector instead of
    // leaving them on the null view.
    if (role === ROLES.AI_STUDIO && !isSuperAdmin) { setRole(null); return; }
    // Display Checks is gated on the master flag + module access (not a plain
    // permission map) — drop a stale/persisted role that no longer qualifies.
    if (role === ROLES.DISPLAY_CHECKS && !displayChecksRouteOpen) { setRole(null); return; }
    const required = ROLE_TO_PERMISSION[role];
    if (required && !hasPermission(required)) setRole(null);
  }, [role, hasPermission, canAccessStock, isSuperAdmin, displayChecksRouteOpen]);

  const products = useProducts();
  // Orders use the per-id map; mutations bypass setOrders entirely and write
  // straight to /orders/{id} via writeOrder() / updateOrder().
  // Store-access (audit #6-adjacent): a store-ASSIGNED staff user (permRecord.destShop
  // set — e.g. "trophy") reads ONLY their shop's orders, enforced by the /orders
  // rule (an unscoped read from them is rejected). Warehouse/admin/super-admin have
  // no destShop → full read. This is the single feed for every authenticated view.
  const myShop = isSuperAdmin ? null : (permRecord?.destShop || null);
  const orders = useOrders(myShop);
  const returnsLog = useReturnsLog();

  // ── ORDER AUDIT — runs on every render; logs only when numbers mismatch ────
  // Run window.__orderAudit() in the console for the full report.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const today = getSADateString();
    const KNOWN = new Set(["ready","collected","out_of_stock","tomorrow","on_hold","incoming","coming_tomorrow"]);

    const onTodayCreated  = orders.filter(o => o.createdAt && o.createdAt.slice(0,10) === today);
    const onTodayTouched  = orders.filter(o => {
      const ts = o.createdAt || o.updatedAt || o.readyAt || o.collectedAt;
      return ts && ts.slice(0,10) === today;
    });

    window.__orderAudit = () => {
      console.log("══════════════════════════════════════════════════════════════════");
      console.log("ORDER AUDIT — today =", today);
      console.log("══════════════════════════════════════════════════════════════════");

      console.log("Total orders in Firebase:", orders.length);
      console.log("Created today (createdAt):", onTodayCreated.length);
      console.log("Touched today (any timestamp):", onTodayTouched.length);

      // Status distribution across ALL orders + today only
      const byStatusAll = {};
      const byStatusToday = {};
      orders.forEach(o => {
        const s = o.status === undefined ? "(undefined)" : (o.status || "(empty)");
        byStatusAll[s] = (byStatusAll[s] || 0) + 1;
      });
      onTodayCreated.forEach(o => {
        const s = o.status === undefined ? "(undefined)" : (o.status || "(empty)");
        byStatusToday[s] = (byStatusToday[s] || 0) + 1;
      });
      console.log("Status distribution (all orders):", byStatusAll);
      console.log("Status distribution (today only):", byStatusToday);

      // Order number gaps — sneaker orders only (clothing "Shop Refill" ids are
      // R{n}-{i} on their own counter; digit-stripping them fakes gaps/dupes).
      const todayNums = onTodayCreated
        .filter(o => o.customerName !== "Shop Refill")
        .map(o => parseInt(String(o.id).replace(/[^0-9]/g, ""), 10))
        .filter(n => !isNaN(n));
      const minNum = todayNums.length ? Math.min(...todayNums) : null;
      const maxNum = todayNums.length ? Math.max(...todayNums) : null;
      const present = new Set(todayNums);
      const gaps = [];
      if (minNum !== null && maxNum !== null) {
        for (let i = minNum; i <= maxNum; i++) {
          if (!present.has(i)) gaps.push(i);
        }
      }
      console.log("Order number range today:", minNum, "→", maxNum, "(span:", maxNum - minNum + 1, ")");
      console.log("MISSING order numbers in range:", gaps.length, gaps);
      // Duplicates
      const dupCount = {};
      todayNums.forEach(n => dupCount[n] = (dupCount[n] || 0) + 1);
      const dups = Object.entries(dupCount).filter(([, c]) => c > 1);
      console.log("DUPLICATE order numbers today:", dups.length, dups);

      // Orders with no/empty/unknown status
      const ordersNoStatus = onTodayCreated.filter(o => !o.status || String(o.status).trim() === "");
      const ordersUnknownStatus = onTodayCreated.filter(o => o.status && !KNOWN.has(o.status));
      console.log("Orders today with NO status:", ordersNoStatus.length, ordersNoStatus.map(o => ({id:o.id, createdAt:o.createdAt, status:o.status})));
      console.log("Orders today with UNKNOWN/legacy status:", ordersUnknownStatus.length, ordersUnknownStatus.map(o => ({id:o.id, status:o.status, createdAt:o.createdAt})));

      // Soft-delete flags
      const softDeleted = onTodayCreated.filter(o => o.deleted === true || o.removed === true || o.archived === true);
      console.log("Orders flagged deleted/removed/archived:", softDeleted.length, softDeleted.map(o => ({id:o.id, deleted:o.deleted, removed:o.removed, archived:o.archived})));

      // Multi-timestamp anomalies
      const multiStamp = onTodayCreated.filter(o => {
        const stamps = [o.readyAt, o.outOfStockAt, o.comingTomorrowAt].filter(Boolean);
        return stamps.length > 1;
      });
      console.log("Orders with MULTIPLE status timestamps (changed mind):", multiStamp.length, multiStamp.map(o => ({id:o.id, status:o.status, readyAt:o.readyAt, outOfStockAt:o.outOfStockAt, comingTomorrowAt:o.comingTomorrowAt})));

      // Reconciliation math
      const ready     = onTodayCreated.filter(o => o.status === STATUS.READY).length;
      const collected = onTodayCreated.filter(o => o.status === STATUS.COLLECTED).length;
      const oos       = onTodayCreated.filter(o => o.status === STATUS.OUT_OF_STOCK).length;
      const tomorrow  = onTodayCreated.filter(o => o.status === STATUS.COMING_TOMORROW).length;
      const incoming  = onTodayCreated.filter(o => o.status === STATUS.INCOMING).length;
      const sum       = ready + collected + oos + tomorrow + incoming;
      const returnsToday = returnsLog.filter(r => (r.timestamp||"").slice(0,10) === today).length;
      console.log("══════════════════════════════════════════════════════════════════");
      console.log("RECONCILIATION (today, by status):");
      console.log("  READY            :", ready);
      console.log("  COLLECTED        :", collected);
      console.log("  OUT_OF_STOCK     :", oos);
      console.log("  COMING_TOMORROW  :", tomorrow);
      console.log("  INCOMING         :", incoming);
      console.log("  ─────────────────────");
      console.log("  Sum              :", sum);
      console.log("  Total today      :", onTodayCreated.length);
      console.log("  Diff (unaccounted):", onTodayCreated.length - sum);
      console.log("  Returns today    :", returnsToday);
      console.log("  Net Sales        : (ready+collected) − returns =", (ready + collected) - returnsToday);
      console.log("══════════════════════════════════════════════════════════════════");

      // Show every unaccounted-for order
      const accounted = new Set([STATUS.READY, STATUS.COLLECTED, STATUS.OUT_OF_STOCK, STATUS.COMING_TOMORROW, STATUS.INCOMING]);
      const unaccounted = onTodayCreated.filter(o => !accounted.has(o.status));
      if (unaccounted.length) {
        console.log("UNACCOUNTED-FOR ORDERS:", unaccounted.length);
        console.table(unaccounted.map(o => ({
          id: o.id,
          status: o.status === undefined ? "(undefined)" : (o.status || "(empty)"),
          createdAt: o.createdAt,
          updatedAt: o.updatedAt,
          readyAt: o.readyAt,
          collectedAt: o.collectedAt,
          outOfStockAt: o.outOfStockAt,
          comingTomorrowAt: o.comingTomorrowAt,
          deleted: o.deleted,
          customerName: o.customerName,
          productName: o.productName,
        })));
      }
      console.log("Tip: full data available as window.__orderAudit.data");
      window.__orderAudit.data = { today, orders, onTodayCreated, byStatusAll, byStatusToday, gaps, dups, ordersNoStatus, ordersUnknownStatus, softDeleted, multiStamp, unaccounted, returnsToday };
    };

    // Auto-run silent reconciliation on every render — only logs if numbers don't add up
    if (onTodayCreated.length > 0) {
      const ready     = onTodayCreated.filter(o => o.status === STATUS.READY).length;
      const collected = onTodayCreated.filter(o => o.status === STATUS.COLLECTED).length;
      const oos       = onTodayCreated.filter(o => o.status === STATUS.OUT_OF_STOCK).length;
      const tomorrow  = onTodayCreated.filter(o => o.status === STATUS.COMING_TOMORROW).length;
      const incoming  = onTodayCreated.filter(o => o.status === STATUS.INCOMING).length;
      const sum = ready + collected + oos + tomorrow + incoming;
      if (sum !== onTodayCreated.length) {
        console.warn("🚨 ORDER COUNT MISMATCH — run window.__orderAudit() for details", {
          total: onTodayCreated.length,
          sum,
          diff: onTodayCreated.length - sum,
        });
      }
    }
  }, [orders, returnsLog]);
  // ── END ORDER AUDIT ────────────────────────────────────────────────────────

  // ── Global edge-swipe-back gesture ──────────────────────────────────────────
  // Swipe right starting within 30px of the left edge → go back to role selector.
  // Attached at document level so it covers every view without modifying each one.
  const edgeSwipeStartX = useRef(null);
  useEffect(() => {
    if (!role) return; // only active when a view is showing

    const onTouchStart = (e) => {
      const x = e.touches[0].clientX;
      edgeSwipeStartX.current = x <= 30 ? x : null;
    };

    const onTouchEnd = (e) => {
      if (edgeSwipeStartX.current === null) return;
      const dx = e.changedTouches[0].clientX - edgeSwipeStartX.current;
      edgeSwipeStartX.current = null;
      if (dx > 80) {
        // Clear Insights/Customers auth so the password is required next time
        if (role === ROLES.INSIGHTS)     sessionStorage.removeItem(INSIGHTS_SESSION_KEY);
        if (role === ROLES.CUSTOMERS_DB) sessionStorage.removeItem(CUSTOMERS_SESSION_KEY);
        setRole(null);
      }
    };

    document.addEventListener("touchstart", onTouchStart, { passive: true });
    document.addEventListener("touchend",   onTouchEnd,   { passive: true });
    return () => {
      document.removeEventListener("touchstart", onTouchStart);
      document.removeEventListener("touchend",   onTouchEnd);
    };
  }, [role]);
  // ────────────────────────────────────────────────────────────────────────────

  // ── ALL CONDITIONAL RETURNS AFTER ALL HOOKS ─────────────────────────────────
  // (Privacy page handled by the outer App wrapper before AuthGate mounts.)

  // Helper: enforce permission on each role-keyed view. If user lacks the
  // permission (e.g. via direct hash navigation that bypassed the tile list),
  // render nothing so the role-reset effect above can drop them to the
  // selector. The UI alone is bypassable; server-side Rules (Phase 2) are
  // the real enforcement.
  const guard = (roleKey, node) => hasPermission(ROLE_TO_PERMISSION[roleKey]) ? node : null;

  let view = null;
  if (wantUserMgmt) {
    // UserManagement handles its own super-admin gate + renders NotAuthorized
    // for non-super-admin viewers. Hash-routed sub-paths (e.g. /#admin/users/<uid>)
    // are parsed inside the component, so we just mount it and let it handle the rest.
    view = <UserManagement authUser={authUser} onExit={() => (window.location.hash = "")} />;
  } else if (wantAdmin && !isSuperAdmin) {
    view = <AdminSignInScreen onCancel={() => (window.location.hash = "")} />;
  } else if (!role) {
    view = <RoleSelector onSelect={setRole} orders={orders} returnsLog={returnsLog} hasPermission={hasPermission} canAccessStock={canAccessStock} isSuperAdmin={isSuperAdmin} />;
  } else if (role === ROLES.INSIGHTS)     view = guard(ROLES.INSIGHTS,     <InsightsView   onExit={() => setRole(null)} />);
  else if (role === ROLES.SOURCE)         view = guard(ROLES.SOURCE,       <SourceView     orders={orders} returnsLog={returnsLog} products={products} onExit={() => setRole(null)} />);
  else if (role === ROLES.RETURNS)        view = guard(ROLES.RETURNS,      <ReturnsView    orders={orders} products={products} onExit={() => setRole(null)} />);
  else if (role === ROLES.CUSTOMERS_DB)   view = guard(ROLES.CUSTOMERS_DB, <CustomersView  onExit={() => setRole(null)} />);
  else if (role === ROLES.DISPLAY) {
    // TV mode is chrome-free, but a hidden top-right DOUBLE-tap exits back to
    // the view picker (TvDisplayMockup renders the invisible zone from onExit).
    view = guard(ROLES.DISPLAY, <TvWithAutoCollect orders={orders} onExit={() => setRole(null)} />);
  }
  else if (role === ROLES.ADMIN)     view = guard(ROLES.ADMIN,            <AdminView     products={products} orders={orders} onExit={() => setRole(null)} />);
  // AI Studio is route-guarded on the REAL isSuperAdmin flag (verified email),
  // not a grantable permission string — a non-super-admin who lands here via a
  // persisted role or manual state gets null and drops back to the selector.
  else if (role === ROLES.AI_STUDIO) view = isSuperAdmin ? <AiStudioView products={products} onExit={() => setRole(null)} /> : null;
  // Display Checks — route-guarded on the module gate (master flag + super-admin
  // or store-scoped grant); a viewer who no longer qualifies gets null and the
  // reset effect drops them home. Shell only — reads no data.
  else if (role === ROLES.DISPLAY_CHECKS) view = displayChecksRouteOpen ? <DisplayChecks onExit={() => setRole(null)} products={products} /> : null;
  else if (role === ROLES.STOCK)     view = canAccessStock ? <StockView products={products} onExit={() => setRole(null)} /> : null;
  else if (role === ROLES.HEALTH)    view = canAccessStock ? <HealthView products={products} onExit={() => setRole(null)} /> : null;
  else if (role === ROLES.DISPLAY_REGISTER) view = <DisplayRegister products={products} onExit={() => setRole(null)} standalone />;
  else if (role === ROLES.BARCODES)  view = <BarcodeCatalog products={products} canMint={canMint} onExit={() => setRole(null)} />;
  else if (role === ROLES.LABEL_PRINT) view = <LabelPrintView products={products} onExit={() => setRole(null)} />;
  else if (role === ROLES.ASSISTANT) view = guard(ROLES.ASSISTANT,        <AssistantView products={products} orders={orders} onExit={() => setRole(null)} />);
  else if (role === ROLES.WAREHOUSE) view = guard(ROLES.WAREHOUSE,        <WarehouseView products={products} orders={orders} onExit={() => setRole(null)} />);
  else if (role === ROLES.CUSTOMER)  view = guard(ROLES.CUSTOMER,         <CustomerView  orders={orders} onExit={() => setRole(null)} />);
  else if (role === ROLES.BROADCAST_GROUPS) view = guard(ROLES.BROADCAST_GROUPS, <BroadcastGroupsView authUser={authUser} onExit={() => setRole(null)} />);

  // The user-indicator pill shows for any signed-in real user (PIN account
  // OR super-admin). Suppressed on the TV display so it's truly chrome-free.
  const indicatorLabel = isSuperAdmin
    ? (authUser?.email?.split("@")[0] || "Admin")
    : (permRecord?.displayName || permRecord?.username || authUser?.email?.split("@")[0] || "Staff");
  // On desktop, the redesigned workspaces (home dashboard, Assistant, Barcode
  // Studio) carry their own top-bar / Home nav, so the global pill is suppressed
  // there to avoid a stray floating sign-out.
  const showIndicator = authUser && !authUser.isAnonymous && role !== ROLES.DISPLAY
    && !(!isNarrowApp && (role === ROLES.ASSISTANT || role === ROLES.BARCODES || role === ROLES.STOCK || role === ROLES.INSIGHTS || role === ROLES.WAREHOUSE || role === ROLES.LABEL_PRINT || role === ROLES.CUSTOMER || role === ROLES.CUSTOMERS_DB || role === ROLES.DISPLAY_CHECKS || role === null))
    && !(!isNarrowApp && wantUserMgmt);   // desktop User Management carries its own rail Exit

  // "This device's clock is wrong" — gated on ROLE, not on tree position. Being a
  // child of AuthGate is NOT enough to mean staff-only: ROLES.DISPLAY renders the
  // SAME TvWithAutoCollect the #tv shell does, right here inside AppInner, so a
  // tree-placed banner would paint across the customer queue board. Mirrors the
  // showIndicator rule above — DISPLAY is customer-facing and carries no staff
  // chrome. Sibling of the boundary, so a crash in `view` still leaves it up.
  const showClockWarning = role !== ROLES.DISPLAY;

  return (
    <>
      <PWAUpdateBanner />
      {showClockWarning && <ClockWarningBanner />}
      {!role && <AndroidInstallChip />}
      {!role && <IOSInstallTooltip />}
      <AppErrorBoundary key={role || "home"}>{view}</AppErrorBoundary>
      {showIndicator && <UserIndicator label={indicatorLabel} onSignOut={handleAdminSignOut} />}
    </>
  );
}

// ─── TV DISPLAY-TIDY WRAPPER ──────────────────────────────────────────────────
// Side-effects layer around <TvDisplayMockup>. This is now DISPLAY-ONLY — it
// never writes order state to RTDB. Collection is confirmed solely by a real POS
// sale (marathon-pos-app sell-by-order-number), so an order stays live in /orders
// until it's actually sold. Watches the live orders list purely to tidy the board:
// • IN-STOCK READY → display-hidden after TV_EXPIRY_MS = 8 min (NO DB write; the
//   order stays READY/live so a still-browsing customer can pay later). This used
//   to auto-flip READY→COLLECTED, which retired orders mid-visit and broke the POS
//   lookup — removed.
// • OUT-OF-STOCK → display-hidden after TV_EXPIRY_MS (stays OOS as kept demand).
// • COMING_TOMORROW → display-hidden after TV_TOMORROW_HIDE_MS = 15 min.
// All three are display-only; Ref-Sets dedupe across multiple TV screens and prune
// entries on order removal. Manual warehouse "Collected" (changeStatus) is separate
// and unchanged — a deliberate human action still collects + logs restock.
const TV_TOMORROW_HIDE_MS = 15 * 60 * 1000;

// TV display form of a layby invoice number: strip the padding zeros so the board
// shows "L-45" instead of "L-00045" (the padded form is too wide for the number
// slot). Falls back to the raw value for any non-standard / migrated invoice shape.
function laybyTvNumber(invoiceNo) {
  const s = String(invoiceNo || "").trim();
  const m = s.match(/^([A-Za-z]+)[-\s]?0*(\d+)$/);
  return m ? `${m[1].toUpperCase()}-${m[2]}` : s;
}

// ─── PICKUP-BOARD VOICE (preloaded OpenAI clips, network-free playback) ────────
// The board speaks "Order number <digits>, <phrase>" when an order NEWLY becomes
// ready / out-of-stock / tomorrow. The store network is always slow, so we DO NOT
// fetch audio at announcement time (a live callable + clip download stalls and the
// order never gets read). Instead the TV preloads a tiny FIXED vocabulary of
// OpenAI-generated clips ONCE at startup — "Order number", the ten digit words,
// and the three phrase clips — decodes them into a single Web Audio context, and
// then assembles every announcement LOCALLY (gapless, works even if the network
// later drops). The old robotic browser speechSynthesis engine and the per-clip
// callable playback are gone; the voice is a single hardcoded OpenAI voice.
// One user tap unlocks audio (browser autoplay policy) and then vanishes.
const TV_VOICE_VOICE        = "nova"; // hardcoded OpenAI TTS voice for the board
const ANNOUNCE_REPEATS      = 2;      // say each announcement this many times
const ANNOUNCE_WORD_GAP_S   = 0.05;   // silence between words inside one announcement
const ANNOUNCE_REPEAT_GAP_S = 0.45;   // silence between repeats / back-to-back orders
const ANNOUNCE_MAX_AGE_MS   = 5 * 60 * 1000; // only read out a transition this recent — a late vocab load must not recite long-since-ready orders (margin also tolerates modest warehouse↔TV clock skew)
// Fixed vocabulary: token → the exact text each preloaded clip says. Digit-by-digit
// number reading keeps the whole set to ~15 tiny clips (vs a clip per 1–999 number).
// The pickupVoice callable's `vocab` mode generates + caches exactly these.
const VOICE_VOCAB = {
  order_number: "Order number",
  d0: "zero", d1: "one", d2: "two",   d3: "three", d4: "four",
  d5: "five", d6: "six", d7: "seven", d8: "eight", d9: "nine",
  ready:    "ready for collection",
  oos:      "out of stock",
  tomorrow: "scheduled for tomorrow",
  enabled:  "Pickup announcements on",
};

function TvWithAutoCollect({ orders: ordersRaw, onExit }) {
  // The customer pickup board shows REAL customer orders only. "Shop Refill"
  // rows are internal clothing-refill (CR) requests that live in the SAME
  // /orders node — the warehouse Order Queue already excludes them (see the
  // hubOrders filter), but the TV historically merged everything, so fulfilled
  // refills leaked onto the customer board as stuck "Incoming" (their base
  // status stays "incoming"; the CR flow resolves via clothingRefillStatus).
  // Drop them here so they never reach the board, the announcer, or the timers.
  // Steady clock so the Hub 2 dispatch hold reveals on time (a held order flips
  // INCOMING → READY purely with the passage of time, not a data change).
  const [revealClock, setRevealClock] = useState(() => serverNowMs());
  useEffect(() => {
    const id = setInterval(() => setRevealClock(serverNowMs()), 10 * 1000);
    return () => clearInterval(id);
  }, []);
  const orders = useMemo(
    () => (ordersRaw || [])
      .filter(o => o && o.customerName !== "Shop Refill")
      .map(o => holdHub2Ready(o, revealClock)),      // hold Hub 2 "Ready" until its reveal instant
    [ordersRaw, revealClock]
  );
  // Dedupe markers are keyed by a composite of order.id + createdAt rather
  // than id alone. order.id is daily-scoped (it's the orderNumber, which
  // resets each day — see project memory project_order_number_daily_reset),
  // so without the createdAt suffix yesterday's "001" marker would silently
  // carry over to today's brand-new "001" and either auto-collect it the
  // instant it appears or hide it forever from COMING_TOMORROW.
  const orderKey = (o) => `${o.id}:${o.createdAt || ""}`;
  const hiddenReadyRef    = useRef(new Set());  // READY rows hidden from the TV after 8 min (display-only — NO collect)
  const hiddenOosRef      = useRef(new Set());  // OOS hidden from the TV (display-only)
  const hiddenTomorrowRef = useRef(new Set());
  const [tick, setTick]   = useState(0);

  // ── VOICE PICKUP ANNOUNCEMENTS (preloaded OpenAI clips) ──────────────────────
  // Speak "Order number <digits>, <phrase>" when an order NEWLY becomes ready /
  // out-of-stock / tomorrow. The fixed vocabulary (VOICE_VOCAB) is fetched + decoded
  // ONCE at mount into a single Web Audio context, then every announcement is
  // assembled from those buffers and scheduled LOCALLY — no per-order network, so it
  // survives the store's slow link. TV device ONLY. Orders already terminal at load
  // are SEEDED (never read out). One tap unlocks audio, then the control disappears.
  const [voiceUnlocked, setVoiceUnlocked] = useState(false); // browsers block audio until one user gesture per page load
  const [vocabReady, setVocabReady] = useState(false); // true once the clip vocabulary is decoded — STATE (not just the ref) so a late load re-fires the announce effect and catches orders that went ready during the load window
  const announcedRef = useRef(null); // Set of announced order keys; null until seeded with the load-time backlog
  const audioCtxRef  = useRef(null); // shared AudioContext (created on mount for decode; resumed on the unlock tap)
  const bufsRef      = useRef(null); // Map token → decoded AudioBuffer; null until the vocabulary finishes loading
  const chainEndRef  = useRef(0);    // AudioContext time cursor so queued clips schedule back-to-back, never overlap
  const MAX_QUEUE_AHEAD_S = 25;      // never schedule more than this far past now — a batch of ready orders must not become a minutes-long recital (there is no mute)

  // Preload the vocabulary once: pull each clip's URL from the pickupVoice callable
  // (`vocab` mode generates + caches them server-side), fetch the bytes, and decode
  // into AudioBuffers. Retries a few times because startup may hit the slow network —
  // unlike a live announcement, startup has time to wait. No user gesture needed to
  // decode; only playback later requires the unlock tap.
  useEffect(() => {
    let cancelled = false;
    let retryTimer = null;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;                                  // no Web Audio → board runs silent (no crash)
    const ctx = audioCtxRef.current || (audioCtxRef.current = new Ctx());
    const TOKENS = Object.keys(VOICE_VOCAB);
    const decoded = new Map();                         // persists ACROSS retries — a flaky link only re-fetches the clips still missing, never the whole set again
    const load = async (attempt = 0) => {
      try {
        const res = await httpsCallable(functions, "pickupVoice")({ vocab: true, voice: TV_VOICE_VOICE });
        const urls = res?.data?.urls || {};
        await Promise.all(TOKENS.map(async (tok) => {
          if (decoded.has(tok)) return;                // already have this clip from a prior attempt
          const url = urls[tok];
          if (!url) return;
          const r = await fetch(url);
          if (!r.ok) throw new Error(`clip ${tok} http ${r.status}`); // don't hand an error body to decodeAudioData
          const ab = await r.arrayBuffer();
          const buf = await ctx.decodeAudioData(ab.slice(0));
          if (buf) decoded.set(tok, buf);              // legacy callback-style decode returns undefined — skip, don't store a dud
        }));
        if (cancelled) return;
        // Require the FULL vocabulary — a partial set would drop digits mid-number.
        if (decoded.size === TOKENS.length) {
          bufsRef.current = decoded;
          setVocabReady(true);                         // re-fires the announce effect → orders that went ready mid-load still get read
          return;
        }
        throw new Error(`vocab incomplete (${decoded.size}/${TOKENS.length})`);
      } catch (e) {
        if (cancelled) return;
        // Never give up permanently (the point is surviving a flaky link), but widen
        // the interval sharply once it's clearly a persistent failure (corrupt clip,
        // unsupported decoder) so a doomed load can't hammer the callable forever.
        const delay = attempt < 20 ? Math.min(120000, 4000 * (attempt + 1)) : 20 * 60000;
        retryTimer = setTimeout(() => load(attempt + 1), delay);
      }
    };
    load();
    return () => {
      cancelled = true;
      if (retryTimer) clearTimeout(retryTimer);
      // Close the context on unmount so scheduled clips stop (no ghost audio over the
      // admin UI after exit) and we don't leak toward Chrome's ~6-context ceiling.
      // close() REJECTS if already closed — swallow it (an unhandled rejection trips
      // the app's fatal error banner).
      try { const p = audioCtxRef.current?.close?.(); if (p && p.catch) p.catch(() => {}); } catch { /* ignore */ }
      audioCtxRef.current = null;
    };
  }, []);

  // Schedule a list of vocabulary tokens to play gaplessly, one after another, after
  // anything already queued (chainEndRef). Silently no-ops until the buffers are
  // loaded and audio is unlocked, so a call before either is harmless.
  const playTokens = (tokens) => {
    const ctx = audioCtxRef.current, bufs = bufsRef.current;
    if (!ctx || !bufs || !voiceUnlocked) return;
    let t = Math.max(ctx.currentTime + 0.02, chainEndRef.current);
    for (const tok of tokens) {
      const buf = bufs.get(tok);
      if (!buf) continue;
      const src = ctx.createBufferSource();
      src.buffer = buf;
      src.connect(ctx.destination);
      src.start(t);
      t += buf.duration + ANNOUNCE_WORD_GAP_S;
    }
    chainEndRef.current = t;
  };

  const enableVoice = () => {
    // One user gesture unlocks Web Audio playback for the page load. Resume the
    // context, mark unlocked (which hides the button), and play a short confirmation.
    try { audioCtxRef.current?.resume?.(); } catch { /* ignore */ }
    setVoiceUnlocked(true);
    // voiceUnlocked flips async, so schedule the confirmation directly rather than
    // via playTokens (which reads the not-yet-updated state).
    const ctx = audioCtxRef.current, bufs = bufsRef.current;
    if (ctx && bufs?.get("enabled")) {
      try {
        const src = ctx.createBufferSource();
        src.buffer = bufs.get("enabled");
        src.connect(ctx.destination);
        src.start(ctx.currentTime + 0.05);
        chainEndRef.current = ctx.currentTime + 0.05 + bufs.get("enabled").duration;
      } catch { /* ignore */ }
    }
  };

  // Status → phrase-clip token. Keyed by orderKey:status so each TRANSITION is
  // announced once (e.g. Out-of-stock → Ready later gets both). The board's other
  // column (Incoming) is intentionally not announced.
  const ANNOUNCE_PHRASE = {
    [STATUS.READY]:           "ready",
    [STATUS.OUT_OF_STOCK]:    "oos",
    [STATUS.COMING_TOMORROW]: "tomorrow",
  };
  const announceKey = (o) => `${orderKey(o)}:${o.status}`;

  // Detect newly-announceable status transitions → announce once each.
  useEffect(() => {
    if (announcedRef.current === null) {
      if (!orders || orders.length === 0) return;                          // wait for the first populated load
      announcedRef.current = new Set(orders.filter(o => ANNOUNCE_PHRASE[o.status]).map(announceKey)); // seed backlog, don't read out
      return;
    }
    const seen = announcedRef.current;
    const liveKeys = new Set((orders || []).map(orderKey));
    for (const k of seen) if (!liveKeys.has(k.slice(0, k.lastIndexOf(":")))) seen.delete(k); // prune vanished orders
    for (const o of (orders || [])) {
      const phraseTok = ANNOUNCE_PHRASE[o.status];
      if (!phraseTok) continue;
      const k = announceKey(o);
      if (seen.has(k)) continue;
      // Unlocked but the vocabulary hasn't loaded yet → do NOT mark seen; leave the
      // order so this effect re-fires when vocabReady flips and reads it then. Without
      // this, an order that goes ready during the (slow-network) load window is marked
      // done and silently lost forever — the exact failure this feature exists to fix.
      if (voiceUnlocked && !vocabReady) continue;
      seen.add(k);                                                          // mark announced even when locked so unlocking later won't dump a backlog
      if (!voiceUnlocked) continue;
      // Freshness guard: only announce a RECENT transition. After a long vocab-load
      // outage (retry-forever) the catch-up would otherwise recite orders that went
      // ready many minutes ago — already collected or hidden from the board. Marked
      // seen above, so a stale one is skipped for good, not re-evaluated.
      // Key the timestamp to the status being ANNOUNCED — updateStatus stamps only the
      // new status and never clears the old ones, so a fixed readyAt||oosAt||… chain
      // would read a stale earlier stamp on a corrective 2nd transition (Ready→OOS)
      // and wrongly drop it. Only these 3 statuses reach here (ANNOUNCE_PHRASE gate).
      const ts = (o.status === STATUS.READY ? o.readyAt
                : o.status === STATUS.OUT_OF_STOCK ? o.outOfStockAt
                : o.comingTomorrowAt) || o.updatedAt;
      if (!ts || serverNowMs() - new Date(ts).getTime() > ANNOUNCE_MAX_AGE_MS) continue;
      const ctx = audioCtxRef.current;
      // Backlog cap: if clips are already queued far past now (a batch of orders just
      // went ready), skip rather than pile on — there's no mute, so an unbounded queue
      // would become a multi-minute recital. Skipped orders are already on-screen.
      if (ctx && chainEndRef.current - ctx.currentTime > MAX_QUEUE_AHEAD_S) continue;
      // Read the order number digit-by-digit from the preloaded clips (leading zeros
      // dropped, but a bare "0" kept). Customer order ids are numeric; a non-numeric
      // id (shouldn't reach here — laybys aren't announced) is skipped, not misread.
      const num = String(o.id ?? "").replace(/^0+(?=\d)/, "");
      const digits = num.split("").filter(c => /[0-9]/.test(c)).map(d => "d" + d);
      if (!digits.length) continue;
      const seq = ["order_number", ...digits, phraseTok];
      for (let i = 0; i < ANNOUNCE_REPEATS; i++) {                          // repeat so it's not missed
        if (ctx) chainEndRef.current = Math.max(chainEndRef.current, ctx.currentTime) + ANNOUNCE_REPEAT_GAP_S;
        playTokens(seq);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orders, voiceUnlocked, vocabReady]);
  // Layby collections tracked on the customer board exactly like orders: when the
  // cashier sends a pull request the invoice number appears in INCOMING; once the
  // warehouse marks it Sent it moves to READY and hides on the SAME 8-min timer as
  // orders. Only "collect" pulls (return_to_stock are internal cancellations).
  const laybyPulls = useLaybyPulls();
  const laybyOrders = useMemo(() => (laybyPulls || [])
    .filter(p => p && p.invoiceNo && dispositionOf(p) !== DISPOSITION.RETURN_TO_STOCK)
    .map(p => {
      const st = p.status || PULL_STATUS.PENDING;
      const num = laybyTvNumber(p.invoiceNo);
      if (st === PULL_STATUS.PENDING) {
        return { id: num, status: STATUS.INCOMING, isLayby: true,
                 createdAt: p.requestedAt || p.createdAt || p.updatedAt || "" };
      }
      if (st === PULL_STATUS.SENT) {
        return { id: num, status: STATUS.READY, isLayby: true,
                 readyAt: p.sentAt, updatedAt: p.sentAt, createdAt: p.sentAt || p.requestedAt || "" };
      }
      return null; // rejected / returnedToStock → not shown on the board
    })
    .filter(Boolean), [laybyPulls]);
  const allOrders = useMemo(() => [...(orders || []), ...laybyOrders], [orders, laybyOrders]);

  // ── TV AUTO-UPDATE ──────────────────────────────────────────────────────────
  // A kiosk TV is never manually reloaded, so a deploy otherwise never reaches it
  // (the page keeps running the in-memory bundle it loaded hours ago — which is
  // exactly how stale "auto-collect" code lingered after we shipped the fix).
  // index.html is served no-cache, so poll it and reload when the built asset hash
  // changes. SCOPED TO THE TV ONLY — no in-progress staff action to disrupt, and a
  // reload re-applies the 8-min hide instantly (it's keyed off the persisted
  // readyAt age). No reload loop: after reload the document's bundle == deployed.
  useEffect(() => {
    const runningBundle =
      document.querySelector('script[type="module"][src*="assets/index-"]')
        ?.getAttribute("src")?.match(/index-[A-Za-z0-9_-]+\.js/)?.[0] || "";
    if (!runningBundle) return; // can't tell what we're running → never force-reload
    let stopped = false;
    const check = async () => {
      if (stopped) return;
      try {
        const html = await fetch("/", { cache: "no-store" }).then((r) => r.text());
        const deployed = html.match(/assets\/(index-[A-Za-z0-9_-]+\.js)/)?.[1] || "";
        if (deployed && deployed !== runningBundle) {
          console.warn("TV: new build deployed — reloading", { runningBundle, deployed });
          window.location.reload();
        }
      } catch { /* offline / transient — retry next tick */ }
    };
    check();                                        // check IMMEDIATELY on load (don't wait a full interval)
    const id = setInterval(check, 60 * 1000);       // then every 60s
    // Also check when the TV tab regains focus/visibility (background tabs throttle
    // the timer, so a kiosk that was asleep still catches up on wake).
    const onVisible = () => { if (document.visibilityState === "visible") check(); };
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("focus", check);
    return () => {
      stopped = true;
      clearInterval(id);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("focus", check);
    };
  }, []);

  useEffect(() => {
    const check = () => {
      const nowMs    = serverNowMs();
      const liveKeys = new Set(allOrders.map(orderKey));
      for (const k of hiddenReadyRef.current)    if (!liveKeys.has(k)) hiddenReadyRef.current.delete(k);
      for (const k of hiddenOosRef.current)      if (!liveKeys.has(k)) hiddenOosRef.current.delete(k);
      for (const k of hiddenTomorrowRef.current) if (!liveKeys.has(k)) hiddenTomorrowRef.current.delete(k);

      let changed = false;
      allOrders.forEach(o => {
        const key = orderKey(o);
        // IN-STOCK READY → DISPLAY-ONLY hide after 8 min (NO RTDB write). The
        // order stays READY/live in /orders so a customer who's still in-store can
        // pay later: it is now ONLY a real POS sale that marks an order collected
        // (marathon-pos-app sell-by-order-number). This used to auto-flip
        // READY→COLLECTED on the timer, which retired the order while the customer
        // was still browsing — they'd then fail the POS lookup ("no live order").
        // The timer now just tidies the board; collection = a confirmed sale.
        if (o.status === STATUS.READY && !hiddenReadyRef.current.has(key)) {
          const ts = o.readyAt || o.updatedAt;
          if (ts && nowMs - new Date(ts).getTime() >= TV_EXPIRY_MS) {
            hiddenReadyRef.current.add(key);
            changed = true;
          }
        }
        // OUT-OF-STOCK → display-only hide from the customer TV after 8 min (NO RTDB
        // write; the order stays OOS in /orders as unfulfilled-demand data).
        if (o.status === STATUS.OUT_OF_STOCK && !hiddenOosRef.current.has(key)) {
          const ts = o.outOfStockAt || o.updatedAt;
          if (ts && nowMs - new Date(ts).getTime() >= TV_EXPIRY_MS) {
            hiddenOosRef.current.add(key);
            changed = true;
          }
        }
        // Hide COMING_TOMORROW after 15 min (display-only)
        if (o.status === STATUS.COMING_TOMORROW && !hiddenTomorrowRef.current.has(key)) {
          const ts = o.comingTomorrowAt || o.updatedAt;
          if (ts && nowMs - new Date(ts).getTime() >= TV_TOMORROW_HIDE_MS) {
            hiddenTomorrowRef.current.add(key);
            changed = true;
          }
        }
      });
      if (changed) setTick(n => n + 1);
    };
    check();
    const id = setInterval(check, TV_EXPIRY_CHECK_MS);
    return () => clearInterval(id);
  }, [allOrders]);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const filteredOrders = useMemo(
    () => allOrders.filter(o =>
      (o.status !== STATUS.COMING_TOMORROW || !hiddenTomorrowRef.current.has(orderKey(o))) &&
      (o.status !== STATUS.OUT_OF_STOCK    || !hiddenOosRef.current.has(orderKey(o))) &&
      (o.status !== STATUS.READY           || !hiddenReadyRef.current.has(orderKey(o)))
    ),
    [allOrders, tick]
  );

  return (
    <>
      <TvDisplayMockup orders={filteredOrders} onExit={onExit} />
      {/* Audio-unlock tap ONLY (browsers block audio until one user gesture per page
          load). Shows until tapped once, then disappears entirely — there is no
          persistent mute toggle. After the tap, announcements play from the preloaded
          clips with no further UI. Reappears only when the kiosk page reloads. */}
      {!voiceUnlocked && (
        <button
          type="button"
          onClick={enableVoice}
          aria-label="Enable pickup announcements"
          style={{
            position: "fixed", left: "50%", bottom: 22, transform: "translateX(-50%)", zIndex: 400,
            display: "flex", alignItems: "center", gap: 9,
            background: "rgba(74,127,255,.94)", color: "#fff", border: "none", borderRadius: 999,
            padding: "13px 24px", fontSize: 15, fontWeight: 800, letterSpacing: 0.3, cursor: "pointer",
            fontFamily: FONT, boxShadow: "0 8px 28px rgba(0,0,0,.55)",
          }}
        >
          🔊 Tap once to enable pickup voice
        </button>
      )}
    </>
  );
}

// ─── TV ONLY SHELL ────────────────────────────────────────────────────────────
// Mounted by AuthGate when hash === "#tv". Pulls orders via the anonymous
// auth that AuthGate kicks off; renders the bare TV display with no admin
// chrome, no role selector, no login screen.
function TvOnlyShell() {
  const orders = useOrders();
  // Hidden top-right double-tap leaves the #tv kiosk URL → back to the normal app.
  return <TvWithAutoCollect orders={orders} onExit={() => { window.location.hash = ""; }} />;
}

// ─── MAIN APP ─────────────────────────────────────────────────────────────────
// Default export wraps AppInner in AuthGate. The renderTv callback returns
// the TV-only shell so it never mounts on non-TV routes. Privacy page is
// the only path that bypasses both AuthGate and the rest of the shell.
export default function App() {
  if (typeof window !== "undefined" && window.location.pathname === "/privacy") {
    return <PrivacyPage />;
  }
  return (
    <>
      {/* Deploy pickup for long-lived warehouse/TV tabs — banner + idle
          auto-reload (src/update/updateChecker.js). Outside AuthGate so the
          TV shell (which never navigates or re-auths) updates itself too. */}
      <UpdateBanner />
      <AuthGate renderTv={() => <TvOnlyShell />}>
        <AppErrorBoundary>
          <AppInner />
        </AppErrorBoundary>
      </AuthGate>
    </>
  );
}
